use telnet::{Telnet, TelnetOption, Action, TelnetError};

fn negotiate_compression(telnet: &mut Telnet) -> Result<(), TelnetError> {
    // Check if MCCP2 is supported by the server
    telnet.option(TelnetOption::MCCP2, Action::Synchronize)?;

    // Wait for the server's response to the Synchronize request
    telnet.wait_for_option(TelnetOption::MCCP2, Action::Subnegotiation)?;

    // If the server supports MCCP2, initiate compression negotiation
    telnet.option(TelnetOption::MCCP2, Action::Subnegotiation)?;

    Ok(())
}

use yansi_term::{Colour, Style};

fn color_gradient(start: (u8, u8, u8), end: (u8, u8, u8), width: u32) {
    for i in 0..width {
        let fraction = i as f32 / (width - 1) as f32;
        let r = start.0 as f32 + (end.0 as f32 - start.0 as f32) * fraction;
        let g = start.1 as f32 + (end.1 as f32 - start.1 as f32) * fraction;
        let b = start.2 as f32 + (end.2 as f32 - start.2 as f32) * fraction;

        let r = r.round() as u8;
        let g = g.round() as u8;
        let b = b.round() as u8;

        let color = Colour::RGB(r, g, b);
        let style = Style::Bg(color);
        println!("{}", style.paint(" "));
    }
}

fn refresh_discovery_records<P>(behaviour: &mut Behaviour<P>, now: Instant, ttl: Duration)
where
    P: Provider,
{
    let mut peers = behaviour.peers.lock().unwrap();
    let mut updated_peers = VecDeque::new();

    for peer in peers.iter_mut() {
        if peer.last_seen + ttl > now {
            peer.last_seen = now;
            updated_peers.push_back(peer.clone());
        }
    }

    peers = updated_peers;
    behaviour.peers = peers;

    behaviour
        .swarm
        .emit_event(Event::Discovered(updated_peers));
}

use scrap::{Capturer, Display};

fn capture_frames(display: &Display, count: usize) -> Result<Vec<Vec<u8>>, std::io::Error> {
    let mut capturer = Capturer::new(display)?;
    let mut frames = Vec::new();

    for _ in 0..count {
        let frame = capturer.capture_frame()?;
        let buffer = frame.data.to_vec();
        frames.push(buffer);
    }

    Ok(frames)
}

