        ..Default::default()
    })
}

fn bidirectional_forward<A, B>(a: A, b: B) 
where 
    A: tokio::io::AsyncRead + tokio::io::AsyncWrite + Unpin + 'static, 
    B: tokio::io::AsyncRead + tokio::io::AsyncWrite + Unpin + 'static
{
    let (a_reader, a_writer) = split_io(a);
    let (b_reader, b_writer) = split_io(b);

    spawn(async move {
        let _ = copy(a_reader, b_writer).await;
    });

    spawn(async move {
        let _ = copy(b_reader, a_writer).await;
    });
}

