use filedescriptor::{FileDescriptor, poll, pollfd, Result, POLLIN, POLLOUT};
use std::time::Duration;

fn wait_ready(pairs: &[(FileDescriptor, i16)]) -> Result<usize> {
    let mut pfd = Vec::with_capacity(pairs.len());
    for (&fd, events) in pairs {
        let mut pfds = pollfd {
            fd: fd as i32,
            events: events as u16,
            revents: 0,
        };
        pfd.push(pfds);
    }

    let timeout = Duration::from_secs(2);
    let res = poll(&mut pfd, timeout.as_millis() as i32)?;
    let ready_count = pfd.iter().filter(|p| p.revents != 0).count();
    Ok(ready_count)
}

fn proxy_for_domains(domains: &[&str], proxy_uri: Uri) -> Result<ProxyConnector<HttpConnector>, io::Error> {
    let http_connector = HttpConnector::new();
    let intercept = move |uri: &Uri| -> Result<Intercept, io::Error> {
        let host = uri.host().ok_or(io::Error::new(io::ErrorKind::InvalidInput, "missing host"))?;
        let host_str = host.to_string();
        if domains.iter().any(|&d| d == host) {
            Ok(Intercept::Proxy(proxy_uri.clone()))
        } else {
            Ok(Intercept::Direct)
        }
    };
    Ok(ProxyConnector::new(http_connector, intercept))
}

use todo_txt::task::Simple;
