fn count_overdue_tasks_by_project(tasks: &[Simple]) -> HashMap<String, usize> {
    let mut overdue_counts = HashMap::new();
    let today = today();

    for task in tasks {
        if let Some(due_date) = task.due_date() {
            if due_date < today {
                *overdue_counts.entry(task.project().to_string()).or_insert(0) += 1;
            }
        }
    }

    overdue_counts
}

use logging_timer::{stime, executing, finish};

fn fetch_with_progress(url: &str, max_retries: u32) -> Result<(), Box<dyn std::error::Error + Send + Sync>> {
    let start_time = stime();
    executing!("Fetch operation started");

    let mut retry_count = 0;
    let mut success = false;

    loop {
        let result = fetch(url);
        match result {
            Ok(_) => {
                success = true;
                break;
            }
            Err(e) => {
                retry_count += 1;
                if retry_count >= max_retries {
                    finish!("Fetch failed after {retry_count} retries");
                    return Err(e.into());
                }
                executing!("Fetch attempt {retry_count} failed, retrying...");
            }
        }
    }

    finish!("Fetch succeeded after {retry_count} attempts");
    Ok(())
}

