fn safe_realloc_aligned<T>(ptr: *mut T, new_len: usize, alignment: usize) -> *mut T {
    // Check for overflow in new_len
    if new_len > usize::MAX / mem::size_of::<T>() {
        panic!("Allocation size would overflow");
    }

    // Calculate the size needed for the new allocation
    let size = new_len * mem::size_of::<T>();

    // Check if alignment is a power of two
    if alignment == 0 || (alignment & (alignment - 1)) != 0 {
        panic!("Alignment must be a power of two");
    }

    // Perform the reallocation with alignment
    unsafe {
        let result = mi_realloc_aligned(ptr as *mut c_void, size as u64, alignment as u64);
        if result.is_null() {
            panic!("Failed to reallocate memory with alignment");
        }
        result as *mut T
    }
}

