use ansiterm::{Style, Colour};

fn format_log_message(timestamp: &str, level: &str, message: &str) -> String {
    let timestamp_style = Style::new().fg(Colour::Green);
    let level_style = match level {
        "ERROR" => Style::new().fg(Colour::Red),
        "WARN" => Style::new().fg(Colour::Yellow),
        "INFO" => Style::new().fg(Colour::Blue),
        "DEBUG" => Style::new().fg(Colour::Magenta),
        _ => Style::new().fg(Colour::White),
    };
    let message_style = Style::new().fg(Colour::White);

    format!(
        "{}{}{}{}",
        timestamp_style.apply_to(timestamp),
        level_style.apply_to(level),
        message_style.apply_to(message),
        Style::new().reset()
    )
}

fn validate_range<T>(range: &Range<DateTime<T>>) -> bool
where
    T: TimeZone,
{
    // Convert both bounds to UTC
    let lower_utc = range.lower().to_utc();
    let upper_utc = range.upper().to_utc();

    // Check if the lower bound does not exceed the upper bound
    lower_utc <= upper_utc
}

use miraland_metrics::datapoint::DataPoint;

fn aggregate_datapoints(points: &[DataPoint]) -> Vec<DataPoint> {
    let mut aggregated = std::collections::HashMap::new();

    for point in points {
        let name = point.name();
        let mut fields = point.fields();

        // If the name is already in the map, merge the fields
        if let Some(existing) = aggregated.get_mut(&name) {
            for (key, value) in fields {
                *existing.entry(key.to_string()).or_insert(0) += *value;
            }
        } else {
            // Otherwise, create a new entry
            let mut new_fields = std::collections::HashMap::new();
            for (key, value) in fields {
                new_fields.insert(key.to_string(), *value);
            }
            aggregated.insert(name.to_string(), new_fields);
        }
    }

    // Convert the aggregated map back to a Vec<DataPoint>
    aggregated.into_iter()
        .map(|(name, fields)| DataPoint::new(name, fields))
        .collect()
}

