pub struct CompositeVortexReadAt<P, S> {
    primary: P,
    secondary: S,
}

impl<P, S> CompositeVortexReadAt<P, S> {
    fn new(primary: P, secondary: S) -> Self {
        CompositeVortexReadAt { primary, secondary }
    }
}

impl<P, S> VortexReadAt for CompositeVortexReadAt<P, S>
where
    P: VortexReadAt + 'static,
    S: VortexReadAt + 'static,
{
    fn read_at(
        &self,
        buffer: &mut ByteBuffer,
        offset: u64,
        range: Range<u64>,
        _hint: PerformanceHint,
    ) -> io::Result<usize> {
        let mut total_read = 0;
        let mut remaining = range.end - range.start;

        let mut current_offset = offset;

        loop {
            if remaining == 0 {
                break;
            }

            let read_size = std::cmp::min(remaining, buffer.capacity() as u64) as usize;
            let mut buffer_slice = buffer.buffer_mut().slice_mut(0, read_size);

            match self.primary.read_at(
                &mut buffer_slice,
                current_offset,
                range.start..(range.start + read_size as u64),
                _hint,
            ) {
                Ok(bytes_read) => {
                    total_read += bytes_read;
                    remaining -= bytes_read as u64;
                    current_offset += bytes_read as u64;
                }
                Err(ref e) if e.kind() == io::ErrorKind::NotFound => {
                    // Primary source not found, fall back to secondary
                    let mut buffer_slice = buffer.buffer_mut().slice_mut(0, read_size);
                    match self.secondary.read_at(
                        &mut buffer_slice,
                        current_offset,
                        range.start..(range.start + read_size as u64),
                        _hint,
                    ) {
                        Ok(bytes_read) => {
                            total_read += bytes_read;
                            remaining -= bytes_read as u64;
                            current_offset += bytes_read as u64;
                        }
                        Err(e) => return Err(e),
                    }
                }
                Err(e) => return Err(e),
            }
        }

        Ok(total_read)
    }
}

