fn create_peg_out_with_rbf(
    config: &WalletConfig,
    recipient: Address,
    amount: Amount,
    estimated_weight: u64,
) -> Result<PegOut, anyhow::Error> {
    // Compute the fee rate based on the federation's fee consensus
    let fee_rate = config.federation.fee_consensus.fee_rate();

    // Calculate the required fee using the estimated weight
    let fee = fee_rate.compute_fee(estimated_weight);

    // Ensure the fee meets the minimum threshold
    if fee < config.federation.fee_consensus.min_fee() {
        return Err(anyhow!("Fee is below the minimum threshold"));
    }

    // Calculate the total amount to be sent, including the fee
    let total_amount = amount + fee;

    // Create the PegOutFees struct with computed fees
    let fees = PegOutFees {
        fee_rate,
        fee,
        total_amount,
    };

    // Create the PegOut struct with all necessary fields
    let peg_out = PegOut {
        recipient,
        amount,
        fees,
        // Assuming other fields are populated appropriately based on context
        // For example:
        // timestamp: Utc::now(),
        // transaction: None,
        // rbf_enabled: true,
    };

    Ok(peg_out)
}

fn create_bounding_box(points: &[graphene_point3d_t]) -> graphene_box_t {
    if points.is_empty() {
        return graphene_box_t {
            min: graphene_point3d_t { x: 0.0, y: 0.0, z: 0.0 },
            max: graphene_point3d_t { x: 0.0, y: 0.0, z: 0.0 },
        };
    }

    let mut min_x = points[0].x;
    let mut min_y = points[0].y;
    let mut min_z = points[0].z;

    let mut max_x = points[0].x;
    let mut max_y = points[0].y;
    let mut max_z = points[0].z;

    for &point in points {
        if point.x < min_x {
            min_x = point.x;
        }
        if point.y < min_y {
            min_y = point.y;
        }
        if point.z < min_z {
            min_z = point.z;
        }

        if point.x > max_x {
            max_x = point.x;
        }
        if point.y > max_y {
            max_y = point.y;
        }
        if point.z > max_z {
            max_z = point.z;
        }
    }

    graphene_box_t {
        min: graphene_point3d_t { x: min_x, y: min_y, z: min_z },
        max: graphene_point3d_t { x: max_x, y: max_y, z: max_z },
    }
}

