struct BatchUploadQueue {
    ctx: Context,
    paths: Vec<std::path::PathBuf>,
    allow_duplicate: bool,
    uploaded: std::collections::HashSet<String>,
}

impl BatchUploadQueue {
    fn new(ctx: Context, paths: Vec<std::path::PathBuf>, allow_duplicate: bool) -> Self {
        BatchUploadQueue {
            ctx,
            paths,
            allow_duplicate,
            uploaded: std::collections::HashSet::new(),
        }
    }

    fn process(&mut self) -> Result<()> {
        for path in &self.paths {
            let filename = path.file_name().and_then(|s| s.to_str()).unwrap_or("");
            if !self.allow_duplicate && self.uploaded.contains(filename) {
                println!("Skipping duplicate: {}", filename);
                continue;
            }

            let result = upload::upload(&self.ctx, path.clone());
            match result {
                Ok(_) => {
                    self.uploaded.insert(filename.to_string());
                    println!("Uploaded: {}", filename);
                }
                Err(e) => {
                    eprintln!("Failed to upload {}: {}", filename, e);
                }
            }
        }
        Ok(())
    }
}

fn test_status(test: &TestResult) -> (bool, Option<String>) {
    match test {
        TestResult::Passed => (true, None),
        TestResult::Failed(reason) => {
            if let Some(state) = &test.state {
                if state.is_reverted() {
                    (false, Some("Test failed due to revert code".to_string()))
                } else if state.is_unexpected() {
                    (false, Some("Test failed due to unexpected state".to_string()))
                } else {
                    (false, Some("Test failed for unknown reason".to_string()))
                }
            } else {
                (false, Some("Test failed but no state information available".to_string()))
            }
        }
    }
}

fn collect_variables(stmt: &Stmt, set: &mut std::collections::HashSet<Symbol>) {
    match stmt {
        Stmt::Assign(assign) => {
            for expr in &assign.values {
                collect_expressions(expr, set);
            }
        }
        Stmt::Expr(expr) => {
            collect_expressions(expr, set);
        }
        Stmt::If(if_stmt) => {
            collect_variables(&if_stmt.condition, set);
            collect_variables(&if_stmt.then_branch, set);
            if let Some(else_branch) = &if_stmt.else_branch {
                collect_variables(else_branch, set);
            }
        }
        Stmt::Loop(loop_stmt) => {
            if let Some(condition) = &loop_stmt.condition {
                collect_variables(condition, set);
            }
            collect_variables(&loop_stmt.body, set);
        }
        Stmt::Match(match_stmt) => {
            collect_variables(&match_stmt.expr, set);
            for arm in &match_stmt.arms {
                collect_variables(&arm.body, set);
            }
        }
        Stmt::Return(return_stmt) => {
            if let Some(expr) = &return_stmt.expr {
                collect_expressions(expr, set);
            }
        }
        Stmt::While(while_stmt) => {
            collect_variables(&while_stmt.condition, set);
            collect_variables(&while_stmt.body, set);
        }
        Stmt::Break(_) | Stmt::Continue(_) | Stmt::Discard(_) | Stmt::MacroCall(_) => {}
    }
}

fn collect_expressions(expr: &Expr, set: &mut std::collections::HashSet<Symbol>) {
    match expr {
        Expr::Ident(ident) => {
            set.insert(*ident);
        }
        Expr::Call(call) => {
            for arg in &call.args {
                collect_expressions(arg, set);
            }
        }
        Expr::Binary(binary) => {
            collect_expressions(&binary.left, set);
            collect_expressions(&binary.right, set);
        }
        Expr::Unary(unary) => {
            collect_expressions(&unary.expr, set);
        }
        Expr::Group(group) => {
            collect_expressions(group, set);
        }
        Expr::Lit(_) | Expr::Path(_) | Expr::Range(_) | Expr::Array(_) | Expr::Tuple(_) | Expr::Record(_) | Expr::Block(_) => {}
    }
}

fn check_all_mint_tokens_received(deps: Deps, sender: Addr, mint_tokens: Vec<MintToken>) -> Result<bool, ContractError> {
    for token in &mint_tokens {
        let amount = token.amount;
        let token_addr = token.token_addr;
        let received = RECEIVED_TOKENS.load(deps.storage, &sender, &token_addr).unwrap_or_default();
        if received < amount {
            return Err(ContractError::MintTokenNotReceived {
                token: token_addr.to_string(),
                required: amount,
                received,
            });
        }
    }
    Ok(true)
}

