fn after(&self, req: &mut dyn conduit::RequestExt, res: conduit_middleware::AfterResult) -> conduit_middleware::AfterResult {
    if let conduit_middleware::AfterResult::Response(res) = res {
        let etag = res.headers.get(header::ETAG).and_then(|s| s.to_str().ok()).and_then(|s| s.strip_prefix("\"").and_then(|s| s.strip_suffix("\"").map(String::from)));
        let if_none_match = req.headers.get(header::IF_NONE_MATCH).and_then(|s| s.to_str().ok()).and_then(|s| s.strip_prefix("\"").and_then(|s| s.strip_suffix("\"").map(String::from)));

        if let (Some(etag), Some(if_none_match)) = (etag, if_none_match) {
            if etag == if_none_match {
                return conduit_middleware::AfterResult::Response(Response::new(Body::empty(), StatusCode::NOT_MODIFIED));
            }
        }
    }

    res
}

use std::path::Path;
use vortex::file::VortexFile;
use vortex::error::VortexResult;
use vortex_layout::LayoutRef;
use std::collections::VecDeque;

fn total_row_count(vxf: &VortexFile) -> VortexResult<u64> {
    let root_layout = vxf.root_layout()?;
    let mut total_rows = 0;
    let mut queue = VecDeque::new();
    queue.push_back(root_layout);

    while let Some(layout) = queue.pop_front() {
        if let Some(row_count) = layout.row_count() {
            total_rows += row_count;
        }
        if let Some(children) = layout.children() {
            queue.extend(children.iter().cloned());
        }
    }

    Ok(total_rows)
}

fn combine_dynamic_attributes(base: &HotReloadedTemplate, extra: &HotReloadedTemplate) -> HotReloadedTemplate {
    let mut combined_attributes = std::collections::HashSet::new();
    let mut merged_nodes = Vec::new();

    for node in &base.nodes {
        if let HotReloadDynamicNode::Attributes(attrs) = node {
            for attr in attrs {
                combined_attributes.insert(attr.name.clone());
            }
        }
    }

    for node in &extra.nodes {
        if let HotReloadDynamicNode::Attributes(attrs) = node {
            for attr in attrs {
                if !combined_attributes.contains(&attr.name) {
                    combined_attributes.insert(attr.name.clone());
                }
            }
        }
    }

    let mut merged_nodes = base.nodes.clone();
    for node in &extra.nodes {
        merged_nodes.push(node.clone());
    }

    HotReloadedTemplate {
        nodes: merged_nodes,
        ..base.clone()
    }
}

use std::path::Path;
use std::path::PathBuf;
use anyhow::Result;
use fs_err as fs;

fn list_installed_components(target: &str, cache_dir: &Path) -> Result<Vec<String>> {
    let components_dir = cache_dir.join("components");
    if !components_dir.exists() {
        return Ok(vec![]);
    }

    let mut components = Vec::new;
    for entry in fs::read_dir(components_dir)? {
        let entry = entry?;
        let path = entry.path();
        let file_name = path.file_name().and_then(|n| n.to_str()).ok_or(anyhow::anyhow!("Invalid filename"))?;
        let component_name = file_name.to_string();

        // Check if the component is relevant to the target
        if path.join("target").exists() && fs::read_to_string(path.join("target"))?.contains(target) {
            components.push(component_name);
        }
    }

    Ok(components)
}

use std::sync::Arc;
use miraland_quic_client::nonblocking::quic_client::QuicClientConnection;
use solana_sdk::transport::Result as TransportResult;
use tokio::time::sleep;
use std::time::Duration;

fn send_with_timeout_and_retry(
    conn: &QuicClientConnection,
    data: Vec<u8>,
    max_retries: u32,
) -> TransportResult<()> {
    let mut retries = 0;
    loop {
        match conn.send(data.clone()) {
            Ok(_) => {
                return Ok(());
            }
            Err(e) => {
                if retries >= max_retries {
                    return Err(e);
                }
                retries += 1;
                sleep(Duration::from_millis(100)).await;
            }
        }
    }
}

