use crate::module_type::{Client, SessionId};
use crate::SdkErr;
use crate::responses::SessionStatusRes;
use bincode;
use risc0_zkvm::Receipt;

fn download_and_verify_receipt(client: &Client, session_uuid: &str, method_id: &[u32; 8]) -> Result<Receipt, SdkErr> {
    // Fetch session status to check if the session is complete
    let session_status_res: SessionStatusRes = client.get_session_status(session_uuid).map_err(SdkErr::from)?;

    if session_status_res.status != "complete" {
        return Err(SdkErr::SessionNotComplete);
    }

    // Download the receipt
    let receipt_data = client.get_receipt(session_uuid).map_err(SdkErr::from)?;

    // Deserialize the receipt
    let receipt: Receipt = bincode::deserialize(&receipt_data).map_err(|e| SdkErr::DeserializationError(e.to_string()))?;

    // Verify the receipt against the method ID
    if receipt.method_id != *method_id {
        return Err(SdkErr::MethodIdMismatch);
    }

    Ok(receipt)
}

fn debounced_input_handler<F>(
    delay: Duration,
    mut callback: F,
) -> impl FnMut(Event)
where
    F: FnMut(String) + 'static,
{
    let callback = Rc::new(RefCell::new(callback));
    let mut timeout_handle: Option<TimeoutHandle> = None;

    move |event: Event| {
        if let Some(handle) = timeout_handle.take() {
            set_timeout_with_handle(handle, |_| {});
        }

        let value = event_target_value(&event);
        set_timeout_with_handle(
            set_timeout_with_handle(
                Rc::new(RefCell::new(move || {
                    if let Some(callback) = callback.borrow_mut().as_mut() {
                        callback(value.clone());
                    }
                })),
                delay,
            ),
            |_| {},
        );

        timeout_handle = Some(set_timeout_with_handle(
            Rc::new(RefCell::new(move || {
                if let Some(callback) = callback.borrow_mut().as_mut() {
                    callback(value.clone());
                }
            })),
            delay,
        ));
    }
}

fn withdrawable_dao_cells<'a, DL>(calculator: &DaoCalculator<'a, DL>, rtx: &ResolvedTransaction) -> Result<Vec<&'a CellMeta>, DaoError>
where
    DL: CellDataProvider + HeaderProvider,
{
    let mut result = Vec::new();
    let consensus = calculator.consensus();
    let dao_version = consensus.dao_version();

    for input in &rtx.inputs {
        if let Some(meta) = input.cell_meta() {
            if let Some(cell_data) = calculator.cell_data_provider().get_cell_data(&meta.cell_id) {
                if let Some(dao_data) = cell_data.dao_data() {
                    if dao_data.version() == dao_version {
                        if dao_data.is_withdrawable() {
                            result.push(meta);
                        }
                    }
                }
            }
        }
    }

    Ok(result)
}

