fn refresh_token(
    token_str: &str,
    refresh_key: &[u8],
    new_expiration: u64,
) -> Result<String, jwt::Error> {
    let mut header = Header::new(jwt::Algorithm::HS256);
    let mut claims = Claims::default();

    let token = Token::decode(token_str, &header, refresh_key)?;
    let original_claims = token.claims();

    // Extract the original expiration time
    let original_exp = original_claims.exp.unwrap_or(0);
    let current_time = chrono::Utc::now().timestamp();

    // Calculate the new expiration time
    let new_exp = new_expiration as i64;

    // Update the expiration time in the claims
    claims.exp = Some(new_exp);

    // Encode the new token with the updated claims and the same key
    let new_token = Token::encode(&header, &claims, refresh_key)?;
    Ok(new_token.to_string())
}

use aotuv_lancer_vorbis_sys::{OggVorbis_File, ov_time_seek, ov_read_float};

fn read_pcm_at_time(vf: &mut OggVorbis_File, start_sec: f64, sample_count: i32) -> Result<Vec<Vec<f32>>, String> {
    // Seek to the specified time position
    if ov_time_seek(vf, start_sec) != 0 {
        return Err("Failed to seek to the specified time position".to_string());
    }

    // Read the specified number of interleaved float samples
    let samples = ov_read_float(vf, sample_count as usize);
    if samples.is_null() {
        return Err("Failed to read PCM samples".to_string());
    }

    // Convert raw pointer to Vec<Vec<f32>>
    let sample_data = unsafe {
        let sample_ptr = samples as *mut [f32];
        let mut result = Vec::new();
        let mut i = 0;
        while i < sample_count {
            let channel = unsafe { *sample_ptr.add(i) };
            result.push(vec![channel]);
            i += 1;
        }
        result
    };

    Ok(sample_data)
}

use chrono::NaiveDateTime;
use chrono::Utc;
use vortex_array::arrays::PrimitiveArray;
use vortex_array::validity::Validity;
use vortex_array::{ArrayRef, VortexResult};
use vortex_dtype::datetime::TimeUnit;
use vortex_dtype::datetime::DateTimeParts;
use crate::{DateTimePartsArray, TimestampParts};

fn to_rfc3339_strings(array: &DateTimePartsArray, time_unit: TimeUnit) -> VortexResult<ArrayRef> {
    let mut values = Vec::with_capacity(array.len());
    let mut validity = Validity::new(array.len());

    for (i, parts) in array.iter().enumerate() {
        if parts.is_valid() {
            let timestamp_parts = TimestampParts {
                year: parts.year,
                month: parts.month,
                day: parts.day,
                hour: parts.hour,
                minute: parts.minute,
                second: parts.second,
                nanosecond: parts.nanosecond,
            };

            let timestamp = timestamp::from_parts(timestamp_parts, time_unit);
            let naive_datetime = NaiveDateTime::new(
                timestamp.year() as u32,
                timestamp.month() as u32,
                timestamp.day() as u32,
                timestamp.hour() as u32,
                timestamp.minute() as u32,
                timestamp.second() as u32,
            );

            let rfc3339 = naive_datetime.and_utc().to_rfc3339();
            values.push(rfc3339);
        } else {
            validity.set(i, false);
        }
    }

    Ok(PrimitiveArray::new(
        Box::new(values),
        Box::new(validity),
    ))
}

fn verify_jwt_vc<E>(credential: &EnvelopedVerifiableCredential, trust_anchor: &JWK, now: &E) -> Result<(), ClaimsValidity>
where
    E: DateTimeProvider,
{
    let jose_vc: JoseVc = credential.into();
    let jws_slice: JwsSlice = jose_vc.into();
    let payload = jws_slice.payload().ok_or(ClaimsValidity::MissingPayload)?;
    let json_credential: JsonCredential = serde_json::from_slice(payload).map_err(|_| ClaimsValidity::InvalidJson)?;

    let issuer = json_credential.issuer().ok_or(ClaimsValidity::MissingIssuer)?;
    if issuer != trust_anchor.did() {
        return Err(ClaimsValidity::InvalidIssuer);
    }

    let issued_at = json_credential.issued_at().ok_or(ClaimsValidity::MissingIssuedAt)?;
    let expiration_time = json_credential.expiration_time().ok_or(ClaimsValidity::MissingExpirationTime)?;

    let issued_at = DateTimeProvider::now(now).timestamp() - issued_at.timestamp();
    let expiration_time = expiration_time.timestamp() - DateTimeProvider::now(now).timestamp();

    if issued_at < 0 || expiration_time <= 0 {
        return Err(ClaimsValidity::InvalidTime);
    }

    let signature = jws_slice.signature().ok_or(ClaimsValidity::MissingSignature)?;
    if !trust_anchor.verify_signature(payload, signature) {
        return Err(ClaimsValidity::InvalidSignature);
    }

    Ok(())
}

struct RedirectionLogger {
    inner: Logger,
    output: Output,
}

impl RedirectionLogger {
    fn new(inner: Logger) -> Self {
        let output = match env::var("LOG_OUTPUT").as_deref() {
            Ok("stdout") => Output::Stdout,
            Ok("stderr") => Output::Stderr,
            _ => Output::Stderr,
        };
        RedirectionLogger { inner, output }
    }
}

impl log::Log for RedirectionLogger {
    fn log(&self, record: &log::Record) {
        let mut writer = match self.output {
            Output::Stdout => std::io::stdout(),
            Output::Stderr => std::io::stderr(),
        };
        writeln!(writer, "{}", record.args()).unwrap();
    }

    fn enabled(&self, metadata: &log::Metadata) -> bool {
        self.inner.enabled(metadata)
    }

    fn log_metadata(&self, metadata: &log::Metadata) {
        self.inner.log_metadata(metadata)
    }

    fn flush(&self) {
        self.inner.flush()
    }
}

fn monitor_tpu_connections(&self) {
    let mut interval = interval(Duration::from_secs(5));
    let mut reconnect_attempts = 0;

    loop {
        interval.tick();

        // Check each TPU connection
        for tpu_client in &self.tpu_clients {
            if tpu_client.is_disconnected() {
                // Attempt to reconnect
                if let Err(e) = tpu_client.reconnect() {
                    eprintln!("Failed to reconnect to TPU: {}", e);
                    reconnect_attempts += 1;
                    if reconnect_attempts >= 3 {
                        // If too many failures, panic or handle as needed
                        panic!("Exceeded maximum reconnect attempts for TPU");
                    }
                } else {
                    reconnect_attempts = 0;
                    eprintln!("Successfully reconnected to TPU");
                }
            }
        }

        // Reset reconnect attempts if no failures
        reconnect_attempts = 0;
    }
}

use rs_llama_cpp::{gpt_params_c, run_inference, str_to_mut_i8};

fn run_batch_inference(prompts: &[&str], model_path: &str) -> Vec<String> {
    let mut outputs = Vec::new();
    let mut params = gpt_params_c::default();
    let mut prompt = String::new();

    for &prompt_str in prompts {
        prompt = prompt_str.to_string();
        let mut prompt_bytes = str_to_mut_i8(prompt);
        let mut output = String::new();
        let result = unsafe { run_inference(model_path, &mut params, prompt_bytes, &mut output) };
        if result.is_ok() {
            outputs.push(output);
        } else {
            outputs.push("Error generating response".to_string());
        }
    }

    outputs
}

use crate::{H160, H256, H512, H520};
use crate::error::FromStrError;

fn parse_fixed_hash(input: &str) -> Result<FixedHash, FromStrError> {
    let trimmed = input.trim_start_matches('0').trim_start_matches('x');
    let hex = trimmed.parse::<Vec<u8>>()?;

    match hex.len() {
        20 => Ok(FixedHash::H160(H160::from_slice(&hex))),
        32 => Ok(FixedHash::H256(H256::from_slice(&hex))),
        128 => Ok(FixedHash::H512(H512::from_slice(&hex))),
        128 + 1 => Ok(FixedHash::H520(H520::from_slice(&hex))),
        _ => Err(FromStrError::InvalidLength),
    }
}

