}

#[derive(Debug)]
pub enum Error {
    Initialization(Box<dyn std::error::Error + Send + Sync>),
    Write(std::io::Error),
    Io(std::io::Error),
}

#[derive(Debug)]
pub enum Transport {
    Unix(String),
    Tcp(SocketAddr),
    Udp(SocketAddr),
}

fn create_unix_logger(formatter: Formatter3164, path: String) -> Result<Logger<LoggerBackend, Formatter3164>, Error> {
    let writer = Writer::new_unix(path).map_err(|e| Error::Initialization(Box::new(e)))?;
    let logger = Logger::new(formatter, writer).map_err(|e| Error::Initialization(Box::new(e)))?;
    Ok(logger)
}

fn create_tcp_logger(formatter: Formatter3164, addr: SocketAddr) -> Result<Logger<LoggerBackend, Formatter3164>, Error> {
    let writer = Writer::new_tcp(addr).map_err(|e| Error::Initialization(Box::new(e)))?;
    let logger = Logger::new(formatter, writer).map_err(|e| Error::Initialization(Box::new(e)))?;
    Ok(logger)
}

fn create_udp_logger(formatter: Formatter3164, addr: SocketAddr) -> Result<Logger<LoggerBackend, Formatter3164>, Error> {
    let writer = Writer::new_udp(addr).map_err(|e| Error::Initialization(Box::new(e)))?;
    let logger = Logger::new(formatter, writer).map_err(|e| Error::Initialization(Box::new(e)))?;
    Ok(logger)
}

fn create_logger(
    transport: Transport,
    formatter: Formatter3164,
) -> Result<Logger<LoggerBackend, Formatter3164>, Error> {
    match transport {
        Transport::Unix(path) => create_unix_logger(formatter, path),
        Transport::Tcp(addr) => create_tcp_logger(formatter, addr),
        Transport::Udp(addr) => create_udp_logger(formatter, addr),
    }
}

