    let apdu = APDUCommand::new(
        0x00, // CLA
        0x04, // INS
        0x00, // P1
        0x00, // P2
        vec![0x01, 0x02, 0x03], // Data
        0x00, // LC
        0x00, // Le
        0x00, // Lc (for response)
    );

    let response = transport.send(apdu)?;

    if response.status == 0x9000 {
        Ok(())
    } else {
        Err(LedgerHIDError::InvalidResponse)
    }
}

use crate::Contract;
use crate::LightningInputError;
use crate::DecryptedPreimage;

fn is_contract_spendable(contract: &Contract) -> Result<bool, LightningInputError> {
    if contract.is_incoming {
        if let Some(preimage) = &contract.decrypted_preimage {
            if preimage.is_valid() {
                return Ok(true);
            }
        }
        return Err(LightningInputError::DecryptionFailed);
    } else {
        if contract.timelock.is_expired() {
            return Ok(true);
        }
        return Err(LightningInputError::TimelockNotExpired);
    }
}

use js_sys::{Array, Uint8Array};
use multihash::Multihash;
use crate::bindings::{WebTransportHash, WebTransportOptions};

fn build_webtransport_options(certhashes: &[Multihash<64>]) -> WebTransportOptions {
    let mut hashes_array = Array::new();
    for hash in certhashes {
        let hash_bytes = hash.digest();
        let uint8_array = Uint8Array::from(&hash_bytes[..]);
        let hash_obj = WebTransportHash::new_with_u8_array(&uint8_array);
        hashes_array.push(&hash_obj);
    }
    WebTransportOptions::new_with_hashes(&hashes_array)
}

fn send_transaction_with_retry(&self, transaction: &Transaction, max_retries: usize) -> bool {
    let mut retry_count = 0;
    let mut delay = Duration::from_millis(100);

    loop {
        match self.send_transaction(transaction) {
            Ok(_) => return true,
            Err(_) => {
                retry_count += 1;
                if retry_count >= max_retries {
                    return false;
                }
                std::thread::sleep(delay);
                delay = delay * 2;
            }
        }
    }
}

