fn generate_and_validate_invoice(
    lightning: &impl ILnRpcClient,
    amount_msats: u64,
    expiry_secs: Option<u64>,
    description: &str,
) -> Result<(), anyhow::Error> {
    let amount = Amount::from_msats(amount_msats);
    let request = CreateInvoiceRequest {
        amount,
        expiry_secs,
        description: description.to_string(),
        ..Default::default()
    };

    let invoice = lightning.create_invoice(request)?;
    let bolt11 = Bolt11Invoice::from_str(&invoice.bolt11)?;
    let preimage = bolt11.preimage();

    // Validate invoice parameters
    if bolt11.amount_msat() != amount_msats {
        return Err(anyhow::anyhow!("Invoice amount mismatch"));
    }

    if let Some(expiry) = expiry_secs {
        if bolt11.expiry() != expiry {
            return Err(anyhow::anyhow!("Invoice expiry mismatch"));
        }
    }

    if bolt11.description() != description {
        return Err(anyhow::anyhow!("Invoice description mismatch"));
    }

    // Check that the preimage matches the mock one
    if preimage != *MOCK_INVOICE_PREIMAGE {
        return Err(anyhow::anyhow!("Preimage mismatch"));
    }

    Ok(())
}

fn validate_claims_time(claims: &JWTClaims) -> Result<(), String> {
    let now = Utc::now();

    if let Some(exp) = claims.expiration_time() {
        if now.timestamp() >= exp.timestamp() {
            return Err("Token has expired".to_string());
        }
    }

    if let Some(nbf) = claims.not_before() {
        if now.timestamp() < nbf.timestamp() {
            return Err("Token is not yet valid".to_string());
        }
    }

    if let Some(iat) = claims.issued_at() {
        if now.timestamp() < iat.timestamp() {
            return Err("Token was issued in the future".to_string());
        }
    }

    Ok(())
}

use ftail::Config;
use ftail::formatters::readable::ReadableFormatter;
use ftail::ansi_escape::TextStyling;
use log::{Log, Metadata, Record, LevelFilter};

struct DynamicStylingLogger {
    config: Config,
    formatter: ReadableFormatter,
}

impl DynamicStylingLogger {
    fn new(config: Config) -> Self {
        Self {
            config,
            formatter: ReadableFormatter::new(),
        }
    }
}

impl Log for DynamicStylingLogger {
    fn enabled(&self, metadata: &Metadata) -> bool {
        metadata.level() <= self.config.level_filter
    }

    fn log(&self, record: &Record) {
        if self.enabled(record.metadata()) {
            let level_color = match record.level() {
                LevelFilter::Trace => TextStyling::FG_BLUE,
                LevelFilter::Debug => TextStyling::FG_MAGENTA,
                LevelFilter::Info => TextStyling::FG_GREEN,
                LevelFilter::Warn => TextStyling::FG_YELLOW,
                LevelFilter::Error => TextStyling::FG_RED,
            };

            let target_style = TextStyling::BOLD;

            let styled_target = format!("{}{}", target_style.apply_to(record.target()), TextStyling::RESET);
            let styled_level = level_color.apply_to(record.level().to_string());

            let message = format!(
                "{} [{}] {}",
                styled_target,
                styled_level,
                self.formatter.format(record)
            );

            println!("{}", message);
        }
    }

    fn flush(&self) {
        // No-op for simplicity, as println! is synchronous
    }
}

use std::process::Command;
use std::str::from_utf8;
use std::path::Path;
use crate::error::Error;
use crate::version::compare_versions;

fn is_protoc_up_to_date(required: &str, bin_path: &Path) -> Result<bool, Error> {
    let output = Command::new(bin_path)
        .arg("--version")
        .output()
        .map_err(|e| Error::new(format!("Failed to execute protoc: {}", e)))?;

    if !output.status.success() {
        return Err(Error::new("protoc binary failed to execute"));
    }

    let stdout = from_utf8(&output.stdout).map_err(|e| Error::new(format!("Failed to decode protoc version output: {}", e)))?;
    let version = parse_protoc_version(stdout)?;

    Ok(compare_versions(&version, required) == Ordering::Equal)
}

fn parse_protoc_version(output: &str) -> Result<String, Error> {
    let parts: Vec<&str> = output.split_whitespace().collect();
    if parts.len() < 2 {
        return Err(Error::new("Invalid protoc version output format"));
    }

    let version = parts[1].to_string();
    Ok(version)
}

