use bitcoin::Amount;
use fedimint_core::db::DatabaseTransaction;
use futures::StreamExt;
use crate::{UTXOPrefixKey, UnspentTxOutPrefix};

fn calculate_wallet_balance(
    dbtx: &mut DatabaseTransaction<'_>,
    include_unconfirmed: bool,
) -> Amount {
    let mut total_balance = Amount::zero();

    // Query all confirmed UTXOs
    let confirmed_utxos = dbtx
        .prefix_iter::<UTXOPrefixKey, UnspentTxOutPrefix>()
        .filter_map(|item| item.ok())
        .filter(|utxo| utxo.confirmations >= 1);

    for utxo in confirmed_utxos {
        total_balance += utxo.amount;
    }

    // If including unconfirmed, add those as well
    if include_unconfirmed {
        let unconfirmed_utxos = dbtx
            .prefix_iter::<UTXOPrefixKey, UnspentTxOutPrefix>()
            .filter_map(|item| item.ok())
            .filter(|utxo| utxo.confirmations < 1);

        for utxo in unconfirmed_utxos {
            total_balance += utxo.amount;
        }
    }

    total_balance
}

use bitcoincore_zmq::{subscribe_async_monitor, SocketMessage, monitor::event::SocketEvent};
use futures_util::StreamExt;

fn on_disconnect<F>(endpoints: &[&str], mut callback: F) -> bitcoincore_zmq::Result<()>
where
    F: FnMut(&str) + Send + 'static,
{
    for &endpoint in endpoints {
        let (tx, rx) = std::sync::mpsc::channel();
        let mut monitor = subscribe_async_monitor(endpoint)?;
        monitor.subscribe(SocketEvent::Disconnection)?;

        std::thread::spawn(move || {
            while let Some(msg) = rx.recv() {
                if let Some(socket_message) = msg.downcast_ref::<SocketMessage>() {
                    if let Some(event) = socket_message.event {
                        if event == SocketEvent::Disconnection {
                            if let Some(addr) = socket_message.address {
                                callback(addr.as_str());
                            }
                        }
                    }
                }
            }
        });

        monitor.run();
    }

    Ok(())
}

use std::fs::File;
use std::io::{self, BufReader, BufWriter, Read, Write};
use base64_stream::FromBase64Reader;
use base64_stream::generic_array::typenum::U8192;

fn decode_large_file_custom_buffer(input_path: &str, output_path: &str) -> io::Result<()> {
    let input_file = File::open(input_path)?;
    let reader = BufReader::new(input_file);
    let decoder = FromBase64Reader::new(reader, U8192);

    let output_file = File::create(output_path)?;
    let writer = BufWriter::new(output_file);

    let mut buffer = vec![];
    let mut decoded = vec![];

    loop {
        let read = decoder.read(&mut buffer)?;
        if read == 0 {
            break;
        }
        decoded.clear();
        decoder.read_base64(&mut decoded)?;
        writer.write_all(&decoded)?;
        writer.flush()?;
    }

    Ok(())
}

