use derive_visitor::{VisitorMut, Event};
use std::any::Any;

struct TransformerVisitor<F, T>
where
    F: Fn(&mut T),
    T: 'static,
{
    transform: F,
    target_type: std::any::TypeId,
}

impl<F, T> TransformerVisitor<F, T>
where
    F: Fn(&mut T),
    T: 'static + Any,
{
    fn new(transform: F) -> Self {
        TransformerVisitor {
            transform,
            target_type: TypeId::of::<T>(),
        }
    }
}

impl<F, T> VisitorMut for TransformerVisitor<F, T>
where
    F: Fn(&mut T),
    T: 'static + Any,
{
    fn visit(&mut self, value: &mut dyn Any) -> Event {
        if let Some(target) = value.downcast_mut::<T>() {
            (self.transform)(target);
            Event::Continue
        } else if let Some(any) = value.downcast_mut::<Box<dyn Any>>() {
            if any.type_id() == self.target_type {
                if let Some(target) = any.downcast_mut::<T>() {
                    (self.transform)(target);
                    Event::Continue
                } else {
                    Event::Continue
                }
            } else {
                Event::Continue
            }
        } else {
            Event::Continue
        }
    }
}

fn create_transformer<F, T>(transform: F) -> TransformerVisitor<F, T>
where
    F: Fn(&mut T),
    T: 'static,
{
    TransformerVisitor::new(transform)
}

