use crate::internal::{EMPTY, post_tree};

fn custom_postorder<F: FnMut(usize) -> usize>(nn: usize, parent: &[isize], f_size: &[isize], mut _get_child: F) -> Vec<isize> {
    let mut child = vec![vec![]; nn];
    let mut sibling = vec![vec![]; nn];

    for i in 0..nn {
        let p = parent[i] as usize;
        if p != EMPTY {
            let c = _get_child(i);
            child[p].push(c);
            sibling[c].push(i);
        }
    }

    for i in 0..nn {
        child[i].sort_by(|&a, &b| {
            let size_a = f_size[a] as isize;
            let size_b = f_size[b] as isize;
            size_b.cmp(&size_a)
        });
    }

    let mut order = vec![0; nn];
    let mut post = vec![0; nn];
    let mut count = 0;

    for i in 0..nn {
        let mut stack = vec![];
        let mut p = i;
        while p != EMPTY {
            stack.push(p);
            p = parent[p] as usize;
        }

        while let Some(node) = stack.pop() {
            let mut next = EMPTY;
            for &child_node in &child[node] {
                if sibling[child_node].iter().any(|&x| x == node) {
                    next = child_node;
                    break;
                }
            }

            if next == EMPTY {
                post[count] = node as isize;
                count += 1;
                continue;
            }

            let mut idx = 0;
            while idx < child[node].len() && child[node][idx] != next {
                idx += 1;
            }

            if idx < child[node].len() {
                let mut temp = child[node].split_off(idx + 1);
                child[node] = child[node].split_off(idx);
                child[node].extend(temp);
            }

            let mut stack2 = vec![];
            let mut p2 = next;
            while p2 != EMPTY {
                stack2.push(p2);
                p2 = parent[p2] as usize;
            }

            while let Some(n) = stack2.pop() {
                stack.push(n);
            }
        }
    }

    for i in 0..nn {
        order[i] = post[i] as isize;
    }

    post_tree(nn, &mut order, &mut child, &mut sibling);
    order
}

