        from: String,
        to: String,
    }

    impl VisitorMut for CensorVisitor {
        fn visit(&mut self, node: &mut impl DriveMut) {
            if let Some(text) = node.get_text_mut() {
                *text = text.replace(&self.from, &self.to);
            }
