}

fn aggregate_seals<Seal>(operations: &[OperationSeals<Seal>]) -> BTreeMap<CellAddr, Seal>
where
    Seal: RgbSeal,
{
    let mut seals = BTreeMap::new();
    for op in operations {
        for (addr, seal) in &op.seals {
            if let Some(existing) = seals.get(addr) {
                // In case of duplicate addresses, we assume the last one takes precedence
                // or handle as per business logic; here we overwrite
                seals.insert(*addr, *seal);
            } else {
                seals.insert(*addr, *seal);
            }
        }
    }
    seals
}

use ergo_nipopow::{NipopowAlgos, PoPowHeader};
use ergo_merkle_tree::{MerkleTree, MerkleNode};

fn verify_interlink_proof(header: &PoPowHeader) -> bool {
    if header.interlink_proof.is_empty() {
        return false;
    }

    let interlink_root = header.interlink_root;
    let proof = &header.interlink_proof;

    let tree = MerkleTree::new(proof.len(), NipopowAlgos::default());
    let mut current_hash = proof[0].hash();

    for i in 1..proof.len() {
        let sibling = if i % 2 == 0 {
            proof[i - 1]
        } else {
            proof[i + 1]
        };
        current_hash = MerkleNode::combine(&current_hash, &sibling.hash());
    }

    current_hash == interlink_root
}

