fn serialize_nested_collection<'j, C, T>(cx: &mut C, data: &Vec<Vec<T>>) -> LibResult<Handle<'j, JsValue>>
where
    C: Context<'j>,
    T: Serialize,
{
    let mut array = cx.empty_array()?;
    for inner in data {
