}

fn batch_process<const N: usize>(batch: PendingAssignment<'_, Self, N>) -> CompletionReceipt<Self> {
    let mut high_priority_queue = LocalQueue::new();
    let mut low_priority_queue = LocalQueue::new();

    for task in batch.tasks() {
        if task.priority() == Priority::High {
            high_priority_queue.enqueue(task);
        } else {
            low_priority_queue.enqueue(task);
        }
    }

    let mut result = CompletionReceipt::new();
    while let Some(task) = high_priority_queue.dequeue() {
        result.add_task(task);
    }
    while let Some(task) = low_priority_queue.dequeue() {
        result.add_task(task);
    }

    result
}

