fn group_transactions_by_week(transactions: Vec<transactions::Item>) -> HashMap<String, Vec<transactions::Item>> {
    let mut grouped: HashMap<String, Vec<transactions::Item>> = HashMap::new();

    for transaction in transactions {
        if let Some(date) = transaction.executed_at {
            // Calculate the start of the week (Monday)
            let week_start = date
                .checked_sub(Duration::weeks(1))
                .and_then(|d| d.checked_add(Duration::days((d.weekday() as i64 + 1) % 7)))
                .unwrap_or(date);

            // Format the week key as "YYYY-WW"
            let week_key = format!("{}-{:02}", week_start.year(), week_start.week_number());

            // Group the transaction
            grouped.entry(week_key)
                .or_insert_with(Vec::new)
                .push(transaction);
        }
    }

    grouped
}

fn evaluate_expr(
    expr: &Expr,
    interner: &Interner,
    vars: &std::collections::HashMap<Symbol, Value>,
) -> Result<Value, RuntimeError> {
    match expr {
        Expr::Literal(value) => Ok(value.clone()),
        Expr::Variable(name) => {
            if let Some(value) = vars.get(name) {
                Ok(value.clone())
            } else {
                Err(RuntimeError::UnknownVariable(*name))
            }
        },
        Expr::Binary(op, left, right) => {
            let left_val = evaluate_expr(left, interner, vars)?;
            let right_val = evaluate_expr(right, interner, vars)?;
            match op {
                BinaryOperator::Add => Ok(Value::Int(left_val.as_int().unwrap() + right_val.as_int().unwrap())),
                BinaryOperator::Subtract => Ok(Value::Int(left_val.as_int().unwrap() - right_val.as_int().unwrap())),
                BinaryOperator::Multiply => Ok(Value::Int(left_val.as_int().unwrap() * right_val.as_int().unwrap())),
                BinaryOperator::Divide => {
                    if right_val.as_int().unwrap() == 0 {
                        Err(RuntimeError::DivisionByZero)
                    } else {
                        Ok(Value::Int(left_val.as_int().unwrap() / right_val.as_int().unwrap()))
                    }
                },
                BinaryOperator::Modulo => {
                    if right_val.as_int().unwrap() == 0 {
                        Err(RuntimeError::DivisionByZero)
                    } else {
                        Ok(Value::Int(left_val.as_int().unwrap() % right_val.as_int().unwrap()))
                    }
                },
                BinaryOperator::LessThan => Ok(Value::Bool(left_val.as_int().unwrap() < right_val.as_int().unwrap())),
                BinaryOperator::LessThanOrEqual => Ok(Value::Bool(left_val.as_int().unwrap() <= right_val.as_int().unwrap())),
                BinaryOperator::GreaterThan => Ok(Value::Bool(left_val.as_int().unwrap() > right_val.as_int().unwrap())),
                BinaryOperator::GreaterThanOrEqual => Ok(Value::Bool(left_val.as_int().unwrap() >= right_val.as_int().unwrap())),
                BinaryOperator::Equal => Ok(Value::Bool(left_val == right_val)),
                BinaryOperator::NotEqual => Ok(Value::Bool(left_val != right_val)),
                _ => Err(RuntimeError::UnsupportedOperator(*op)),
            }
        },
        Expr::Unary(op, expr) => {
            let value = evaluate_expr(expr, interner, vars)?;
            match op {
                UnaryOperator::Negate => Ok(Value::Int(-value.as_int().unwrap())),
                UnaryOperator::Not => Ok(Value::Bool(!value.as_bool().unwrap())),
                _ => Err(RuntimeError::UnsupportedOperator(*op)),
            }
        },
        Expr::Ternary(condition, true_expr, false_expr) => {
            let condition_val = evaluate_expr(condition, interner, vars)?;
            if condition_val.as_bool().unwrap() {
                evaluate_expr(true_expr, interner, vars)
            } else {
                evaluate_expr(false_expr, interner, vars)
            }
        },
        Expr::Call(func, args) => {
            if func == interner.get("print") {
                if args.len() == 1 {
                    let arg_val = evaluate_expr(args[0], interner, vars)?;
                    println!("{}", arg_val);
                    Ok(Value::Unit)
                } else {
                    Err(RuntimeError::InvalidArgumentCount)
                }
            } else {
                Err(RuntimeError::UnknownFunction(func))
            }
        },
