use std::io;
use positioned_io::ReadAt;

fn read_c_string<R: ReadAt>(io: &R, offset: u64) -> io::Result<String> {
    let mut buffer = Vec::new();
    let mut current_offset = offset;

    loop {
        let mut byte = [0u8; 1];
        io.read_at(&mut byte, current_offset)?; // Read a single byte

        if byte[0] == 0 {
            // Null terminator found, break the loop
            break;
        }

        buffer.push(byte[0]);
        current_offset += 1;
    }

    Ok(String::from_utf8(buffer).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?)
}

