fn deepest_node(&self) -> Node<T>
    where
        T: Clone,
{
    let mut deepest = self;
    let mut current_depth = 0;
    let mut max_depth = 0;

    let mut stack = vec![(self, 0)];

    while let Some((node, depth)) = stack.pop() {
        if depth > max_depth {
            max_depth = depth;
            deepest = node;
        }

        for child in &node.children {
            stack.push((child, depth + 1));
        }
    }

    deepest.clone()
}

