use procinfo::LocalProcessInfo;

fn filter_by_exe_name(root: &LocalProcessInfo, name: &str) -> Vec<LocalProcessInfo> {
    let mut result = Vec::new();
    let mut queue = vec![root.clone()];

    while let Some(current) = queue.pop() {
        if let Some(exe_path) = current.exe_path() {
            if exe_path.ends_with(name) {
                result.push(current);
            }
        }

        if let Ok(children) = current.children() {
            queue.extend(children.iter().cloned());
        }
    }

    result
}

use fax::{encoder::Encoder, VecWriter, Color, BitWriter};

fn encode_bitmap(bitmap: &[bool], width: u16) -> Result<Vec<u8>, Box<dyn std::error::Error>> {
    let mut writer = VecWriter::new();
    let mut encoder = Encoder::new(&mut writer, width, 1, Color::Gray);

    let mut row = Vec::new();
    for &pixel in bitmap {
        row.push(pixel as u8);
        if row.len() == width as usize {
            encoder.encode_row(&row)?;
            row.clear();
        }
    }

    if !row.is_empty() {
        encoder.encode_row(&row)?;
    }

    encoder.finish()?;
    Ok(writer.into_inner())
}

