use packageurl::PackageUrl;
use packageurl::Error;
use std::collections::HashMap;

fn merge_purls(purl1: PackageUrl<'static>, purl2: PackageUrl<'static>) -> Result<PackageUrl<'static>, String> {
    // Check if the core components match
    if purl1.type_() != purl2.type_() {
        return Err("Package types do not match".to_string());
    }

    if purl1.name() != purl2.name() {
        return Err("Package names do not match".to_string());
    }

    if purl1.namespace() != purl2.namespace() {
        return Err("Namespaces do not match".to_string());
    }

    if purl1.version() != purl2.version() {
        return Err("Versions do not match".to_string());
    }

    if purl1.subpath() != purl2.subpath() {
        return Err("Subpaths do not match".to_string());
    }

    // Merge qualifier maps
    let mut merged_qualifiers = HashMap::new();
    for (k, v) in purl1.qualifiers() {
        merged_qualifiers.insert(k.to_string(), v.to_string());
    }
    for (k, v) in purl2.qualifiers() {
        merged_qualifiers.insert(k.to_string(), v.to_string());
    }

    // Create a new PackageUrl with merged qualifiers
    let merged_purl = PackageUrl::new(
        purl1.type_(),
        purl1.namespace(),
        purl1.name(),
        purl1.version(),
        purl1.subpath(),
        merged_qualifiers,
    );

    Ok(merged_purl)
}

fn calculate_obb<P>(points: &[P], rotation: Mat3A) -> (Vec3A, Vec3A, Vec3A, Vec3A)
where
    P: Into<Vec3A> + Copy,
{
    let mut min = Vec3A::MAX;
    let mut max = Vec3A::MIN;
    let mut center = Vec3A::ZERO;
    let mut extent = Vec3A::ZERO;

    for &point in points {
        let world_point = rotation * point.into();
        center += world_point;
        min = min.componentwise_min(world_point);
        max = max.componentwise_max(world_point);
    }

    center /= points.len() as f32;

    let mut axes = Vec::new();
    axes.push(rotation.column(0));
    axes.push(rotation.column(1));
    axes.push(rotation.column(2));

    for &axis in &axes {
        let mut min_proj = f32::MAX;
        let mut max_proj = f32::MIN;
        for &point in points {
            let world_point = rotation * point.into();
            let proj = axis.x * world_point.x + axis.y * world_point.y + axis.z * world_point.z;
            min_proj = min_proj.min(proj);
            max_proj = max_proj.max(proj);
        }
        extent += Vec3A::new(
            (max_proj - min_proj).abs(),
            (max_proj - min_proj).abs(),
            (max_proj - min_proj).abs(),
        );
    }

    let half_extents = extent / 2.0;

    (center, half_extents, axes[0], axes[1], axes[2])
}

use array2d::{Array2D, Error};

fn subgrid<T: Clone>(array: &Array2D<T>, start_row: usize, start_col: usize, sub_rows: usize, sub_cols: usize) -> Result<Array2D<T>, Error> {
    if start_row >= array.num_rows() || start_col >= array.num_cols() {
        return Err(Error::DimensionMismatch);
    }
    if start_row + sub_rows > array.num_rows() || start_col + sub_cols > array.num_cols() {
        return Err(Error::DimensionMismatch);
    }

    let mut result = Array2D::new(sub_rows, sub_cols)?;
    for i in 0..sub_rows {
        for j in 0..sub_cols {
            result[(i, j)] = array[(start_row + i, start_col + j)].clone();
        }
    }
    Ok(result)
}

fn from_regular_polygon(sides: usize, radius: f64) -> Sketch {
    let mut sketch = Sketch::new();
    let angle_step = 2.0 * PI / sides as f64;

    for i in 0..sides {
        let angle = i as f64 * angle_step;
        let x = radius * angle.cos();
        let y = radius * angle.sin();
        sketch.add_point((x, y));
    }

    sketch
}

use rust_i18n;
