fn translate_message(msg: &str, args: &[(&str, &str)], locale: Option<&str>) -> String {
    let locale = locale.unwrap_or(rust_i18n::current_locale());
    let translated = rust_i18n::t!(msg, locale = locale);
    let mut result = translated.to_string();

    for (key, value) in args {
        if let Some(pos) = result.find(&format!("{{{}}}", key)) {
            let mut new_result = String::with_capacity(result.len() + value.len());
            new_result.push_str(&result[..pos]);
            new_result.push_str(value);
            new_result.push_str(&result[pos + key.len() + 2..]);
            result = new_result;
        }
    }

    result
}

