fn add_member_to_stages(
    deps: DepsMut,
    env: Env,
    info: MessageInfo,
    member: String,
    stage_ids: Vec<u32>,
) -> Result<Response, ContractError> {
    // Check if the sender is an admin
    if !can_execute(deps.as_ref(), &info.sender) {
        return Err(ContractError::Unauthorized {});
    }

    // Check if all stages exist
    for &stage_id in &stage_ids {
        if !WHITELIST_STAGES
            .load(deps.storage)
            .map_or(false, |stages| stages.contains(&stage_id))
        {
            return Err(ContractError::StageDoesNotExist { stage_id });
        }
    }

    // Load the current member count
    let mut member_count = MEMBER_COUNT
        .may_load(deps.storage)
        .unwrap_or_default();

    // Check if adding the member would exceed the global limit
    if member_count >= CONFIG.load(deps.storage).unwrap().max_members {
        return Err(ContractError::MaxMembersExceeded {});
    }

    // Load the current whitelist
    let mut whitelist = WHITELIST_STAGES
        .load(deps.storage)
        .unwrap_or_default();

    // Check if the member is already in any of the stages
    for &stage_id in &stage_ids {
        if whitelist
            .get(&stage_id)
            .map_or(false, |members| members.contains(&member))
        {
            return Err(ContractError::MemberAlreadyExists { member, stage_id });
        }
    }

    // Add the member to each stage
    for &stage_id in &stage_ids {
        let members = whitelist
            .entry(stage_id)
            .or_insert_with(Vec::new);
        members.push(member.clone());
    }

    // Update the member count
    member_count += 1;
    MEMBER_COUNT.save(deps.storage, &member_count)?;

    // Update the whitelist
    WHITELIST_STAGES.save(deps.storage, &whitelist)?;

    // Build the response
    Ok(Response::new()
        .add_attribute("action", "add_member_to_stages")
        .add_attribute("member", member)
        .add_attribute("stages", stage_ids.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(","))
        .add_attribute("member_count", member_count.to_string()))
}

