fn compute_target_dir(args: &Args, config: Option<&Config>) -> PathBuf {
    let mut target_dir = PathBuf::new();

    // Check if --target-dir was provided
    if let Some(target_dir_arg) = &args.target_dir {
        target_dir = target_dir_arg.clone();
    } else {
        // Check environment variables in order of precedence
        if let Ok(env_var) = std::env::var("CARGO_BUILD_TARGET_DIR") {
            target_dir = PathBuf::from(env_var);
        } else if let Ok(env_var) = std::env::var("CARGO_TARGET_DIR") {
            target_dir = PathBuf::from(env_var);
        } else {
            // Use the config file if provided
            if let Some(config) = config {
                if let Some(target_dir_config) = &config.build.target_dir {
                    target_dir = target_dir_config.clone();
                }
            }
        }
    }

    target_dir
}

use std::sync::Arc;
use ckb_chain_spec::consensus::Consensus;
use ckb_chain_spec::versionbits::VersionbitsIndexer;
use ckb_error::Error;
use ckb_verification::UnclesError;
use ckb_store::ChainStore;
use ckb_types::{core::{HeaderView, EpochExt}, packed::Byte32};
use crate::contextual_block_verifier::{VerifyContext, UncleVerifierContext};

fn verify_uncle<CS>(
    context: &VerifyContext<CS>,
    uncle: &HeaderView,
    epoch: &EpochExt,
) -> Result<(), Error>
where
    CS: ChainStore,
{
    // Check if the uncle is already in the main chain
    if context.chain_store().get_block_hash_by_number(uncle.number().to_u64()?).is_some() {
        return Err(Error::from(UnclesError::UncleAlreadyInMainChain));
    }

    // Check if the uncle belongs to the same epoch
    if uncle.epoch() != epoch {
        return Err(Error::from(UnclesError::UncleEpochMismatch));
    }

    // Check if the uncle has a matching compact target
    let uncle_compact_target = uncle.compact_target();
    let epoch_consensus = context.chain_spec().consensus();
    if uncle_compact_target != epoch_consensus.target() {
        return Err(Error::from(UnclesError::UncleCompactTargetMismatch));
    }

    // Check if the uncle is a proper descendant of the referenced block
    let referenced_block_hash = context.chain_store().get_block_hash_by_number(uncle.number().to_u64()?)?;
    if referenced_block_hash == uncle.parent_hash() {
        return Err(Error::from(UnclesError::UncleNotProperDescendant));
    }

    Ok(())
}

fn list_installed_toolchains(locator: &PavexLocator) -> Result<Vec<(String, semver::Version)>, anyhow::Error> {
    let toolchain_dir = locator.toolchain_dir()?;
    let mut toolchains = Vec::new();

    if toolchain_dir.exists() {
        for entry in fs::read_dir(toolchain_dir)? {
            let entry = entry?;
            let path = entry.path();
            if path.is_dir() && path.file_name().map_or(false, |name| name != ".git") {
                let version = parse_toolchain_version(&path)?;
                toolchains.push((path.file_name().unwrap().to_string_lossy().into(), version));
            }
        }
    }

    Ok(toolchains)
}

fn parse_toolchain_version(path: &Path) -> Result<semver::Version, anyhow::Error> {
    let version_str = path.file_name().and_then(|name| name.to_str()).ok_or_else(|| anyhow::anyhow!("Invalid filename"))?;
    let version: semver::Version = version_str.parse()?;
    Ok(version)
}

use market::{Producer, Recall, Fault, Failure};
use core::convert::TryFrom;

fn produce_batch_retry<P, I, G>(producer: &P, goods: I) -> Result<(), Recall<P::Flaws, G>>
where
    P: Producer<Good = G>,
    I: IntoIterator<Item = G>,
    G: Clone,
    <P::Flaws as Flaws>::Defect: Flaws<Defect = <P::Flaws as Flaws>::Defect>,
    <<P::Flaws as Flaws>::Defect as Flaws>::Insufficiency: TryFrom<<P::Flaws as Flaws>::Insufficiency>,
{
    for good in goods {
        let mut retry = true;
        while retry {
            match producer.produce(good.clone()) {
                Ok(()) => {
                    retry = false;
                }
                Err(Fault::Failure(Failure::Insufficiency)) => {
                    // Retry on stock insufficiency
                    continue;
                }
                Err(Fault::Recall(recall)) => {
                    // Propagate real defects
                    return Err(Recall::new(recall, good));
                }
                Err(Fault::Failure(other)) => {
                    // Propagate other failures
                    return Err(Recall::new(Fault::Failure(other), good));
                }
            }
        }
    }
    Ok(())
}

fn decode_tty_stream<S>(stream: S) -> impl futures_util::Stream<Item = Result<(TtyType, Vec<u8>)>> 
where
    S: futures_util::Stream<Item = Result<TtyChunk>> + Unpin,
{
    stream.map(|result| {
        let chunk = result?;
        let mut data = Vec::new();
        data.extend_from_slice(&chunk.data);
        Ok((chunk.tty_type, data))
    })
}

fn report_unused_directives<'a>(ctx: &mut Context<'a>) {
    let all_directives = ctx.directives.clone();
    let used_directives = ctx.used_directives.clone();

    let unused_directives: HashSet<&String> = all_directives
        .difference(&used_directives)
        .filter(|&&dir| !dir.is_empty())
        .collect();

    if !unused_directives.is_empty() {
        let mut report = Report::new();
        report.with_title("Unused Directives Detected");
        report.with_description(format!(
            "The following directives are defined but not used in the schema: {:?}",
            unused_directives
        ));

        ctx.report(report);
    }
}

