use bcrypt::{hash, verify, BcryptError};

fn hash_password(password: &str) -> Result<[u8; 24], &'static str> {
    let hashed = match hash(password, 12) {
        Ok(h) => h,
        Err(_) => return Err("Failed to hash password"),
    };
    let mut result = [0u8; 24];
    hashed
        .as_bytes()
        .iter()
        .take(24)
        .cloned()
        .enumerate()
        .for_each(|(i, b)| result[i] = b);
    Ok(result)
}

fn FadeIn() -> impl IntoView {
    let (opacity, set_opacity) = create_signal(0.0);
    let node = create_node_ref();
    let on_mount = move |_| {
        let node = node.get();
        if let Some(node) = node {
            let mut opacity = 0.0;
            let animation_frame = move |_| {
                opacity += 0.05;
                set_opacity.set(opacity);
                if opacity < 1.0 {
                    request_animation_frame(animation_frame);
                }
            };
            request_animation_frame(animation_frame);
        }
    };
    view! {
        <div class="fade-in" style=move || format!("opacity: {}", opacity()) node_ref=node on_mount=on_mount>
            "Fade In Content"
        </div>
    }
}

