fn publish_to_specific_peers(&mut self, topic: impl Into<String>, data: impl Into<Bytes>, peers: &[PeerId]) {
    let topic = topic.into();
    let data = data.into();

    let message = FloodsubMessage::new(topic, data);

    for &peer in peers {
        let handler = NotifyHandler::new(move |swarm, peer_id, _| {
            if peer_id == peer {
                swarm.to_swarm(ToSwarm::NotifyHandler(NotifyHandler::new(move |_, _| {
                    // Handle the event if needed
                }))));
            }
        });

        self.floodsub.behaviour_mut().publish(message);
        self.floodsub.behaviour_mut().notify(peer, handler);
    }
}

fn run_proof_workflow(client: &Client, elf: &[u8], input: Vec<u8>, method_id: [u32; 8]) -> Result<Receipt, SdkErr> {
    let image_id = compute_image_id(elf)?;
    let session_id = client.create_session(image_id, input.clone(), method_id)?;
    client.poll_session(session_id, Duration::from_secs(30))?;
    let receipt = client.download_receipt(session_id)?;
    receipt.verify(&image_id, &method_id)
}

fn filter_segments_by_name(app_state: &mut AppState, filter_text: &str) -> VortexResult<()> {
    if filter_text.is_empty() {
        // If no filter text, reset to the full segment tree
        app_state.segment_grid = collect_segment_tree(&app_state.layout)?;
        return Ok(());
    }

    let filtered_segments = app_state
        .segment_grid
        .iter()
        .filter(|segment| {
            if let Some(name) = &segment.name {
                name.to_lowercase().contains(&filter_text.to_lowercase())
            } else {
                false
            }
        })
        .cloned()
        .collect::<Vec<_>>();

    app_state.segment_grid = filtered_segments;
    Ok(())
}

