fn monitor_session_until_done(client: &Client, session_uuid: &str, timeout: Duration) -> Result<SessionStatusRes, SdkErr> {
    let mut remaining_timeout = timeout;
    loop {
        if remaining_timeout <= Duration::from_millis(0) {
            return Err(SdkErr::Timeout);
        }

        let status_res = client.get_session_status(session_uuid).map_err(|e| {
            SdkErr::Internal(format!("Failed to get session status: {}", e))
        })?;

        if status_res.status == "completed" {
            return Ok(status_res);
        } else if status_res.status == "failed" {
            return Err(SdkErr::SessionFailed);
        }

        // Wait for a short interval before checking again
        sleep(Duration::from_millis(1000));
        remaining_timeout -= Duration::from_millis(1000);
    }
}

use crate::theme::THEMES;
