use std::path::PathBuf;

fn find_icons_by_prefix(prefix: &str) -> Vec<PathBuf> {
    let mut icon_paths = Vec::new();

    for theme in THEMES {
        if let Ok(theme_data) = read_ini_theme(theme.path.clone()) {
            if let Some(icon_dir) = theme_data.icon_dir {
                let icon_dir_path = icon_dir.clone().into_path_buf();
                let entries = std::fs::read_dir(icon_dir_path).ok()?;

                for entry in entries {
                    if let Ok(entry) = entry {
                        let path = entry.path();
                        if path.is_file() && path.to_string_lossy().starts_with(prefix) {
                            icon_paths.push(path);
                        }
                    }
                }
            }
        }
    }

    icon_paths
}

fn validate_client_state() {
    // This function validates parameters required for constructing a Tendermint ClientState
    // It checks chain ID length, trust level, periods, and proof specs

    // Example validation for chain ID length
    let chain_id: ChainId = "example-chain-id".to_string();
    if chain_id.len() > 64 {
        panic!("Chain ID must be at most 64 characters long");
    }

    // Example validation for trust threshold
    let trust_level = TrustThreshold::new(1000000000);
    if trust_level.is_zero() {
        panic!("Trust threshold cannot be zero");
    }

    // Example validation for trusting period
    let trusting_period = Duration::new(10, 0);
    if trusting_period.as_secs() < 60 {
        panic!("Trusting period must be at least 60 seconds");
    }

    // Example validation for unbonding period
    let unbonding_period = Duration::new(20, 0);
    if unbonding_period.as_secs() < trusting_period.as_secs() {
        panic!("Unbonding period must be greater than or equal to trusting period");
    }

    // Example validation for proof specs
    let proof_specs = ProofSpecs::default();
    if proof_specs.merkle_proof_height().is_none() {
        panic!("Merkle proof height must be specified");
    }

    // If all validations pass, the ClientState can be safely constructed
    println!("All ClientState parameters are valid.");
}

