fn validate_pegin_proof(
    proof: &PegInProof,
    secp: &Secp256k1<Verification>,
    descriptor: &Descriptor<CompressedPublicKey>,
) -> Result<(), PegInProofError> {
    if proof.script_pubkey.len() != 25 {
        return Err(PegInProofError::InvalidScriptPubkeyLength);
    }

    let mut script = vec![0; 25];
    script.copy_from_slice(&proof.script_pubkey);

    let tweak = match descriptor.tweak() {
        Some(tweak) => tweak,
        None => return Err(PegInProofError::NoTweakInDescriptor),
    };

    let tweak_pubkey = secp
        .tap_tweak(tweak, &proof.tweak_pubkey)
        .map_err(|_| PegInProofError::InvalidTweakApplication)?;

    let mut tweak_script = vec![0; 25];
    tweak_script.copy_from_slice(&proof.script_pubkey);

    let expected_script = match descriptor
        .derive_script_with_tweak(&tweak_pubkey)
        .map_err(|_| PegInProofError::ScriptDerivationFailed)?
    {
        miniscript::Script::P2WSh(script) => script,
        _ => return Err(PegInProofError::InvalidScriptType),
    };

    if expected_script != script {
        return Err(PegInProofError::ScriptMismatch);
    }

    Ok(())
}

