use shaderc::{Compiler, Error};

fn assemble_and_validate(assembly: &str) -> Result<Vec<u32>, Error> {
    let mut compiler = Compiler::new()?;
    let result = compiler.compile_assembly(assembly, shaderc::TargetMachine::Spv1_0)?;
    let binary = result.binary();

    // Check the magic number
    if binary.len() < 4 || binary[0] != 0x07230223 {
        return Err(Error::new("Invalid SPIR-V magic number".to_string()));
    }

    Ok(binary)
}

fn save_uploaded_files(multipart: &mut Multipart<'_>, dir: &std::path::Path) -> Result<(), Error> {
    while let Some(part) = multipart.next_part().await? {
        if let Some(filename) = part.headers.get("filename") {
            let filename = filename.to_str().ok_or(Error::InvalidHeaderValue)?;
            let path = dir.join(filename);
            let mut file = tokio::fs::File::create(&path).await?;
            let mut buffer = Vec::new();
            while let Some(chunk) = part.next_chunk().await {
                let chunk = chunk?;
                buffer.extend_from_slice(&chunk);
                file.write_all(&buffer).await?;
                buffer.clear();
            }
        }
    }
    Ok(())
}

use crate::CanvasError;
use image::DynamicImage;
use image::ColorType;

fn average_rgba(image: &DynamicImage) -> Result<[u8; 4], CanvasError> {
    let (width, height) = image.dimensions();
    if width == 0 || height == 0 {
        return Err(CanvasError::EmptyImage);
    }

    let mut r_sum = 0u32;
    let mut g_sum = 0u32;
    let mut b_sum = 0u32;
    let mut a_sum = 0u32;
    let mut pixel_count = 0;

    for row in image.enumerate_rows() {
        for pixel in row {
            let [r, g, b, a] = pixel;
            r_sum += r as u32;
            g_sum += g as u32;
            b_sum += b as u32;
            a_sum += a as u32;
            pixel_count += 1;
        }
    }

    if pixel_count == 0 {
        return Err(CanvasError::EmptyImage);
    }

    let r = (r_sum as f32 / pixel_count as f32) as u8;
    let g = (g_sum as f32 / pixel_count as f32) as u8;
    let b = (b_sum as f32 / pixel_count as f32) as u8;
    let a = (a_sum as f32 / pixel_count as f32) as u8;

    Ok([r, g, b, a])
}

