use wascap::jwt::{Claims, Component};
use wascap::wasm;
use wascap::wasm::days_from_now_to_jwt_time;
use nkeys::KeyPair;
use wascap::Result;

fn sign_component_with_claims(
    name: String,
    wasm_bytes: &[u8],
    mod_kp: &KeyPair,
    acct_kp: &KeyPair,
    expires_days: Option<u64>,
    not_before_days: Option<u64>,
    tags: Vec<String>,
    provider: bool,
    rev: Option<i32>,
    ver: Option<String>,
    call_alias: Option<String>,
) -> Result<Vec<u8>> {
    let now = std::time::SystemTime::now();
    let now_seconds = match now.duration_since(std::time::UNIX_EPOCH) {
        Ok(n) => n.as_secs() as u64,
        Err(_) => return Err("Failed to get current time".into()),
    };

    let mut claims = Claims::default();
    claims.name = name;
    claims.tags = tags;
    claims.provider = provider;

    if let Some(rev) = rev {
        claims.rev = rev;
    }

    if let Some(ver) = ver {
        claims.ver = ver;
    }

    if let Some(alias) = call_alias {
        claims.call_alias = alias;
    }

    let expires = match expires_days {
        Some(days) => Some(now_seconds + days_from_now_to_jwt_time(days)),
        None => None,
    };

    let not_before = match not_before_days {
        Some(days) => Some(now_seconds - days_from_now_to_jwt_time(days)),
        None => None,
    };

    claims.expires = expires;
    claims.not_before = not_before;

    let component = Component::new(wasm_bytes, &mod_kp, &acct_kp, &claims)?;
    Ok(component.sign()?)
}

pub async fn prune_stale_gateways(&self) -> anyhow::Result<()> {
    let db = self.db();
    let mut stale_gateways = HashSet::new();
    let mut current_gateways = HashSet::new();

    // Fetch current gateways from the federation
    let current_gateways_result = self.federation().get_gateways().await;
    if let Err(e) = &current_gateways_result {
        return Err(e.into());
    }
    let current_gateways = current_gateways_result.unwrap();

    // Collect current gateway URLs
    for gateway in &current_gateways {
        if let Ok(url) = gateway.url.parse::<SafeUrl>() {
            current_gateways.insert(url);
        }
    }

    // Scan the local gateway mapping for stale entries
    let prefix = GatewayPrefix::new();
    let mut iter = db.iter_prefix(prefix).await?;
    while let Some((key, _)) = iter.next().await {
        let gateway_key: GatewayKey = key.parse()?;
        if let Ok(url) = gateway_key.url.parse::<SafeUrl>() {
            if !current_gateways.contains(&url) {
                stale_gateways.insert(gateway_key);
            }
        }
    }

    // Delete stale entries
    for gateway_key in stale_gateways {
        db.delete(&gateway_key).await?;
    }

    Ok(())
}

fn collect_into_vec<I, T>(iter: I) -> Vec<T>
where
    I: Iterator<Item = T>,
{
    let mut buffer = Vec::with_capacity(1024);
    let mut guard = SliceMemoryGuard::new(&mut buffer);
    let mut count = 0;

    for item in iter {
        if count >= buffer.capacity() {
            buffer.reserve(1024);
            guard = SliceMemoryGuard::new(&mut buffer);
        }
        unsafe {
            *guard.next() = MaybeUninit::new(item);
        }
        count += 1;
    }

    unsafe {
        buffer.set_len(count);
    }

    buffer
}

fn arrow_ipc_to_json_lines<S>(stream: S) -> impl futures::Stream<Item = Result<String, reqwest_streams::StreamBodyError>>
where
    S: futures::Stream<Item = reqwest_streams::StreamBodyResult<arrow::array::RecordBatch>> + Unpin,
{
    stream.map(move |result| {
        let batch = match result {
            Ok(batch) => batch,
            Err(e) => return Err(e.into()),
        };

        let json = batch.to_json().map_err(|e| reqwest_streams::StreamBodyError::Custom(e.to_string()))?;
        Ok(json)
    })
}

