fn validate_next_block_height<D>(db: &D, sealed_block: &SealedBlock) -> Result<(), Error>
where
    D: ImporterDatabase,
{
    let current_tip_height = db.get_latest_block_height()?;
    let block_height = sealed_block.header().height();

    if block_height == BlockHeight::genesis() {
        if current_tip_height != BlockHeight::genesis() - 1 {
            return Err(Error::InvalidBlockHeight);
        }
    } else {
        if block_height != current_tip_height + 1 {
            return Err(Error::InvalidBlockHeight);
        }
    }

    Ok(())
}

use serde_json::Value;
use std::error::Error;

fn add_deletion_policy(
    mut template: Value,
    resource_ids: &[String],
) -> Result<Value, Box<dyn Error>> {
    if template.is_object() {
        if let Some(resources) = template.get("Resources").and_then(|r| r.as_object()) {
            for (resource_id, resource) in resources {
                if resource_ids.iter().any(|&id| id == resource_id) {
                    if let Some(properties) = resource.get("Properties").and_then(|p| p.as_object()) {
                        let deletion_policy = serde_json::json!({
                            "DeletionPolicy": "Retain"
                        });
                        let mut new_properties = serde_json::Map::new();
                        for (k, v) in properties {
                            new_properties.insert(k.clone(), v.clone());
                        }
                        new_properties.insert("DeletionPolicy".to_string(), deletion_policy);
                        let new_resource = serde_json::json!({
                            "Properties": new_properties
                        });
                        template["Resources"][resource_id] = new_resource;
                    }
                }
            }
        }
    }
    Ok(template)
}

