use std::path::Path;
use std::collections::HashMap;
use anyhow::Result;
use rattler_conda_types::{PackageRecord, Platform};
use rattler_index::{package_record_from_conda, package_record_from_tar_bz2};
use fs_err;

fn collect_package_records(channel_path: &Path) -> Result<HashMap<Platform, Vec<PackageRecord>>> {
    let mut records_by_platform = HashMap::new();

    if !channel_path.exists() {
        return Ok(records_by_platform);
    }

    for entry in fs_err::read_dir(channel_path)? {
        let entry = entry?;
        let path = entry.path();

        if path.is_dir() {
            let platform = Platform::from_path(&path);
            if let Some(platform) = platform {
                let mut records = Vec::new();
                for file in fs_err::read_dir(&path)? {
                    let file = file?;
                    let file_path = file.path();

                    if file_path.is_file() {
                        if file_path.extension().and_then(|s| s.to_str()).map_or(false, |ext| ext == "conda") {
                            if let Ok(record) = package_record_from_conda(&file_path) {
                                records.push(record);
                            }
                        } else if file_path.extension().and_then(|s| s.to_str()).map_or(false, |ext| ext == "tar.bz2") {
                            if let Ok(record) = package_record_from_tar_bz2(&file_path) {
                                records.push(record);
                            }
                        }
                    }
                }
                records_by_platform.insert(platform, records);
            }
        }
    }

    Ok(records_by_platform)
}

