use deno_process::Command;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::process::Child;
use tokio::spawn;
use std::sync::{Arc, Mutex};

fn collect_output(command: &str, args: &[&str]) -> Result<(Vec<u8>, Vec<u8>), String> {
    let cmd = Command::new(command).args(args);
    let child = cmd.spawn().map_err(|e| e.to_string())?;

    let stdout = child.stdout.take().ok_or("stdout not available".to_string());
    let stderr = child.stderr.take().ok_or("stderr not available".to_string());

    let (stdout_handle, stderr_handle) = (stdout, stderr);

    let stdout_data = Arc::new(Mutex::new(Vec::new()));
    let stderr_data = Arc::new(Mutex::new(Vec::new()));

    let stdout_handle_clone = stdout_data.clone();
    let stderr_handle_clone = stderr_data.clone();

    let stdout_task = spawn(async move {
        let mut reader = tokio::io::BufReader::new(stdout_handle_clone);
        let mut buffer = Vec::new();
        reader.read_to_end(&mut buffer).await.map_err(|e| e.to_string())
    });

    let stderr_task = spawn(async move {
        let mut reader = tokio::io::BufReader::new(stderr_handle_clone);
        let mut buffer = Vec::new();
        reader.read_to_end(&mut buffer).await.map_err(|e| e.to_string())
    });

    let (_stdout_result, _stderr_result) = join!(stdout_task, stderr_task);

    Ok((stdout_data.lock().unwrap().clone(), stderr_data.lock().unwrap().clone()))
}

