#[derive(Debug, Clone)]
pub struct ExtensionManager {
    extensions_dir: std::path::PathBuf,
}

impl ExtensionManager {
    pub fn new() -> Result<Self> {
        let extensions_dir = fluvio_extensions_dir()?;
        Ok(ExtensionManager { extensions_dir })
    }

    fn clean_extensions(&self) -> Result<()> {
        let entries = std::fs::read_dir(&self.extensions_dir)?;
        for entry in entries {
            let entry = entry?;
            let path = entry.path();
            let file_name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
            if !file_name.starts_with("fluvio-") {
                std::fs::remove_file(path)?;
            }
        }
        Ok(())
    }

    pub fn list_extensions(&self) -> Result<Vec<String>> {
        self.clean_extensions()?;
        let entries = std::fs::read_dir(&self.extensions_dir)?;
        let mut extensions = Vec::new();
        for entry in entries {
            let entry = entry?;
            let file_name = entry.file_name().to_str().unwrap_or("");
            extensions.push(file_name.to_string());
        }
        Ok(extensions)
    }
}

fn validate_pegin_proof(
    proof: &PegInProof,
    secp: &Secp256k1<Verification>,
    untweaked_descriptor: &Descriptor<CompressedPublicKey>,
) -> Result<(), PegInProofError> {
    // Check if the transaction is included in the proof
    if proof.transaction.is_none() {
        return Err(PegInProofError::MissingTransaction);
    }

    // Check if the output index exists
    if proof.output_index >= proof.transaction.as_ref().unwrap().tx.out.len() {
        return Err(PegInProofError::InvalidOutputIndex);
    }

    // Get the transaction and the output
    let tx = proof.transaction.as_ref().unwrap();
    let output = &tx.tx.out[proof.output_index];

    // Check if the tweaked script matches the expected script
    let expected_script = untweaked_descriptor.tweak(proof.tweak.as_ref().unwrap(), secp);
    if output.script_pubkey != expected_script {
        return Err(PegInProofError::InvalidTweakedScript);
    }

    Ok(())
}

