fn generate_transaction_summary<T>(transaction: &RuntimeTransaction<T>) -> String
where
    T: solana_svm_transaction::svm_message::SVMMessage,
{
    let message = &transaction.message;
    let mut summary = String::new();

    summary.push_str("Transaction Summary:\n");
    summary.push_str(&format!("Transaction Hash: {}\n", transaction.signature));
    summary.push_str(&format!("Fee: {}\n", transaction.fee));
    summary.push_str(&format!("Instruction Count: {}\n", message.instructions.len()));
    summary.push_str(&format!("Signature Type Count:\n"));

    let signature_counts: std::collections::HashMap<&str, usize> = message
        .signature_types
        .iter()
        .map(|&sig_type| (sig_type.as_str(), 1))
        .fold(std::collections::HashMap::new(), |mut map, (key, value)| {
            *map.entry(key).or_insert(0) += value;
            map
        });

    for (sig_type, count) in signature_counts {
        summary.push_str(&format!("  {}: {}\n", sig_type, count));
    }

    summary
}

fn filter_mangled_symbols_by_frequency(semantic: &mut Semantic<'_>, program: &Program<'_>) -> Vec<(SymbolId, usize)> {
    let mut symbol_frequency = std::collections::HashMap::new();

    for symbol_id in semantic.symbol_table().symbols() {
        let symbol = semantic.symbol_table().get(*symbol_id);
        if let Some(symbol) = symbol {
            let mut count = 0;
            for node in program.body() {
                if let Some(ident) = node.as_ident() {
                    if ident.symbol_id() == *symbol_id {
                        count += 1;
                    }
                }
            }
            symbol_frequency.insert(*symbol_id, count);
        }
    }

    let mut result: Vec<(SymbolId, usize)> = symbol_frequency.into_iter().collect();
    result.sort_by(|a, b| b.1.cmp(&a.1));
    result
}

