fn ping_pong<C>(mux: &libp2p_mplex::Multiplex<C>, payload: &[u8]) -> std::io::Result<()>
where
    C: futures::io::AsyncRead + futures::io::AsyncWrite + Unpin,
{
    let (mut substream, _) = mux.open_outbound()?;
    let (mut reader, mut writer) = substream.split();

    writer.write_all(payload)?;
    writer.flush()?;

    let mut buffer = vec![0; payload.len()];
    reader.read_exact(&mut buffer)?;
    if buffer != payload {
        return Err(std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            "payload mismatch",
        ));
    }

    Ok(())
}

