fn collect_links(pandoc: &mut Pandoc) -> Vec<String> {
    let mut links = Vec::new();
    let mut visitor = LinkCollector(&mut links);
    visitor.visit_pandoc(pandoc);
    links
}

struct LinkCollector<'a> {
    links: &'a mut Vec<String>,
}

impl<'a> MutVisitor for LinkCollector<'a> {
    fn visit_inline(&mut self, inline: &mut Inline) {
        if let Inline::Link(link) = inline {
            if let Some(url) = &link.url {
                self.links.push(url.clone());
            }
        }
    }
}

fn draw_centered_image(
    engine: &mut Engine,
    image: &Image,
    target: Rectangle,
    transformation: Transformation,
    pixels: &mut tiny_skia::PixmapMut<'_>,
    clip_mask: &mut tiny_skia::Mask,
    clip_bounds: Rectangle,
) {
    let src_width = image.width as f32;
    let src_height = image.height as f32;

    let fitted_rect = fit_rect_into(target, src_width, src_height);

    let mut transform = transformation;
    transform.translate(fitted_rect.x - target.x, fitted_rect.y - target.y);

    engine.draw_image(
        image,
        pixels,
        clip_mask,
        clip_bounds,
        &transform,
    );
}

use libarchive::reader::Builder;
use libarchive::writer::Disk;
use libarchive::archive::{ReadFormat, ReadFilter};
use tempfile;

fn extract_to_temp(path: &str) -> Result<std::path::PathBuf, Box<dyn std::error::Error>> {
    let temp_dir = tempfile::tempdir()?;
    let mut reader = Builder::new_file(path, ReadFormat::Ustar, ReadFilter::All)?;
    let mut writer = Disk::new(&temp_dir.path(), true)?;

    while let Some(entry) = reader.next_entry() {
        writer.write_entry(entry)?;
    }

    Ok(temp_dir.path().to_path_buf())
}

fn validate_blob_fees(tx: &dyn crate::transaction::Transaction, block: &dyn crate::Block) -> Result<(), &'static str> {
    if tx.get_type() != TransactionType::Eip4844 {
        return Ok(());
    }

    let blob_gas_price = block.calculate_blob_gas_price();
    let max_fee_per_blob_gas = tx.get_max_fee_per_blob_gas();

    if max_fee_per_blob_gas < blob_gas_price {
        return Err("Transaction's max fee per blob gas is less than the block's blob gas price");
    }

    Ok(())
}

use nom::{character::complete::{char, digit1}, combinator::{map_res, opt}, IResult};
use slyce::{Slice, Index};

fn parse_slice_expr(input: &str) -> Result<Slice, String> {
    let result: IResult<&str, (u64, u64, u64)> = parse_slice(input);
    match result {
        Ok((_, (start, end, step))) => {
            Ok(Slice {
                start: Index::From(start),
                end: Index::From(end),
                step: Index::From(step),
            })
        }
        Err(_) => Err("Invalid slice expression".to_string()),
    }
}

fn parse_slice(input: &str) -> IResult<&str, (u64, u64, u64)> {
    let (input, _) = char('[')(input)?;
    let (input, start) = parse_index(input)?;
    let (input, _) = char(':')(input)?;
    let (input, end) = parse_index(input)?;
    let (input, _) = char(':')(input)?;
    let (input, step) = parse_index(input)?;
    let (input, _) = char(']')(input)?;
    Ok((input, (start, end, step)))
}

fn parse_index(input: &str) -> IResult<&str, u64> {
    let (input, num) = map_res(digit1, |s: &str| s.parse::<u64>())(input)?;
    Ok((input, num))
}

fn log_update_check_to_file(informer: UpdateInformer<registry::Crates, &str, &str>, log_path: &std::path::Path) -> std::io::Result<()> {
    let mut file = std::fs::File::create(log_path)?;
    let check = informer.check();
    let result = match check {
        Check::NoUpdate => "No update available",
        Check::UpdateAvailable(version) => format!("Update available: {}", version),
        Check::Error(msg) => format!("Error checking for updates: {}", msg),
    };
    writeln!(file, "{}", result)?;
    Ok(())
}

fn payment_latency(
    payment_image: PaymentImage,
    events: &[PersistedLogEntry],
) -> Option<Duration> {
    let start_event = events
        .iter()
        .find(|entry| {
            if let Event::OutgoingPaymentStarted(OutgoingPaymentStarted {
                payment_image: img,
                ..
            }) = &entry.event
            {
                img == &payment_image
            } else {
                false
            }
        })
        .map(|entry| entry.timestamp);

    let success_event = events
        .iter()
        .find(|entry| {
            if let Event::CompleteLightningPaymentSucceeded(CompleteLightningPaymentSucceeded {
                payment_image: img,
                ..
            }) = &entry.event
            {
                img == &payment_image
            } else {
                false
            }
        })
        .map(|entry| entry.timestamp);

    start_event.and_then(|start| success_event.map(|success| success - start))
}

fn notify_multiple_accounts(&self, accounts: &[(&AccountSharedData, Option<&SanitizedTransaction>, &Pubkey, u64)], slot: Slot, is_startup: bool) {
    let measure = Measure::start("notify_multiple_accounts");
    let mut plugins = self.plugins.read().unwrap();
    for (account, tx, pubkey, _slot) in accounts {
        let key = *pubkey;
        let account_data = account.as_ref();
        let tx = tx.unwrap_or(&SanitizedTransaction::default());
        let account_info = (&key, account_data, tx);
        for plugin in &*plugins {
            plugin.notify_account_update(account_info, slot, is_startup);
        }
    }
    measure.stop();
    metrics::record("notify_multiple_accounts_time", measure.as_nanos() as u64, "nanoseconds");
}

fn backup_store(
    &self,
    context: Option<Context>,
    bucket: String,
    file_path: &str,
) -> anyhow::Result<()> {
    let store = self.store()?;
    let mut stream = store.iter(bucket.as_str());

    let mut file = fs::File::create(file_path).await?;
    while let Some(entry) = stream.try_next().await? {
        let key = entry.key().to_string();
        let value = entry.value().to_vec();
        let encoded_value = base64::encode(&value);
        let json_line = format!("{{\"key\": \"{}\", \"value\": \"{}\"}}\n", key, encoded_value);
        file.write_all(json_line.as_bytes()).await?;
    }
    Ok(())
}

