fn remove(&mut self, value: T) -> bool {
    if let Some(slot_index) = self.key2slot.remove(&value) {
        let index = slot_index.index();
        let last = self.slots.len() - 1;
        self.slots.swap_remove(index);
        if index != last {
            let moved = self.slots[index].clone();
            self.key2slot.insert(moved, SlotIndex(index));
        }
        true
    } else {
        false
    }
}

