fn format_see_links(doxygen: &str) -> String {
    let mut result = String::new();
    let mut in_see = false;
    let mut in_sa = false;
    let mut current_annotation = String::new();
    let mut current_content = String::new();
    let mut current_link = String::new();

    for ch in doxygen.chars() {
        if ch == '@' {
            if in_see || in_sa {
                // End of current annotation
                if in_see {
                    // Format @see as markdown link
                    if !current_content.is_empty() && !current_link.is_empty() {
                        result.push_str(&format!("[{}]: {}{}", current_content, current_link, if current_link.ends_with('.') { "" } else { "." }));
                    }
                } else if in_sa {
                    // Format @sa as markdown link
                    if !current_content.is_empty() && !current_link.is_empty() {
                        result.push_str(&format!("[{}]: {}{}", current_content, current_link, if current_link.ends_with('.') { "" } else { "." }));
                    }
                }
                in_see = false;
                in_sa = false;
                current_annotation.clear();
                current_content.clear();
                current_link.clear();
            } else {
                // Start of new annotation
                in_see = ch == 's' && current_annotation == "@see";
                in_sa = ch == 's' && current_annotation == "@sa";
                current_annotation.push(ch);
            }
        } else if in_see || in_sa {
            if ch == ' ' {
                // Separate annotation name from content
                if current_annotation == "@see" || current_annotation == "@sa" {
                    current_content.push(ch);
                }
            } else if ch == '[' {
                // Start of link
                current_link.push(ch);
            } else if ch == ']' {
                // End of link
                current_link.push(ch);
                if current_link.ends_with("]") {
                    current_link.pop();
                }
                if in_see || in_sa {
                    // End of annotation
                    if !current_content.is_empty() && !current_link.is_empty() {
                        result.push_str(&format!("[{}]: {}{}", current_content, current_link, if current_link.ends_with('.') { "" } else { "." }));
                    }
                }
            } else {
                if current_annotation == "@see" || current_annotation == "@sa" {
                    current_content.push(ch);
                } else {
                    current_link.push(ch);
                }
            }
        } else {
            result.push(ch);
        }
    }

    if in_see || in_sa {
        if !current_content.is_empty() && !current_link.is_empty() {
            result.push_str(&format!("[{}]: {}{}", current_content, current_link, if current_link.ends_with('.') { "" } else { "." }));
        }
    }

    result
}

fn format_transaction_status_meta(meta: &TransactionStatusMeta) -> String {
    let mut result = String::new();
    result.push_str("Transaction Status Meta:\n");

    if let Some(signature) = &meta.signature {
        result.push_str(&format!("  Signature: {}\n", signature));
    }

    if let Some(slot) = meta.slot {
        result.push_str(&format!("  Slot: {}\n", slot));
    }

    if let Some(block_time) = meta.block_time {
        result.push_str(&format!("  Block Time: {}\n", block_time));
    }

    if let Some(wallets) = &meta.wallets {
        result.push_str("  Wallets:\n");
        for wallet in wallets {
            result.push_str(&format!("    {}\n", wallet));
        }
    }

    if let Some(inner_instructions) = &meta.inner_instructions {
        result.push_str("  Inner Instructions:\n");
        for inner_instruction in inner_instructions {
            result.push_str(&format!("    Index: {}\n", inner_instruction.index));
            if let Some(program_id) = &inner_instruction.program_id {
                result.push_str(&format!("      Program ID: {}\n", program_id));
            }
            if let Some(accounts) = &inner_instruction.accounts {
                result.push_str("      Accounts:\n");
                for account in accounts {
                    result.push_str(&format!("        {}\n", account));
                }
            }
            if let Some(data) = &inner_instruction.data {
                result.push_str(&format!("      Data: {}\n", data));
            }
        }
    }

    if let Some(fee) = meta.fee {
        result.push_str(&format!("  Fee: {}\n", fee));
    }

    if let Some(recent_blockhash) = &meta.recent_blockhash {
        result.push_str(&format!("  Recent Blockhash: {}\n", recent_blockhash));
    }

    if let Some(account_keys) = &meta.account_keys {
        result.push_str("  Account Keys:\n");
        for account_key in account_keys {
            result.push_str(&format!("    {}\n", account_key));
        }
    }

    if let Some(pre_token_balances) = &meta.pre_token_balances {
        result.push_str("  Pre Token Balances:\n");
        for balance in pre_token_balances {
            result.push_str(&format!("    Account: {}, Old Balance: {}\n", balance.account, balance.old_balance));
        }
    }

    if let Some(post_token_balances) = &meta.post_token_balances {
        result.push_str("  Post Token Balances:\n");
        for balance in post_token_balances {
            result.push_str(&format!("    Account: {}, New Balance: {}\n", balance.account, balance.new_balance));
        }
    }

    if let Some(recent_blockhashes) = &meta.recent_blockhashes {
        result.push_str("  Recent Blockhashes:\n");
        for blockhash in recent_blockhashes {
            result.push_str(&format!("    {}\n", blockhash));
        }
    }

    if let Some(transaction) = &meta.transaction {
        result.push_str("  Transaction:\n");
        result.push_str(&format!("    Length: {}\n", transaction.len()));
        result.push_str(&format!("    Data: {}\n", transaction));
    }

    result
}

fn map_port_with_retry(
    protocol: Protocol,
    private_port: u16,
    public_port: u16,
    lifetime: u32,
    max_retries: u32,
) -> Result<()> {
    let mut retries = 0;
    loop {
        match Natpmp::new().map_port(protocol, private_port, public_port, lifetime) {
            Ok(Response::Success) => {
                return Ok(());
            }
            Ok(Response::Failure) => {
                if retries >= max_retries {
                    return Err(Error::TransientFailure);
                }
                retries += 1;
                std::thread::sleep(Duration::from_secs(5));
            }
            Err(e) => {
                if retries >= max_retries {
                    return Err(e);
                }
                retries += 1;
                std::thread::sleep(Duration::from_secs(5));
            }
        }
    }
}

use fuel_indexer_database_types::{Table, Column, Persistence, SqlFragment, Constraint};
use std::fmt::Write;

fn generate_create_sql(table: &Table) -> String {
    let mut sql = String::new();
    write!(&mut sql, "CREATE TABLE ").unwrap();
    write!(&mut sql, "{}", table.name).unwrap();
    write!(&mut sql, " (").unwrap();

    for (i, column) in table.columns.iter().enumerate() {
        if i > 0 {
            write!(&mut sql, ", ").unwrap();
        }

        let mut column_sql = String::new();
        write!(&mut column_sql, "{}", column.name).unwrap();

        match column.persistence {
            Persistence::Virtual => {
                write!(&mut column_sql, " {}", column.type_.as_str()).unwrap();
                write!(&mut column_sql, " {}", column.nullable).unwrap();
            }
            Persistence::Physical => {
                write!(&mut column_sql, " {}", column.type_.as_str()).unwrap();
                if let Some(default) = &column.default {
                    write!(&mut column_sql, " DEFAULT {}", default).unwrap();
                }
                write!(&mut column_sql, " {}", column.nullable).unwrap();
            }
        }

        write!(&mut sql, "{}", column_sql).unwrap();
    }

    for constraint in &table.constraints {
        write!(&mut sql, ", ").unwrap();
        write!(&mut sql, "{}", constraint.fragment).unwrap();
    }

    write!(&mut sql, ");").unwrap();

    sql
}

use fedimint_server_core::bitcoin_rpc::ServerBitcoinRpcMonitor;
use fedimint_core::bitcoin::Transaction;
use std::time::Duration;
use tokio::time;

fn submit_transaction_with_retry(
    rpc_monitor: &ServerBitcoinRpcMonitor,
    tx: Transaction,
    max_retries: u64,
    initial_backoff: Duration,
) {
    let mut retries = 0;
    let mut backoff = initial_backoff;

    loop {
        if retries >= max_retries {
            panic!("Max retries exceeded while submitting transaction");
        }

        if rpc_monitor.is_node_synced_at_least(95) {
            if let Err(e) = rpc_monitor.broadcast_transaction(&tx) {
                eprintln!("Transaction broadcast failed: {}", e);
                retries += 1;
                tokio::time::sleep(backoff).await;
                backoff = backoff * 2;
            } else {
                println!("Transaction successfully broadcasted");
                break;
            }
        } else {
            println!("Node not synced enough (95% required). Waiting...");
            tokio::time::sleep(Duration::from_secs(10)).await;
        }
    }
}

