fn remaining_resources_at(&self, rate_limit: &RateLimit, at: Instant) -> u32 {
    let now = at;
    let mut tokens = rate_limit.capacity;
    let mut last_refresh = self.last_refresh;

    if now > last_refresh {
        let elapsed = now - last_refresh;
        let tokens_refilled = (elapsed.as_nanos() as f64 / rate_limit.interval.as_nanos() as f64) * rate_limit.rate as f64;
        tokens = (tokens + tokens_refilled as u32).min(rate_limit.capacity);
        last_refresh = now;
    }

    tokens.saturating_sub(self.tokens_used)
}

use std::path::Path;
use anyhow::Result;
use risc0_zkp::core::digest::Digest;
use risc0_binfmt::compute_image_id;
use hex::FromHex;

fn compute_image_id_with_fallback(elf_path: &Path) -> Result<Digest> {
    // Try the fast r0vm --id method
    let mut cmd = std::process::Command::new("r0vm");
    cmd.arg("--id").arg(elf_path);
    let output = cmd.output()?;

    if output.status.success() {
        let hex_str = String::from_utf8_lossy(&output.stdout);
        let digest = Digest::from_hex(hex_str.trim()).map_err(|e| anyhow::anyhow!("Failed to parse digest from r0vm: {}", e))?;
        return Ok(digest);
    }

    // Fallback to the slower risc0_binfmt method
    compute_image_id(elf_path).map_err(|e| anyhow::anyhow!("Failed to compute image ID with both methods: {}", e))
}

use crate::args::{gather_commandline_args, is_safe_taskname};
