fn validate_nur_args(args: Vec<String>) -> NurResult<(Vec<String>, bool, Vec<String>)> {
    if args.is_empty() {
        return Err(NurError::new("No arguments provided"));
    }

    let (task_name, rest) = gather_commandline_args(&args);
    if !is_safe_taskname(&task_name) {
        return Err(NurError::new("Invalid task name"));
    }

    let (arguments, remaining) = gather_commandline_args(&rest);
    Ok((arguments, task_name != "", remaining))
}

use logging_timer::{stimer, executing, finish};

fn process_items(items: &[i32]) -> i32 {
    stimer!("Processing items");
    let chunk_size = 100;
    let mut total = 0;

    for chunk in items.chunks(chunk_size) {
        executing!("Processing chunk");
        let sum: i32 = chunk.iter().sum();
        total += sum;
    }

    finish!("Processing completed");
    total
}

