use crate::bedrock::{BedrockStreamingResponse, BedrockError};
use futures::stream::BoxStream;
use anyhow::{Result, Context};

fn collect_stream(stream: BoxStream<'static, Result<BedrockStreamingResponse, BedrockError>>) -> Result<String, anyhow::Error> {
    let mut result = String::new();
    let mut first = true;

    stream.for_each(|item| match item {
        Ok(response) => {
            if let Some(content) = &response.content {
                if !first {
                    result.push('\n');
                }
                result.push_str(content);
                first = false;
            }
        }
        Err(e) => return Err(e.into()),
    }).await?;

    Ok(result)
}

fn persist_files(parts: &mut awmp::Parts, dest_dir: &std::path::Path) -> Result<Vec<PathBuf>, awmp::Error> {
    let mut file_paths = Vec::new();

    while let Some(part) = parts.next() {
        if let Ok(file) = part {
            if let Some(filename) = file.filename() {
                let sanitized_filename = sanitize_filename(filename);
                let file_path = dest_dir.join(sanitized_filename);

                // Ensure the destination directory exists
                std::fs::create_dir_all(dest_dir).map_err(|e| awmp::Error::Io(e))?;

                // Open the file for writing
                let mut file = std::fs::File::create(&file_path).map_err(|e| awmp::Error::Io(e))?;

                // Copy the file content
                std::io::copy(&mut file, &mut std::io::BufReader::new(file)).map_err(|e| awmp::Error::Io(e))?;

                file_paths.push(file_path);
            }
        }
    }

    Ok(file_paths)
}

fn sanitize_filename(filename: &str) -> String {
    filename
        .chars()
        .filter(|c| c.is_alphanumeric() || ["_", "-", ".", " ", "(", ")", "[", "]", "{", "}", "/", "\\",
                                            ":", ";", ",", "=", "+", "*", "&", "^", "%", "$", "#", "@",
                                            "!", "'", "\"", "<", ">", "|", "~", "`", "\t", "\n", "\r"]
                                 .contains(c))
        .collect()
}

