use std::io::Write;
use ocaml_gen::Env;

pub fn decl_module_indented<W: std::io::Write>(
    w: &mut W,
    env: &mut Env,
    mod_name: &'static str,
    indent: usize,
    block: impl FnOnce(&mut Env),
) {
    write!(w, "{}", format_args!("{: >1$}", "", indent * env.nested())).unwrap();
    let module_declaration = env.new_module(mod_name);
    write!(w, "{}\n", module_declaration).unwrap();

    block(env);

    write!(w, "{}", format_args!("{: >1$}", "", indent * (env.nested() - 1))).unwrap();
    write!(w, "{}\n", env.parent()).unwrap();
}

fn reverse_set<T>(set: &LinkedHashSet<T>) -> LinkedHashSet<T>
where
    T: Eq + Hash + Clone,
{
    let mut reversed = LinkedHashSet::new();
    let mut iter = set.iter().rev();
    while let Some(item) = iter.next() {
        reversed.insert(item.clone());
    }
    reversed
}

use image_compare::prelude::*;
use image::DynamicImage;

fn average_ssim(pairs: Vec<(DynamicImage, DynamicImage)>) -> f64 {
    if pairs.is_empty() {
        return 0.0;
    }

    let mut total_ssim = 0.0;
    for (img1, img2) in pairs {
        let ssim = image_compare::ssim(img1, img2, image_compare::SsimOptions::default());
        total_ssim += ssim;
    }

    total_ssim / pairs.len() as f64
}

fn summarize(msg: &SyslogMessage) -> String {
    let timestamp = time::OffsetDateTime::from_unix_timestamp(msg.timestamp as i64)
        .unwrap()
        .format(time::format_description::well_known::Rfc3339)
        .to_string();
    let severity = match msg.severity {
        0 => "emerg",
        1 => "alert",
        2 => "crit",
        3 => "error",
        4 => "warning",
        5 => "notice",
        6 => "info",
        7 => "debug",
        _ => "unknown",
    };
    format!(
        "{} {} {} {} {}",
        timestamp, msg.hostname, msg.appname, severity, msg.message
    )
}

use jrsonnet_parser::{Expr, LiteralType};

fn extract_literal_value(expr: &Expr) -> Option<String> {
    match expr {
        Expr::Lit(lit) => {
            let value = match lit.ty {
                LiteralType::Null => "null".to_string(),
                LiteralType::Bool => {
                    if lit.val.is_true() {
                        "true".to_string()
                    } else {
                        "false".to_string()
                    }
                }
                LiteralType::Num => lit.val.to_string(),
                LiteralType::Str => lit.val.to_string(),
                _ => return None,
            };
            Some(value)
        }
        _ => None,
    }
}

#[proc_macro]
pub fn generate_dispatch_tests(input: TokenStream) -> TokenStream {
    let input = input.to_string();
    let env_def = parse_env_def(&input).unwrap();

    let mut tests = vec![];

    for func in &env_def.functions {
        if func.protocol_version == Some(Host::current_protocol_version()) {
            let test_name = format_ident!("test_dispatch_{}", func.name);
            let wasm_path = format!("wasm/{}.wasm", func.name);
            let args = generate_args(func);
            let host_func = format_ident!("{}", func.name);
            let test_code = quote! {
                #[test]
                fn #test_name() {
                    let host = Host::new();
                    let wasm = std::fs::read(#wasm_path).unwrap();
                    let module = host.load_wasm(&wasm).unwrap();
                    let instance = module.instantiate();
                    let args = #args;
                    let result = instance.invoke(#host_func, &args).unwrap();
                    assert!(result.is_ok());
                }
            };
            tests.push(test_code);
        }
    }

    quote! {
        #(#tests)*
    }
}

fn parse_env_def(input: &str) -> Result<EnvDef, ()> {
    let tokens: Vec<TokenTree> = input.parse().unwrap();
    let mut env_def = EnvDef::default();
    let mut i = 0;

    while i < tokens.len() {
        let token = &tokens[i];
        if let TokenTree::Ident(ident) = token {
            if ident.to_string() == "env_def" {
                i += 1;
                if i < tokens.len() {
                    if let TokenTree::Group(group) = &tokens[i] {
                        let mut group_tokens = group.tokens.clone().into_iter();
                        let mut func = FunctionDef::default();
                        while let Some(token) = group_tokens.next() {
                            if let TokenTree::Ident(ident) = token {
                                match ident.to_string().as_str() {
                                    "name" => {
                                        if let TokenTree::Ident(name) = group_tokens.next().unwrap() {
                                            func.name = name.to_string();
                                        }
                                    }
                                    "protocol_version" => {
                                        if let TokenTree::Ident(version) = group_tokens.next().unwrap() {
                                            func.protocol_version = Some(version.to_string().parse().unwrap());
                                        }
                                    }
                                    "args" => {
                                        let args_tokens: Vec<TokenTree> = group_tokens.collect();
                                        func.args = parse_args(&args_tokens);
                                    }
                                    _ => {}
                                }
                            }
                        }
                        env_def.functions.push(func);
                    }
                }
            }
        }
        i += 1;
    }

    Ok(env_def)
}

fn parse_args(tokens: &[TokenTree]) -> Vec<ArgDef> {
    let mut args = vec![];
    let mut i = 0;

    while i < tokens.len() {
        let token = &tokens[i];
        if let TokenTree::Ident(ident) = token {
            if ident.to_string() == "arg" {
                i += 1;
                let name_token = tokens[i].clone();
                let name = name_token.to_string();
                i += 1;
                let ty_token = tokens[i].clone();
                let ty = ty_token.to_string();
                i += 1;
                let default_token = tokens[i].clone();
                let default = match default_token {
                    TokenTree::Ident(ident) => ident.to_string(),
                    TokenTree::Literal(literal) => literal.to_string(),
                    _ => String::new(),
                };
                args.push(ArgDef { name, ty, default });
            }
        }
        i += 1;
    }

    args
}

fn generate_args(func: &FunctionDef) -> TokenStream {
    let mut args = vec![];
    for arg in &func.args {
        match arg.ty.as_str() {
            "u32" => {
                args.push(quote! { #arg.name: 42_u32 });
            }
            "u64" => {
                args.push(quote! { #arg.name: 42_u64 });
            }
            "i32" => {
                args.push(quote! { #arg.name: 42_i32 });
            }
            "i64" => {
                args.push(quote! { #arg.name: 42_i64 });
            }
            "bool" => {
                args.push(quote! { #arg.name: true });
            }
            "String" => {
                args.push(quote! { #arg.name: String::from("test") });
            }
            "HostVec" => {
                args.push(quote! { #arg.name: HostVec::new() });
            }
            _ => {
                args.push(quote! { #arg.name: #arg.default });
            }
        }
    }

fn aggregate_discover_results<S>(
    nodes: &[PeerId],
    namespace: Namespace,
    limit: Option<u64>,
    client: &mut client::Behaviour,
    mut events: S,
) -> Result<Vec<Registration>, client::RegisterError>
where
    S: futures::stream::Stream<Item = client::Event> + Unpin,
{
    let mut results = Vec::new();
    let mut pending_requests = nodes.iter().map(|&node| {
        let namespace = namespace.clone();
        let limit = limit.clone();
        async move {
            let mut request = client::Request::new(namespace, limit);
            client.send_request(node, request).await?;
            Ok(())
        }
    });

    while let Some(event) = events.next().await {
        match event {
            client::Event::Discovered { registration, .. } => {
                results.push(registration);
            }
            client::Event::RequestFailed { error, .. } => {
                return Err(error);
            }
            _ => {}
        }
    }

    Ok(results)
}

fn sign_sd_jwt_conceal_subject<S>(vc: ssi_vc::v2::JsonCredential, signer: S) -> Result<ssi_vc::enveloped::EnvelopedVerifiableCredential, ssi_jws::SignatureError>
where
    S: ssi_jws::JwsSigner,
{
    let json_pointer = json_pointer::from_string("/credentialSubject/id").unwrap();
    let sd_jwt_vc = SdJwtVc::from_json_vc(&vc, vec![json_pointer]).unwrap();
    let signed_jwt = signer.sign(sd_jwt_vc.to_bytes(), SdAlg::ES256).unwrap();
    let enveloped_vc = EnvelopedVerifiableCredential::new(signed_jwt.to_string());
    Ok(enveloped_vc)
}

use crate::{Digest32, blake2b256_hash};

fn calculate_merkle_root(transactions: &[Digest32]) -> Digest32 {
    let mut current_level = transactions.to_vec();

    while current_level.len() > 1 {
        let mut next_level = Vec::new();
        for chunk in current_level.chunks(2) {
            let mut hash = Digest32::default();
            if chunk.len() == 1 {
                hash = *chunk[0];
            } else {
                hash = blake2b256_hash(chunk[0], chunk[1]);
            }
            next_level.push(hash);
        }
        current_level = next_level;
    }

    current_level[0]
}

