fn variant_to_json_value(variant: &Variant) -> Result<Value, ArrowError> {
    match variant {
        Variant::Null => Ok(Value::Null),
        Variant::Bool(b) => Ok(Value::Bool(*b)),
        Variant::I8(i) => Ok(Value::Number((*i).into())),
        Variant::I16(i) => Ok(Value::Number((*i).into())),
        Variant::I32(i) => Ok(Value::Number((*i).into())),
        Variant::I64(i) => Ok(Value::Number((*i).into())),
        Variant::U8(u) => Ok(Value::Number((*u).into())),
        Variant::U16(u) => Ok(Value::Number((*u).into())),
        Variant::U32(u) => Ok(Value::Number((*u).into())),
        Variant::U64(u) => Ok(Value::Number((*u).into())),
        Variant::F32(f) => Ok(Value::Number((*f).into())),
        Variant::F64(f) => Ok(Value::Number((*f).into())),
        Variant::Decimal(d) => {
            let s = d.to_string();
            Ok(Value::String(s))
        }
        Variant::Date(d) => {
            let date = NaiveDate::from_timestamp_opt(*d as i64, 0).ok_or(ArrowError::Invalid)?; // Assuming d is in seconds since epoch
            Ok(Value::String(date.to_string()))
        }
        Variant::Timestamp(t) => {
            let datetime = DateTime::<Utc>::from_timestamp_opt(*t as i64, 0).ok_or(ArrowError::Invalid)?; // Assuming t is in seconds since epoch
            Ok(Value::String(datetime.to_rfc3339()))
        }
        Variant::Binary(b) => {
            let decoded = base64::decode(b).map_err(|e| ArrowError::Invalid)?;
            Ok(Value::Bytes(decoded))
        }
        Variant::String(s) => Ok(Value::String(s.clone())),
        Variant::List(l) => {
            let mut json_list = Vec::new();
            for item in l {
                json_list.push(variant_to_json_value(item)?);
            }
            Ok(Value::Array(json_list))
        }
        Variant::Map(m) => {
            let mut json_map = serde_json::Map::new();
            for (k, v) in m {
                json_map.insert(k.clone(), variant_to_json_value(v)?);
            }
            Ok(Value::Object(json_map))
        }
        Variant::Struct(s) => {
            let mut json_map = serde_json::Map::new();
            for (k, v) in s {
                json_map.insert(k.clone(), variant_to_json_value(v)?);
            }
            Ok(Value::Object(json_map))
        }
        Variant::Union(u) => {
            let (field_index, value) = u;
            let json_value = variant_to_json_value(value)?;
            Ok(Value::Object(serde_json::Map::from_iter([(format!("field_{}", field_index), json_value)])))
        }
        _ => Err(ArrowError::Invalid),
    }
}

use std::sync::Arc;
use arrow::array::{ArrayRef, StringArray, Int32Array};
use arrow::datatypes::Int32Type;
use datafusion_common::{Result, exec_err, DataFusionError};
use datafusion_expr::{ColumnarValue, ScalarValue};
use crate::function::hash::sha2::compute_sha2;

fn variable_sha2(args: [ColumnarValue; 2]) -> Result<ColumnarValue, DataFusionError> {
    let input_strings = match &args[0] {
        ColumnarValue::Array(array) => array,
        _ => return exec_err!("First argument must be an array of strings"),
    };

    let bit_lengths = match &args[1] {
        ColumnarValue::Array(array) => array,
        _ => return exec_err!("Second argument must be an array of integers"),
    };

    if input_strings.len() != bit_lengths.len() {
        return exec_err!("Arrays must have the same length");
    }

    let string_array = input_strings.as_any().downcast_ref::<StringArray>().ok_or_else(|| {
        exec_err!("First argument must be a StringArray")
    })?;

    let int_array = bit_lengths.as_any().downcast_ref::<Int32Array>().ok_or_else(|| {
        exec_err!("Second argument must be an Int32Array")
    })?;

    let mut result = vec![];
    for i in 0..string_array.len() {
        if string_array.is_null(i) || int_array.is_null(i) {
            result.push(None);
            continue;
        }

        let input = string_array.value(i);
        let bit_length = int_array.value(i) as u32;

        if bit_length != 256 && bit_length != 512 {
            return exec_err!("Bit length must be 256 or 512");
        }

        let hash = compute_sha2(&input, bit_length);
        result.push(Some(hash));
    }

    Ok(Arc::new(StringArray::from(result)) as ArrayRef)
}

fn select_optimal_gateway(&self, invoice: &Bolt11Invoice) -> Result<(SafeUrl, RoutingInfo), SelectGatewayError> {
    // Check if the invoice has a gateway that created it
    if let Some(gateway_key) = invoice.payment_secret().map(|ps| GatewayKey::from_payment_secret(ps)) {
        if let Some(gateway) = self.get_gateway(&gateway_key) {
            return Ok((gateway.url.clone(), gateway.routing_info.clone()));
        }
    }

    // If no matching gateway, select a random vetted gateway
    let vetted_gateways = self.list_vetted_gateways()?;
    if vetted_gateways.is_empty() {
        return Err(SelectGatewayError::NoVettedGateways);
    }

    let mut rng = rand::thread_rng();
    let selected = vetted_gateways.choose(&mut rng).ok_or(SelectGatewayError::NoVettedGateways)?;
    let routing_info = self.get_routing_info(&selected.url).map_err(|e| SelectGatewayError::FailedToFetchRoutingInfo(e.to_string()))?;
    Ok((selected.url.clone(), routing_info))
}

fn get_gateway(&self, gateway_key: &GatewayKey) -> Option<&LightningFederationApi> {
    self.gateways.get(gateway_key)
}

fn list_vetted_gateways(&self) -> Result<Vec<LightningFederationApi>, String> {
    let gateways: Vec<_> = self.gateways.values().filter(|g| g.is_vetted()).collect();
    if gateways.is_empty() {
        Err("No vetted gateways available".to_string())
    } else {
        Ok(gateways)
    }
}

fn get_routing_info(&self, url: &SafeUrl) -> Result<RoutingInfo, String> {
