}

use near_indexer_primitives::IndexerChunkView;

fn summarize_block_stats(chunks: &[IndexerChunkView]) -> (usize, f64) {
    let mut total_transactions = 0;
    let mut total_gas_used = 0;

    for chunk in chunks {
        if let Some(chunk) = chunk {
            total_transactions += chunk.transactions.len();
            total_gas_used += chunk.total_gas_used;
        }
    }

    let average_gas = if total_transactions > 0 {
        total_gas_used as f64 / total_transactions as f64
    } else {
        0.0
    };

    (total_transactions, average_gas)
}

fn transform_subtrie_values<K, V, F>(trie: &mut Trie<K, V>, prefix: &K, mut func: F)
where
    K: TrieKey + Clone,
    V: Clone,
    F: Fn(&mut V),
{
    if let Some(subtrie) = trie.get_subtrie_mut(prefix) {
        let mut keys = Vec::new();
        subtrie.iter().for_each(|(key, _)| keys.push(key.clone()));
        for key in keys {
            if let Some(value) = trie.get_mut(&key) {
                func(value);
            }
        }
    }
}

use any_spawner::Executor;
use std::future::Future;
use std::sync::{Arc, atomic::{AtomicUsize, Ordering}, Mutex};
use futures::channel::oneshot;

fn spawn_batch<T>(futs: Vec<impl Future<Output = T> + Send + 'static>) -> oneshot::Receiver<()> {
    let (tx, rx) = oneshot::channel();
    let count = futs.len();
    let done = Arc::new(AtomicUsize::new(0));
    let done_clone = Arc::clone(&done);
    let executor = Executor::new();

    for fut in futs {
        let done_clone = Arc::clone(&done_clone);
        let tx = tx.clone();
        let fut = fut.boxed();
        executor.spawn(async move {
            fut.await;
            done_clone.fetch_add(1, Ordering::Relaxed);
            if done_clone.load(Ordering::Relaxed) == count {
                tx.send(()).unwrap();
            }
        });
    }

    rx
}

use lazy_regex::regex_switch;

#[derive(Debug, PartialEq)]
enum ScrollCommand {
    ScrollLines(usize),
    JumpTo(String),
    Unknown,
}

fn parse_scroll_command(s: &str) -> Result<ScrollCommand, &'static str> {
    let result = regex_switch!(s => {
        "scroll-lines(\\d+)" => {
            let count = std::str::from_utf8(&s.as_bytes()[13..]).unwrap().parse::<usize>().unwrap();
            ScrollCommand::ScrollLines(count)
        },
        "jump-to(\\w+)" => {
            let target = std::str::from_utf8(&s.as_bytes()[9..]).unwrap();
            ScrollCommand::JumpTo(target.to_string())
        },
        _ => ScrollCommand::Unknown,
    });

    match result {
        ScrollCommand::Unknown => Err("Invalid scroll command"),
        _ => Ok(result),
    }
}

