use fax::{decoder, decoder::pels, VecWriter, Bits, Color};
use std::fs;
use std::io::BufReader;

fn validate_fax_against_pbm(fax_path: &str, pbm_path: &str) -> Result<bool, Box<dyn std::error::Error>> {
    // Read PBM file
    let pbm_data = fs::read_to_string(pbm_path)?;
    let pbm_lines: Vec<&str> = pbm_data.lines().collect();

    // Parse PBM header to get width and height
    let width = parse_pbm_width(&pbm_lines)?;
    let height = parse_pbm_height(&pbm_lines)?;

    // Read and decode fax file
    let fax_data = fs::read(fax_path)?;
    let mut decoder = decoder::Decoder::new(&fax_data);
    let mut lines = Vec::new();
    let mut current_line = Vec::new();

    // Decode fax data into pixel lines
    while let Some(pel) = decoder.next() {
        current_line.push(pel);
        if current_line.len() == width {
            lines.push(current_line.clone());
            current_line.clear();
        }
    }

    // Compare each line with the reference PBM
    for (line_idx, line) in lines.iter().enumerate() {
        if line_idx >= height {
            return Err("Fax file has more lines than PBM image".into());
        }
        if line.len() != width {
            return Err("Line width mismatch".into());
        }

        let pbm_line = &pbm_lines[line_idx + 1]; // Skip the header line
        let pbm_line = pbm_line.trim();
        let pbm_line = pbm_line.split_whitespace().collect::<Vec<&str>>();

        if pbm_line.len() != width {
            return Err("PBm line width mismatch".into());
        }

        for (pixel_idx, pel) in line.iter().enumerate() {
            let pbm_pixel = pbm_line[pixel_idx];
            if pbm_pixel != "0" && pbm_pixel != "1" {
                return Err("Invalid pixel value in PBM".into());
            }
            let pbm_pixel = pbm_pixel.parse::<u8>().unwrap();
            if *pel != pbm_pixel {
                return Err(format!("Mismatch at line {}, pixel {} (fax: {}, pbm: {})", line_idx, pixel_idx, pel, pbm_pixel).into());
            }
        }
    }

    Ok(true)
}

fn parse_pbm_width(lines: &[&str]) -> Result<usize, Box<dyn std::error::Error>> {
    let header_line = lines[0];
    if !header_line.starts_with("P1") {
        return Err("Invalid PBM format".into());
    }
    let mut parts = header_line.split_whitespace();
    parts.next(); // Skip 'P1'
    let width = parts.next().ok_or("Missing width in PBM header")?;
    Ok(width.parse::<usize>().map_err(|e| e.to_string().into()))
}

fn parse_pbm_height(lines: &[&str]) -> Result<usize, Box<dyn std::error::Error>> {
    let header_line = lines[0];
    if !header_line.starts_with("P1") {
        return Err("Invalid PBM format".into());
    }
    let mut parts = header_line.split_whitespace();
    parts.next(); // Skip 'P1'
    parts.next(); // Skip width
    let height = parts.next().ok_or("Missing height in PBM header")?;
    Ok(height.parse::<usize>().map_err(|e| e.to_string().into()))
}

fn format_testament(testament: &GitTestament<'_>, trusted_branch: Option<&'static str>) -> String {
    let branch = testament.branch().unwrap_or("<no branch>");
    let commit = if testament.is_clean() {
        if let Some(trust_branch) = trusted_branch {
            if branch == trust_branch {
                "crate version".to_string()
            } else {
                testament.commit().unwrap_or("unknown")
            }
        } else {
            testament.commit().unwrap_or("unknown")
        }
    } else {
        "dirty".to_string()
    };
    let tag = testament.tag().unwrap_or("none");
    let kind = match testament.commit_kind() {
        CommitKind::Commit => "commit",
        CommitKind::Tag => "tag",
        CommitKind::Tree => "tree",
    };
    format!("{} ({}) [{}]", branch, commit, tag, kind)
}

