fn upsert_rows(storage: &MongoStorage, table_name: &str, rows: Vec<(Key, DataRow)>) -> Result<()> {
    let collection = storage.collection(table_name)?;
    let primary_key = get_primary_key(table_name)?;

    for (key, row) in rows {
        let document: Document = row.into_bson()?;
        let filter = doc! { primary_key: key };
        let options = ReplaceOptions::builder()
            .upsert(true)
            .build();

        collection.replace_one(filter, document, options)?;
    }

    Ok(())
}

