use simd_json::borrowed::Value;

fn parse_log_line(line: &str) -> Result<Value, Error> {
    let pattern = Pattern::compile("timestamp:datetime[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z padding:padding port:uint32")?;
    let result = pattern.run(line)?;
    Ok(result)
}

fn extract_statuses(html: &str) -> Vec<Status> {
    let document = Html::parse_document(html);
    let mut statuses = Vec::new();

    let link_selector = Selector::parse("a").unwrap();
    for node in document.select(&link_selector) {
        if let Some(link_status) = node
            .get_attribute("status")
            .and_then(|status| match status.as_str() {
                "active" => Some(Status::Active),
                "inactive" => Some(Status::Inactive),
                _ => Some(Status::Unknown),
            })
        {
            statuses.push(link_status);
        }
    }

    statuses
}

