fn search_positions_by_token_and_pnl(
    db: &Database,
    token_name: &str,
    min_pnl: Decimal,
    max_pnl: Decimal,
    limit: Option<u32>,
    ascending: bool,
) -> Result<Vec<PositionLog>, Box<dyn std::error::Error>> {
    let collection = db.collection("position_logs");

    let mut find_options = FindOptions::default();
    find_options.limit(limit);
    find_options.sort(doc! { "open_timestamp": if ascending { 1 } else { -1 } });

    let pipeline = vec![
        doc! {
            "$match": {
                "token_name": token_name,
                "pnl": { "$gte": min_pnl, "$lte": max_pnl }
            }
        },
        doc! {
            "$sort": {
                "open_timestamp": if ascending { 1 } else { -1 }
            }
        },
    ];

    let mut results = Vec::new();
    let mut cursor = collection.aggregate(pipeline, None)?;
    while let Some(result) = cursor.next().await {
        let position = result?;
        results.push(position);
    }

    Ok(results)
}

use fuel_crypto::SecretKey;
