fn generate_wallet_address_from_counter(counter: u64) -> Address {
    // Convert the counter to bytes
    let mut counter_bytes = counter.to_le_bytes();

    // Derive a deterministic secret key from the counter
    let secret_key = SecretKey::from_bytes(&counter_bytes);

    // Derive the wallet address from the secret key
    let address = secret_key.to_address();

    address
}

use crate::Context;
use crate::Program;
use crate::Shader;
use crate::Enum;
use crate::VERTEX_SHADER;
use crate::FRAGMENT_SHADER;
use crate::COMPILE_STATUS;
use crate::LINK_STATUS;

fn create_shader_program(context: &Context, vertex_src: &str, fragment_src: &str) -> Option<Program> {
    let vertex_shader = Shader::new(context, vertex_src, VERTEX_SHADER);
    let fragment_shader = Shader::new(context, fragment_src, FRAGMENT_SHADER);

    if vertex_shader.is_err() || fragment_shader.is_err() {
        return None;
    }

    let vertex_shader = vertex_shader.unwrap();
    let fragment_shader = fragment_shader.unwrap();

    if !vertex_shader.get_status(COMPILE_STATUS) || !fragment_shader.get_status(COMPILE_STATUS) {
        let vertex_log = vertex_shader.get_info_log();
        let fragment_log = fragment_shader.get_info_log();
        eprintln!("Vertex shader compilation failed: {}", vertex_log);
        eprintln!("Fragment shader compilation failed: {}", fragment_log);
        return None;
    }

    let program = Program::new(context);
    if program.is_err() {
        return None;
    }

    let program = program.unwrap();
    program.attach_shader(&vertex_shader);
    program.attach_shader(&fragment_shader);

    if !program.link() {
        let log = program.get_info_log();
        eprintln!("Shader program linking failed: {}", log);
        return None;
    }

    if !program.get_status(LINK_STATUS) {
        let log = program.get_info_log();
        eprintln!("Shader program linking failed: {}", log);
        return None;
    }

    Some(program)
}

use libp2p_mdns::Event;
use libp2p_core::Multiaddr;
use libp2p_identity::PeerId;
use std::collections::HashMap;
use std::time::{Instant, Duration};

fn manage_peer_expiry(events: Vec<Event>, ttl_duration: Duration) -> Vec<(PeerId, Multiaddr)> {
    let mut peer_last_seen = HashMap::new();
    let mut active_peers = HashMap::new();

    for event in events {
        match event {
            Event::Found(peer_id, addr) => {
                if let Some(last_seen) = peer_last_seen.get_mut(&peer_id) {
                    *last_seen = Instant::now();
                } else {
                    peer_last_seen.insert(peer_id, Instant::now());
                }
                active_peers.insert(peer_id, addr);
            }
            Event::Expired(peer_id) => {
                peer_last_seen.remove(&peer_id);
                active_peers.remove(&peer_id);
            }
            _ => {}
        }
    }

    let current_time = Instant::now();
    let mut result = Vec::new();

    for (peer_id, addr) in &active_peers {
        if current_time.duration_since(peer_last_seen[peer_id]) > ttl_duration {
            continue;
        }
        result.push((*peer_id, addr.clone()));
    }

    result
}

use crt0stack::{Builder, Entry, Handle, OutOfSpace};

fn create_minimal_stack<'a>(stack: &'a mut [u8], exec: &'a str, uid: usize, gid: usize) -> core::result::Result<Handle<'a>, OutOfSpace> {
    let mut builder = Builder::new(stack);

    // Add executable name
    if let Err(_) = builder.add_entry(Entry::ExecName(exec)) {
        return Err(OutOfSpace);
    }

    // Add UID
    if let Err(_) = builder.add_entry(Entry::Uid(uid)) {
        return Err(OutOfSpace);
    }

    // Add GID
    if let Err(_) = builder.add_entry(Entry::Gid(gid)) {
        return Err(OutOfSpace);
    }

    // Add platform
    if let Err(_) = builder.add_entry(Entry::Platform("unknown".as_ref())) {
        return Err(OutOfSpace);
    }

    Ok(builder.build())
}

fn frame_size_in_bytes(picture: &dav1d::Picture) -> usize {
    let mut total_size = 0;
    for component in &picture.components {
        let plane = match component {
            PlanarImageComponent::Y => 0,
            PlanarImageComponent::U => 1,
            PlanarImageComponent::V => 2,
        };
        let stride = picture.stride[plane];
        let height = picture.height[plane];
        total_size += stride * height;
    }
    total_size
}

