fn handle_intercepted_htlc(module: &GatewayClientModule, htlc: Htlc) -> Result<OperationId> {
    // Create the incoming contract output
    let output = ClientOutput::Lightning(LightningOutput::new(
        htlc.contract.outpoint,
        htlc.contract.payment_hash,
        htlc.contract.payment_secret,
    ));

    // Build the transaction bundle
    let mut builder = TransactionBuilder::new();
    builder.add_output(output);
    let bundle = ClientOutputBundle::new(builder.build()?, OutPointRange::new(0, 0));

    // Submit the transaction to the federation
    let operation_id = module.submit_transaction(bundle)?;

    // Log the start of the incoming payment
    module.log_event(IncomingPaymentStarted {
        operation_id,
        payment_hash: htlc.contract.payment_hash,
    });

    Ok(operation_id)
}

