fn bresenham_line_length<T>(start: Point<T>, end: Point<T>) -> f64
where
    T: SignedNum + Into<f64> + Copy,
{
    let mut length = 0.0;
    let mut prev = start;
    for point in Bresenham::new(start, end) {
        let dx = (point.x - prev.x).into();
        let dy = (point.y - prev.y).into();
        let dist = (dx.powi(2) + dy.powi(2)).sqrt();
        length += dist;
        prev = point;
    }
    length
}

fn get_current_versionstamp(&self) -> anyhow::Result<[u8; 10]> {
    let config = get_config()?;
    let value = config.get(TT_CONFIG_KEY_CURRENT_SNAPSHOT_VERSIONSTAMP12).ok_or(anyhow::anyhow!("Missing current snapshot versionstamp in config"))?;

    if value.len() != 20 {
        return Err(anyhow::anyhow!("Invalid length for versionstamp hex string"));
    }

    let bytes: [u8; 10] = hex::decode(value)
        .map_err(|e| anyhow::anyhow!("Failed to decode hex string: {}", e))?
        .try_into()
        .map_err(|e| anyhow::anyhow!("Failed to convert hex bytes to fixed-size array: {}", e))?;

    Ok(bytes)
}

fn format_datetime_with_timezone(
    date: icu::calendar::Date,
    time: icu::time::Time,
    tz: icu::time::TimeZoneInfo<icu::time::zone::models::Full>,
    locale: icu::locale::Locale,
) -> String {
    let zoned_date_time = ZonedDateTime::new(date, time, tz);
    let formatter = DateTimeFormatter::try_new_with_datetime_fieldset(
        locale,
        fieldsets::datetime::medium,
    )
    .expect("Failed to create DateTimeFormatter");
    formatter.format(&zoned_date_time).to_string()
}

fn hash_multiple(params: &umash_params, seed: u64, inputs: &[&[u8]]) -> Vec<u64> {
    let mut state = umash_state { /* initialize as needed */ };
    let mut results = Vec::new();

    for input in inputs {
        unsafe {
            umash_init(&mut state, params, seed, 0);
            umash_sink_update(&mut state, input.as_ptr() as _, input.len() as _);
            results.push(umash_digest(&state));
        }
    }

    results
}

fn protobuf_stream_with_buffering() -> impl IntoResponse {
    async_stream::stream! {
        let mut buffer = Vec::new();
        for i in 0..100 {
            let item = format!("item_{}", i);
            buffer.push(item);
            if buffer.len() == 10 {
                let chunk = buffer.clone();
                buffer.clear();
                yield chunk;
            }
        }
        if !buffer.is_empty() {
            yield buffer;
        }
    }
    .map(|chunk| {
        let mut stream_body = StreamBodyAs::new(chunk.into_iter().map(|s| s.into_bytes()));
        stream_body.options = StreamBodyAsOptions {
            format: ProtobufStreamFormat,
            ..Default::default()
        };
        stream_body
    })
    .into_response()
}

