use solana_tpu_client::tpu_client::TpuClient;
use solana_transaction::Transaction;
use solana_transaction_error::TransportResult;
use std::time::Duration;
use tokio::time::sleep;
use bincode;

fn send_transaction_batch_with_retry(
    &self,
    transactions: &[Transaction],
    max_retries: usize,
    base_delay: Duration,
) -> TransportResult<()> {
    let mut retry_count = 0;
    loop {
        match self.send_transactions(transactions) {
            Ok(_) => return Ok(()),
            Err(err) => {
                if retry_count >= max_retries {
                    return Err(err);
                }
                retry_count += 1;
                let delay = base_delay * (1 << retry_count); // Exponential backoff
                sleep(delay).await.unwrap();
            }
        }
    }
}

use libdeflater::{Compressor, CompressionLvl, crc32, adler32};
use std::error::Error;

fn compress_with_checksums<T: AsRef<[u8]>>(data: T) -> Result<(Vec<u8>, u32, u32), Box<dyn Error>> {
    let mut compressor = Compressor::new(CompressionLvl::Fast);
    let mut compressed_data = Vec::new();
    let mut crc32_checksum = 0;
    let mut adler32_checksum = 0;

    compressor.write(data.as_ref(), &mut compressed_data)?;
    compressor.finish(&mut compressed_data)?;

    crc32_checksum = crc32(&compressed_data);
    adler32_checksum = adler32(&compressed_data);

    Ok((compressed_data, crc32_checksum, adler32_checksum))
}

use async_graphql_parser::{types as ast, Positioned};
use crate::Context;

fn all_enum_values<'a>(ctx: &Context<'a>, enum_name: &str) -> Vec<Positioned<ast::EnumValueDefinition>> {
    let mut result = Vec::new();
    let enum_def = ctx.enum_type(enum_name).unwrap();

    // Collect values from the original enum definition
    for value in &enum_def.values {
        result.push(value.clone());
    }

    // Collect values from extensions
    if let Some(extensions) = &enum_def.extensions {
        for extension in extensions {
            if let Some(enum_extension) = extension.enum_extension() {
                for value in &enum_extension.values {
                    result.push(value.clone());
                }
            }
        }
    }

    result
}

fn payment_report(&self, operation_id: OperationId) -> anyhow::Result<PaymentReport> {
    let mut state_machine = self.state_machines().get(&operation_id).ok_or_else(|| {
        anyhow::anyhow!("OperationId {} not found", operation_id)
    })?;

    let mut outcome = None;
    let mut amount = None;
    let mut preimage = None;
    let mut is_incoming = false;

    while let Some(event) = state_machine.next().await {
        match event {
            GatewayClientStateMachines::IncomingSm(IncomingSmStates::Success(preimage)) => {
                is_incoming = true;
                preimage = Some(preimage.clone());
                outcome = Some("success".to_string());
            }
            GatewayClientStateMachines::IncomingSm(IncomingSmStates::Failed) => {
                outcome = Some("failed".to_string());
            }
            GatewayClientStateMachines::GatewayPay(GatewayPayStates::Success(amount)) => {
                outcome = Some("success".to_string());
                amount = Some(*amount);
            }
            GatewayClientStateMachines::GatewayPay(GatewayPayStates::Failed) => {
                outcome = Some("failed".to_string());
            }
            GatewayClientStateMachines::GatewayComplete(GatewayCompleteStates::Success) => {
                outcome = Some("success".to_string());
            }
            GatewayClientStateMachines::GatewayComplete(GatewayCompleteStates::Failed) => {
                outcome = Some("failed".to_string());
            }
            _ => {}
        }
    }

    let outcome = outcome.ok_or_else(|| anyhow::anyhow!("No outcome found for operation {}", operation_id))?;
    let amount = amount.ok_or_else(|| anyhow::anyhow!("No amount found for operation {}", operation_id))?;

    Ok(PaymentReport {
        operation_id,
        outcome,
        amount,
        preimage,
        is_incoming,
    })
}

fn validate_outgoing_contract_expiration<T: ?Sized>(api: &T, outpoint: OutPoint) -> Result<(), anyhow::Error>
where
    T: GatewayFederationApi,
{
    let contract = api.get_outgoing_contract(outpoint)?;
    let expiration = contract.expiration;

    if expiration.is_none() {
        return Err(anyhow!("Contract is missing an expiration date"));
    }

    let current_time = now();
    let expiration_time = expiration.unwrap();

    if current_time >= expiration_time {
        return Err(anyhow!("Contract has expired"));
    }

    Ok(())
}

fn record_query_preparation_latency_with_cache(
    &self,
    operation: Option<GraphqlOperationAttributes>,
    duration: Duration,
    cache_status: &str,
) {
    let mut metrics = self.metrics.lock().unwrap();
    let mut attributes = Vec::new();

    if let Some(op) = operation {
        attributes.push(KeyValue::new("operation_name", op.name));
        attributes.push(KeyValue::new("operation_type", op.operation_type));
    }

    attributes.push(KeyValue::new("cache_status", cache_status));
    attributes.push(KeyValue::new("duration_seconds", duration.as_secs_f64()));

    metrics.observe_query_preparation_latency(attributes);
}

