use crate::metadata::HookInfo;
use syn::{self, visit::Visit};

fn collect_hooks(file_content: &str) -> Vec<HookInfo> {
    let file_content = file_content.to_string();
    let mut hook_info = Vec::new();
    let mut visitor = HookVisitor { hook_info: &mut hook_info };
    let file = syn::parse_file(&file_content).expect("Failed to parse RSX file");
    visitor.visit_file(&file);
    hook_info
}

struct HookVisitor {
    hook_info: &mut Vec<HookInfo>,
}

impl Visit for HookVisitor {
    fn visit_expr(&mut self, expr: &syn::Expr) {
        if let syn::Expr::Call(ref call) = expr {
            if let syn::Expr::Path(ref path) = &*call.func {
                if let Some(seg) = path.segments.last() {
                    if seg.ident == "use_hook" {
                        let hook_name = seg.ident.to_string();
                        self.hook_info.push(HookInfo {
                            name: hook_name,
                            file_path: String::new(), // Assuming file path is not provided, can be extended if needed
                            line_number: 0, // Line number not parsed here, would require more context
                        });
                    }
                }
            }
        }
        syn::visit::visit_expr(self, expr);
    }
}

