impl<H> Handler for PowerHeaderMiddleware<H>
where
    H: Handler,
{
    fn handle(&self, req: Request) -> Result<Response, Box<dyn Error + Send + Sync>> {
        let mut res = self.handler.handle(req)?;
        res.headers.insert("X-Powered-By".to_string(), "civet".to_string());
        Ok(res)
    }
