use toml::Value;

#[derive(Debug, Clone)]
pub struct Args {
    pub chain: String,
    pub network: String,
    pub data_dir: String,
    pub rpc_url: String,
    pub max_txs: usize,
}

fn substitute_placeholders(template: &str, args: &Args) -> String {
    let mut result = String::new();
    let mut i = 0;
    while i < template.len() {
        if template.chars().nth(i) == Some('{') {
            let start = i;
            let mut depth = 1;
            let mut j = i + 1;
            while j < template.len() {
                if template.chars().nth(j) == Some('{') {
                    depth += 1;
                } else if template.chars().nth(j) == Some('}') {
                    depth -= 1;
                    if depth == 0 {
                        let placeholder = &template[start + 1..j];
                        let value = match placeholder {
                            "chain" => &args.chain,
                            "network" => &args.network,
                            "data_dir" => &args.data_dir,
                            "rpc_url" => &args.rpc_url,
                            "max_txs" => &args.max_txs.to_string(),
                            _ => "",
                        };
                        result.push_str(value);
                        i = j + 1;
                        break;
                    }
                }
                j += 1;
            }
            if depth != 0 {
                // Malformed placeholder, leave as is
                result.push_str(&template[i..]);
                break;
            }
        } else {
            result.push(template.chars().nth(i).unwrap());
            i += 1;
        }
    }
    result
}

fn parse_and_render(template: &str, args: &Args) -> Result<String, toml::ser::Error> {
    let substituted = substitute_placeholders(template, args);
    let value: Value = toml::from_str(&substituted)?;
    Ok(toml::to_string(&value)?)
}

pub fn render_config(template: &str, args: &Args) -> String {
    parse_and_render(template, args).unwrap_or_default()
}

