use fedimint_lnv2_common::contracts::IncomingContract;
use std::collections::BTreeMap;
use tpe::{AggregatePublicKey, DecryptionKeyShare, aggregate_dk_shares};

fn decrypt_preimage(
    contract: &IncomingContract,
    shares: BTreeMap<u64, DecryptionKeyShare>,
    tpe_agg_pk: AggregatePublicKey,
) -> Result<[u8; 32], String> {
    // Aggregate decryption key shares
    let aggregated_key = aggregate_dk_shares(&shares)?;

    // Validate aggregated key against the TPE aggregate public key
    if aggregated_key != tpe_agg_pk {
        return Err("Aggregated decryption key does not match TPE aggregate public key".to_string());
    }

    // Decrypt the preimage using the aggregated key
    let preimage = contract.decrypt_preimage(&aggregated_key)?;

    Ok(preimage)
}

use ezk_ice::{IceAgent, Component};
