fn all_discovered_pairs(agent: &IceAgent) -> Vec<(Component, SocketAddr, SocketAddr)> {
    let mut result = Vec::new();
    for component in agent.components() {
        if let Some(local_address) = component.local_address() {
            if let Some(remote_address) = component.remote_address() {
                result.push((component, local_address, remote_address));
            }
        }
    }
    result
}

