    let call_price = call(stock, strike, rate, sigma, maturity);
    let put_price = put(stock, strike, rate, sigma, maturity);
    let call_delta = call_delta(stock, strike, rate, sigma, maturity);
    let put_delta = put_delta(stock, strike, rate, sigma, maturity);
    let call_gamma = call_gamma(stock, strike, rate, sigma, maturity);
    let put_gamma = put_gamma(stock, strike, rate, sigma, maturity);
    let call_theta = call_theta(stock, strike, rate, sigma, maturity);
    let put_theta = put_theta(stock, strike, rate, sigma, maturity);
    let call_vega = call_vega(stock, strike, rate, sigma, maturity);
    let put_vega = put_vega(stock, strike, rate, sigma, maturity);

    OptionData {
        call_price,
        put_price,
        call_delta,
        put_delta,
        call_gamma,
        put_gamma,
        call_theta,
        put_theta,
        call_vega,
        put_vega,
