}

use anyhow::Result;
use fedimint_core::Feerate;
use crate::bitcoin_rpc::ServerBitcoinRpcMonitor;

fn average_feerate(monitor: &ServerBitcoinRpcMonitor, blocks: u64) -> Result<Feerate> {
    let mut total_feerate = Feerate::zero();
    let mut block_count = 0;

    for i in 0..blocks {
        let block_height = monitor.get_block_height() - i as u64;
        if block_height < monitor.get_block_height() - 1000 {
            let feerate = monitor.get_feerate(block_height).unwrap_or(Feerate::zero());
            total_feerate += feerate;
            block_count += 1;
        }
    }

    if block_count == 0 {
        return Err(anyhow::anyhow!("No valid fee rates found in the specified block range"));
    }

    Ok(total_feerate / block_count)
}

