fn check_plugin_compatibility(
    plugin_manager: &Arc<RwLock<GeyserPluginManager>>,
    required_version: &str,
) -> Result<(), String> {
    let manager = plugin_manager.read().map_err(|e| e.to_string())?;
    let plugins = manager.get_loaded_plugins();

    for plugin in plugins {
        let version_str = plugin.get_version();
        let version = Version::parse(version_str).map_err(|e| format!("Invalid version string: {}", e))?;

        let required_version = Version::parse(required_version).map_err(|e| format!("Invalid required version: {}", e))?;

        if version < required_version {
            return Err(format!("Plugin {} is incompatible: version {} is less than required {}", plugin.name(), version_str, required_version));
        }
    }

    Ok(())
}

fn safe_decode_varint<R: std::io::Read>(reader: &mut R) -> Result<u64, String> {
    let mut result = 0;
    let mut bytes_read = 0;
    let mut byte: u8;

    loop {
        byte = match reader.read_byte() {
            Ok(b) => b,
            Err(_) => return Err("Failed to read byte from input stream".to_string()),
        };

        result = (result as u64) | ((byte & 0x7F) as u64);
        bytes_read += 1;

        if (byte & 0x80) == 0 {
            break;
        }

        if bytes_read > 10 {
            return Err("Varint exceeds maximum allowed length of 10 bytes".to_string());
        }
    }

    Ok(result)
}

