use alloc::collections::BTreeMap;
use risc0_binfmt::{MemoryImage, Page, ByteAddr, WordAddr};

fn memory_image_from_words(words: BTreeMap<u32, u32>) -> MemoryImage {
    let mut image = MemoryImage::new();
    let mut pages = BTreeMap::new();
    let mut current_page = Page::new();
    let mut current_addr = ByteAddr(0);

    for (&word_addr, &word) in words.iter() {
        let byte_addr = ByteAddr(word_addr as u64 * 4);
        let page_num = (byte_addr.0 / 4096) as u32;
        let offset = (byte_addr.0 % 4096) as u32;

        // If we're moving to a new page, flush the current one
        if page_num != current_page.page_num() {
            if !current_page.is_empty() {
                pages.insert(current_page.page_num(), current_page);
            }
            current_page = Page::new();
            current_page.set_page_num(page_num);
        }

        // Write the word to the current page
        let mut page_bytes = [0u8; 4096];
        for i in 0..4 {
            page_bytes[offset + i] = (word >> (i * 8)) as u8;
        }
        current_page.set_bytes(&page_bytes);
        current_addr = byte_addr;
    }

    // Flush the last page
    if !current_page.is_empty() {
        pages.insert(current_page.page_num(), current_page);
    }

    // Update the image with all pages
    image.pages = pages;
    image.digest = image.compute_digest();
    image
}

use syslog::Error;
