fn batch_log<I>(
    logger: &mut Logger<LoggerBackend, Formatter3164>,
    severity: Severity,
    messages: I,
) -> Result<usize, Error>
where
    I: IntoIterator,
    I::Item: AsRef<str>,
{
    let mut count = 0;
    for message in messages {
        let msg = message.as_ref();
        let formatted = format!(
            "<{}> {}",
            severity as u32,
            msg
        );
        logger.backend.write_all(formatted.as_bytes())?;
        count += 1;
    }
    Ok(count)
}

fn invert_brillig(input: Witness, output: Witness) -> Opcode {
    let brillig = Brillig {
        inputs: BrilligInputs {
            input_registers: vec![RegisterIndex::from(0)],
            output_registers: vec![RegisterIndex::from(0)],
        },
        outputs: BrilligOutputs {
            output_registers: vec![RegisterIndex::from(0)],
        },
        opcodes: vec![
            BrilligOpcode::Load(RegisterOrMemory::Register(RegisterIndex::from(0)), input),
            BrilligOpcode::Call("invert", vec![RegisterIndex::from(0)], vec![RegisterIndex::from(0)]),
            BrilligOpcode::Store(RegisterOrMemory::Register(RegisterIndex::from(0)), output),
        ],
    };
    Opcode::Brillig(brillig)
}

use v_frame::plane::Plane;
