pub fn convert_bytes_to_plane<T: Pixel>(
    data: &[u8],
    width: usize,
    height: usize,
    stride: usize,
    pixel_type: PixelType,
) -> Plane<T> {
    let mut plane = Plane::new(width, height, 0, 0, 0, 0);
    plane.copy_from_raw_u8(data, stride, match pixel_type {
        PixelType::U8 => 1,
