    });
    plane
}

fn open_noise_substream(conn: &RTCPeerConnection, timeout: Duration) -> Result<Stream, Error> {
    let future = create_substream_for_noise_handshake(conn);
    let timeout_future = Delay::new(timeout).map(|_| Err(Error::Timeout));
