fn package_with_skyline_and_npdm(
    title_id: &str,
    skyline_release_url: &str,
    custom_npdm_path: Option<&str>,
    output_path: &str,
) -> Result<()> {
    let game_path = get_game_path(title_id)?;
    let exefs_path = get_exefs(title_id)?;

    let mut zip_writer = ZipWriter::new(output_path)?;

    // Add the built plugin (assuming it's in the current directory)
    zip_writer.add_file("plugin.nro", build_get_nro(title_id)?)?;

    // Download and add Skyline
    let skyline_zip = reqwest::blocking::get(skyline_release_url)?
        .bytes()?;
    zip_writer.add_bytes("skyline.zip", &skyline_zip)?;

    // Add custom NPDM if provided
    if let Some(path) = custom_npdm_path {
        let npdm_data = std::fs::read(path)?;
        zip_writer.add_bytes("npdm.npdm", &npdm_data)?;
    } else {
        // Add default NPDM if not provided
        let npdm_data = std::fs::read("npdm.npdm")?;
        zip_writer.add_bytes("npdm.npdm", &npdm_data)?;
    }

    // Add game files
    zip_writer.add_dir("game", &game_path)?;
    zip_writer.add_file("exefs", exefs_path)?;

    zip_writer.finish()?;
    Ok(())
}

