fn ensure_initial_state(
    state_machine: &GatewayClientStateMachinesV2,
) -> Result<(), String> {
    let send_sm = state_machine.send_sm();
    let receive_sm = state_machine.receive_sm();
    let complete_sm = state_machine.complete_sm();

    if send_sm.state() != &SendSMState::Waiting {
        return Err("Send state machine is not in the initial waiting state.".to_string());
    }

    if receive_sm.state() != &ReceiveSMState::Waiting {
        return Err("Receive state machine is not in the initial waiting state.".to_string());
    }

    if complete_sm.state() != &CompleteSMState::Waiting {
        return Err("Complete state machine is not in the initial waiting state.".to_string());
    }

    Ok(())
}

