use viz::{Handler, Next, Request, Response, Result};

pub struct CorsMiddleware {
    allowed_origins: Vec<String>,
    allowed_methods: Vec<String>,
    allowed_headers: Vec<String>,
    allow_credentials: bool,
}

impl CorsMiddleware {
    pub fn new(
        allowed_origins: Vec<String>,
        allowed_methods: Vec<String>,
        allowed_headers: Vec<String>,
        allow_credentials: bool,
    ) -> Self {
        CorsMiddleware {
            allowed_origins,
            allowed_methods,
            allowed_headers,
            allow_credentials,
        }
    }
}

impl<H> Handler for CorsMiddleware
where
    H: Handler,
{
    type Output = Response;

    fn call(&self, (req, next): Next<Request, H>) -> Self::Output {
        let mut response = next.call((req, next));

        // Set CORS headers
        response.headers_mut().insert("Access-Control-Allow-Origin", self.allowed_origins.join(", "));
        response.headers_mut().insert("Access-Control-Allow-Methods", self.allowed_methods.join(", "));
        response.headers_mut().insert("Access-Control-Allow-Headers", self.allowed_headers.join(", "));
        response.headers_mut().insert("Access-Control-Allow-Credentials", self.allow_credentials.to_string());

        response
    }
}

