use domeseeing_analysis::{DeltaOPDSet, DeltaOPD};

fn filter_and_stats(dopds: &DeltaOPDSet, min_baseline: f64, max_baseline: f64) -> (DeltaOPDSet, f64, f64) {
    let filtered: DeltaOPDSet = dopds.iter()
        .filter(|d| d.baseline >= min_baseline && d.baseline <= max_baseline)
        .cloned()
        .collect();

    let delta_opd_values: Vec<f64> = filtered.iter().map(|d| d.delta_opd).collect();
    let mean = delta_opd_values.iter().sum::<f64>() / delta_opd_values.len() as f64;
    let variance = delta_opd_values.iter().map(|&x| (x - mean).powi(2)).sum::<f64>() / delta_opd_values.len() as f64;

    (filtered, mean, variance)
}

