fn batch_call_map<T>(client: &HttpClient, methods: Vec<&str>) -> Result<HashMap<String, Result<T, Error>>, Error>
where
    T: DeserializeOwned + Clone,
{
    let mut batch = BatchRequestBuilder::new();
    let mut method_results = HashMap::new();

    for &method in methods.iter() {
        batch = batch.add_request(method, rpc_params![]);
    }

    let batch_response = client.batch_call(batch.build()).map_err(|e| e)?;

    for (i, response) in batch_response.into_iter().enumerate() {
        let method_name = methods[i].to_string();
        let result = match response {
            Ok(value) => Ok(value),
            Err(err) => Err(err),
        };
        method_results.insert(method_name, result);
    }

    Ok(method_results)
}

