use std::collections::HashMap;
use jlabel_question::{AllPosition, PhonePosition, SignedRangePosition, UnsignedRangePosition, BooleanPosition, CategoryPosition, UndefinedPosition};

fn group_patterns_by_position(patterns: &[&str]) -> HashMap<AllPosition, Vec<String>> {
    let mut grouped: HashMap<AllPosition, Vec<String>> = HashMap::new();

    for &pattern in patterns {
        let position = match parse_position(pattern) {
            Ok(pos) => pos,
            Err(_) => AllPosition::UndefinedPosition,
        };
        grouped.entry(position).or_insert_with(Vec::new).push(pattern.to_string());
    }

    grouped
}

fn parse_position(pattern: &str) -> Result<AllPosition, ()> {
    if pattern.starts_with("phone:") {
        Ok(AllPosition::PhonePosition(PhonePosition))
    } else if pattern.starts_with("signed_range:") {
        Ok(AllPosition::SignedRangePosition(SignedRangePosition))
    } else if pattern.starts_with("unsigned_range:") {
        Ok(AllPosition::UnsignedRangePosition(UnsignedRangePosition))
    } else if pattern.starts_with("boolean:") {
        Ok(AllPosition::BooleanPosition(BooleanPosition))
    } else if pattern.starts_with("category:") {
        Ok(AllPosition::CategoryPosition(CategoryPosition))
    } else {
        Err(())
    }
}

fn wait_for_child_exit(pty: &mut impl EventedPty) -> Option<ChildEvent> {
    let token = pty.child_event_token();
    let mut poll = Poll::new()?;
    poll.register(pty, token, Events::readable(), PollOpt::edge(), None)?;

    loop {
        let events = poll.poll(iter::empty(), Some(Duration::from_secs(10)))?;
        if events.is_empty() {
            continue;
        }

        if events.contains(&Ready::readable()) {
            return pty.wait()?;
        }
    }
}

