#[derive(Debug, Clone)]
struct SystemCellInfo {
    transaction_hash: H256,
    output_index: u32,
    data_hash: H256,
    type_hash: Option<H256>,
}

fn extract_system_cells(spec: &ChainSpec) -> HashMap<String, SystemCellInfo> {
    let mut system_cells = HashMap::new();
    if let Some(cells) = &spec.cells {
        for cell in cells {
            if let Some(output) = &cell.output {
                let output_data = output.data().as_bytes();
                let data_hash = H256::new_from_slice(output_data).unwrap();
                let transaction_hash = cell.transaction_hash();
                let output_index = cell.output_index();
                let type_hash = cell.type_hash();

                let info = SystemCellInfo {
                    transaction_hash,
                    output_index,
                    data_hash,
                    type_hash,
                };
                system_cells.insert(cell.name().to_string(), info);
            }
        }
    }
    system_cells
}

