fn trim_high_frequency_queues(&mut self, max_len: usize) {
    for (_, (&queue_len, queue)) in &mut self.event_queues {
        if *queue_len > max_len {
            while queue.len() > max_len {
                queue.pop_front();
            }
            *queue_len = queue.len();
        }
    }
}

use rusty_jsc::{JSContext, JSValue};
use rusty_jsc::internal::JSString;
use rusty_jsc_sys::JSValueCreateJSONString;
use rusty_jsc_sys::JSStringRelease;

fn serialize_to_json(context: &JSContext, value: &JSValue) -> Result<String, JSValue> {
    let json_string = unsafe { JSValueCreateJSONString(context.0, value.0) };
    if json_string.is_null() {
        return Err(JSValue::new(context, std::ptr::null_mut()));
    }

    let js_string = JSString::new(json_string);
    let string_data = unsafe { js_string.to_string() };
    unsafe { JSStringRelease(json_string) };

