use snowstorm::{PacketVerifier, SnowstormError, SnowstormResult};
use std::collections::HashSet;

struct PacketVerifier {
    used_nonces: HashSet<u64>,
    expected_timestamp: u32,
}

impl PacketVerifier {
    fn new() -> Self {
        PacketVerifier {
            used_nonces: HashSet::new(),
            expected_timestamp: 0,
        }
    }
}

impl PacketVerifier for PacketVerifier {
    fn verify_packet(&mut self, timestamp: u32, nonce: u64) -> SnowstormResult<()> {
        if timestamp < self.expected_timestamp {
            return Err(SnowstormError::InvalidTimestamp);
        }

        if self.used_nonces.contains(&nonce) {
            return Err(SnowstormError::ReplayedNonce);
        }

        self.used_nonces.insert(nonce);
        self.expected_timestamp = timestamp + 1;

        Ok(())
    }
}

