fn kill_containers_by_image(port: u16, image_name: &str, signal: KillportSignal, dry_run: bool) -> Result<Vec<String>, std::io::Error> {
    let docker = Docker::connect_with_defaults()?;
    let mut containers = vec![];

    let options = ListContainersOptions::default()
        .with_all(true)
        .with_filters(HashMap::from([("exited", Some("0"))]));

    for container in docker.list_containers(Some(options))? {
        if let Some(host_config) = container.host_config {
            if let Some(port_bindings) = host_config.port_bindings {
                if port_bindings.contains_key(&port.to_string()) {
                    if let Some(image) = container.image {
                        if image.contains(image_name) {
                            let container_id = container.id.unwrap();
                            let container_name = container.names.first().unwrap_or(&"").to_string();
                            containers.push(container_name);

                            if !dry_run {
                                match signal {
                                    KillportSignal::SIGKILL => {
                                        docker.kill_container(&container_id, Some("SIGKILL"))?;
                                    }
                                    KillportSignal::SIGTERM => {
                                        docker.kill_container(&container_id, Some("SIGTERM"))?;
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    Ok(containers)
}

use std::fs::File;
