fn load_user_certs(user: &str) -> Result<(Cert, Cert), std::io::Error> {
    let cert_path = Path::new("certs").join(format!("{}.crt", user));
    let key_path = Path::new("keys").join(format!("{}.key", user));

    let cert = load_cert_from_path(&cert_path)?;
    let key = load_cert_from_path(&key_path)?;

    Ok((cert, key))
}

fn load_cert_from_path(path: &Path) -> Result<Cert, std::io::Error> {
    if !path.exists() {
        return Err(std::io::Error::new(std::io::ErrorKind::NotFound, format!("Certificate file not found: {}", path.display())));
    }

    let file = File::open(path)?;
    let mut reader = BufReader::new(file);
    let mut contents = Vec::new();
    reader.read_to_end(&mut contents)?;

    Ok(Cert::from(contents))
}

use std::io::{Read, Write};
use crate::pullparser::{PullParser, PullParserState, Error};

fn skip_message(&mut self) -> Result<(), Error> {
    let mut state = self.state;
    let mut buffer = [0u8; 1024];
    let mut line_ending = false;

    loop {
        match state {
            PullParserState::Start => {
                // Read until the first line ending to find the start of the message
                let mut bytes_read = 0;
                loop {
                    if bytes_read >= buffer.len() {
                        return Err(Error::UnexpectedEndOfStream);
                    }
                    let n = self.reader.read(&mut buffer[bytes_read..])?;
                    bytes_read += n;
                    if n == 0 {
                        return Err(Error::UnexpectedEndOfStream);
                    }

                    let mut i = 0;
                    while i < bytes_read {
                        if buffer[i] == b'\r' {
                            line_ending = true;
                            i += 1;
                            if i < bytes_read && buffer[i] == b'\n' {
                                i += 1;
                            }
                        } else if buffer[i] == b'\n' {
                            line_ending = true;
                            i += 1;
                        } else {
                            i += 1;
                        }

                        if line_ending {
                            // Skip the line ending
                            self.reader.read_exact(&mut [0; 0])?;
                            line_ending = false;
                            state = PullParserState::Body;
                            break;
                        }
                    }

                    if line_ending {
                        break;
                    }
                }
            },
            PullParserState::Body => {
                // Skip until the end of the message (CRLF)
                let mut bytes_read = 0;
                loop {
                    if bytes_read >= buffer.len() {
                        return Err(Error::UnexpectedEndOfStream);
                    }
                    let n = self.reader.read(&mut buffer[bytes_read..])?;
                    bytes_read += n;
                    if n == 0 {
                        return Err(Error::UnexpectedEndOfStream);
                    }

                    let mut i = 0;
                    while i < bytes_read {
                        if buffer[i] == b'\r' {
                            line_ending = true;
                            i += 1;
                            if i < bytes_read && buffer[i] == b'\n' {
                                i += 1;
                            }
                        } else if buffer[i] == b'\n' {
                            line_ending = true;
                            i += 1;
                        } else {
                            i += 1;
                        }

                        if line_ending {
                            // Skip the line ending
                            self.reader.read_exact(&mut [0; 0])?;
                            line_ending = false;
                            state = PullParserState::Start;
                            break;
                        }
                    }

                    if line_ending {
                        break;
                    }
                }
            },
            _ => {
                // Invalid state, should not occur
                return Err(Error::InvalidState);
            }
        }
    }
}

