fn attach_metrics<A>(options: ReconnectOptions) -> (ReconnectOptions, ReconnectMetrics)
where
    A: std::any::Any + 'static,
{
    let reconnect_attempts = Arc::new(AtomicUsize::new(0));
    let reconnect_attempts_clone = reconnect_attempts.clone();

    let mut options = options;
    options.on_reconnect = Some(Box::new(move || {
        reconnect_attempts_clone.fetch_add(1, Ordering::SeqCst);
    }));

    let metrics = ReconnectMetrics {
        reconnect_attempts,
    };

    (options, metrics)
}

