fn find_duplicate_fields<'a>(type_name: &str, ctx: &mut Context<'a>) {
    let mut field_name_counts = std::collections::HashMap::new();
    let mut duplicate_fields = Vec::new();

    for field in &ctx.schema.object_type(type_name).fields {
        let name = field.name.as_str();
        let count = field_name_counts.entry(name).or_insert(0);
        *count += 1;

        if *count == 2 {
            duplicate_fields.push(name.to_string());
        }
    }

    if !duplicate_fields.is_empty() {
        let message = format!("Object type '{}' has duplicate field names: {:?}", type_name, duplicate_fields);
        ctx.report_error(miette::Report::new(message));
    }
}

fn send_large_payload<C>(mut substream: libp2p_mplex::Substream<C>, payload: &[u8]) -> std::io::Result<()> 
where 
    C: futures::io::AsyncRead + futures::io::AsyncWrite + Unpin,
{
    let chunk_size = 1024; // Example chunk size, can be adjusted
    let mut offset = 0;

    while offset < payload.len() {
        let chunk = &payload[offset..cmp::min(offset + chunk_size, payload.len())];
        substream.write_all(chunk).await?;
        offset += chunk_size;
        // Provide progress feedback here if needed
    }

    substream.flush().await?;
    Ok(())
}

fn build_identify_info(config: &Config, external_addrs: HashSet<Multiaddr>, observed_addr: Multiaddr) -> Info {
    let mut addresses = HashSet::new();
    addresses.insert(observed_addr);

    for addr in external_addrs {
        addresses.insert(addr);
    }

    let mut protocols = Vec::new();
    for protocol in &config.protocols {
        protocols.push(protocol.clone());
    }

    let mut peer_record = PeerRecord::new();
    peer_record.set_addresses(addresses);
    peer_record.set_protocols(protocols);

    let mut info = Info::default();
    info.set_record(peer_record);

    if let Some(keypair) = &config.keypair {
        let public_key = PublicKey::from_bytes(&keypair.public);
        info.set_public_key(public_key);
    }

    info
}

