fn custom_panic_hook(info: &panic::PanicInfo) {
    // Build the DataPoint with extra tags
    let mut tags = vec![
        ("program", program),
        ("version", version.as_ref().unwrap_or(&"")),
    ];
    tags.extend(extra_tags.iter().map(|&(k, v)| (k, v)));

    let data_point = DataPoint::new(
        "panic",
        Level::Error,
        info.message().unwrap_or("unknown panic"),
        tags,
    );

    // Submit and flush the data point
    submit(data_point);
    flush();
}

fn set_custom_panic_hook(program: &'static str, version: Option<String>, extra_tags: &[(&'static str, &str)]) {
    ONCE.call_once(|| {
        unsafe {
            if !CUSTOM_PANIC_HOOK_INSTALLED {
                // Set the custom panic hook
                panic::set_hook(Box::new(|info| {
                    custom_panic_hook(info);
                }));
                CUSTOM_PANIC_HOOK_INSTALLED = true;
            }
        }
    });
}

