fn estimate_heap_compute_units(heap_size: u32, heap_cost: u64) -> u64 {
    // Convert heap_size from bytes to pages, assuming 4096 bytes per page
    let pages = (heap_size + 4095) / 4096;
    pages as u64 * heap_cost
}

fn total_usable_size(heap: *mut mi_heap_t) -> usize {
    let mut total = 0;
    let mut block = ptr::null_mut();

    unsafe {
        while mi_heap_walk_blocks(heap, &mut block) != 0 {
            if !block.is_null() {
                let usable_size = mi_usable_size(block as *mut c_void);
                total += usable_size as usize;
            }
        }
    }

    total
}

fn find_all_simd(needle: &[u8], haystack: &[u8]) -> Vec<usize> {
    if needle.is_empty() || haystack.is_empty() {
        return Vec::new();
    }

    let mut results = Vec::new();
    let mut searcher = DynamicAvx2Searcher::new(needle);
    let mut offset = 0;

    while let Some(pos) = searcher.find_next(haystack, offset) {
        results.push(pos);
        offset = pos + 1;
    }

    results
}

