fn load_plugin_with_timing<P: AsRef<std::path::Path>>(
    &mut self,
    geyser_plugin_config_file: P,
) -> Result<String, GeyserPluginManagerError> {
    let start = Instant::now();
    let config_path = geyser_plugin_config_file.as_ref();
    let config = std::fs::read_to_string(config_path)
        .map_err(|e| GeyserPluginManagerError::ConfigReadError(e.to_string()))?;

    let plugin_name = Path::new(config_path).file_stem().and_then(|s| s.to_str()).unwrap_or("unknown");
    info!("Loading plugin config for {}", plugin_name);

    let plugin_config: PluginConfig = toml::from_str(&config)
        .map_err(|e| GeyserPluginManagerError::ConfigParseError(e.to_string()))?;

    let plugin_path = Path::new(&plugin_config.path);
    let plugin_lib = unsafe {
        libloading::Library::new(plugin_path)
            .map_err(|e| GeyserPluginManagerError::LibraryLoadError(e.to_string()))?
    };

    let on_load = plugin_lib.get::<unsafe extern "C" fn() -> i32>("on_load")
        .map_err(|e| GeyserPluginManagerError::SymbolError(e.to_string()))?;

    let result = on_load();
    if result != 0 {
        error!("Plugin {} on_load failed with code {}", plugin_name, result);
        return Err(GeyserPluginManagerError::PluginLoadError(format!("on_load failed with code {}", result)));
    }

    let duration = start.elapsed();
    info!("Loaded plugin {} in {:?}", plugin_name, duration);

    Ok(plugin_name.to_string())
}

use libp2p_core::multiaddr::{Multiaddr, Protocol};
use std::net::SocketAddr;
use crate::tokio::transport::parse_webrtc_listen_addr;
use crate::tokio::fingerprint::Fingerprint;
use multihash::Multihash;

fn parse_webrtc_multiaddr(addr: &Multiaddr) -> Result<(SocketAddr, Option<Fingerprint>), ()> {
    let mut iter = addr.iter();
    let mut ip4 = None;
    let mut udp = None;
    let mut cert_hash = None;

    while let Some(proto) = iter.next() {
        match proto {
            Protocol::Ip4(ip) => {
                ip4 = Some(ip.to_string());
            }
            Protocol::Udp(port) => {
                udp = Some(port);
            }
            Protocol::WebrtcDirect => {
                // WebrtcDirect is a special protocol that indicates the address is a WebRTC direct address
                // We need to check if there is a certhash protocol following it
                if let Some(next) = iter.next() {
                    if next.is_protocol(Protocol::Certhash) {
                        if let Some(next_next) = iter.next() {
                            if let Some(hash) = next_next.as_multihash() {
                                cert_hash = Some(Fingerprint::from_hash(hash));
                            }
                        }
                    }
                }
            }
            _ => continue,
        }
    }

    let ip_str = ip4.ok_or(())?;
    let port = udp.ok_or(())?;
    let socket_addr = format!("{}:{}", ip_str, port).parse().map_err(|_| ())?;

    Ok((socket_addr, cert_hash))
}

