use typesize::TypeSize;
use std::sync::Arc;
use std::collections::HashSet;

struct TreeNode<T> {
    value: T,
    children: Vec<Arc<TreeNode<T>>>,
}

fn tree_total_size<T: TypeSize>(root: &Arc<TreeNode<T>>) -> usize {
    let mut visited = HashSet::new();
    let mut total_size = 0;

    fn visit<T: TypeSize>(node: &Arc<TreeNode<T>>, visited: &mut HashSet<*const TreeNode<T>>, total_size: &mut usize) {
        let ptr = node as *const TreeNode<T>;
        if visited.contains(&ptr) {
            return;
        }
        visited.insert(ptr);

        // Add the size of the current node
        *total_size += TypeSize::size_of::<TreeNode<T>>() as usize;

        // Add the size of the value
        *total_size += TypeSize::size_of_val(&node.value) as usize;

        // Recursively visit children
        for child in &node.children {
            visit(child, visited, total_size);
        }
    }

    visit(root, &mut visited, &mut total_size);
    total_size
}

