use wasm_bindgen::prelude::*;
use web_extensions_sys::chrome;
use js_sys::{Object, Reflect, Array};

fn url_is_open(url: &str) -> Result<bool, wasm_bindgen::JsValue> {
    let tabs = chrome::tabs::query(
        &Object::new(),
        Some(&json!({
            "currentWindow": true,
            "windowType": "normal"
        })),
    );

    if tabs.is_err() {
        return Err(tabs.unwrap_err());
    }

    let tabs = tabs.unwrap();
    let tabs_array = tabsdyn::JsValue::from(tabs);

    for i in 0..tabs_array.length() {
        let tab = tabs_array.get(i);
        if tab.is_undefined() {
            continue;
        }

        let url_property = Reflect::get(&tab, &JsValue::from("url"));
        if url_property.is_null() {
            continue;
        }

        let tab_url = url_property.as_string().unwrap();
        if tab_url == url {
            return Ok(true);
        }
    }

    Ok(false)
}

use crate::Sheet;
use crate::event::{Event, MidiEvent};

fn extract_bars(sheet: Sheet, ticks_per_beat: u16) -> Vec<Vec<MidiEvent>> {
    let mut bars = Vec::new();
    let mut current_bar = Vec::new();
    let mut current_tick = 0;
    let mut bar_number = 1;

    for event in sheet.events {
        if let Event::MidiEvent(midi_event) = event {
            let event_tick = midi_event.tick;
            let beat = event_tick / ticks_per_beat;
            let bar = (beat / sheet.time_signature.numerator) + 1;

            if bar != bar_number {
                bars.push(current_bar);
                current_bar = Vec::new();
                bar_number = bar;
            }

            current_bar.push(midi_event);
        }
    }

    if !current_bar.is_empty() {
        bars.push(current_bar);
    }

    bars
}

