    let percent = (current as f64 / total as f64) * 100.0;
    let bar_length = cmp::min(terminal_width as usize - 6, 50); // 6 for brackets and text
    let filled = (bar_length as f64 * percent / 100.0) as usize;
    let empty = bar_length - filled;

    let mut bar = String::with_capacity(bar_length);
    for _ in 0..filled {
        bar.push('#');
    }
    for _ in 0..empty {
        bar.push(' ');
    }

    format!("{}[{}{}]", "Progress: ", bar, "]")
}

use crate::queries::indexer_assets;
