fn fetch_all_assets(conn: &mut IndexerConnection, index_id: i64) -> sqlx::Result<HashMap<IndexerAssetType, Vec<u8>>> {
    let mut assets = HashMap::new();

    // Fetch WASM asset
    let wasm_result = sqlx::query!(
        "SELECT asset_data FROM indexer_assets WHERE index_id = $1 AND asset_type = $2",
        index_id,
        IndexerAssetType::Wasm as i16
    )
    .fetch_optional(conn)
    .await?
    .map(|r| r.asset_data);

    if let Some(wasm) = wasm_result {
        assets.insert(IndexerAssetType::Wasm, wasm);
    }

    // Fetch schema asset
    let schema_result = sqlx::query!(
        "SELECT asset_data FROM indexer_assets WHERE index_id = $1 AND asset_type = $2",
        index_id,
        IndexerAssetType::Schema as i16
    )
    .fetch_optional(conn)
    .await?
    .map(|r| r.asset_data);

    if let Some(schema) = schema_result {
        assets.insert(IndexerAssetType::Schema, schema);
    }

    // Fetch manifest asset
    let manifest_result = sqlx::query!(
        "SELECT asset_data FROM indexer_assets WHERE index_id = $1 AND asset_type = $2",
        index_id,
        IndexerAssetType::Manifest as i16
    )
    .fetch_optional(conn)
    .await?
    .map(|r| r.asset_data);

    if let Some(manifest) = manifest_result {
        assets.insert(IndexerAssetType::Manifest, manifest);
    }

    Ok(assets)
}

fn create_framebuffer_with_texture(context: &Context, width: SizeI, height: SizeI) -> Option<(Framebuffer, Texture)> {
    // Create a texture for the color attachment
    let texture = Texture::new_2d(
        context,
        width,
        height,
        TEXTURE_2D,
        RGBA,
        UNSIGNED_BYTE,
    );

    if texture.is_none() {
        return None;
    }

    let texture = texture.unwrap();

    // Create a framebuffer and attach the texture as the color attachment
    let framebuffer = Framebuffer::new(context);
    if framebuffer.is_none() {
        return None;
    }

    let framebuffer = framebuffer.unwrap();

    unsafe {
        // Bind the texture to the color attachment point
        context.bind_texture(TEXTURE_2D, Some(&texture));
        context.framebuffer_texture_2d(
            FRAMEBUFFER,
            COLOR_ATTACHMENT0,
            TEXTURE_2D,
            &texture,
            0,
        );
    }

    // Check if the framebuffer is complete
    let status = context.check_framebuffer_status(FRAMEBUFFER);
    if status != FRAMEBUFFER_COMPLETE {
        return None;
    }

    Some((framebuffer, texture))
}

use sha2::{Sha256, Sha384, Sha512};
use hmac::{Hmac, Mac};
use crate::ShaAny;
use crate::ShaAnyBytes;

fn hash_all<I: IntoIterator>(&self, iter: I) -> ShaAnyBytes
    where
        I::Item: AsRef<[u8]>,
{
    let mut hasher = match self {
        ShaAny::Sha256 => Sha256::new(),
        ShaAny::Sha384 => Sha384::new(),
        ShaAny::Sha512 => Sha512::new(),
    };

    for item in iter {
        hasher.update(item.as_ref());
    }

    let result = hasher.finalize();
    ShaAnyBytes::from(result.as_ref().to_vec())
}

fn read_cached_body(
    cache: &dyn Cache,
    request: CacheMatchRequest,
) -> Result<Option<Vec<u8>>, CacheError> {
    if let Some(resource) = cache.match_request(request)? {
        let body = resource.body();
        let mut vec = Vec::new();
        let mut reader = body.reader();
        while let Ok(n) = reader.read_buf(&mut vec) {
            if n == 0 {
                break;
            }
        }
        Ok(Some(vec))
    } else {
        Ok(None)
    }
}

