fn analyze_delayed_receipts_for_accounts(
    home: &PathBuf,
    genesis_validation: GenesisValidationMode,
    account_ids: Vec<AccountId>,
) -> anyhow::Result<()> {
    let config = load_config(home, genesis_validation)?;
    let storage = open_storage(home, &config)?;
    let chain_store = ChainStore::new(storage, &config)?;
    let chain_store_access = ChainStoreAccess::new(chain_store);
    let epoch_manager = EpochManager::new(&config, &storage)?;
    let epoch_manager_adapter = EpochManagerAdapter::new(epoch_manager);
    let block_iterator = make_block_iterator_from_command_args(CommandArgs {
        start_block: 0,
        end_block: 100,
        ..Default::default()
    });

    let mut account_delayed_receipts: HashMap<AccountId, usize> = HashMap::new();

    for block in block_iterator {
        let block_height = block.height();
        let shard_uid = ShardUId::for_block_height(block_height, &config.epoch_config);
        let trie_config = TrieConfig::default();
        let state_snapshot_config = StateSnapshotConfig::default();
        let shard_tries = ShardTries::new(
            &storage,
            &config,
            &trie_config,
            &state_snapshot_config,
            &shard_uid,
        );
        let store_adapter = StoreAdapter::new(shard_tries, &config);
        let delayed_receipt_indices = get_delayed_receipt_indices(&store_adapter, block_height)?;

        for index in delayed_receipt_indices {
            let receipt_hash = store_adapter.get_receipt_hash(index)?;
            let receipt = store_adapter.get_receipt(index)?;
            let account_id = receipt.receiver_id();
            if account_ids.contains(&account_id) {
                *account_delayed_receipts.entry(account_id).or_insert(0) += 1;
            }
        }
    }

    for (account_id, count) in &account_delayed_receipts {
        println!("Account {}: {} delayed receipts", account_id, count);
    }

    Ok(())
}

