struct CircuitBreaker {
    client: Client,
    threshold: u32,
    timeout: Duration,
    failure_count: u32,
    last_failure: Option<Instant>,
}

impl CircuitBreaker {
    fn new(client: Client, threshold: u32, timeout: Duration) -> Self {
        CircuitBreaker {
            client,
            threshold,
            timeout,
            failure_count: 0,
            last_failure: None,
        }
    }

    async fn execute_command<F, R>(&mut self, command: F) -> Result<R, RedisError>
    where
        F: FnOnce(&mut Connection) -> RedisResult<R>,
    {
        if self.is_open() {
            return Err(RedisError::new(ErrorKind::Other, "Circuit breaker is open"));
        }

        let mut conn = match self.client.get_connection().await {
            Ok(conn) => conn,
            Err(e) => {
                self.failure_count += 1;
                self.last_failure = Some(Instant::now());
                return Err(e);
            }
        };

        match command(&mut conn) {
            Ok(result) => {
                self.failure_count = 0;
                self.last_failure = None;
                Ok(result)
            }
            Err(e) => {
                self.failure_count += 1;
                self.last_failure = Some(Instant::now());
                if self.failure_count >= self.threshold {
                    self.open_circuit();
                }
                Err(e)
            }
        }
    }

    fn is_open(&self) -> bool {
        self.failure_count >= self.threshold && self.last_failure.map_or(false, |t| t.elapsed() < self.timeout)
    }

    fn open_circuit(&mut self) {
        self.failure_count = self.threshold;
        self.last_failure = Some(Instant::now());
    }
}

fn create_bid(auction_id: usize, cfg: &GeneratorConfig) -> Bid {
    let mut rng = SmallRng::seed_from_u64(cfg.seed);
    let person = Person {
        id: rng.gen_range(0..cfg.person_count),
        name: rng.gen(),
    };

    let channel = if cfg.hot_channel_ratio > 0.0 {
        let hot_channels = &cfg.hot_channels;
        let hot_urls = &cfg.hot_urls;
        let hot_channels_len = hot_channels.len();
        let mut hot_channels_vec = hot_channels.to_vec();
        hot_channels_vec.shuffle(&mut rng);
        let selected_channel = hot_channels_vec[0];
        let selected_url = hot_urls[selected_channel as usize];
        (selected_channel, selected_url)
    } else {
        let channel_keys: Vec<usize> = CHANNEL_URL_MAP.keys().cloned().collect();
        let selected_channel = *channel_keys.choose(&mut rng).unwrap();
        (selected_channel, CHANNEL_URL_MAP[&selected_channel])
    };

    let price = rng.gen_range(cfg.price_min..=cfg.price_max);
    let timestamp = rng.gen_range(cfg.start_time..=cfg.end_time);

    Bid {
        id: rng.gen(),
        auction_id,
        person,
        channel: channel.0,
        url: channel.1,
        price,
        timestamp,
    }
}

use dispatch2::{DispatchQueue, DispatchSemaphore, DispatchTime};
use alloc::vec::Vec;

fn throttled_map<T, R, F>(
    items: &[T],
    queue: &DispatchQueue,
    max_concurrency: usize,
    mapper: F,
) -> Vec<R>
where
    T: Sync,
    R: Send + 'static,
    F: Fn(&T) -> R + Send + Sync + 'static,
{
    let semaphore = DispatchSemaphore::new(max_concurrency as i32);
    let mut results = Vec::with_capacity(items.len());

    for item in items {
        let semaphore = semaphore.clone();
        let mapper = mapper.clone();
        let item = item.clone();

        queue.async_send(move || {
            semaphore.wait();
            let result = mapper(&item);
            results.push(result);
            semaphore.signal();
        });
    }

    queue.sync_wait();
    results
}

fn auto_refresh_registration(
    &mut self,
    namespace: Namespace,
    rendezvous_node: PeerId,
    ttl: Ttl,
) {
    let mut interval = time::interval(ttl - Duration::from_secs(60));
    let mut registration_done = false;

    tokio::spawn(async move {
        loop {
            interval.tick().await;
            let now = time::Instant::now();
            let registration_expiry = now + ttl;

            if !registration_done {
                match self.register(namespace, rendezvous_node, ttl).await {
                    Ok(_) => {
                        tracing::info!("Registration successful.");
                        registration_done = true;
                    }
                    Err(RegisterError::AlreadyRegistered) => {
                        tracing::info!("Already registered, no action needed.");
                    }
                    Err(e) => {
                        tracing::error!("Failed to register: {}", e);
                    }
                }
            } else {
                let time_until_expiry = registration_expiry - now;
                if time_until_expiry < Duration::from_secs(60) {
                    match self.re_register(namespace, rendezvous_node, ttl).await {
                        Ok(_) => {
                            tracing::info!("Re-registration successful.");
                        }
                        Err(RegisterError::AlreadyRegistered) => {
                            tracing::info!("Already registered, no action needed.");
                        }
                        Err(e) => {
                            tracing::error!("Failed to re-register: {}", e);
                        }
                    }
                }
            }
        }
    });
}

fn send_to_first_leader<P, M, C>(tpu_client: &TpuClient<P, M, C>, transaction: &Transaction) -> TransportResult<()>
where
    P: ConnectionPool<NewConnectionConfig = C>,
    M: ConnectionManager<ConnectionPool = P, NewConnectionConfig = C>,
    C: NewConnectionConfig,
{
    for leader in tpu_client.leader_list() {
        let socket_addr: SocketAddr = leader.parse().map_err(|_| TransportError::new("Invalid leader address"))?;
        let mut client = tpu_client.clone();
        client.set_tpu_socket(socket_addr);
        match client.send_transaction(transaction) {
            Ok(_) => return Ok(()),
            Err(e) => {
                warn!("Failed to send transaction to leader {}: {}", leader, e);
                continue;
            }
        }
    }
    Err(TransportError::new("All leader TPUs failed to accept the transaction"))
}

fn execute_pipeline(commands: &mut [&mut Command]) -> Result<String, std::io::Error> {
    let mut last_cmd = commands.last_mut().unwrap();
    let mut stdout = Vec::new();
    let mut stderr = Vec::new();

    // Pipe the stdout of the first command to the stdin of the second
    if let Some(first_cmd) = commands.get_mut(0) {
        let mut child = first_cmd
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;

        if let Some(next_cmd) = commands.get(1) {
            let mut next_cmd = next_cmd.stdin(std::process::Stdio::from(child.stdout.take().unwrap()));
            next_cmd = next_cmd.stdout(std::process::Stdio::piped())
                .stderr(std::process::Stdio::piped());
            let mut next_child = next_cmd.spawn().map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;

            // Collect stdout of the second command
            let mut next_stdout = Vec::new();
            let mut next_stderr = Vec::new();
            let mut next_status = next_child.wait().map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;

            if !next_status.success() {
                let next_stderr = std::str::from_utf8(&next_stderr).map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;
                return Err(std::io::Error::new(std::io::ErrorKind::Other, format!("Command failed: {}", next_stderr)));
            }

            let _ = next_child.stdout.take().unwrap().read_to_end(&mut next_stdout);
            let _ = next_child.stderr.take().unwrap().read_to_end(&mut next_stderr);

            stdout = next_stdout;
            stderr = next_stderr;
        } else {
            let _ = child.stdout.take().unwrap().read_to_end(&mut stdout);
            let _ = child.stderr.take().unwrap().read_to_end(&mut stderr);

            let status = child.wait().map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;
            if !status.success() {
                let stderr = std::str::from_utf8(&stderr).map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;
                return Err(std::io::Error::new(std::io::ErrorKind::Other, format!("Command failed: {}", stderr)));
            }
        }
    }

    let stdout_str = std::str::from_utf8(&stdout).map_err(|e| std::io::Error::new(std::io::ErrorKind::Other, e))?;
    Ok(stdout_str.to_string())
}

