use gluesql_core::{error::Result, store::Store};
use gluesql_core::data::DataRow;

impl JsonStorage {
    pub fn export_to_csv(&self, table_name: &str) -> Result<String> {
        let (rows, schema) = self.scan_data(table_name)?;
        let headers: Vec<String> = schema
            .column_defs
            .as_ref()
            .map(|cols| cols.iter().map(|col| col.name.clone()).collect())
            .unwrap_or_default();
        let mut csv = headers.join(",");
        csv.push('\n');
        for item in rows {
            let (_key, row) = item?;
            let values: Vec<String> = match row {
                DataRow::Vec(vals) => {
                    schema
                        .column_defs
                        .as_ref()
                        .map(|cols| {
                            cols.iter()
                                .zip(vals)
                                .map(|(_, v)| v.to_string())
                                .collect()
                        })
                        .unwrap_or_default()
                }
                DataRow::Map(map) => {
                    schema
                        .column_defs
                        .as_ref()
                        .map(|cols| {
                            cols.iter()
                                .map(|col| {
                                    map.get(&col.name)
                                        .map(|v| v.to_string())
                                        .unwrap_or_default()
                                })
                                .collect()
                        })
                        .unwrap_or_default()
                }
            };
            csv.push_str(&values.join(","));
            csv.push('\n');
        }
        Ok(csv)
    }
}

