fn load_verifying_key_from_file(path: &str) -> Result<Groth16Verifyingkey<'static>, std::io::Error> {
    let path = Path::new(path);
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let verifying_key_file: VerifyingKeyFile = from_reader(reader)?;

    let alpha_g1 = verifying_key_file.alpha_g1;
    let beta_g2 = verifying_key_file.beta_g2;
    let gamma_g2 = verifying_key_file.gamma_g2;
    let delta_g2 = verifying_key_file.delta_g2;
    let ic = verifying_key_file.ic;

    Ok(Groth16Verifyingkey::new(
        verifying_key_file.npubinputs,
        alpha_g1,
        beta_g2,
        gamma_g2,
        delta_g2,
        ic
    ))
}

