fn find_top_matches<'a>(
    matcher: &dyn FuzzyMatcher,
    pattern: &str,
    candidates: &[&'a str],
    limit: usize,
    min_score: ScoreType,
) -> Vec<(&'a str, ScoreType)> {
    let mut results: Vec<(&'a str, ScoreType)> = Vec::new();
    let mut score_map: std::collections::HashMap<&'a str, ScoreType> = std::collections::HashMap::new();

    for &candidate in candidates {
        let score = matcher.match_score(pattern, candidate);
        score_map.insert(candidate, score);
    }

    let mut sorted: Vec<_> = score_map.into_iter().collect();
    sorted.sort_by(|a, b| b.1.cmp(&a.1));

    let mut count = 0;
    let mut current_score = ScoreType::MAX;
    let mut current_candidates = Vec::new();

    for (candidate, score) in sorted {
        if score < min_score {
            break;
        }

        if score != current_score {
            if !current_candidates.is_empty() {
                for &c in &current_candidates {
                    results.push((c, current_score));
                }
            }
            current_score = score;
            current_candidates = Vec::new();
        }

        current_candidates.push(candidate);
        count += 1;

        if count >= limit {
            break;
        }
    }

    if !current_candidates.is_empty() {
        for &c in &current_candidates {
            results.push((c, current_score));
        }
    }

    results
}

