fn await_preimage_with_timeout<T: LightningFederationApi>(api: &T, outpoint: OutPoint, expiration: u64, timeout: std::time::Duration) -> Result<Option<[u8; 32]>, anyhow::Error> {
    let start_time = std::time::Instant::now();
    let mut last_seen = None;

    while start_time.elapsed() < timeout {
        if let Some(preimage) = api.get_preimage(outpoint).blocking() {
            if preimage.timestamp <= expiration {
                return Ok(Some(preimage.preimage));
            }
        } else if let Some(preimage) = last_seen {
            if preimage.timestamp <= expiration {
                return Ok(Some(preimage.preimage));
            }
        }

        sleep(std::time::Duration::from_millis(500)).await;
    }

    Ok(None)
}

use mongodb::bson::Document;
use gluesql_core::prelude::Key;
use gluesql_mongo_storage::error::MongoStorageError;

fn extract_key(document: &Document, has_primary: bool) -> Result<Key, MongoStorageError> {
    if !has_primary {
        return Err(MongoStorageError::MissingPrimaryKey);
    }

    if let Some(primary) = document.get("_id") {
        if let Some(object_id) = primary.as_oid() {
            return Ok(Key::from(object_id.to_string()));
        } else if let Some(binary) = primary.as_binary() {
            // Handle binary representation, assuming it's a valid ObjectId
            if binary.subtype == mongodb::bson::BinarySubtype::ObjectId {
                let bytes = binary.bytes().to_vec();
                if bytes.len() == 12 {
                    let oid = mongodb::oid::ObjectId::from_bytes(&bytes);
                    return Ok(Key::from(oid.to_string()));
                }
            }
        }
    }

    Err(MongoStorageError::InvalidPrimaryKeyType)
}

