use stream_delimit::stream::FramedRead;
use std::io::Read;

struct FilteredFramedRead<'a, R: Read> {
    inner: &'a mut R,
    predicate: Box<dyn Fn(&[u8]) -> bool + 'a>,
}

impl<'a, R: Read> FilteredFramedRead<'a, R> {
    fn new(inner: &'a mut R, predicate: impl Fn(&[u8]) -> bool + 'a) -> Self {
        FilteredFramedRead {
            inner,
            predicate: Box::new(predicate),
        }
    }
}

impl<'a, R: Read> FramedRead for FilteredFramedRead<'a, R> {
    type Item = Vec<u8>;

    fn read_frame(&mut self) -> Result<Option<Self::Item>, std::io::Error> {
        match FramedRead::read_frame(self.inner) {
            Ok(Some(frame)) => {
                if (self.predicate)(&frame) {
                    Ok(Some(frame))
                } else {
                    Ok(None)
                }
            }
            Ok(None) => Ok(None),
            Err(e) => Err(e),
        }
    }
}

use fedimint_api_client::api::net::Connector;
