use fedimint_api_client::query::FilterMap;
use fedimint_core::endpoint_constants::CLIENT_CONFIG_ENDPOINT;
use fedimint_core::module::ApiRequestErased;
use anyhow::{bail, Context as _};

fn download_and_verify_config(
    connector: &Connector,
    invite: &InviteCode,
) -> anyhow::Result<ClientConfig> {
    let peers = invite.peers();
    let mut configs = Vec::new();

    for peer in peers {
        let api = connector
            .connect(peer)
            .context("Failed to connect to peer")?;
        let config = api
            .request(ApiRequestErased::new(CLIENT_CONFIG_ENDPOINT, None))
            .context("Failed to get client config from peer")?
            .downcast::<ClientConfig>()
            .context("Unexpected response type")?;

        configs.push(config);
    }

    let first_config = configs.first().ok_or("No peer configs received")?;
    for config in configs.iter().skip(1) {
        if config != first_config {
            bail!("Client config differs between peers");
        }
    }

    Ok(first_config.clone())
}

