fn get_current_window_tab_urls() -> Result<Vec<String>, JsValue> {
    let window_id = 0; // Current window ID is 0
    let mut urls = Vec::new();

    // Get the current window's tabs
    let tabs = chrome::tabs::query(
        &Object::new(),
        &json!({
            "windowId": window_id,
            "currentWindow": true
        })
    );

    // Wait for the tabs query to resolve
    let tabs_future = JsFuture::from(tabs);
    let tabs_result = tabs_future.await?;

    // Convert the tabs result to an array
    let tabs_array = tabs_result.dyn_ref::<Array>().ok_or("Failed to get tabs array")?;

    // Iterate over each tab and collect URLs
    for tab in tabs_array.iter() {
        let tab = tab.dyn_ref::<Tab>().ok_or("Failed to get tab object")?;
        if let Some(url) = tab.url() {
            urls.push(url.into());
        }
    }

    Ok(urls)
}

