fn verify_pegin_proof<C: Verification>(
    proof: &PegInProof,
    config: &WalletConfig,
    secp: &Secp256k1<C>,
) -> Result<(), PegInProofError> {
    // Verify the peg-in proof against the federation's descriptor
    let descriptor = &config.descriptor;

    // Check if the proof's tweaked script matches the federation's descriptor
    let expected_tweaked_script = descriptor.tweaked_script();
    let actual_tweaked_script = proof.tweaked_script();

    if actual_tweaked_script != expected_tweaked_script {
        return Err(PegInProofError::InvalidTweakedScript);
    }

    // Verify the signature using the provided secp context
    let signature = &proof.signature;
    let public_key = &proof.public_key;

    let result = secp.verify(&signature, &public_key, &actual_tweaked_script)?;

    if !result {
        return Err(PegInProofError::InvalidSignature);
    }

    Ok(())
}

