use crate::ffi::*;

#[derive(Debug)]
pub struct TileInfo {
    pub index: OPJ_UINT32,
    pub x0: OPJ_INT32,
    pub y0: OPJ_INT32,
    pub x1: OPJ_INT32,
    pub y1: OPJ_INT32,
    pub component_count: OPJ_UINT32,
}

fn extract_tile_info(
    stream: *mut opj_stream_t,
    codec: *mut opj_codec_t,
) -> Result<Vec<TileInfo>, String> {
    unsafe {
        let mut tile_count = 0;
        let mut tile_info = Vec::new();
        let mut tile_index = 0;

        // Get the number of tiles
        let mut num_tiles = 0;
        if opj_get_num_tiles(codec, &mut num_tiles) != 0 {
            return Err("Failed to get number of tiles".to_string());
        }
        tile_count = num_tiles;

        // Iterate through each tile
        for _ in 0..tile_count {
            let mut tile = opj_tile_t::default();
            let mut tile_index_u32: OPJ_UINT32 = 0;

            // Get the current tile index
            if opj_get_current_tile_index(codec, &mut tile_index_u32) != 0 {
                return Err("Failed to get current tile index".to_string());
            }

            // Get the tile information
            if opj_get_tile_info(codec, &mut tile) != 0 {
                return Err("Failed to get tile information".to_string());
            }

            // Extract tile metadata
            let tile_info = TileInfo {
                index: tile_index_u32,
                x0: tile.x0,
                y0: tile.y0,
                x1: tile.x1,
                y1: tile.y1,
                component_count: tile.components as OPJ_UINT32,
            };

            tile_info.push(tile_info);
            tile_index += 1;
        }

        Ok(tile_info)
    }
}

