fn install_with_dependencies(title_id: &str, ip: Option<String>) -> Result<()> {
    let ip = match ip {
        Some(ip) => verify_ip(&ip)?,
        None => get_ip()?,
    };

    let metadata = get_metadata(title_id)?;
    let dependencies = metadata.dependencies;

    for (dep_title_id, _) in dependencies {
        install_plugin(&dep_title_id, Some(ip.clone()))?;
    }

    install_plugin(title_id, Some(ip))
}

fn install_plugin(title_id: &str, ip: Option<String>) -> Result<()> {
    let ip = match ip {
        Some(ip) => verify_ip(&ip)?,
        None => get_ip()?,
    };

    let game_path = get_game_path()?;
    let plugin_path = get_plugin_path(title_id)?;

    let ftp = FtpClient::connect(ip)?;
    ftp.upload(plugin_path, &format!("{}/{}", game_path, title_id))?;

    Ok(())
}

