use solana_zk_token_sdk::encryption::pedersen::{Pedersen, PedersenOpening};
use solana_zk_token_sdk::zk_token_proof_instruction::BatchedRangeProofU64Data;

fn verify_batched_u64_range_proofs(values: &[u64]) -> Result<(), Box<dyn std::error::Error>> {
    let mut commitments = Vec::new();
    let mut openings = Vec::new();

    for &value in values {
        let commitment = Pedersen::new(value);
        let opening = PedersenOpening::new(commitment, value);
        commitments.push(commitment);
        openings.push(opening);
    }

    let batched_data = BatchedRangeProofU64Data::new(commitments, openings);
    batched_data.verify()?;

    Ok(())
}

use tree_sitter::Parser;
use tree_sitter::TreeCursor;
use tree_sitter_embedded_template::LANGUAGE;

fn find_comment_directives(source: &str) -> Result<Vec<String>, String> {
    let mut parser = Parser::new();
    parser.set_language(LANGUAGE).map_err(|e| e.to_string())?;

    let tree = parser.parse(source).ok_or("Failed to parse source".to_string())?;
    let root_node = tree.root_node;

    let mut comment_directives = Vec::new();
    let mut cursor = TreeCursor::new(&root_node);

    while let Some(node) = cursor.next() {
        if node.kind() == "comment_directive" {
            if let Some(text) = node.text() {
                comment_directives.push(text.to_string());
            }
        }
    }

    Ok(comment_directives)
}

