use async_std::sync::Arc;
use drawbridge_type::TagContext;
use crate::store::{Store, GetError};
use anyhow;
use futures::stream::Stream;
use futures::io::AsyncReadExt;
use bytes::Bytes;

fn stream_tag_content(
    store: &Arc<Store>,
    cx: TagContext,
) -> Result<impl futures::Stream<Item = Result<Bytes, std::io::Error>>, GetError<anyhow::Error>> {
    let store = Arc::clone(store);
    let (mut reader, _) = store.get(cx)?;
    let stream = futures::stream::unfold(reader, move |mut reader| {
        async move {
            let mut buffer = [0; 4096];
            match reader.read(&mut buffer).await {
                Ok(0) => None,
                Ok(n) => {
                    let chunk = Bytes::from(&buffer[..n]);
                    Some((Ok(chunk), reader))
                }
                Err(e) => Some((Err(e), reader)),
            }
        }
    });
    Ok(stream)
}

