use std::ffi::c_void;
use crabgrind::memcheck::mempool::{create, destroy, alloc, free, trim, move_to, change, is_exists};

pub struct MemoryPool {
    pool: *mut c_void,
}

impl MemoryPool {
    fn new(size: usize) -> Self {
        unsafe {
            let pool = create(size);
            if pool.is_null() {
                panic!("Failed to create memory pool");
            }
            MemoryPool { pool }
        }
    }

    pub fn alloc(&self, size: usize) -> *mut c_void {
        unsafe {
            alloc(self.pool, size)
        }
    }

    pub fn free(&self, ptr: *mut c_void) {
        unsafe {
            free(self.pool, ptr);
        }
    }

    pub fn trim(&self, size: usize) {
        unsafe {
            trim(self.pool, size);
        }
    }

    pub fn move_to(&self, ptr: *mut c_void, new_pool: *mut c_void) {
        unsafe {
            move_to(self.pool, ptr, new_pool);
        }
    }

    pub fn change(&self, ptr: *mut c_void, new_size: usize) {
        unsafe {
            change(self.pool, ptr, new_size);
        }
    }

    pub fn is_exists(&self, ptr: *mut c_void) -> bool {
        unsafe {
            is_exists(self.pool, ptr)
        }
    }

    pub fn destroy(self) {
        unsafe {
            destroy(self.pool);
        }
    }
}

impl Drop for MemoryPool {
    fn drop(&mut self) {
        self.destroy();
    }
}

impl MemoryPool {
    pub fn create(size: usize) -> Self {
        Self::new(size)
    }
}

fn alloc_zeroed_buffer(size: usize) -> &'static mut [u8] {
    // Calculate the alignment as the size of a word
    let align = WORD_SIZE;
    // Allocate memory with sys_alloc_aligned and ensure it's zero-filled
    let ptr = unsafe { sys_alloc_aligned(size, align) };
    // Ensure the allocation was successful
    assert!(!ptr.is_null(), "Failed to allocate memory");
    // Create a mutable slice from the allocated memory
    let slice = unsafe { slice::from_raw_mut_slice(ptr as *mut u8, size) };
    slice
}

