fn fetch_global_packages() -> Result<Vec<GlobalPackage>> {
    let agent = Agent::new()?;
    let output = agent.run("npm", &["list", "-g", "--json"])?;

    let json: Value = serde_json::from_str(&output)?;

    let packages = json
        .as_object()
        .and_then(|obj| obj.get("dependencies"))
        .and_then(|deps| deps.as_object())
        .into_iter()
        .map(|(name, value)| {
            let version = value
                .as_str()
                .and_then(|s| Version::parse(s).ok())
                .unwrap_or(Version::new(0, 0, 0));

            GlobalPackage::new(name.to_string(), version)
        })
        .collect();

    Ok(packages)
}

use caith::{Roller, Result};
use caith::rollresult;

fn average_total(expr: &str, samples: usize) -> Result<f64> {
    let mut total = 0.0;
    let roller = Roller::new(expr)?;

    for _ in 0..samples {
        if let Ok(result) = roller.roll() {
            total += result.total as f64;
        }
    }

    Ok(total / samples as f64)
}

fn verify_cellbase_reward(&self, resolved: &[Arc<ResolvedTransaction>], parent: &HeaderView) -> Result<(), Error> {
    // Check if there is exactly one cellbase transaction
    let cellbase_tx = resolved
        .iter()
        .find(|tx| tx.transaction().is_cellbase())
        .ok_or(Error::CellbaseNotFound)?;

    // Check if the cellbase is the first transaction
    if cellbase_tx.transaction().index() != 0 {
        return Err(Error::CellbaseNotFirstTransaction);
    }

    // Get the cellbase output
    let cellbase_output = cellbase_tx
        .output()
        .iter()
        .find(|output| output.type_.is_none())
        .ok_or(Error::CellbaseOutputNotFound)?;

    // Check if the cellbase output is a reward output
    if cellbase_output.type_.is_some() {
        return Err(Error::CellbaseOutputNotReward);
    }

    // Calculate expected reward
    let consensus = self.consensus();
    let versionbits_indexer = VersionbitsIndexer::new(consensus);
    let expected_reward = RewardCalculator::new(
        consensus,
        versionbits_indexer,
        parent,
        self.chain_store(),
    )
    .calculate_reward();

    // Check if the cellbase output capacity matches the expected reward
    let cellbase_capacity = cellbase_output.capacity();
    if cellbase_capacity != expected_reward {
        return Err(Error::CellbaseRewardMismatch);
    }

    // Check for finalisation-delay edge case
    if let Some(finalization_delay) = consensus.finalization_delay() {
        let block_number = parent.number();
        let finalization_block = block_number.saturating_add(finalization_delay);
        let finalization_block_height = finalization_block.to_u64();
        let current_block_height = parent.number().to_u64();
        if current_block_height >= finalization_block_height {
            return Err(Error::FinalizationDelayEdgeCase);
        }
    }

    // Check if the cellbase output capacity is sufficient
    if cellbase_capacity < Capacity::zero() {
        return Err(Error::InsufficientCapacity);
    }

    Ok(())
}

pub struct ExponentialBackoffWithJitter {
    base_delay: Duration,
    max_delay: Duration,
    backoff_factor: u32,
    include_jitter: bool,
}

impl ExponentialBackoffWithJitter {
    fn calculate_delay(&self, attempt: u32) -> Duration {
        let mut delay = self.base_delay;
        for _ in 0..attempt {
            delay = delay * Duration::from_secs(self.backoff_factor as u64);
        }
        if self.include_jitter {
            let mut rng = rand::thread_rng();
            let jitter = Duration::from_nanos(rng.gen_range(0..1000000000));
            delay = delay.saturating_add(jitter);
        }
        delay.min(self.max_delay)
    }
}

impl RetryStrategy for ExponentialBackoffWithJitter {
    fn next_backoff(&mut self, attempt: u32, start_time: Instant) -> Option<Duration> {
        let delay = self.calculate_delay(attempt);
        Some(delay)
    }
}

impl ExponentialBackoffWithJitter {
    fn new(base_delay: Duration, max_delay: Duration, backoff_factor: u32, include_jitter: bool) -> Self {
        ExponentialBackoffWithJitter {
            base_delay,
            max_delay,
            backoff_factor,
            include_jitter,
        }
    }
}

