fn send_transaction_with_retry<P, M, C>(
    client: &TpuClient<P, M, C>,
    tx: &Transaction,
    max_retries: usize,
) -> Result<bool, TpuSenderError>
where
    P: ConnectionPool<NewConnectionConfig = C>,
    M: ConnectionManager<ConnectionPool = P, NewConnectionConfig = C>,
    C: NewConnectionConfig,
{
    let mut retries = 0;
    loop {
        match client.send_transaction(tx) {
            Ok(accepted) => {
                if accepted {
                    return Ok(true);
                } else {
                    // Transaction not accepted, retry if within max retries
                    if retries < max_retries {
                        retries += 1;
                        let delay = Duration::from_secs(1 << retries); // Exponential backoff
                        sleep(delay).await.unwrap();
                        continue;
                    } else {
                        return Err(TpuSenderError::TransactionNotAccepted);
                    }
                }
            }
            Err(e) => {
                // Handle other errors, e.g., network issues
                if retries < max_retries {
                    retries += 1;
                    let delay = Duration::from_secs(1 << retries); // Exponential backoff
                    sleep(delay).await.unwrap();
                    continue;
                } else {
                    return Err(e);
                }
            }
        }
    }
}

use image::{RgbImage, Rgb};

fn render_stroke_brush(brush: &StrokeBrush) -> RgbImage {
    let width = brush.canvas_width;
    let height = brush.canvas_height;
    let color = brush.color;

    let mut image = RgbImage::new(width, height);
    for x in 0..width {
        for y in 0..height {
            image.put_pixel(x, y, Rgb([color.red, color.green, color.blue]));
        }
    }

    image
}

fn get_ed25519_offsets(instruction: &Instruction) -> Result<Ed25519SignatureOffsets, PrecompileError> {
    let data = &instruction.data;
    if data.len() < SIGNATURE_OFFSETS_START + SIGNATURE_OFFSETS_SERIALIZED_SIZE {
        return Err(PrecompileError::custom("Instruction data is too short to contain Ed25519 signature offsets"));
    }

    let offsets_bytes = &data[SIGNATURE_OFFSETS_START..SIGNATURE_OFFSETS_START + SIGNATURE_OFFSETS_SERIALIZED_SIZE];
    let offsets = Ed25519SignatureOffsets::try_from(offsets_bytes)
        .map_err(|_| PrecompileError::custom("Failed to parse Ed25519 signature offsets"))?;

    Ok(offsets)
}

use wezterm_dynamic::{Object, Value};

fn get_nested<'a>(obj: &'a Object, path: &[&str]) -> Option<&'a Value> {
    let mut current = obj;
    for &field in path {
        if let Some(next) = current.get(field) {
            current = next;
        } else {
            return None;
        }
    }
    Some(current)
}

use line_drawing::{Bresenham, Point};

fn thick_line(start: Point<i32>, end: Point<i32>, thickness: i32) -> Vec<Point<i32>> {
    let line = Bresenham::new(start, end).points();
    let mut result = Vec::new();
    let direction = end - start;
    let length = direction.x.abs() + direction.y.abs();
    let perp_dir = Point::new(-direction.y, direction.x);
    let perp_dir = perp_dir.normalize();
    let half_thickness = thickness / 2;

    for point in line {
        let offset = perp_dir * half_thickness;
        let left = point + offset;
        let right = point - offset;
        result.push(left);
        result.push(right);
    }

    result
}

fn request<E: Endpoint>(&self, _: &E, req: &mut Request<Vec<u8>>) -> Result<(), ClientError> {
