fn call_with_retry<R>(client: &Client, method: &str, args: &[Box<RawValue>], retries: usize) -> Result<R, Error>
where
    R: for<'de> serde::de::Deserialize<'de>,
{
    let mut retry_count = 0;
    let mut backoff = Duration::from_millis(100);
    let max_retries = retries;

    loop {
        match client.call(method, args) {
            Ok(response) => {
                return Ok(serde_json::from_str(&response).map_err(|e| Error::from(e))?;
            }
            Err(ref err) if is_transport_error(err) => {
                if retry_count < max_retries {
                    retry_count += 1;
                    let sleep_duration = backoff * (1 << retry_count);
                    std::thread::sleep(sleep_duration);
                    backoff = sleep_duration;
                    continue;
                } else {
                    return Err(Error::from(err));
                }
            }
            Err(err) => {
                return Err(Error::from(err));
            }
        }
    }
}

fn is_transport_error(err: &Error) -> bool {
    match err {
        Error::Transport(_) => true,
        _ => false,
    }
}

fn get_current_mint_price(deps: Deps, is_whitelisted: bool, is_admin: bool) -> StdResult<Coin> {
    let config: ParamsResponse = deps.querier.query_wasm_smart(
        CONFIG,
        &vending_factory::msg::QueryMsg::Params {},
    )?;

    let whitelist_config: WhitelistConfigResponse = deps.querier.query_wasm_smart(
        CONFIG,
        &WhitelistQueryMsg::Config {},
    )?;

    // Check if a discount price is set
    if let Some(discount_price) = whitelist_config.discount_price {
        // If the user is whitelisted or admin, return the discount price
        if is_whitelisted || is_admin {
            return Ok(coin(discount_price, config.denom));
        }
    } else {
        // If no discount price, check if the user is admin
        if is_admin {
            return Ok(coin(config.admin_price, config.denom));
        }
    }

    // Default price for non-whitelisted, non-admin users
    Ok(coin(config.default_price, config.denom))
}

