use acir::circuit::Circuit;
use acir::native_types::{WitnessMap, Witness};
use acir_field::FieldElement;

fn witness_map_from_circuit(circuit: &Circuit) -> WitnessMap {
    let mut witness_map = WitnessMap::new();
    for input in &circuit.public_inputs {
        witness_map.insert(*input, Witness::Public(FieldElement::zero()));
    }
    for output in &circuit.return_values {
        witness_map.insert(*output, Witness::Public(FieldElement::zero()));
    }
    witness_map
}

use xml_rpc::client::Client;
use xml_rpc::error::Result;
use hyper::Url;
use serde::{Serialize, Deserialize};
use xml_rpc::xmlfmt::Fault;

fn batch_call<Tkey, Treq, Tres>(uri: &Url, calls: Vec<(Tkey, Treq)>) -> Result<Vec<std::result::Result<Tres, Fault>>>
where
    Tkey: Into<String>,
    Treq: Serialize,
    Tres: Deserialize<'static>,
{
    let client = Client::new(uri)?;
    let mut results = Vec::new();

    for (key, req) in calls {
        let method_name = key.into();
        let response = client.call(&method_name, &req)?;
        let result: std::result::Result<Tres, Fault> = response.into();
        results.push(result);
    }

    Ok(results)
}

pub struct CompressedFileProcessor {
    detector: Detector,
    decompression_options: DecompressionOptions,
}

impl CompressedFileProcessor {
    pub fn new() -> Self {
        CompressedFileProcessor {
            detector: Detector::new(),
            decompression_options: DecompressionOptions::default(),
        }
    }

    pub async fn decompress_file<P: AsRef<Path>>(&self, path: P) -> Result<Bytes, Error> {
        let file = tokio::fs::File::open(path).await?;
        let mut reader = tokio::io::BufReader::new(file);
        let mut buffer = Vec::new();
        reader.read_to_end(&mut buffer).await?;
        self.decompress_bytes(Bytes::from(buffer))
    }

    pub fn decompress_bytes(&self, data: Bytes) -> Result<Bytes, Error> {
        let detected = self.detector.detect(&data);
        if let Some(compression) = detected {
            let decompressed = self
                .decompression_options
                .decompress(data, compression)
                .map_err(|e| anyhow!("Decompression failed: {}", e))?;
            Ok(decompressed)
        } else {
            Ok(data)
        }
    }
}

fn collect_idents(expr: &hir::Expr) -> Vec<String> {
    match &expr.kind {
        ExprKind::Binary(Binary { left, right, .. }) => {
            let mut result = collect_idents(left);
            result.extend(collect_idents(right));
            result
        }
        ExprKind::Literal(_) => Vec::new(),
        ExprKind::Ident(ident) => vec![ident.name.clone()],
        ExprKind::Call { func, args, .. } => {
            let mut result = collect_idents(func);
            for arg in args {
                result.extend(collect_idents(arg));
            }
            result
        }
        ExprKind::If { cond, then, else_ } => {
            let mut result = collect_idents(cond);
            result.extend(collect_idents(then));
            if let Some(else_) = else_ {
                result.extend(collect_idents(else_));
            }
            result
        }
        ExprKind::Let { pat, expr, .. } => {
            let mut result = collect_idents(expr);
            // For patterns, we would need to collect identifiers in the pattern
            // but for simplicity, this example only collects from the expression
            result
        }
        ExprKind::Match { expr, arms, .. } => {
            let mut result = collect_idents(expr);
            for arm in arms {
                result.extend(collect_idents(&arm.expr));
            }
            result
        }
        ExprKind::Block { exprs, .. } => {
            let mut result = Vec::new();
            for expr in exprs {
                result.extend(collect_idents(expr));
            }
            result
        }
        ExprKind::Loop { body, .. } => collect_idents(body),
        ExprKind::Break { expr, .. } => {
            if let Some(expr) = expr {
                collect_idents(expr)
            } else {
                Vec::new()
            }
        }
        ExprKind::Continue => Vec::new(),
        ExprKind::While { cond, body, .. } => {
            let mut result = collect_idents(cond);
            result.extend(collect_idents(body));
            result
        }
        ExprKind::Assign { lhs, rhs, .. } => {
            let mut result = collect_idents(rhs);
            // For lhs, we would need to collect identifiers in the pattern
            // but for simplicity, this example only collects from the expression
            result
        }
        ExprKind::Cast { expr, .. } => collect_idents(expr),
        ExprKind::Tuple { elements, .. } => {
            let mut result = Vec::new();
            for elem in elements {
                result.extend(collect_idents(elem));
            }
            result
        }
        ExprKind::Array { elements, .. } => {
            let mut result = Vec::new();
            for elem in elements {
                result.extend(collect_idents(elem));
            }
            result
        }
        ExprKind::Struct { fields, .. } => {
            let mut result = Vec::new();
            for field in fields {
                result.extend(collect_idents(&field.value));
            }
            result
        }
        ExprKind::Index { expr, index, .. } => {
            let mut result = collect_idents(expr);
            result.extend(collect_idents(index));
            result
        }
        ExprKind::Unary { expr, .. } => collect_idents(expr),
        ExprKind::Range { start, end, .. } => {
            let mut result = collect_idents(start);
            if let Some(end) = end {
                result.extend(collect_idents(end));
            }
            result
        }
        ExprKind::Closure { body, .. } => collect_idents(body),
        ExprKind::Fn { body, .. } => collect_idents(body),
        ExprKind::Return { expr, .. } => {
            if let Some(expr) = expr {
                collect_idents(expr)
            } else {
                Vec::new()
            }
        }
        ExprKind::MacroCall { .. } => Vec::new(),
    }
}

fn reload_plugin(
    manager: &Arc<RwLock<GeyserPluginManager>>,
    name: &str,
    config_path: &Path,
) -> Result<(), String> {
    let manager = manager.read().map_err(|e| format!("Failed to lock plugin manager: {}", e))?;

    // Check if the plugin exists
    if !manager.plugins.contains_key(name) {
        return Err(format!("Plugin '{}' not found", name));
    }

    // Unload the plugin
    match manager.unload_plugin(name) {
        Ok(_) => {
            // Load the new configuration
            let plugin = match manager.load_plugin_from_path(config_path) {
                Ok(plugin) => plugin,
                Err(e) => return Err(format!("Failed to load plugin from {}: {}", config_path.display(), e)),
            };

            // Register the new plugin
            if let Err(e) = manager.register_plugin(plugin) {
                return Err(format!("Failed to register plugin: {}", e));
            }

            Ok(())
        }
        Err(e) => Err(format!("Failed to unload plugin: {}", e)),
    }
}

fn configure_tx_pool(config: &mut TxPoolConfig) {
    // Set a reasonable maximum pool size to balance throughput and memory usage
    config.max_pool_size = 10000;

    // Set a default fee rate threshold to prioritize higher-fee transactions
    config.min_fee_rate = FeeRate::new(1000).unwrap();

    // Set verification cycles to optimize for performance while maintaining validity
    config.verification_cycles = TWO_IN_TWO_OUT_CYCLES;

    // Enable cleanup policy to remove old transactions periodically
    config.cleanup_enabled = true;

    // Set cleanup interval in seconds to control resource usage
    config.cleanup_interval = 60;
}

fn batch_tracks_with_context(
    tracks: Vec<Track>,
    shared_context: Value,
) -> Batch {
    let mut batch = Batch::new();
    for track in tracks {
        let mut merged_context = track.context.clone();
        if let Some(shared) = shared_context.as_object() {
            for (key, value) in shared {
                merged_context.insert(key.clone(), value.clone());
            }
        }
        let track_with_context = Track {
            context: merged_context,
            ..track
        };
        batch.add_message(BatchMessage::Track(track_with_context));
    }
    batch
}

fn variant_to_json_pretty(writer: &mut impl Write, variant: &Variant, indent: usize) -> Result<(), ArrowError> {
