use worker_sys::types::d1::{D1Database, D1PreparedStatement};
use wasm_bindgen_futures::JsFuture;
use wasm_bindgen::JsValue;
use js_sys::Array;

fn run_query(
    db: &D1Database,
    query: &str,
    params: Array,
) -> Result<Array, JsValue> {
    let mut stmt = db.prepare(query)?;
    let result = stmt.execute(params)?;
    let rows = result.rows();
    let mut array = Array::new();
    for row in rows {
        let mut row_array = Array::new();
        for field in row.values() {
            row_array.push(&field);
        }
        array.push(&row_array);
    }
    Ok(array)
}

fn validate_peer_info(peer_info: &str) -> Result<(), String> {
    let parts: Vec<&str> = peer_info.split(':').collect();

    if parts.len() != 2 {
        return Err("Peer info must contain exactly one colon (\":\") to separate IP and port".to_string());
    }

    let ip_part = parts[0];
    let port_part = parts[1];

    let port = match port_part.parse::<u16>() {
        Ok(port) if port >= 1 && port <= 65535 => port,
        _ => return Err("Invalid port number".to_string()),
    };

    let ip = match ip_part.parse::<IpAddr>() {
        Ok(ip) => ip,
        Err(_) => return Err("Invalid IP address".to_string()),
    };

    Ok(())
}

