fn rotate_encryption_key(
    nats_client: &Client,
    secret_bucket: &str,
    old_key: &XKey,
    new_key: &XKey,
) -> Result<()> {
    let js = nats_client.jetstream().context("Failed to get JetStream context")?;
    let subject = format!("secrets.{}", secret_bucket);

    // Fetch all secrets from the bucket
    let mut stream = js
        .stream(secret_bucket)
        .context("Failed to get stream")?
        .subscribe(subject.clone())
        .context("Failed to subscribe to subject")?;

    while let Some(msg) = stream.next().await {
        let msg = msg.context("Failed to receive message")?;
        let data = msg.payload();
        let secret = std::str::from_utf8(data).context("Failed to decode secret data")?;

        // Re-encrypt the secret with the new key
        let reencrypted_secret = re_encrypt(secret, old_key, new_key)
            .context("Failed to re-encrypt secret")?;

        // Publish the re-encrypted secret back to the same subject
        let mut msg = msg.to_owned();
        msg.payload(reencrypted_secret.as_bytes());
        msg.headers_mut().insert("re-encrypted", "true");
        js
            .publish(subject.clone(), msg)
            .await
            .context("Failed to publish re-encrypted secret")?;
    }

    Ok(())
}

