fn validate_contract_expiry(
    api: &dyn LightningFederationApi,
    contract: &OutgoingContract,
    min_delta: u64,
    max_delta: u64,
) -> Result<(), ContractValidationError> {
    let current_block = api.get_block_count()?;
    let expiry_block = contract.expiry_block();

    let delta = expiry_block.saturating_sub(current_block);

    if delta < min_delta {
        return Err(ContractValidationError::ExpiryTooSoon {
            expected: min_delta,
            actual: delta,
        });
    }

    if delta > max_delta {
        return Err(ContractValidationError::ExpiryTooLate {
            expected: max_delta,
            actual: delta,
        });
    }

    Ok(())
}

use crate::convert::generated;

fn filter_transactions_by_reward_type(
    confirmed_block: &generated::ConfirmedBlock,
    reward_type: generated::RewardType,
) -> Vec<generated::ConfirmedTransaction> {
    confirmed_block
        .transactions
        .iter()
        .filter(|tx| {
            if let Some(reward) = &tx.reward {
                reward.reward_type == reward_type
            } else {
                false
            }
        })
        .cloned()
        .collect()
}

fn monitor_transaction_confirmations(
    tpu_client: &TpuClient<_, _, _>,
    signatures: &[Signature],
) -> TransportResult<()> {
    let total = signatures.len();
    let pb = ProgressBar::new(total as u64);
    pb.set_style(ProgressStyle::default_bar()
        .template("{spinner:.green} [{elapsed_precise}] [{bar:40.cyan/blue}] {bytes}/{total_bytes} {msg}")
        .progress_chars("##-"));

    for (i, &sig) in signatures.iter().enumerate() {
        let confirmed = tpu_client.confirm_transaction(&sig)?;
        if confirmed {
            pb.println(format!("Transaction confirmed: {}", sig));
        } else {
            pb.println(format!("Transaction not confirmed yet: {}", sig));
        }
        pb.inc(1);
        sleep(Duration::from_millis(500)).await;
    }

    pb.finish_with_message("All transactions processed");
    Ok(())
}

fn validate_whitelist_stage_mint_limit(
    deps: Deps,
    info: &MessageInfo,
) -> Result<(), ContractError> {
    let config: WhitelistConfigResponse = CONFIG.load(deps.storage)?;
    let minter_addrs = match config.stage {
        1 => WHITELIST_FS_MINTER_ADDRS.load(deps.storage)?,
        2 => WHITELIST_SS_MINTER_ADDRS.load(deps.storage)?,
        3 => WHITELIST_TS_MINTER_ADDRS.load(deps.storage)?,
        _ => return Err(ContractError::InvalidStage {}),
    };

    if !minter_addrs.contains(&info.sender) {
        return Err(ContractError::Unauthorized {});
    }

    let stage_response: StageResponse = TieredWhitelistQueryMsg::Stage {}.query(deps.as_ref())?;
    let current_stage = stage_response.stage;

    let max_mint_per_stage = match current_stage {
        1 => 1,
        2 => 2,
        3 => 3,
        _ => return Err(ContractError::InvalidStage {}),
    };

    let user_mint_count: u32 = match current_stage {
        1 => {
            let count: u32 = deps.querier.query_wasm_smart(
                WHITELIST_FS_MINTER_ADDRS.address(),
                &WhitelistQueryMsg::UserMintCount {
                    user_addr: info.sender.clone(),
                },
            )?;
            count
        }
        2 => {
            let count: u32 = deps.querier.query_wasm_smart(
                WHITELIST_SS_MINTER_ADDRS.address(),
                &WhitelistQueryMsg::UserMintCount {
                    user_addr: info.sender.clone(),
                },
            )?;
            count
        }
        3 => {
            let count: u32 = deps.querier.query_wasm_smart(
                WHITELIST_TS_MINTER_ADDRS.address(),
                &WhitelistQueryMsg::UserMintCount {
                    user_addr: info.sender.clone(),
                },
            )?;
            count
        }
        _ => return Err(ContractError::InvalidStage {}),
    };

    if user_mint_count >= max_mint_per_stage {
        return Err(ContractError::MintLimitExceeded {});
    }

    Ok(())
}

fn cancel_outgoing_contract(&self, contract_id: ContractId) -> Result<TransactionId, anyhow::Error> {
    let context = self.context();
    let module_api = self.module_api();
    let contract = module_api.get_contract(contract_id)?;
    let contract = contract.downcast_ref::<OutgoingContractAccount>().ok_or(anyhow::anyhow!("Contract is not an outgoing contract"))?;

    let contract = contract
        .contracts()
        .iter()
        .find(|c| c.contract_id() == &contract_id)
        .ok_or(anyhow::anyhow!("Contract not found"))?;

    let amount = contract.amount();
    let funding_output = contract.funding_output()?;
    let funding_tx = funding_output.funding_tx();

    let secp = Secp256k1::new();
    let message = Message::from_slice(&funding_tx.id().as_bytes()).map_err(|e| anyhow::anyhow!("Failed to create message from tx id"))?;
    let signature = secp.sign(&message, &contract.signing_key())?;

    let output = LightningOutput::new(
        contract_id,
        amount,
        signature,
        funding_output.output(),
    );

    let mut outputs = vec![output];
    let mut client_outputs = vec![];

    for output in outputs {
        let client_output = ClientOutput::new(output, funding_tx, None);
        client_outputs.push(client_output);
    }

    let client_output_bundle = ClientOutputBundle::new(client_outputs);
    let transaction_id = module_api.create_transaction(client_output_bundle)?;

    Ok(transaction_id)
}

fn verify_entries_with_report(entries: &[Entry], start_hash: &Hash) -> Vec<VerificationReport> {
    let mut reports = Vec::new();
    let mut current_hash = *start_hash;

    for (index, entry) in entries.iter().enumerate() {
        let expected_hash = current_hash;
        let actual_hash = entry.hash();

        if expected_hash != actual_hash {
            reports.push(VerificationReport {
                index,
                entry_hash: actual_hash,
                expected_hash,
                reason: "Hash mismatch between entry and previous hash".to_string(),
            });
        }

        current_hash = actual_hash;
    }

    reports
}

#[derive(Debug, Clone)]
struct VerificationReport {
    index: usize,
    entry_hash: Hash,
    expected_hash: Hash,
    reason: String,
}

fn merge(&self, other: &StlData) -> Self {
    let mut triangles = self.triangles.clone();
    triangles.extend_from_slice(&other.triangles);
    let mut normals = self.normals.clone();
    normals.extend_from_slice(&other.normals);
    let name = format!("{} + {}", self.name, other.name);
    let header = self.header.clone();
    let encoding = self.encoding.clone();
    let force_normals = self.force_normals;
    let disable_normals = self.disable_normals;
    let nullify_normals = self.nullify_normals;

    StlData {
        triangles,
        normals,
        name,
        header,
        encoding,
        force_normals,
        disable_normals,
        nullify_normals,
    }
}

