fn batch_insert_with_version<T>(
    pool: &PgC3p0Pool,
    records: &[NewModel<Value>],
) -> Result<Vec<Model<u64, Value>>, C3p0Error>
where
    T: C3p0Json<Id = u64, Data = Value>,
{
    let conn = pool.get().map_err(|e| C3p0Error::ConnectionError(e.to_string()))?;
    let mut transaction = conn.begin().map_err(|e| C3p0Error::DatabaseError(e.to_string()))?;

    let mut models = Vec::new();

    for record in records {
        let model = T::insert(&mut transaction, record)
            .map_err(|e| C3p0Error::DatabaseError(e.to_string()))?;
        models.push(model);
    }

    transaction.commit().map_err(|e| C3p0Error::DatabaseError(e.to_string()))?;

    Ok(models)
}

