use crate::client_error::Result;

fn get_cached_blockhash(
    cache: &Arc<RwLock<Option<(Hash, u64, Instant)>>>,
    rpc: &RpcClient,
    commitment: CommitmentConfig,
    ttl: Duration,
) -> Result<(Hash, u64)> {
    let mut cache_entry = cache.write().unwrap();
    let now = Instant::now();

    if let Some((blockhash, last_valid_block_height, cached_time)) = cache_entry {
        if now - cached_time < ttl {
            return Ok((blockhash, last_valid_block_height));
        }
    }

    let (blockhash, last_valid_block_height) = rpc.get_latest_blockhash_with_commitment(commitment)?;
    *cache_entry = Some((blockhash, last_valid_block_height, now));
    Ok((blockhash, last_valid_block_height))
}

use iptools::error::Result;
use iptools::iprange::{IpRange, IPv4};
use iptools::ipv4;

fn merge_ipv4_cidrs(cidr_list: &[&str]) -> Result<Vec<IpRange<IPv4>>> {
    let mut ranges: Vec<IpRange<IPv4>> = Vec::new();
    for &cidr in cidr_list {
        let range = ipv4::from_str(cidr)?;
        ranges.push(range);
    }

    // Sort ranges by starting IP
    ranges.sort_by(|a, b| a.start().cmp(b.start()));

    let mut merged = Vec::new();
    if let Some(first) = ranges.first() {
        merged.push(first.clone());
    }

    for range in ranges.iter().skip(1) {
        let last = merged.last().unwrap();
        if last.end().ge(range.start()) {
            // Overlapping or adjacent, merge them
            let new_start = last.start();
            let new_end = std::cmp::max(last.end(), range.end());
            let mut merged_last = merged.pop().unwrap();
            merged_last.set_end(new_end);
            merged.push(merged_last);
        } else {
            merged.push(range.clone());
        }
    }

    Ok(merged)
}

use jwks_client::keyset::KeyStore;
use jwks_client::error;
use serde_json::Value;
use std::collections::HashMap;

fn verify_tokens(tokens: &[&str], jwks_url: &str) -> Result<Vec<serde_json::Value>, error::Error> {
    let mut key_store = KeyStore::new();
    let keys = key_store.load_keys(jwks_url)?;

    let mut verified_payloads = Vec::new();

    for &token in tokens {
        let payload = verify_token(token, &keys)?;
        verified_payloads.push(payload);
    }

    Ok(verified_payloads)
}

fn verify_token(token: &str, keys: &[HashMap<String, Value>]) -> Result<Value, error::Error> {
    for key in keys {
        if let Some(nbf) = key.get("nbf") {
            if let Some(nbf_val) = nbf.as_i64() {
                if nbf_val > (chrono::Utc::now().timestamp() as i64) {
                    continue;
                }
            }
        }

        if let Some(exp) = key.get("exp") {
            if let Some(exp_val) = exp.as_i64() {
                if exp_val < (chrono::Utc::now().timestamp() as i64) {
                    continue;
                }
            }
        }

        let mut header = HashMap::new();
        let mut payload = HashMap::new();

        let parts: Vec<&str> = token.split('.').collect();
        if parts.len() != 3 {
            return Err(error::Error::InvalidToken);
        }

        let header_str = parts[0];
        let payload_str = parts[1];
        let signature_str = parts[2];

        let header = serde_json::from_str(header_str).map_err(|_| error::Error::InvalidToken)?;
        let payload = serde_json::from_str(payload_str).map_err(|_| error::Error::InvalidToken)?;

        header.into_iter().for_each(|(k, v)| {
            header.insert(k, v);
        });

        payload.into_iter().for_each(|(k, v)| {
            payload.insert(k, v);
        });

        let mut verified = false;
        for key in keys {
            if let Some(kid) = header.get("kid") {
                if let Some(kid_str) = kid.as_str() {
                    if key.get("kid") == Some(&Value::String(kid_str.to_string())) {
                        verified = true;
                        break;
                    }
                }
            }
        }

        if verified {
            return Ok(payload);
        }
    }

    Err(error::Error::InvalidToken)
}

