use sha1_smol::Sha1;
use std::fs::File;
use std::io::{BufReader, Read};
use std::path::Path;

pub fn compute_file_sha1(path: &Path) -> std::io::Result<String> {
    let file = File::open(path)?;
    let mut reader = BufReader::new(file);
    let mut sha1 = Sha1::new();
    let mut buffer = [0u8; 8192];
    loop {
        let n = reader.read(&mut buffer)?;
        if n == 0 {
            break;
        }
        sha1.update(&buffer[..n]);
    }
    Ok(sha1.digest().to_string())
}

use std::collections::HashMap;
use actix::Addr;
use near_primitives::hash::CryptoHash;
use near_primitives::views::ReceiptView;
use near_indexer_primitives::IndexerExecutionOutcomeWithOptionalReceipt;
use near_epoch_manager::shard_tracker::ShardTracker;
use crate::streamer::fetchers::{fetch_block, fetch_block_new_chunks, fetch_outcomes};
use crate::streamer::errors::FailedToFetchData;

fn fetch_all_receipts_for_block(client: &Addr<near_client::ViewClientActor>, block_hash: CryptoHash, shard_tracker: &ShardTracker) -> Result<HashMap<CryptoHash, ReceiptView>, FailedToFetchData> {
    let mut receipts = HashMap::new();

    // Fetch the block to get its chunk hashes
    let block = fetch_block(client, block_hash)?;
    let chunk_hashes = block.chunks.iter().map(|chunk| chunk.hash).collect::<Vec<_>>();

    // Fetch new chunks for the block
    for chunk_hash in chunk_hashes {
        let chunks = fetch_block_new_chunks(client, block_hash, chunk_hash)?;
        for chunk in chunks {
            if let Some(receipts_in_chunk) = chunk.receipts {
                for receipt in receipts_in_chunk {
                    receipts.insert(receipt.hash, receipt);
                }
            }
        }
    }

    // Fetch execution outcomes for the block to get receipts attached to outcomes
    let outcomes = fetch_outcomes(client, block_hash)?;
    for outcome in outcomes {
        if let Some(receipt) = outcome.receipt {
            receipts.insert(receipt.hash, receipt);
        }
    }

    Ok(receipts)
}

