use libp2p_core::multiaddr::{Multiaddr, Protocol};
use libp2p_identity::PeerId;

fn filter_observed_addresses(observed: &[Multiaddr], local_peer: PeerId) -> Vec<Multiaddr> {
    observed
        .iter()
        .filter(|&&addr| {
            // Check if the address ends with the local peer's PeerId
            if let Some(last) = addr.last_protocol() {
                if let Some(Protocol::P2p(peer_id)) = last {
                    return peer_id == local_peer;
                }
            }
            false
        })
        .filter(|&&addr| {
            // Check if the address is not a relayed address
            !addr.iter().any(|protocol| protocol == &Protocol::Relay)
        })
        .cloned()
        .collect()
}

use std::path::Path;
use std::io::Read;
use json5::parse;

fn validate_plugin_config(config_path: &Path) -> Result<(), String> {
    let mut file = std::fs::File::open(config_path).map_err(|e| e.to_string())?;
    let mut contents = String::new();
    file.read_to_string(&mut contents).map_err(|e| e.to_string())?;

    let json: json5::Value = parse(&contents).map_err(|e| e.to_string())?;

    if !json.is_object() {
        return Err("Configuration file is not a JSON object".to_string());
    }

    let obj = json.as_object().unwrap();

    if !obj.contains_key("name") {
        return Err("Missing required field 'name' in configuration".to_string());
    }

    if !obj.contains_key("libpath") {
        return Err("Missing required field 'libpath' in configuration".to_string());
    }

    Ok(())
}

use anyhow::{Context, Result};
use std::collections::HashMap;

fn parse_custom_headers(headers: &[String]) -> Result<HashMap<String, String>, anyhow::Error> {
    let mut map = HashMap::new();
    for header in headers {
        let mut parts = header.split('=');
        let key = parts
            .next()
            .context("Missing key in header")?;
        let value = parts
            .next()
            .context("Missing value in header")?;
        map.insert(key.to_string(), value.to_string());
    }
    Ok(map)
}

