fn clear_all<K, V, E, B>(cache: &crate::cache_api::LoadingCache<K, V, E, B>) -> Result<(), crate::cache_api::CacheLoadingError<E>>
where
    K: Clone + Eq + std::hash::Hash + Send + 'static,
    V: Clone + Send + 'static,
    E: std::fmt::Debug + Clone + Send + 'static,
    B: crate::backing::CacheBacking<K, crate::cache_api::CacheEntry<V, E>> + Send + 'static,
{
    // Clear the cache entries
    cache.clear()?;

    // Abort any pending loads by dropping the cache's internal load futures
    // This may require a mechanism to track and cancel ongoing loads
    // For the sake of this example, we'll assume the cache has a method to abort pending loads
    cache.abort_pending_loads()?;

    Ok(())
}

