fn generate_migration_sql(paths: &[&std::path::Path], config: &Config) -> Result<String> {
    let schema = Schema::from_paths(paths)?;
    let mut sql = String::new();
    for table in schema.tables() {
        let table_name = table.name();
        let columns = table.columns();
        let mut columns_sql = Vec::new();
        for column in columns {
            let column_name = column.name();
            let column_type = column.data_type();
            let nullable = column.nullable();
            let default = column.default();
            let mut column_sql = format!("{} {}", column_name, column_type);
            if !nullable {
                column_sql.push_str(" NOT NULL");
            }
            if let Some(default) = default {
                column_sql.push_str(&format!(" DEFAULT {}", default));
            }
            columns_sql.push(column_sql);
        }
        let columns_sql = columns_sql.join(", ");
        sql.push_str(&format!("CREATE TABLE {} ({})\n", table_name, columns_sql));
    }
    Ok(sql)
}

