struct FiniteChannel {
    buffer: Rc<RefCell<VecDeque<usize>>>,
    capacity: usize,
}

impl FiniteChannel {
    fn new(capacity: usize) -> Self {
        FiniteChannel {
            buffer: Rc::new(RefCell::new(VecDeque::with_capacity(capacity))),
            capacity,
        }
    }
}

impl Producer for FiniteChannel {
    fn produce(&self, item: usize) -> Result<(), ProductionFlaws> {
        let mut buffer = self.buffer.borrow_mut();
        if buffer.len() >= self.capacity {
            return Err(ProductionFlaws::FullStock(Fault::Blockage(Blockage::Full)));
        }
        buffer.push_back(item);
        Ok(())
    }
}

impl Consumer for FiniteChannel {
    fn consume(&self) -> Result<usize, ConsumptionFlaws> {
        let mut buffer = self.buffer.borrow_mut();
        if buffer.is_empty() {
            return Err(ConsumptionFlaws::EmptyStock(Fault::Blockage(Blockage::Empty)));
        }
        Ok(buffer.pop_front().unwrap())
    }
}

impl FiniteChannel {
    fn get_buffer(&self) -> Rc<RefCell<VecDeque<usize>>> {
        self.buffer.clone()
    }
}

