fn send_with_retry(
    lightning: &LightningClientModule,
    invoice: Bolt11Invoice,
    max_retries: u8,
) -> Result<OperationId, SendPaymentError> {
    let mut retries = 0;
    let mut current_gateway = 0;

    loop {
        if retries >= max_retries {
            return Err(SendPaymentError::MaxRetriesExceeded);
        }

        let gateways = lightning.get_gateways();
        if gateways.is_empty() {
            return Err(SendPaymentError::NoGatewaysAvailable);
        }

        let gateway = gateways[current_gateway % gateways.len()];
        let operation_id = match lightning.send_payment(gateway, invoice.clone()) {
            Ok(id) => return Ok(id),
            Err(SendPaymentError::GatewayNotAvailable) => {
                retries += 1;
                current_gateway = (current_gateway + 1) % gateways.len();
                continue;
            }
            Err(e) => return Err(e),
        };
    }
}

