use petal_clustering::{Optics, Fit};
use petal_neighbors::distance::Euclidean;
use ndarray::Array2;
use petal_neighbors::knn::KNN;

fn auto_eps_optics(
    data: &Array2<f64>,
    min_samples: usize,
) -> Optics<f64, Euclidean> {
    let n_samples = data.nrows();
    let mut distances = Vec::with_capacity(n_samples);

    for i in 0..n_samples {
        let mut knn = KNN::new(min_samples);
        knn.fit(data.view());
        let dist = knn.kneighbors(&data.row(i).into_dyn()).unwrap()[min_samples - 1];
        distances.push(dist);
    }

    let avg_eps = distances.iter().sum::<f64>() / distances.len() as f64;

    Optics::new(data, Euclidean, avg_eps)
}

fn filter_packages_by_architecture<P: AsRef<std::path::Path>>(paths: &[P], arch: &str) -> Vec<std::path::PathBuf> {
    paths.iter()
        .filter_map(|path| {
            let path_buf = path.as_ref().to_path_buf();
            let file = match File::open(&path_buf) {
                Ok(file) => file,
                Err(_) => return None,
            };

            let deb_pkg = match DebPkg::from_reader(file) {
                Ok(pkg) => pkg,
                Err(_) => return None,
            };

            let control = match deb_pkg.control() {
                Ok(ctrl) => ctrl,
                Err(_) => return None,
            };

            let architecture = control.get("Architecture").unwrap_or("");

            if architecture == arch {
                Some(path_buf)
            } else {
                None
            }
        })
        .collect()
}

fn progress_percentage(&self) -> f64 {
    let inner = self.inner.lock().unwrap();
    let total = self.len;
    let downloaded = inner.requested_range.end - inner.requested_range.start;
    if total == 0 {
        return 0.0;
    }
    downloaded as f64 / total as f64
}

