fn fuzz_multiple_types<T1, T2, F>(mut closure: F)
where
    T1: arbitrary::Arbitrary<'static> + std::fmt::Debug,
    T2: arbitrary::Arbitrary<'static> + std::fmt::Debug,
    F: FnMut(&[u8]),
{
    let mut u = Unstructured::new(&afl::input());
    let mut data = vec![];

    if let Ok(t1) = T1::arbitrary(&mut u) {
        data.extend_from_slice(&afl::serialize(&t1));
    }

    if let Ok(t2) = T2::arbitrary(&mut u) {
        data.extend_from_slice(&afl::serialize(&t2));
    }

    if !data.is_empty() {
        closure(&data);
    }
}

fn verify_and_execute<V, E>(
    verifier: &V,
    executor: &E,
    sealed_block: &SealedBlock,
) -> Result<UncommittedResult<Changes>, Error>
where
    V: BlockVerifier,
    E: Validator,
{
    let verification_result = verifier.verify_block(sealed_block)?;
    let validation_result = executor.validate_block(sealed_block)?;

    if verification_result != UncommittedValidationResult::Valid {
        return Err(Error::InvalidBlockVerification);
    }

    if validation_result != UncommittedValidationResult::Valid {
        return Err(Error::InvalidBlockValidation);
    }

    let uncommitted_result = executor.execute_block(sealed_block)?;
    Ok(uncommitted_result)
}

use netlink_packet_generic::ctrl::nlas::{GenlCtrlAttrs, PolicyAttr, NlaType};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AttributePolicy {
    pub index: u16,
    pub ty: Option<NlaType>,
    pub min_len: Option<u32>,
    pub max_len: Option<u32>,
    pub min_val: Option<u64>,
    pub max_val: Option<u64>,
    pub mask: Option<u64>,
    pub bitfield_mask: Option<u32>,
}

fn parse_policy(attr: &GenlCtrlAttrs) -> Option<Vec<AttributePolicy>> {
    let mut policies = Vec::new();
    let policy_attr = match attr.get(PolicyAttr::type_id()) {
        Some(nla) => nla,
        None => return None,
    };

    let policy_data = match policy_attr.parse() {
        Ok(data) => data,
        Err(_) => return None,
    };

    for (index, policy) in policy_data.iter().enumerate() {
        let mut policy_entry = AttributePolicy {
            index: index as u16,
            ty: None,
            min_len: None,
            max_len: None,
            min_val: None,
            max_val: None,
            mask: None,
            bitfield_mask: None,
        };

        if let Some(ty) = policy.ty {
            policy_entry.ty = Some(ty);
        }

        if let Some(min_len) = policy.min_len {
            policy_entry.min_len = Some(min_len);
        }

        if let Some(max_len) = policy.max_len {
            policy_entry.max_len = Some(max_len);
        }

        if let Some(min_val) = policy.min_val {
            policy_entry.min_val = Some(min_val);
        }

        if let Some(max_val) = policy.max_val {
            policy_entry.max_val = Some(max_val);
        }

        if let Some(mask) = policy.mask {
            policy_entry.mask = Some(mask);
        }

        if let Some(bitfield_mask) = policy.bitfield_mask {
            policy_entry.bitfield_mask = Some(bitfield_mask);
        }

        policies.push(policy_entry);
    }

    Some(policies)
}

