fn last_business_day_of_quarter(date: NaiveDate) -> NaiveDate {
    let quarter_start = date.signed_duration_since(date.num_days_from_someday(0))
        .num_days() / 91 + 1;
    let quarter_start_date = date.signed_duration_since(quarter_start)
        .num_days() as i64;
    let quarter_start_date = NaiveDate::from_ymd(
        date.year(),
        ((date.month() - 1) / 3) * 3 + 1,
        1,
    );

    let mut last_day_of_quarter = NaiveDate::from_ymd(
        date.year(),
        ((date.month() - 1) / 3 + 1) * 3,
        1,
    )
    .last_day_of_month();

    while last_day_of_quarter.weekday() > Weekday::Fri {
        last_day_of_quarter = last_day_of_quarter.signed_duration_since(1).num_days() as i64;
    }

    last_day_of_quarter
}

fn read_message<R>(reader: &mut PartialRead<R>) -> std::io::Result<Vec<u8>>
where
    R: std::io::Read,
{
    let mut length_buffer = [0u8; 4];
    let mut payload = Vec::new();

    // Read the length prefix
    let length_bytes_read = reader.read(&mut length_buffer)?;
    if length_bytes_read < 4 {
        return Err(std::io::Error::new(
            ErrorKind::Incomplete,
            "Incomplete length prefix",
        ));
    }

    let length = u32::from_be_bytes(length_buffer) as usize;

    // Read the payload
    let mut payload_buffer = vec![0u8; length];
    let payload_bytes_read = reader.read(&mut payload_buffer)?;

    if payload_bytes_read < length {
        return Err(std::io::Error::new(
            ErrorKind::Incomplete,
            "Incomplete payload",
        ));
    }

    payload = payload_buffer;

    Ok(payload)
}

fn websocket_connector_with_overrides(
    peers: BTreeMap<PeerId, SafeUrl>,
    api_secret: Option<String>,
) -> anyhow::Result<WebsocketConnector> {
    let overrides = parse_kv_list_from_env(FM_WS_API_CONNECT_OVERRIDES_ENV)?
        .into_iter()
        .map(|(k, v)| (k.parse()?, v.parse()?))
        .collect::<Result<BTreeMap<PeerId, SafeUrl>>>()?;

    let mut connector_peers = peers.into_iter().collect::<BTreeMap<_, _>>();

    for (peer_id, url) in overrides {
        if let Some(existing) = connector_peers.get_mut(&peer_id) {
            *existing = url;
        } else {
            connector_peers.insert(peer_id, url);
        }
    }

