fn normalize_output_path(path: &str) -> Result<String, Error> {
    let path_buf = Path::new(path);
    if !path_buf.is_absolute() {
        let current_dir = env::current_dir()?;
        let absolute_path = current_dir.join(path_buf);
        if absolute_path.exists() {
            return Ok(absolute_path.to_string_lossy().into());
        }
        return Err(Error::new(ErrorKind::InvalidPath, "Provided path is not absolute and does not exist"));
    }

    if path_buf.exists() {
        Ok(path_buf.to_string_lossy().into())
    } else {
        Err(Error::new(ErrorKind::InvalidPath, "Provided path does not exist"))
    }
}

use imgproc::colorcvt::assert;
use yuv_sys;

fn nv12_to_rgb24_with_flip(
    src_y: &[u8],
    src_stride_y: u32,
    src_uv: &[u8],
    src_stride_uv: u32,
    dst_rgb24: &mut [u8],
    dst_stride_rgb24: u32,
    width: u32,
    height: u32,
    flip_y: bool,
) {
    assert!(src_y.len() >= (width * height) as usize, "Invalid Y buffer size");
    assert!(src_uv.len() >= (width * height / 4) as usize, "Invalid UV buffer size");
    assert!(dst_rgb24.len() >= (width * height * 3) as usize, "Invalid RGB24 buffer size");

    let src_y_data = src_y;
    let src_uv_data = src_uv;
    let dst_rgb24_data = dst_rgb24;

    let src_y_ptr = src_y_data.as_ptr();
    let src_uv_ptr = src_uv_data.as_ptr();
    let dst_rgb24_ptr = dst_rgb24_data.as_mut_ptr();

    let mut y_plane = yuv_sys::Plane {
        data: src_y_ptr,
        stride: src_stride_y,
        height: height,
        width: width,
    };

    let mut uv_plane = yuv_sys::Plane {
        data: src_uv_ptr,
        stride: src_stride_uv,
        height: height / 2,
        width: width / 2,
    };

    let mut rgb_plane = yuv_sys::Plane {
        data: dst_rgb24_ptr,
        stride: dst_stride_rgb24,
        height: height,
        width: width,
    };

    if flip_y {
        yuv_sys::flip_plane(&mut y_plane, yuv_sys::FlipDirection::Vertical);
    }

    unsafe {
        yuv_sys::nv12_to_rgb24(&mut y_plane, &mut uv_plane, &mut rgb_plane);
    }
}

fn execute_batch(
    db: &dyn sqlness::Database,
    ctx: QueryContext,
    sql: String,
) -> Vec<Box<dyn Display>> {
    let mut results = Vec::new();
    let mut current_query = String::new();
    let delimiter = DELIMITER;

    for line in sql.lines() {
        if line.trim() == delimiter {
            if !current_query.is_empty() {
                let query = current_query.clone();
                current_query.clear();
                if let Ok(stmt) = query.parse::<sqlness::Statement>() {
                    let result = db.execute(&stmt, &ctx);
                    if let Ok(output) = result {
                        results.push(Box::new(output));
                    }
                }
            }
        } else {
            current_query.push_str(line);
            current_query.push('\n');
        }
    }

    // Process the last query if it wasn't followed by a delimiter
    if !current_query.is_empty() {
        let query = current_query.clone();
        current_query.clear();
        if let Ok(stmt) = query.parse::<sqlness::Statement>() {
            let result = db.execute(&stmt, &ctx);
            if let Ok(output) = result {
                results.push(Box::new(output));
            }
        }
    }

    results
}

use sikula::prelude::*;
