fn filter_by_author<'a>(query: &str, items: &[DeriveResource<'a>]) -> Result<Vec<&DeriveResource<'a>>, Error> {
    let authors = parse_author_query(query)?;
    let filtered: Vec<&DeriveResource<'a>> = items.iter().filter(|item| {
        item.qualifiers().iter().any(|qual| {
            if let Some(author) = qual.get("Author") {
                authors.contains(author)
            } else {
                false
            }
        })
    }).collect();
    Ok(filtered)
}

fn parse_author_query(query: &str) -> Result<Vec<String>, Error> {
    let mut authors = Vec::new();
    let mut parser = QueryParser::new();
    parser.parse(query)?;
    for token in parser.tokens() {
        if let Token::Value(value) = token {
            authors.push(value.to_string());
        }
    }
    Ok(authors)
}

fn try_add_candidate(&mut self, mut addr: Multiaddr) -> Result<(), &'static str> {
    // Check if the address is a direct address
    if !addr.iter().any(|p| p == &Protocol::P2p) {
        return Err("Address must be a direct address (contain /p2p/)");
    }

    // Check if the address ends with the local PeerId
    if let Some(last) = addr.iter().last() {
        if let Some(Protocol::P2p(peer_id)) = last {
            if peer_id != self.local_peer_id() {
                return Err("Address must end with the local PeerId");
            }
        } else {
            return Err("Address must end with the local PeerId");
        }
    }

    // Add the validated address to the candidate pool
    self.behaviour.add_address(addr);

    Ok(())
}

fn validate_bitcoin_rpc_config(config: &BitcoinRpcConfig) -> Result<()> {
    let client = Client::new();
    let url = format!("http://{}:{}/", config.user, config.pass);
    let headers = reqwest::header::HeaderMap::new();
    let mut params = serde_json::Map::new();
    params.insert("jsonrpc".to_string(), "2.0".into());
    params.insert("id".to_string(), "1".into());
    params.insert("method".to_string(), "getblockchaininfo".into());

    let body = serde_json::to_string(&params).unwrap();
    let res = client.post(url)
        .headers(headers)
        .body(body)
        .send()
        .map_err(|e| anyhow!("Failed to send request: {}", e))?;

    if !res.status().is_success() {
        return Err(anyhow!("RPC request failed with status: {}", res.status()));
    }

    let json_response: Value = res.json().map_err(|e| anyhow!("Failed to parse JSON response: {}", e))?;
    let network = json_response["result"]["chain"].as_str().ok_or(anyhow!("Failed to get network from response"))?;
    let expected_network = match config.network {
        Network::Mainnet => "main",
        Network::Testnet => "test",
        Network::Regtest => "regtest",
    };

    if network != expected_network {
        return Err(anyhow!("Expected network: {}, got: {}", expected_network, network));
    }

    Ok(())
}

fn serve_embedded_file<F>(file: F) -> actix_web::HttpResponse
where
    F: rust_embed_for_web::EmbedableFile,
{
    let content_type = match file.content_type() {
        Some(ct) => ct,
        None => "application/octet-stream",
    };

    let last_modified = file.last_modified().map(|tm| tm.to_string());

    let etag = file.etag().map(|etag| etag.to_string());

    let body = file.data().to_vec();

    let mut response = HttpResponse::Ok()
        .content_type(content_type)
        .insert_header(("Last-Modified", last_modified.unwrap_or_default()))
        .insert_header(("ETag", etag.unwrap_or_default()))
        .body(body);

    response
}

fn handle_intercepted_htlc(module: &GatewayClientModule, htlc: Htlc) -> anyhow::Result<OperationId> {
    let amount = Amount::from_sat(htlc.amount);
    let output = LightningOutputV0::new(
        amount,
        htlc.payment_hash,
        htlc.payment_secret,
        htlc.redeem_script,
    );
    let output_id = output.id();
    let output_bundle = ClientOutputBundle::new(
        OutPointRange::new(0, 1),
        vec![ClientOutput::Lightning(output)],
    );

    let mut tx_builder = TransactionBuilder::new();
    tx_builder.add_output(output_bundle);

    let tx = tx_builder.build()?;
    let operation_id = module.create_operation(OperationId::new(), tx)?;

    module.log_event(IncomingPaymentStarted {
        operation_id,
        amount,
        gateway_meta: GatewayMeta {
            output_id,
            payment_hash: htlc.payment_hash,
        },
    });

    Ok(operation_id)
}

fn calculate_cumulative_pnl_for_fund(
    db: &Database,
    fund_name: &str,
) -> Result<Decimal, Box<dyn std::error::Error>> {
    let collection = db.collection("position_logs");

    let filter = doc! { "fund_name": fund_name };

    let mut total_pnl = Decimal::zero();

    let mut options = FindOptions::default();
    options.skip = 0;
    options.limit = None;

    let mut cursor = collection.find(filter, Some(options))?;

    while let Some(result) = cursor.next().await {
        let position_log: PositionLog = result?;
        total_pnl += position_log.pnl;
    }

    Ok(total_pnl)
}

