use tini::Ini;

fn merge_inis(base: Ini, overlay: Ini) -> Ini {
    let mut merged = base;
    for (section, overlay_section) in overlay.sections() {
        merged.insert_section(section);
        for (key, value) in overlay_section.entries() {
            merged.set(section, key, value);
        }
    }
    merged
}

fn list_logs_with_prefix(
    &self,
    start_after: Option<&MutationRangeKey>,
    limit: u64,
    prefix: &str,
) -> Result<Vec<MutationRangeEntry>> {
    let s3_client = self.s3_client();
    let mut entries = Vec::new();
    let mut continuation_token = start_after.map(|k| k.to_string());

    loop {
        let request = self
            .s3_client()
            .list_objects_v2()
            .bucket(self.bucket_name())
            .prefix(prefix)
            .max_keys(limit as i64)
            .set_continuation_token(continuation_token.as_deref());

        let response = request.send().map_err(|e| anyhow!("Failed to list objects: {}", e))?;

        for obj in response.contents {
            let key = obj.key.unwrap_or_default();
            let mut entry = MutationRangeEntry::try_from(key)?;
            entries.push(entry);
        }

        if response.is_truncated {
            continuation_token = Some(response.next_continuation_token.unwrap_or_default());
        } else {
            break;
        }

        if entries.len() as u64 >= limit {
            break;
        }
    }

    Ok(entries)
}

use yadf::fs::{find_dupes_partial, filter::FileFilter};
use yadf::hasher::Hasher;
use std::collections::HashMap;
use std::path::PathBuf;

fn compute_hashes<H, P>(dirs: &[P]) -> HashMap<PathBuf, H::Hash>
where
    H: Hasher,
    P: AsRef<PathBuf>,
{
    let mut result = HashMap::new();
    let mut file_filter = FileFilter::new();
    let mut hasher = H::default();

    for dir in dirs {
        let dir_path = dir.as_ref();
        if !dir_path.exists() {
            continue;
        }

        let files = find_dupes_partial(dir_path, &mut file_filter, &mut hasher);
        for file in files {
            if let Ok(path) = file.path().strip_prefix(dir_path) {
                result.insert(path.to_path_buf(), file.hash());
            }
        }
    }

    result
}

