use crate::{Table, Constraint};

fn generate_create_sql(table: &Table) -> String {
    let columns = table.columns.iter()
        .map(|col| {
            let mut col_def = format!("{} {}", col.name, col.data_type);
            if let Some(default) = &col.default {
                col_def.push_str(&format!(" DEFAULT {}", default));
            }
            if col.nullable {
                col_def.push_str(" NULL");
            } else {
                col_def.push_str(" NOT NULL");
            }
            col_def
        })
        .collect::<Vec<String>>()
        .join(",\n");

    let primary_key = if let Some(pk) = &table.primary_key {
        format!("PRIMARY KEY ({})", pk)
    } else {
        String::new()
    };

    let foreign_keys = table.foreign_keys.iter()
        .map(|fk| {
            let mut fk_def = format!("FOREIGN KEY ({}) REFERENCES {}", fk.columns.join(", "), fk.referenced_table);
            if let Some(on_delete) = &fk.on_delete {
                fk_def.push_str(&format!(" ON DELETE {}", on_delete));
            }
            if let Some(on_update) = &fk.on_update {
                fk_def.push_str(&format!(" ON UPDATE {}", on_update));
            }
            fk_def
        })
        .collect::<Vec<String>>()
        .join(",\n");

    let indexes = table.indexes.iter()
        .map(|idx| format!("INDEX {} ({})", idx.name, idx.columns.join(", ")))
        .collect::<Vec<String>>()
        .join(",\n");

    let mut constraints = vec![];
    if !primary_key.is_empty() {
        constraints.push(primary_key);
    }
    if !foreign_keys.is_empty() {
        constraints.push(foreign_keys);
    }
    if !indexes.is_empty() {
        constraints.push(indexes);
    }

    let constraints_clause = if !constraints.is_empty() {
        format!(",\n{}", constraints.join(",\n"))
    } else {
        String::new()
    };

    format!("CREATE TABLE {} ({}){};",
        table.name, columns, constraints_clause)
}

