use arrow::array::{ArrayData, make_array};
use arrow::pyarrow::FromPyArrow;
use pyo3::{prelude::*, types::{PyDict, PyTuple}};
use crate::typed::{TypedValue, TypeInfo};
use eyre::Result;

fn serialize_message(py_dict: &Bound<'_, PyDict>, type_info: &TypeInfo) -> Result<ArrayData> {
    let mut fields = Vec::new();
    let mut buffers = Vec::new();

    for field in &type_info.fields {
        let field_name = field.name();
        let py_value = py_dict.get_item(field_name)?;
        let typed_value = TypedValue::from_py_value(py_value, field.type_info())?;
        let array_data = typed_value.to_arrow()?;
        fields.push(field.name().to_string());
        buffers.push(array_data);
    }

    let array_data = make_array(buffers, fields);
    Ok(array_data)
}

