fn stream_inference(prompt: &str, model_path: &str) -> std::sync::mpsc::Receiver<String> {
    let (sender, receiver) = mpsc::channel();

    thread::spawn(move || {
        let params = gpt_params_c {
            prompt: str_to_mut_i8(prompt),
            model_path: str_to_mut_i8(model_path),
            ..Default::default()
        };

        if let Ok(tokens) = run_inference(&params) {
            for token in tokens {
                if let Ok(token_str) = std::str::from_utf8(&token) {
                    sender.send(token_str.to_string()).unwrap();
                }
            }
        }
    });

    receiver
}

fn check_whitelist_mint_count_limit(
    deps: Deps,
    whitelist_addr: &Addr,
    stage_id: u32,
) -> Result<bool, StdError> {
    let stage_response: StageResponse = deps
        .querier
        .query::<TieredWhitelistQueryMsg>(TieredWhitelistQueryMsg::Stage {
            address: whitelist_addr.to_string(),
            stage_id,
        })
        .map_err(StdError::from)?;

    let current_mint_count = match stage_id {
        1 => WHITELIST_FS_MINT_COUNT.load(deps.storage)?,
