use std::sync::Arc;
use arrow::record_batch::RecordBatch;
use arrow::array::BooleanBuilder;
use arrow::compute::filter_record_batch;
use datafusion_common::{Result, DataFusionError};
use datafusion_common::scalar::ScalarValue;

fn filter_batch_by_column<F>(
    batch: &RecordBatch,
    column_name: &str,
    predicate: F,
) -> Result<RecordBatch>
where
    F: Fn(&ScalarValue) -> bool,
{
    let schema = batch.schema();
    let field_index = schema
        .field_indices(column_name)
        .ok_or(DataFusionError::Plan(format!("Column {} not found", column_name)))?
        .next()
        .ok_or(DataFusionError::Plan(format!("Column {} not found", column_name)))?;

    let array = batch.column(field_index);
    let mut filter_array = BooleanBuilder::with_capacity(array.len() as usize);

    for i in 0..array.len() {
        let value = array.value_at(i);
        if predicate(value) {
            filter_array.append(true)?;
        } else {
            filter_array.append(false)?;
        }
    }

    let filter_array = filter_array.build()?;
    let filtered_batch = filter_record_batch(batch, &filter_array)?;
    Ok(filtered_batch)
}

fn echo_with_owned_halves(mut stream: VsockStream) -> Result<()> {
    let (mut read_half, mut write_half) = stream.split();

    // Spawn a task to read from the read half and write to the write half
    tokio::spawn(async move {
        let mut buffer = [0; 1024];
        loop {
            match read_half.read(&mut buffer).await {
                Ok(n) if n == 0 => break,
                Ok(n) => {
                    if let Err(e) = write_half.write_all(&buffer[..n]).await {
                        eprintln!("Write error: {}", e);
                        break;
                    }
                }
                Err(e) => {
                    eprintln!("Read error: {}", e);
                    break;
                }
            }
        }
    });

    // Keep the main task alive until the read task completes
    tokio::task::yield_now().await;

    Ok(())
}

use bhtsne::tSNE;
use num_traits::Float;
use serde_json;

fn embedding_to_json<T>(tsne: &tSNE<T, impl Send + Sync>, dim: usize) -> String
where
    T: Float + ToString,
{
    let embedding = tsne.embedding();
    let mut json_array = Vec::new();

    for i in 0..embedding.len() {
        let point = &embedding[i];
        let mut point_array = Vec::new();

        for j in 0..dim {
            if j < point.len() {
                point_array.push(point[j].to_string());
            } else {
                point_array.push("0".to_string());
            }
        }

