use usage::Spec;
use std::path::Path;
use miette::Result;
use std::fs::File;
use std::io::prelude::*;
use serde_yaml::from_reader;

fn normalize_usage_spec(file_path: &Path) -> Result<Spec> {
    let mut file = File::open(file_path)?;
    let mut contents = String::new();
    file.read_to_string(&mut contents)?;

    let spec: Spec = from_reader(contents.as_bytes())?;
    normalize_spec(&spec)
}

fn normalize_spec(spec: &Spec) -> Result<Spec> {
    let mut normalized = spec.clone();

    // Normalize subcommand names to lowercase
    for subcommand in &mut normalized.subcommands {
        subcommand.name = subcommand.name.to_lowercase();
    }

    // Normalize flag definitions
    for command in &mut normalized.commands {
        for flag in &mut command.flags {
            flag.name = flag.name.to_lowercase();
            if flag.default.is_none() {
                flag.default = flag.default_type().map(|dt| dt.into());
            }
        }
    }

    Ok(normalized)
}

fn flag_default_type(flag: &usage::Flag) -> Option<String> {
    match flag.ty {
        usage::FlagType::Bool => Some("false".to_string()),
        usage::FlagType::String => Some("".to_string()),
        usage::FlagType::Integer => Some("0".to_string()),
        usage::FlagType::Float => Some("0.0".to_string()),
        usage::FlagType::Enum => Some("".to_string()),
    }
}

