fn format_structured_data(&self, data: &StructuredData) -> String {
    let mut result = String::new();
    let mut first = true;

    for (key, value) in data {
        if !first {
            result.push(';");
        } else {
            first = false;
        }

        result.push_str(&format!("{}={}", key, self.escape_value(value)));
    }

    if !first {
        result.push(';");
    }

    result
}

fn escape_value(&self, value: &BTreeMap<String, String>) -> String {
    let mut escaped = String::new();
    let mut first = true;

    for (k, v) in value {
        if !first {
            escaped.push(';');
        } else {
            first = false;
        }

        escaped.push_str(&format!("{}={}", k, self.escape_string(v)));
    }

    escaped
}

fn escape_string(&self, s: &str) -> String {
    let mut escaped = String::new();
    let mut in_escape = false;

    for c in s.chars() {
        if in_escape {
            match c {
                'b' => escaped.push('\x08'),
                'f' => escaped.push('\x0c'),
                'n' => escaped.push('\n'),
                'r' => escaped.push('\r'),
                't' => escaped.push('\t'),
                'v' => escaped.push('\x0b'),
                _ => escaped.push(c),
            }
            in_escape = false;
        } else if c == '\\' {
            in_escape = true;
        } else if c == '"' {
            escaped.push('\\');
            escaped.push('"');
        } else {
            escaped.push(c);
        }
    }

    escaped
}

fn validate_consistency(&self) -> Result<(), String> {
    if self.block_header.is_none() {
        return Err("Block header is missing".to_string());
    }

    let block_height = self.block_header.as_ref().unwrap().block_height;

    for shard in &self.shards {
        if let Some(chunk_view) = &shard.chunk_view {
            if chunk_view.header.block_height != block_height {
                return Err(format!("Chunk in shard {} has inconsistent block height: expected {}, found {}", shard.shard_id, block_height, chunk_view.header.block_height));
            }
        }
    }

    Ok(())
}

