use rudderanalytics::message::{Batch, BatchMessage};
use rudderanalytics::utils;

fn validate_batch(batch: &Batch) -> Result<(), String> {
    if batch.messages.len() > 100 {
        return Err("Batch contains more than 100 messages".to_string());
    }

    let reserved_top_level_keys = ["timestamp", "type", "context", "integrations", "message_id", "sent_at"];
    if let Some(context) = &batch.context {
        for key in reserved_top_level_keys {
            if context.contains_key(key) {
                return Err(format!("Reserved top-level key '{}' found in batch context", key));
            }
        }
    }

    for message in &batch.messages {
        if let Some(context) = &message.context {
            let reserved_message_keys = ["timestamp", "type", "context", "integrations", "message_id", "sent_at"];
            for key in reserved_message_keys {
                if context.contains_key(key) {
                    return Err(format!("Reserved message context key '{}' found", key));
                }
            }
        }
    }

    Ok(())
}

fn activate_with_custom_paths(
    prefix: &Path,
    shell_type: impl Shell + 'static,
    custom_paths: &[PathBuf],
) -> Result<ActivationResult<impl Shell>, ActivationError> {
    let mut activation_vars = ActivationVariables::new(prefix, shell_type);
    let platform = Platform::current();

    // Prepend custom paths to PATH
    let mut new_path = std::env::var_os("PATH").map_or_else(
        || Vec::new(),
        |path| {
            std::env::split_paths(&path)
                .map(|p| p.into_os_string())
                .collect::<Vec<_>>()
        },
    );

    // Prepend custom_paths to the new_path
    for path in custom_paths {
        if let Some(path_str) = path.to_str() {
            new_path.insert(0, path_str.to_string());
        }
    }

    // Set the new PATH
    activation_vars.set_path(new_path);

    // Activate the environment
    let activation_result = activation_vars.activate(platform)?;

    Ok(activation_result)
}

use fuzzy_matcher::clangd::ClangdMatcher;
use fuzzy_matcher::FuzzyMatcher;
use fuzzy_matcher::ScoreType;

pub enum CaseMatching {
    Respect,
    Ignore,
    Smart,
}

fn fuzzy_match_with_case_control(
    choice: &str,
    pattern: &str,
    case_sensitivity: CaseMatching,
) -> Option<ScoreType> {
    let matcher = ClangdMatcher::new();
    let mut score = None;

    match case_sensitivity {
        CaseMatching::Respect => {
            if let Some(s) = matcher.fuzzy_match(choice, pattern) {
                score = Some(s);
            }
        }
        CaseMatching::Ignore => {
            let lower_choice = choice.to_lowercase();
            let lower_pattern = pattern.to_lowercase();
            if let Some(s) = matcher.fuzzy_match(&lower_choice, &lower_pattern) {
                score = Some(s);
            }
        }
        CaseMatching::Smart => {
            let lower_pattern = pattern.to_lowercase();
            let mut lower_choice = choice.to_lowercase();
            let mut is_smart = false;

            // Check if the pattern starts with an uppercase letter
            if pattern.chars().next().map_or(false, |c| c.is_uppercase()) {
                is_smart = true;
            }

            if is_smart {
                // Make the choice lowercase except for the first character
                if let Some(first_char) = lower_choice.chars().next() {
                    lower_choice = first_char.to_uppercase().to_string() + &lower_choice[1..];
                }
            }

            if let Some(s) = matcher.fuzzy_match(&lower_choice, &lower_pattern) {
                score = Some(s);
            }
        }
    }

    score
}

