fn normalize_path(path: &str) -> PathBuf {
    let mut path_buf = PathBuf::new();
    let mut components = path.split('/');

    if path.starts_with('/') {
        path_buf.push("/");
    }

    for component in components {
        if component.is_empty() {
            continue;
        }
        path_buf.push(component);
    }

    path_buf
}

