fn uppercase_body<B>(body: B) -> impl http_body::Body<Data = bytes::Bytes, Error = B::Error>
where
    B: http_body::Body<Data = bytes::Bytes>,
{
    struct UppercaseBody<B> {
        body: B,
        is_trailers: bool,
    }

    impl<B> http_body::Body for UppercaseBody<B>
    where
        B: http_body::Body<Data = bytes::Bytes>,
    {
        type Data = bytes::Bytes;
        type Error = B::Error;

        fn poll_frame(
            self: std::pin::PinMut<'_, Self>,
            cx: &mut std::task::Context<'_>,
        ) -> std::task::Poll<Option<Self::Data>> {
            let this = self.get_mut();
            if this.is_trailers {
                return std::task::Poll::Ready(None);
            }

            match http_body::Body::poll_frame(self.body, cx) {
                std::task::Poll::Ready(Some(Frame::Data(data))) => {
                    let upper = data.to_vec().into_iter().map(|c| c.to_ascii_uppercase()).collect();
                    std::task::Poll::Ready(Some(Frame::Data(Bytes::from(upper))))
                }
                std::task::Poll::Ready(Some(Frame::Trailers(trailers))) => {
                    this.is_trailers = true;
                    std::task::Poll::Ready(Some(Frame::Trailers(trailers)))
                }
                poll => poll,
            }
        }

        fn is_end_stream(&self) -> bool {
            self.body.is_end_stream()
        }
    }

    UppercaseBody {
        body,
        is_trailers: false,
    }
}

fn publish_batch<B, I>(behaviour: &mut B, msgs: I)
where
    B: crate::layer::Behaviour,
    I: IntoIterator<Item = (crate::topic::Topic, bytes::Bytes)>,
{
    let mut topics = HashSet::new();
    let mut messages = Vec::new();

    for (topic, data) in msgs {
        topics.insert(topic.clone());
        messages.push((topic, data));
    }

    let floodsub_rpc = FloodsubRpc {
        messages: messages.into_iter().map(|(topic, data)| FloodsubMessage {
            topic,
            data,
        }).collect(),
    };

    for topic in topics {
        behaviour.to_swarm(ToSwarm::BehaviourMessage(
            FloodsubRpc {
                messages: vec![FloodsubMessage {
                    topic,
                    data: Bytes::new(),
                }],
            },
        ));
    }
}

use async_tempfile::Error;
use std::path::{Path, PathBuf};
use tokio::fs;

fn list_temp_files<P>(dir: P) -> Result<Vec<PathBuf>, Error>
where
    P: AsRef<Path>,
{
    let dir_path = dir.as_ref();
    if !dir_path.exists() {
        return Err(Error::new("Directory does not exist"));
    }

    if !dir_path.is_dir() {
        return Err(Error::new("Path is not a directory"));
    }

    let mut temp_files = Vec::new();
    let entries = tokio::fs::read_dir(dir_path).await?;

    for entry in entries {
        let entry = entry?;
        let path = entry.path();
        if path.is_file() {
            if path.extension().map_or(false, |ext| ext == "tmp") {
                temp_files.push(path);
            }
        }
    }

    Ok(temp_files)
}

fn redirect_with_query<U, Q>(&self, destination: &U, query: Q) -> Redirect
    where
        U: Route,
        Q: Serialize,
{
    let url = destination.url();
    let query_string = to_string(&query).unwrap_or_default();
    let mut url = url.parse().unwrap();
    url.query_pairs_mut().extend_pairs(query_string.parse().unwrap());
    Redirect::to(url.to_string())
}

fn find_duplicate_fields_in_objects(ctx: &mut Context<'_>) -> Vec<(String, String)> {
    let mut duplicates = Vec::new();
    let object_types = ctx.schema().object_types();

    for object_type in object_types {
        let name = object_type.name().to_string();
        let fields = object_type.fields();

        let mut field_names = std::collections::HashMap::new();
        let mut seen_fields = std::collections::HashMap::new();

        for field in fields {
            let field_name = field.name().to_string();
            let field_type = field.type_.clone();

            if let Some(existing) = field_names.get(&field_name) {
                if existing == &field_type {
                    if let Some(count) = seen_fields.get_mut(&field_name) {
                        *count += 1;
                    } else {
                        seen_fields.insert(field_name.clone(), 1);
                    }
                }
            } else {
                field_names.insert(field_name.clone(), field_type);
                seen_fields.insert(field_name, 1);
            }
        }

        for (field_name, count) in seen_fields {
            if *count > 1 {
                duplicates.push((name.clone(), field_name));
            }
        }
    }

    duplicates
}

