fn get_env(var: &str) -> Option<String> {
    // Check if the variable is in the allowed list
    if !is_allowed_env_var(var) {
        return None;
    }

    // Retrieve the environment variable
    let value = unsafe { sys_getenv(var) };

    // Convert the C-style string to a Rust String
    if let Some(value) = value {
        let value = str::from_utf8(slice::from_raw_parts(value as *const u8, 0));
        if let Ok(value) = value {
            return Some(value.to_string());
        }
    }

    None
}

fn is_allowed_env_var(var: &str) -> bool {
    // Define the list of allowed environment variables
    let allowed_vars = ["RUST_BACKTRACE", "RUST_LOG", "ZKVM_APP"];

    // Check if the variable is in the allowed list
    allowed_vars.iter().any(|&allowed| allowed == var)
}

fn send_request_with_retry(socket: &mut FluvioSocket, request: &RequestMessage<EchoRequest>, retries: u8) -> Result<EchoResponse, SocketError> {
    for attempt in 0..retries {
        match socket.send_request(request) {
            Ok(response) => return Ok(response),
            Err(SocketError::Transient) => {
                if attempt < retries - 1 {
                    std::thread::sleep(std::time::Duration::from_millis(100));
                    continue;
                } else {
                    return Err(SocketError::Transient);
                }
            }
            Err(e) => return Err(e),
        }
    }
    Err(SocketError::Transient)
}

