    });
    let version = genlmsg.payload.nlas.iter().find_map(|nla| {
        if let GenlCtrlAttrs::Version(ver) = nla {
            Some(*ver)
        } else {
            None
        }
    });
    let hdrsize = genlmsg.payload.nlas.iter().find_map(|nla| {
        if let GenlCtrlAttrs::HdrSize(hdr) = nla {
            Some(*hdr)
        } else {
            None
        }
    });
    match (family_id, family_name, version, hdrsize) {
        (Some(id), Some(name), Some(ver), Some(hdr)) => Some((id, name, ver, hdr)),
        _ => None,
    }
}

fn get_ancestor_header(
    header_map: &HeaderMap,
    start_hash: Byte32,
    target_number: BlockNumber,
) -> Option<HeaderIndexView> {
    let mut current_hash = start_hash;
    let mut current_number = header_map.get(&current_hash).map_or(0, |h| h.number().value());

    while current_number > target_number {
        if let Some(header) = header_map.get(&current_hash) {
            current_hash = header.parent_hash();
            current_number = header.number().value();
        } else {
            return None;
        }
    }

    header_map.get(&current_hash).cloned()
}

fn build_user_query(
    org_name: Option<&str>,
    user_type: Option<i32>,
    min_age: Option<u8>,
    max_age: Option<u8>,
) -> ormlite::query_builder::SelectQueryBuilder<User> {
    let mut query = User::select();

    if let Some(name) = org_name {
        query = query.join(Join::Left, |join| {
            join.on(User::organization_id.eq(Organization::id))
                .and(Organization::name.eq(name))
        });
    }

    if let Some(ty) = user_type {
        query = query.where_(User::ty.eq(ty));
    }

    if let Some(min) = min_age {
        query = query.where_(User::age.ge(min));
    }

    if let Some(max) = max_age {
        query = query.where_(User::age.le(max));
    }

    query
}

use cbordata::{Cbor, err_at, Result};

fn merge_cbor_maps(map1: Cbor, map2: Cbor) -> Result<Cbor> {
    if map1.is_map() && map2.is_map() {
        let mut merged = map1.to_map()?;
        for (key, value) in map2.to_map()? {
            merged.insert(key, value);
        }
        Ok(Cbor::from_map(merged))
    } else {
        err_at!("Both inputs must be CBOR maps")
    }
}

