fn main() {
    // Connect to the SQLite database
    let conn = Connection::open("example.db").expect("Failed to open database");

    // Define custom column definitions
    let columns = vec![
        Column {
            name: "id".to_string(),
            physical_type: PhysicalType::Int32,
            logical_type: LogicalType::Int32,
            encoding: Encoding::Delta,
            dictionary: false,
        },
        Column {
            name: "name".to_string(),
            physical_type: PhysicalType::Utf8,
            logical_type: LogicalType::Utf8,
            encoding: Encoding::Rle,
            dictionary: true,
        },
        Column {
            name: "timestamp".to_string(),
            physical_type: PhysicalType::Timestamp(TimeUnit::Millis),
            logical_type: LogicalType::Timestamp(TimeUnit::Millis),
            encoding: Encoding::Delta,
            dictionary: false,
        },
        Column {
            name: "price".to_string(),
            physical_type: PhysicalType::Float64,
            logical_type: LogicalType::Float64,
            encoding: Encoding::Delta,
            dictionary: false,
        },
    ];

    // Execute a query to fetch data
    let mut stmt = conn.prepare("SELECT id, name, timestamp, price FROM table_name").unwrap();
    let mut rows = stmt.query_map([], |row| {
        Ok((
            row.get::<_, i32>(0).unwrap(),
            row.get::<_, String>(1).unwrap(),
            row.get::<_, String>(2).unwrap(),
            row.get::<_, f64>(3).unwrap(),
