    }

    // Generate the Parquet file with custom column definitions
    sqlite2parquet::write_parquet("output.parquet", &data, &columns).unwrap();
}

use binary_rw::{BinaryWriter, Result};

fn write_bool_slice(writer: &mut BinaryWriter, values: &[bool]) -> Result<usize> {
    let mut byte = 0u8;
    let mut count = 0;
    let mut index = 0;

    while index < values.len() {
        if values[index] {
            byte |= 1 << (7 - (count % 8));
        }
        count += 1;

        if count % 8 == 0 || index == values.len() - 1 {
            writer.write_u8(byte)?;
            byte = 0;
        }
        index += 1;
    }

    Ok(count)
}

use jwks_client::keyset::KeyStore;
use jwks_client::error;
use serde_json::Value;
