fn verify_and_extract_audience(token: &str, expected_aud: &str, jwks_url: &str) -> Result<serde_json::Value, error::Error> {
    // Fetch the JWKS keyset from the provided URL
    let keyset = KeyStore::from_url(jwks_url)?;

    // Parse the JWT token
    let token = Token::from_str(token)?;

    // Verify the token using the keyset
    let verified_token = token.verify_with_keyset(&keyset)?;

    // Extract the payload
    let payload = verified_token.payload();

    // Check if the 'aud' claim matches the expected audience
    if payload.get("aud").and_then(|v| v.as_str()).map_or(false, |aud| aud == expected_aud) {
        Ok(payload.clone().into())
    } else {
        Err(error::Error::new("Invalid audience"))
    }
}

fn send_large_payload<E>(transport: &E, payload: &[u8]) -> Result<(), LedgerAppError<E::Error>>
where
    E: Exchange + Send + Sync,
{
    let chunk_size = 250;
    let mut offset = 0;

    while offset < payload.len() {
        let chunk = &payload[offset..offset + chunk_size];
        let payload_type = ChunkPayloadType::Chunk;
        let command = APDUCommand::new(0x00, 0x00, 0x00, 0x00, payload_type as u8, chunk);
        let result = transport.send(command)?;

        if result.status != 0x9000 {
            return Err(LedgerAppError::new(result.status));
        }

        offset += chunk_size;
    }

    Ok(())
}

fn verify_cose_vcs(vcs: &[CoseSign1Bytes], key: &CoseKey) -> Result<Vec<bool>, SignatureError> {
    let mut results = Vec::with_capacity(vcs.len());
    for vc in vcs {
        let cose_vc = CoseVc::from_bytes(vc)?;
        let verified = cose_vc.verify(key)?;
        results.push(verified);
    }
    Ok(results)
}

