fn validate_signatures_against_programs<T: SVMMessage>(
    transaction: &T,
    trusted_programs: &[Pubkey],
) -> (u64, u64) {
    let mut secp256k1_signatures = 0;
    let mut ed25519_signatures = 0;

    for instruction in &transaction.instructions {
        let program_id = instruction.program_id;
        let num_signatures = get_num_signatures_in_instruction(instruction);

        if trusted_programs.contains(&program_id) {
            if program_id == SECP256K1_ID {
                secp256k1_signatures += num_signatures;
            } else if program_id == ED25519_ID {
                ed25519_signatures += num_signatures;
            }
        }
    }

    (secp256k1_signatures, ed25519_signatures)
}

fn simulate_dao_field_with_deposits(
    &self,
    parent: &HeaderView,
    new_deposits: &[(CellOutput, Bytes)],
) -> Result<Byte32, DaoError> {
    let mut tx_builder = TransactionBuilder::new();
    let mut outputs = vec![];
    for (output, data) in new_deposits {
        let output = output.clone();
        let data = data.clone();
        tx_builder = tx_builder.add_output(output);
        outputs.push((output, data));
    }

    let tx = tx_builder.build().map_err(|e| DaoError::TransactionBuild(e))?;  
    let resolved_tx = ResolvedTransaction::new(&tx, &vec![], &vec![]).map_err(|e| DaoError::TransactionResolve(e))?;

    let dao_data = extract_dao_data(&resolved_tx, parent, self).map_err(|e| DaoError::DaoCalculation(e))?;

    Ok(pack_dao_data(dao_data))
}

