fn wait_for_programs_ready(&self, program_ids: &[Pubkey], payer: &Keypair, max_attempts: u64) -> Result<(), String> {
    let client = RpcClient::new(self.url.clone());
    let commitment_config = CommitmentConfig::confirmed();
    let mut attempt = 0;

    while attempt < max_attempts {
        let mut all_ready = true;
        let mut failed_programs = Vec::new();

        for &program_id in program_ids {
            let mut transaction = Transaction::new_with_payer(
                &[Instruction::new_with_bincode(
                    program_id,
                    &[],
                    Vec::new(),
                )],
                Some(&payer.pubkey()),
            );

            transaction.sign(&[payer], transaction.signer_keypair().recent_blockhash);

            match client.send_and_CONFIRM(&transaction, commitment_config) {
                Ok(_) => {
                    // Optionally verify the program is deployable
                    // This is a placeholder, actual verification may require more logic
                }
                Err(e) => {
                    all_ready = false;
                    failed_programs.push(program_id);
                    warn!("Failed to send no-op to program {}: {}", program_id, e);
                }
            }
        }

        if all_ready {
            info!("All programs are ready: {:?}", program_ids);
            return Ok(());
        }

        attempt += 1;
        if attempt < max_attempts {
            info!("Attempt {} failed for programs: {:?}", attempt, failed_programs);
            sleep(Duration::from_secs(5));
        }
    }

    Err(format!("Max attempts ({}) reached. Some programs may not be ready: {:?}", max_attempts, program_ids))
}

use libp2p_core::multiaddr::{Multiaddr, Protocol};
use libp2p_identity::PeerId;
use lru::LruCache;
use std::num::NonZeroUsize;

fn is_relayed(addr: &Multiaddr) -> bool {
    addr.iter().any(|p| p == Protocol::P2pCircuit)
}

fn normalize_address(addr: &Multiaddr, me: &PeerId) -> Multiaddr {
    let mut normalized = addr.clone();
    if let Some(p) = normalized.iter().find(|p| **p == Protocol::P2p) {
        let peer_id_str = me.to_string();
        let peer_id_bytes = peer_id_str.as_bytes();
        let mut new_p = Protocol::P2p(peer_id_bytes.to_vec());
        *p = new_p;
    }
    normalized
}

fn aggregate_candidates(
    observed: &[Multiaddr],
    new_candidate: &Multiaddr,
    me: PeerId,
) -> Vec<Multiaddr> {
    let mut cache: LruCache<Multiaddr, usize> = LruCache::new(NonZeroUsize::new(100).unwrap());
    let mut candidates = Vec::new();

    // Process observed addresses
    for addr in observed {
        if !is_relayed(addr) {
            let normalized = normalize_address(addr, &me);
            *cache.entry(normalized).or_insert(0) += 1;
        }
    }

    // Process new candidate
    if !is_relayed(new_candidate) {
        let normalized = normalize_address(new_candidate, &me);
        *cache.entry(normalized).or_insert(0) += 1;
    }

    // Extract and sort candidates by frequency (most frequent first)
    let mut sorted: Vec<_> = cache.iter().map(|(k, &v)| (k.clone(), v)).collect();
    sorted.sort_by(|a, b| b.1.cmp(&a.1));

    // Extract the addresses
    candidates = sorted.into_iter().map(|(addr, _)| addr).collect();

    candidates
}

use wasm_bindgen::prelude::*;
use wasm_bindgen::JsCast;
use web_extensions_sys::Port;
use messages::{PortRequest, PortResponsePayload, Response, StreamingStartedStatus, StreamingResponsePayload};

fn register_port(port: Port) {
    port.on_message().unwrap().set_handler(move |_port, msg| {
        let msg = msg.dyn_into::<js_sys::Object>().unwrap();
        let payload = js_sys::Reflect::get(&msg, &js_sys::Undefined::undefined()).unwrap();
        let payload = payload.dyn_into::<js_sys::Object>().unwrap();

        let request_type = js_sys::Reflect::get(&payload, &JsValue::from("type")).unwrap();
        let request_type = request_type.as_string().unwrap();

        match request_type.as_str() {
            "start_streaming" => {
                let streaming_started = true;
                let response = Response {
                    payload: Some(StreamingResponsePayload {
                        streaming_started,
                        status: StreamingStartedStatus::Started,
                    }),
                };
                let json_response = serde_wasm_bindgen::to_value(&response).unwrap();
                _port.send(&json_response).unwrap();
            }
            "stop_streaming" => {
                let streaming_started = false;
                let response = Response {
                    payload: Some(StreamingResponsePayload {
                        streaming_started,
                        status: StreamingStartedStatus::Stopped,
                    }),
                };
                let json_response = serde_wasm_bindgen::to_value(&response).unwrap();
                _port.send(&json_response).unwrap();
            }
            _ => {
                let response = Response {
                    payload: Some(PortResponsePayload {
                        message: format!("Unknown request type: {}", request_type),
                    }),
                };
                let json_response = serde_wasm_bindgen::to_value(&response).unwrap();
                _port.send(&json_response).unwrap();
            }
        }
    });
}

fn total_unlocked_lamports(unlock_info: &UnlockInfo, total_stake: u64) -> u64 {
    let mut total_unlocked = 0;
    let mut current_time = unlock_info.start_time;
    let mut remaining_time = unlock_info.end_time - unlock_info.start_time;

    while remaining_time > 0 {
        let time_passed = std::cmp::min(remaining_time, unlock_info.unlock_duration);
        let unlock_amount = (time_passed * total_stake) / unlock_info.unlock_duration;
        total_unlocked += unlock_amount;
        current_time += time_passed;
        remaining_time = unlock_info.end_time - current_time;
    }

    total_unlocked
}

