fn vcp_features_with_subvalues(capability: &str) -> Vec<u8> {
    let caps = parse_capabilities(capability).unwrap_or_default();
    let mut result = Vec::new();

    for cap in caps {
        if let Cap::Vcp(Vcp { code, values }) = cap {
