            }
        }
    }

    result
}

use datafusion_common::{Result, ScalarValue, DataType, DataFusionError};
use datafusion_expr::{Expr, evaluate_partition_prefix};
use datafusion_catalog_listing::helpers::{list_partitions, prune_partitions, parse_partitions_for_path, PartitionedFile, Partition, CONCURRENCY_LIMIT};
use datafusion_datasource::ListingTableUrl;
use object_store::{ObjectStore, ObjectMeta};
use futures::stream::{BoxStream, StreamExt, TryStreamExt, FuturesUnordered};
use log::trace;

fn filter_partitions_with_expr(
    ctx: &dyn Session,
    store: &dyn ObjectStore,
    table_path: &ListingTableUrl,
    filters: &[Expr],
    file_extension: &str,
    partition_cols: &[(String, DataType)],
) -> Result<BoxStream<'static, Result<PartitionedFile>>> {
    let mut partitions = list_partitions(ctx, store, table_path, partition_cols, file_extension)?;

    let partition_exprs = filters
        .iter()
        .filter(|expr| {
            if let Expr::BinaryExpr { left, right, .. } = expr {
                if let ScalarValue::String(s) = right.as_ref() {
                    if let ScalarValue::String(p) = left.as_ref() {
                        return p.eq(s);
                    }
                }
            }
            true
        })
        .cloned()
        .collect::<Vec<_>>();

    let partitioned_files = partitions
        .into_iter()
        .map(move |partition| {
            let mut files = vec![];
            for (file, _) in parse_partitions_for_path(&partition, store, table_path, file_extension)? {
                let mut matches = true;
                for expr in &partition_exprs {
                    if let Err(e) = evaluate_partition_prefix(ctx, expr, &partition) {
                        trace!("Failed to evaluate filter expression: {}", e);
                        matches = false;
                        break;
                    }
                }
                if matches {
                    files.push(file);
                }
            }
            Ok(PartitionedFile::from_partitioned_files(partition, files))
        })
        .collect::<Result<Vec<_>>>()?;

    Ok(Box::new(futures::stream::iter(partitioned_files).map(|pf| Ok(pf))))
}

