use datafusion_expr::ColumnarValue;
use datafusion_common::{Result, ScalarValue, exec_err};
use datafusion_common::cast::as_int64_array;
use arrow::array::{Int64Array, ArrayRef};
use std::sync::Arc;
use std::ops::ControlFlow;

fn factorial_extended(arg: ColumnarValue) -> Result<ColumnarValue> {
    let array = match arg {
        ColumnarValue::Scalar(scalar) => {
            let value = scalar.as_int64().ok_or(exec_err!("Expected integer"))?;
            let result = factorial(value)?;
            Ok(ColumnarValue::Scalar(ScalarValue::Int64(result)))
        }
        ColumnarValue::Array(array) => {
            let int_array = as_int64_array(array)?;
            let mut result_array = Int64Array::with_capacity(int_array.len());
            for &value in int_array.iter() {
                let result = factorial(value)?;
                result_array.push(result);
            }
            Ok(ColumnarValue::Array(Arc::new(result_array)))
        }
    };
    array
}

fn factorial(n: i64) -> Result<i64> {
    if n < 0 {
        return exec_err!("Factorial is undefined for negative numbers");
    }
    let mut result = 1;
    for i in 1..=n {
        match result.checked_mul(i) {
            Some(val) => result = val,
            None => return exec_err!("Factorial overflow for n = {}", n),
        }
    }
    Ok(result)
}

use fedimint_testing::fixtures::Fixtures;
