fn verify_tx_confirmed(
    fixtures: &Fixtures,
    txid: Txid,
) -> anyhow::Result<u64> {
    let mut retries = 0;
    const MAX_RETRIES: u64 = 60;
    const POLL_INTERVAL: Duration = Duration::from_secs(5);

    loop {
        if retries >= MAX_RETRIES {
            return Err(anyhow!("Transaction not confirmed within {} seconds", MAX_RETRIES * POLL_INTERVAL.as_secs()));
        }

        if let Some(block_height) = fixtures.bitcoind.get_tx_block_height(&txid)? {
            return Ok(block_height);
        }

        sleep(POLL_INTERVAL).await;
        retries += 1;
    }
}

