fn transform_rectangle<R, T>(rect: R, transform: T) -> R
where
    R: Rectangle,
    R::Scalar: FloatingScalar,
    T: Transform<Scalar = R::Scalar>,
{
    let corners = rect.corners();
    let transformed_corners: Vec<Vector2<R::Scalar>> = corners
        .iter()
        .map(|&corner| transform.apply(corner))
        .collect();

    let min_x = transformed_corners.iter().map(|v| v.x).fold(R::Scalar::infinity(), f64::min);
    let max_x = transformed_corners.iter().map(|v| v.x).fold(R::Scalar::neg_infinity(), f64::max);
    let min_y = transformed_corners.iter().map(|v| v.y).fold(R::Scalar::infinity(), f64::min);
    let max_y = transformed_corners.iter().map(|v| v.y).fold(R::Scalar::neg_infinity(), f64::max);

    R::from_corners(
        Vector2::new(min_x, min_y),
        Vector2::new(max_x, max_y),
    )
}

fn private_ip_rule() -> Rule<NetworkConfig> {
    Rule::new("ip", |data: &NetworkConfig| {
        if let Some(ip_str) = &data.ip {
            if let Ok(ip) = ip_str.parse::<std::net::IpAddr>() {
                if let std::net::IpAddr::V4(ip_v4) = ip {
                    let bytes = ip_v4.octets();
                    if bytes[0] == 192 && bytes[1] == 168 {
                        return Ok(());
                    }
                }
            }
        }
        Err(ValidationError::new("ip must be in the 192.168.0.0/16 private network range"))
    })
}

fn summarize_resources(
    resources: &[&cloudformation::types::StackResourceSummary],
) -> Result<Vec<String>, Box<dyn std::error::Error>> {
    if resources.is_empty() {
        return Ok(vec![]);
    }

    let max_logical_id = resources
        .iter()
        .map(|r| r.logical_id().len())
        .max()
        .unwrap_or(0);
    let max_physical_id = resources
        .iter()
        .map(|r| r.physical_id().len())
        .max()
        .unwrap_or(0);
    let max_type = resources
        .iter()
        .map(|r| r.resource_type().len())
        .max()
        .unwrap_or(0);

    let mut result = Vec::new();
    result.push(format!(
        "{:1$} | {:2$} | {:3$}",
        "Type",
        "Logical ID",
        "Physical ID",
        max_type,
        max_logical_id,
        max_physical_id
    ));
    result.push("-".repeat(max_type + max_logical_id + max_physical_id + 4));

    for resource in resources {
        result.push(format!(
            "{:1$} | {:2$} | {:3$}",
            resource.resource_type().to_string(),
            resource.logical_id().to_string(),
            resource.physical_id().to_string(),
            max_type,
            max_logical_id,
            max_physical_id
        ));
    }

    Ok(result)
}

fn to_rotation_matrix(self) -> RowMatrix3<f32> {
    let q = self;
    let xx = q.x * q.x;
    let yy = q.y * q.y;
    let zz = q.z * q.z;
    let xy = q.x * q.y;
    let xz = q.x * q.z;
    let yz = q.y * q.z;
    let xw = q.x * q.w;
    let yw = q.y * q.w;
    let zw = q.z * q.w;

    RowMatrix3::new(
        1.0 - 2.0 * (yy + zz),
        2.0 * (xy - zw),
        2.0 * (xz + yw),
        2.0 * (xy + zw),
        1.0 - 2.0 * (xx + zz),
        2.0 * (yz - xw),
        2.0 * (xz - yw),
        2.0 * (yz + xw),
        1.0 - 2.0 * (xx + yy),
    )
}

fn clone_upgradeable_programs_from_rpc<T>(&mut self, addresses: T, rpc_client: &RpcClient) -> Result<&mut Self, String>
where
    T: IntoIterator<Item = Pubkey>,
{
    let mut program_accounts: HashSet<Pubkey> = HashSet::new();
    let mut data_accounts: HashSet<Pubkey> = HashSet::new();

    // Fetch all program accounts from the RPC endpoint
    let program_accounts_result = rpc_client.get_program_accounts(&Pubkey::default(), None);
    if let Err(e) = &program_accounts_result {
        return Err(format!("Failed to fetch program accounts: {}", e));
    }
    let program_accounts_data = program_accounts_result.unwrap();

    for (pubkey, _) in program_accounts_data {
        program_accounts.insert(pubkey);
    }

    // Fetch all accounts for each program account to find data accounts
    for pubkey in program_accounts {
        let account_result = rpc_client.get_account(&pubkey);
        if let Err(e) = &account_result {
            return Err(format!("Failed to fetch account for pubkey {}: {}", pubkey, e));
        }
        let account = account_result.unwrap();
        if let Ok(loader_state) = UpgradeableLoaderState::from_account(&account) {
            if let Some(data_account) = loader_state.data {
                data_accounts.insert(data_account);
            }
        }
    }

    // Clone the program accounts and their data accounts
    for (pubkey, _) in program_accounts_data {
        // Clone the program account
        let account_result = rpc_client.get_account(&pubkey);
        if let Err(e) = &account_result {
            return Err(format!("Failed to fetch account for pubkey {}: {}", pubkey, e));
        }
        let account = account_result.unwrap();
        self.clone_account(&pubkey, &account)?;
    }

    for data_account in data_accounts {
        let account_result = rpc_client.get_account(&data_account);
        if let Err(e) = &account_result {
            return Err(format!("Failed to fetch data account for {}: {}", data_account, e));
        }
        let account = account_result.unwrap();
        self.clone_account(&data_account, &account)?;
    }

    Ok(self)
}

