use patch::{Patch, Line};

fn count_lines(patch: &Patch) -> (usize, usize, usize) {
    let mut added = 0;
    let mut removed = 0;
    let mut context = 0;

    for hunk in &patch.hunks {
        for line in &hunk.lines {
            match line {
                Line::Added => added += 1,
                Line::Removed => removed += 1,
                Line::Context => context += 1,
            }
        }
    }

    (added, removed, context)
}

