fn merge_variant_objects(v1: &Variant, v2: &Variant) -> Result<Variant<'static, 'static>, ArrowError> {
    let mut builder = VariantBuilder::new();
    for (key, value) in v1.fields() {
        builder.push(key, value)?;
    }
    for (key, value) in v2.fields() {
        builder.push(key, value)?;
    }
    Ok(builder.build()?)
}

