fn find_duplicate_fields<'a>(type_name: &str, ctx: &mut Context<'a>) -> Vec<(String, usize, usize)> {
    let mut field_map = std::collections::HashMap::new();
    let mut duplicates = Vec::new();
    let mut field_count = 0;

    // Collect all fields from the base type and extensions
    let mut fields = vec![];
    if let Some(base_type) = ctx.get_type(type_name) {
        fields.extend(base_type.fields.iter().map(|f| f.name.clone()));
    }

    for extension in &ctx.extensions {
        if extension.name == type_name {
            fields.extend(extension.fields.iter().map(|f| f.name.clone()));
        }
    }

    // Track the first and second occurrence of each field
    for (index, &field_name) in fields.iter().enumerate() {
        if let Some(&first_index) = field_map.get(&field_name) {
            // Duplicate found
            duplicates.push((field_name.clone(), first_index, index));
        } else {
            field_map.insert(field_name.clone(), index);
        }
    }

    duplicates
}

fn format_error(message: &str, size: ConsoleSize, indent: usize) -> String {
    let mut lines = message.lines().map(|line| Cow::Owned(line.to_string())).collect::<Vec<_>>();
    let mut result = String::new();
    let mut line_index = 0;

    while line_index < lines.len() {
        let line = &lines[line_index];
        let mut current_line = String::new();
        let mut words = tokenize_words(line);
        let mut has_ansi = false;

        // Check if the line contains ANSI codes
        if line.contains('\x1b') {
            has_ansi = true;
        }

        // Wrap the line according to the console size
        while !words.is_empty() {
            let word = words[0].clone();
            let word_width = UnicodeWidthStr::new(word.as_str());

            // Check if adding the word would exceed the console width
            if current_line.is_empty() {
                // Start of the line, add the word directly
                current_line.push_str(word.as_str());
            } else {
                let current_line_width = UnicodeWidthStr::new(&current_line);
                let total_width = current_line_width + word_width;

                if total_width <= size.width as u16 {
                    current_line.push_str(" ");
                    current_line.push_str(word.as_str());
                    words.remove(0);
                } else {
                    // Wrap the line
                    result.push_str(&current_line);
                    result.push('\n');
                    current_line.clear();
                    current_line.push_str(word.as_str());
                    words.remove(0);
                }
            }
        }

        // Add the wrapped line to the result
        if !current_line.is_empty() {
            result.push_str(&current_line);
            result.push('\n');
        }

        line_index += 1;
    }

    // Indent the result
    let indent_str = " ".repeat(indent);
    result = result.lines().map(|line| format!("{}{}", indent_str, line)).collect::<Vec<_>>().join("\n");

    // Restore ANSI codes if any were stripped
    if has_ansi {
        result = strip_ansi_codes(&result);
    }

    result
}

fn validate_info<T, V>(client_ids: T, parser: &JwtParser<GooglePayload>) -> MyResult<()>
where
    T: AsRef<[V]>,
    V: AsRef<str>,
{
    let payload = parser.parse()?;
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .ok_or(Error::TimeConversionError)?;

    if payload.iss != GOOGLE_ISS {
        return Err(GoogleIssuerNotMatchError.into());
    }

    if payload.exp < now {
        return Err(Error::TokenExpired.into());
    }

    let aud = payload.aud.as_ref();
    let client_id = client_ids.as_ref().iter().find(|id| id.as_ref() == aud);

    if client_id.is_none() {
        return Err(IDTokenClientIDNotFoundError.into());
    }

    Ok(())
}

