use shaderc::{parse_version_profile, GlslProfile, Error};

fn get_version_profile(source: &str) -> Result<(u32, GlslProfile), Error> {
    let mut lines = source.lines();
    while let Some(line) = lines.next() {
        if line.starts_with("#version") {
            let line = line.trim();
            let parts: Vec<&str> = line.split_whitespace().collect();
            if parts.len() >= 2 {
                if let Ok(version) = parts[1].parse::<u32>() {
                    if parts.len() > 2 {
                        let profile = parse_version_profile(parts[2])?;
                        return Ok((version, profile));
                    } else {
                        // Default profile if not specified
                        let profile = parse_version_profile("core")?;
                        return Ok((version, profile));
                    }
                }
            }
            return Err(Error::new("Invalid version directive format"));
        }
    }
    Err(Error::new("No #version directive found"))
}

fn read_substream_to_bytes<C>(sub: &mut Substream<C>) -> Result<Bytes, std::io::Error>
where
    C: AsyncRead + AsyncWrite + Unpin,
{
    let mut buffer = BytesMut::new();
    let mut reader = sub;

    loop {
        let mut buf = [0; 1024];
        match reader.read(&mut buf).await {
            Ok(0) => break,
            Ok(n) => {
                if n > 0 {
                    buffer.extend_from_slice(&buf[..n]);
                }
            }
            Err(e) => return Err(e),
        }
    }

    Ok(buffer.freeze())
}

use std::error::Error;
use std::fs;
use std::path::{Path, PathBuf};
use wildcard::Wildcard;

fn filter_files_by_pattern(directory: &Path, pattern: &str) -> Result<Vec<PathBuf>, Box<dyn Error>> {
    let wildcard = Wildcard::new(pattern)?;
    let mut matching_files = Vec::new();

    if !directory.exists() {
        return Err("Directory does not exist".into());
    }

    if !directory.is_dir() {
        return Err("Provided path is not a directory".into());
    }

    for entry in fs::read_dir(directory)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_file() && wildcard.is_match(&path.file_name().unwrap().to_string_lossy()) {
            matching_files.push(path);
        }
    }

    Ok(matching_files)
}

fn fang_oost_custom_payoff_price<S, P>(
    num_u: usize,
    asset: f64,
    strikes: &[f64],
    max_strike: f64,
    rate: f64,
    t_maturity: f64,
    cf: S,
    payoff: P,
) -> Vec<fang_oost::GraphElement>
where
    S: Fn(&Complex<f64>) -> Complex<f64> + Sync + Send,
    P: Fn(f64, f64) -> f64 + Sync + Send,
{
    let x_range = get_x_range(num_u, asset, strikes, max_strike);
    let mut result = Vec::new();
    let mut price_transform = |x: f64, t: f64| {
        let x_complex = Complex::new(x, 0.0);
        let cf_value = cf(&x_complex);
        let payoff_value = payoff(x, t);
        let price = cf_value * payoff_value;
        price
    };
    let prices = fang_oost_generic_move(
        num_u,
        asset,
        strikes,
        max_strike,
        rate,
        t_maturity,
        &price_transform,
    );
    for (i, &price) in prices.iter().enumerate() {
        let graph_element = fang_oost::GraphElement {
            strike: strikes[i],
            price,
        };
        result.push(graph_element);
    }
    result
}

