#[derive(RustEmbed)]
#[folder = "examples/public/"]
struct Asset;

fn respond(path: &str, accept_encoding: &str) -> Option<(Vec<u8>, &'static str, Option<&'static str>)> {
    let asset = Asset::get(path).ok()?;
    let content_type = match path {
        _ if path.ends_with(".html") => "text/html",
        _ if path.ends_with(".css") => "text/css",
        _ if path.ends_with(".js") => "application/javascript",
        _ if path.ends_with(".png") => "image/png",
        _ if path.ends_with(".jpg") || path.ends_with(".jpeg") => "image/jpeg",
        _ if path.ends_with(".gif") => "image/gif",
        _ if path.ends_with(".svg") => "image/svg+xml",
        _ if path.ends_with(".woff") => "application/font-woff",
        _ if path.ends_with(".woff2") => "application/font-woff2",
        _ if path.ends_with(".ttf") => "application/x-font-ttf",
        _ if path.ends_with(".otf") => "font/otf",
        _ if path.ends_with(".eot") => "application/vnd.ms-fontobject",
        _ if path.ends_with(".ico") => "image/x-icon",
        _ => "application/octet-stream",
    };

    let mut supported_encodings = HashSet::new();
    supported_encodings.insert("identity");
    supported_encodings.insert("gzip");
    supported_encodings.insert("br");

    let mut encodings = accept_encoding
        .split(',')
        .filter_map(|s| {
            let mut parts = s.trim().split(';');
            let encoding = parts.next().unwrap_or("identity");
            let quality = parts.next().and_then(|s| s.trim().strip_prefix("q=").map(|s| s.parse::<f64>().ok()));
            if let Some(q) = quality {
                if q >= 0.0 && q <= 1.0 {
                    Some((encoding.to_string(), q))
                } else {
                    None
                }
            } else {
                Some((encoding.to_string(), 1.0))
            }
        })
        .collect::<Vec<_>>();

    encodings.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap_or(std::cmp::Ordering::Equal));

    for (encoding, _) in encodings {
        let encoding_lower = encoding.to_lowercase();
        if supported_encodings.contains(&encoding_lower) {
            let compressed = match encoding_lower.as_str() {
                "br" => {
                    if let Ok(compressed) = Asset::get(&format!("{}.br", path)) {
                        compressed.data().to_vec()
                    } else {
                        continue;
                    }
                }
                "gzip" => {
                    if let Ok(compressed) = Asset::get(&format!("{}.gzip", path)) {
                        compressed.data().to_vec()
                    } else {
                        continue;
                    }
                }
                _ => asset.data().to_vec(),
            };

            return Some((compressed, content_type, Some(encoding.as_str())));
        }
    }

    Some((asset.data().to_vec(), content_type, None))
}

