use array2d::{Array2D, Error};

fn transpose<T: Clone>(array: &Array2D<T>) -> Result<Array2D<T>, Error> {
    let rows = array.num_rows();
    let cols = array.num_cols();
    let mut transposed = Array2D::new(cols, rows)?;

    for r in 0..rows {
        for c in 0..cols {
            transposed.set(c, r, array.get(r, c).cloned())?;
        }
    }

    Ok(transposed)
}

use tokio_schedule::{every, Job};
use chrono::Utc;
use std::future::Future;
use std::sync::{Arc, Mutex};

fn schedule_limited<F, Fut>(interval_minutes: u32, max_runs: usize, task: F) -> impl Future<Output = ()>
where
    F: Fn() -> Fut + Send + Sync + 'static,
    Fut: Future<Output = ()> + Send + 'static,
{
    let max_runs = Arc::new(Mutex::new(max_runs));
    let counter = Arc::new(Mutex::new(0));

    let job = move || {
        let max_runs = Arc::clone(&max_runs);
        let counter = Arc::clone(&counter);
        let task = task.clone();

        async move {
            let mut count = counter.lock().unwrap();
            if *count >= *max_runs.lock().unwrap() {
                return;
            }
            *count += 1;

            task().await;
        }
    };

    let interval = interval_minutes * 60;
    every(interval)
        .start_at(Utc::now() + std::time::Duration::from_secs(interval as u64))
        .for_job(job)
        .map(|_| ())
}

