use reqwest_websocket::{WebSocket, Message, Error};
use bytes::Bytes;
use futures_util::{SinkExt, StreamExt};
use std::time::{Duration, Instant};
use tokio::task::JoinHandle;
use tokio::time::sleep;

fn start_keepalive(mut ws: WebSocket, interval_secs: u64) -> WebSocket {
    let interval = Duration::from_secs(interval_secs);
    let mut last_sent = Instant::now();

    // Spawn a background task to handle keepalive pings
    let handle = tokio::spawn(async move {
        loop {
            let now = Instant::now();
            let elapsed = now - last_sent;

            // Send a ping if the interval has passed
            if elapsed >= interval {
                if let Err(e) = ws.send(Message::Ping(Bytes::new())).await {
                    eprintln!("Failed to send ping: {}", e);
                    break;
                }
                last_sent = now;
            }

            // Sleep for a short period to avoid busy waiting
            tokio::select! {
                _ = sleep(interval) => {},
                _ = ws.next() => break,
            }
        }
    });

    // Return the original WebSocket to allow the caller to use it
    ws
}

use futures::StreamExt;
use fedimint_core::core::OperationId;
use anyhow::Result;
use crate::{LightningClientModule, SendOperationState, FinalSendOperationState};

fn wait_final_send_state(
    client: &LightningClientModule,
    operation_id: OperationId,
) -> Result<FinalSendOperationState> {
    let mut stream = client.subscribe_send_operation(operation_id);
    let mut state = SendOperationState::Pending;

    while let Some(event) = stream.next().await {
        state = event.state;
        if let Some(final_state) = state.as_final() {
            return Ok(final_state);
        }
    }

    Err(anyhow::anyhow!("Operation did not reach a final state"))
}

