fn sign_message_via_locator(locator_uri: &str, message: &[u8]) -> Result<String, RemoteWalletError> {
    let locator = Locator::from_uri(locator_uri)?;
    let keypair = generate_remote_keypair(&locator)?;
    let derivation_path = DerivationPath::default();
    let signature = keypair.sign_message(message, &derivation_path)?;
