}

fn validate_interface_implementation_cycles<'a>(
    interface_name: &str,
    iface: &'a ast::InterfaceType,
    ctx: &mut Context<'a>,
) {
    let mut visited = HashSet::new();
    let mut stack = vec![interface_name.to_string()];
    let mut current = interface_name.to_string();

    while let Some(interface) = stack.pop() {
        if visited.contains(&interface) {
            continue;
        }

        visited.insert(interface.clone());

        if let Some(impl_interfaces) = ctx.interfaces.get(&interface) {
            for impl_interface in impl_interfaces {
                if stack.contains(impl_interface) {
                    ctx.report(Report::new().with_message(format!("Circular interface implementation cycle detected: {} -> {}", interface, impl_interface)));
                    return;
                }
                stack.push(impl_interface.clone());
            }
        }
    }
}

