use ansi_term::{Colour, ANSIStrings};

fn rgb_gradient_line(text: &str) -> ANSIStrings<'static> {
    let mut result = ANSIStrings::new();
    let length = text.len();

    for (i, c) in text.chars().enumerate() {
        let fraction = i as f32 / (length - 1) as f32;
        let red = (1.0 - fraction) * 255.0;
        let green = fraction * 255.0;
        let blue = 0.0;

        let color = Colour::RGB(red as u8, green as u8, blue as u8);
        result.push(color.paint(c.to_string()));
    }

    result
}

use crate::issues::{Issue, IssueReport};

fn suggest_move_hook_out_of_loop(report: &IssueReport) -> Vec<String> {
    let mut suggestions = Vec::new();
    if let Some(issues) = &report.issues {
        for issue in issues {
            if let Issue::HookInsideLoop { location, hook_name } = issue {
                let suggestion = format!(
                    "Consider moving the call to hook '{hook_name}' out of the loop at {location} to avoid unnecessary repeated execution."
                );
                suggestions.push(suggestion);
            }
        }
    }
    suggestions
}

use tui_input::{Input, StateChanged};
use crossterm::event::Event;
use std::collections::HashMap;

struct PasswordInput {
    input: Input,
    is_visible: bool,
    mask: char,
    value: String,
}

impl PasswordInput {
    fn new(initial: String) -> Self {
        let mask = '*';
        let input = Input::new(initial)
            .with_state(StateChanged::new())
            .with_mask(mask);
        PasswordInput {
            input,
            is_visible: false,
            mask,
            value: initial,
        }
    }

    fn is_visible(&self) -> bool {
        self.is_visible
    }

    fn set_visible(&mut self, visible: bool) {
        self.is_visible = visible;
        self.input.set_mask(if visible { ' ' } else { self.mask });
    }

    fn get_value(&self) -> String {
        if self.is_visible {
            self.value.clone()
        } else {
            self.input.get_value().chars().map(|_| self.mask).collect()
        }
    }

    fn handle_event(&mut self, event: Event) -> bool {
        match event {
            Event::Key(key) => {
                if key.code == crossterm::event::KeyCode::Char('v') && key.modifiers == crossterm::event::Modifiers::CTRL | crossterm::event::Modifiers::SHIFT {
                    self.set_visible(!self.is_visible);
                    true
                } else {
                    self.input.handle_event(event)
                }
            }
            _ => self.input.handle_event(event),
        }
    }

    fn draw(&mut self, f: &mut tui::Frame<tui::backend::Backend>, area: tui::layout::Area) {
        self.input.draw(f, area);
    }

    fn get_state(&self) -> StateChanged {
        self.input.get_state()
    }

    fn set_state(&mut self, state: StateChanged) {
        self.input.set_state(state);
    }
}

