struct CustomFile {
    file: File,
    consecutive_empty_reads: usize,
    max_consecutive_empty_reads: usize,
    is_disconnected: Arc<AtomicBool>,
}

impl CustomFile {
    fn new(file: File) -> Self {
        CustomFile {
            file,
            consecutive_empty_reads: 0,
            max_consecutive_empty_reads: 3,
            is_disconnected: Arc::new(AtomicBool::new(false)),
        }
    }
}

impl UnderlyingIo for CustomFile {
    type ReadFuture = Pin<Box<dyn Future<Output = Result<usize>> + Send + Sync>>;
    type WriteFuture = Pin<Box<dyn Future<Output = Result<usize>> + Send + Sync>>;
    type AsyncRead = Pin<Box<dyn Future<Output = Result<usize>> + Send + Sync>>;
    type AsyncWrite = Pin<Box<dyn Future<Output = Result<usize>> + Send + Sync>>;

    fn read(&mut self, buf: &mut [u8]) -> Self::ReadFuture {
        let file = self.file.clone();
        let consecutive_empty_reads = &mut self.consecutive_empty_reads;
        let max_consecutive_empty_reads = self.max_consecutive_empty_reads;
        let is_disconnected = self.is_disconnected.clone();

        Box::pin(async move {
            let result = file.read(buf).await;
            match result {
                Ok(0) => {
                    *consecutive_empty_reads += 1;
                    if *consecutive_empty_reads >= *max_consecutive_empty_reads {
                        *is_disconnected.store(true, Ordering::SeqCst);
                    }
                    Ok(0)
                }
                Ok(n) => {
                    *consecutive_empty_reads = 0;
                    Ok(n)
                }
                Err(e) => {
                    if e.kind() == ErrorKind::WouldBlock {
                        // Handle non-blocking read
                        Ok(0)
                    } else {
                        Err(e)
                    }
                }
            }
        })
    }

    fn write(&mut self, buf: &[u8]) -> Self::WriteFuture {
        let file = self.file.clone();
        Box::pin(async move {
            file.write(buf).await
        })
    }

    fn poll_read(&mut self, cx: &mut Context<'_>) -> Poll<Result<usize>> {
        let file = self.file.clone();
        let consecutive_empty_reads = &mut self.consecutive_empty_reads;
        let max_consecutive_empty_reads = self.max_consecutive_empty_reads;
        let is_disconnected = self.is_disconnected.clone();

        Pin::new(&mut file).poll_read(cx).map(move |res| {
            match res {
                Ok(0) => {
                    *consecutive_empty_reads += 1;
                    if *consecutive_empty_reads >= *max_consecutive_empty_reads {
                        *is_disconnected.store(true, Ordering::SeqCst);
                    }
                    Ok(0)
                }
                Ok(n) => {
                    *consecutive_empty_reads = 0;
                    Ok(n)
                }
                Err(e) => {
                    if e.kind() == ErrorKind::WouldBlock {
                        Ok(0)
                    } else {
                        Err(e)
                    }
                }
            }
        })
    }

    fn poll_write(&mut self, cx: &mut Context<'_>) -> Poll<Result<usize>> {
        let file = self.file.clone();
        Pin::new(&mut file).poll_write(cx)
    }

    fn is_disconnected(&self) -> bool {
        self.is_disconnected.load(Ordering::SeqCst)
    }

    fn shutdown(&mut self) -> Self::WriteFuture {
        let file = self.file.clone();
        Box::pin(async move {
            file.shutdown().await
        })
    }
}

