fn average_latency(
    consensus: Option<Duration>,
    peers: &BTreeMap<PeerId, Option<Duration>>,
) -> Option<Duration> {
    let mut total = Duration::ZERO;
    let mut count = 0;

    if let Some(latency) = consensus {
        total += latency;
        count += 1;
    }

    for &peer_id in peers.keys() {
        if let Some(latency) = peers.get(&peer_id) {
            if let Some(latency) = latency {
                total += *latency;
                count += 1;
            }
        }
    }

    if count == 0 {
        None
    } else {
        Some(total / count)
    }
}

fn generate_contracts_state_root<DB>(contract_ids: &[ContractId], db: &DB) -> Result<Bytes32, ExecutorError>
where
    DB: StorageAsRef<ContractsState>,
{
    let mut calculator = MerkleRootCalculator::new();
    for &contract_id in contract_ids {
        if let Ok(state_root) = db.as_ref().get(&contract_id) {
            calculator.add_leaf(Bytes32::from_slice(&state_root));
        }
    }
    Ok(calculator.root())
}

