use std::net::Ipv4Addr;

fn compute_udp_checksum(payload: &[u8], src_ip: Ipv4Addr, dst_ip: Ipv4Addr) -> u16 {
    let mut pseudo_header = [0u16; 8];
    pseudo_header[0] = u16::from_be(src_ip.octets()[0] as u16) | (u16::from_be(src_ip.octets()[1] as u16) << 8);
    pseudo_header[1] = u16::from_be(src_ip.octets()[2] as u16) | (u16::from_be(src_ip.octets()[3] as u16) << 8);
    pseudo_header[2] = u16::from_be(dst_ip.octets()[0] as u16) | (u16::from_be(dst_ip.octets()[1] as u16) << 8);
    pseudo_header[3] = u16::from_be(dst_ip.octets()[2] as u16) | (u16::from_be(dst_ip.octets()[3] as u16) << 8);
    pseudo_header[4] = 0; // Zero
    pseudo_header[5] = 0; // Zero
    pseudo_header[6] = 0; // Length of UDP packet (in words)
    pseudo_header[7] = 0;

    let mut checksum = 0;
    let mut i = 0;

    while i < pseudo_header.len() {
        checksum += pseudo_header[i] as u32;
        i += 1;
    }

    let mut payload_checksum = 0;
    let mut j = 0;

    while j < payload.len() {
        payload_checksum += u16::from_be(payload[j] as u16) | (u16::from_be(payload[j + 1] as u16) << 8);
        j += 2;
    }

    checksum += payload_checksum as u32;

    let mut result = checksum;
    while result > 0xffff {
        result = (result >> 16) + (result & 0xffff);
    }

    result as u16
}

use std::collections::HashMap;
use msgpack_simple::{MsgPack, ConversionError};

fn parse_map_to_hashmap(map: MsgPack) -> Result<HashMap<String, i64>, ConversionError> {
    let mut result = HashMap::new();
    let items = map.as_map()?;
    for (key, value) in items {
        let key_str = key.as_str()?;
        let value_int = value.as_i64()?;
        result.insert(key_str.to_string(), value_int);
    }
    Ok(result)
}

