use parquet_variant::{Variant, VariantBuilder, VariantObject};
use arrow_schema::ArrowError;

fn merge_variants(obj1: &Variant, obj2: &Variant) -> Result<Variant<'static, 'static>, ArrowError> {
    let mut builder = VariantBuilder::new();
    if let Some(obj1_obj) = obj1.as_object() {
        for (key, value) in obj1_obj {
            builder.push_field(key, value)?;
        }
    }
    if let Some(obj2_obj) = obj2.as_object() {
        for (key, value) in obj2_obj {
            builder.push_field(key, value)?;
        }
    }
    Ok(builder.build()?)
}

