use openapi_type::{OpenapiSchema, OpenapiType};
use indexmap::IndexMap;

fn collect_all_schema_dependencies<T>() -> IndexMap<String, OpenapiSchema>
where
    T: OpenapiType,
{
    let mut schemas = IndexMap::new();
    collect_schemas(&mut schemas, T::type_ref());
    schemas
}

fn collect_schemas(schemas: &mut IndexMap<String, OpenapiSchema>, type_ref: &str) {
    if let Some(schema) = schemas.get(type_ref) {
        return;
    }

    let schema = match type_ref {
        "string" => OpenapiSchema::new_string(),
        "number" => OpenapiSchema::new_number(),
        "integer" => OpenapiSchema::new_integer(),
        "boolean" => OpenapiSchema::new_boolean(),
        "null" => OpenapiSchema::new_null(),
        "array" => OpenapiSchema::new_array(),
        "object" => OpenapiSchema::new_object(),
        _ => {
            if let Some(ref schema) = T::schema() {
                schema.clone()
            } else {
                OpenapiSchema::new_object()
            }
        }
    };

    schemas.insert(type_ref.to_string(), schema);

    if let Some(ref refs) = T::type_refs() {
        for ref_type in refs {
            collect_schemas(schemas, ref_type);
        }
    }
}

fn in_flight_user_endpoint(name: &'static str) -> InFlightCounterLayer<impl MetricsAttributes<http::Request<()>>> {
    InFlightCounterLayer::new(name, |request: &http::Request<()>| {
        let user_id = request.headers().get("X-User-ID").and_then(|h| h.to_str().ok()).filter(|s| !s.is_empty);
        let path = request.uri().path().to_string();
        let mut attributes = Vec::new();
        if let Some(user_id) = user_id {
            attributes.push(KeyValue::new("user.id", user_id));
        }
        attributes.push(KeyValue::new("http.path", path));
        attributes
    })
}

use crate::md_pre_process::flatten_markdown;
use crate::error::Error;
use std::path::Path;
use std::fs::File;
use std::io::Read;

fn validate_readme_size(project_dir: &Path, max_bytes: usize) -> Result<(), Error> {
    let readme_path = project_dir.join("README.md");
    if !readme_path.exists() {
        return Err(Error::ReadmeNotFound);
    }

    let content = match flatten_markdown(&readme_path) {
        Ok(content) => content,
        Err(e) => return Err(e),
    };

    let size = content.len();

    if size > max_bytes {
        return Err(Error::ReadmeTooLarge(size, max_bytes));
    }

    Ok(())
}

fn efficient_slot_status_notification(
    plugin_manager: std::sync::Arc<std::sync::RwLock<crate::geyser_plugin_manager::GeyserPluginManager>>,
    slot: solana_clock::Slot,
    parent: Option<solana_clock::Slot>,
    slot_status: agave_geyser_plugin_interface::geyser_plugin_interface::SlotStatus,
) -> Result<(), Box<dyn std::error::Error>> {
    let manager = plugin_manager.read().unwrap();
    let plugins = manager.get_plugins();
    let mut measure = Measure::start("slot_status_notification");

    for plugin in plugins {
        let plugin_arc = plugin.clone();
        let measure_plugin = Measure::start("plugin_call");
        match plugin_arc.slot_status_notification(slot, parent, slot_status) {
            Ok(_) => {
                info!("Plugin {} processed slot status notification successfully", plugin_arc.name());
                metrics::increment_counter!("slot_status_notification_success", "plugin" => plugin_arc.name());
            }
            Err(e) => {
                error!("Plugin {} failed to process slot status notification: {}", plugin_arc.name(), e);
                metrics::increment_counter!("slot_status_notification_failure", "plugin" => plugin_arc.name());
                // Optionally handle failure, e.g., retry, log, or skip
            }
        }
        measure_plugin.stop();
        metrics::record_gauge!("plugin_call_duration", measure_plugin.duration().as_nanos() as f64, "plugin" => plugin_arc.name());
    }

    measure.stop();
    metrics::record_gauge!("slot_status_notification_duration", measure.duration().as_nanos() as f64);
    Ok(())
}

