fn rename_crate_in_index(index: Arc<RegistryIndex>, old_name: &str, new_name: &str) -> Result<(), Error> {
    let mut index = index.write();

    if let Some(crate_entry) = index.remove(old_name) {
        index.insert(new_name, crate_entry)?;
    } else {
        return Err(Error::CrateNotFound(old_name.to_string()));
    }

    Ok(())
}

fn list_query_scopes<'a>(query: &str) -> Result<Vec<String>, sikula::mir::Error> {
    let mut scopes = Vec::new();
    let mut in_scope = false;
    let mut current_scope = String::new();

    for c in query.chars() {
        if c == 'i' && query[(query.find('i').unwrap() + 1)..].starts_with("n:") {
            in_scope = true;
            current_scope.clear();
            current_scope.push('i');
            current_scope.push('n');
            current_scope.push(':');
        } else if in_scope && c == ':' {
            in_scope = false;
            current_scope.push(c);
            scopes.push(current_scope.clone());
            current_scope.clear();
        } else if in_scope {
            current_scope.push(c);
        }
    }

    Ok(scopes)
}

use lazy_regex::regex_switch;

#[derive(Debug, PartialEq)]
enum CliCommand {
    Open(String),
    Close,
    Save,
    Unknown,
}

fn parse_command(input: &str) -> CliCommand {
    regex_switch!(input {
        "open\\((.*?)\\)" => CliCommand::Open($1),
        "close" => CliCommand::Close,
        "save" => CliCommand::Save,
        _ => CliCommand::Unknown,
    })
}

fn verify_extension_basic(block: &BlockView, consensus: &Consensus) -> Result<(), Error> {
    let extension = block.extension();
    let max_extension_size = consensus.max_extension_size();

    if extension.is_none() {
        return Err(Error::new(ErrorKind::InvalidBlock, "Block extension is missing"));
    }

    let extension = extension.unwrap();
    if extension.len() > max_extension_size as usize {
        return Err(Error::new(ErrorKind::InvalidBlock, "Block extension size exceeds maximum allowed"));
    }

    if extension.is_empty() && consensus.enforce_non_empty_extension() {
        return Err(Error::new(ErrorKind::InvalidBlock, "Block extension must not be empty"));
    }

    Ok(())
}

use anyhow::Result;
use lightning_invoice::{Builder, Bolt11Invoice, Features, Feature, FeatureValue};

fn create_bolt11_invoice(p: &PrunedInvoice) -> Result<Bolt11Invoice> {
    let mut builder = Builder::new();
    builder.set_payment_hash(p.payment_hash);
    builder.set_r_hash(p.r_hash);
    builder.set_amount_msat(p.amount_msat);
    builder.set_expiry_time(p.expiry_time);
    builder.set_description(p.description.clone());
    builder.set_memo(p.memo.clone());

    if let Some(features) = &p.features {
        let mut features_builder = Features::new();
        for (feature, value) in features {
            features_builder.add_feature(Feature::new(*feature, *value));
        }
        builder.set_features(features_builder);
    }

    Ok(builder.build()?)
}

use deno_core::url::Url;

fn normalize_url_strip_default_port(url_str: &str) -> Result<String, String> {
    let url = Url::new(url_str).map_err(|e| e.to_string())?;
    let mut normalized = url.to_string();

    // Check if the URL uses HTTP and the port is 80
    if url.scheme() == "http" && url.port().is_some() && url.port().unwrap() == 80 {
        normalized = normalized.replacen(":80", "", 1);
    }
    // Check if the URL uses HTTPS and the port is 443
    else if url.scheme() == "https" && url.port().is_some() && url.port().unwrap() == 443 {
        normalized = normalized.replacen(":443", "", 1);
    }

    Ok(normalized)
}

fn comprehensive_health_check(
    config: &IndexerConfig,
    pool: &IndexerConnectionPool,
    start_time: &Instant,
) -> ApiResult<Json<Value>> {
    let db_status = pool
        .test_connection()
        .map(|_| ServiceStatus::Healthy)
        .unwrap_or(ServiceStatus::Unhealthy);

    let fuel_status = get_fuel_status();
    let uptime = start_time
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    let current_time = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    let metrics = json!({
        "timestamp": current_time,
        "db_status": db_status.to_string(),
        "fuel_status": fuel_status,
        "uptime_seconds": uptime,
    });

    Ok(Json(metrics))
}

use crate::retrieve::RetrievedDigest;
use sha2::{Sha256, Sha512};
use digest::Digest;

fn compute_digests(data: &[u8]) -> (RetrievedDigest<Sha256>, RetrievedDigest<Sha512>) {
    let sha256 = {
        let mut hasher = Sha256::new();
        hasher.update(data);
        let result = hasher.finalize();
        RetrievedDigest(result)
    };

    let sha512 = {
        let mut hasher = Sha512::new();
        hasher.update(data);
        let result = hasher.finalize();
        RetrievedDigest(result)
    };

    (sha256, sha512)
}

fn variant_name(&self) -> &'static str {
    match self {
        Color::RGB(..) => "RGB",
        Color::HSV(..) => "HSV",
        Color::Grey(..) => "Grey",
        Color::FromOutOfSpace => "FromOutOfSpace",
        Color::Black => "darkness",
    }
}

fn merge_with(self, other: Ini) -> Ini {
    let mut merged = Ini::new();
    let mut sections = OrderedHashMap::new();

    // Add all sections from the first Ini
    for (section_name, section) in self.document.iter() {
        let mut new_section = Section::new();
        for (key, value) in section.inner.iter() {
            new_section.inner.insert(key.clone(), value.clone());
        }
        sections.insert(section_name.clone(), new_section);
    }

    // Override sections from the second Ini
    for (section_name, section) in other.document.iter() {
        let mut new_section = Section::new();
        for (key, value) in section.inner.iter() {
            new_section.inner.insert(key.clone(), value.clone());
        }
        sections.insert(section_name.clone(), new_section);
    }

    merged.document = sections;
    merged.last_section_name = self.last_section_name;
    merged.empty_section = Section::new();
    merged
}

fn should_log(level: tracing_core::Level, min_severity: opentelemetry::logs::Severity) -> bool {
    match level {
        tracing_core::Level::ERROR => level >= tracing_core::Level::ERROR && min_severity <= Severity::ERROR,
        tracing_core::Level::WARN => level >= tracing_core::Level::WARN && min_severity <= Severity::WARN,
        tracing_core::Level::INFO => level >= tracing_core::Level::INFO && min_severity <= Severity::INFO,
        tracing_core::Level::DEBUG => level >= tracing_core::Level::DEBUG && min_severity <= Severity::DEBUG,
        tracing_core::Level::TRACE => level >= tracing_core::Level::TRACE && min_severity <= Severity::TRACE,
    }
}

