fn execute_with_retry<'a, S, P, R>(
    client: &RestClient<'a, S, P>,
    request: R,
    max_attempts: usize,
    base_delay: Duration,
) -> Result<(R::Response, Metric), P::OutputError>
where
    S: barter_integration::protocol::http::BuildStrategy,
    P: barter_integration::protocol::http::HttpParser,
    R: RestRequest + Send + 'static,
{
    let mut attempts = 0;
    let mut delay = base_delay;

    loop {
        attempts += 1;
        let result = client.execute(request.clone());
        match result {
            Ok((response, metric)) => {
                return Ok((response, metric));
            }
            Err(error) => {
                if attempts >= max_attempts {
                    return Err(error);
                }
                sleep(delay).await;
                delay = delay * 2;
            }
        }
    }
}

fn batch_notify_account_updates(
    plugins: &[LoadedGeyserPlugin],
    updates: &[ReplicaAccountInfoV3],
    slot: Slot,
) {
    if plugins.is_empty() || updates.is_empty() {
        return;
    }

    let mut plugin_notifications = Vec::new();

    for plugin in plugins {
        let mut plugin_updates = Vec::new();
        for update in updates {
            if update.version == ReplicaAccountInfoVersions::V3 as u32 {
                plugin_updates.push(update.clone());
            }
        }
        if !plugin_updates.is_empty() {
            plugin_notifications.push((plugin.clone(), plugin_updates));
        }
    }

    for (plugin, plugin_updates) in plugin_notifications {
        plugin.notify_account_updates(plugin_updates, slot);
    }
}

use std::{net::{SocketAddr, TcpStream, IpAddr}, io::{Read, Write}, time::Duration};
use crate::{HEADER_LENGTH, IP_ECHO_SERVER_RESPONSE_LENGTH, IpEchoServerMessage, IpEchoServerResponse};

fn get_public_ip_addr_with_timeout(
    ip_echo_server_addr: &SocketAddr,
    timeout: Duration,
) -> Result<IpAddr, String> {
    let mut stream = match TcpStream::connect_timeout(ip_echo_server_addr, timeout) {
        Ok(s) => s,
        Err(e) => return Err(format!("Failed to connect to IP echo server: {}", e)),
    };

    // Send the request
    let request = IpEchoServerMessage::default();
    if let Err(e) = stream.write_all(&request.0) {
        return Err(format!("Failed to send request: {}", e));
    }

    // Set a read timeout to match the overall timeout
    if let Err(e) = stream.set_read_timeout(Some(timeout)) {
        return Err(format!("Failed to set read timeout: {}", e));
    }

    // Read the response
    let mut buffer = vec![0; IP_ECHO_SERVER_RESPONSE_LENGTH];
    if let Err(e) = stream.read_exact(&mut buffer) {
        return Err(format!("Failed to read response: {}", e));
    }

    // Parse the response
    let response = IpEchoServerResponse::from_bytes(&buffer);
    if response.is_err() {
        return Err("Invalid response from IP echo server".to_string());
    }

    let ip_addr = match response.unwrap().ip_address {
        Some(ip) => ip,
        None => return Err("No IP address in response".to_string()),
    };

    Ok(ip_addr)
}

use dtg_lib::{Dtg, Format, DtgError, tz};
use jiff::tz::TimeZone;

fn hourly_timestamps(date: &str, tz_name: &str, fmt: &str) -> Result<Vec<String>, DtgError> {
    let dtg = Dtg::new(date, Format::Iso8601)?;
    let tz = tz::lookup(tz_name)?;
    let dtg_tz = dtg.in_timezone(tz);

    let start = dtg_tz.floor_to_hours();
    let end = start.add(Duration::hours(24));

    let mut timestamps = Vec::new();
    let mut current = start;

    while current < end {
        let dtg_current = Dtg::from(current);
        let formatted = dtg_current.format(fmt)?;
        timestamps.push(formatted);
        current = current.add(Duration::hours(1));
    }

    Ok(timestamps)
}

use std::net::SocketAddr;
use std::str::FromStr;

fn parse_host_with_default_port(
    host_input: &str,
    default_port: u16,
) -> Result<SocketAddr, String> {
    let parts: Vec<&str> = host_input.split(':').collect();

    if parts.len() == 1 {
        // Only hostname provided, use default port
        let host = parts[0];
        if let Ok(addr) = SocketAddr::from_str(&format!("{}:{}", host, default_port)) {
            return Ok(addr);
        } else {
            return Err(format!("Invalid hostname: {}", host));
        }
    } else if parts.len() == 2 {
        // Hostname and port provided
        let host = parts[0];
        if let Ok(port) = parts[1].parse::<u16>() {
            if let Ok(addr) = SocketAddr::from_str(&format!("{}:{}", host, port)) {
                return Ok(addr);
            } else {
                return Err(format!("Invalid hostname or port: {}", host_input));
            }
        } else {
            return Err(format!("Invalid port: {}", parts[1]));
        }
    } else {
        return Err(format!("Invalid format: {}", host_input));
    }
}

fn event_with_timestamp<T>(name: impl ToString, payload: &T) -> Event
where
    T: Serialize + Clone,
{
    let wrapper = TimestampedPayload {
        timestamp: SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_millis() as u128,
        inner: payload.clone(),
    };
    Event::with_payload(name, &wrapper)
}

fn second_element(vm: &mut Vm, var_name: &str) -> SourceResult<Option<Value>> {
    // Get the variable by name
    let var = vm.get_variable(var_name)
        .ok_or_else(|| bail!("Variable '{}' not found", var_name))?;

    // Check if the variable is an array
    if let Value::Array(arr) = var {
        // Check if the array has at least two elements
        if arr.len() >= 2 {
            // Return the second element (index 1)
            Ok(Some(arr[1].clone()))
        } else {
            // Array has fewer than two elements
            Ok(None)
        }
    } else {
        // Variable is not an array
        bail!("Variable '{}' is not an array", var_name)
    }
}

