use async_tempfile::{TempDir, Error};
use std::path::Path;
use tokio::fs::{self, DirEntry};
use tokio::io::AsyncReadExt;
use tokio::sync::Mutex;
use std::collections::VecDeque;

fn copy_dir_to_temp<P>(src: P) -> Result<TempDir, Error>
where
    P: AsRef<std::path::Path>,
{
    let temp_dir = TempDir::new()?;
    let src_path = src.as_ref();
    let dst_path = temp_dir.path();

    copy_dir_contents(src_path, dst_path).unwrap();

    Ok(temp_dir)
}

async fn copy_dir_contents(src: &Path, dst: &Path) {
    let mut entries = fs::read_dir(src).await.unwrap();
    let mut queue = VecDeque::new();

    while let Some(entry) = entries.next_entry().await.unwrap() {
        queue.push_back(entry);
    }

    while let Some(entry) = queue.pop_front() {
        let file_type = entry.file_type().await.unwrap();
        let src_path = entry.path();
        let dst_path = dst.join(src_path.file_name().unwrap());

        if file_type.is_dir() {
            fs::create_dir(&dst_path).await.unwrap();
            let mut sub_entries = fs::read_dir(&src_path).await.unwrap();
            while let Some(sub_entry) = sub_entries.next_entry().await.unwrap() {
                queue.push_back(sub_entry);
            }
        } else {
            let mut file = fs::File::open(&src_path).await.unwrap();
            let mut contents = Vec::new();
            file.read_to_end(&mut contents).await.unwrap();
            fs::write(&dst_path, contents).await.unwrap();
        }
    }
}

