fn batch_insert_to_disk<K, V, S>(cache: &HybridCache<K, V, S>, entries: Vec<(K, V)>) -> Vec<HybridCacheEntry<K, V, S>>
where
    K: StorageKey + Clone,
    V: StorageValue,
    S: HashBuilder + Debug,
{
    let mut writer = cache.writer();
    let mut inserted_entries = Vec::new();

    for (key, value) in entries {
        let entry = HybridCacheEntry::new(key.clone(), value);
        let result = writer.insert(entry);

        match result {
            Ok(entry) => inserted_entries.push(entry),
            Err(e) => {
                // Handle error, e.g., log or panic
                panic!("Failed to insert entry: {:?}", e);
            }
        }
    }

    writer.flush().expect("Failed to flush writer");
    inserted_entries
}

use anyhow::Result;
use rusqlite::Connection;
use std::path::Path;
use sqlite2parquet::{Column, infer_schema, write_table};

fn export_timestamp_range(
    conn: &rusqlite::Connection,
    table: &str,
    start_ts: i64,
    end_ts: i64,
    out_path: &Path,
) -> Result<()> {
    // Build the SQL query with WHERE clause for timestamp range
    let query = format!(
        "SELECT * FROM {} WHERE timestamp_column BETWEEN {} AND {}",
        table, start_ts, end_ts
    );

    // Execute the query and collect results
    let mut stmt = conn.prepare(&query)?;
    let mut rows = stmt.query_map([], |row| {
        Ok(row.collect::<Result<Vec<_>, _>>())
    })?;

    // Collect rows into a Vec
    let mut data = Vec::new();
    for row in rows {
        let row_data = row?;
        data.push(row_data);
    }

    // Infer schema from the first row
    let schema = infer_schema(&data)?;

    // Define column definitions
    let columns: Vec<Column> = schema
        .iter()
        .enumerate()
        .map(|(i, name)| Column {
            name: name.to_string(),
            data_type: schema[i].data_type.clone(),
        })
        .collect();

    // Write the data to a parquet file
    write_table(&data, &columns, out_path)?;

    Ok(())
}

