fn connect_with_retry_and_logging(
    connector: &IrohConnector,
    peer_id: PeerId,
) -> PeerResult<DynClientConnection> {
    let max_retries = 5;
    let mut retry_count = 0;
    let mut connection = None;

    while retry_count < max_retries {
        match connector.connect(peer_id) {
            Ok(conn) => {
                connection = Some(conn);
                break;
            }
            Err(PeerError::NetworkError(e)) => {
                warn!(target: LOG_NET_IROH, "Network error connecting to peer {}: {}", peer_id, e);
                retry_count += 1;
                if retry_count < max_retries {
                    warn!(target: LOG_NET_IROH, "Retrying connection to peer {} (Attempt {retry_count}/{max_retries})", peer_id);
                    std::thread::sleep(std::time::Duration::from_secs(2));
                } else {
                    return Err(anyhow!("Failed to connect to peer {} after {} attempts", peer_id, max_retries));
                }
            }
            Err(PeerError::ConnectionClosed) => {
                warn!(target: LOG_NET_IROH, "Connection to peer {} closed", peer_id);
                return Err(anyhow!("Connection to peer {} closed", peer_id));
            }
            Err(e) => {
                warn!(target: LOG_NET_IROH, "Unexpected error connecting to peer {}: {}", peer_id, e);
                return Err(e.into());
            }
        }
    }

    connection.ok_or(anyhow!("Failed to establish connection after retries"))
}

use anyhow::Result;
use std::path::Path;
use std::fs;
use toml_edit::Document;
use std::str::FromStr;

fn list_workspace_packages(root: &Path) -> Result<Vec<String>> {
    let mut packages = Vec::new();
    let workspace_dir = root.join("Cargo.toml");
    if !workspace_dir.exists() {
        return Ok(packages);
    }

    let content = fs::read_to_string(workspace_dir)?;
    let doc: Document = content.parse().unwrap();
    let workspace_table = doc.as_table().get("workspace").and_then(|v| v.as_table());

    if let Some(workspace_table) = workspace_table {
        if let Some(members) = workspace_table.get("members").and_then(|v| v.as_array()) {
            for member in members {
                if let Some(member_str) = member.as_str() {
                    let member_path = root.join(member_str);
                    if member_path.exists() {
                        let member_cargo = member_path.join("Cargo.toml");
                        if member_cargo.exists() {
                            let member_content = fs::read_to_string(member_cargo)?;
                            let member_doc: Document = member_content.parse().unwrap();
                            if let Some(package_table) = member_doc.as_table().get("package") {
                                if let Some(name) = package_table.get("name").and_then(|v| v.as_str()) {
                                    packages.push(name.to_string());
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    Ok(packages)
}

