use failure::Error;
use gcsf::{FileManager, FileId};
use fuser::FileType;

fn calculate_directory_size(
    manager: &mut FileManager,
    dir_inode: u64,
) -> Result<u64, Error> {
    let mut total_size = 0;

    // Get the directory's entries
    let entries = manager.readdir(dir_inode, 0)?; // Assuming readdir is called with offset 0

    for entry in entries {
        let file_id = entry.file_id;
        let file_type = manager.get_file_type(file_id)?;

        if file_type == FileType::Directory {
            // Recurse into subdirectories
            let sub_size = calculate_directory_size(manager, file_id)?;
            total_size += sub_size;
        } else {
            // Add file size directly
            let file_size = manager.get_file_size(file_id)?;
            total_size += file_size;
        }
    }

    Ok(total_size)
}

fn wait_for_transaction_confirmation(
    bitcoin: &impl BitcoinTest,
    txid: &Txid,
    min_confirmations: u64,
) -> Result<(), anyhow::Error> {
    let mut confirmations = 0;
    let mut wait_time = Duration::from_secs(10);

    loop {
        let tx_info = bitcoin.get_transaction_info(txid)?;
        confirmations = tx_info.confirmations;

        if confirmations >= min_confirmations {
            return Ok(());
        }

        if wait_time > Duration::from_secs(60 * 60) {
            return Err(anyhow::anyhow!("Transaction confirmation timeout"));
        }

        sleep(wait_time).await;
        wait_time *= 2;
    }
}

