use std::sync::Mutex;

lazy_static! {
    static ref PREV_POSITION: Mutex<Option<(i32, i32)>> = Mutex::new(None);
}

fn mouse_delta() -> Option<(i32, i32)> {
    let state = DeviceState::new();
    let current_position = (state.mouse_x as i32, state.mouse_y as i32);

    let mut prev_pos = PREV_POSITION.lock().unwrap();
    let delta = match *prev_pos {
        Some((prev_x, prev_y)) => Some((current_position.0 - prev_x, current_position.1 - prev_y)),
        None => {
            *prev_pos = Some(current_position);
            None
        }
    };

    delta
}

fn extract_rewards(
    rewards: &RwLock<Vec<(Pubkey, RewardInfo)>>,
) -> Vec<RewardSummary> {
    let read_lock = rewards.read().unwrap();
    let mut result = Vec::new();
    for (pubkey, reward_info) in read_lock.iter() {
        let reward_type = match reward_info.reward_type {
            RewardType::BlockReward => "BlockReward",
            RewardType::Fee => "Fee",
            RewardType::Stake => "Stake",
            RewardType::Other => "Other",
        };
        result.push(RewardSummary {
            pubkey: *pubkey,
            reward_type: reward_type.to_string(),
            amount: reward_info.amount,
        });
    }
    result
}

