use async_http_range_reader::AsyncHttpRangeReaderError;
use reqwest::{Client, Url, Method};
use reqwest::header::ACCEPT_RANGES;

fn is_range_supported(client: &Client, url: &Url) -> Result<bool, AsyncHttpRangeReaderError> {
    let response = client.head(url)
        .send()
        .map_err(|e| AsyncHttpRangeReaderError::RequestError(e.to_string()))?;

    if let Some(range_header) = response.headers().get(ACCEPT_RANGES) {
        if let Ok(range_header_value) = range_header.to_str() {
            return Ok(range_header_value.eq("bytes"));
        }
    }

    Ok(false)
}

