    ttl: Duration,
    fees: RoutingFees,
) -> Result<LightningGatewayAnnouncement, anyhow::Error> {
    // Validate api_url format
    if api_url.scheme() != "https" {
        return Err(anyhow::anyhow!("API URL must use HTTPS scheme"));
    }

    // Validate that route hints are not empty
    if route_hints.is_empty() {
        return Err(anyhow::anyhow!("At least one route hint is required"));
    }

    // Validate that TTL is positive
    if ttl <= Duration::from_secs(0) {
        return Err(anyhow::anyhow!("TTL must be a positive duration"));
    }

    // Validate that federation index is non-zero
    if federation_index == 0 {
        return Err(anyhow::anyhow!("Federation index must be a non-zero value"));
    }

    // Construct the LightningGatewayAnnouncement
    let gateway = LightningGateway {
        api_url: api_url.clone(),
        federation_index,
        route_hints,
        ttl,
        fees,
    };

    // Sign the gateway announcement with the provided keypair
    let signed_announcement = lightning_context.sign_gateway_announcement(gateway, gateway_keypair)?;

    Ok(signed_announcement)
}

fn validate_bitcoin_rpc_config(config: &BitcoinRpcConfig) -> Result<(), String> {
    if config.network != Network::Mainnet && config.network != Network::Testnet && config.network != Network::Regtest {
        return Err("Invalid network specified. Must be Mainnet, Testnet, or Regtest.".to_string());
    }

    if config.url.is_empty() {
        return Err("RPC URL cannot be empty.".to_string());
    }

    if !config.url.starts_with("http://") && !config.url.starts_with("https://") {
        return Err("RPC URL must start with http:// or https://.".to_string());
    }

    Ok(())
}

fn decompress_gzip_file(input_path: &str, expected_content: &[u8]) -> Result<(), Box<dyn Error>> {
    let file = File::open(input_path)?;
    let reader = BufReader::new(file);
    let mut decompressor = Decompressor::new();
    let mut decompressed_data = Vec::new();
    let mut buffer = [0; 1024];

    loop {
        let bytes_read = reader.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }
        let decompressed = decompressor.decompress(&buffer[..bytes_read], &mut decompressed_data)?;
        if decompressed {
            // Continue decompression
        } else {
            // No more data to decompress
            break;
        }
    }

    // Check if decompression was successful
    if decompressor.finish(&mut decompressed_data)? {
        // Verify content
        if decompressed_data == expected_content {
            Ok(())
        } else {
            Err("Decompressed data does not match expected content".into())
        }
    } else {
        Err("Decompression failed".into())
    }
}

use tui_tree_widget::TreeItem;

pub fn filter_items_by_identifier<T>(items: &[TreeItem<'static, T>], pattern: &str) -> Vec<TreeItem<'static, T>>
where
    T: AsRef<str> + Clone,
{
    items
        .iter()
        .filter_map(|item| {
            if item.identifier.as_ref().contains(pattern) {
                Some(item.clone())
            } else {
                let filtered_children = filter_items_by_identifier(&item.children, pattern);
                if !filtered_children.is_empty() {
                    let mut new_item = item.clone();
                    new_item.children = filtered_children;
                    Some(new_item)
                } else {
                    None
                }
            }
        })
        .collect()
}

