fn batch_writable_accounts(accounts: &[Pubkey]) -> Vec<Vec<Pubkey>> {
    let mut batches = Vec::new();
    let mut current_batch = Vec::new();
    let mut current_cost = 0;

    for &account in accounts {
        let account_cost = WRITE_LOCK_UNITS;
        if current_cost + account_cost > MAX_WRITABLE_ACCOUNT_UNITS {
            batches.push(current_batch);
            current_batch = Vec::new();
            current_cost = 0;
        }
        current_batch.push(account);
        current_cost += account_cost;
    }

    if !current_batch.is_empty() {
        batches.push(current_batch);
    }

    batches
}

