use std::fs::File;
use std::io::{self, BufReader, Read};
use std::path::Path;
use sp800_185::ParallelHash;

fn hash_file_parallel<P: AsRef<Path>>(path: P, custom: &[u8], blocksize: usize, security_strength: u8) -> io::Result<Vec<u8>> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);

    let mut ph = match security_strength {
        128 => ParallelHash::new_sha3_128(custom, blocksize),
        256 => ParallelHash::new_sha3_256(custom, blocksize),
        _ => return Err(io::Error::new(io::ErrorKind::InvalidInput, "Unsupported security strength")),
    };

    let mut buffer = [0; 1024];
    loop {
        let bytes_read = reader.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }
        ph.update(&buffer[..bytes_read]);
    }

    Ok(ph.finalize().to_vec())
}

