fn use_debounced_signal<T: Clone + 'static>(signal: ReadOnlySignal<T>, delay_ms: u64) -> Signal<T> {
    use dioxus::prelude::*;
    use dioxus_core::spawn;
    use dioxus_signals::Signal;
    use std::time::Duration;

    let (debounced_signal, set_debounced_signal) = use_signal(|| signal.get().clone());

    use_effect(move || {
        let signal = signal.clone();
        let set_debounced_signal = set_debounced_signal.clone();
        let delay = delay_ms;

        spawn(async move {
            let value = signal.get().clone();
            let _ = set_debounced_signal(value);
        });

        let delay = Duration::from_millis(delay_ms);
        let mut last_value = signal.get().clone();
        let mut timer = std::time::Instant::now();

        loop {
            let now = std::time::Instant::now();
            if now - timer > delay {
                timer = now;
                let current_value = signal.get().clone();
                if current_value != last_value {
                    last_value = current_value;
                    set_debounced_signal(current_value);
                }
            }
            std::thread::sleep(Duration::from_nanos(100));
        }
    });

    debounced_signal
}

