fn batch_verify_cose_vcs(vcs: &[CoseSign1Bytes], key: &CoseKey) -> Vec<Result<(), SignatureError>> {
    let params = VerificationParameters::new().with_key(key);
    let futures = vcs.iter().map(|vc| {
        let params = params.clone();
        async move {
            let vc = CoseVc::from_bytes(vc.as_ref()).map_err(|e| SignatureError::from(e))?;
            vc.verify(&params).map_err(|e| SignatureError::from(e))
        }
    });
    futures::future::join_all(futures).await
}

fn execute_transactions(
    pool: &InstalledSchedulerPoolArc,
    bank: Arc<Bank>,
    transactions: Vec<SanitizedTransaction>,
) -> ResultWithTimings {
    let mut context = SchedulingContext::new();
    let mut scheduler = pool.acquire_scheduler();
    let mut timings = Vec::new();

    for transaction in transactions {
        let task = Task::new(transaction, &bank, &mut context);
        scheduler.schedule(task);
        timings.push(std::time::Instant::now());
    }

    scheduler.wait();
    let mut result = initialized_result_with_timings();
    for (i, start_time) in timings.iter().enumerate() {
        let duration = std::time::Instant::now() - *start_time;
        result.timings.push((i, duration));
    }

    result
}

fn extract_tag_names_and_types(
    tagger: &tree_sitter_tags::TSTagger,
    scope_name: &str,
    source_code: &[u8],
) -> Vec<(String, String)> {
    let buffer = unsafe { ts_tags_buffer_new(source_code.as_ptr(), source_code.len() as _) };
    if buffer.is_null() {
        return Vec::new();
    }

    let tags = unsafe { ts_tags_buffer_tags(buffer) };
    let tags_len = unsafe { ts_tags_buffer_tags_len(buffer) };

    let syntax_kinds = unsafe { ts_tagger_syntax_kinds_for_scope_name(tagger, scope_name.as_ptr() as _) };

    let mut result = Vec::new();
    for i in 0..tags_len {
        let tag = unsafe { ts_tagger_tag(tagger, tags.add(i)) };
        if tag.is_null() {
            continue;
        }

        let name = unsafe { CString::from_raw(*tag as _) };
        let name_str = name.to_str().unwrap_or("").to_string();
        unsafe { CString::free(name.as_ptr()) };

        let syntax_kind = unsafe { *syntax_kinds.add(i) };
        let syntax_type = match syntax_kind {
            0 => "unknown".to_string(),
            1 => "constant".to_string(),
            2 => "function".to_string(),
            3 => "variable".to_string(),
            4 => "class".to_string(),
            5 => "interface".to_string(),
            6 => "enum".to_string(),
            7 => "type".to_string(),
            8 => "module".to_string(),
            9 => "macro".to_string(),
            10 => "property".to_string(),
            11 => "method".to_string(),
            12 => "parameter".to_string(),
            13 => "return".to_string(),
            14 => "label".to_string(),
            15 => "type_alias".to_string(),
            _ => "other".to_string(),
        };

        result.push((name_str, syntax_type));
    }

    unsafe {
        ts_tags_buffer_delete(buffer);
    }

    result
}

use ckb_shared::Shared;
use ckb_app_config::ExitCode;

fn uncle_rate(shared: &Shared, from: u64, to: u64) -> Result<f64, ExitCode> {
    let block_count = to - from;
    if block_count == 0 {
        return Err(ExitCode::Error);
    }

    let mut uncle_blocks = 0;
    let mut current_block = from;

    while current_block < to {
        if let Some(block) = shared.get_block_by_number(current_block) {
            if let Some(parent_block) = shared.get_block_by_number(block.parent_hash()) {
                if block.header().timestamp() > parent_block.header().timestamp() {
                    uncle_blocks += 1;
                }
            }
        }
        current_block += 1;
    }

    Ok(uncle_blocks as f64 / block_count as f64)
}

