fn format_dependency(name: &str, version: &str, features: &[&str]) -> String {
    let mut features_str = String::new();
    if !features.is_empty() {
        features_str.push_str("features = [");
        for (i, &feature) in features.iter().enumerate() {
            if i > 0 {
                features_str.push_str(", ");
            }
            features_str.push_str(feature);
        }
        features_str.push_str("]");
    }
    format!("{} {}{}", name, version, features_str)
}

fn stmt_result_to_csv(result: &StmtResult) -> String {
    if result.columns.is_empty() || result.rows.is_empty() {
        return String::new();
    }

    let header = result.columns.iter().map(|col| col.name.clone()).collect::<Vec<String>>().join(",");
    let mut csv = String::with_capacity(header.len() + 1000);
    csv.push_str(&header);
    csv.push('\n');

    for row in &result.rows {
        let mut row_data = Vec::new();
        for value in &row.values {
            match value {
                Value::Null => row_data.push(String::from("")),
                Value::Integer(i) => row_data.push(i.to_string()),
                Value::Real(r) => row_data.push(r.to_string()),
                Value::Text(t) => row_data.push(t.clone()),
                Value::Bytes(b) => row_data.push(format!("{:?}", b)),
                Value::Bool(b) => row_data.push(b.to_string()),
            }
        }
        csv.push_str(&row_data.join(","));
        csv.push('\n');
    }

    csv
}

