use std::fs::File;
use std::io::{BufReader, Read};
use arrow_array::StringArray;
use fsst::fsst::{compress, FSST_SYMBOL_TABLE_SIZE};

fn estimate_compression_ratio(file_path: &str, sample_chars: usize) -> std::io::Result<f64> {
    let file = File::open(file_path)?;
    let mut reader = BufReader::new(file);
    let mut buffer = Vec::new();
    reader.read_to_end(&mut buffer)?;

    if buffer.len() < sample_chars {
        return Err(std::io::Error::new(std::io::ErrorKind::InvalidData, "File too small for sample"));
    }

    let sample = &buffer[..sample_chars];
    let sample_str = String::from_utf8_lossy(sample);

    let compressed = compress(sample_str.as_bytes(), FSST_SYMBOL_TABLE_SIZE);
    let original_size = sample_chars as f64;
    let compressed_size = compressed.len() as f64;

    Ok(original_size / compressed_size)
}

macro_rules! binary_op_enum {
    ($name:ident, $precedence:expr, $($op:expr),*) => {
        enum $name {
            $($op),*
        }

        impl $name {
            pub fn precedence(&self) -> usize {
                match self {
                    $($op => $precedence),*
                }
            }
        }
    };
}

fn cairo_path_to_svg(path: *mut cairo_path_t) -> String {
    unsafe {
        let mut result = String::new();
        let path_data = (*path).data;
        let num_data = (*path).num_data as usize;

        for i in 0..num_data {
            let data = *path_data.add(i);
            let header = data.header;
            let data_type = header.data_type;

            match data_type {
                PATH_DATA_TYPE_MOVE_TO => {
                    let point = data.point;
                    result.push_str(&format!("M {} {}", point[0], point[1]));
                }
                PATH_DATA_TYPE_LINE_TO => {
                    let point = data.point;
                    result.push_str(&format!("L {} {}", point[0], point[1]));
                }
                PATH_DATA_TYPE_CURVE_TO => {
                    let point = data.point;
                    result.push_str(&format!("C {} {} {} {} {} {}", point[0], point[1], point[2], point[3], point[4], point[5]));
                }
                PATH_DATA_TYPE_CLOSE_PATH => {
                    result.push_str("Z");
                }
                _ => {}
            }
        }

        result
    }
}

use oxc_semantic::{Scoping, SymbolId};
use oxc_index::Idx;
use std::collections::HashMap;

type Slot = usize;

fn compute_slot_frequencies(scoping: &Scoping, slots: &[Slot]) -> Vec<(Slot, usize)> {
    let mut frequency_map = HashMap::new();

    for &slot in slots {
        let symbol_id = scoping.slot_to_symbol(slot);
        if let Some(symbol_id) = symbol_id {
            let symbol = scoping.symbol(symbol_id);
            if let Some(symbol) = symbol {
                // Count each symbol occurrence per slot
                *frequency_map.entry(slot).or_insert(0) += 1;
            }
        }
    }

    let mut result: Vec<(Slot, usize)> = frequency_map.into_iter().collect();
    result.sort_by(|a, b| b.1.cmp(&a.1));
    result
}

fn filter_avro_reader<R, F>(mut reader: Reader<R>, predicate: F) -> impl Iterator<Item = ArrowResult<RecordBatch>>
where
    R: std::io::Read,
    F: Fn(&RecordBatch) -> bool,
{
    std::iter::from_fn(move || {
        let batch_result = reader.next();
        match batch_result {
            Some(Ok(batch)) if predicate(&batch) => Some(Ok(batch)),
            Some(Ok(_)) => None,
            Some(Err(e)) => Some(Err(e)),
            None => None,
        }
    })
}

fn bulk_upsert(storage: &MongoStorage, table_name: &str, rows: Vec<(Key, DataRow)>) -> Result<()> {
    let collection = storage.collection(table_name)?;
    let mut docs = Vec::new();

    for (key, row) in rows {
        let doc = doc! {
            "_id": key.into_bson()?,
            "data": row.into_bson()?,
        };
        docs.push(doc);
    }

    let options = ReplaceOptions::builder().upsert(true).build();
    collection.bulk_write(docs, options)?;
    Ok(())
}

