    if path.exists() {
        // Check if the user wants to overwrite the existing file
        if args.overwrite {
            if let Err(e) = write_secret_to_file(&args.secret_path, &secret) {
                return Err(ExitCode::from(e));
            }
            println!("Overwrote peer ID key file at: {}", &args.secret_path);
        } else {
            eprintln!("Error: The file '{}' already exists and overwrite is not allowed.", &args.secret_path);
            return Err(ExitCode::from(1));
        }
    } else {
        if let Err(e) = write_secret_to_file(&args.secret_path, &secret) {
            return Err(ExitCode::from(e));
        }
        println!("Generated and saved peer ID key file at: {}", &args.secret_path);
    }

    Ok(())
}

use pio::{Assembler, Program, SideSet, WaitSource, InSource, JmpCondition};

fn generate_sampling_program() -> Program<32> {
    let mut asm = Assembler::new();

    // Set up the side-set for toggling the auxiliary pin
    asm.side_set(SideSet::new().bit(0).set(1));

    // Wait for the start condition
    asm.wait(WaitSource::In(InSource::Pin(0)), 0);

    // Main loop: sample the input pin and toggle the side-set bit
    asm.label("loop");
    asm.in_(InSource::Pin(0), 0); // Sample the input pin
    asm.side_set(SideSet::new().bit(0).set(1)); // Toggle the auxiliary pin
    asm.out(0, 0); // Push the sampled bit into the TX FIFO
    asm jmp(JmpCondition::always, "loop");

    Program::from_asm(asm)
}

use anyhow::Result;
use bytes::Bytes;

const TC_TF_PH_SIZE: usize = 5;
const TC_SEG_HDR_SIZE: usize = 1;
const TC_TF_FECF_SIZE: usize = 2;
const MAX_SPACE_PACKET_SIZE: usize = 444 - 12;

fn from_tc_tf(tc_tf: Bytes) -> Result<Bytes> {
    // Check if the input is long enough to contain at least the payload header
    if tc_tf.len() < TC_TF_PH_SIZE {
        return Err(anyhow::anyhow!("Input too short to contain payload header"));
    }

    // Extract payload header
    let payload_header = &tc_tf[..TC_TF_PH_SIZE];
    let payload_length = u16::from_be_bytes(payload_header[3..5].try_into().unwrap()) as usize;

    // Validate payload length
    if payload_length > MAX_SPACE_PACKET_SIZE {
        return Err(anyhow::anyhow!("Payload length exceeds maximum allowed size"));
    }

    // Calculate required minimum size for the packet
    let min_required_size = TC_TF_PH_SIZE + payload_length;

    // Check if the input is long enough to contain the entire payload
    if tc_tf.len() < min_required_size {
        return Err(anyhow::anyhow!("Input too short to contain full payload"));
    }

    // Extract the full payload
    let payload = &tc_tf[..min_required_size];

    Ok(payload.to_vec().into())
}

