use webm_iterable::matroska_spec::{Block, BlockLacing};
use webm_iterable::errors::WebmCoercionError;

fn convert_xiph_to_fixed<'a>(block: Block<'a>) -> Result<Block<'static>, WebmCoercionError> {
    if block.lacing != BlockLacing::Xiph {
        return Err(WebmCoercionError::InvalidLacing);
    }

    let frames = block.frames;
    let first_frame_size = frames[0].size;

    for &frame_size in &frames[1..] {
        if frame_size != first_frame_size {
            return Err(WebmCoercionError::NonUniformFrameSizes);
        }
    }

    let mut new_frames = Vec::with_capacity(frames.len());
    for &frame_size in &frames {
        new_frames.push(frame_size);
    }

    Ok(Block {
        lacing: BlockLacing::FixedSize,
        frames: new_frames,
    })
}

fn send_transaction_with_backoff(
    tpu_client: &QuicTpuClient,
    transaction: &Transaction,
    max_retries: u32,
    initial_delay: Duration,
    backoff_factor: f64,
) -> TransportResult<()> {
    let mut retries = 0;
    let mut delay = initial_delay;

    loop {
        match tpu_client.send_transaction(transaction) {
            Ok(_) => return Ok(()),
            Err(TpuSenderError::Transient) => {
                if retries >= max_retries {
                    return Err(TpuSenderError::MaxRetriesExceeded.into());
                }
                retries += 1;
                sleep(delay).await?;
                delay = Duration::from_nanos((delay.as_nanos() as f64 * backoff_factor) as u64);
            }
            Err(e) => return Err(e.into()),
        }
    }
}

