fn batch_ping<C>(client: &C, names: Vec<String>) -> Result<Vec<PingResponse>, ClientError>
where
    C: TestApiClient + Sync,
{
    let mut futures = Vec::new();
    for name in names {
        let client = client.clone();
        let request = PingRequest {
            name: name.clone(),
        };
        let fut = future::lazy(move || {
            client.ping(request).map(|res| res.into_inner())
        });
        futures.push(fut);
    }

    let results = future::join_all(futures).map(|results| results.into_iter().collect::<Result<Vec<_>, _>>())
        .map_err(|e| e.into())?;

    Ok(results)
}

fn compute_merkle_root(mut hashes: Vec<H256>) -> H256 {
    while hashes.len() > 1 {
        let mut new_hashes = Vec::new();
        for i in (0..hashes.len()).step_by(2) {
            let right = if i + 1 < hashes.len() { hashes[i + 1] } else { hashes[i] };
            let left = hashes[i];
            let mut hasher = Sha256::new();
            hasher.update(left.as_bytes());
            hasher.update(right.as_bytes());
            let mut combined = [0u8; 32];
            combined.copy_from_slice(&hasher.finalize());
            new_hashes.push(H256::from_slice(&combined));
        }
        hashes = new_hashes;
    }
    hashes[0]
}

use atoi::FromRadix10Checked;

fn parse_u32_list(text: &[u8]) -> Option<Vec<u32>> {
    let mut result = Vec::new();
    let mut current = Vec::new();
    let mut in_number = false;

    for &b in text {
        if b == b',' {
            if in_number {
                if let Ok(num) = u32::from_radix_10_checked(&current) {
                    result.push(num);
                } else {
                    return None;
                }
                current = Vec::new();
                in_number = false;
            }
        } else if b == b' ' || b == b'\t' || b == b'\n' || b == b'\r' {
            if in_number {
                if let Ok(num) = u32::from_radix_10_checked(&current) {
                    result.push(num);
                } else {
                    return None;
                }
                current = Vec::new();
                in_number = false;
            }
        } else if b.is_ascii_digit() {
            current.push(b);
            in_number = true;
        } else {
            return None;
        }
    }

    if in_number {
        if let Ok(num) = u32::from_radix_10_checked(&current) {
            result.push(num);
        } else {
            return None;
        }
    }

    Some(result)
}

