fn batch_insert_with_retries(client: &Client) -> Result<()> {
    let mut batch = Batch::new();
    // Assume we have a list of statements to insert
    let stmts: Vec<Stmt> = vec![
        Stmt::new("INSERT INTO users (name) VALUES ('Alice')".to_string()),
        Stmt::new("INSERT INTO users (name) VALUES ('Bob')".to_string()),
        Stmt::new("INSERT INTO users (name) VALUES ('Charlie')".to_string()),
    ];

    let max_retries = 3;
    let mut retry_count = 0;

    while retry_count < max_retries {
        let mut failed_stmts = Vec::new();
        let mut success_count = 0;

        for stmt in &stmts {
            match client.execute(stmt) {
                Ok(_) => {
                    success_count += 1;
                    info!("Statement executed successfully: {:?}", stmt);
                }
                Err(e) => {
                    error!("Statement failed: {:?}, error: {}", stmt, e);
                    failed_stmts.push(stmt.clone());
                }
            }
        }

        if success_count == stmts.len() {
            info!("All statements executed successfully.");
            return Ok(());
        }

        if failed_stmts.is_empty() {
            break;
        }

        info!("Retrying failed statements...");
        retry_count += 1;

        // Retry only the failed statements
        for stmt in failed_stmts {
            match client.execute(&stmt) {
                Ok(_) => {
                    info!("Retried statement executed successfully: {:?}", stmt);
                }
                Err(e) => {
                    error!("Retry failed: {:?}, error: {}", stmt, e);
                }
            }
        }
    }

    error!("Maximum retries reached. Some statements failed.");
    Ok(())
}

use pio::{Assembler, SideSet, InSource, MovDestination, MovOperation, MovSource, JmpCondition, Program, Label};

fn generate_pin_sampler(sample_pin: u8, side_set_delay: u8) -> pio::Program<32> {
    let mut assembler = Assembler::new();
    let mut program = Program::new();

    // Label for the start of the loop
    let start_label = assembler.label();
    let shift_label = assembler.label();
    let side_set_label = assembler.label();
    let end_label = assembler.label();

    // Set up the side set pin
    assembler.side_set(SideSet::new(0, 1).with_delay(side_set_delay));
    assembler.in_source(InSource::new(0, sample_pin));
    assembler.mov(MovOperation::new(MovDestination::x, MovSource::in_0));
    assembler.mov(MovOperation::new(MovDestination::osr, MovSource::x));
    assembler.mov(MovOperation::new(MovDestination::x, MovSource::literal(0)));
    assembler jmp(JmpCondition::always, start_label);

    // Label for the start of the loop
    assembler.label(start_label);
    assembler.side_set(SideSet::new(0, 1).with_delay(side_set_delay));
    assembler.in_source(InSource::new(0, sample_pin));
    assembler.mov(MovOperation::new(MovDestination::x, MovSource::in_0));
    assembler.mov(MovOperation::new(MovDestination::osr, MovSource::x));
    assembler.mov(MovOperation::new(MovDestination::x, MovSource::literal(0)));
    assembler jmp(JmpCondition::always, start_label);

    program.instructions = assembler.instructions;
    program
}

