fn open_substream_with_timeout<C>(mux: &Multiplex<C>, dur: Duration) -> Result<Substream<C>, io::Error>
where
    C: AsyncRead + AsyncWrite + Unpin,
{
    let substream_future = mux.next().map(|substream| substream.map_err(|e| io::Error::new(io::ErrorKind::Other, e)));
    let timeout_future = timeout(dur, substream_future);

    match timeout_future.await {
        Ok(substream) => substream?,
        Err(_) => return Err(io::Error::new(io::ErrorKind::TimedOut, "Timeout while opening substream")),
    }
}

