fn total_gas_burnt_for_block(client: &Addr<near_client::ViewClientActor>, block_hash: CryptoHash, shard_tracker: &ShardTracker) -> Result<u64, FailedToFetchData> {
    // Fetch all outcomes for the block
    let outcomes = fetch_outcomes(client, block_hash, shard_tracker)?;

    // Calculate total gas burnt
    let total_gas_burnt: u64 = outcomes
        .iter()
        .filter_map(|outcome| {
            if let ExecutionOutcomeWithId::Success(outcome) = outcome {
                Some(outcome.outcome.gas_burnt)
            } else {
                None
            }
        })
        .sum();

    Ok(total_gas_burnt)
}

