fn directory_index(path: &std::path::Path, req_path: &str) -> conduit::Response<conduit::Body> {
    if !path.exists() || !path.is_dir() {
        return conduit::Response::new(
            conduit::StatusCode::NOT_FOUND,
            vec![],
            conduit::Body::from("Not found"),
        );
    }

    let mut entries = Vec::new();
    if let Ok(entries_list) = fs::read_dir(path) {
        for entry in entries_list {
            if let Ok(entry) = entry {
                let file_name = entry.file_name();
                let file_name_str = file_name.to_str().unwrap_or("");
                if file_name_str == "." || file_name_str == ".." {
                    continue;
                }
                entries.push(file_name_str.to_string());
            }
        }
    }

    let html = format!(
        "<html><body><h1>Index of {}</h1><ul>",
        req_path
    );

    for entry in &entries {
        html.push_str(&format!("<li><a href=\"{}\">{}</a></li>", entry, entry));
    }

    html.push_str("</ul></body></html>");

    conduit::Response::new(
        conduit::StatusCode::OK,
        vec![
            (header::CONTENT_TYPE, "text/html"),
            (header::CONTENT_LENGTH, html.len().to_string()),
        ],
        conduit::Body::from(html),
    )
}

fn salted_sha2(expr: ColumnarValue, salt: &str) -> Result<ColumnarValue> {
    match expr {
        ColumnarValue::Scalar(scalar) => {
            if let ScalarValue::String(s) = scalar {
                let hash = sha2(s.as_str().as_bytes(), salt.as_bytes());
                Ok(ColumnarValue::Scalar(ScalarValue::String(hash)))
            } else {
                Err(internal_err!("Expected string input for salted_sha2"))
            }
        }
        ColumnarValue::Array(array) => {
            let array_ref = array.array().as_any().downcast_ref::<StringArray>().ok_or_else(|| {
                internal_err!("Expected StringArray for salted_sha2")
            });

            let mut builder = StringArray::with_capacity(array_ref.len());
            for i in 0..array_ref.len() {
                if let Some(value) = array_ref.value(i) {
                    let hash = sha2(value.as_bytes(), salt.as_bytes());
                    builder.push_value(hash);
                } else {
                    builder.push_null();
                }
            }

            Ok(ColumnarValue::Array(Arc::new(builder)))
        }
    }
}

fn sha2(input: &[u8], salt: &[u8]) -> String {
    let mut hasher = sha2::Sha256::new();
    hasher.update(input);
    hasher.update(salt);
    let result = hasher.finalize();
    hex::encode(result)
}

use anyhow::Result;
use monger_core::fs::Fs;
use semver::Version;

fn prune_custom_versions(threshold: &Version) -> Result<()> {
    let fs = Fs::new()?;
    let versions_dir = fs.join("custom_versions");

    if !versions_dir.exists() {
        return Ok(());
    }

    let mut version_files = Vec::new;

    for entry in fs.read_dir(versions_dir)? {
        let path = entry.path();
        if path.is_dir() && path.file_name().and_then(|n| n.to_str()).map_or(false, |s| s.starts_with("v")) {
            if let Ok(version_str) = path.file_name().and_then(|n| n.to_str()).ok_or(anyhow::anyhow!("Invalid filename")) {
                if let Ok(version) = Version::parse(version_str) {
                    version_files.push((version, path));
                }
            }
        }
    }

    for (version, path) in version_files {
        if version < threshold {
            fs.remove_dir_all(&path)?;
        }
    }

    Ok(())
}

fn cargo_install_command(source: &Source, kind: CliKind) -> String {
    let mut command = String::new();
    match source {
        Source::CratesIO(crate_name) => {
            command.push_str("cargo install ");
            command.push_str(crate_name);
            if let Some(target) = kind.target() {
                command.push_str(" --target ");
                command.push_str(target);
            }
        }
        Source::Git(GitSourceRevision { url, branch, rev }) => {
            command.push_str("cargo install --git ");
            command.push_str(url);
            if let Some(branch) = branch {
                command.push_str(" --branch ");
                command.push_str(branch);
            }
            if let Some(rev) = rev {
                command.push_str(" --rev ");
                command.push_str(rev);
            }
            if let Some(target) = kind.target() {
                command.push_str(" --target ");
                command.push_str(target);
            }
        }
    }
    command
}

