    if !header_overrides.is_empty() {
        let headers: Vec<String> = header_overrides
            .into_iter()
            .map(|(k, v)| format!("-H '{}:{}'", k, v))
            .collect();
        base_curl.push_str(&format!(" {}", headers.join(" ")));
    }

    Ok(base_curl)
}

fn data_from_value(&self, value: serde_json::Value) -> Result<CustomData, C3p0Error> {
    let mut data = CustomData {
