            data.metadata = metadata.clone();
        }
    }

    Ok(data)
}

fn parse_signed_num<'a>(pm: &mut ParseMaster<StringPoint<'a>, Error>, pt: StringPoint<'a>) -> Progress<StringPoint<'a>, i32, Error> {
    let mut progress = Progress::new(pt);
    let c = pm.peek_char(progress);
    if c == Some('+') || c == Some('-') {
        progress = pm.consume(progress);
    }
    let num = parse_number(pm, progress);
    match num {
        Ok(n) => {
            if let Some(c) = pm.peek_char(progress) {
                if c != Some('\0') {
                    pm.error(Error::ExpectedNumber, progress);
                    return Progress::error(Error::ExpectedNumber, progress);
                }
            }
            Ok(n)
        }
        Err(e) => {
            if let Some(c) = pm.peek_char(progress) {
                if c != Some('\0') {
                    pm.error(Error::ExpectedNumber, progress);
                }
            }
            Err(e)
        }
    }
}

fn parse_number<'a>(pm: &mut ParseMaster<StringPoint<'a>, Error>, pt: StringPoint<'a>) -> Result<i32, Error> {
    let mut progress = pt;
    let mut value = 0;
    let mut is_negative = false;
    let mut has_digits = false;
    while let Some(c) = pm.peek_char(progress) {
        if c.is_ascii_digit() {
            has_digits = true;
            let digit = c.to_digit(10).ok_or(Error::InvalidNumber(0))?;
            value = value * 10 + digit as i32;
            progress = pm.consume(progress);
        } else {
            break;
        }
    }
    if !has_digits {
        return Err(Error::InvalidNumber(0));
    }
    Ok(if is_negative { -value } else { value })
}

use kuchiki::parse_html;
use kuchiki::nodes::Node;

fn replace_class(html: &str, old_class: &str, new_class: &str) -> String {
    let document = parse_html(html).unwrap();
    replace_classes(&document, old_class, new_class);
    document.to_string()
}

fn replace_classes(node: &Node, old_class: &str, new_class: &str) {
    if let Some(element) = node.as_element() {
        let mut classes = element.class().split_whitespace().collect::<Vec<_>>();
        classes = classes
            .into_iter()
            .map(|cls| if cls == old_class { new_class } else { cls })
            .collect();
        element.set_class(&classes.join(" "));
    }

    for child in node.children() {
        replace_classes(child, old_class, new_class);
    }
}

fn race_requests<A, B, E>(req_a: gj::Promise<A, E>, req_b: gj::Promise<B, E>) -> gj::Promise<Either<A, B>, E>
where
    E: 'static,
    A: 'static,
    B: 'static,
{
    let (tx, rx) = EventPort::new();
    let (tx2, rx2) = EventPort::new();

    let promise = gj::Promise::new(move |resolve, reject| {
        let tx = tx.clone();
        let tx2 = tx2.clone();
        let resolve_clone = resolve.clone();
        let reject_clone = reject.clone();

        let handle_a = thread::spawn(move || {
            if let Ok(a) = req_a.wait() {
                tx.send(()).unwrap();
                resolve_clone(Either::Left(a));
            } else {
                reject_clone(E::default());
            }
        });

        let handle_b = thread::spawn(move || {
            if let Ok(b) = req_b.wait() {
                tx2.send(()).unwrap();
                resolve_clone(Either::Right(b));
            } else {
                reject_clone(E::default());
            }
        });

        let result = match rx.recv_timeout(Duration::from_secs(10)) {
            Ok(_) => {
                handle_b.abort();
                handle_a.join().unwrap();
                Either::Left(A::default())
            }
            Err(_) => {
                handle_a.abort();
                handle_b.join().unwrap();
                Either::Right(B::default())
            }
        };

        resolve_clone(result);
    });

    promise
}

fn start_connection_health_monitor<P, M, C>(
    client: std::sync::Arc<crate::tpu_client::TpuClient<P, M, C>>,
    interval: std::time::Duration,
) where
    P: solana_connection_cache::connection_cache::ConnectionPool<NewConnectionConfig = C>,
    M: solana_connection_cache::connection_cache::ConnectionManager<ConnectionPool = P, NewConnectionConfig = C>,
    C: solana_connection_cache::connection_cache::NewConnectionConfig,
{
    let client = client.clone();
    let interval = interval;

    tokio::spawn(async move {
        let mut interval = interval::interval(interval);
        loop {
            interval.tick().await;

            let connection = match client.get_connection().await {
                Ok(conn) => conn,
                Err(e) => {
                    error!("Failed to get connection for health check: {}", e);
                    continue;
                }
            };

            if let Err(e) = connection.ping().await {
                error!("TPU connection health check failed: {}", e);
                // Handle failure, e.g., trigger reconnection or alert
            }
        }
    });
}

