fn parse_invoice(invoice_str: &str) -> Result<PrunedInvoice, anyhow::Error> {
    let invoice = Bolt11Invoice::from_str(invoice_str)
        .with_context(|| format!("Failed to parse Bolt11 invoice: {}", invoice_str))?;

    let features = encode_bolt11_invoice_features_without_length(&invoice.features);
    let payment_hash = invoice.payment_hash();
    let payment_secret = invoice.payment_secret();
    let rbf = invoice.rbf();
    let fallbacks = invoice.fallbacks().to_vec();
    let routes = invoice.routes().to_vec();
    let num_parts = invoice.num_parts();
    let amount_msat = invoice.amount_msat();
    let timestamp = invoice.timestamp();
    let expiry_time = invoice.expiry_time();
    let description_hash = invoice.description_hash();
    let min_final_cltv_expiry = invoice.min_final_cltv_expiry();
    let max_sendable = invoice.max_sendable();
    let min_sendable = invoice.min_sendable();
    let payment_url = invoice.payment_url();
    let supports_forwarding = invoice.supports_forwarding();
    let is_keysend = invoice.is_keysend();
    let is_rbf = invoice.is_rbf();
    let is_final = invoice.is_final();
    let is_expired = invoice.is_expired();

    Ok(PrunedInvoice {
        features,
        payment_hash,
        payment_secret,
        rbf,
        fallbacks,
        routes,
        num_parts,
        amount_msat: Amount::from_msat(amount_msat),
        timestamp,
        expiry_time,
        description_hash,
        min_final_cltv_expiry,
        max_sendable: Amount::from_msat(max_sendable),
        min_sendable: Amount::from_msat(min_sendable),
        payment_url,
        supports_forwarding,
        is_keysend,
        is_rbf,
        is_final,
        is_expired,
    })
}

