fn parse_memory_map_entries(data: &[u8]) -> Result<Vec<IGVM_VHS_MEMORY_MAP_ENTRY>, &'static str> {
    let mut entries = Vec::new();
    let mut offset = 0;

    while offset + std::mem::size_of::<IGVM_VHS_MEMORY_MAP_ENTRY>() <= data.len() {
        let entry = unsafe { std::ptr::read_unaligned(data.as_ptr().add(offset) as *const IGVM_VHS_MEMORY_MAP_ENTRY) };
        entries.push(entry);
        offset += std::mem::size_of::<IGVM_VHS_MEMORY_MAP_ENTRY>();
    }

    Ok(entries)
}

