use emcee::Guess;

fn constrained_initial_guesses(values: &[f64], nwalkers: usize, bounds: &[(Option<(f64, f64)>)]) -> Vec<Guess> {
    let mut guesses = Vec::with_capacity(nwalkers);
    let mut perturbations = Vec::with_capacity(values.len());

    // Generate small random perturbations for each parameter
    for _ in 0..values.len() {
        perturbations.push(1e-4 * (2.0 * rand::random::<f64>() - 1.0));
    }

    for _ in 0..nwalkers {
        let mut guess = Vec::new();
        for (i, &val) in values.iter().enumerate() {
            let mut value = val + perturbations[i];
            if let Some((low, high)) = bounds[i] {
                if value < low {
                    value = low;
                } else if value > high {
                    value = high;
                }
            }
            guess.push(value);
        }
        guesses.push(Guess::new(guess));
    }

    guesses
}

