fn create_svg_container(id: u16) {
    let ns = "http://www.w3.org/2000/svg";
    let doc = bindgen::document();
    let container = doc.create_element_ns(ns, "svg").unwrap();
    container.set_attribute("id", &id.to_string()).unwrap();
    container.set_attribute("width", "100%").unwrap();
    container.set_attribute("height", "100%").unwrap();
    container.set_attribute("version", "1.1").unwrap();
    container.set_attribute("xmlns", ns).unwrap();

    let group = doc.create_element_ns(ns, "g").unwrap();
    group.set_attribute("transform", "translate(50, 50)").unwrap();

    container.append_child(group).unwrap();
    doc.body().unwrap().append_child(container).unwrap();
}

