use crate::block::{compress_to_buffer, compress_bound, CompressionMode};
use std::io::Result;

fn compress_with_progress(src: &[u8], mode: Option<CompressionMode>, prepend_size: bool, progress_callback: &dyn Fn(f64)) -> Result<Vec<u8>> {
    let mut output = Vec::new();
    let mut offset = 0;
    let total = src.len() as f64;

    // Calculate the maximum compressed size
    let max_compressed_size = compress_bound(src.len());
    output.resize(max_compressed_size, 0);

    // Compress in chunks
    let chunk_size = 1024 * 1024; // 1MB chunks
    while offset < src.len() {
        let chunk = &src[offset..offset + chunk_size];
        let chunk_len = chunk.len();

        // Compress the chunk
        let mut compressed_chunk = vec![];
        let compressed_len = compress_to_buffer(chunk, &mut compressed_chunk, mode);
        if compressed_len == 0 {
            return Err(std::io::Error::new(std::io::ErrorKind::Other, "Compression failed"));
        }

        // Update the output with the compressed chunk
        output.splice(0..output.len(), compressed_chunk);

        // Update progress
        let progress = (offset as f64 + chunk_len as f64) / total;
        progress_callback(progress);

        offset += chunk_len;
    }

    // Prepend size if needed
    if prepend_size {
        let size = output.len() as u64;
        let mut size_buffer = vec![0; std::mem::size_of::<u64>()];
        size.to_le_bytes().copy_into_slice(&mut size_buffer);
        output.splice(0..0, size_buffer);
    }

    Ok(output)
}

fn pay_with_retry(
    gateway: &dyn IGatewayClientV2,
    invoice: Bolt11Invoice,
    max_delay: u64,
    max_fee: Amount,
    max_attempts: usize,
) -> Result<[u8; 32], LightningRpcError> {
    let mut attempt = 0;
    let mut delay = Duration::from_secs(1);

    loop {
        attempt += 1;
        if attempt > max_attempts {
            return Err(LightningRpcError::new("Max attempts exceeded"));
        }

        match gateway.pay_invoice(invoice.clone(), max_fee) {
            Ok(payment_preimage) => {
                return Ok(payment_preimage);
            }
            Err(LightningRpcError::LightningError { .. }) => {
                log::warn!("Transient Lightning error, retrying...");
                sleep(delay).await?;
                delay = std::cmp::min(delay * 2, Duration::from_secs(max_delay));
            }
            Err(e) => {
                return Err(e);
            }
        }
    }
}

fn extract_memory_slice(image: &mut MemoryImage, start: ByteAddr, length: usize) -> Result<Vec<u8>> {
    let mut result = Vec::with_capacity(length);
    let mut current_addr = start;

    while length > 0 {
        let page = image.get_page_mut(current_addr)?;
        let page_start = page.start();
        let page_end = page.end();

        let bytes_to_copy = std::cmp::min(length, (page_end - current_addr) as usize);
        let slice = &page.bytes()[current_addr as usize - page_start as usize..current_addr as usize - page_start as usize + bytes_to_copy];

        result.extend_from_slice(slice);

        current_addr += bytes_to_copy as ByteAddr;
        length -= bytes_to_copy;
    }

    Ok(result)
}

fn check_interlinks_proof(&self) -> bool {
    if self.interlinks.is_empty() {
        return true;
    }

    let interlinks = &self.interlinks;
    let proof = &self.interlinks_proof;

    let mut current_hash = *interlinks.last().unwrap();

    for i in (0..interlinks.len() - 1).rev() {
        let left = interlinks[i];
        let right = current_hash;

        let left_hash = left.compute_hash();
        let right_hash = right.compute_hash();

        let combined_hash = MerkleNode::combine(&left_hash, &right_hash);
        current_hash = combined_hash;
    }

    let root_hash = current_hash;
    proof.verify(root_hash, interlinks.len())
}

use std::path::Path;
use std::fs;
use std::io::prelude::*;
use reqwest::blocking::Client;
use reqwest::header::{HeaderMap, HeaderValue};
use crate::error::Error;
use crate::helpers::get_github_token;
use crate::version::get_protoc_asset_name;
use crate::install::download;

fn download_protoc_binary(version: &str, output_path: &Path) -> Result<(), Error<'static>> {
    let asset_name = get_protoc_asset_name(version);
    let url = format!("https://github.com/protocolbuffers/protobuf/releases/download/v{version}/{asset_name}.zip");

    let client = Client::new();
    let token = get_github_token();
    let mut headers = HeaderMap::new();
    if let Ok(token) = token {
        headers.insert("Authorization", HeaderValue::from_str(&format!("token {}", token)).unwrap());
    }

    let response = client.get(&url)
        .headers(headers)
        .send()
        .map_err(|e| Error::new("Failed to send request"))?;

    if !response.status().is_success() {
        return Err(Error::new("Failed to download protoc binary"));
    }

    let mut file = fs::File::create(output_path)
        .map_err(|e| Error::new("Failed to create output file"))?;

    let content = response.bytes()
        .map_err(|e| Error::new("Failed to read response content"))?;

    file.write_all(&content)
        .map_err(|e| Error::new("Failed to write file"))?;

    Ok(())
}

fn try_lock_with_timeout(file: &File, timeout: Duration, offset: usize, len: usize) -> io::Result<FileGuard<&File>> {
    let start = Instant::now();
    loop {
        let result = try_lock(file, offset, len);
        match result {
            Ok(guard) => return Ok(guard),
            Err(e) if start.elapsed() >= timeout => return Err(e),
            Err(e) => {
                // Retry after a short delay
                thread::sleep(Duration::from_millis(100));
            }
        }
    }
}

use bosonnlp::BosonNLP;
use bosonnlp::errors::Result;
use std::time::{Duration, SystemTime};

fn summarize_with_retry<T: AsRef<str>>(nlp: &BosonNLP, title: T, content: T, word_limit: f32, max_retries: usize) -> Result<String> {
    let mut retries = 0;
    let mut delay = Duration::from_millis(100); // Initial delay in milliseconds

    loop {
        retries += 1;
        if retries > max_retries {
            return Err("Max retries exceeded".into());
        }

        // Simulate a delay before the next attempt
        std::thread::sleep(delay);

        // Perform the summarize operation
        match nlp.summarize(title.as_ref(), content.as_ref(), word_limit) {
            Ok(summary) => return Ok(summary),
            Err(e) => {
                // Log or handle the error if needed
                eprintln!("Summary failed, retrying... ({}/{})", retries, max_retries);
                // Increase the delay for the next attempt
                delay = Duration::from_millis(delay.as_millis() * 2);
            }
        }
    }
}

