fn build_format_string<'a>(nodes: &'a [Node]) -> (String, Vec<&'a Expr>) {
    let mut format_string = String::new();
    let mut exprs = Vec::new();
    let mut first = true;

    for node in nodes {
        match node {
            Node::Text(text) => {
                if !first {
                    format_string.push_str("}");
                }
                format_string.push_str(text);
                first = false;
            }
            Node::Expr(expr) => {
                if !first {
                    format_string.push('}');
                }
                format_string.push_str("}");
                exprs.push(expr);
                first = false;
            }
            Node::Tag(tag) => {
                if !first {
                    format_string.push('}');
                }
                format_string.push_str("}");
                first = false;
            }
        }
    }

    (format_string, exprs)
}

fn subject_json_pointers(vc: &JsonCredential) -> Vec<JsonPointer> {
    let mut pointers = Vec::new();
    if let Some(subject) = &vc.credential_subject {
        if let Some(value) = subject.get("type") {
            if let Some(type_value) = value.as_str() {
                if type_value == "VerifiableCredential" {
                    if let Some(subject) = &vc.credential_subject {
                        for (field, value) in subject.as_object().unwrap() {
                            if field != "type" {
                                let pointer = json_pointer::to_pointer(field);
                                pointers.push(pointer);
                            }
                        }
                    }
                }
            }
        }
    }
    pointers
}

macro_rules! error_msg {
    ($($primary:expr),+ $(,)?) => {
        error_msg!($($primary),+ , "")
    };
    ($($primary:expr),+ , $fallback:expr $(,)?) => {
        error_msg!($($primary),+ , $fallback, "")
    };
    ($($primary:expr),+ , $fallback:expr, $context:expr $(,)?) => {
        let primary = format!("{}", stringify!($($primary),+));
        let fallback = format!("{}", $fallback);
        let context = format!("{}", $context);
        let message = if let Some(msg) = std::env::var("ERROR_MESSAGES").as_deref() {
            match msg.split(',').find(|s| s.starts_with(primary.as_str())) {
                Some(msg) => msg.trim().to_string(),
                None => fallback,
            }
        } else {
            fallback
        };
        format!("{}: {}", message, context)
    };
}

fn error_msg_with_context<F, C>(primary: F, fallback: C, context: &str) -> String
where
    F: std::fmt::Display,
    C: std::fmt::Display,
{
    let primary = format!("{}", primary);
    let fallback = format!("{}", fallback);
    let context = context.to_string();
    let message = if let Some(msg) = std::env::var("ERROR_MESSAGES").as_deref() {
        match msg.split(',').find(|s| s.starts_with(primary.as_str())) {
            Some(msg) => msg.trim().to_string(),
            None => fallback,
        }
    } else {
        fallback
    };
    format!("{}: {}", message, context)
}

