use deno_core::OpState;
use deno_core::url::Url;

fn normalize_and_sanitize_url_path(
    state: &mut OpState,
    url_str: &str,
) -> Result<String, String> {
    let url = Url::parse(url_str).map_err(|e| e.to_string())?;
    let path = url.path();

    let normalized_path = normalize_path(path);

    if normalized_path.starts_with("..") {
        return Err("Invalid path: parent directory reference not allowed".to_string());
    }

    Ok(normalized_path)
}

fn normalize_path(path: &str) -> String {
    let mut components = path.split('/').filter(|s| !s.is_empty());
    let mut result = Vec::new();

    for component in components {
        if component == "." {
            continue;
        } else if component == ".." {
            if !result.is_empty() && result.last() != Some("..") {
                result.pop();
            }
        } else {
            result.push(component);
        }
    }

    format!("/{}", result.join("/"))
}

use crate::interface::ReadRange;
use crate::codec;

fn is_key_in_range(key: &[u8], range: &ReadRange) -> bool {
    if range.start.is_none() && range.end.is_none() {
        return true;
    }

    let start = range.start.as_ref().map(|s| codec::decode_key(s));
    let end = range.end.as_ref().map(|e| codec::decode_key(e));

    let start_key = match start {
        Some(s) => s,
        None => {
            // If no start is provided, the range starts from the beginning
            return true;
        }
    };

    let end_key = match end {
        Some(e) => e,
        None => {
            // If no end is provided, the range goes to the end
            return true;
        }
    };

    // Compare keys using the codec's comparison
    let key = codec::decode_key(key);
    if key < start_key {
        false
    } else if key > end_key {
        false
    } else {
        true
    }
}

