fn register_with_validation<F, H>(server: &mut Server, name: &str, validator: F, handler: H)
where
    F: Fn(&Vec<Value>) -> bool + Send + Sync + 'static,
    H: Fn(Vec<Value>) -> Result<Value> + Send + Sync + 'static,
{
    server.register_method(name, move |params: Vec<Value>| {
        if validator(&params) {
            handler(params)
        } else {
            Err(Fault::new(400, "Validation failed"))
        }
    });
}

use fedimint_server_core::bitcoin_rpc::ServerBitcoinRpcMonitor;
use fedimint_core::Feerate;
use fedimint_core::bitcoin::Network;
use anyhow::anyhow;

fn calculate_optimal_fee_rate(
    rpc_monitor: &ServerBitcoinRpcMonitor,
    _target_confirmations: u64,
) -> anyhow::Result<Feerate> {
    let status = rpc_monitor.status()?;
    let network = status.network;

    // Determine base fee rate based on network
    let base_fee_rate = match network {
        Network::Bitcoin => Feerate::from_sat_per_byte(10),
        Network::Testnet => Feerate::from_sat_per_byte(5),
        Network::Regtest => Feerate::from_sat_per_byte(1),
    };

    // Adjust fee rate based on current network congestion
    let congestion_factor = match status.congestion {
        0 => 1.0,
        1 => 1.5,
        2 => 2.0,
        _ => 2.5,
    };

    let optimal_fee_rate = base_fee_rate * congestion_factor;

    Ok(optimal_fee_rate)
}

