fn siblings_with_class(&self, class: &str) -> Vec<Node<'a>> {
    let parent = self.parent();
    let mut result = Vec::new();
    if let Some(parent) = parent {
        for sibling in parent.children() {
            if sibling != self && sibling.has_class(class) {
                result.push(sibling);
            }
        }
    }
    result
}

