use crate::text::{diff_lines, ContextConfig};

fn aligned_diff(old: &str, new: &str, context: Option<usize>) -> String {
    let context_config = ContextConfig::new(context);
    let changeset = diff_lines(old, new, &context_config);
    let mut result = String::new();
    let mut line_number = 1;

    for change in &changeset {
        match change {
            LineChange::OldOnly(line) => {
                result.push_str(&format!("{}\t{}\n", line_number, line));
                line_number += 1;
            }
            LineChange::NewOnly(line) => {
                result.push_str(&format!("{}\t{}\n", line_number, line));
                line_number += 1;
            }
            LineChange::Both(old_line, new_line) => {
                result.push_str(&format!("{}\t{}\t{}\n", line_number, old_line, new_line));
                line_number += 1;
            }
        }
    }

    result
}

