fn generate_key_pairs(
    &self,
    start: usize,
    count: usize,
    passphrase: Option<&str>,
) -> Result<Vec<(String, String)>, Error> {
    let mut key_pairs = Vec::new();
    for i in start..start + count {
        let seed = self.derive_seed(i, passphrase);
        let private_key = PrivateKey::from_seed(&seed);
        let public_key = PublicKey::from_private_key(&private_key);
        key_pairs.push((public_key.to_string(), private_key.to_string()));
    }
    Ok(key_pairs)
}

use anyhow::{Context, Result};
use tree_sitter::{Query, QueryMatch};
use crate::patterns;
use tree_sitter_json;

fn update_context_predicates(text: &str) -> Result<Option<String>> {
    let json = tree_sitter_json::language().build()?;
    let query = Query::new(
        &json,
        r#"
        (string
            (string_content
                (predicate
                    (identifier) @old_predicate
                )
            )
        )
        "#,
    )
    .context("Failed to create query")?;

    let mut result = String::new();
    let mut in_string = false;
    let mut current_string = String::new();
    let mut matches = Vec::new();

    for token in json.tokenize(text).into_iter() {
        let token = token?;
        let (ty, value) = token;

        match ty {
            "string" => {
                in_string = true;
                current_string = value.to_string();
            }
            "string_content" => {
                current_string = value.to_string();
            }
            "identifier" => {
                if in_string {
                    current_string.push_str(value);
                }
            }
            _ => {
                if in_string {
                    let mut buffer = String::new();
                    buffer.push_str(&current_string);
                    buffer.push_str(value);
                    current_string = buffer;
                }
            }
        }

        if ty == "string_close" {
            in_string = false;
            let mut buffer = String::new();
            buffer.push_str(&current_string);
            buffer.push_str(value);
            current_string = buffer;

            let matches = query.matches(&buffer).context("Failed to match query")?;
            for match_ in matches {
                for capture in match_.captures.iter() {
                    if let Some((_, capture)) = capture {
                        if let Some(id) = capture.name() {
                            if id == "old_predicate" {
                                let predicate = capture.text();
                                let new_predicate = predicate.replace("inline_completion", "edit_prediction");
                                let updated = buffer.replace(predicate, &new_predicate);
                                matches = query.matches(&updated).context("Failed to match updated query")?;
                                break;
                            }
                        }
                    }
                }
            }

            result.push_str(&buffer);
        }
    }

    if result.is_empty() {
        Ok(None)
    } else {
        Ok(Some(result))
    }
}

use std::{fs::File, path::Path};
use gluesql_core::{error::Result, store::Store};
use serde_json::{Value, Map};

impl JsonStorage {
    pub async fn export_table<P: AsRef<std::path::Path>>(&self, table_name: &str, out_path: P) -> Result<()> {
        let rows_iter = self.scan_data(table_name).await?;
        let schema = self.fetch_schema(table_name).await?.ok_or_else(|| {
            gluesql_core::error::Error::StorageMsg(format!("Table {} does not exist", table_name))
        })?;
        let jsons: Vec<Value> = rows_iter
            .map(|res| {
                let (_key, row) = res?;
                match row {
                    gluesql_core::data::DataRow::Vec(values) => {
                        let labels = schema
                            .column_defs
                            .as_ref()
                            .map(|defs| defs.iter().map(|c| c.name.clone()).collect::<Vec<_>>())
                            .unwrap_or_default();
                        let obj = Map::from_iter(
                            labels
                                .into_iter()
                                .zip(values.into_iter())
                                .map(|(k, v)| Ok((k, v.try_into()?)))
                        );
                        Ok(Value::Object(obj))
                    }
                    gluesql_core::data::DataRow::Map(map) => {
                        let obj = Map::from_iter(
                            map.into_iter()
                                .map(|(k, v)| Ok((k, v.try_into()?)))
                        );
                        Ok(Value::Object(obj))
                    }
                }
            })
            .collect::<Result<Vec<_>>>()?;
        let out_file = File::create(out_path).map_err(|e| {
            gluesql_core::error::Error::StorageMsg(e.to_string())
        })?;
        serde_json::to_writer_pretty(out_file, &jsons).map_err(|e| {
            gluesql_core::error::Error::StorageMsg(e.to_string())
        })?;
        Ok(())
    }
}

use std::path::Path;
use anyhow::Result;
use crate::lockfile::Lockfile;
use crate::config::Config;
use crate::repository::Repository;

fn generate_workspace_summary(workspace: &Path) -> Result<String> {
    let config = Config::load(workspace)?;
    let lockfile = Lockfile::load(workspace)?;
    let repositories = lockfile.repositories();

    let total_repositories = repositories.len() as u32;
    let provider_counts = repositories
        .iter()
        .fold(std::collections::HashMap::new(), |mut map, repo| {
            *map.entry(repo.provider.clone()).or_insert(0) += 1;
            map
        });
    let missing_locally = repositories
        .iter()
        .filter(|repo| !config.contains_repository(&repo.name))
        .count() as u32;

    let mut summary = String::new();
    summary.push_str(&format!("Total repositories: {}\n", total_repositories));
    summary.push_str("Repositories by provider:\n");
    for (provider, count) in provider_counts {
        summary.push_str(&format!("  {}: {}\n", provider, count));
    }
    summary.push_str(&format!("Repositories missing locally: {}\n", missing_locally));

    Ok(summary)
}

use crate::{retrieve::{RetrievedDigest, RetrievalMetadata}, store::{store_document, Document, StoreError}};
use sha2::{Sha256, Sha512};
use digest::Digest;

fn store_document_with_checksums(
    file: &std::path::Path,
    document_data: &[u8],
    signature: Option<String>,
    metadata: &RetrievalMetadata,
) -> Result<(), StoreError> {
    let sha256 = Sha256::digest(document_data);
    let sha512 = Sha512::digest(document_data);

    let digest_sha256 = format!("{:x}", sha256);
    let digest_sha512 = format!("{:x}", sha512);

    let retrieved_digest = RetrievedDigest {
        digest_sha256,
        digest_sha512,
        signature: signature.clone(),
    };

    let document = Document {
        file_path: file.to_path_buf(),
        data: document_data.to_vec(),
        retrieval_metadata: metadata.clone(),
        retrieved_digest,
    };

    store_document(&document)
}

fn request_with_retry<R, Params>(&self, method: &str, params: Params, max_retries: usize) -> Result<R, Error>
where
    R: DeserializeOwned,
    Params: ToRpcParams + Send,
{
    let mut retries = 0;
    let mut delay = Duration::from_millis(100);

    loop {
        match self.request(method, params).map_err(|e| {
            if e.is_transport() {
                Error::from(e)
            } else {
                e
            }
        }) {
            Ok(result) => return Ok(result),
            Err(err) => {
                if retries >= max_retries {
                    return Err(err);
                }
                retries += 1;
                sleep(delay).await.unwrap();
                delay *= 2;
            }
        }
    }
}

fn load_custom_macros(cfg: &KatexConfig, root: &Path) -> HashMap<String, String> {
    let macro_path = get_macro_path(cfg, root);
    if let Ok(contents) = load_as_string(&macro_path) {
        let mut macros = HashMap::new();
        for line in contents.lines() {
            if let Some((name, value)) = line.split_once("\\newcommand{") {
                if let Some(value) = value.strip_prefix('{').and_then(|s| s.strip_suffix('}')) {
                    macros.insert(name.to_string(), value.to_string());
                }
            }
        }
        macros
    } else {
        HashMap::new()
    }
}

