fn get_repository_tags(store: &Store, repo_cx: &RepositoryContext) -> Result<Vec<(TagName, Meta)>, GetError<anyhow::Error>> {
    let tag_names = store.get_tag_names(repo_cx).context("Failed to get tag names")?;
