fn duplicate_on_drop<T>(items: &mut Vec<T>, response: &egui_dnd::DragDropResponse)
where
    T: Clone + egui_dnd::DragDropItem,
{
    if let Some(dragged_item) = response.dragged_item() {
        if response.drop_position().is_some() {
            if let Some(index) = response.drop_position().unwrap().index() {
                // Insert the original item at the drop position
                items.insert(index, dragged_item.clone());
                // Insert the duplicate right after the drop position
                items.insert(index + 1, dragged_item.clone());
            }
        }
    }
}

fn monitor_transactions_with_timeout(
    client: &solana_client::rpc_client::RpcClient,
    signatures: &[solana_sdk::signature::Signature],
    timeout: std::time::Duration,
) -> solana_client::client_error::Result<Vec<Option<solana_sdk::transaction::TransactionError>>> {
    let start = Instant::now();
    let mut results = Vec::with_capacity(signatures.len());

    while start.elapsed() < timeout {
        let mut all_finalized = true;
        let mut errors = Vec::with_capacity(signatures.len());

        for &sig in signatures {
            match client.get_transaction(&sig) {
                Ok(Some(tx)) => {
                    if tx.meta.status.is_finalized() {
                        results.push(None);
                    } else {
                        results.push(Some(TransactionError::TransactionExpired));
                        all_finalized = false;
                    }
                }
                Ok(None) => {
                    results.push(Some(TransactionError::TransactionNotFound));
                    all_finalized = false;
                }
                Err(e) => {
                    results.push(Some(e));
                    all_finalized = false;
                }
            }
        }

        if all_finalized {
            return Ok(results);
        }

        sleep(Duration::from_millis(1000));
    }

    Err(solana_client::client_error::ClientError::Timeout)
}

fn extract_validated_json<T>(req: &HttpRequest, payload: &mut Payload) -> Result<T, Error>
where
    T: DeserializeOwned + Validate + 'static,
{
    let content_type = req.headers().get("Content-Type").cloned().unwrap_or(mime::APPLICATION_OCTET_STREAM);
    if content_type != mime::APPLICATION_JSON {
        return Err(error::ErrorContentType("application/json".to_string()).into());
    }

    let mut buffer = Vec::new();
    let mut size = 0;

    while let Ok(chunk) = payload.next() {
        let chunk = chunk?;
        buffer.extend_from_slice(&chunk);
        size += chunk.len();

        if size > 1024 * 1024 { // 1 MB limit
            return Err(error::ErrorTooLarge.into());
        }
    }

    let json_str = std::str::from_utf8(&buffer).map_err(|_| error::ErrorInvalidData)?;
    let data: T = serde_json::from_str(json_str).map_err(|_| error::ErrorInvalidData)?;
    data.validate().map_err(|e| error::ErrorInvalidData.format(e))
}

use crate::{types::*, IndexerConnection};
use crate::queries::{type_id_list_by_name, list_column_by_id};
use sqlx::Result;

fn find_column_in_table(
    conn: &mut IndexerConnection,
    namespace: &str,
    identifier: &str,
    table_name: &str,
    column_name: &str,
) -> sqlx::Result<Option<Column>> {
    // Get the type ID for the given namespace and identifier
    let type_id_result = type_id_list_by_name(conn, namespace, identifier);
    if let Err(e) = type_id_result {
        return Err(e);
    }
    let type_id = type_id_result.unwrap();

    // Get the column ID for the given table name and column name
    let column_id_result = list_column_by_id(conn, type_id, table_name, column_name);
    if let Err(e) = column_id_result {
        return Err(e);
    }
    let column_id = column_id_result.unwrap();

    // Fetch the full Column struct using the column ID
    let column_result = get_column_by_id(conn, column_id);
    column_result
}

// Helper function to get a Column by its ID
fn get_column_by_id(conn: &mut IndexerConnection, column_id: i32) -> sqlx::Result<Option<Column>> {
    let column = sqlx::query_as!(
        Column,
        "SELECT * FROM columns WHERE id = $1",
        column_id
    )
    .fetch_optional(conn)
    .map_err(|e| e.into())
;

    column
}

fn insert_organizations_and_users(
    organizations: Vec<Organization>,
    users: Vec<User>,
    db: &mut impl ormlite::Connection,
) -> Result<Vec<User>, ormlite::Error> {
    // Insert all organizations first
    let inserted_organizations: Vec<Organization> = organizations
        .into_iter()
        .map(|org| {
            let mut org = org;
            org.id = 0; // Reset ID to let the database assign it
            Insert::new(db).insert(&mut org)
        })
        .collect::<Result<Vec<_>, _>>()?;

    // Map inserted organizations to their IDs
    let org_id_map: std::collections::HashMap<String, i32> = inserted_organizations
        .iter()
        .map(|org| (org.name.clone(), org.id))
        .collect();

    // Update users with correct org_id based on the map
    let mut updated_users: Vec<User> = users
        .into_iter()
        .map(|mut user| {
            if let Some(org_id) = org_id_map.get(&user.organization.name) {
                user.organization.id = *org_id;
            }
            user
        })
        .collect();

    // Insert users
    Insert::new(db).insert_all(&mut updated_users)
}

fn validate_audience_and_expiration(claims: &jwt::Claims, expected_audience: &str) -> Result<(), String> {
    if claims.aud != expected_audience {
        return Err("Invalid audience".to_string());
    }

    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|_| "Time went backwards".to_string())?
        .as_secs();

    if claims.exp <= now {
        return Err("Token has expired".to_string());
    }

    Ok(())
}

fn summarize_token_balance_changes(
    token_mint: &Pubkey,
    transactions: &[TransactionWithStatusMeta],
) -> TokenBalanceSummary {
    let mut balance_changes: HashMap<Pubkey, i64> = HashMap::new();
    let mut transaction_details: Vec<TransactionDetail> = Vec::new();
    let mut total_net_change = 0;

    for transaction in transactions {
        if let Some(meta) = &transaction.meta {
            if let Some(inner) = &meta.inner {
                if let Some(instructions) = &inner.instructions {
                    for instruction in instructions {
                        if let Some(accounts) = &instruction.accounts {
                            let mut is_token_mint = false;
                            let mut token_account = None;
                            let mut from_account = None;
                            let mut to_account = None;

                            for (index, &account_pubkey) in accounts.iter() {
                                if account_pubkey == *token_mint {
                                    is_token_mint = true;
                                } else if let Some(balance) = balance_changes.get(&account_pubkey) {
                                    if *balance > 0 {
                                        if from_account.is_none() {
                                            from_account = Some(account_pubkey);
                                        } else {
                                            to_account = Some(account_pubkey);
                                        }
                                    }
                                }
                            }

                            if is_token_mint && from_account.is_some() && to_account.is_some() {
                                let from = from_account.unwrap();
                                let to = to_account.unwrap();
                                let amount = balance_changes.get(&from).unwrap() - balance_changes.get(&to).unwrap();
                                total_net_change += amount;

                                transaction_details.push(TransactionDetail {
                                    transaction_signature: transaction.transaction.signatures[0].to_string(),
                                    from: from.to_string(),
                                    to: to.to_string(),
                                    amount,
                                });

                                if let Some(balance) = balance_changes.get_mut(&from) {
                                    *balance -= amount;
                                }
                                if let Some(balance) = balance_changes.get_mut(&to) {
                                    *balance += amount;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    TokenBalanceSummary {
        total_net_change,
        transaction_details,
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct TokenBalanceSummary {
    total_net_change: i64,
    transaction_details: Vec<TransactionDetail>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct TransactionDetail {
    transaction_signature: String,
    from: String,
    to: String,
    amount: i64,
}

fn record_operation_duration_with_context(
    &self,
    operation: GraphqlOperationAttributes,
    client: Option<Client>,
    status: GraphqlResponseStatus,
    latency: std::time::Duration,
) {
    if operation.ty.is_subscription() {
        return;
    }
    let mut attributes = self.create_operation_key_values(operation);

    if let Some(version) = self.graph_version.clone() {
        attributes.push(KeyValue::new("grafbase.graph.version", version));
    }

    attributes.push(KeyValue::new("graphql.response.status", status.as_str()));

    if let Some(client) = client {
        attributes.push(KeyValue::new("http.headers.x-grafbase-client-name", client.name));

        if let Some(version) = client.version {
            attributes.push(KeyValue::new("http.headers.x-grafbase-client-version", version));
        }
    }

    self.operation_latency.record(latency.as_millis() as u64, &attributes);
}

use std::sync::Arc;
use std::io::Read;
use datafusion_common::Result;
use arrow::record_batch::RecordBatch;
use arrow::array::TimestampMicrosecondArray;
use arrow::compute::{gt_eq_scalar, lt_scalar, and, filter_record_batch};
use object_store::{ObjectStore, ObjectMeta, GetResultPayload};
use datafusion_datasource_avro::avro_to_arrow::ReaderBuilder;

fn filter_avro_by_timestamp(
    store: Arc<dyn ObjectStore>,
    location: ObjectMeta,
    start_ts: i64,
    end_ts: i64,
) -> Result<Vec<Arc<RecordBatch>>> {
    // Get the Avro file from the object store
    let mut payload = store.get(location.clone())?;
    let mut contents = Vec::new();
    payload.read_to_end(&mut contents)?;

    // Convert Avro file to Arrow RecordBatch
    let reader = ReaderBuilder::new().build(&contents)?;
    let mut batches = Vec::new();
    for batch in reader {
        let batch = batch?;
        let ts_array = batch.column(0).as_any().downcast_ref::<TimestampMicrosecondArray>().unwrap();
        let filter = and(gt_eq_scalar(ts_array, &start_ts), lt_scalar(ts_array, &end_ts));
        let filtered_batch = filter_record_batch(&batch, &filter)?;
        batches.push(Arc::new(filtered_batch));
    }

    Ok(batches)
}

fn wat_to_masm(
    wat: &str,
    source_name: &str,
    session: &midenc_session::Session,
) -> midenc_compile::CompilerResult<masm::Module> {
    let module = parse_str(wat)
        .map_err(|e| Report::new(format!("Failed to parse WAT: {}", e)))?;
    let config = WasmTranslationConfig {
        source_name: source_name.to_string(),
        optimize: true,
        ..Default::default()
    };
    let hir = translate(&module, &config, session)
        .map_err(|e| Report::new(format!("Failed to translate WAT: {}", e)))?;
    let analysis_manager = AnalysisManager::new(session);
    let module = masm::Module::new(&hir, &analysis_manager, session)
        .map_err(|e| Report::new(format!("Failed to generate MASM module: {}", e)))?;
    Ok(module)
}

use buddy_alloc::{BuddyAlloc, BuddyAllocParam};

pub struct FixedSizePool {
    buddy: BuddyAlloc,
    block_size: usize,
    free_blocks: Vec<usize>,
}

impl FixedSizePool {
    pub fn new(param: BuddyAllocParam, block_size: usize, capacity: usize) -> Self {
        let buddy = BuddyAlloc::new(param);
        let mut free_blocks = Vec::with_capacity(capacity);
        for _ in 0..capacity {
            let addr = buddy.alloc(block_size).unwrap();
            free_blocks.push(addr);
        }
        FixedSizePool {
            buddy,
            block_size,
            free_blocks,
        }
    }

    pub fn alloc(&mut self) -> Option<usize> {
        self.free_blocks.pop()
    }

    pub fn free(&mut self, addr: usize) {
        self.free_blocks.push(addr);
    }
}

use chrono::NaiveDateTime;
use tzfile::RcTz;
use std::io;

fn offset_difference_minutes(tz1_name: &str, tz2_name: &str) -> Result<i32, std::io::Error> {
    let tz1 = RcTz::from_name(tz1_name)?;
    let tz2 = RcTz::from_name(tz2_name)?;

    let epoch = NaiveDateTime::from_timestamp(0, 0);
    let tz1_offset = tz1.offset_at(&epoch);
    let tz2_offset = tz2.offset_at(&epoch);

    let difference = tz1_offset.total_minutes() - tz2_offset.total_minutes();
    Ok(difference)
}

