fn select_cheapest_gateway(client: &LightningClientModule, invoice: &Bolt11Invoice) -> anyhow::Result<SafeUrl> {
    let federation_id = FederationId::from(client.federation_id());
    let gateways = client.list_gateways()?;

    let mut cheapest_gateway = None;
    let mut min_fee = u64::MAX;

    for gateway in gateways {
        if !gateway.vetted {
