#[async_trait]
pub struct TimingMiddleware<H> {
    handler: H,
}

impl<H> TimingMiddleware<H> {
    pub fn new(handler: H) -> Self {
        TimingMiddleware { handler }
    }
}

#[async_trait]
impl<H> Handler for TimingMiddleware<H>
where
    H: Handler + 'static,
{
    type Output = H::Output;

    async fn call(&self, (req, handler): Next<Request, H>) -> Self::Output {
        let start = Instant::now();
        let response = handler.call((req, self.handler)).await;
        let duration = start.elapsed();

        tracing::info!(
            method = %req.method(),
            path = %req.path(),
            duration = ?duration,
            "Request processed"
        );

        response
    }
}

