fn extract_utf8_column(
    rows: &mut [&[u8]],
    column_index: usize,
    opts: RowEncodingOptions,
    dtypes: &[ArrowDataType],
) -> Vec<Option<String>> {
    let mut result = Vec::new();
    let mut row_idx = 0;

    while row_idx < rows.len() {
        let row = rows[row_idx];
        let (item_len, _) = dtype_and_data_to_encoded_item_len(dtypes[column_index], row, opts);
        if item_len == 0 {
            result.push(None);
            row_idx += 1;
            continue;
        }

        let (start, end) = {
            let mut pos = 0;
            for i in 0..column_index {
                let (len, _) = dtype_and_data_to_encoded_item_len(dtypes[i], row, opts);
                pos += len;
            }
            (pos, pos + item_len)
        };

        if end > row.len() {
            result.push(None);
            row_idx += 1;
            continue;
        }

        let bytes = &row[start..end];
        if bytes.is_empty() {
            result.push(None);
        } else {
            let decoded = decode_str(bytes);
            result.push(decoded);
        }

        row_idx += 1;
    }

    result
}

fn set_line_coding_validated(&mut self, coding: LineCoding) -> Result<(), UsbError> {
    // Validate baud rate
    if coding.baud_rate < 1200 || coding.baud_rate > 1000000 {
        return Err(UsbError::InvalidParameter);
    }

    // Validate data bits
    if coding.data_bits != 5 && coding.data_bits != 6 && coding.data_bits != 7 && coding.data_bits != 8 {
        return Err(UsbError::InvalidParameter);
    }

    // Validate stop bits
    if coding.stop_bits != StopBits::One && coding.stop_bits != StopBits::Two {
        return Err(UsbError::InvalidParameter);
    }

    // Validate parity
    if coding.parity != ParityType::None && coding.parity != ParityType::Odd && coding.parity != ParityType::Even {
        return Err(UsbError::InvalidParameter);
    }

    // Apply the validated line coding
    self.set_line_coding(coding)
}

