use pg_async::{Cluster, PgOperation, PgQueryPiece, PgFuture, PgError};

fn execute_transaction(cluster: &Cluster, ops: Vec<PgOperation>) -> PgFuture {
    let mut query_pieces = vec![PgQueryPiece::Begin];
    let mut future = PgFuture::new();

    for op in ops {
        query_pieces.push(op);
    }

    query_pieces.push(PgQueryPiece::Commit);

    let future = future.then(move |result| {
        match result {
            Ok(()) => Ok(()),
            Err(e) => {
                // Rollback on error
                let rollback_future = cluster.query(vec![PgQueryPiece::Rollback]);
                rollback_future.then(|_| Err(e))
            }
        }
    });

    cluster.query(query_pieces)
        .then(move |result| {
            match result {
                Ok(()) => future,
                Err(e) => {
                    // If query fails, trigger rollback and return error
                    let rollback_future = cluster.query(vec![PgQueryPiece::Rollback]);
                    rollback_future.then(|_| Err(e))
                }
            }
        })
}

use windows_numerics::Vector2;

fn bounding_box(points: &[Vector2]) -> Option<(Vector2, Vector2)> {
    if points.is_empty() {
        return None;
    }

    let mut min_x = f32::MAX;
    let mut min_y = f32::MAX;
    let mut max_x = f32::MIN;
    let mut max_y = f32::MIN;

    for &point in points {
        if point.x < min_x {
            min_x = point.x;
        }
        if point.y < min_y {
            min_y = point.y;
        }
        if point.x > max_x {
            max_x = point.x;
        }
        if point.y > max_y {
            max_y = point.y;
        }
    }

    Some((Vector2::new(min_x, min_y), Vector2::new(max_x, max_y)))
}

use core::ffi::c_void;
use libmimalloc_sys2::{mi_stats_print_out, mi_output_fun};

fn register_custom_stats_output() {
    let prefix = b"CustomStats: ";
    let prefix_len = prefix.len() as u64;

    let output_fun = Box::new(|buf: *mut u8, len: u64, _user: *mut c_void| {
        if !buf.is_null() && len > 0 {
            let user = unsafe { &mut *(user) };
            let prefix = user as *mut [u8; 128];
            let prefix_len = user as *mut u64;
            let mut output = Vec::with_capacity(len as usize + *prefix_len as usize);
            output.extend_from_slice(unsafe { &*prefix });
            output.extend_from_slice(unsafe { &*buf as *const u8 as *const [u8; len as usize] });
            let output_str = std::str::from_utf8(&output).unwrap();
            println!("{}", output_str);
        }
    });

    unsafe {
        mi_stats_print_out(mi_output_fun::new(output_fun.as_ptr(), Box::into_raw(output_fun) as *mut c_void));
    }
}

fn open_substream_with_timeout<C>(
    mux: &Arc<Mutex<Multiplexed<C>>>,
    timeout: std::time::Duration,
) -> Result<LocalStreamId, std::io::Error>
where
    C: AsyncRead + AsyncWrite + Unpin,
{
    let mux = mux.clone();
    let fut = poll_fn(move |cx| {
        let mux = mux.lock();
        let poll = mux.poll_open_stream(cx);
        Poll::Ready(poll)
    });

    let result = timeout(timeout, fut).await;

    match result {
        Ok(Ok(stream_id)) => Ok(stream_id),
        Ok(Err(e)) => Err(e),
        Err(e) => Err(std::io::Error::new(std::io::ErrorKind::TimedOut, e)),
    }
}

