use combine::{Parser, Stream, ParseError, StreamOnce};
use combine_language::LanguageEnv;

fn key_value_list<'a, I, K, V>(
    env: &LanguageEnv<'a, I>,
    key_parser: K,
    value_parser: V,
) -> impl Parser<I, Output = Vec<(String, String)>>
where
    I: Stream<Token = char> + 'a,
    I::Error: ParseError<I::Token, I::Range, I::Position>,
    K: Parser<I, Output = String> + Clone,
    V: Parser<I, Output = String> + Clone,
{
    let key_parser = env.whitespace().then(key_parser).then(env.whitespace());
    let value_parser = env.whitespace().then(value_parser).then(env.whitespace());

    let key_value = key_parser
        .then(|_| env.parse_char('='))
        .then(value_parser)
        .map(|((key, _), value)| (key, value.0));

    key_value
        .skip(env.parse_char(','))
        .many()
        .map(|items| items.into_iter().collect())
}

fn validate_mint_limit(deps: Deps, user_addr: &Addr, is_whitelisted: bool) -> Result<(), ContractError> {
    let config = CONFIG.load(deps.storage).map_err(|_| ContractError::ConfigNotFound)?;
    let mut total_minted = 0;

    // Check public mint limit
    if config.public_mint_limit > 0 {
        let public_minted = mint_count(deps.storage, user_addr);
        if public_minted >= config.public_mint_limit {
            return Err(ContractError::PublicMintLimitExceeded {});
        }
        total_minted += public_minted;
    }

    // Check if user is in whitelist
    if is_whitelisted {
        // Check whitelist mint limit
        let whitelist_minted = whitelist_mint_count(deps.storage, user_addr);
        if whitelist_minted >= config.whitelist_mint_limit {
            return Err(ContractError::WhitelistMintLimitExceeded {});
        }
        total_minted += whitelist_minted;

        // Check tiered whitelist mint limit
        let whitelist_config = WhitelistConfigResponse::query(&deps.querier, WhitelistQueryMsg::Config {}).unwrap();
        if let Some(tiered_config) = whitelist_config.tiered_config {
            let tiered_minted = match tiered_config.tiers.iter().find(|tier| tier.addr == user_addr.to_string()) {
                Some(tier) => {
                    let stage_response = StageResponse::query(&deps.querier, TieredWhitelistQueryMsg::Stage {
                        stage: tier.stage,
                    }).unwrap();
                    stage_response.minted
                },
                None => 0,
            };
            if tiered_minted >= tiered_config.tiers[0].limit {
                return Err(ContractError::TieredWhitelistMintLimitExceeded {});
            }
            total_minted += tiered_minted;
        }
    }

    // Check total mint limit
    if total_minted >= config.total_mint_limit {
        return Err(ContractError::TotalMintLimitExceeded {});
    }

    Ok(())
}

