use simple_xml_serialize::XMLElement;

pub fn merge_into_root(root_name: &str, elements: &[XMLElement]) -> XMLElement {
    let mut root = XMLElement::new(root_name);
    for ele in elements {
        if let Some(attrs) = &ele.attrs {
            for attr in attrs {
                let exists = root.attrs.as_ref().map_or(false, |a| a.iter().any(|ra| ra.name == attr.name));
                if !exists {
                    root.add_attr(&attr.name, &attr.value);
                }
            }
        }
        root.add_element(ele.clone());
    }
    root
}

use crate::signature::Signature;

fn pretty_signature(sig: &Signature) -> String {
    match sig {
        Signature::Basic(b) => format!("{}{}", b.char(), b.name()),
        Signature::Array(arr) => {
            let inner = pretty_signature(&arr.inner);
            format!("Array of {}", inner)
        }
        Signature::Struct(struct_sig) => {
            let fields = struct_sig
                .fields
                .iter()
                .map(|f| pretty_signature(f))
                .collect::<Vec<_>>()
                .join(", ");
            format!("Structure({})", fields)
        }
        Signature::Dict(dict) => {
            let fields = dict
                .fields
                .iter()
                .map(|f| pretty_signature(f))
                .collect::<Vec<_>>()
                .join(", ");
            format!("Dictionary({})", fields)
        }
        Signature::Union(union) => {
            let fields = union
                .fields
                .iter()
                .map(|f| pretty_signature(f))
                .collect::<Vec<_>>()
                .join(", ");
            format!("Union({})", fields)
        }
        Signature::Interface(interface) => {
            let fields = interface
                .fields
                .iter()
                .map(|f| pretty_signature(f))
                .collect::<Vec<_>>()
                .join(", ");
            format!("Interface({})", fields)
        }
        Signature::Variant(variant) => {
            let inner = pretty_signature(&variant.inner);
            format!("Variant of {}", inner)
        }
        Signature::ObjectPath => "ObjectPath".to_string(),
        Signature::String => "String".to_string(),
        Signature::Signature => "Signature".to_string(),
        Signature::Boolean => "Boolean".to_string(),
        Signature::Byte => "Byte".to_string(),
        Signature::Int16 => "Int16".to_string(),
        Signature::UInt16 => "UInt16".to_string(),
        Signature::Int32 => "Int32".to_string(),
        Signature::UInt32 => "UInt32".to_string(),
        Signature::Int64 => "Int64".to_string(),
        Signature::UInt64 => "UInt64".to_string(),
        Signature::Double => "Double".to_string(),
        Signature::UnixFD => "UnixFD".to_string(),
        Signature::Error => "Error".to_string(),
        Signature::ArrayEnd => "ArrayEnd".to_string(),
        Signature::StructEnd => "StructEnd".to_string(),
        Signature::DictEnd => "DictEnd".to_string(),
        Signature::UnionEnd => "UnionEnd".to_string(),
        Signature::InterfaceEnd => "InterfaceEnd".to_string(),
        Signature::VariantEnd => "VariantEnd".to_string(),
    }
}

