            }
        }
    }
    Ok(result)
}

use async_backtrace::taskdump_tree;

fn filtered_taskdump(wait_for_running_tasks: bool, pattern: &str) -> String {
    let tree = taskdump_tree(wait_for_running_tasks);
    let mut result = String::new();
    for task in tree {
        if task.name.contains(pattern) {
            result.push_str(&format!("{}\n", task));
        }
    }
