fn jsvalue_to_byte_string<'s>(
    scope: &mut v8::HandleScope<'s>,
    value: Local<'s, v8::Value>,
) -> Result<String, AnyError> {
    if value.is_string() {
        let string = value.to_string(scope).unwrap();
        let utf8 = string.to_utf8();
        if utf8.len != utf8.chars().count() {
            return Err(AnyError::new("String contains non-byte characters"));
        }
        Ok(utf8.chars().collect())
    } else {
        Err(AnyError::new("Value is not a string"))
    }
}

use merge3::{Merge3, StandardMarkers};
use std::borrow::ToOwned;

fn merge_multiple_branches<'b, T: Eq + std::hash::Hash + ToOwned + ?Sized>(
    base: &'b [&'b T],
    branches: &[&'b [&'b T]],
) -> Vec<T::Owned>
where
    T::Owned: std::fmt::Debug,
{
    let mut result = base.to_vec();
    let mut current = base.to_vec();

    for &branch in branches {
        let mut merged = Vec::new();
        let mut merge = Merge3::new(&current, branch, base);
        let mut markers = StandardMarkers::new();

        while let Some(line) = merge.next() {
            merged.push(line);
        }

        current = merged;
    }

    current.into_iter().map(|s| s.to_owned()).collect()
}

