fn collect_user_device_ids(user_id: Ulid, ctx: JobContext) -> Result<std::collections::HashSet<String>, anyhow::Error> {
    let mut device_ids = HashSet::new();

    // Collect device IDs from compatibility sessions
    let compat_sessions = ctx
        .compat_sessions()
        .list(CompatSessionFilter::user_id(user_id), Pagination::default())
        .context("Failed to list compatibility sessions")?;

    for session in compat_sessions {
        if let Some(device_id) = session.device_id {
            device_ids.insert(device_id.to_string());
        }
    }

    // Collect device IDs from OAuth2 sessions
    let oauth_sessions = ctx
        .oauth2_sessions()
        .list(OAuth2SessionFilter::user_id(user_id), Pagination::default())
        .context("Failed to list OAuth2 sessions")?;

    for session in oauth_sessions {
        if let Some(device_id) = session.device_id {
            device_ids.insert(device_id.to_string());
        }
    }

    Ok(device_ids)
}

