fn request_json<C, B, T>(
    client: &mut Client<C, B>,
    req: Request<B>,
) -> impl Future<Item = T, Error = Box<dyn std::error::Error + Send + Sync>>
where
    C: tower_hyper::client::client::HyperConnect + Sync + 'static,
    C::Transport: Send + 'static,
    C::Future: Send + 'static,
    B: http_body::Body + Send + 'static,
    B::Data: Send,
    B::Error: Into<crate::Error>,
    T: serde::de::DeserializeOwned,
{
    client.request(req).map(|res| {
        let body = res.into_body();
        let mut bytes = vec![];
        let _ = body.fold(bytes, |mut bytes, chunk| {
            bytes.extend_from_slice(&chunk);
            Ok(bytes)
        });
        serde_json::from_slice(&bytes).map_err(|e| e.into())
    })
}

