use wasm_bindgen::prelude::*;
use wasm_bindgen_futures::JsFuture;
use web_sys::{Request, RequestInit, RequestMode, Headers, Response};

fn post_json_result(json: &str) -> Result<js_sys::ArrayBuffer, JsValue> {
    // Create a new Headers object
    let mut headers = Headers::new().map_err(|e| e.into())?;
    headers.set("Content-Type", "application/json").map_err(|e| e.into())?;

    // Create request init object
    let mut request_init = RequestInit::new();
    request_init.method("POST");
    request_init.mode(RequestMode::Cors);
    request_init.headers(&headers);

    // Create the request body
    let body = JsValue::from(json);

    // Create the request
    let request = Request::new_with_init(&json::json!({}).as_string().unwrap(), &request_init).map_err(|e| e.into())?;

    // Send the request
    let window = web_sys::window().expect("no window found");
    let fetch_controller = window.fetch_with_request(&request).map_err(|e| e.into())?;

    // Handle the response
    let response = JsFuture::from(fetch_controller).map_err(|e| e.into())?;

    // Check if the response is ok
    if response.is_ok() {
        let response: Response = response.into();
        let array_buffer = JsFuture::from(response.array_buffer().unwrap()).map_err(|e| e.into())?;
        Ok(array_buffer)
    } else {
        let error = JsFuture::from(response).map_err(|e| e.into())?;
        Err(error)
    }
}

