use base64::prelude::{Base64Url, Engine as _};
use hyper::{Request, Body};
use libdoh::constants::{DNS_QUERY_PARAM, MAX_DNS_QUESTION_LEN, MIN_DNS_PACKET_LEN};
use libdoh::errors::DoHError;

fn extract_dns_query(req: &Request<Body>) -> Result<Vec<u8>, DoHError> {
    // Check if the query parameter exists
    if let Some(query) = req.uri().query() {
        let params: Vec<&str> = query.split('&').collect();
        for param in params {
            let kv: Vec<&str> = param.split('=').collect();
            if kv.len() == 2 && kv[0] == DNS_QUERY_PARAM {
                // Decode the base64url payload
                let decoded = Base64Url::decode_vec(kv[1]).map_err(|_| DoHError::InvalidBase64)?;

                // Validate packet size
                if decoded.len() < MIN_DNS_PACKET_LEN {
                    return Err(DoHError::InvalidPacketSize);
                }

                // Optional: Validate DNS question length if needed
                // For example, if the packet is a DNS query, check the question section length
                // This part would depend on the specific DNS protocol parsing logic
                // For simplicity, we'll assume the packet is valid if it meets the minimum size

                return Ok(decoded);
            }
        }
    }

    Err(DoHError::MissingQueryParameter)
}

