fn calculate_total_gas_used(shard: &IndexerShard) -> u64 {
    let mut total_gas = 0;
    for outcome_with_receipt in &shard.outcomes {
        if let Some(outcome) = &outcome_with_receipt.outcome {
            if let Some(view) = outcome.get_execution_outcome_view() {
                if let Some(gas_burnt) = view.gas_burnt {
                    total_gas += gas_burnt;
                }
            }
        }
    }
    total_gas
}

use std::path::{Path, PathBuf};
use std::sync::OnceLock;
use reflexo_typst::path::PathClean;
use crate::CompileOnceArgs;
use crate::utils::UnwrapOrExit;

fn resolve_entry_in_workspace(workspace: &str, entry: &str) -> CompileOnceArgs {
    let workspace_path = Path::new(workspace);
    let entry_path = if entry == "-" {
        // stdin case
        PathBuf::from("-")
    } else {
        let mut resolved_path = workspace_path.join(entry);
        if resolved_path.is_absolute() {
            // If the path is absolute, check if it's within the workspace
            if !resolved_path.starts_with(workspace_path) {
                return CompileOnceArgs {
                    parsed_entry: None,
                    main_id: None,
                    output_dir: None,
                    ..Default::default()
                };
            }
        } else {
            // If the path is relative, resolve it relative to the workspace
            resolved_path = workspace_path.join(entry);
        }
        resolved_path
    };

    // Ensure the entry file is within the workspace
    if let Some(entry_path) = entry_path.to_str() {
        if !entry_path.starts_with(workspace) {
            return CompileOnceArgs {
                parsed_entry: None,
                main_id: None,
                output_dir: None,
                ..Default::default()
            };
        }
    }

    let parsed_entry = PathClean::new(entry_path);
    let main_id = parsed_entry.to_string();
    let output_dir = workspace_path.join("output");

    CompileOnceArgs {
        parsed_entry: Some(parsed_entry),
        main_id: Some(main_id),
        output_dir: Some(output_dir),
        ..Default::default()
    }
}

use logging_timer::{timer, stimer, finish};

fn process_data(data: &str) {
    // Start the parent timer for the entire operation
    let total_timer = timer!("Total Data Processing");

    // Start the loading phase timer
    let loading_timer = stimer!("Loading Data");
    // Simulate loading data
    std::thread::sleep(std::time::Duration::from_millis(500));
    finish!(loading_timer, "data_loaded", "data_size" => data.len());

    // Start the transforming phase timer
    let transforming_timer = stimer!("Transforming Data");
    // Simulate data transformation
    std::thread::sleep(std::time::Duration::from_millis(700));
    finish!(transforming_timer, "data_transformed", "transformation_steps" => 3);

    // Start the saving phase timer
    let saving_timer = stimer!("Saving Data");
    // Simulate saving data
    std::thread::sleep(std::time::Duration::from_millis(300));
    finish!(saving_timer, "data_saved", "storage_type" => "disk");

    // Finish the total timer
    finish!(total_timer, "data_processed", "total_records" => data.len());
}

