use bytes::BytesMut;
use flate2::{Compress, Compression, FlushCompress, Status};
use crate::error::DeflateExtensionError;
use crate::codec::BufCompress;
use crate::LZ77_MAX_WINDOW_SIZE;

fn compress_payload(payload: &[u8], level: Compression) -> Result<BytesMut, DeflateExtensionError> {
    let mut encoder = Compress::new(level);
    encoder.set_window_size(LZ77_MAX_WINDOW_SIZE);
    let mut compressed = BytesMut::with_capacity(payload.len() + 1024);

    let mut buf_compress = BufCompress::new(&mut compressed);
    let mut flush = FlushCompress::Finish;

    loop {
        let bytes_read = payload.len().saturating_sub(buf_compress.pos);
        let bytes_to_compress = payload[..buf_compress.pos + bytes_read].to_vec();

        match encoder.compress(&bytes_to_compress, &mut buf_compress) {
            Ok(()) => {
                if flush == FlushCompress::Finish {
                    break;
                }
            }
            Err(Status::BufferFull) => {
                flush = FlushCompress::Finish;
                break;
            }
            Err(e) => return Err(DeflateExtensionError::from(e)),
        }
    }

    match encoder.flush(&mut buf_compress, flush) {
        Ok(()) => {
            if buf_compress.pos > 0 {
                compressed.truncate(buf_compress.pos);
            }
            Ok(compressed)
        }
        Err(e) => Err(DeflateExtensionError::from(e)),
    }
}

use viz::{Handler, Next, Request, Response, Result, StatusCode};
use std::collections::HashMap;
use std::time::{Duration, SystemTime};

struct RateLimiter {
    limit: usize,
    window: Duration,
    requests: HashMap<String, Vec<SystemTime>>,
}

impl RateLimiter {
    fn new(limit: usize, window: Duration) -> Self {
        RateLimiter {
            limit,
            window,
            requests: HashMap::new(),
        }
    }

    fn is_rate_limited(&self, ip: &str) -> bool {
        let now = SystemTime::now();
        let mut count = 0;

        // Remove old timestamps that are outside the time window
        let mut timestamps = self.requests.entry(ip.to_string()).or_insert_with(Vec::new);
        timestamps.retain(|&t| now.duration_since(t).ok().unwrap_or_default() < self.window);

        // Count how many requests are within the window
        count = timestamps.len();

        count >= self.limit
    }

    fn record_request(&mut self, ip: &str) {
        let now = SystemTime::now();
        let mut timestamps = self.requests.entry(ip.to_string()).or_insert_with(Vec::new);
        timestamps.push(now);
    }
}

impl Handler for RateLimiter {
    fn handle(&self, req: Request, _next: Next) -> Result {
        if self.is_rate_limited(req.remote_addr().unwrap_or("unknown".to_string()).as_str()) {
            return Ok(Response::from_status(StatusCode::TOO_MANY_REQUESTS));
        }

        self.record_request(req.remote_addr().unwrap_or("unknown".to_string()).as_str());
        _next.run(req)
    }
}

use std::io::Read;
