fn verify_method_return_matches_enum<E: Type, R: Read>(xml: R, interface_name: &str, method_name: &str) -> Result<(), Box<dyn std::error::Error>> {
    let method_return_type = get_method_return_type(xml, interface_name, method_name)?;
    let enum_signature = E::signature();

    if method_return_type != enum_signature {
        return Err(format!("DBus method return type mismatch: expected {:?}, got {:?}", enum_signature, method_return_type).into());
    }

    Ok(())
}

