fn compact(self) -> Self {
    let mut parts = self.parts;
    parts.remove(0); // Remove the top border line
    parts.pop();      // Remove the bottom border line
    Self {
        parts,
        ..self
    }
}

fn copy_range<R, W>(src: &R, dst: &mut W, src_offset: u64, dst_offset: u64, length: usize) -> std::io::Result<()> 
where
    R: ReadAt,
    W: WriteAt,
{
    const BUFFER_SIZE: usize = 4096;
    let mut buffer = vec![0; BUFFER_SIZE];
    let mut bytes_copied = 0;

    while bytes_copied < length {
        let remaining = length - bytes_copied;
        let chunk_size = std::cmp::min(remaining, BUFFER_SIZE);

        // Read from source
        let read_result = src.read_at(&mut buffer, src_offset + bytes_copied as u64);

        // Check if read was successful
        if read_result.unwrap() == 0 {
            break;
        }

        // Write to destination
        dst.write_at(&buffer[..chunk_size], dst_offset + bytes_copied as u64)?;
        bytes_copied += chunk_size;
    }

    Ok(())
}

