fn spi_read_with_progress(
    ec: &mut Ec<Box<dyn Access>>,
    target: SpiTarget,
    scratch: bool,
) -> Result<Vec<u8>, Error> {
    let rom = SpiRom::new(ec, target, scratch)?;
    let total_size = rom.size()?;
    let mut data = Vec::with_capacity(total_size);
    let sector_size = rom.sector_size()?;
    let mut offset = 0;

    while offset < total_size {
        let end = std::cmp::min(offset + sector_size, total_size);
        let chunk = rom.read_range(offset, end - offset)?;
        data.extend_from_slice(&chunk);
        offset += end - offset;
        let percent = (offset * 100) / total_size;
        println!("Read progress: {}%", percent);
    }

    Ok(data)
}

