use super::*;
use core::result::Result;
use core::fmt::Write;

fn export_key_to_json(key: &Key) -> Result<String> {
    let mut json = String::new();
    let mut writer = json::Encoder::new(&mut json);

    writer.write_start_object()?;

    // Write key name
    writer.write_string("name", key.name())?;

    // Write key class
    writer.write_string("class", key.class())?;

    // Write key last write time
    writer.write_string("last_write_time", &format!("{}", key.last_write_time()))?;

    // Write key values
    writer.write_string("values", &export_values_to_json(key.values())?)?;

    // Write subkeys
    writer.write_string("subkeys", &export_subkeys_to_json(key.subkeys())?)?;

    writer.write_end_object()?;
    Ok(json)
}

fn export_values_to_json(values: &[Value]) -> Result<String> {
    let mut json = String::new();
    let mut writer = json::Encoder::new(&mut json);

    writer.write_start_array()?;

    for value in values {
        writer.write_start_object()?;
        writer.write_string("name", value.name())?;
        writer.write_string("type", value.type().to_string())?;
        writer.write_string("data", &format!("{:?}", value.data()))?;
        writer.write_end_object()?;
    }

    writer.write_end_array()?;
    Ok(json)
}

fn export_subkeys_to_json(subkeys: &[Key]) -> Result<String> {
    let mut json = String::new();
    let mut writer = json::Encoder::new(&mut json);

    writer.write_start_array()?;

    for subkey in subkeys {
        writer.write_string("", &export_key_to_json(subkey)?)?;
    }

    writer.write_end_array()?;
    Ok(json)
}

fn create_cyclic_graph<'a>(arena: &'a Arena<Node<'a>>) -> &'a Node<'a> {
    let node1 = arena.alloc(Node { value: 1, neighbors: Vec::new() });
    let node2 = arena.alloc(Node { value: 2, neighbors: Vec::new() });
    let node3 = arena.alloc(Node { value: 3, neighbors: Vec::new() });

