use std::time::Duration;
use tokio::time::sleep;
use solana_sdk::message::Message;
use solana_sdk::transaction::TransactionError;
use solana_sdk::signers::Signers;
use miraland_client::tpu_client::TpuClient;
use miraland_client::quic_client::{QuicPool, QuicConnectionManager, QuicConfig};
use miraland_client::rpc_client::RpcClient;
use crate::client_error::Result;

fn send_batch_with_backoff(
    tpu_client: &TpuClient<QuicPool, QuicConnectionManager, QuicConfig>,
    rpc: &RpcClient,
    messages: &[Message],
    signers: &impl Signers,
    max_retries: usize,
) -> Result<Vec<Option<TransactionError>>> {
    let mut errors = Vec::new();
    let mut retry_count = 0;

    loop {
        let mut batch_errors = Vec::new();
        let mut batch_txs = Vec::new();

        for message in messages {
            let (tx, err) = tpu_client.send_message(message, signers);
            batch_txs.push(tx);
            batch_errors.push(err);
        }

        let mut all_ok = true;
        for &err in &batch_errors {
            if let Some(err) = err {
                match err {
                    TransactionError::BlockhashExpired => {
                        all_ok = false;
                        break;
                    }
                    _ => {
                        // Non-blockhash related error, treat as failure
                        all_ok = false;
                        break;
                    }
                }
            }
        }

        if all_ok {
            return Ok(batch_errors);
        }

        // If blockhash expired, fetch new blockhash and retry
        if let Some(index) = batch_errors.iter().position(|&err| err == Some(TransactionError::BlockhashExpired)) {
            let new_blockhash = rpc.get_latest_blockhash()?;
            for (i, tx) in batch_txs.iter_mut().enumerate() {
                if i == index {
                    tx.blockhash = new_blockhash;
                }
            }
        }

        // If we've reached max retries, return errors
        if retry_count >= max_retries {
            return Ok(batch_errors);
        }

        // Exponential backoff
        let delay = Duration::from_secs(1 << retry_count);
        sleep(delay).await;

        retry_count += 1;
    }
}

fn snapshot_keys<K: leveldb::database::key::Key + Ord>(db: &leveldb::database::Database<K>) -> Result<Vec<K>, leveldb::database::error::Error> {
    let read_options = ReadOptions::new();
    read_options.set_snapshot(true);
    let snapshot = db.snapshot(&read_options)?;
    let mut keys = Vec::new();
    let mut iter = db.iterator(&read_options);
    iter.seek_to_first();
    while let Some(key) = iter.next() {
        keys.push(key.key().clone());
    }
    Ok(keys)
}

