fn retry_task<T>(task: T::Task, max_retries: u8) -> T::Value
where
    T: TaskQueue + LocalQueue<64, BufferCell = stack_queue::task::TaskRef<T>>,
    T::Task: Clone,
{
    let mut retries = 0;
    let mut result = None;

    while retries < max_retries {
        match T::enqueue(task.clone()) {
            Ok(value) => {
                result = Some(value);
                break;
            }
            Err(_) => {
                if retries == max_retries - 1 {
                    // Last attempt, no backoff
                    continue;
                }
                // Wait with exponential backoff
                let delay = Duration::from_secs(1 << retries);
                sleep(delay).await;
                retries += 1;
            }
        }
    }

    result.expect("Failed to enqueue task after maximum retries")
}

fn diff_with_filter<F>(first: &[&str], second: &[&str], filter: F) -> Vec<String>
where
    F: Fn(&str) -> bool,
{
    let filtered_first: Vec<&str> = first.iter().filter(|&&line| filter(line)).collect();
    let filtered_second: Vec<&str> = second.iter().filter(|&&line| filter(line)).collect();

    let differ = Differ::new();
    let diff = differ.compare(filtered_first, filtered_second);

    diff.iter().map(|line| line.to_string()).collect()
}

use easy_jsonrpc_mw::{Handler, BoundMethod, Call, Response, ResponseFail, Tracker};
use serde::Deserialize;

fn execute_batch<T, H>(handler: &H, methods: Vec<BoundMethod<'static, T>>) -> Result<Vec<T>, ResponseFail>
where
    T: Deserialize<'static>,
    H: Handler,
{
    let mut tracker = Tracker::new();
    let mut calls = Vec::new();
    let mut results = Vec::new();

    for method in methods {
        let call = Call::new(method, &mut tracker);
        calls.push(call);
    }

    handler.send_batch(calls)?;

    while tracker.has_pending() {
        if let Some(response) = handler.poll_response() {
            if let Response::Success(result) = response {
                results.push(result);
            } else {
                return Err(ResponseFail::new(response));
            }
        }
    }

    Ok(results)
}

fn handle_gateway_refund(context: &LightningClientContext, operation_id: OperationId) -> Result<(), anyhow::Error> {
    // Fetch the send operation state for the given operation ID
    let send_op_state = context
        .get_send_operation_state(operation_id)
        .map_err(|e| anyhow::anyhow!("Failed to get send operation state: {}", e))?;

    // Check if the operation is a refund
    if send_op_state.is_refund() {
        // Initiate the refund transaction
        let refund_tx = context
            .initiate_refund_transaction(operation_id)
            .map_err(|e| anyhow::anyhow!("Failed to initiate refund transaction: {}", e))?;

        // Wait for the refund transaction to be confirmed
        let refund_tx_id = refund_tx.transaction_id();
        let mut confirmed = context
            .wait_for_transaction_confirmation(refund_tx_id)
            .map_err(|e| anyhow::anyhow!("Failed to wait for refund transaction confirmation: {}", e))?;

        // Report success once the refund is confirmed
        if confirmed {
            println!("Refund transaction confirmed successfully.");
        } else {
            println!("Refund transaction failed to confirm.");
        }
    } else {
        println!("Operation is not a refund.");
    }

    Ok(())
}

