use std::io;
use positioned_io2::{ReadAt, ReadBytesAtExt};

fn read_c_string_at<R: ReadAt>(io: &R, offset: u64) -> io::Result<String> {
    let mut buffer = Vec::new();
    let mut bytes_read = 0;

    loop {
        let byte = io.read_byte_at(offset + bytes_read)?;
        bytes_read += 1;

        if byte == 0 {
            break;
        }

        buffer.push(byte);
    }

    String::from_utf8(buffer).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))
}

fn get_or_insert_with_meta<K, V, E, B>(
    cache: &crate::cache_api::LoadingCache<K, V, E, B>,
    key: K,
    ttl: std::time::Duration,
) -> Result<V, crate::cache_api::CacheLoadingError<E>>
where
    K: Clone + Eq + std::hash::Hash + Send + 'static,
    V: Clone + Send + 'static,
    E: std::fmt::Debug + Clone + Send + 'static,
    B: crate::backing::CacheBacking<K, crate::cache_api::CacheEntry<V, E>> + Send + 'static,
    crate::backing::TtlMeta: From<std::time::Duration>,
{
    let entry = cache.get(&key);
    match entry {
        Ok(entry) => Ok(entry.value().clone()),
        Err(CacheLoadingError::NotFound) => {
            let value = cache.load(key.clone())?;
            let entry = CacheEntry {
                value: value.clone(),
                metadata: TtlMeta::from(ttl),
            };
            cache.insert(key, entry);
            Ok(value)
        }
        Err(e) => Err(e),
    }
}

