use grok::Grok;
use std::collections::HashMap;

fn multi_pattern_match(
    pattern_map: &HashMap<&str, &str>,
    text: &str,
) -> HashMap<String, HashMap<String, String>> {
    let mut result = HashMap::new();
    let mut grok_patterns = HashMap::new();

    // Precompile all patterns
    for (name, pattern) in pattern_map {
        let grok = Grok::new(pattern).unwrap();
        grok_patterns.insert(name.to_string(), grok);
    }

    // Apply each precompiled pattern to the text
    for (name, &pattern) in pattern_map {
        if let Some(grok) = grok_patterns.get(name) {
            if let Ok(matches) = grok.match(text) {
                let mut match_map = HashMap::new();
                for (key, value) in matches {
                    match_map.insert(key.to_string(), value.to_string());
                }
                result.insert(name.to_string(), match_map);
            }
        }
    }

    result
}

