fn write_processing_instruction(&mut self, target: &str, data: &str) -> io::Result<()> {
    if self.state != State::Document {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "Processing instruction must be written in the document context"));
    }

    let mut buffer = String::with_capacity(target.len() + data.len() + 10);
    buffer.push_str("<?");
    buffer.push_str(target);
    buffer.push(' ');
    buffer.push_str(data);
    buffer.push_str("?>");

    self.writer.write_all(buffer.as_bytes())?;
    self.writer.flush()?;

    Ok(())
}

