    format!("-----BEGIN PUBLIC KEY-----\n{}\n-----END PUBLIC KEY-----", encoded)
}

fn draw_quads(
    &mut self,
    quads: &[Quad],
    background: &Background,
    transformation: Transformation,
    pixels: &mut tiny_skia::PixmapMut<'_>,
    clip_mask: &mut tiny_skia::Mask,
    clip_bounds: Rectangle,
) {
    let mut clip_mask_path = tiny_skia::Path::new();
    clip_mask_path.add_rect(clip_bounds.to_skia_rect());

    let mut clip_mask_data = tiny_skia::MaskData::new();
    clip_mask_data.set_path(clip_mask_path, tiny_skia::BlendMode::SourceOver);
    clip_mask_data.set_paint(tiny_skia::Paint::default());
    clip_mask_data.set_bounds(clip_bounds.to_skia_rect());

    clip_mask.set_data(clip_mask_data);

    pixels.set_mask(clip_mask);

    for quad in quads {
        let mut paint = tiny_skia::Paint::default();
        paint.set_color(quad.color);
        paint.set_alpha(quad.opacity);
        paint.set_blend_mode(tiny_skia::BlendMode::SourceOver);

        let mut path = tiny_skia::Path::new();
        path.add_rect(quad.bounds.to_skia_rect());

        let transformed_path = transformation.apply_to_path(&path);

        pixels.fill_path(&transformed_path, &paint);
    }
}

fn update_dispute_status(dispute: &mut Dispute, new_status: Status) -> Result<(), ServiceError> {
    let current_status = dispute.status;

    match (current_status, new_status) {
        (Status::Initiated, Status::InProgress) => {
            dispute.status = new_status;
            Ok(())
        },
        (Status::InProgress, Status::Resolved) => {
            dispute.status = new_status;
            Ok(())
        },
        (Status::InProgress, Status::Escalated) => {
            dispute.status = new_status;
            Ok(())
        },
        (Status::Resolved, Status::Closed) => {
            dispute.status = new_status;
            Ok(())
        },
        (Status::Escalated, Status::InProgress) => {
            dispute.status = new_status;
            Ok(())
        },
        (Status::Escalated, Status::Closed) => {
            dispute.status = new_status;
            Ok(())
        },
        _ => Err(ServiceError::InvalidStatusTransition),
    }
}

fn get_with_retry(
    &self,
    options: &ReadOptions,
    key: &dyn IntoLevelDBKey,
    max_retries: usize,
) -> Result<Option<Vec<u8>>, Error> {
    let mut retries = 0;
    loop {
        match self.get(options, key) {
            Ok(value) => return Ok(value),
            Err(Error::IOError(_)) => {
                if retries >= max_retries {
                    return Err(Error::IOError("Max retries exceeded".to_string()));
                }
                retries += 1;
                std::thread::sleep(std::time::Duration::from_secs(2usize.pow(retries as u32)));
                continue;
            }
            Err(e) => return Err(e),
        }
    }
}

use sixel_sys::{sixel_decode, status};

fn extract_palette(sixels: &[u8]) -> Result<Vec<u8>, i32> {
    let mut decoded = sixel_decode(sixels);
    if decoded.is_err() {
        return Err(decoded.err().unwrap());
    }

    let decoded = decoded.unwrap();
    let palette = decoded.palette;

    if palette.is_null() {
        return Err(status::SIXEL_ERR_NO_PALETTE as i32);
    }

    let palette_size = decoded.palette_size as usize;
    let mut palette_data = Vec::with_capacity(palette_size);
    unsafe {
        for i in 0..palette_size {
            palette_data.push(*palette.add(i));
        }
    }

    Ok(palette_data)
}

fn rollback_last_migration(text: &str, current_version: &str) -> Result<Option<String>> {
    let pending = pending_migrations(current_version)?;
    if pending.is_empty() {
        return Ok(None);
    }

    let latest_migration = pending.last().unwrap();
    let migration_version = latest_migration.version();

    let mut modified_text = text.to_string();
    let migration_pattern = match migrations().get(migration_version) {
        Some(migration) => migration.pattern.clone(),
        None => return Ok(None),
    };

    let query = Query::new(SETTINGS_NESTED_KEY_VALUE_PATTERN, &migration_pattern)?;
    let mut captures = query.captures(&modified_text);

    while let Some(capture) = captures.next() {
        if let Some(capture) = capture {
            if let Some(text) = capture.capture_text() {
                let key = capture.name();
                let value = text.to_string();
                let mut new_text = modified_text.clone();
                let replacement = format!("{}{}", key, value);
                new_text = new_text.replace(&format!("{}{}", key, value), &replacement);
                modified_text = new_text;
            }
        }
    }

    Ok(Some(modified_text))
}

