fn average_latency(
    latencies: &std::collections::BTreeMap<fedimint_core::PeerId, Option<std::time::Duration>>,
) -> Option<std::time::Duration> {
    let mut total = Duration::zero();
    let mut count = 0;

    for &(_, latency) in latencies {
        if let Some(latency) = latency {
            total += latency;
            count += 1;
        }
    }

    if count == 0 {
        return None;
    }

    Some(total / count)
}

