use syn::ItemFn;
use syn::Error;
use syn::spanned::Spanned;
use syn::AttrStyle;
use syn::Meta;
use syn::MetaList;
use syn::NestedMeta;
use syn::Ident;
use syn::Lit;
use syn::LitStr;

fn validate_node_bindgen_attrs(item: &syn::ItemFn) -> Result<(), syn::Error> {
    let attrs = &item.attrs;
    let mut has_constructor = false;
    let mut name_attr = None;

    for attr in attrs {
        if attr.style != AttrStyle::Outer {
            continue;
        }

        if let Ok(meta) = attr.parse_meta() {
            if let Meta::List(MetaList { path, nested, .. }) = meta {
                if path.get_ident().map_or(false, |ident| ident.to_string() == "node_bindgen") {
                    for nested_meta in nested {
                        if let NestedMeta::Meta(Meta::NameValue(name_value)) = nested_meta {
                            if name_value.path.get_ident().map_or(false, |ident| ident.to_string() == "constructor") {
                                has_constructor = true;
                            } else if name_value.path.get_ident().map_or(false, |ident| ident.to_string() == "name") {
                                if let syn::Lit::Str(lit_str) = &name_value.value {
                                    if !lit_str.value().starts_with('"') || !lit_str.value().ends_with('"') {
                                        return Err(Error::new(name_value.span(), "name attribute must be a string literal"));
                                    }
                                } else {
                                    return Err(Error::new(name_value.span(), "name attribute must be a string literal"));
                                }
                                name_attr = Some(name_value.value.clone());
                            }
                        }
                    }
                }
            }
        }
    }

    if has_constructor && item.sig.fn_token.is_some() && !item.sig.name.is_none() {
        return Err(Error::new(item.sig.name.as_ref().map(|n| n.span()).unwrap_or(item.span()), "constructor attribute cannot be used with a free function"));
    }

    Ok(())
}

use fsevent::Event;
use std::path::Path;

fn filter_by_extensions(events: Vec<Event>, extensions: &[&str]) -> Vec<Event> {
    events.into_iter().filter(|event| {
        if let Some(path) = event.path() {
            if let Some(ext) = path.extension() {
                if let Some(ext_str) = ext.to_str() {
                    extensions.iter().any(|&ext| ext == ext_str)
                } else {
                    false
                }
            } else {
                false
            }
        } else {
            false
        }
    }).collect()
}

