use solana_program::clock::Slot;
use std::collections::HashSet;

impl LastVotedForkSlotsAggregate {
    pub fn merge(&mut self, other: &LastVotedForkSlotsAggregate) {
        for (pubkey, other_slots) in &other.last_voted_fork_slots {
            let sender_stake = Self::validator_stake(&self.epoch_stakes, pubkey);
            if sender_stake == 0 { continue; }
            self.active_peers.insert(*pubkey);
            let new_set: HashSet<Slot> = other_slots.to_slots(self.root_slot).into_iter().collect();
            let old_set = match self.last_voted_fork_slots.get(pubkey) {
                Some(old) => old.to_slots(self.root_slot).into_iter().collect(),
                None => HashSet::new(),
            };
            for slot in old_set.difference(&new_set) {
                if let Some(entry) = self.slots_stake_map.get_mut(slot) {
                    *entry = entry.saturating_sub(sender_stake);
                }
            }
            for slot in new_set.difference(&old_set) {
                let entry = self.slots_stake_map.entry(*slot).or_insert(0);
                *entry = entry.saturating_add(sender_stake);
            }
            self.last_voted_fork_slots.insert(*pubkey, other_slots.clone());
        }
        self.slots_to_repair.clear();
        let total_stake = self.epoch_stakes.total_stake();
        let threshold = (total_stake as f64 * self.repair_threshold) as u64;
        for (slot, stake) in &self.slots_stake_map {
            if *stake >= threshold {
                self.slots_to_repair.insert(*slot);
            }
        }
    }

    fn validator_stake(stakes: &HashSet<solana_program::pubkey::Pubkey>, pubkey: &solana_program::pubkey::Pubkey) -> u64 {
        *stakes.get(pubkey).unwrap_or(&0)
    }
}

use winresource::{WindowsResource, VersionInfo};

fn main() {
    if std::env::var("CARGO_CFG_TARGET_OS").unwrap() == "windows" {
        let mut res = WindowsResource::new();
        let version = std::env::var("MY_APP_VERSION")
            .expect("MY_APP_VERSION environment variable not set");
        let parts: Vec<u32> = version
            .split('.')
            .map(|s| s.parse::<u32>().expect("Invalid version component"))
            .collect();
        let (major, minor, patch) = (parts[0], parts[1], parts[2]);
        let filever = ((major as u64) << 48) | ((minor as u64) << 32) | ((patch as u64) << 16);
        res.set_version_info(VersionInfo::FILEVERSION, filever)
            .set_version_info(VersionInfo::PRODUCTVERSION, filever)
            .compile()
            .unwrap();
    }
}

fn parse_transaction_logs_filter(config: &serde_json::Value) -> Result<RpcTransactionLogsFilter, String> {
    if let Some(s) = config.as_str() {
        match s {
            "all" => return Ok(RpcTransactionLogsFilter::All),
            "all_with_votes" => return Ok(RpcTransactionLogsFilter::AllWithVotes),
            _ => {
                if s.starts_with("mentions:") {
                    let address_str = &s["mentions:".len()..];
                    if let Ok(pubkey) = Pubkey::from_str(address_str) {
                        return Ok(RpcTransactionLogsFilter::Mentions(vec![pubkey]));
                    }
                }
                return Err(format!("Invalid filter: {}", s));
            }
        }
    } else if let Some(arr) = config.as_array() {
        let mut pubkeys = Vec::new();
        for item in arr {
            if let Some(s) = item.as_str() {
                if s.starts_with("mentions:") {
                    let address_str = &s["mentions:".len()..];
                    if let Ok(pubkey) = Pubkey::from_str(address_str) {
                        pubkeys.push(pubkey);
                    } else {
                        return Err(format!("Invalid address: {}", address_str));
                    }
                } else {
                    return Err(format!("Invalid filter entry: {}", s));
                }
            } else {
                return Err("Invalid filter entry".to_string());
            }
        }
        if pubkeys.is_empty() {
            return Err("No addresses provided".to_string());
        }
        return Ok(RpcTransactionLogsFilter::Mentions(pubkeys));
    }
    Err("Invalid filter format".to_string())
}

