    total = total + metrics.heap;
    total = total + metrics.stack;
    total = total + metrics.metadata;
    total = total + metrics.indirect;
    total = total + metrics.builtin;
    total = total + metrics.queues;
    total = total + metrics.allocated;
    total = total + metrics.arena;
    total = total + metrics.threads;
    total = total + metrics.globals;
    total = total + metrics.queues;
    total = total + metrics.heap_allocated;
    total = total + metrics.heap_freed;
    total = total + metrics.heap_growth;
    total = total + metrics.heap_usage;
    total = total + metrics.heap_peak;
    total = total + metrics.heap_usage;
    total = total + metrics.heap_usage;
    total
}

fn escape_field(buf: &[u8]) -> Vec<u8> {
    if buf.is_empty() {
        return Vec::new();
    }

    if !should_escape(buf) {
        return buf.to_vec();
    }

    let mut result = Vec::with_capacity(buf.len() * 2 + 2);
    result.push(b'{');

    for &b in buf {
        match b {
            CURLY_L | SP | CR | LF => {
                result.push(b'\\');
                result.push(b);
            }
            _ => result.push(b),
        }
    }

    result.push(b'}');
    result
}

fn should_escape(buf: &[u8]) -> bool {
    if buf.len() > 100 {
        return true;
    }
    buf.iter().any(|&b| b == CURLY_L || b == SP || b == CR || b == LF)
}

fn run_command_capture(
    cmd: &str,
    args: &[&str],
) -> Result<(ChildStatus, String, String), ProcessError> {
    let mut child = Command::new(cmd)
        .args(args)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(ProcessError::FailedToSpawnProcess)?;

    let stdout = child
        .stdout
        .take()
        .ok_or(ProcessError::MissingStdout)
        .read_to_string()
        .map_err(ProcessError::FailedToReadStdout)?;

    let stderr = child
        .stderr
        .take()
        .ok_or(ProcessError::MissingStderr)
        .read_to_string()
        .map_err(ProcessError::FailedToReadStderr)?;

    let status = child
        .wait()
        .map_err(ProcessError::FailedToWaitForChild)?;

    Ok((status, stdout, stderr))
}

fn batch_insert_data<M>(
