{
    let mut documents = Vec::with_capacity(rows.len());
    for (key, data_row) in rows {
        let mut doc = doc! {};
        for (column_name, value) in data_row {
            doc.insert(column_name, value);
        }
        documents.push(doc);
    }
    storage.insert_many(table_name, documents)
}

