use libdeflater::{Decompressor, DecompressionError};

fn safe_gzip_decompress(data: &[u8]) -> Result<Vec<u8>, DecompressionError> {
    // Check the gzip magic header
    if data.len() < 2 {
        return Err(DecompressionError::BadData);
    }
    if data[0] != 0x1f || data[1] != 0x8b {
        return Err(DecompressionError::BadData);
    }

    // Check for the gzip footer (2 bytes)
    if data.len() < 2 {
        return Err(DecompressionError::BadData);
    }

    // Create a decompressor
    let mut decompressor = Decompressor::new();

    // Decompress the data
    let mut result = Vec::new();
    decompressor.decompress(data, &mut result)?;

    // Check for the gzip footer (2 bytes)
    if data.len() < 2 {
        return Err(DecompressionError::BadData);
    }

    Ok(result)
}

use coremidi_sys::{MIDIPortRef, MIDIEndpointRef, MIDIEventList, MIDIEventListInit, MIDIEventListAdd, MIDISendEventList, MIDIProtocolID, kMIDIProtocol_2_0, ByteCount, UInt32, OSStatus};

fn send_event_list(port: MIDIPortRef, destination: MIDIEndpointRef, packets: &[&[UInt32]]) -> Result<(), OSStatus> {
    let mut event_list = unsafe { MIDIEventListInit() };
    if event_list.is_null() {
        return Err(OSStatus::new(-1));
    }

    for &packet in packets {
        let mut packet_count = packet.len() as UInt32;
        let packet_buffer = packet.as_ptr() as *const UInt32;
        let protocol_id = MIDIProtocolID::new(kMIDIProtocol_2_0 as u32);
        let status = unsafe { MIDIEventListAdd(event_list, protocol_id, packet_buffer, packet_count) };
        if status != 0 {
            unsafe { MIDISendEventList(event_list, port, destination) };
            unsafe { MIDIEventListInit() };
            return Err(status);
        }
    }

    let status = unsafe { MIDISendEventList(event_list, port, destination) };
    unsafe { MIDIEventListInit() };
    Ok(status)
}

use icu_decimal::DecimalFormatter;
use icu_provider::prelude::*;
use icu_locale_core::locale;
use fixed_decimal::Decimal;

fn format_with_custom_signs<D>(
    provider: &D,
    locale: icu_locale_core::Locale,
    value: &Decimal,
    plus: &str,
    minus: &str,
) -> String
where
    D: DataProvider<icu_decimal::provider::DecimalSymbolsV1>
        + DataProvider<icu_decimal::provider::DecimalDigitsV1>,
{
    let decimal_symbols = DecimalSymbolsV1::try_new(
        provider.load_payload_for_locale(&locale, UnicodePath::from_str("decimal").unwrap())
            .expect("Failed to load decimal symbols"),
    )
    .expect("Failed to create decimal symbols");

    let decimal_digits = DecimalDigitsV1::try_new(
        provider.load_payload_for_locale(&locale, UnicodePath::from_str("digits").unwrap())
            .expect("Failed to load decimal digits"),
    )
    .expect("Failed to create decimal digits");

    let formatter = DecimalFormatter::try_new(
        decimal_symbols,
        decimal_digits,
        locale,
    )
    .expect("Failed to create decimal formatter");

    let formatted = formatter.format(value).expect("Failed to format value");

    let formatted_str = formatted.to_string();

    let mut result = formatted_str;

    // Replace the plus sign with the custom plus string
    if result.starts_with('+') {
        result = result.replace('+', plus);
    }

    // Replace the minus sign with the custom minus string
    if result.starts_with('-') {
        result = result.replace('-', minus);
    }

    result
}

