    while let Some(key) = stream.next().await {
        // This is a no-op as the filter already processes the key
    }

    Ok(latest_revisions)
}

fn read_custom_csv(
    store: &Arc<dyn ObjectStore>,
    object: &ObjectMeta,
    delimiter: u8,
    null_regex: Option<String>,
) -> Result<Vec<RecordBatch>> {
    let file_url = ObjectStoreUrl::from(object.location().clone());
    let file_path = file_url.to_file_path().unwrap();

    let config = FileScanConfigBuilder::new()
        .with_delimiter(delimiter as char)
        .with_has_header(true)
        .with_null_regex(null_regex)
        .build();

    let csv_format = CsvFormat::new(config);

    let source = CsvSource::new(store, object, csv_format);

    let session = Session::new();
    let task_ctx = TaskContext::new();
    let stream = source.execute(&session, &task_ctx)?;

    let batches: Vec<RecordBatch> = stream.collect().await?.into_iter().collect();

    Ok(batches)
}

use crate::RocksDB;
use crate::Col;
use crate::Result;
use rocksdb::DB;
use rocksdb::Options;
use rocksdb::WriteOptions;
use rocksdb::IteratorMode;
use std::path::Path;

fn merge_dbs(source_db1: &RocksDB, source_db2: &RocksDB, new_path: &Path, columns: u32) -> Result<()> {
    // Create a new RocksDB instance at the new path
    let mut opts = Options::default();
    opts.create_if_missing(true);
    let db = DB::open(&opts, new_path)?;

    // Function to copy all key-value pairs from a source DB to the new DB
    fn copy_db(source: &DB, target: &DB, columns: u32) -> Result<()> {
        let mut write_opts = WriteOptions::default();
        write_opts.disable_wal(true); // Disable WAL to avoid duplicate logs

        let mut iter = source.iter();
        while let Some((key, value)) = iter.next() {
            let key = key.to_vec();
            let value = value.to_vec();
            target.put_opt(&key, &value, &write_opts)?;
        }
        Ok(())
    }

    // Copy data from both source databases to the new one
    copy_db(source_db1, &db, columns)?;
    copy_db(source_db2, &db, columns)?;

    Ok(())
}

use std::time::Duration;
use tokio_with_wasm::time::interval;

fn poll_js_api_until<T, F>(mut fetch: F, period: Duration, max_polls: usize) -> Vec<T>
where
    T: Send + 'static,
    F: FnMut() -> T + Send + 'static,
{
    let mut results = Vec::with_capacity(max_polls);
    let mut poll_count = 0;

    // Spawn a tokio task to perform the polling
    tokio_with_wasm::spawn(async move {
        if let Ok(mut interval) = interval(period) {
            while poll_count < max_polls {
                // Check if cancellation is requested (simulated here with a flag)
                // In a real scenario, this could be a shared state or a channel
                if poll_count >= max_polls {
                    break;
                }

                // Perform the poll
                let result = fetch();
                results.push(result);

                poll_count += 1;

                // Wait for the next interval
                if let Err(_) = interval.tick().await {
                    break;
                }
            }
        }
    });

    // Wait for the polling task to complete
    tokio_with_wasm::runtime::current_thread::block_on(async {
        // Wait for the task to finish
        tokio_with_wasm::task::yield_now().await;
        results
    })
}

