fn md5_of_files(paths: &[PathBuf]) -> Result<Vec<Digest>, Error> {
    let mut tasks = vec![];
    for path in paths {
        tasks.push(task::spawn(async move {
            match chksum(path).await {
                Ok(digest) => Ok(digest),
                Err(e) => Err(e),
            }
        }));
    }
    let results = join_all(tasks).await;
    let mut digests = vec![];
    for result in results {
        digests.push(result?);
    }
    Ok(digests)
}

fn spans_overlap(a: Span, b: Span) -> bool {
    // Check if the spans overlap by comparing their start and end positions
    // A span [start1, end1) overlaps with [start2, end2) if:
    // start1 < end2 and start2 < end1
    a.start < b.end && b.start < a.end
}

