where
    F: FnMut(&str) + Send + 'static,
{
    let original_writer = unsafe { Hostfxr::get_error_writer() };

    unsafe {
        Hostfxr::set_error_writer(|msg: *mut c_char| {
            if !msg.is_null() {
                let c_str = std::ffi::CStr::from_ptr(msg);
