    Some(original_writer)
}

fn train_with_metadata(&mut self, text: &str, classification: &str, metadata: String) {
    let tokens = get_tokenized_and_stemmed(text);
    let mut word_counts = HashMap::new();

    for token in tokens {
        *word_counts.entry(token.to_string()).or_insert(0) += 1;
    }

    let document_id = format!("doc_{}", self.total_document_count);
    self.total_document_count += 1;

    self.documents.entry(classification.to_string()).or_insert_with(HashMap::new).entry(document_id.clone()).or_insert(0);
    self.documents.get_mut(classification).unwrap().get_mut(&document_id).unwrap() += 1;

    self.metadata.entry(classification.to_string()).or_insert_with(Vec::new).push((document_id, metadata));
}

