use std::io::Read;
use std::ptr;
use lz4_sys::{LZ4FDecompressionContext, LZ4F_VERSION, LZ4F_createDecompressionContext, LZ4F_freeDecompressionContext, LZ4F_decompress, check_error, size_t};

fn decompress_chunked<R: Read>(mut src: R, chunk_size: usize) -> std::io::Result<Vec<u8>> {
    let mut context: *mut LZ4FDecompressionContext = ptr::null_mut();
    let mut decompressed_size = 0;
    let mut decompressed_data = Vec::with_capacity(chunk_size);
    let mut buffer = vec![0u8; chunk_size];

    unsafe {
        check_error(LZ4F_createDecompressionContext(&mut context, LZ4F_VERSION));
    }

    loop {
        let mut input_size = 0;
        let mut output_size = 0;

        // Read input data
        let mut input_buffer = vec![0u8; chunk_size];
        let bytes_read = src.read(&mut input_buffer)?;
        if bytes_read == 0 {
            break;
        }
        input_size = bytes_read as size_t;

        // Decompress
        check_error(LZ4F_decompress(
            context,
            input_buffer.as_ptr(),
            input_size,
            buffer.as_mut_ptr(),
            chunk_size as size_t,
            &mut output_size,
        ));

        decompressed_data.extend_from_slice(&buffer[..output_size as usize]);
        decompressed_size += output_size as usize;

        // If decompressed data is larger than chunk_size, return it
        if decompressed_data.len() >= chunk_size {
            break;
        }
    }

    unsafe {
        check_error(LZ4F_freeDecompressionContext(context));
    }

    Ok(decompressed_data)
}

fn log_build_status(status: BuildStatus, reason: Option<&str>) {
    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .expect("Time went backwards")
        .as_secs();

    let reason_str = match reason {
        Some(r) => format!(" (reason: {})", r),
        None => String::new(),
    };

    match status {
        BuildStatus::Success => {
            println!("[{}] Build succeeded{}", timestamp, reason_str);
        }
        BuildStatus::Failed => {
            println!("[{}] Build failed{}", timestamp, reason_str);
        }
        BuildStatus::Skipped => {
            println!("[{}] Build skipped{}", timestamp, reason_str);
        }
        BuildStatus::Cancelled => {
            println!("[{}] Build cancelled{}", timestamp, reason_str);
        }
    }
}

struct RetryIterator {
    base: Duration,
    max: Duration,
    jitter_factor: f64,
    current: Duration,
    count: usize,
}

impl RetryIterator {
    fn new(base: Duration, max: Duration, jitter_factor: f64) -> Self {
        RetryIterator {
            base,
            max,
            jitter_factor,
            current: base,
            count: 0,
        }
    }

    fn next(&mut self) -> Option<Duration> {
        if self.current > self.max {
            return None;
        }

        let jitter = (self.current.as_nanos() as f64 * self.jitter_factor) as u128;
        let jittered_duration = Duration::new(self.current.as_secs(), self.current.subsec_nanos() as u32 + jitter as u32);

        self.count += 1;
        self.current = min(Duration::new(self.count as u64, 0), self.max);
        Some(jittered_duration)
    }
}

