use line_drawing::{BresenhamCircle, Point};
use std::collections::HashMap;

fn filled_disc(cx: i32, cy: i32, radius: i32) -> Vec<Point<i32>> {
    let mut points = Vec::new();
    let mut circle_points = BresenhamCircle::new(cx, cy, radius);

    // Collect all perimeter points
    let mut perimeter = HashMap::new();
    for point in circle_points {
        perimeter.insert((point.x, point.y), ());
    }

    // Iterate over all points inside the circle
    for x in (cx - radius)..=(cx + radius) {
        for y in (cy - radius)..=(cy + radius) {
            let dx = x - cx;
            let dy = y - cy;
            if dx*dx + dy*dy <= radius*radius {
                points.push(Point { x, y });
            }
        }
    }

    points
}

fn request_id_trace_layer() -> TraceLayer<impl MakeSpan<Request<()>>, impl EnrichSpan<Response<()>>, impl EnrichSpan<Error>> {
    TraceLayer::new()
        .make_span_with(|request: &Request<()>| {
            let span = Span::current();
            if let Some(id) = request.headers().get("X-Request-ID") {
                span.record("request_id", id);
            }
            span
        })
        .enrich(|span: &mut Span, response: &Response<()>| {
            span.record("status", &response.status().as_str());
        })
        .enrich(|span: &mut Span, error: &Error| {
            if let Some(description) = error.to_string().as_str() {
                span.record("error", description);
            }
        })
}

