use websockets::{WebSocket, WebSocketError, secure::TlsCertificate};
use native_tls::Certificate;
use std::fs::File;
use std::io::BufReader;

fn connect_with_custom_root() -> Result<WebSocket, WebSocketError> {
    // Load the custom root certificate from a file
    let cert_file = "path/to/custom_root_certificate.pem";
    let file = File::open(cert_file)?;
    let reader = BufReader::new(file);
    let cert = Certificate::from_pem(reader)?;

    // Create a TlsCertificate with the custom root certificate
    let tls_certificate = TlsCertificate::new(vec![cert]);

    // Connect to the WebSocket server with the custom certificate
    let socket = WebSocket::connect("wss://secure.websocket.server").secure(|cfg| {
        cfg.certificate(tls_certificate)
    })?;

    Ok(socket)
}

fn send_payment_with_retry(client: &GatewayClientModuleV2, invoice: Bolt11Invoice, max_delay: u64, max_fee: Amount, retries: u8) -> Result<[u8; 32], Cancelled> {
    let mut delay = Duration::from_millis(100);
    for _ in 0..retries {
        match client.send_payment(invoice.clone(), max_fee) {
            Ok(payment_hash) => return Ok(payment_hash),
            Err(err) if err.is_transient() => {
                println!("Transient error, retrying... {:?}", err);
                sleep(delay).await;
                delay = delay * 2;
                if delay.as_millis() > max_delay {
                    delay = Duration::from_millis(max_delay);
                }
            }
            Err(err) => return Err(err),
        }
    }
    Err(Cancelled)
}

