use std::collections::HashMap;

fn count_element_frequency<'a>(lists: &[&'a [&'a str]]) -> HashMap<&'a str, usize> {
    let mut frequency_map = HashMap::new();

    for list in lists {
        let mut permutator = Permutator::new(list);
        while let Some(permutation) = permutator.next() {
            for &element in permutation {
                *frequency_map.entry(element).or_insert(0) += 1;
            }
        }
    }

    frequency_map
}

