use crate::eip7702::EIP7702_MAGIC_BYTES;
use primitives::{Address, Bytes};

fn validate_eip7702(bytecode: &Bytes) -> Result<(), String> {
    // Check minimum length requirement (magic bytes + version + address)
    if bytecode.len() < 24 {
        return Err("Bytecode length is too short".to_string());
    }

    // Check magic bytes
    if &bytecode[0..EIP7702_MAGIC_BYTES.len()] != EIP7702_MAGIC_BYTES {
        return Err("Invalid magic bytes".to_string());
    }

    // Check version is 1
    if bytecode[20] != 1 {
        return Err("Invalid version".to_string());
    }

    // Extract the trailing 20 bytes as an address
    let address_bytes = &bytecode[bytecode.len() - 20..];
    let address = Address::from_slice(address_bytes);

    // Ensure the address is valid
    if address.is_zero() {
        return Err("Invalid address (zero address)".to_string());
    }

    Ok(())
}

