fn create_range_magnet_grabbable(
    parent: &impl SpatialRefAspect,
    transform: Transform,
    field: &Field,
    max_magnet_distance: f32,
) -> Result<Grabbable, NodeError> {
    let mut grabbable = Grabbable::new(
        parent,
        transform,
        field,
        GrabbableSettings {
            pointer_mode: PointerMode::Single(PointerMode::Single::Primary),
            ..Default::default()
        },
    )?;

    let magnet_flag = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
    let magnet_flag_clone = magnet_flag.clone();

    tokio::spawn(async move {
        let input_data = field.get_input_data();
        let mut pointer_pos = Vec3::ZERO;

        loop {
            tokio::select! {
                _ = tokio::time::sleep(tokio::time::Duration::from_millis(16)) => {
                    if let Some(input) = input_data.get::<InputDataType>() {
                        if let Some(pos) = input.pointer_position() {
                            pointer_pos = pos;
                        }
                    }

                    let grabbable_pos = grabbable.get_position();
                    let distance = (grabbable_pos - pointer_pos).length();

                    if distance < max_magnet_distance {
                        if !magnet_flag_clone.load(std::sync::atomic::Ordering::SeqCst) {
                            magnet_flag_clone.store(true, std::sync::atomic::Ordering::SeqCst);
                            grabbable.set_magnet(true);
                        }
                    } else {
                        if magnet_flag_clone.load(std::sync::atomic::Ordering::SeqCst) {
                            magnet_flag_clone.store(false, std::sync::atomic::Ordering::SeqCst);
                            grabbable.set_magnet(false);
                        }
                    }
                }
            }
        }
    });

    Ok(grabbable)
}

