use zvariant::{Value, OwnedValue, Type};

struct ExampleStruct<'a> {
    data: &'a str,
}

impl<'a> Type for ExampleStruct<'a> {
    const NAME: &'static str = "example.struct";
    type Owned = ExampleStruct<'static>;

    fn type_id() -> zvariant::Type {
        zvariant::Type::ObjectPath
    }

    fn owned(self) -> Self::Owned {
        ExampleStruct {
            data: self.data,
        }
    }

    fn into_value(self) -> Value {
        Value::new(self)
    }

    fn from_value(value: OwnedValue) -> Option<Self> {
        if let Value::ObjectPath(path) = value {
            if let Some(data) = path.to_str() {
                return Some(ExampleStruct { data });
            }
        }
        None
    }
}

fn example() {
    let data = "test";
    let struct_instance = ExampleStruct { data };
    let value: Value = struct_instance.into_value();
    let owned_value: OwnedValue = value.into();
    if let Some(recovered) = ExampleStruct::from_value(owned_value) {
        println!("Recovered data: {}", recovered.data);
    }
}

fn record_http_request_with_context(
    &self,
    method: http::Method,
    route: &str,
    client: Option<Client>,
    status_code: u16,
    cache_status: Option<String>,
    url_scheme: &str,
    listen_address: &std::net::SocketAddr,
    version: http::Version,
    has_graphql_errors: bool,
    duration: std::time::Duration,
) {
    let mut attributes = vec![
        KeyValue::new("http.response.status_code", status_code as i64),
        KeyValue::new("http.request.method", method.to_string()),
        KeyValue::new("http.route", route),
        KeyValue::new("url.scheme", url_scheme.to_string()),
        KeyValue::new("network.protocol.version", format!("{:?}", version)),
        KeyValue::new("server.address", listen_address.ip().to_string()),
        KeyValue::new("server.port", listen_address.port() as i64),
    ];

    if let Some(client) = client {
        attributes.push(KeyValue::new("http.headers.x-grafbase-client-name", client.name));

        if let Some(version) = client.version {
            attributes.push(KeyValue::new("http.headers.x-grafbase-client-version", version));
        }
    }

    if let Some(cache_status) = cache_status {
        attributes.push(KeyValue::new("http.response.headers.cache.status", cache_status));
    }

    if has_graphql_errors {
        attributes.push(KeyValue::new("graphql.response.has_errors", true));
    }

    self.latency.record(duration.as_millis() as u64, &attributes);
}

use dora_node_api::EventStream;
use dora_node_api::event::Event;
use dora_core::config::DataId;
use std::time::Duration;
use eyre::Result;

fn wait_for_input(
    stream: &mut EventStream,
    target_id: &DataId,
    timeout: Duration,
) -> Result<Option<Event>> {
    let mut remaining = timeout;
    let mut interval = Duration::from_millis(100);

    while remaining > Duration::ZERO {
        if let Some(event) = stream.poll() {
            if event.id() == target_id {
                return Ok(Some(event));
            }
        }

        std::thread::sleep(interval);
        remaining = Duration::from_millis(remaining.as_millis() as u64 - interval.as_millis() as u64);
    }

    Ok(None)
}

use crate::{MediaType, ProtocolTestFailure, try_json_eq, try_xml_equivalent, try_cbor_eq, urlencoded::try_url_encoded_form_equivalent};

fn validate_body_with_media_type(actual_body: &[u8], expected_body: &str, media_type: MediaType) -> Result<(), ProtocolTestFailure> {
    match media_type {
        MediaType::Json => {
            let expected_json = expected_body;
            let actual_json = std::str::from_utf8(actual_body)
                .map_err(|_| ProtocolTestFailure::InvalidUtf8)?;
            try_json_eq(expected_json, actual_json)
        },
        MediaType::Xml => {
            let expected_xml = expected_body;
            let actual_xml = std::str::from_utf8(actual_body)
                .map_err(|_| ProtocolTestFailure::InvalidUtf8)?;
            try_xml_equivalent(expected_xml, actual_xml)
        },
        MediaType::Cbor => {
            let expected_cbor = expected_body;
            let actual_cbor = std::str::from_utf8(actual_body)
                .map_err(|_| ProtocolTestFailure::InvalidUtf8)?;
            try_cbor_eq(expected_cbor, actual_cbor)
        },
        MediaType::UrlEncoded => {
            let expected_url_encoded = expected_body;
            let actual_url_encoded = std::str::from_utf8(actual_body)
                .map_err(|_| ProtocolTestFailure::InvalidUtf8)?;
            try_url_encoded_form_equivalent(expected_url_encoded, actual_url_encoded)
        },
        _ => Err(ProtocolTestFailure::UnsupportedMediaType),
    }
}

