use mnist::{Mnist, NormalizedMnist};

fn normalize_images(mnist: &Mnist) -> NormalizedMnist {
    let max_value = 255.0;
    let mut normalized_data = Vec::new();

    for image in &mnist.data {
        let mut normalized_image = Vec::new();
        for pixel in &image.pixel {
            normalized_image.push(*pixel / max_value);
        }
        normalized_data.push(normalized_image);
    }

    NormalizedMnist {
        data: normalized_data,
        label: mnist.label.clone(),
    }
}

