fn formatted_session_list(sessions: &Sessions) -> Vec<String> {
    let mut session_list = Vec::new();
    let max_length = sessions.values().map(|s| s.name.len()).max().unwrap_or(0);
    let mut headers = Vec::new();
    headers.push("SESSION".blue().bold());
    headers.push("WINDOW".blue().bold());
    headers.push("PID".blue().bold());
    headers.push("STATUS".blue().bold());
    headers.push("KEY".blue().bold());

    let header_line = headers.join(" | ");
    session_list.push(header_line);

    for (name, session) in sessions {
        let name_col = format!("{name: >max_length$}");
        let window_col = session.windows.iter().map(|w| w.name.clone()).collect::<Vec<_>>().join(", ");
        let pid_col = session.pid.to_string();
        let status_col = match session.status {
            "active" => "ACTIVE".green(),
            "inactive" => "INACTIVE".red(),
            _ => "UNKNOWN".yellow(),
        };
        let key_col = session.key
            .as_ref()
            .map(|k| k.to_string())
            .unwrap_or("N/A".dimmed());

        let row = format!(
            "{name_col} | {window_col} | {pid_col} | {status_col} | {key_col}"
        );
        session_list.push(row);
    }

    session_list
}

