use av_stream_info_rust::request::Request;

fn get_bitrate_and_codec(url: &str) -> Option<(u32, String)> {
    let response = Request::get(url).ok()?;
    let headers = response.headers();

    let bitrate_str = headers.get("icy-br").and_then(|s| s.to_str().ok());
    let codec = headers.get("icy-metaint").and_then(|s| s.to_str().ok()).and_then(|s| {
        if let Ok(value) = s.parse::<u32>() {
            let mut data = vec![0; value as usize];
            if let Ok(mut bytes) = response.bytes() {
                if bytes.len() >= data.len() {
                    data.copy_from_slice(&bytes[..data.len()]);
                }
            }
            if !data.is_empty() {
                let mut i = 0;
                while i < data.len() {
                    let length = data[i] as u32;
                    if i + length + 1 > data.len() {
                        break;
                    }
                    let start = i + 1;
                    let end = start + length as usize;
                    let metadata = &data[start..end];
                    if !metadata.is_empty() {
                        if let Ok(codec) = String::from_utf8(metadata.to_vec()) {
                            return Some(codec);
                        }
                    }
                    i += length as usize + 1;
                }
            }
        }
        None
    });

    let bitrate = bitrate_str.and_then(|s| s.parse::<u32>().ok());

    bitrate.zip(codec).map(|(b, c)| (b, c))
}

