use mdka::from_html;
use std::fs;
use std::io::{self, Read, Write};
use std::path::{Path, PathBuf};
use walkdir::WalkDir;

fn convert_html_files_to_markdown(
    directory_path: &str,
    output_directory: &str,
) -> Result<(), String> {
    if !Path::new(directory_path).exists() {
        return Err(format!("Directory does not exist: {}", directory_path));
    }

    let output_path = Path::new(output_directory);
    if !output_path.exists() {
        fs::create_dir_all(output_path).map_err(|e| format!("Failed to create output directory: {}", e))?;
    }

    for entry in WalkDir::new(directory_path) {
        let entry = entry.map_err(|e| format!("Error reading directory: {}", e))?;
        let path = entry.path();

        if path.is_file() && path.extension().map_or(false, |ext| ext.eq_ignore_ascii_case("html")) {
            let relative_path = path.strip_prefix(directory_path).map_err(|_| "Failed to get relative path".to_string())?;
            let output_path = output_path.join(relative_path);

            let mut input = fs::File::open(&path).map_err(|e| format!("Failed to open file: {}", e))?;
            let mut contents = Vec::new();
            input.read_to_end(&mut contents).map_err(|e| format!("Failed to read file: {}", e))?;

            let markdown_content = from_html(&String::from_utf8_lossy(&contents)).map_err(|e| format!("HTML to Markdown conversion failed: {}", e))?;

            let mut output = fs::File::create(&output_path).map_err(|e| format!("Failed to create output file: {}", e))?;
            output.write_all(markdown_content.as_bytes()).map_err(|e| format!("Failed to write to output file: {}", e))?;
        }
    }

    Ok(())
}

fn generate_wasm_enum_binding(name: &str, values: &[&str]) -> TokenStream {
    let name = Ident::new(name, Span::call_site());
    let variants = values.iter().map(|&variant| {
        let variant = Ident::new(variant, Span::call_site());
        let js_name = convert_case::to_case(Case::Camel, variant.to_string());
        quote! {
            #[wasm_bindgen(js_name = #js_name)]
            #variant
        }
    });

    quote! {
        #[wasm_bindgen]
        pub enum #name {
            #(#variants),*
        }
    }
}

