use rfc2047_decoder::{Decoder, Error, RecoverStrategy};

fn decode_header_batch(headers: &[&[u8]]) -> Result<Vec<(String, String)>, Error> {
    let mut result = Vec::new();
    for &header in headers {
        let decoded = Decoder::new()
            .recover_strategy(RecoverStrategy::SkipLongEncodedWords)
            .decode(header)
            .map_err(|e| Error::DecodingError(e.to_string()))?;
        if let Some((key, value)) = decoded.split_once('\x00') {
            result.push((key.to_string(), value.to_string()));
        }
    }
    Ok(result)
}

