use import_map::ImportMap;
use url::Url;

fn merge_import_maps(base_url: Url, maps: Vec<ImportMap>) -> ImportMap {
    let mut merged = ImportMap::new();
    let mut seen = std::collections::HashSet::new();

    for map in maps {
        for (key, value) in map {
            let key = key.to_string();
            let value = value.to_string();
            let normalized_key = normalize_key(&key, &base_url);
            let normalized_value = normalize_value(&value, &base_url);

            if !seen.contains(&normalized_key) {
                merged.insert(normalized_key, normalized_value);
                seen.insert(normalized_key);
            }
        }
    }

    merged
}

fn normalize_key(key: &str, base_url: &Url) -> String {
    if key.starts_with('/') {
        return key.to_string();
    }

    let mut url = base_url.clone();
    url.set_path(key);
    url.set_query(None);
    url.set_fragment(None);
    url.to_string()
}

fn normalize_value(value: &str, base_url: &Url) -> String {
    if value.starts_with('/') {
        let mut url = base_url.clone();
        url.set_path(value);
        url.set_query(None);
        url.set_fragment(None);
        return url.to_string();
    }

    if let Ok(url) = Url::parse(value) {
        return url.to_string();
    }

    value.to_string()
}

