use chrono::{NaiveDate, Weekday};
use chronoutil::{RelativeDuration, shift_months};

fn generate_billing_dates(start: NaiveDate, count: usize) -> Vec<NaiveDate> {
    let mut dates = Vec::new();
    let mut current = start;

    for _ in 0..count {
        // Move to the 15th of the current month
        let month_15 = shift_months(current, -current.day() + 15);
        let day_15 = month_15.day();

        // Check if the 15th is a Saturday or Sunday
        let weekday = month_15.weekday();
        let adjusted_date = match weekday {
            Weekday::Sat => month_15.succing_days(2), // Move to Monday
            Weekday::Sun => month_15.succing_days(1), // Move to Monday
            _ => month_15,
        };

        dates.push(adjusted_date);
        current = adjusted_date.succing_months(1);
    }

    dates
}

