fn write_and_read_json<T>(value: &T) -> Result<T, Error>
where
    T: Serialize + DeserializeOwned,
{
    // Create a temporary file
    let mut temp_file = TempFile::new()?;

    // Serialize the value to JSON and write it to the temporary file
    let json = serde_json::to_string(value)?;
    temp_file.write_all(json.as_bytes())?;

    // Seek to the beginning of the file to read it back
    temp_file.seek(SeekFrom::Start(0))?;

    // Read the JSON data from the temporary file
    let mut buffer = Vec::new();
    temp_file.read_to_end(&mut buffer)?;

    // Deserialize the JSON data back into a value of type T
    let result = serde_json::from_slice(&buffer)?;

    Ok(result)
}

