) -> Result<(), PubsubClientError> {
    let subscription = client.subscribe("slot-update")?;

    println!("Subscribed to slot updates. Listening...");

    let mut stream = subscription.stream();

    while let Some(Ok(SlotUpdate { slot, timestamp })) = stream.next().await {
        let current_time = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("Time went backwards");

        let latency = current_time.as_nanos() as u64 - timestamp.as_nanos() as u64;

        println!(
            "Slot {} received. Latency: {} nanoseconds",
            slot, latency
        );
    }

    Ok(())
}

fn path_to_points(path: *mut cairo_path_t) -> Vec<(f64, f64)> {
    unsafe {
        let mut points = Vec::new();
        let mut data = std::ptr::null_mut();
        let mut n_data = 0;

        // Assuming we have a way to get the path data, this is a placeholder
        // In real usage, you would use cairo_path_get_data and related functions
        // For the sake of this example, we assume data and n_data are valid
        // and that the data is in the correct format.

        // In a real scenario, you would call cairo_path_get_data and handle the data accordingly
        // For this example, we'll simulate the data structure

        let mut current_data = data;
        let mut num_elements = n_data;

        while num_elements > 0 {
            let header = &(*current_data).header;
            let data_type = header.data_type;
            let length = header.length;

            match data_type {
                PATH_DATA_TYPE_MOVE_TO => {
                    let point = &(*current_data).point;
                    points.push((point[0], point[1]));
                }
                PATH_DATA_TYPE_LINE_TO => {
                    let point = &(*current_data).point;
                    points.push((point[0], point[1]));
                }
                PATH_DATA_TYPE_CURVE_TO => {
                    // Curve_to has 6 points (x1, y1, x2, y2, x3, y3)
                    // We need to extract these points
                    let curve_data = &(*current_data).point;
                    points.push((curve_data[0], curve_data[1])); // x1, y1
                    points.push((curve_data[2], curve_data[3])); // x2, y2
                    points.push((curve_data[4], curve_data[5])); // x3, y3
                }
                _ => {}
            }

            current_data = current_data.offset(length as isize);
            num_elements -= length;
        }

        points
    }
}

use css_color_parser::Color;

fn contrast_ratio(c1: Color, c2: Color) -> f32 {
    let (l1, l2) = (relative_luminance(c1), relative_luminance(c2));
    let contrast = (l1 + 0.05) / (l2 + 0.05);
    contrast.max(1.0)
}

fn relative_luminance(color: Color) -> f32 {
    let rgb = color.into_rgb();
    let r = rgb.0 / 255.0;
    let g = rgb.1 / 255.0;
    let b = rgb.2 / 255.0;

    let r = if r <= 0.03928 { r / 12.92 } else { ((r + 0.055) / 1.055).powf(2.4) };
    let g = if g <= 0.03928 { g / 12.92 } else { ((g + 0.055) / 1.055).powf(2.4) };
    let b = if b <= 0.03928 { b / 12.92 } else { ((b + 0.055) / 1.055).powf(2.4) };

    0.05 * r + 0.45 * g + 0.26 * b
}

