use stubborn_io::{ReconnectOptions, StubbornTcpStream};
use std::time::Duration;
use tokio::io::AsyncWriteExt;
use log::{info, warn, error};

fn create_logged_stream(addr: &str) -> std::io::Result<StubbornTcpStream<&str>> {
    let reconnect_options = ReconnectOptions::new(Duration::from_secs(5), 3);
    let stream = StubbornTcpStream::connect(addr, reconnect_options)
        .map(|stream| {
            info!("Connected to {}", addr);
            stream
        })
        .map_err(|e| {
            error!("Failed to connect to {}: {}", addr, e);
            e
        });

    stream
}

fn send_logged_message(stream: &mut StubbornTcpStream<&str>, message: &str) -> std::io::Result<()> {
    let mut buffer = Vec::new();
    buffer.extend_from_slice(message.as_bytes());
    buffer.push(b'\n');
    stream.write_all(&buffer)
        .map(|_| {
            stream.flush().expect("Failed to flush");
            info!("Sent message: {}", message);
            Ok(())
        })
        .map_err(|e| {
            warn!("Failed to send message: {}", e);
            Err(e)
        })
}

use crate::parser::{self, GrammarItem, ParseError};

fn extract_params(doxygen: &str) -> Result<Vec<(String, String)>, crate::parser::ParseError> {
    let mut params = Vec::new();
    let lines: Vec<&str> = doxygen.lines().collect();
    let mut in_param_block = false;
    let mut current_param = String::new();
    let mut current_desc = String::new();

    for line in &lines {
        if line.trim().starts_with("@param") {
            in_param_block = true;
            current_param = line.trim().split('@').nth(1).unwrap_or("").trim().to_string();
            current_desc = String::new();
        } else if in_param_block && line.trim().starts_with('@') {
            if !current_param.is_empty() && !current_desc.is_empty() {
                params.push((current_param, current_desc));
                current_param = String::new();
                current_desc = String::new();
            }
        } else if in_param_block {
            current_desc.push_str(line);
            current_desc.push('\n');
        } else if line.trim().starts_with("@end") {
            in_param_block = false;
        }
    }

    if !current_param.is_empty() && !current_desc.is_empty() {
        params.push((current_param, current_desc));
    }

    Ok(params)
}

