fn find_nodes_with_python_operators(descriptor: &Descriptor) -> impl Iterator<Item = &Node> {
    descriptor.nodes.iter().filter(|node| {
        if let Some(operators) = &node.operators {
            operators.iter().any(|op| {
                if let Some(config) = &op.config {
                    if let OperatorSource::Python(PythonSource::Script(_)) = &config.source {
                        return true;
                    }
                }
                false
            })
        } else if let Some(operator) = &node.operator {
            if let OperatorSource::Python(PythonSource::Script(_)) = &operator.source {
                return true;
            }
        }
        false
    })
}

