use glob::glob;
use crate::Error;
use crate::rerun_if_changed;

fn rerun_if_changed_files(pattern: &str) -> Result<(), Error> {
    let mut paths = Vec::new();
    for entry in glob(pattern).map_err(|e| Error::GlobError(e.to_string()))? {
        let path = entry.map_err(|e| Error::GlobError(e.to_string()))?;
        if path.is_dir() {
            return Err(Error::ExpandedPathExpectedFile(path.path().to_path_buf()));
        }
        paths.push(path.path().to_path_buf());
    }
    rerun_if_changed(&paths)
}

use crate::api::ApiError;
use crate::ffi::check_wasm_toolchain_version;
use axum::extract::multipart::Multipart;
use fuel_indexer_database::types::IndexerAssetType;
use std::str::FromStr;
use tracing::warn;

fn parse_register_indexer_multipart(
    mut multipart: Multipart,
) -> ApiResult<(String, bool, Vec<(IndexerAssetType, Vec<u8>)>)> {
    let mut wasm_module = None;
    let mut manifest = None;
    let mut graphql_schema = None;
    let mut replace = false;

    while let Some(field) = multipart.next_field() {
        let field = field?;
        let name = field.name().ok_or(ApiError::MissingFormField)?;
        let value = field.bytes().map_err(|e| ApiError::MultipartError(e.to_string()))?;

        match name {
            "wasm_module" => {
                if wasm_module.is_some() {
                    return Err(ApiError::DuplicateFormField);
                }
                wasm_module = Some(value);
            }
            "manifest" => {
                if manifest.is_some() {
                    return Err(ApiError::DuplicateFormField);
                }
                manifest = Some(value);
            }
            "graphql_schema" => {
                if graphql_schema.is_some() {
                    return Err(ApiError::DuplicateFormField);
                }
                graphql_schema = Some(value);
            }
            "replace" => {
                if replace {
                    return Err(ApiError::DuplicateFormField);
                }
                let replace_str = std::str::from_utf8(&value)
                    .map_err(|e| ApiError::MultipartError(e.to_string()))?;
                replace = bool::from_str(replace_str).map_err(|e| ApiError::InvalidValue {
                    field: "replace".to_string(),
                    message: e.to_string(),
                })?;
            }
            _ => {
                warn!("Unexpected form field: {}", name);
            }
        }
    }

    let wasm_module = wasm_module.ok_or(ApiError::MissingFormField)?;
    let manifest = manifest.ok_or(ApiError::MissingFormField)?;
    let graphql_schema = graphql_schema.ok_or(ApiError::MissingFormField)?;

    let toolchain_version = check_wasm_toolchain_version(&wasm_module)
        .map_err(|e| ApiError::InvalidWasmModule { message: e })?;

    let assets = vec![
        (IndexerAssetType::WasmModule, wasm_module),
        (IndexerAssetType::Manifest, manifest),
        (IndexerAssetType::GraphQLSchema, graphql_schema),
    ];

    Ok((toolchain_version, replace, assets))
}

use std::net::IpAddr;
use std::time::Duration;
use std::sync::Arc;
use std::thread::sleep;
use ping_rs::{send_ping_async, PingOptions, PingReply, PingError};

fn ping_with_retry(addr: &IpAddr, timeout: Duration, data: Arc<&[u8]>, options: Option<&PingOptions>, max_retries: u32) -> Result<PingReply, PingError> {
    let mut retries = 0;
    let mut backoff = Duration::from_millis(100);

    loop {
        retries += 1;
        if retries > max_retries {
            return Err(PingError::TooManyRetries);
        }

        match send_ping_async(addr, timeout, data.clone(), options) {
            Ok(reply) => {
                return Ok(reply);
            }
            Err(e) => {
                if retries == max_retries {
                    return Err(e);
                }
                sleep(backoff);
                backoff = backoff * 2;
            }
        }
    }
}

