use crate::bindings::{WebTransportHash, WebTransportOptions};
use crate::Error;
use js_sys::{Array, Uint8Array};

fn build_options_from_hashes(hashes: &[&[u8]]) -> Result<WebTransportOptions, Error> {
    let mut web_transport_options = WebTransportOptions::new();
    let mut hash_array = Array::new();

    for &hash_bytes in hashes {
        if hash_bytes.len() != 32 {
            return Err(Error::InvalidHashLength);
        }

        let uint8_array = Uint8Array::new_with_length(32);
        uint8_array.set(Uint8Array::new_with_length(32), hash_bytes);
        let hash = WebTransportHash::new_with_array(&uint8_array);
        hash_array.push(&hash);
    }

    web_transport_options.set_hashes(hash_array);
    Ok(web_transport_options)
}

use std::path::Path;
use toml_edit::Document;
use toml_edit::value;

fn bump_workspace_versions(root_manifest: &Path, new_version: &str) -> Result<(), Box<dyn std::error::Error>> {
    let mut root_toml = Document::load(root_manifest)?;
    let workspace = root_toml["workspace"].as_table_mut().ok_or("Root manifest does not have a workspace section")?;

    // Bump root manifest version
    if let Some(version) = root_toml["package"].as_table_mut().and_then(|p| p.get("version")) {
        version.set(new_version);
    } else {
        return Err("Root manifest does not have a package section with version".into());
    }

    // Find all member crates
    let member_crates = workspace.get("members").and_then(|v| v.as_array()).unwrap_or(&[]);

    for member in member_crates {
        let crate_path = root_manifest.parent().unwrap().join(member.as_str().unwrap());
        let mut crate_toml = Document::load(&crate_path)?;
        if let Some(version) = crate_toml["package"].as_table_mut().and_then(|p| p.get("version")) {
            version.set(new_version);
        } else {
            return Err(format!("Member crate {} does not have a package section with version", crate_path.display()).into());
        }
        crate_toml.save(&crate_path)?;
    }

    root_toml.save(root_manifest)?;
    Ok(())
}

