fn infer_schema_limited<R: std::io::Read>(reader: &mut R, max_bytes: usize) -> datafusion_common::Result<arrow::datatypes::Schema> {
    let mut buffer = vec![];
    let mut read_bytes = 0;

    // Read up to max_bytes or until EOF
    loop {
        let mut chunk = vec![0; 1024];
        let bytes_read = reader.read(&mut chunk)?;
        if bytes_read == 0 {
            break;
        }
        buffer.extend_from_slice(&chunk[..bytes_read]);
        read_bytes += bytes_read;
        if read_bytes >= max_bytes {
            break;
        }
    }

    // Create a cursor from the captured buffer
    let cursor = Cursor::new(buffer);
    let schema = read_avro_schema_from_reader(cursor)?;
    Ok(schema)
}

