use ckb_shared::Shared;
use ckb_app_config::ExitCode;

fn total_uncles_between(shared: &Shared, from: u64, to: u64) -> Result<u64, ExitCode> {
    if from > to {
        return Err(ExitCode::Error);
    }

    let mut total = 0;
    let mut current = from;

    while current <= to {
        if let Ok(block) = shared.get_block_by_number(current) {
            if let Some(extension) = block.extension() {
                if let Some(uncles_count) = extension.uncles_count() {
                    total += uncles_count;
                }
            }
        } else {
            return Err(ExitCode::Error);
        }
        current += 1;
    }

    Ok(total)
}

fn sha256_hash(args: &[ColumnarValue]) -> Result<ColumnarValue, DataFusionError> {
    if args.len() != 1 {
        return Err(DataFusionError::Plan("SHA256_HASH requires exactly one argument".to_string()));
    }

    let arg = &args[0];
    let batch = arg.columnar_batch()?;
    let data_type = arg.data_type();

    // Ensure the data type is binary
    if data_type != &datafusion_common::DataType::Binary {
        return Err(DataFusionError::Plan("SHA256_HASH expects a binary column".to_string()));
    }

    let num_rows = batch.num_rows();
    let mut result = vec![ScalarValue::Null; num_rows];

    for i in 0..num_rows {
        if let Some(value) = batch.column(0).get(i) {
            if let ScalarValue::Binary(b) = value {
                if let Ok(hash) = sha2(b.as_bytes(), 256) {
                    result[i] = ScalarValue::Binary(hash);
                }
            }
        }
    }

    Ok(ColumnarValue::new(
        Arc::new(datafusion_common::DataType::Binary),
        Arc::new(datafusion_common::ArrayRef::new(result.into())),
    ))
}

use solana_tpu_client::tpu_client::TpuClient;
use solana_transaction::Transaction;
use solana_transaction_error::TransportResult;
use solana_connection_cache::connection_cache::{ConnectionPool, ConnectionManager, NewConnectionConfig};
use std::time::Duration;
use tokio::time::sleep;
use bincode;

fn send_batch_with_backoff<P, M, C>(client: &TpuClient<P, M, C>, transactions: &[Transaction>) -> TransportResult<()>
where
    P: ConnectionPool<NewConnectionConfig = C>,
    M: ConnectionManager<ConnectionPool = P, NewConnectionConfig = C>,
    C: NewConnectionConfig,
{
    let mut attempts = 0;
    let max_attempts = 5;
    let mut delay = Duration::from_secs(1);

    loop {
        let result = client.send_transactions(transactions);
        match result {
            Ok(_) => {
                return Ok(());
            }
            Err(e) => {
                attempts += 1;
                if attempts >= max_attempts {
                    return Err(e);
                }
                sleep(delay).await;
                delay *= 2;
            }
        }
    }
}

