use libp2p_tls::certificate;
use libp2p_identity::PeerId;
use rustls::SignatureScheme;
use rustls::pki_types::CertificateDer;

fn validate_certificate(
    cert: &CertificateDer,
    expected_peer: &PeerId,
) -> Result<(), certificate::ParseError> {
    let certificate = certificate::parse(cert)?;
    let subject = certificate.subject();
    let peer_id = PeerId::from_bytes(&subject);

    if peer_id != *expected_peer {
        return Err(certificate::ParseError::InvalidPeerId);
    }

    let supported_schemes = vec![
        SignatureScheme::RSA_PKCS1v15_SHA256,
        SignatureScheme::RSA_PKCS1v15_SHA384,
        SignatureScheme::RSA_PKCS1v15_SHA512,
        SignatureScheme::RSA_PSS_SHA256,
        SignatureScheme::RSA_PSS_SHA384,
        SignatureScheme::RSA_PSS_SHA512,
        SignatureScheme::ECDSA_P256_SHA256,
        SignatureScheme::ECDSA_P384_SHA384,
        SignatureScheme::ED25519,
    ];

    let signature_scheme = certificate.signature_scheme();
    if !supported_schemes.contains(&signature_scheme) {
        return Err(certificate::ParseError::UnsupportedSignatureScheme);
    }

    Ok(())
}

use c3p0::*;
use c3p0::postgres::tokio_postgres::Row;

fn ensure_age_column(conn: &C3p0Impl, table: &str) -> Result<(), C3p0Error> {
    // Query to check if the column exists
    let column_exists_sql = format!(
        "SELECT column_name FROM information_schema.columns \
         WHERE table_name = '{}' AND column_name = 'age'",
        table
    );

    // Execute the query to check for column existence
    let mut stmt = conn.prep(column_exists_sql)?;
    let mut row = stmt.query(&[])?;

    // Check if the column exists
    let exists = row.get(0).map_or(false, |v| v != "");

    if !exists {
        // Column does not exist, perform the ALTER TABLE
        let alter_sql = format!(
            "ALTER TABLE {} ADD COLUMN age INTEGER NULL",
            table
        );
        conn.exec(&alter_sql, &[])?;
    }

    Ok(())
}

fn validate_outgoing_contract(
