}

use shaderc::{IncludeType, ResolvedInclude};
use std::path::{Path, PathBuf};
use std::fs;
use std::env;

fn custom_include_resolver(name: &str, include_type: IncludeType, requesting_file: &str, depth: usize) -> Result<ResolvedInclude, String> {
    let base_path = Path::new(requesting_file).parent().ok_or("Invalid requesting file path")?;
    let include_path = match include_type {
        IncludeType::Relative => base_path.join(name),
        IncludeType::Standard => {
            let include_dir = env::var("SHADER_INCLUDE_PATH")
                .map_err(|_| "Missing SHADER_INCLUDE_PATH env var")?;
            PathBuf::from(include_dir).join(name)
        }
    };
    let content = fs::read_to_string(&include_path).map_err(|e| e.to_string())?;
    Ok(ResolvedInclude {
        resolved_name: include_path.to_string_lossy().into_owned(),
        content,
    })
}

fn json_dates_to_variant(date_strings: &[&str]) -> Result<Variant<'static, 'static>, ArrowError> {
