            .map_err(|e| ArrowError::InvalidArgumentError(format!("Invalid date string: {}", e)))?;
        builder.push_date(date.and_time(NaiveTime::default()));
    }
    Ok(builder.build())
}

use std::collections::HashSet;
use libp2p_core::Multiaddr;
use libp2p_swarm::ConnectionId;
use libp2p_core::multiaddr::Protocol;

fn is_quic_addr(addr: &Multiaddr, v1: bool) -> bool {
    use Protocol::*;
    let mut iter = addr.iter();
    let Some(first) = iter.next() else { return false; };
    let Some(second) = iter.next() else { return false; };
    let Some(third) = iter.next() else { return false; };
    let fourth = iter.next();
    let fifth = iter.next();
    matches!(first, Ip4(_) | Ip6(_) | Dns(_) | Dns4(_) | Dns6(_))
        && matches!(second, Udp(_))
        && if v1 { matches!(third, QuicV1) } else { matches!(third, Quic) }
        && matches!(fourth, Some(P2p(_)) | None)
        && fifth.is_none()
}

fn is_tcp_addr(addr: &Multiaddr) -> bool {
    use Protocol::*;
    let mut iter = addr.iter();
    let Some(first) = iter.next() else { return false; };
    let Some(second) = iter.next() else { return false; };
    matches!(first, Ip4(_) | Ip6(_) | Dns(_) | Dns4(_) | Dns6(_)) && matches!(second, Tcp(_))
}

fn translate_observed_address(connection_id: ConnectionId, observed: &Multiaddr, listen_addrs: &HashSet<Multiaddr>) -> Vec<Multiaddr> {
    let mut result = HashSet::new();
    let mut seen = HashSet::new();

    for listen_addr in listen_addrs {
        let mut iter = listen_addr.iter();
        let Some(first) = iter.next() else { continue; };
        let Some(second) = iter.next() else { continue; };
        let Some(third) = iter.next() else { continue; };
        let fourth = iter.next();
        let fifth = iter.next();

        if matches!(first, Ip4(_) | Ip6(_) | Dns(_) | Dns4(_) | Dns6(_)) {
            if matches!(second, Tcp(_)) {
                if is_tcp_addr(observed) {
                    let mut new_addr = listen_addr.clone();
                    if let Some(p2p) = observed.iter().find(|p| matches!(p, Protocol::P2p(_))) {
                        if let Some(p2p) = new_addr.iter().find(|p| matches!(p, Protocol::P2p(_))) {
                            *p2p = p2p.clone();
                        }
                    }
                    result.insert(new_addr);
                }
            } else if matches!(second, Udp(_)) {
                let v1 = match third {
                    Protocol::QuicV1 => true,
                    Protocol::Quic => false,
                    _ => continue,
                };
                if is_quic_addr(observed, v1) {
                    let mut new_addr = listen_addr.clone();
                    if let Some(p2p) = observed.iter().find(|p| matches!(p, Protocol::P2p(_))) {
                        if let Some(p2p) = new_addr.iter().find(|p| matches!(p, Protocol::P2p(_))) {
                            *p2p = p2p.clone();
                        }
                    }
                    result.insert(new_addr);
                }
            }
        }
    }

    result.into_iter().collect()
}

