fn generate_script_with_subtitle(video_path: &Path, subtitle_path: &Path) -> Result<(), String> {
    // Create a new AviSynth script
    let mut script = Script::new();

    // Add the video source
    let video = Video::new(video_path).map_err(|e| e.to_string())?;
    script.add_video(video);

    // Add the subtitle filter
    let subtitle = Subtitle::new(subtitle_path).map_err(|e| e.to_string())?;
    let text_sub = TextSub::new(subtitle);
    script.add_filter(text_sub);

    // Write the AviSynth script to a file
    let avs_path = video_path.with_extension("avs");
    let mut writer = AvisynthWriter::new(avs_path, AvsOptions::default());
    writer.write_script(&script).map_err(|e| e.to_string())?;

    Ok(())
}

