fn cleanup_temporary_files() -> Result<u32, io::Error> {
    let path = Path::new(".");
    let entries = fs::read_dir(path)?;

    let mut count = 0;
    for entry in entries {
        let entry = entry?;
        let file_name = entry.file_name();
        let file_name_str = file_name.to_str().ok_or(io::Error::new(io::ErrorKind::InvalidData, "Invalid filename"))?;

        if file_name_str.starts_with('.') && file_name_str.len() > 1 {
            let file_path = entry.path();
            if file_path.is_file() {
                fs::remove_file(&file_path)?;
                count += 1;
            }
        }
    }

    Ok(count)
}

fn calculate_upgrade_fee(current_limit: u32, new_limit: u32) -> u128 {
    if new_limit <= current_limit {
        return 0;
    }

    let increment = new_limit.saturating_sub(current_limit);
    let increments_of_1000 = (increment + 999) / 1000;

    let fee = increments_of_1000 as u128 * PRICE_PER_1000_MEMBERS;

    fee
}

fn record_user_activity_diff(user: &mut User, diff: &UserActivityDiff) {
    // Process removed activities
    for activity in &diff.removed {
        user.activities.remove(activity);
    }

    // Process altered activities
    for (activity, activity_diff) in &diff.altered {
        if let Some(existing) = user.activities.get_mut(activity) {
            existing.count = activity_diff.count;
        } else {
            // If the activity is not present, it's considered a new entry
            let new_activity = UserActivity {
                count: activity_diff.count,
            };
            user.activities.insert(activity.clone(), new_activity);
        }
    }
}

