use eip4844::constants::BYTES_PER_BLOB;
use serialization::types::BlobRef;
use hex::FromHex;

fn blob_from_hex(hex_str: &str) -> Result<BlobRef<'static>, String> {
    // Check if the hex string length is even
    if hex_str.len() % 2 != 0 {
        return Err("Hex string length must be even".to_string());
    }

    // Decode the hex string into bytes
    let bytes = hex::from_hex(hex_str)
        .map_err(|_| "Invalid hex string".to_string())?;

    // Validate the length against the expected blob size
    if bytes.len() != BYTES_PER_BLOB {
        return Err(format!("Hex string length {} does not match expected blob size {}", hex_str.len(), BYTES_PER_BLOB));
    }

    // Create a BlobRef from the bytes
    Ok(unsafe { BlobRef::new(bytes.as_ptr() as *const [u8; BYTES_PER_BLOB], std::mem::size_of::<[u8; BYTES_PER_BLOB]>() as usize) })
}

use permutate::{Permutator, PermutatorWrapper as _};

fn filter_permutations<'a>(lists: &[&'a [&'a str]]) -> Vec<Vec<&'a str>> {
    let mut result = Vec::new();
    let mut permutator = Permutator::new(lists);

    while let Some(mut permutation) = permutator.next() {
        if permutation.iter().any(|&s| s.contains('5')) {
            result.push(permutation);
        }
    }

    result
}

use crate::{uinput_setup, uinput_abs_setup, ui_dev_setup, ui_set_keybit, ui_set_absbit, ui_abs_setup, ui_dev_create, input_id, input_absinfo, UINPUT_MAX_NAME_SIZE};
use libc::{c_int, c_char};
use nix::Result;

fn create_uinput_device(fd: c_int, name: &str, keys: &[c_int], abs_axes: &[(c_int, input_absinfo)]) -> Result<c_int> {
    let mut uinput = uinput_setup();
    let mut ui_dev = ui_dev_setup();

    // Set device name
    let name_bytes = name.as_bytes();
    if name_bytes.len() > UINPUT_MAX_NAME_SIZE {
        return Err(nix::Error::from_raw_errno(libc::ENAMETOOLONG));
    }
    unsafe {
        std::ptr::copy_nonoverlapping(name_bytes.as_ptr() as *const c_char, uinput.name.as_mut_ptr(), name_bytes.len());
        uinput.name[name_bytes.len() as usize] = 0;
    }

    // Set input ID
    ui_dev.id.bustype = input_id::BUS_USB as _;
    ui_dev.id.vendor = 0x1234;
    ui_dev.id.product = 0x5678;
    ui_dev.id.version = 1;

    // Enable key capabilities
    for &key in keys {
        ui_set_keybit(&mut uinput, key);
    }

    // Enable absolute axes
    for &(axis, info) in abs_axes {
        ui_set_absbit(&mut uinput, axis);
        uinput_abs_setup(&mut uinput, axis, info);
    }

    // Create the device
    let new_fd = unsafe { libc::open("/dev/uinput", libc::O_WRONLY | libc::O_NONBLOCK) };
    if new_fd < 0 {
        return Err(nix::Error::from_raw_errno(errno()));
    }

    // Write the device setup
    unsafe {
        if libc::ioctl(new_fd, libc::UI_SET_EVBIT, libc::EV_KEY as _) != 0 {
            return Err(nix::Error::from_raw_errno(errno()));
        }
        for &key in keys {
            if libc::ioctl(new_fd, libc::UI_SET_KEYBIT, key as _) != 0 {
                return Err(nix::Error::from_raw_errno(errno()));
            }
        }
        for &(axis, info) in abs_axes {
            if libc::ioctl(new_fd, libc::UI_SET_ABSBIT, axis as _) != 0 {
                return Err(nix::Error::from_raw_errno(errno()));
            }
            if libc::ioctl(new_fd, libc::UI_ABS_SETUP, &info as *const _) != 0 {
                return Err(nix::Error::from_raw_errno(errno()));
            }
        }
        if libc::ioctl(new_fd, libc::UI_DEV_SETUP, &ui_dev as *const _) != 0 {
            return Err(nix::Error::from_raw_errno(errno()));
        }
        if libc::ioctl(new_fd, libc::UI_DEV_CREATE, 0 as _) != 0 {
            return Err(nix::Error::from_raw_errno(errno()));
        }
    }

    Ok(new_fd)
}

fn read_all_pending<B, RS, WS>(
    port: &mut SerialPort<'_, B, RS, WS>,
    out: &mut [u8],
) -> Result<usize, UsbError>
where
    B: UsbBus,
    RS: BorrowMut<[u8]>,
    WS: BorrowMut<[u8]>,
{
    let mut total = 0;
    let mut offset = 0;

    while offset < out.len() {
        let remaining = out.len() - offset;
        let n = port.read(&mut out[offset..offset + remaining])?;

        if n == 0 {
            break;
        }

        total += n;
        offset += n;
    }

    Ok(total)
}

fn safe_g1_msm(points: &[G1Point], scalars: &[Scalar]) -> Option<G1Projective> {
    if points.len() != scalars.len() {
        return None;
    }

    let mut non_zero_points = Vec::new();
    let mut non_zero_scalars = Vec::new();

    for (&point, &scalar) in points.iter().zip(scalars.iter()) {
        if scalar.is_zero() {
            continue;
        }
        non_zero_points.push(point);
        non_zero_scalars.push(scalar);
    }

    if non_zero_points.is_empty() {
        return Some(G1Projective::identity());
    }

    g1_lincomb(&non_zero_points, &non_zero_scalars)
}

fn aggregate_component_statuses(status: &Status) -> std::collections::HashMap<String, StatusType> {
    let mut component_statuses = HashMap::new();
    walk_status(status, &mut |component_status| {
        if let Some(name) = &component_status.name {
            if let Some(status_type) = &component_status.status {
                *component_statuses.entry(name.clone()).or_insert(StatusType::default()) += status_type.clone();
            }
        }
    });
    component_statuses
}

fn walk_status(status: &Status, f: &mut dyn FnMut(&ComponentStatus)) {
    f(status);
    for component in &status.components {
        walk_status(component, f);
    }
}

fn log_secret_access(
    nats_client: &Client,
    audit_client: &Client,
    encryption_xkey: &XKey,
    secret_bucket: &str,
    audit_bucket: &str,
    request: &SecretRequest,
) -> anyhow::Result<()> {
    let timestamp = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0);

    let audit_log_entry = AuditLogEntry {
        timestamp,
        entity: request.entity.clone(),
        secret_key: request.secret_key.clone(),
        secret_value: request.secret_value.clone(),
    };

    let audit_log_entry_bytes = serde_json::to_vec(&audit_log_entry).unwrap();

    let mut jetstream = nats_client.jetstream().unwrap();
    let subject = format!("audit.{}", audit_bucket);

    let mut msg = jetstream
        .publish(subject.as_str(), audit_log_entry_bytes)
        .await
        .map_err(|e| anyhow::anyhow!("Failed to publish audit log: {}", e))?;

    msg.reply_to = Some(format!("audit.reply.{}", audit_bucket));
    msg.headers = Some(serde_json::json!({
        "encryption_xkey": encryption_xkey.to_string(),
        "secret_bucket": secret_bucket.to_string(),
        "audit_bucket": audit_bucket.to_string(),
    }));

    msg.await?;

    Ok(())
}

