use async_graphql_parser::{self as agp, types as ast};

fn deprecated_required_arguments(sdl: &str) -> Vec<String> {
    let schema = agp::parse_schema(sdl).expect("Failed to parse SDL");
    let mut violations = Vec::new();

    for type_def in schema.definitions.iter() {
        if let ast::Definition::Object(obj) = type_def {
            for field in &obj.fields {
                if let Some(args) = &field.arguments {
                    for arg in args {
                        if arg.is_non_null() && arg.is_deprecated() {
                            violations.push(format!("Field: {}.{} has a non-null argument marked as deprecated", obj.name, field.name));
                        }
                    }
                }
            }
        }
    }

    violations
}

