fn calculate_effective_mint_price(deps: Deps, is_admin: bool, user_addr: &Addr) -> Result<Coin, ContractError> {
    // Check if the user is an admin
    if is_admin {
        // Admin gets the airdrop price
        let airdrop_price = CONFIG.load(deps.storage).unwrap().airdrop_price;
        return Ok(airdrop_price);
    }

    // Query the whitelist configuration
    let whitelist_config: WhitelistConfigResponse = deps
        .querier
        .query(&QueryRequest::CosmosQuery {
            path: vec![],
            msg: to_vec(&WhitelistQueryMsg::Config {}).unwrap(),
        })
        .map_err(|e| ContractError::QueryError(e.to_string()))?;

    // Check if the user is in the whitelist
    let is_whitelisted = whitelist_config
        .whitelist
        .iter()
        .any(|addr| addr == user_addr);

    if is_whitelisted {
        // Whitelisted users get the whitelist price
        let whitelist_price = CONFIG.load(deps.storage).unwrap().whitelist_price;
        return Ok(whitelist_price);
    }

    // Query the discount price if applicable
    let discount_price = match CONFIG.load(deps.storage).unwrap().discount_price {
        Some(price) => price,
        None => return Err(ContractError::NoDiscountPrice),
    };

    // Check if the user is eligible for a discount
    let is_discount_eligible = match CONFIG.load(deps.storage).unwrap().discount_eligibility {
        Some(conditions) => {
            // Placeholder logic for checking discount eligibility
            // In a real implementation, this would check user-specific conditions
            conditions.contains(user_addr)
        }
        None => false,
    };

    if is_discount_eligible {
        return Ok(discount_price);
    }

    // Default to public price
    let public_price = CONFIG.load(deps.storage).unwrap().public_price;
    Ok(public_price)
}

use fasttext::FastText;
use std::cmp::Ordering;

fn most_similar_words(ft: &FastText, query: &str, top_n: usize) -> Result<Vec<(String, f32)>, String> {
    // Check if the query word exists in the model
    if !ft.has_word(query) {
        return Err(format!("Word '{}' not found in the model", query));
    }

    // Get the vector for the query word
    let query_vec = match ft.get_vector(query) {
        Some(vec) => vec,
        None => return Err(format!("Failed to get vector for word '{}'", query)),
    };

    // Collect all words and their cosine similarity scores
    let mut similarities: Vec<(String, f32)> = ft.get_words()
        .filter_map(|word| {
            if word == query {
                return None; // Skip the query word itself
            }
            let word_vec = ft.get_vector(word).ok()?;
            let similarity = cosine_similarity(&query_vec, &word_vec);
            Some((word.to_string(), similarity))
        })
        .collect();

    // Sort by similarity in descending order
    similarities.sort_by(|a, b| {
        b.1.partial_cmp(&a.1)
            .expect("Similarity scores should be comparable")
    });

    // Take the top N results
    Ok(similarities.into_iter().take(top_n).collect())
}

fn cosine_similarity(a: &[f32], b: &[f32]) -> f32 {
    if a.len() != b.len() {
        panic!("Vectors must have the same length for cosine similarity");
    }

    let dot_product: f32 = a.iter().zip(b.iter()).map(|(&x, &y)| x * y).sum();
    let norm_a: f32 = a.iter().map(|&x| x * x).sum::<f32>().sqrt();
    let norm_b: f32 = b.iter().map(|&x| x * x).sum::<f32>().sqrt();

    if norm_a == 0.0 || norm_b == 0.0 {
        return 0.0; // Avoid division by zero
    }

    dot_product / (norm_a * norm_b)
}

