fn copy_file(fs: &Client, src: &str, dst: &str) -> std::io::Result<()> {
    let mut source = fs.open(src)?;
    let mut destination = fs.create(dst, false, None)?;

    let mut buffer = [0; 1024 * 1024]; // 1MB buffer
    loop {
        let bytes_read = source.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }
        destination.write_all(&buffer[..bytes_read])?;
    }

    Ok(())
}

fn ensure_signature_scheme_allowed(
    cert: &CertificateDer<'_>,
    allowed: &[SignatureScheme],
) -> Result<(), RustlsError> {
    let parsed = parse(cert).map_err(|e| match e {
        ParseError::CertificateError(CertificateError::Other(e)) => RustlsError::Other(e),
        ParseError::CertificateError(CertificateError::InvalidSignatureScheme) => {
            RustlsError::InvalidCertificate
        }
        ParseError::CertificateError(CertificateError::InvalidSignature) => {
            RustlsError::InvalidCertificate
        }
        ParseError::Other(e) => RustlsError::Other(e),
    })?;

    let signature_scheme = parsed.signature_scheme();
    if allowed.contains(&signature_scheme) {
        Ok(())
    } else {
        Err(RustlsError::InvalidCertificate)
    }
}

fn fill_random(buf: &mut [u8]) {
    let aligned_buf = pod_align_to_mut(buf);
    let aligned_len = aligned_buf.len();

    let mut bytes = [0u8; 65536];
    let mut offset = 0;

    while offset < aligned_len {
        let chunk_size = aligned_len - offset;
        let chunk_size = chunk_size.min(bytes.len());

        unsafe {
            sys_rand(bytes.as_mut_ptr().cast(), chunk_size as _);
        }

        aligned_buf[offset..offset + chunk_size].copy_from_slice(&bytes[..chunk_size]);
        offset += chunk_size;
    }
}

use crate::rgh::hash::{RHash, OutputOptions};
use walkdir::WalkDir;
use base64::{encode, decode};
use std::fs::File;
use std::io::Read;
use std::error::Error;

fn hash_directory(path: &str, algorithm: &str, output: OutputOptions) -> Result<String, Box<dyn Error>> {
    let mut hasher = RHash::new(algorithm);

    for entry in WalkDir::new(path) {
        let entry = entry?;
        let path = entry.path();
        if path.is_file() {
            let mut file = File::open(path)?;
            let mut contents = Vec::new();
            file.read_to_end(&mut contents)?;
            hasher.update(&contents);
        }
    }

    let hash = hasher.finish();

    match output {
        OutputOptions::Hex => Ok(hash.encode_hex().to_string()),
        OutputOptions::Base64 => {
            let encoded = encode(&hash);
            Ok(encoded)
        },
        OutputOptions::Base64Url => {
            let encoded = encode(&hash);
            let url_safe = encoded.replace('+', "-").replace('/', "_");
            Ok(url_safe)
        },
    }
}

use std::future::Future;
use std::time::Duration;
use tokio::select;
use tokio_with_wasm::task::JoinSet;
use tokio_with_wasm::time::sleep;

fn run_tasks_with_timeout<T, Fut, F>(tasks: Vec<F>, max_duration: Duration) -> Vec<T>
where
    T: Send + 'static,
    Fut: Future<Output = T> + Send + 'static,
    F: FnOnce() -> Fut + Send + 'static,
{
    let mut join_set = JoinSet::new();
    let mut results = Vec::new();
    let timeout_task = sleep(max_duration);

    for task in tasks {
        join_set.spawn(task);
    }

    select! {
        _ = timeout_task => {
            // Cancel all pending tasks
            while let Some(join_handle) = join_set.join_next().now_or_never() {
                if let Some(join_handle) = join_handle {
                    join_handle.abort();
                }
            }
        },
        result = join_set.join_next() => {
            if let Some(Ok(value)) = result {
                results.push(value);
            }
        }
    }

    results
}

