use std::io::BufReader;
use misc_utils::fs::{guess_file_type, read_to_string};
use misc_utils::error::Error;
use misc_utils::fs::FileType;

fn read_file_to_string(path: &Path) -> Result<String, Error> {
    let file_type = guess_file_type(path)?;
    let file = File::open(path)?;
    let reader = BufReader::new(file);

    match file_type {
        FileType::Text => read_to_string(reader),
        FileType::Gz => {
            let decompressed = std::io::BufReader::new(std::io::BufReader::new(file).bytes().filter_map(|b| b.ok()).collect::<Vec<u8>>());
            read_to_string(decompressed)
        }
        FileType::Xz => {
            let decompressed = std::xz2::read::XzDecoder::new(file).bytes().filter_map(|b| b.ok()).collect::<Vec<u8>>();
            read_to_string(std::io::BufReader::new(decompressed))
        }
        FileType::Bz2 => {
            let decompressed = std::bzip2::Decompress::new(file).bytes().filter_map(|b| b.ok()).collect::<Vec<u8>>();
            read_to_string(std::io::BufReader::new(decompressed))
        }
        FileType::Unknown => {
            read_to_string(reader)
        }
    }
}

