use vortex_array::{ArrayRef, IntoArray};
use vortex_array::arrays::PrimitiveArray;
use vortex_dtype::datetime::{TemporalMetadata, TimeUnit};
use vortex_error::{VortexResult, vortex_bail};
use crate::{DateTimePartsArray, DateTimePartsVTable};

fn datetime_parts_to_iso_string(array: &DateTimePartsArray) -> VortexResult<ArrayRef> {
    let vtable = array.vtable();
    let data = array.data();

    let mut result = PrimitiveArray::new(
        vtable.dtype().with_unit(TimeUnit::Nanoseconds),
        data.len() as u64,
    );

    for (i, &value) in data.iter().enumerate() {
        let nanoseconds = match vtable.unit() {
            TimeUnit::Seconds => value as i64 * 1_000_000_000,
            TimeUnit::Milliseconds => value as i64 * 1_000_000,
            TimeUnit::Microseconds => value as i64 * 1_000,
            TimeUnit::Nanoseconds => value as i64,
        };

        let iso_string = format!("{:?}", std::time::SystemTime::UNIX_EPOCH + std::time::Duration::new(nanoseconds as u64 / 1_000_000_000, (nanoseconds % 1_000_000_000) as u32));
        result.data_mut()[i] = iso_string.into();
    }

    Ok(result.into())
}

fn memory_regions<'dt>(index: &DevTreeIndex<'dt, 'dt>) -> Result<Vec<(u64, u64)>, DevTreeError> {
    let memory_node = index.find_node("/memory")?;
    let mut regions = Vec::new();

    for child in memory_node.children() {
        if let Some(name) = child.name() {
            if name == "reg" {
                let reg_property = child.property("reg")?;
                let mut offset = 0;
                while offset < reg_property.len() {
                    let base = u64::from_be(reg_property[offset..offset + 4].try_into()?);
                    offset += 4;
                    let size = u64::from_be(reg_property[offset..offset + 4].try_into()?);
                    offset += 4;
                    regions.push((base, size));
                }
            }
        }
    }

    Ok(regions)
}

