fn send_message<S>(stream: &mut snowstorm::NoiseStream<S>, payload: &[u8]) -> SnowstormResult<()>
where
    S: tokio::io::AsyncWrite + Unpin,
{
    let payload_len = payload.len() as u16;
    stream.write_all(&payload_len.to_le_bytes())?;
    stream.write_all(payload)
}

async fn receive_message<S>(stream: &mut snowstorm::NoiseStream<S>) -> SnowstormResult<Vec<u8>>
where
    S: tokio::io::AsyncRead + Unpin,
{
    let mut length_buffer = [0u8; 2];
    stream.read_exact(&mut length_buffer)?;
    let payload_len = u16::from_le_bytes(length_buffer) as usize;

    let mut payload = vec![0u8; payload_len];
    stream.read_exact(&mut payload)?;
    Ok(payload)
}

