fn todos_to_markdown(doxygen: &str) -> String {
    let mut result = String::new();
    let mut in_todo = false;
    let mut current_todo = String::new();

    for c in doxygen.chars() {
        if c == '@' && !in_todo {
            in_todo = true;
            current_todo.push(c);
        } else if c == '@' && in_todo {
            in_todo = false;
            current_todo.push(c);
        } else if c == '}' && in_todo {
            in_todo = false;
            current_todo.push(c);
            result.push_str(&format!("- [ ] {}", current_todo));
            current_todo.clear();
        } else if in_todo {
            current_todo.push(c);
        } else {
            result.push(c);
        }
    }

    result
}

use kd_tree::{KdTreeN, KdPoint, ItemAndDistance};
use typenum::Unsigned;
use num_traits::{NumAssign, Zero};

fn farthest<T, N>(self, query: &impl KdPoint<Scalar = T::Scalar, Dim = N>) -> Option<ItemAndDistance<T, T::Scalar>>
where
    T: NumAssign + Zero + Copy,
    N: Unsigned,
{
    let mut max_distance = Zero::zero();
    let mut farthest_point = None;

    for item in self {
        let distance = item.point.distance_squared(query);
        if distance > max_distance {
            max_distance = distance;
            farthest_point = Some(item);
        }
    }

    farthest_point
}

use arrow_schema::ArrowError;
use parquet_variant::{Variant, VariantBuilder, VariantObject};

fn merge_variants(first: &Variant, second: &Variant) -> Result<Variant<'static, 'static>, ArrowError> {
    let mut builder = VariantBuilder::new();
    let mut merged = VariantObject::new();

    for (key, value) in second.fields() {
        merged.insert(key, value.clone());
    }

    for (key, value) in first.fields() {
        if !merged.contains_key(key) {
            merged.insert(key, value.clone());
        }
    }

    builder.set_object(merged);
    Ok(builder.build())
}

