fn validate_sha256(body: SdkBody, expected: Bytes) -> Result<(), Error> {
    let mut checksum_body = ChecksumBody::new(body);
    let (result, actual) = checksum_body.finish();
    if result.is_err() {
        return Err(Error::new(result.unwrap_err()));
    }
    if actual != expected {
        return Err(Error::new(format!(
            "Expected SHA256 checksum: {:x}, got: {:x}",
            expected, actual
        )));
    }
    Ok(())
}

