) -> Result<(), GeyserPluginServiceError> {
    let plugin = self
        .plugins
        .get_mut(name)
        .ok_or(GeyserPluginServiceError::PluginNotFound)?;

    // Attempt to reload from primary config
    if let Err(e) = plugin.reload(primary_config) {
