    }

    Ok(())
}

fn read_all<R>(reader: &mut PartialAsyncRead<R>, mut buf: &mut [u8]) -> std::io::Result<usize>
where
    R: tokio::io::AsyncRead + Unpin,
{
    let mut total = 0;
    loop {
        match reader.read(buf) {
            Ok(n) if n == 0 => break,
            Ok(n) => {
                total += n;
                buf = &mut buf[n..];
                if buf.is_empty() {
                    break;
                }
            }
            Err(err) if err.kind() == ErrorKind::Interrupted => {
                // Continue reading after interruption
                continue;
            }
            Err(err) => return Err(err),
        }
    }
    Ok(total)
}

fn send_with_retry(
    lightning: &LightningClientModule,
    invoice: Bolt11Invoice,
    max_attempts: usize,
) -> Result<OperationId, SendPaymentError> {
    let mut attempts = 0;
    let mut tried_gateways = HashSet::new();

    loop {
        attempts += 1;
        if attempts > max_attempts {
            return Err(SendPaymentError::MaxRetriesExceeded);
        }

        // Try to select a gateway and send payment
        match lightning.select_gateway(&invoice, &mut tried_gateways) {
            Ok(gateway) => {
                match lightning.send_payment(gateway, invoice) {
                    Ok(op_id) => return Ok(op_id),
                    Err(SendPaymentError::GatewayError(_)) => {
                        // Gateway failed, try another
                        continue;
                    }
                    Err(e) => return Err(e),
                }
            }
            Err(SelectGatewayError::NoAvailableGateways) => {
                return Err(SendPaymentError::NoAvailableGateways);
            }
            Err(e) => return Err(e.into()),
        }
    }
}

fn estimate_transaction_complexity(instructions: &[(&Pubkey, SVMInstruction)]) -> (u16, PrecompileSignatureDetails) {
    let mut total_instruction_data_len = 0;
    let mut precompile_signature_details = PrecompileSignatureDetails::default();

    for (&program_id, instruction) in instructions {
        // Calculate instruction data length
        let instruction_data_len = InstructionDataLenBuilder::new()
            .with_instruction(instruction)
            .with_program_id(program_id)
            .build()
            .unwrap_or(0);
        total_instruction_data_len += instruction_data_len;

        // Check if the program is a precompile
        if program_id == &Pubkey::default() {
            // Count precompile signatures
            let signature_details = get_precompile_signature_details(instruction);
            precompile_signature_details += signature_details;
        }
    }

    // Convert total instruction data length to a complexity score (u16)
    let complexity_score = total_instruction_data_len as u16;

    (complexity_score, precompile_signature_details)
}

struct MemoryMonitor {
    total_bytes: usize,
    allocator: SnMalloc,
}

impl MemoryMonitor {
    fn new() -> Self {
        SnMalloc::new().unwrap()
    }

    fn allocate(&mut self, layout: Layout) -> Option<NonNull<u8>> {
        let ptr = self.allocator.allocate(layout);
        if let Some(ptr) = ptr {
            self.total_bytes += layout.size();
            Some(ptr)
        } else {
            None
        }
    }

    fn deallocate(&mut self, ptr: NonNull<u8>, layout: Layout) {
        self.allocator.deallocate(ptr, layout);
        self.total_bytes -= layout.size();
    }

    fn get_total_bytes(&self) -> usize {
        self.total_bytes
    }
}

