        query: &'a ObliviousDoHMessagePlaintext,
        server_url: &'a str,
        result_sender: mpsc::Sender<Result<ObliviousDoHMessagePlaintext>>,
    ) -> Self {
        Task {
            config,
            query,
            server_url,
            result_sender,
        }
    }

    async fn run(self) {
        let config = self.config;
        let query = self.query;
        let server_url = self.server_url;
        let result_sender = self.result_sender;

        let encrypted_query = encrypt_query(config, query).unwrap();

        let client = Client::new();
        let request = Request::post(server_url)
            .header(ODOH_HTTP_HEADER, "1")
            .body(Body::from(encrypted_query))
            .unwrap();

        match client.request(request).await {
            Ok(response) => {
                if response.status() == StatusCode::OK {
                    let body = to_bytes(response.into_body()).await.unwrap();
                    let decrypted_response = decrypt_response(config, &body).unwrap();
                    result_sender.send(Ok(decrypted_response)).unwrap();
                } else {
                    result_sender.send(Err(Error::new("HTTP error"))).unwrap();
                }
            }
            Err(e) => {
                result_sender.send(Err(Error::new(e.to_string()))).unwrap();
            }
        }
    }
}

struct TaskQueue {
    queue: VecDeque<Task>,
    max_concurrent: usize,
    current_concurrent: usize,
    result_receiver: mpsc::Receiver<Result<ObliviousDoHMessagePlaintext>>,
}

impl TaskQueue {
    fn new(
        queries: Vec<ObliviousDoHMessagePlaintext>,
        config: &ObliviousDoHConfigContents,
        server_url: &str,
        max_concurrent: usize,
    ) -> Self {
        let (result_sender, result_receiver) = mpsc::channel(max_concurrent);
        let mut queue = VecDeque::new();
        for query in queries {
            let task = Task::new(config, &query, server_url, result_sender.clone());
            queue.push_back(task);
        }
        TaskQueue {
            queue,
            max_concurrent,
            current_concurrent: 0,
            result_receiver,
        }
    }

    fn next_task(&mut self) -> Option<Task> {
        self.current_concurrent = std::cmp::min(self.current_concurrent + 1, self.max_concurrent);
        self.queue.pop_front()
    }

    fn done_task(&mut self) {
        self.current_concurrent = std::cmp::max(self.current_concurrent - 1, 0);
    }
}

