fn create_proposal_with_initial_vote(
    deps: DepsMut,
    env: Env,
    info: MessageInfo,
    title: String,
    description: String,
    msgs: Vec<CosmosMsg<Empty>>,
    latest: Option<Expiration>,
    initial_voter: Option<String>,
) -> Result<Response, ContractError> {
    // Execute the propose function to create the proposal
    let proposal_id = execute_propose(
        deps,
        env,
        info,
        title,
        description,
        msgs,
        latest,
    )?;

    // If an initial voter is provided, add a yes vote from them
    if let Some(voter) = initial_voter {
        // Check if the voter exists
        let voter_address = deps.api.addr_validate(&voter)?;
        let voter_info = VOTERS.load(deps.storage, &voter_address)?;
        if voter_info.voting_power == 0 {
            return Err(ContractError::NoVotingPower {});
        }

        // Create a ballot with yes vote
        let ballot = Ballot {
            proposal: proposal_id,
            voter: voter_address,
            vote: Vote::Yes,
        };

        // Save the ballot
        BALLOTS.save(deps.storage, &ballot.proposal, &ballot)?;

        // Evaluate if the proposal has passed based on the initial vote
        let proposal = PROPOSALS.load(deps.storage, &proposal_id)?;
        let yes_votes = proposal.votes.get(&Vote::Yes).unwrap_or(&0);
        let no_votes = proposal.votes.get(&Vote::No).unwrap_or(&0);
        let abstain_votes = proposal.votes.get(&Vote::Abstain).unwrap_or(&0);

        let total_voting_power = proposal.voters.iter().map(|(_, v)| v.voting_power).sum::<u128>();
        let yes_percentage = (yes_votes * 100) / total_voting_power;

        // Check if the proposal has passed
        if yes_percentage >= proposal.threshold {
            // If passed, add a message to the response
            let pass_msg = cosmos::Msg::new("Proposal passed!".to_string(), vec![]);
            let response = Response::new()
                .add_message(pass_msg)
                .add_attribute("action", "create_proposal_with_initial_vote")
                .add_attribute("proposal_id", proposal_id.to_string())
                .add_attribute("status", "passed");
            return Ok(response);
        } else {
            // If not passed, just return the proposal creation
            let response = Response::new()
                .add_attribute("action", "create_proposal_with_initial_vote")
                .add_attribute("proposal_id", proposal_id.to_string())
                .add_attribute("status", "not_passed");
            return Ok(response);
        }
    }

    // If no initial voter, just return the proposal creation
    let response = Response::new()
        .add_attribute("action", "create_proposal_with_initial_vote")
        .add_attribute("proposal_id", proposal_id.to_string())
        .add_attribute("status", "created");
    Ok(response)
}

