use wasmedge_wasi_socket::TcpStream;
use std::io::Read;
use std::time::Duration;

fn read_line_with_timeout(stream: &mut TcpStream, timeout: Duration) -> std::io::Result<Option<String>> {
    // Set the receive timeout
    stream.set_read_timeout(Some(timeout))?;

    let mut buffer = Vec::new();
    let mut line = String::new();
    let mut chars_read = 0;

    loop {
        // Check if we've received a newline character
        if chars_read > 0 && line.ends_with('\n') {
            // Remove the newline character
            line.pop();
            break;
        }

        // Read data from the stream
        let n = stream.read(&mut buffer)?;
        if n == 0 {
            // No data received, break the loop
            break;
        }

        // Convert the buffer to a string and check for line endings
        let data = std::str::from_utf8(&buffer)?;
        let mut new_line = String::new();
        let mut pos = 0;

        // Find the first newline character
        while pos < data.len() {
            if data[pos] == '\n' {
                // Extract the line up to the newline
                new_line = data[..pos].to_string();
                // Remove the newline character from the buffer
                buffer = data[pos + 1..].as_bytes().to_vec();
                chars_read += pos + 1;
                break;
            }
            pos += 1;
        }

        if !new_line.is_empty() {
            line.push_str(&new_line);
            break;
        }

        // If no newline found, append the data to the buffer
        line.push_str(data);
        chars_read += data.len();
    }

    // Check if we have a complete line
    if !line.is_empty() && line.ends_with('\n') {
        line.pop();
    }

    Ok(Some(line))
}

