fn consume_matching_pairs<T, I>(&mut self, expected_front: &T, expected_back: &T)
    where
        T: ?Sized,
        I::Item: PartialEq<T>,
        I: DoubleEndedIterator,
        I: DoubleEndedPeekableExt,
{
    while self.peek_front().map_or(false, |front| front == expected_front) &&
          self.peek_back().map_or(false, |back| back == expected_back)
    {
        self.next_front();
        self.next_back();
    }
}

