        }
    }

    Ok(missing_checksums)
}

use crate::Quaternion;

fn slerp(a: Quaternion, b: Quaternion, t: f32) -> Quaternion {
    // Ensure the quaternions are normalized
    let a = a.normalize();
    let b = b.normalize();

    // Compute the cosine of the angle between the two quaternions
    let cos_theta = a.w * b.w + a.x * b.x + a.y * b.y + a.z * b.z;

    // Handle the case where the quaternions are nearly identical
    if cos_theta >= 1.0 {
        return a;
    }

    // Handle the case where the quaternions are nearly opposite
    if cos_theta <= -1.0 {
        return -a;
    }

    // Compute the angle between the quaternions
    let theta = cos_theta.acos();
    let sin_theta = theta.sin();

    // Compute the slerp interpolation
    let a_part = (theta - t * theta).sin() / sin_theta;
    let b_part = (t * theta).sin() / sin_theta;

    Quaternion {
        x: a.x * a_part + b.x * b_part,
        y: a.y * a_part + b.y * b_part,
        z: a.z * a_part + b.z * b_part,
        w: a.w * a_part + b.w * b_part,
    }
}

use bootspec::{BootJson, Generation};

fn all_specialisation_names(boot_json: &BootJson) -> Vec<String> {
    let mut result = Vec::new();
