    result
}

fn collect_specialisations(generations: &[Generation], result: &mut Vec<String>) {
    for generation in generations {
        if let Some(specialisations) = &generation.specialisations {
            for spec in specialisations {
                result.push(spec.name.clone());
                collect_specialisations(&spec.generations, result);
            }
        }
    }
}

fn find_default_font(fc: &Fontconfig, family: &str) -> Option<Font> {
    let mut pattern = Pattern::new();
    let family_c = CString::new(family).expect("Failed to create CString for family");
    pattern.set(FC_FAMILY, &family_c);
    pattern.compile().expect("Failed to compile pattern");

    for font in fc.match_font(&pattern) {
        if font.get_weight() == 400 && font.get_slant() == 0 {
            return Some(font);
        }
    }

    None
}

