use bb8;
use bb8_redis::RedisConnectionManager;
use redis::{self, aio::MultiplexedConnection, Cmd, Value, RedisError};

fn exec_with_retry(
    pool: &bb8::Pool<bb8_redis::RedisConnectionManager>,
    command: &str,
    args: &[&str],
) -> Result<redis::Value, RedisError> {
    let mut conn = pool.get()?;
    let cmd = Cmd::new().arg(command).args(args);
    let result = conn.query(cmd);

    match result {
        Ok(val) => Ok(val),
        Err(e) if e.is_connect_error() => {
            // Release the current connection and try again
            drop(conn);
            let mut conn = pool.get()?;
            let cmd = Cmd::new().arg(command).args(args);
            conn.query(cmd)
        },
        Err(e) => Err(e),
    }
}

