    while let Some(value) = iter.next().map_err(|e| AnyError::new(e.to_string()))? {
        if let Ok(number) = converters::convert_number(&value) {
            result.push(number);
        }
    }

    Ok(result)
}

use crate::rgh::hash::{RHash, OutputOptions};
use base64;
use std::error::Error;

fn batch_hash<I>(algorithm: &str, inputs: I, output: OutputOptions) -> Result<Vec<String>, Box<dyn Error>>
where
    I: IntoIterator,
    I::Item: AsRef<str>,
{
    let mut results = Vec::new();
    let mut hasher = RHash::new(algorithm)?;

    for input in inputs {
        let data = input.as_ref();
        hasher.update(data.as_bytes());
        let hash = hasher.finalize();
        hasher.reset();

        let encoded = match output {
            OutputOptions::Base64 => base64::encode(&hash),
            OutputOptions::Hex => hex::encode(&hash),
            OutputOptions::Binary => base64::encode_config(&hash, base64::STANDARD),
        };

        results.push(encoded);
    }

    Ok(results)
}

use crate::utils::dvm_root;
use semver::Version;
use std::fs;

fn list_installed_versions() -> Result<Vec<String>, std::io::Error> {
    let dvm_root_path = dvm_root()?;
    let versions_dir = format!("{}/versions", dvm_root_path);

    // Check if the versions directory exists
    if !fs::metadata(&versions_dir).is_ok() {
        return Ok(vec![]);
    }

    // Read the directory entries
    let entries = fs::read_dir(versions_dir)?;

    // Collect version strings
    let mut versions: Vec<String> = entries
        .filter_map(|entry| {
            let path = entry.path();
            if path.is_dir() && path.file_name().and_then(|n| n.to_str()).map_or(false, |s| s.starts_with("v")) {
                let version_str = path.file_name().unwrap().to_str().unwrap().to_string();
                if let Ok(version) = Version::parse(&version_str) {
                    Some(version_str)
                } else {
                    None
                }
            } else {
                None
            }
        })
        .collect();

    // Sort versions in descending order
    versions.sort_by(|a, b| {
        let a_ver = Version::parse(a).unwrap();
        let b_ver = Version::parse(b).unwrap();
        b_ver.cmp(&a_ver)
    });

    Ok(versions)
}

