fn build_recover_nested_instruction(
    wallet_address: &Pubkey,
    owner_token_mint: &Pubkey,
    nested_token_mint: &Pubkey,
    token_program_id: &Pubkey,
) -> Instruction {
    // Compute owner ATA
    let owner_ata = get_associated_token_address_with_program_id(
        wallet_address,
        owner_token_mint,
        token_program_id,
    );

    // Compute nested ATA
    let nested_ata = get_associated_token_address_with_program_id(
        &owner_ata,
        nested_token_mint,
        token_program_id,
    );

    // Compute destination ATA (assuming it's the same as owner ATA for recovery)
    let destination_ata = owner_ata;

    // Instruction data for RecoverNested
    let data = spl_associated_token_account_client::instruction::recover_nested::data();

    Instruction {
        program_id: spl_associated_token_account_client::program::id(),
        accounts: vec![
            AccountMeta::new(*wallet_address, false),
            AccountMeta::new(owner_ata, true),
            AccountMeta::new(nested_ata, false),
            AccountMeta::new_readonly(*owner_token_mint, false),
            AccountMeta::new_readonly(*nested_token_mint, false),
            AccountMeta::new_readonly(*token_program_id, false),
            AccountMeta::new(destination_ata, true),
        ],
        data,
    }
}

use datafusion_datasource::ListingTableUrl;
use object_store::path::Path;

fn parse_custom_partitions(
    table_path: &ListingTableUrl,
    file_path: &Path,
    partition_cols: &[&str],
) -> Option<Vec<String>> {
    let path_str = file_path.to_string();
    let mut result = Vec::new;

    // Extract the path relative to the table path
    let table_path_str = table_path.to_string();
    let path_relative = path_str.replace(&table_path_str, "");

    // Split the relative path by slashes
    let parts: Vec<&str> = path_relative.split('/').collect();

    // Iterate over the partition columns and extract values
    for &col in partition_cols {
        // Find the part of the path that matches the column name
        let col_part = parts.iter().find(|&&part| part.starts_with(col));
        if let Some(col_part) = col_part {
            // Extract the value after the column name
            if let Some(value) = col_part.strip_prefix(col) {
                result.push(value.to_string());
            }
        }
    }

    Some(result)
}

