fn is_user_eligible_for_mint(deps: Deps, user: &Addr) -> Result<(bool, Vec<(String, u32)>), ContractError> {
    let config = CONFIG.load(deps.storage)?;
    let required_tokens = &config.mint_tokens;
    let received_tokens = RECEIVED_TOKENS.load(deps.storage)?;

    let mut missing = Vec::new();

    for token in required_tokens {
        let amount_received = received_tokens.get(user).and_then(|t| t.get(token.collection()));
        let required_amount = token.amount();

        if amount_received.map_or(false, |a| a >= required_amount) {
            continue;
        }

        let missing_amount = required_amount.saturating_sub(amount_received.unwrap_or(0));
        missing.push((token.collection().to_string(), missing_amount));
    }

    Ok((missing.is_empty(), missing))
}

use aws_smithy_xml::decode::{Document, ScopedDecoder, XmlDecodeError, try_data};

#[derive(Debug, PartialEq, Eq)]
struct NestedMap {
    entries: Vec<(String, String)>,
}

fn parse_nested_map(xml: &str) -> Result<NestedMap, XmlDecodeError> {
    let document = Document::parse(xml)?;
    let mut decoder = ScopedDecoder::new(&document);
    let mut entries = Vec::new();

    try_data!(decoder.enter_element("entry"))?;
    while decoder.is_element("entry") {
        let key = try_data!(decoder.get_text().map(|s| s.to_string()))?;
        let value = try_data!(decoder.get_text().map(|s| s.to_string()))?;
        entries.push((key, value));
        try_data!(decoder.exit_element())?;
        try_data!(decoder.enter_element("entry"))?;
    }
    try_data!(decoder.exit_element())?;

    Ok(NestedMap { entries })
}

fn batch_execute<'a, S, P, R>(
    client: &RestClient<'a, S, P>,
    requests: Vec<R>,
) -> Result<(Vec<R::Response>, Metric), P::OutputError>
where
    S: barter_integration::protocol::http::BuildStrategy,
    P: barter_integration::protocol::http::HttpParser,
    R: RestRequest + Send + 'static,
{
    let start_time = Utc::now();
    let futures = requests
        .into_iter()
        .map(|request| client.execute(request))
        .collect::<Vec<_>>();
    let results = join_all(futures).await;

    let mut responses = Vec::new();
    let mut total_duration = std::time::Duration::zero();

    for result in results {
        let (response, duration) = result?;
        responses.push(response);
        total_duration += duration;
    }

    let end_time = Utc::now();
    let duration = end_time - start_time;

    let mut metric = Metric::new("batch_request_duration");
    metric.add_field(Field::new("total_duration", Value::Duration(duration)));
    metric.add_field(Field::new("num_requests", Value::Integer(responses.len() as i64)));
    metric.add_tag(Tag::new("environment", Cow::Borrowed("production")));

    Ok((responses, metric))
}

use batbox_la::{vec2, mat3, Angle, Aabb2};

fn rotated_rect_aabb(center: vec2<f32>, half_size: vec2<f32>, angle: Angle<f32>) -> Aabb2<f32> {
    let rotation = mat3::from_angle(angle);
    let corners = [
        vec2!(-half_size.x, -half_size.y),
        vec2!(half_size.x, -half_size.y),
        vec2!(half_size.x, half_size.y),
        vec2!(-half_size.x, half_size.y),
    ];

    let transformed_corners: Vec<vec2<f32>> = corners
        .iter()
        .map(|&corner| rotation * corner)
        .map(|vec| vec + center)
        .collect();

    let min_x = transformed_corners.iter().map(|v| v.x).fold(f32::MAX, f32::min);
    let max_x = transformed_corners.iter().map(|v| v.x).fold(f32::MIN, f32::max);
    let min_y = transformed_corners.iter().map(|v| v.y).fold(f32::MAX, f32::min);
    let max_y = transformed_corners.iter().map(|v| v.y).fold(f32::MIN, f32::max);

    Aabb2::new(vec2!(min_x, min_y), vec2!(max_x, max_y))
}

fn parallel_hash_files(files: &[FileInfo], arguments: &Arguments) -> Vec<FileInfo> {
    let hash_algorithm = match arguments.hash_algorithm.as_str() {
        "md5" => Key::MD5,
        "sha1" => Key::SHA1,
        "sha256" => Key::SHA256,
        _ => Key::MD5,
    };

    files
        .par_iter()
        .map(|file| {
            let mut hasher = match hash_algorithm {
                Key::MD5 => md5::Md5::new(),
                Key::SHA1 => sha1::Sha1::new(),
                Key::SHA256 => sha2::Sha256::new(),
            };
            let path = std::path::Path::new(&file.path);
            let file = std::fs::File::open(path).expect("Failed to open file");
            let mut reader = std::io::BufReader::new(file);
            let mut buffer = [0; 1024 * 1024]; // 1MB buffer

            loop {
                let bytes_read = reader.read(&mut buffer).expect("Failed to read file");
                if bytes_read == 0 {
                    break;
                }
                hasher.update(&buffer[..bytes_read]);
            }

            let hash = match hash_algorithm {
                Key::MD5 => format!("{:x}", hasher.result()),
                Key::SHA1 => format!("{:x}", hasher.result()),
                Key::SHA256 => format!("{:x}", hasher.result()),
            };

            FileInfo {
                path: file.path.clone(),
                hash: hash,
                ..file.clone()
            }
        })
        .collect()
}

use zino_core::{Map, validation::Validation};
