pub fn extract_nested_model<T: Model>(data: &Map, path: &[&str]) -> Result<T, Validation> {
    let mut current = data;
    for &key in path {
        if let Some(obj) = current.get_map(key) {
            current = obj;
        } else {
            return Err(Validation::new().record("nested_field", format!("field `{}` not found", key)));
        }
    }
    let mut model = T::default();
    let validation = model.read_map(current);
    if validation.is_valid() {
        Ok(model)
    } else {
        Err(validation)
    }
}

