use crate::{UnlockedSeedBundle, SharedLockedArray};
use one_err::OneErr;
use std::sync::{Arc, Mutex};
use sodoken::LockedArray;

fn backup_with_multiple_ciphers(
    seed_bundle: &UnlockedSeedBundle,
    passphrase: SharedLockedArray,
    question_list: (String, String, String),
    answer_list: (
        LockedArray,
        LockedArray,
        LockedArray,
    ),
) -> Result<Vec<u8>, OneErr> {
    let mut builder = SeedCipherBuilder::new();

    // Add passphrase cipher
    builder.add_passphrase_cipher(passphrase)?;

    // Add security question ciphers
    builder.add_security_question_ciphers(question_list, answer_list)?;

    let encrypted_bundle = builder.build(seed_bundle)?;

    Ok(encrypted_bundle)
}

struct SeedCipherBuilder {
    ciphers: Vec<Box<dyn Cipher>>,
    lock: Mutex<()>,
}

impl SeedCipherBuilder {
    fn new() -> Self {
        SeedCipherBuilder {
            ciphers: Vec::new(),
            lock: Mutex::new(()),
        }
    }

    fn add_passphrase_cipher(
        &mut self,
        passphrase: SharedLockedArray,
    ) -> Result<(), OneErr> {
        let mut lock = self.lock.lock().map_err(|_| OneErr::new("Failed to lock cipher builder"))?;
        self.ciphers.push(Box::new(PassphraseCipher::new(passphrase)));
        Ok(())
    }

    fn add_security_question_ciphers(
        &mut self,
        question_list: (String, String, String),
        answer_list: (LockedArray, LockedArray, LockedArray),
    ) -> Result<(), OneErr> {
        let mut lock = self.lock.lock().map_err(|_| OneErr::new("Failed to lock cipher builder"))?;
        self.ciphers.push(Box::new(SecurityQuestionCipher::new(question_list, answer_list)));
        Ok(())
    }

    fn build(
        &self,
        seed_bundle: &UnlockedSeedBundle,
    ) -> Result<Vec<u8>, OneErr> {
        let mut encrypted_data = Vec::new();
        for cipher in &self.ciphers {
            let encrypted = cipher.encrypt(seed_bundle)?;
            encrypted_data.extend(encrypted);
        }
        Ok(encrypted_data)
    }
}

trait Cipher {
    fn encrypt(&self, seed_bundle: &UnlockedSeedBundle) -> Result<Vec<u8>, OneErr>;
}

struct PassphraseCipher {
    passphrase: SharedLockedArray,
