use audiotags::{AudioTag, MimeType, Picture};
use std::fs::File;
use std::io::Read;
use std::path::Path;

fn set_album_cover_from_path(tag: &mut dyn AudioTag, path: &Path) -> std::io::Result<()> {
    let mut file = File::open(path)?;
    let mut buffer = Vec::new();
    file.read_to_end(&mut buffer)?;

    let mime_type = if path.extension().and_then(|ext| ext.to_str()).unwrap_or("").to_lowercase() == "jpg" {
        MimeType::Jpeg
    } else if path.extension().and_then(|ext| ext.to_str()).unwrap_or("").to_lowercase() == "png" {
        MimeType::Png
    } else {
        return Err(std::io::Error::new(std::io::ErrorKind::InvalidData, "Unsupported image format"));
    };

    let picture = Picture::new()
        .with_mime_type(mime_type)
        .with_data(buffer)
        .with_type(PictureType::CoverFront)
        .with_description("Album cover");

    tag.set_picture(picture);
    Ok(())
}

use libarchive3_sys::ffi::{archive_read_new, archive_read_support_format_all, archive_read_open_filename, archive_read_next_header, archive_read_data, archive_read_close, archive_read_free, ARCHIVE_OK, Struct_archive, Struct_archive_entry};

fn extract_with_size_limit(path: &str, max_size: usize) -> Result<(), String> {
    let mut archive = unsafe { archive_read_new() };
    if archive.is_null() {
        return Err("Failed to create archive reader".to_string());
    }

    unsafe {
        archive_read_support_format_all(archive);
        if archive_read_open_filename(archive, path as *const _, 1024 * 1024) != ARCHIVE_OK {
            archive_read_close(archive);
            archive_read_free(archive);
            return Err("Failed to open archive file".to_string());
        }

        let mut entry: *mut Struct_archive_entry = std::ptr::null_mut();
        loop {
            if archive_read_next_header(archive, &mut entry) != ARCHIVE_OK {
                break;
            }

            if !entry.is_null() {
                let entry_name = unsafe { std::ffi::CStr::from_ptr((*entry).path) };
                let entry_name = entry_name.to_str().map_err(|e| format!("Invalid entry name: {}", e))?;                
                let entry_size = unsafe { (*entry).size };

                if entry_size > max_size as u64 {
                    return Err(format!("File {} exceeds size limit of {} bytes", entry_name, max_size));
                }

                let mut buffer = vec![0; max_size];
                let mut bytes_read = 0;
                while bytes_read < max_size as u64 {
                    let read = unsafe { archive_read_data(archive, buffer.as_mut_ptr() as _, buffer.len() as u64) };
                    if read < 0 {
                        return Err("Failed to read archive data".to_string());
                    }
                    bytes_read += read as u64;
                }

                // Write the extracted data to a file
                let mut file = std::fs::File::create(entry_name)
                    .map_err(|e| format!("Failed to create file {}: {}", entry_name, e))?;
                file.write_all(&buffer)
                    .map_err(|e| format!("Failed to write file {}: {}", entry_name, e))?;
            }
        }

        unsafe {
            archive_read_close(archive);
            archive_read_free(archive);
        }
    }

    Ok(())
}

use codesnake::{Block, CodeWidth, Parts};

fn with_line_numbers(mut self) -> Self {
    let mut lines = self.lines();
    let mut new_lines = Vec::new();
    let mut line_number = 1;

    while let Some(line) = lines.next() {
        new_lines.push(format!("{}: {}", line_number, line));
        line_number += 1;
    }

    self.set_lines(new_lines);
    self.set_code_width(CodeWidth::Fixed(5));
    self.set_parts(Parts::new(
        self.parts().left(),
        self.parts().center(),
        self.parts().right(),
    ));
    self
}

