use import_map::ext::ImportMapConfig;
use serde_json::Value;
use url::Url;

fn create_synthetic_import_map_from_json(
    base_url: &str,
    base_import_map_json: &str,
    children_import_maps: Vec<(&str, &str)>,
) -> Result<(Url, String), Box<dyn std::error::Error>> {
    let base_url = Url::parse(base_url)?;
    let base_import_map: Value = serde_json::from_str(base_import_map_json)?;
    let mut config = ImportMapConfig::new();
    config.set_base_url(base_url.clone());

    // Parse and add base import map
    config.add_import_map(base_import_map)?;

    // Parse and add child import maps
    for (child_url, child_json) in children_import_maps {
        let child_url = Url::parse(child_url)?;
        let child_import_map: Value = serde_json::from_str(child_json)?;
        config.add_import_map(child_import_map)?;
    }

    let synthetic_import_map = config.build()?;
    let synthetic_import_map_json = serde_json::to_string(&synthetic_import_map)?;

    Ok((base_url, synthetic_import_map_json))
}

use import_map::{parse_from_json_with_options, ImportMapOptions, ImportMapWithDiagnostics};
use url::Url;

fn parse_and_expand_import_map(
    base_url: &str,
    json_string: &str,
) -> Result<ImportMap, Box<dyn std::error::Error>> {
    let base_url = Url::parse(base_url)?;
    let options = ImportMapOptions::new()
        .with_expand_imports(true)
        .with_base_url(base_url.clone())
        .with_resolve_packages(true);

    let import_map_with_diagnostics = parse_from_json_with_options(json_string, options)?;

    let import_map = import_map_with_diagnostics.import_map();
    Ok(import_map)
}

