fn build_and_expression(btor: *mut Btor, nodes: &[*mut BoolectorNode]) -> *mut BoolectorNode {
    if nodes.is_empty() {
        unsafe { boolector_true(btor) }
    } else if nodes.len() == 1 {
        *nodes[0]
    } else {
        let mut result = unsafe { boolector_true(btor) };
        for &node in nodes.iter().skip(1) {
            result = unsafe { boolector_and(btor, result, node) };
        }
        result
    }
}

