fn compute_panel_rects<W>(backend: &mut CrosstermBackend<W>, panel_count: usize) -> io::Result<Vec<(u16, u16, u16, u16)>>
where
    W: Write,
{
    let size = backend.size()?;
    let height = size.height;
    let width = size.width;

    if panel_count == 0 {
        return Ok(vec![]);
    }

    let panel_height = height / panel_count as u16;
    let mut rects = Vec::with_capacity(panel_count);

    for i in 0..panel_count {
        let y = i as u16 * panel_height;
        rects.push((0, y, width, panel_height));
    }

    Ok(rects)
}

