fn validate_secp256r1_signature_components(signature: &[u8]) -> Result<(), PrecompileError> {
    if signature.len() != SIGNATURE_SERIALIZED_SIZE {
        return Err(PrecompileError::new("Invalid signature length"));
    }

    let r = &signature[0..32];
    let s = &signature[32..64];

    let r_bn = BigNum::from_slice(r).map_err(|_| PrecompileError::new("Invalid r value"))?;
    let s_bn = BigNum::from_slice(s).map_err(|_| PrecompileError::new("Invalid s value"))?;

    if r_bn.cmp(&SECP256R1_ORDER_MINUS_ONE) > 0 {
        return Err(PrecompileError::new("r is out of range"));
    }

    if s_bn.cmp(&SECP256R1_HALF_ORDER) > 0 {
        return Err(PrecompileError::new("s is out of range"));
    }

    Ok(())
}

