fn filter_hashblock<S>(mut stream: S) -> impl futures_util::stream::Stream<Item = bitcoincore_zmq::Result<BlockHash>> 
where
    S: futures_util::stream::Stream<Item = bitcoincore_zmq::Result<SocketMessage>> + Unpin,
{
    stream.filter_map(|result| {
        let msg = match result {
            Ok(msg) => msg,
            Err(e) => return Some(Err(e)),
        };

        if msg.typ == "hashblock" {
            let hash = msg.data.clone();
            let block_hash = BlockHash::from_slice(&hash)
                .map_err(|e| bitcoincore_zmq::Error::new(format!("Failed to parse block hash: {}", e)))?;
            Some(Ok(block_hash))
        } else {
            None
        }
    })
}

