use std::path::{Path, PathBuf};
use anyhow::Result;
use typstyle_core::Typstyle;
use typst_syntax::Source;
use crate::cli::StyleArgs;

#[derive(Default)]
pub struct FormattingSummary {
    pub formatted: usize,
    pub unchanged: usize,
    pub errors: usize,
}

fn dry_run_format(paths: &[PathBuf], style: &StyleArgs) -> Result<FormattingSummary> {
    let mut summary = FormattingSummary::default();

    for path in paths {
        if path.is_file() {
            let content = std::fs::read_to_string(path).map_err(|e| anyhow::anyhow!("Failed to read file: {}", e))?;
            let source = Source::new(content, path.display().to_string());
            let typstyle = Typstyle::new(style);
            let formatted = typstyle.format(&source).map_err(|e| anyhow::anyhow!("Failed to format file: {}", e))?;

            if formatted != source {
                summary.formatted += 1;
            } else if let Some(error) = formatted.error {
                summary.errors += 1;
            } else {
                summary.unchanged += 1;
            }
        }
    }

    Ok(summary)
}

use fedimint_lnv2_common::contracts::IncomingContract;
use fedimint_core::PeerId;
use std::collections::BTreeMap;
use tpe::{AggregatePublicKey, DecryptionKeyShare, aggregate_dk_shares};

fn decrypt_preimage_from_shares(
    contract: &IncomingContract,
    shares: BTreeMap<PeerId, DecryptionKeyShare>,
    tpe_agg_pk: AggregatePublicKey,
) -> Result<[u8; 32], String> {
    // Aggregate decryption key shares
    let aggregated_key = aggregate_dk_shares(&shares)?;

    // Check if the aggregated key matches the expected gateway public key
    if aggregated_key != tpe_agg_pk {
        return Err("Aggregated decryption key does not match the gateway's public key".to_string());
    }

    // Attempt to decrypt the preimage using the aggregated key
    let preimage = contract.decrypt_preimage(&aggregated_key)?;

    Ok(preimage)
}

