use parquet_variant::{Variant, VariantBuilder, VariantObject};
use arrow_schema::ArrowError;

fn merge_variant_objects(first: &Variant, second: &Variant) -> Result<Variant<'static, 'static>, ArrowError> {
    let mut builder = VariantBuilder::new();
    merge_variant_into_builder(&mut builder, first, true)?;
    merge_variant_into_builder(&mut builder, second, false)?;
    Ok(builder.build()?)
}

fn merge_variant_into_builder(
    builder: &mut VariantBuilder,
    variant: &Variant,
    first_pass: bool,
) -> Result<(), ArrowError> {
    match variant {
        Variant::Null => {}
        Variant::Bool(b) => {
            if first_pass || builder.field("bool")?.is_none() {
                builder.set_field("bool", *b)?;
            }
        }
        Variant::Int(i) => {
            if first_pass || builder.field("int")?.is_none() {
                builder.set_field("int", *i)?;
            }
        }
        Variant::Long(l) => {
            if first_pass || builder.field("long")?.is_none() {
                builder.set_field("long", *l)?;
            }
        }
        Variant::Float(f) => {
            if first_pass || builder.field("float")?.is_none() {
                builder.set_field("float", *f)?;
            }
        }
        Variant::Double(d) => {
            if first_pass || builder.field("double")?.is_none() {
                builder.set_field("double", *d)?;
            }
        }
        Variant::String(s) => {
            if first_pass || builder.field("string")?.is_none() {
                builder.set_field("string", s.clone())?;
            }
        }
        Variant::Binary(b) => {
            if first_pass || builder.field("binary")?.is_none() {
                builder.set_field("binary", b.clone())?;
            }
        }
        Variant::List(l) => {
            if first_pass || builder.field("list")?.is_none() {
                builder.set_field("list", l.clone())?;
            }
        }
        Variant::Map(m) => {
            if first_pass || builder.field("map")?.is_none() {
                builder.set_field("map", m.clone())?;
            }
        }
        Variant::Object(obj) => {
            if first_pass || builder.field("object")?.is_none() {
                let mut obj_builder = VariantBuilder::new();
                for (key, value) in obj {
                    merge_variant_into_builder(&mut obj_builder, value, true)?;
                }
                builder.set_field("object", obj_builder.build()?)?;
            } else {
                let obj_field = builder.field("object")?;
                let mut obj_builder = VariantBuilder::from_variant(obj_field)?;
                for (key, value) in obj {
                    merge_variant_into_builder(&mut obj_builder, value, true)?;
                }
                builder.set_field("object", obj_builder.build()?)?;
            }
        }
    }
    Ok(())
}

