fn token_with_role(tenant_id: &str, user_id: &str, role: &str, secret: &[u8]) -> Result<String, jwt::Error> {
    let mut header = Header::new(AlgorithmType::HS256);
    header.kid = Some(tenant_id.to_string());

    let mut claims = Claims::default();
    claims.registered = RegisteredClaims {
        iss: Some(tenant_id.to_string()),
        sub: Some(user_id.to_string()),
        ..Default::default()
    };
    claims.custom = BTreeMap::from([(role.to_string(), Value::String(role.to_string()))]);

    let key = Hmac::new_from_slice(secret)?;
    let token = Token::new(header, claims, key, Sha256::new());
    Ok(token.to_string())
}

use fsst::Compressor;
