fn fsst_compress_from_iter<'a, I>(iter: I, dtype: DType) -> VortexResult<FSSTArray>
where
    I: Iterator<Item = Option<&'a [u8]>>,
{
    let mut compressor = Compressor::new(dtype);
    let mut buffer = Vec::new();

    for item in iter {
        if let Some(bytes) = item {
            buffer.extend_from_slice(bytes);
        }
    }

    let compressed = compressor.compress(&buffer)?;
    Ok(FSSTArray::from_compressed(compressed))
}

use std::sync::Arc;
use datafusion_common::config::CsvOptions;
use datafusion_common::Result;
use datafusion_session::Session;
use datafusion_datasource::file_meta::ObjectMeta;
use datafusion_datasource_csv::file_format::CsvFormat;
use object_store::ObjectStore;
use arrow::datatypes::SchemaRef;
use datafusion_common::config::CsvReadOptions;
use datafusion_common::config::CsvReadOptionsBuilder;

fn infer_schema_from_files(
    state: &dyn Session,
    store: Arc<dyn ObjectStore>,
    files: Vec<ObjectMeta>,
    max_rows_per_file: usize,
) -> Result<SchemaRef> {
    let mut schema = None;

    for file in files {
        let file_path = file.location().to_string();
        let mut options = CsvReadOptionsBuilder::new();
        options.max_rows(max_rows_per_file);
        let csv_options = options.build();

        let format = CsvFormat::new(csv_options);
        let file_meta = ObjectMeta::new(file_path, None, None, None);
        let file_reader = format.new_file_reader(state, store.clone(), file_meta)?;

        let file_schema = file_reader.schema()?;
        if let Some(existing_schema) = schema {
            schema = Some(arrow::util::schema::merge_schemas(existing_schema, &file_schema));
        } else {
            schema = Some(file_schema);
        }
    }

    schema.ok_or_else(|| datafusion_common::DataFusionError:: anyhow("No files provided"))
}

fn chrono_to_icu_zoned<Tz: TimeZone>(chrono_dt: &chrono::DateTime<Tz>) -> ZonedDateTime<Iso> {
    let zone_name = chrono_dt.timezone().name();
    let zone_info = TimeZoneInfo::try_new_iana_name(zone_name).expect("Failed to create ICU4X timezone info");

    let utc_offset = chrono_dt.offset().fix().local_minus_utc();
    let utc_offset = UtcOffset::from_seconds(utc_offset as i32);

    let icu_date = IcuDateTime::new(
        Iso::new(
            chrono_dt.year() as u16,
            chrono_dt.month() as u8,
            chrono_dt.day() as u8,
            chrono_dt.hour() as u8,
            chrono_dt.minute() as u8,
            chrono_dt.second() as u16,
            chrono_dt.nanosecond() as u32,
        ),
        Time::new(chrono_dt.hour() as u8, chrono_dt.minute() as u8, chrono_dt.second() as u8, chrono_dt.nanosecond() as u32),
    );

    ZonedDateTime::try_new(icu_date, &zone_info, utc_offset).expect("Failed to create ICU4X zoned datetime")
}

