    config: &near_indexer::IndexerConfig,
    last_synced: Option<u64>,
    latest: u64,
) -> u64 {
    match config.sync_mode {
        SyncModeEnum::Full => {
            if let Some(synced) = last_synced {
                std::cmp::max(synced, latest - 1000)
            } else {
                latest - 1000
            }
        }
        SyncModeEnum::CatchUp => {
            if let Some(synced) = last_synced {
                std::cmp::max(synced, latest - 1000)
            } else {
                latest
            }
        }
        SyncModeEnum::Resume => {
            if let Some(synced) = last_synced {
                synced
            } else {
                latest
            }
        }
    }
}

