fn heading_outline(parsed: &ParsedMarkdown) -> Vec<(HeadingLevel, String)> {
    let mut outline = Vec::new();
    for element in &parsed.elements {
        if let ParsedMarkdownElement::Heading(heading) = element {
            if let ParsedMarkdownHeading { level, text } = heading {
