use fedimint_server_core::bitcoin_rpc::ServerBitcoinRpcMonitor;
use fedimint_core::bitcoin::Transaction;
use std::time::Duration;
use anyhow::Result;

fn submit_transaction_with_retry(
    monitor: &ServerBitcoinRpcMonitor,
    tx: Transaction,
    max_attempts: usize,
    delay: Duration,
) -> Result<()> {
    for attempt in 0..max_attempts {
        match monitor.broadcast_transaction(tx.clone()) {
            Ok(_) => {
                println!("Transaction successfully broadcast on attempt {}", attempt + 1);
                return Ok(());
            }
            Err(e) => {
                eprintln!("Attempt {} failed: {}", attempt + 1, e);
                if attempt < max_attempts - 1 {
                    std::thread::sleep(delay);
                }
            }
        }
    }
    Err(anyhow::anyhow!("Max attempts reached, transaction not broadcasted"))
}

use bincode;
use solana_transaction_status::{TransactionStatusMeta, StoredTransactionStatusMeta};
use solana_transaction_error::TransactionError;

fn convert_status_meta(meta: TransactionStatusMeta) -> Result<StoredTransactionStatusMeta, bincode::Error> {
    let mut inner = Vec::new();
    for inner_meta in meta.inner {
        let inner_converted = convert_inner_status_meta(inner_meta)?;
        inner.push(inner_converted);
    }

    let mut token_balances = Vec::new();
    for balance in meta.token_balances {
        let balance_converted = convert_token_balance(balance)?;
        token_balances.push(balance_converted);
    }

    let mut rewards = Vec::new();
    for reward in meta.rewards {
        let reward_converted = convert_reward(reward)?;
        rewards.push(reward_converted);
    }

    Ok(StoredTransactionStatusMeta {
        status: meta.status,
        inner,
        token_balances,
        rewards,
        error: meta.error.map(|e| e.to_string()),
    })
}

fn convert_inner_status_meta(
    inner: solana_transaction_status::InnerTransactionStatusMeta,
) -> Result<solana_transaction_status::InnerTransactionStatusMeta, bincode::Error> {
    let mut inner = inner;
    if let Some(instruction_index) = inner.instruction_index {
        inner.instruction_index = Some(instruction_index as u64);
    }
    if let Some(program_id) = inner.program_id {
        inner.program_id = Some(program_id);
    }
    if let Some(fee) = inner.fee {
        inner.fee = Some(fee);
    }
    if let Some(memo) = inner.memo {
        inner.memo = Some(memo);
    }
    if let Some(logs) = inner.logs {
        inner.logs = Some(logs);
    }
    if let Some(inner) = inner.inner {
        inner = convert_inner_status_meta(inner)?;
    }
    Ok(inner)
}

