use std::time::{Duration, Instant};
use async_lock::RwLock;
use std::sync::Arc;
use crate::certs::{Cert, Certs};
use crate::utils;
use crate::error::MyResult;
use lazy_static::lazy_static;
use reqwest::Client;
use std::collections::HashMap;

lazy_static! {
    static ref CA_CLIENT: Arc<RwLock<Client>> = Arc::new(RwLock::new(Client::new()));
}

const GOOGLE_SA_CERTS_URL: &str = "https://www.googleapis.com/oauth2/v3/certs";

struct CacheEntry {
    certs: Certs,
    expires: Instant,
}

lazy_static! {
    static ref CERT_CACHE: Arc<RwLock<HashMap<String, CacheEntry>>> = Arc::new(RwLock::new(HashMap::new()));
}

async fn fetch_certs() -> MyResult<Certs> {
    let client = CA_CLIENT.read().await;
    let response = client.get(GOOGLE_SA_CERTS_URL).send().await?;
    let text = response.text().await?;
    let certs = Certs::from_json(&text)?;
    Ok(certs)
}

async fn get_cached_certs() -> MyResult<Certs> {
    let cache = CERT_CACHE.read().await;
    if let Some(entry) = cache.get("google") {
        if entry.expires > Instant::now() {
            return Ok(entry.certs.clone());
        }
    }
    drop(cache);

    let certs = fetch_certs().await?;
    let mut cache = CERT_CACHE.write().await;
    let expires = Instant::now() + Duration::from_secs(60 * 60 * 24); // 24 hours
    cache.insert("google".to_string(), CacheEntry { certs, expires });
    Ok(certs)
}

fn get_cert_from_certs(certs: &Certs, alg: &str, kid: &str) -> MyResult<Cert> {
    for cert in &certs.certs {
        if cert.alg == alg && cert.kid == kid {
            return Ok(cert.clone());
        }
    }
    Err("Certificate not found".into())
}

fn get_cert_from_cache(alg: &str, kid: &str) -> MyResult<Cert> {
    let certs = get_cached_certs().await?;
    get_cert_from_certs(&certs, alg, kid)
}

pub async fn get_cert(&self, alg: &str, kid: &str) -> MyResult<Cert> {
    get_cert_from_cache(alg, kid)
}

