fn progress_bar(percent: f32, width: usize) -> String {
    if percent < 0.0 {
        percent = 0.0;
    } else if percent > 1.0 {
        percent = 1.0;
    }

    let filled = (percent * width as f32) as usize;
    let empty = width - filled;

    let red = (255.0 * percent) as u8;
    let green = (255.0 * (1.0 - percent)) as u8;
    let blue = 0;

    let filled_str: String = (0..filled)
        .map(|_| {
            let r = (red as f32 * (percent * (filled as f32 / width as f32))) as u8;
            let g = (green as f32 * (1.0 - percent * (filled as f32 / width as f32))) as u8;
            let b = blue;
            format!("{}[{};{};{}m{}", Colour::RGB(r, g, b).style(), r, g, b, '█')
        })
        .collect();

    let empty_str: String = (0..empty)
        .map(|_| {
            let r = (red as f32 * (percent * (empty as f32 / width as f32))) as u8;
            let g = (green as f32 * (1.0 - percent * (empty as f32 / width as f32))) as u8;
            let b = blue;
            format!("{}[{};{};{}m{}", Colour::RGB(r, g, b).style(), r, g, b, ' ')
        })
        .collect();

    let mut result = String::new();
    write!(&mut result, "{}{}", filled_str, empty_str).unwrap();
    result
}

