fn calculate_total_mint_cost(stages: &[Stage], mut nfts_to_mint: u32) -> Option<u128> {
    let mut total_cost: u128 = 0;
    let mut remaining_nfts = nfts_to_mint;

    for stage in stages {
        if remaining_nfts == 0 {
            break;
        }

        if stage.mint_limit > 0 && stage.mint_limit < remaining_nfts {
            total_cost += stage.price.u128() * stage.mint_limit as u128;
            remaining_nfts -= stage.mint_limit;
        } else if stage.mint_limit > 0 && stage.mint_limit >= remaining_nfts {
            total_cost += stage.price.u128() * remaining_nfts as u128;
            remaining_nfts = 0;
        } else {
            total_cost += stage.price.u128() * remaining_nfts as u128;
            remaining_nfts = 0;
        }
    }

    if remaining_nfts > 0 {
        return None;
    }

    Some(total_cost)
}

use crate::PrefixedApiKey;
use std::collections::HashMap;
use rand::{Rng, distributions::Uniform};
use std::cmp::Ordering;

fn validate_api_key_security(key: &PrefixedApiKey, min_entropy_bits: f64) -> Result<(), String> {
    // Check prefix
    if key.prefix.is_empty() {
        return Err("API key prefix cannot be empty".to_string());
    }

    // Check suffix length
    if key.suffix.len() < 16 {
        return Err("API key suffix must be at least 16 characters long".to_string());
    }

    // Check if suffix contains only alphanumeric characters
    if !key.suffix.chars().all(|c| c.is_alphanumeric()) {
        return Err("API key suffix must contain only alphanumeric characters".to_string());
    }

    // Calculate entropy of the suffix
    let entropy = calculate_entropy(&key.suffix);

    // Check if entropy meets minimum requirement
    if entropy < min_entropy_bits {
        return Err(format!("API key suffix has insufficient entropy ({} bits < {} bits)", entropy, min_entropy_bits));
    }

    // Additional security checks (e.g., no common patterns, etc.)
    if has_common_pattern(&key.suffix) {
        return Err("API key suffix contains a common pattern".to_string());
    }

    Ok(())
}

fn calculate_entropy(s: &str) -> f64 {
    let mut freq = HashMap::new();
    for c in s.chars() {
        *freq.entry(c).or_insert(0) += 1;
    }

    let total_chars = s.len() as f64;
    let mut entropy = 0.0;

    for &count in freq.values() {
        let prob = count / total_chars;
        entropy -= prob * prob.log2();
    }

    entropy
}

fn has_common_pattern(s: &str) -> bool {
    // Check for common patterns like all digits, all lowercase, etc.
    if s.chars().all(|c| c.is_ascii_digit()) {
        return true;
    }

    if s.chars().all(|c| c.is_ascii_lowercase()) {
        return true;
    }

    if s.chars().all(|c| c.is_ascii_uppercase()) {
        return true;
    }

    // Check for simple repeating patterns
    let mut prev_char = s.chars().next();
    if let Some(first) = prev_char {
        let mut count = 1;
        for c in s.chars().skip(1) {
            if c == first {
                count += 1;
            } else {
                break;
            }
        }
        if count >= s.len() {
            return true;
        }
    }

    false
}

use bincode::serialize;
use solana_transaction::Transaction;
use solana_transaction_error::TransportResult;
use solana_connection_cache::connection_cache::{ConnectionPool, ConnectionManager, NewConnectionConfig};

fn send_transactions_with_fanout(&self, transactions: &[Transaction]) -> TransportResult<()> {
    let config = NewConnectionConfig::default();
    let manager = ConnectionManager::new(config);
    let pool = ConnectionPool::new(manager);

    for transaction in transactions {
        let serialized = serialize(transaction).map_err(|e| {
            solana_transaction_error::TransactionError::SerializationError(e.to_string())
        })?;

        for connection in pool.borrow_connections() {
            let result = connection.send_transaction(&serialized);
            if let Err(e) = result {
                // Handle error, perhaps log or retry
                eprintln!("Failed to send transaction: {}", e);
            }
        }
    }

    Ok(())
}

use pg_async::{PgOperation, PgQueryPiece};

fn batch_insert(table: &str, columns: &[&str], rows: Vec<Vec<&str>>) -> PgOperation {
    if rows.is_empty() {
        return PgOperation::Query(PgQueryPiece::new("BEGIN; COMMIT;"));
    }

    let mut query = String::new();
    query.push_str("BEGIN; ");

    let mut values = Vec::new();
    for row in rows {
        let mut row_values = Vec::new();
        for &value in row.iter() {
            row_values.push(PgQueryPiece::new(value));
        }
        values.push(row_values);
    }

    let mut insert_clause = String::new();
    insert_clause.push_str("INSERT INTO ");
    insert_clause.push_str(table);
    insert_clause.push_str(" (");
    insert_clause.push_str(columns.join(", "));
    insert_clause.push_str(") VALUES ");

    let mut value_clauses = Vec::new();
    for row_values in values {
        let mut clause = String::new();
        clause.push_str("(");
        for (i, value) in row_values.iter().enumerate() {
            if i > 0 {
                clause.push_str(", ");
            }
            clause.push_str(value);
        }
        clause.push_str(")");
        value_clauses.push(PgQueryPiece::new(clause));
    }

    let value_clause = PgQueryPiece::new(value_clauses.join(", "));
    let full_query = PgQueryPiece::new(format!("{}{}", insert_clause, value_clause));

    query.push_str(&full_query.to_string());
    query.push_str(" COMMIT;");

    PgOperation::Query(PgQueryPiece::new(query))
}

