fn fetch_supported_protocols<R>(io: R) -> Result<Vec<String>, NegotiationError>
where
    R: AsyncRead + AsyncWrite + Unpin,
{
    let mut reader = MessageIO::new(io);
    let msg = Message::new(b"ls");

    // Send the 'ls' request
    reader.write_message(&msg).await?;

    // Read the response
    let response = reader.read_message().await?;

    // Extract the list of protocols
    let protocols = match response {
        Message::List(protocols) => protocols,
        _ => return Err(NegotiationError::InvalidMessage),
    };

    Ok(protocols.iter().map(|p| p.to_string()).collect())
}

