fn run_transaction_with_retry<F, Fut>(pool: &bb8::Pool<async_bb8_diesel::ConnectionManager<PgConnection>>, operation: F) -> Result<(), async_bb8_diesel::ConnectionError>
where
    F: Fn(async_bb8_diesel::Connection<PgConnection>) -> Fut + Send + Sync + 'static,
    Fut: std::future::Future<Output = Result<(), async_bb8_diesel::ConnectionError>> + Send,
{
    let mut conn = pool.get().map_err(|e| async_bb8_diesel::ConnectionError::Inner(e))?; // Acquire a connection
    let mut retries = 0;
    let max_retries = 5;

    loop {
        match operation(conn.clone()).await {
            Ok(()) => return Ok(()),
            Err(err) => {
                if let Some(ConnectionError::Inner(ConnectionError::DatabaseError(_, ref error))) = err {
                    if error.code() == "40001" && retries < max_retries {
                        // CockroachDB serialization failure, retry
                        retries += 1;
                        conn = pool.get().map_err(|e| async_bb8_diesel::ConnectionError::Inner(e))?;
                        continue;
                    }
                }
                return Err(err);
            }
        }
    }
}

use crate::types::header_map::memory::MemoryMap;
use ckb_metrics::HistogramTimer;

fn optimize_header_map_memory(memory_map: &mut MemoryMap, max_limit: usize) {
    if memory_map.len() <= max_limit {
        return;
    }

    let timer = HistogramTimer::new("header_map_optimize_timer");
    let mut entries: Vec<_> = memory_map.entries().collect();
    entries.sort_by_key(|entry| entry.0); // Sort by header hash (assuming it's the oldest first)
    let excess = entries.len() - max_limit;

    for i in 0..excess {
        let header_hash = entries[i].0;
        memory_map.remove(&header_hash);
    }

    timer.observe_duration();
}

