fn generate_vanity_regex_mnemonic(pattern: &str, timeout_secs: u64) -> anyhow::Result<()> {
    let regex_matcher = RegexMatcher::new(pattern)?;
    let (address, secret_key) = find_vanity_address_with_timeout(regex_matcher, timeout_secs)?;

    let checksummed_address = checksum_encode(&address);
