}

fn generate_mnemonic_from_secret_key(secret_key: &SecretKey) -> String {
    let seed = secret_key.to_bytes();
    let mnemonic = bip39::Mnemonic::generate(128);
    let seed_phrase = mnemonic.phrase();
    let seed_bytes = bip39::Seed::new(seed_phrase, "").to_bytes();

    let mut derived_key = hkdf::Hkdf::<sha2::Sha256>::new(None, &seed_bytes);
    let key = derived_key.derive(b"mnemonic seed", &seed);

    hex::encode(key)
}

