use std::io;
use std::process;
use std::fs;
use std::os::unix::fs::FileExt;
use std::os::unix::io::RawFd;
use std::os::unix::io::FromRawFd;

fn get_process_cmdline(port: u16) -> Result<Option<String>, io::Error> {
    // On Unix, we can look up the process listening on a port by checking /proc/<pid>/fd/<fd>
    // and then reading /proc/<pid>/cmdline.

    // First, find the PID of the process listening on the given port.
    let pid = match find_pid_by_port(port) {
        Ok(pid) => pid,
        Err(e) => return Err(e),
    };

    // Then, read the command line from /proc/<pid>/cmdline.
    let cmdline = match read_cmdline_from_pid(pid) {
        Ok(cmdline) => cmdline,
        Err(e) => return Err(e),
    };

    Ok(Some(cmdline))
}

fn find_pid_by_port(port: u16) -> Result<u32, io::Error> {
    // On Unix, we can use lsof to find the PID of the process listening on the port.
    // Alternatively, we can use netstat or ss, but for simplicity, we use lsof.
    let output = process::Command::new("lsof")
        .arg("-i")
        .arg(format!(":{}", port))
        .arg("-t")
        .output()
        .map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

    if output.status.success() {
        let stdout = String::from_utf8_lossy(&output.stdout);
        let pid_str = stdout.trim();
        if pid_str.is_empty() {
            return Ok(0); // No process found
        }
        let pid: u32 = pid_str.parse().map_err(|_| io::Error::new(io::ErrorKind::Other, "Invalid PID"))?;
        Ok(pid)
    } else {
        let stderr = String::from_utf8_lossy(&output.stderr);
        Err(io::Error::new(io::ErrorKind::Other, stderr))
    }
}

fn read_cmdline_from_pid(pid: u32) -> Result<String, io::Error> {
    let path = format!("/proc/{}/cmdline", pid);
    let file = fs::File::open(path).map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

    let mut buffer = Vec::new();
    file.read_to_end(&mut buffer).map_err(|e| io::Error::new(io::ErrorKind::Other, e))?;

    // Each argument is null-separated, so we split on NUL bytes.
    let cmdline: Vec<&str> = buffer.split(|&c| c == 0).collect();
    let cmdline = cmdline.join(" ");
    Ok(cmdline)
}

use std::collections::{HashMap, HashSet};
use std::path::PathBuf;
use crate::geyser_plugin_manager::GeyserPluginManager;

pub struct PluginLoader {
    plugin_manager: GeyserPluginManager,
}

impl PluginLoader {
    pub fn new() -> Self {
        Self {
            plugin_manager: GeyserPluginManager::new(),
        }
    }

    pub fn load_plugins(&mut self, plugin_deps: HashMap<String, Vec<String>>) -> Result<(), String> {
        let mut graph: HashMap<String, HashSet<String>> = HashMap::new();
        let mut nodes: HashSet<String> = HashSet::new();

        // Build the dependency graph
        for (plugin, deps) in plugin_deps {
            nodes.insert(plugin.clone());
            graph.insert(plugin, HashSet::new());

            for dep in deps {
                nodes.insert(dep.clone());
                graph.entry(dep).or_insert_with(HashSet::new).insert(plugin.clone());
            }
        }

        // Perform topological sort
        let mut sorted_plugins = Vec::new();
        let mut visited = HashSet::new();
        let mut recursion_stack = HashSet::new();

        fn dfs(
            plugin: &str,
            graph: &HashMap<String, HashSet<String>>,
            visited: &mut HashSet<String>,
            recursion_stack: &mut HashSet<String>,
            sorted_plugins: &mut Vec<String>,
        ) -> bool {
            if recursion_stack.contains(plugin) {
                return false; // Cycle detected
            }

            if visited.contains(plugin) {
                return true;
            }

            recursion_stack.insert(plugin.to_string());
            if let Some(dependencies) = graph.get(plugin) {
                for dep in dependencies {
                    if !dfs(dep, graph, visited, recursion_stack, sorted_plugins) {
                        return false;
                    }
                }
            }

            recursion_stack.remove(plugin);
            visited.insert(plugin.to_string());
            sorted_plugins.push(plugin.to_string());
            true
        }

        for plugin in nodes.iter() {
            if !visited.contains(plugin) {
                if !dfs(plugin, &graph, &mut visited, &mut recursion_stack, &mut sorted_plugins) {
                    return Err("Cycle detected in plugin dependencies".to_string());
                }
            }
        }

        // Load plugins in topological order
        for plugin in sorted_plugins {
            let plugin_path = PathBuf::from(format!("plugins/{}.so", plugin));
            match self.plugin_manager.load_plugin(plugin_path) {
                Ok(_) => {}
                Err(e) => return Err(format!("Failed to load plugin '{}': {}", plugin, e)),
            }
        }

        Ok(())
    }
}

use crate::cli::{is_h256, is_hex};

fn validate_block_assembler(code_hash: &str, args: &[String]) -> Result<(), String> {
    if !is_hex(code_hash) {
        return Err("Invalid code hash format. Must be a hexadecimal string.".to_string());
    }

    if !is_h256(code_hash) {
        return Err("Invalid code hash. Must be a 64-character hexadecimal string.".to_string());
    }

    if args.is_empty() {
        return Err("Argument list cannot be empty.".to_string());
    }

    for arg in args {
        if !is_hex(arg) {
            return Err(format!("Invalid argument: {}", arg));
        }
    }

    Ok(())
}

use vcd::{Parser, Command, IdCode, Value};

fn extract_signal_waveform<R: std::io::BufRead>(parser: &mut Parser<R>, signal_id: IdCode) -> std::io::Result<Vec<bool>> {
    let mut waveform = Vec::new();
    let mut last_value = None;

    while let Some(command) = parser.next() {
        match command {
            Command::VarDecl { id, .. } if id == signal_id => {
                // Initialize the waveform with a false value
                waveform.push(false);
                last_value = Some(Value::from("0"));
            }
            Command::Value { id, value, .. } if id == signal_id => {
                let current_value = Value::from(value);
                if let Some(last) = last_value {
                    if last != current_value {
                        waveform.push(true);
                        last_value = Some(current_value);
                    } else {
                        waveform.push(false);
                        last_value = Some(current_value);
                    }
                } else {
                    waveform.push(false);
                    last_value = Some(current_value);
                }
            }
            _ => {}
        }
    }

    Ok(waveform)
}

use actix::Addr;
