fn fetch_block_with_retry(
    client: &Addr<ViewClientActor>,
    height: u64,
    attempts: u8,
) -> Result<BlockView, Error> {
    let mut retries = attempts;
    let mut delay = time::Duration::from_secs(1);

    loop {
        if retries == 0 {
            return Err(Error::msg("Max retries exceeded"));
        }

        match fetch_block_by_height(client, height).map(|res| res?) {
            Ok(block) => return Ok(block),
            Err(e) => {
                tracing::warn!("Failed to fetch block by height: {}, retrying in {}s", e, delay.as_secs());
                retries -= 1;
                tokio::time::sleep(delay).await;
                delay *= 2;
            }
        }
    }
}

