fn rewrite_delayed_receipts(
    trackers: Vec<DelayedReceiptTracker>,
    shard_tries: &ShardTries,
    source_state_roots: &HashMap<ShardUId, StateRoot>,
    target_shard_layout: &ShardLayout,
    default_key: &PublicKey,
) -> anyhow::Result<()> {
    let mut updates = HashMap::new();
    let mut next_index = 0;

    for tracker in trackers {
        let shard_uid = tracker.shard_uid;
        let state_root = source_state_roots
            .get(&shard_uid)
            .context("Missing state root for source shard")?;

        let trie = shard_tries
            .get_trie(state_root)
            .context("Failed to get trie for source shard")?;

        let receipts = tracker.receipts;

        for (index, receipt) in receipts.iter().enumerate() {
            let receipt = read_delayed_receipt(trie, shard_uid, index as u64)?;
            if let Some(receipt) = receipt {
                let mut receipt = receipt;
                near_mirror::key_mapping::map_account(&mut receipt.receiver_id, default_key);
                set_target_delayed_receipt(
                    &mut updates,
                    &mut next_index,
                    receipt,
                    default_key,
                );
            }
        }
    }

    for (shard_idx, entries) in updates {
        let shard_uid = target_shard_layout.shard_uids()[shard_idx as usize];
        let trie = shard_tries
            .get_trie(&StateRoot::default())
            .context("Failed to get trie for target shard")?;
        for (index, bytes) in entries {
            let key = TrieKey::DelayedReceipt { index };
            near_store::set(trie, &key, bytes.as_ref())?;
        }
    }

    Ok(())
}

pub struct BlockhashProvider {
    rpc: Arc<RpcClient>,
    refresh_interval: Duration,
    cached_blockhash: RwLock<Option<Hash>>,
    refresh_task: Option<JoinHandle<()>>,
}

impl BlockhashProvider {
    pub fn new(rpc: Arc<RpcClient>, refresh_interval: Duration) -> Self {
        let cached_blockhash = RwLock::new(None);
        let refresh_task = Some(tokio::spawn(async move {
            loop {
                let blockhash = rpc.get_latest_blockhash().await.unwrap();
                *cached_blockhash.write().unwrap() = Some(blockhash);
                tokio::time::sleep(refresh_interval).await;
            }
        }));
        BlockhashProvider {
            rpc,
            refresh_interval,
            cached_blockhash,
            refresh_task,
        }
    }

    pub async fn get_blockhash(&self) -> Hash {
        let mut blockhash = self.cached_blockhash.write().await;
        if blockhash.is_none() {
            let blockhash = self.rpc.get_latest_blockhash().await.unwrap();
            *blockhash = Some(blockhash);
        }
        blockhash.as_ref().unwrap().clone()
    }
}

