use difflib::unified_diff;

fn custom_unified_diff(
    first: &[&str],
    second: &[&str],
    from_file: &str,
    to_file: &str,
    from_date: &str,
    to_date: &str,
    context: usize,
    delimiter: &str,
) -> Vec<String> {
    let diff = unified_diff(
        first,
        second,
        from_file,
        to_file,
        from_date,
        to_date,
        context,
    );

    let mut result = Vec::new();
    let mut header = format!("{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}", delimiter, delimiter, delimiter, delimiter, delimiter, delimiter, delimiter, delimiter);

    for line in diff {
        if line.starts_with("@@") {
            result.push(header.clone());
            result.push(line);
        } else {
            result.push(line);
        }
    }

    result
}

fn filter_outliers_by_score(
    data: &Array2<f64>,
    alpha: f64,
    min_samples: usize,
    min_cluster_size: usize,
    threshold: f64,
) -> (HashMap<usize, Vec<usize>>, Vec<usize>) {
    let mut model = HDbscan::new();
    model.set_alpha(alpha);
    model.set_min_samples(min_samples);
    model.set_min_cluster_size(min_cluster_size);
    model.set_distance(Euclidean);

    let labels = model.fit(data).unwrap();

    let mut clusters = HashMap::new();
    let mut outliers = Vec::new();

    for (index, &label) in labels.iter().enumerate() {
        if label >= 0 {
            clusters.entry(label).or_insert_with(Vec::new).push(index);
        } else {
            outliers.push(index);
        }
    }

    let mut filtered_clusters = HashMap::new();
    for (&cluster_id, &mut members) in &mut clusters {
        let has_outlier_above_threshold = members.iter().any(|&idx| {
            let outlier_score = model.get_outlier_scores().get(idx).copied().unwrap_or(0.0);
            outlier_score > threshold
        });

        if has_outlier_above_threshold {
            filtered_clusters.insert(cluster_id, members.clone());
        }
    }

    (filtered_clusters, outliers)
}

use bcmp::Match;

fn validate_patch_set(first: &[u8], second: &[u8], patches: &[Match]) -> bool {
    if patches.is_empty() {
        return first == second;
    }

    let mut prev_end = 0;
    let mut prev_second_start = 0;
    let mut prev_second_end = 0;

    for match_info in patches {
        let Match {
            first_start,
            first_end,
            second_start,
            second_end,
            ..
        } = match_info;

        // Check that the patch is within the bounds of the first and second slices
        if first_start >= first.len() || first_end > first.len() || second_start >= second.len() || second_end > second.len() {
            return false;
        }

        // Check that the patch does not overlap with the previous one
        if first_start < prev_end || second_start < prev_second_end {
            return false;
        }

        // Check that the patch is consistent with the source and target data
        if &first[first_start..first_end] != &second[second_start..second_end] {
            return false;
        }

        // Update previous positions
        prev_end = first_end;
        prev_second_start = second_start;
        prev_second_end = second_end;
    }

    // Check that the entire first and second slices are covered by the patches
    if prev_end != first.len() || prev_second_end != second.len() {
        return false;
    }

    true
}

fn filter_events(events: Vec<SixelEvent>) -> (Vec<SixelEvent>, Vec<SixelEvent>, Vec<SixelEvent>) {
