}

fn find_ancestor_with_kind<T: KindTypes>(cursor: &Cursor<T>, kind: T::NonterminalKind) -> Option<Cursor<T>> {
    let mut current = cursor.clone();
    while let Some(node) = current.node() {
        if node.kind() == kind {
            return Some(current);
        }
        current = current.parent()?;
    }
    None
}

