fn write_uniform_bandwidth_state(
    shard_tries: &ShardTries,
    target_shard_layout: &ShardLayout,
) -> Result<()> {
    let num_shards = target_shard_layout.num_shards();
    let mut bandwidth_state = BandwidthSchedulerState::new();
    let mut link_allowance = LinkAllowance::new();
    link_allowance.set_allowance(1000000000); // Example uniform allowance value

    for shard_id in target_shard_layout.shard_ids() {
        let mut state = BandwidthSchedulerStateV1::new();
        for receiver in 0..num_shards {
            state.add_link_allowance(LinkAllowance::new().set_allowance(1000000000));
        }
        let state_hash = CryptoHash::hash(&state);
        let mut update_state = ShardUpdateState::default();
        update_state.set_state(state_hash);
        StorageMutator::apply_update(shard_tries, shard_id, update_state)?;
    }

    Ok(())
}

use anyhow::Result;
use collections::HashSet;
use fs::Fs;
use std::path::Path;
use std::ops::ControlFlow;
use util::paths::PathMatcher;
use crate::Prettier;

fn is_prettier_ignored(fs: &dyn Fs, file_path: &Path) -> Result<bool> {
    // Find the nearest .prettierignore file
    let ignore_file = find_nearest_prettierignore(fs, file_path)?;

    // Read the ignore file content
    let ignore_content = fs.read_to_string(&ignore_file)?;

    // Parse the ignore patterns
    let ignore_patterns = parse_prettierignore_content(&ignore_content)?;

    // Check if the file path matches any pattern
    for pattern in &ignore_patterns {
        if PathMatcher::new(pattern).matches(file_path) {
            return Ok(true);
        }
    }

    Ok(false)
}

fn find_nearest_prettierignore(fs: &dyn Fs, file_path: &Path) -> Result<Path> {
    let mut current_dir = file_path.parent().unwrap_or(file_path);

    loop {
        let ignore_path = current_dir.join(".prettierignore");
        if fs.exists(&ignore_path) {
            return Ok(ignore_path);
        }

        if current_dir == current_dir.parent().unwrap_or(current_dir) {
            // Prevent infinite loop if no .prettierignore is found
            break;
        }

        current_dir = current_dir.parent().unwrap_or(current_dir);
    }

    Err(anyhow::anyhow!("No .prettierignore file found"))
}

fn parse_prettierignore_content(content: &str) -> Result<HashSet<String>> {
    let mut patterns = HashSet::new();

    for line in content.lines() {
        let line = line.trim();
        if !line.is_empty() && !line.starts_with('#') {
            patterns.insert(line.to_string());
        }
    }

    Ok(patterns)
}

use datafusion_common::{Result, Expr, col, lit, DataFusionError};
use datafusion_expr::{Operator, Expr as ExprType};

fn build_complex_filters(
    filters: &[(String, String)],
    logical_operator: Operator,
) -> Result<Expr> {
    if filters.is_empty() {
        return Ok(lit(false));
    }

    let mut exprs = Vec::new();

    for (column, value) in filters {
        let column_expr = col(column);
        let value_expr = lit(value.parse().map_err(|_| DataFusionError::Plan(format!("Invalid value: {}", value)))?);
        exprs.push(ExprType::BinaryExpr {
            left: Box::new(column_expr),
            right: Box::new(value_expr),
            op: Operator::Eq,
        });
    }

    match logical_operator {
        Operator::And => Ok(Expr::And(exprs)),
        Operator::Or => Ok(Expr::Or(exprs)),
        _ => Err(DataFusionError::Plan(format!("Unsupported logical operator: {:?}", logical_operator))),
    }
}

fn cpu_id_map<'dt>(index: &DevTreeIndex<'dt, 'dt>) -> Result<HashMap<u32, String>, DevTreeError> {
    let mut cpu_id_to_node_name = HashMap::new();
    let root = index.root();
    let nodes = root.children();

    for node in nodes {
        if node.name() == "cpu" {
            if let Some(cpu_id) = node.get_property("reg") {
                if let Ok(cpu_id) = cpu_id.parse::<u32>() {
                    let node_name = format!("cpu@{}", cpu_id);
                    cpu_id_to_node_name.insert(cpu_id, node_name);
                }
            }
        }
    }

    Ok(cpu_id_to_node_name)
}

use jwks_client::keyset::KeyStore;
use jwks_client::error;
use std::time::{SystemTime, Duration};
use jwt::VerifyWithKey;
use jwt::prelude::*;

fn jwt_expiry_in_window(token: &str, jwks_url: &str) -> Result<bool, jwks_client::error::Error> {
    let key_set = KeyStore::from_url(jwks_url)?;
    let token_data = jwt::TokenData::parse(token)?;

    let header = token_data.header();
    let payload = token_data.payload();

    if header.alg != jwt::Algorithm::HS256 {
        return Ok(false);
    }

    let now = SystemTime::now();
    let expiry = payload.get_claim("exp").and_then(|v| v.as_i64()).ok_or(jwks_client::error::Error::InvalidToken)?;

    let expiry_time = SystemTime::UNIX_EPOCH + Duration::from_secs(expiry as u64);
    let time_until_expiry = expiry_time.duration_since(now)?;

    let min_window = Duration::from_minutes(5);
    let max_window = Duration::from_minutes(10);

    Ok(time_until_expiry >= min_window && time_until_expiry <= max_window)
}

use anyhow::Result;
use cargo_metadata::Metadata;
