fn build_all_masm(manifest_path: &std::path::Path) -> Result<Vec<std::path::PathBuf>> {
    let metadata: Metadata = load_from_path(manifest_path)?;
    let mut targets = metadata.target_graph.targets.clone();
    let mut wasm_targets = vec![];

    for target in &targets {
        if target.name.starts_with("wasm32") {
            wasm_targets.push(target.name.clone());
        }
    }

    if wasm_targets.is_empty() {
        wasm_targets.push("wasm32-wasip1".to_string());
    }

    let mut masm_paths = vec![];

    for target in wasm_targets {
        let args = CargoArguments {
            manifest_path: manifest_path.to_path_buf(),
            target: target.clone(),
            args: vec!["build".to_string(), "--target".to_string(), target],
        };

        let result = run_cargo_command(&args)?;
        if let Some(output) = result.stdout {
            for line in output.lines() {
                if line.starts_with("generated masm file: ") {
                    if let Some(path) = line.strip_prefix("generated masm file: ") {
                        if let Ok(path_buf) = std::path::PathBuf::from(path) {
                            masm_paths.push(path_buf);
                        }
                    }
                }
            }
        }
    }

    Ok(masm_paths)
}

fn split_at<const N: usize, T>(buf: &mut Buffer<[T; N]>, pos: usize) -> (Buffer<[T; N]>, Buffer<[T; N]>) 
where 
    T: Copy,
{
    let len = buf.len();
    if pos > len {
        panic!("Position exceeds buffer length");
    }

    let header_data = buf.data[..pos].to_vec();
    let payload_data = buf.data[pos..].to_vec();

    let header_buffer = Buffer::new(header_data);
    let payload_buffer = Buffer::new(payload_data);

    // Clear the original buffer
    buf.data.fill(T::default());

    (header_buffer, payload_buffer)
}

fn list_open_proposals(
