fn average_latency(latencies: &[Option<Duration>]) -> Option<Duration> {
    let mut total = Duration::zero();
    let mut count = 0;
    for &latency in latencies {
        if let Some(duration) = latency {
            total += duration;
            count += 1;
        }
    }
    if count == 0 {
        return None;
    }
    Some(total / count)
}

use bonsai_sdk::blocking::Client;
use bonsai_sdk::SdkErr;

fn upload_image_retry(client: &Client, image_id: &str, data: Vec<u8>) -> Result<bool, SdkErr> {
    let mut retries = 3;
    let mut success = false;

    while retries > 0 {
        match client.upload_image(image_id, data.clone()) {
            Ok(_) => {
                success = true;
                break;
            }
            Err(e) => {
                if e.is_transient() {
                    warn!("Transient error uploading image: {}", e);
                    retries -= 1;
                    continue;
                } else {
                    return Err(e);
                }
            }
        }
    }

    if success {
        Ok(true)
    } else {
        Ok(false)
    }
}

