struct WorkerTracker {
    tx: mpsc::Sender<String>,
    peers: Vec<String>,
}

impl WorkerTracker {
    fn new(discoverer: Discoverer, key: &str, value: Option<&str>) -> (Self, DropGuard) {
        let (tx, mut rx) = mpsc::channel(100);
        let drop_guard = discoverer.start(move |peer: &Peer| {
            if let Some(txt) = peer.txt() {
                if txt.get(key).map_or(false, |v| v == value) {
                    if let Some(id) = peer.id() {
                        if tx.send(id.to_string()).await.is_ok() {
                            // Optionally handle send errors if needed
                        }
                    }
                }
            }
        });

        let tracker = WorkerTracker {
            tx,
            peers: Vec::new(),
        };

        // Spawn a task to collect peers in a vector
        tokio::spawn(async move {
            while let Some(id) = rx.recv().await {
                tracker.peers.push(id);
            }
        });

        (tracker, drop_guard)
    }

    fn get_peers(&self) -> &[String] {
        &self.peers
    }
}

use apache_avro::Schema as AvroSchema;
use arrow::datatypes::{Field, Schema as ArrowSchema};
use datafusion_common::Result;
use crate::avro_to_arrow::schema::{schema_to_field, schema_to_field_with_props};

fn create_projection_schema(avro_schema: &AvroSchema, projection: &[&str]) -> Result<ArrowSchema> {
    let mut fields = Vec::new();
    for &path in projection {
        if let Some(field) = parse_and_extract_field(avro_schema, path) {
            fields.push(field);
        }
    }
    Ok(ArrowSchema::new(fields))
}

fn parse_and_extract_field(schema: &AvroSchema, path: &str) -> Option<Field> {
    let mut current_schema = schema;
    let mut current_path = path.split('.');
    let mut field_name = current_path.next()?;

    while let Some(next_name) = current_path.next() {
        if let Some(field) = current_schema.as_record().and_then(|r| r.fields.iter().find(|f| f.name() == field_name)) {
            current_schema = field.schema();
            field_name = next_name;
        } else {
            return None;
        }
    }

    if let Some(field) = current_schema.as_record().and_then(|r| r.fields.iter().find(|f| f.name() == field_name)) {
        schema_to_field_with_props(field, None)
    } else if let Some(field) = current_schema.as_union().and_then(|u| u.types.iter().find(|t| t.as_record().is_some())) {
        if let Some(record) = field.as_record() {
            if let Some(f) = record.fields.iter().find(|f| f.name() == field_name) {
                schema_to_field_with_props(f, None)
            } else {
                return None;
            }
        } else {
            return None;
        }
    } else if let Some(field) = current_schema.as_map().and_then(|m| m.items().as_record()) {
        if let Some(f) = field.fields.iter().find(|f| f.name() == field_name) {
            schema_to_field_with_props(f, None)
        } else {
            return None;
        }
    } else {
        return None;
    }
}

