fn dialer_select_with_retry<R, I>(
    inner: R,
    protocols: I,
    version: Version,
) -> Result<(String, Negotiated<R>), NegotiationError>
where
    R: AsyncRead + AsyncWrite + Unpin,
    I: IntoIterator,
    I::Item: AsRef<str>,
{
    let mut protocols = protocols.into_iter();
    let mut protocol_name = String::new();
    let mut negotiated = None;

    while let Some(protocol) = protocols.next() {
        let protocol = protocol.as_ref();
        protocol_name = protocol.to_string();
        let mut negotiated = Negotiated::new(inner, protocol, version);
        let mut stream = negotiated.get_mut();

        match negotiate_protocol(&mut stream, protocol).await {
            Ok(_) => {
                negotiated.set_protocol(protocol.to_string());
                return Ok((protocol_name, negotiated));
            }
            Err(NegotiationError::NotAvailable) => {
                continue;
            }
            Err(e) => return Err(e),
        }
    }

    Err(NegotiationError::NoProtocolAvailable)
}

async fn negotiate_protocol<R>(stream: &mut MessageIO<R>, protocol: &str) -> Result<(), NegotiationError>
where
    R: AsyncRead + AsyncWrite + Unpin,
{
    let header = HeaderLine::new("Protocol", protocol);
    let message = Message::new(header, vec![]);
    let mut writer = stream.write_message(message).await?;

    match stream.read_message().await {
        Ok(Message::Response(200, _)) => Ok(()),
        Ok(Message::Response(code, _)) if code == 400 => Err(NegotiationError::NotAvailable),
        Ok(_) => Err(NegotiationError::UnexpectedMessage),
        Err(e) => Err(e),
    }
}

fn aggregate_stats<K, V>(caches: &[&HybridCache<K, V, DefaultHasher>]) -> (usize, f64) {
    let mut total_memory = 0;
    let mut total_hits = 0;
    let mut total_accesses = 0;

    for &cache in caches {
        if let Some(stats) = cache.stats() {
            total_memory += stats.memory_usage;
            total_hits += stats.hits;
            total_accesses += stats.accesses;
        }
    }

    let hit_ratio = if total_accesses > 0 { total_hits as f64 / total_accesses as f64 } else { 0.0 };
    (total_memory, hit_ratio)
}

