fn validate_program_account(
    log_collector: &Option<Rc<RefCell<LogCollector>>>,
    instruction_context: &InstructionContext,
    program: &BorrowedAccount,
    authority_address: &Pubkey,
) -> Result<(), InstructionError> {
    // Check if the account is a program account
    if !program.is_program() {
        return Err(InstructionError::AccountNotProgram);
    }

    // Get the program's loader state
    let loader_state = match program.loader_state() {
        Some(state) => state,
        None => return Err(InstructionError::InvalidAccountData),
    };

    // Check if the account is a loader v4 program
    if let loader_v4::LoaderV4State::Program {
        authority,
        data,
        writable,
        ..
    } = loader_state
    {
        // Check if the provided authority matches the stored authority
        if authority != *authority_address {
            return Err(InstructionError::IncorrectProgramAuthority);
        }

        // Check if the account is writable
        if !writable {
            return Err(InstructionError::AccountNotWritable);
        }

        // Check if the account has data
        if data.is_empty() {
            return Err(InstructionError::InvalidAccountData);
        }

        // If all checks passed, return Ok
        Ok(())
    } else {
        Err(InstructionError::InvalidAccountData)
    }
}

use rust_eth_kzg::{DASContext, Cell, KZGProof, Error};
use rust_eth_kzg::errors::VerifierError;

fn compute_cell_and_proof(blob: &[u8; rust_eth_kzg::constants::BYTES_PER_BLOB], cell_index: usize, ctx: &DASContext) -> Result<(Cell, KZGProof), Error> {
    if cell_index >= rust_eth_kzg::constants::MAX_CELLS {
        return Err(Error::InvalidCellIndex);
    }

    let cell_data = &blob[cell_index * rust_eth_kzg::constants::CELL_SIZE..(cell_index + 1) * rust_eth_kzg::constants::CELL_SIZE];
    let proof = ctx.compute_proof(cell_index, blob)?;

    Ok((Cell::from(cell_data), proof))
}

