use deepl::{DeepLApi, Lang};

fn translate_markdown_preserve_code(api: &DeepLApi, markdown: &str, target: Lang) -> Result<String, deepl::Error> {
    let mut result = String::new();
    let mut in_code_block = false;
    let mut buffer = String::new();

    for c in markdown.chars() {
        if c == '`' {
            if !in_code_block {
                // End of code block, translate the buffer
                if !buffer.is_empty() {
                    let translated = api.translate(buffer.as_str(), Lang::EN, target)?;
                    result.push_str(&translated);
                }
                result.push(c);
                in_code_block = true;
            } else {
                // End of code block, add the closing backtick
                result.push(c);
                in_code_block = false;
            }
        } else if in_code_block {
            // Inside code block, just append the character
            result.push(c);
        } else {
            // Outside code block, buffer the character
            buffer.push(c);
        }
    }

    if !in_code_block && !buffer.is_empty() {
        let translated = api.translate(buffer.as_str(), Lang::EN, target)?;
        result.push_str(&translated);
    }

    Ok(result)
}

fn stream_output_to_file(command: &str, args: &[&str], log_path: &std::path::Path) -> Result<deno_process::ChildProcess, Box<dyn std::error::Error>> {
    let child = Command::new(command)
        .args(args)
        .spawn()?;

    let log_file = File::create(log_path)?;
    let mut log_writer = BufReader::new(log_file);
    let mut log_writer = tokio::io::BufWriter::new(log_file);

    let stdout = child.stdout.take().ok_or("stdout not available")?;
    let stderr = child.stderr.take().ok_or("stderr not available")?;

    let stdout_handle = tokio::spawn(async move {
        let mut reader = BufReader::new(stdout);
        let mut buffer = Vec::new();
        loop {
            let n = reader.read_buf(&mut buffer).await?;
            if n == 0 {
                break;
            }
            log_writer.write_all(&buffer).await?;
            log_writer.flush().await?;
            buffer.clear();
        }
    });

    let stderr_handle = tokio::spawn(async move {
        let mut reader = BufReader::new(stderr);
        let mut buffer = Vec::new();
        loop {
            let n = reader.read_buf(&mut buffer).await?;
            if n == 0 {
                break;
            }
            log_writer.write_all(&buffer).await?;
            log_writer.flush().await?;
            buffer.clear();
        }
    });

    tokio::try_join!(stdout_handle, stderr_handle)?;

    Ok(child)
}

fn call_with_retry<R>(
    handler: &dyn easy_jsonrpc::Handler,
    method: easy_jsonrpc::BoundMethod<'static, R>,
    max_attempts: usize,
    base_delay_ms: u64,
) -> Result<R, easy_jsonrpc::ResponseFail>
where
    R: serde::de::DeserializeOwned,
{
    let mut attempts = 0;
    loop {
        attempts += 1;
        if attempts > max_attempts {
            return Err(easy_jsonrpc::ResponseFail::new("Max retries exceeded"));
        }

        match handler.call(method.clone()) {
            MaybeReply::Response(response) => {
                if let Some(result) = response.result {
                    return Ok(serde_json::from_value(result).unwrap());
                } else if let Some(error) = response.error {
                    if is_transient_error(&error) {
                        let delay = Duration::from_millis(base_delay_ms as u64 * (1 << (attempts - 1)));
                        std::thread::sleep(delay);
                        continue;
                    } else {
                        return Err(easy_jsonrpc::ResponseFail::new(&error.message));
                    }
                } else {
                    return Err(easy_jsonrpc::ResponseFail::new("Unexpected response format"));
                }
            }
            MaybeReply::Error(e) => {
                return Err(e);
            }
        }
    }
}

fn is_transient_error(error: &easy_jsonrpc::Error) -> bool {
    match error {
        easy_jsonrpc::Error::ParseError => true,
        easy_jsonrpc::Error::InvalidRequest => true,
        easy_jsonrpc::Error::MethodNotFound => true,
        easy_jsonrpc::Error::InvalidParams => true,
        easy_jsonrpc::Error::InternalError => true,
        _ => false,
    }
}

