fn purge_stale_entries(cache: &SqliteBackedCache, ttl_seconds: u64) -> Result<(), CacheError> {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .ok_or(CacheError::InvalidTime)?;

    let threshold = now.saturating_sub(ttl_seconds);

    spawn_blocking(move || {
        let conn = cache.connection()?;
        let mut stmt = conn.prepare("DELETE FROM request_response_list WHERE last_inserted_at < ?")?;
        stmt.execute(params![threshold])?;
        Ok::<(), CacheError>(())
    })
    .map_err(|e| CacheError::from(e))
}

