use log;

fn log_tokio_pool_utilization(manager: &ThreadManager, interval: Duration) {
    let mut interval = interval;
    loop {
        // Get the number of active and parked threads
        let active_threads = manager.active_threads().load(Ordering::Relaxed);
        let parked_threads = manager.parked_threads().load(Ordering::Relaxed);

        // Log the utilization
        log::info!("Tokio thread pool utilization: Active threads = {}, Parked threads = {}", active_threads, parked_threads);

        // Wait for the next interval
        std::thread::sleep(interval);
    }
}

fn join_human_times(times: &[HumanTime], conjunction: &str) -> String {
    if times.is_empty() {
        return String::new();
    }

    let mut result = String::new();
    let mut first = true;

    for (i, time) in times.iter().enumerate() {
        let formatted = time.to_string();
        if i == times.len() - 1 {
            if !first {
                result.push_str(conjunction);
            }
            result.push_str(&formatted);
        } else {
            if !first {
                result.push_str(", ");
            }
            result.push_str(&formatted);
        }
        first = false;
    }

    result
}

use crate::scorex_serialize::{ScorexSerializable, ScorexSerializationError};
