fn collect_subscription_messages<T>(url: &str, method: &str, count: usize) -> Result<Vec<T>, Error>
where
    T: DeserializeOwned + Send + 'static,
{
    let client = WsClientBuilder::default().build(url)?;
    let subscription = client.subscribe(method, rpc_params!())?;

    let mut messages = Vec::with_capacity(count);
    let mut stream = subscription.into_stream();

    let future = async move {
        while let Some(result) = stream.next().await {
            if let Ok(msg) = result {
                messages.push(msg);
                if messages.len() == count {
                    break;
                }
            }
        }
        Ok(messages)
    };

    future
}

fn apply_migrations_with_logging(
    ctx: DynServerDbMigrationContext,
    db: &Database,
    kind: &str,
    migrations: BTreeMap<DatabaseVersion, DynServerDbMigrationFn>,
) -> anyhow::Result<()> {
    let current_version = db.version()?;
    tracing::info!("Applying {} migrations from version {} onwards", kind, current_version);

    for (version, migration) in migrations {
        if version <= current_version {
            tracing::info!("Skipping {} migration for version {}", kind, version);
            continue;
        }

        tracing::info!("Running {} migration for version {}", kind, version);
        migration.apply(&ctx)?;
        tracing::info!("Completed {} migration for version {}", kind, version);
    }

    Ok(())
}

