use fax::{decoder::decode_g4, decoder::pels, BitWriter, VecWriter, Bits, Color};

fn extract_line_pbm(data: &[u8], width: u16, target_line: usize) -> Option<Vec<u8>> {
    let mut decoder = decode_g4(data).ok()?;
    let mut line_bytes = Vec::new();
    let mut line_index = 0;

    while let Some((_, row)) = decoder.next_row() {
        if line_index == target_line {
            let mut writer = VecWriter::new(&mut line_bytes);
            let mut bits = Bits::new();
            let mut row_data = Vec::new();

            for pel in row {
                match pel {
                    pels::Pel::Black => bits.push(1),
                    pels::Pel::White => bits.push(0),
                }
            }

            let mut bit_writer = BitWriter::new(&mut writer);
            bit_writer.write_bits(bits, width as usize).ok()?;
            bit_writer.flush();

            return Some(line_bytes);
        }
        line_index += 1;
    }

    None
}

fn validate_bit_string(lit: &str) -> Result<(), String> {
    if lit.is_empty() {
        return Err("Empty bit-string literal is invalid".to_string());
    }

    let mut prev_char = '\0';
    for c in lit.chars() {
        if c == '_' {
            if prev_char == '_' || prev_char == ' ' {
                return Err("Consecutive underscores are not allowed in bit-string literals".to_string());
            }
        } else if c != '0' && c != '1' && c != ' ' {
            return Err(format!("Invalid character '{}' in bit-string literal", c));
        }

        prev_char = c;
    }

    Ok(())
}

