fn detect_duplicate_enum_values(ctx: &mut Context<'_>, enum_name: &str) {
    let mut values = HashSet::new();
    let mut duplicates = HashSet::new();

    // Collect all enum values from the base definition
    if let Some(base_enum) = ctx.find_enum(enum_name) {
        for value in &base_enum.values {
            if !values.insert(value.name.clone()) {
                duplicates.insert(value.name.clone());
            }
        }
    }

    // Collect enum values from all extensions
    for extension in ctx.extensions.values() {
        if let Some(ext_enum) = extension.find_enum(enum_name) {
            for value in &ext_enum.values {
                if !values.insert(value.name.clone()) {
                    duplicates.insert(value.name.clone());
                }
            }
        }
    }

    // Report duplicates
    if !duplicates.is_empty() {
        let error = miette::Report::new()
            .with_title(format!("Duplicate enum values found for '{}'", enum_name))
            .with_help("Ensure that no enum value is defined more than once across the base definition and its extensions.")
            .with_source_code(ctx.source.clone())
            .with_positions(
                duplicates.iter()
                    .flat_map(|name| {
                        let mut positions = Vec::new();
                        if let Some(base_enum) = ctx.find_enum(enum_name) {
                            if let Some(base_value) = base_enum.values.iter().find(|v| v.name == *name) {
                                positions.push(base_value.pos);
                            }
                        }
                        for extension in ctx.extensions.values() {
                            if let Some(ext_enum) = extension.find_enum(enum_name) {
                                if let Some(ext_value) = ext_enum.values.iter().find(|v| v.name == *name) {
                                    positions.push(ext_value.pos);
                                }
                            }
                        }
                        positions
                    })
                    .collect::<Vec<_>>()
            );

        ctx.report_error(error);
    }
}

use crate::GroupInfo;

fn calculate_size_distribution(groups: &[GroupInfo], bins: &[u64]) -> Vec<(u64, usize)> {
    let mut result = Vec::new();
    let mut counts = std::collections::HashMap::new();

    for group in groups {
        let size = group.size;
        let mut placed = false;
        for &bin in bins {
            if size < bin {
                counts.entry(bin).or_insert(0);
                *counts.get_mut(&bin).unwrap() += 1;
                placed = true;
                break;
            }
        }
        if !placed {
            counts.entry(u64::MAX).or_insert(0);
            *counts.get_mut(&u64::MAX).unwrap() += 1;
        }
    }

    let mut sorted_bins = bins.to_vec();
    sorted_bins.sort();
    sorted_bins.push(u64::MAX);

    for &bin in &sorted_bins {
        if let Some(&count) = counts.get(&bin) {
            result.push((bin, count));
        }
    }

    result
}

