fn run_shutdown() -> Result<(), std::io::Error> {
    let mut shutdown_stream = ShutdownStream::new();
    let mut signals = vec![
        SignalKind::interrupt(),
        SignalKind::terminate(),
    ];

    // Configure the shutdown stream with signals and a timeout
    let shutdown_stream = shutdown_stream
        .with_signals(signals)
        .with_timeout(Duration::from_secs(5));

    // Start the shutdown stream
    let shutdown_handle = shutdown_stream.start();

    // Await shutdown or timeout
    match shutdown_handle.await {
        Ok(ShutdownReason::Signal) => {
            println!("Shutting down due to signal");
        }
        Ok(ShutdownReason::Timeout) => {
            println!("Shutting down due to timeout");
        }
        Err(e) => {
            return Err(e);
        }
    }

    Ok(())
}

fn analyze_migration_feature_usage<'a>(
    instructions: impl Iterator<Item = (&'a Pubkey, SVMInstruction<'a>)> + Clone,
) -> Result<Vec<(usize, u16)>, TransactionError> {
    let mut feature_counts = std::collections::HashMap::new();
    let mut total_features_used = 0;

    for (program_id, instruction) in instructions.clone() {
        if let Some(program_kind) = BuiltinProgramsFilter::get_program_kind(program_id) {
            if let Some(costs) = MIGRATING_BUILTINS_COSTS.get(&program_kind) {
                if let Some(feature_count) = costs.get("feature_count") {
                    *feature_counts.entry(program_kind).or_insert(0) += *feature_count as u16;
                    total_features_used += *feature_count as u16;
                }
            }
        }
    }

    let mut result: Vec<(usize, u16)> = feature_counts
        .into_iter()
        .map(|(kind, count)| (kind as usize, count))
        .collect();

    result.sort_by(|a, b| a.0.cmp(&b.0));

    Ok(result)
}

