fn filter_transactions_by_signer<'a>(
    shards: &'a [IndexerShard],
    signer: &str,
) -> Vec<&'a IndexerTransactionWithOutcome> {
    let mut result = Vec::new();
    for shard in shards {
        if let Some(chunk_views) = &shard.chunk_views {
            for chunk_view in chunk_views {
                if let Some(transactions) = &chunk_view.transactions {
                    for transaction in transactions {
                        if transaction.signer.eq(signer) {
                            result.push(transaction);
                        }
                    }
                }
            }
        }
    }
    result
}

fn merge(&mut self, other: &DtzProfile) {
    // Merge roles, ensuring no duplicates
    let mut role_set: HashSet<String> = self.roles.iter().cloned().collect();
    for role in &other.roles {
        if !role_set.contains(role) {
            role_set.insert(role.clone());
        }
    }
    self.roles = role_set.into_iter().collect();

    // Merge contexts, ensuring no duplicates
    let mut context_set: HashSet<ContextId> = self.contexts.iter().cloned().collect();
    for context in &other.contexts {
        if !context_set.contains(context) {
            context_set.insert(*context);
        }
    }
    self.contexts = context_set.into_iter().collect();
}

use async_nats::Client;
use async_nats::jetstream::Context as JetStreamContext;
use futures::StreamExt;
use nkeys::XKey;
use wasmcloud_secrets_types::Secret;
use anyhow::Context;
use anyhow::Result;

fn get_secret_history(
    nats_client: &Client,
    secret_bucket: &str,
    encryption_xkey: &XKey,
    secret_name: &str,
) -> Result<Vec<Secret>> {
    let js = nats_client.jetstream().context("Failed to get JetStream context")?;
    let subject = format!(">${secret_bucket}.secrets.{}", secret_name);

    let mut stream = js
        .subscribe(&subject)
        .context("Failed to subscribe to secret subject")?;

    let mut secret_history = Vec::new();
    let mut seen_sequence = std::collections::HashSet::new();

    while let Some(msg) = stream.next().await {
        let payload = msg.payload();
        let payload_str = std::str::from_utf8(payload).context("Failed to decode payload")?;

        let secret: Secret = serde_json::from_str(payload_str).context("Failed to parse secret")?;

        if seen_sequence.contains(&secret.sequence) {
            continue;
        }

        seen_sequence.insert(secret.sequence);
        secret_history.push(secret);
    }

    Ok(secret_history)
}

fn random_mintable_token_mapping_with_tx_index(
    deps: Deps,
    env: &Env,
    sender: Addr,
) -> Result<TokenPositionMapping, ContractError> {
    let block_height = env.block.height;
    let tx_index = env.block.transaction_index as u64;
    let sender_bytes = sender.as_bytes();

    let mut hasher = Sha256::new();
    hasher.update(block_height.to_le_bytes());
    hasher.update(tx_index.to_le_bytes());
    hasher.update(sender_bytes);
    let mut hash = [0u8; 32];
    hash.copy_from_slice(hasher.finalize().as_ref());

    let mut rng = nois::rng::Rng::from_hash(hash);
    let num_tokens = MINTABLE_NUM_TOKENS.load(deps.storage)?;
    let mut positions = vec![];

    for _ in 0..num_tokens {
        let position = int_in_range(&mut rng, 0, MINTABLE_TOKEN_POSITIONS.len() as u64);
        positions.push(position);
    }

    let mut unique_positions = positions;
    unique_positions.sort();
    unique_positions.dedup();

    if unique_positions.len() != num_tokens as usize {
        return Err(ContractError::InvalidPositionSelection {});
    }

    let mut token_positions = vec![];
    for &position in &unique_positions {
        token_positions.push(position);
    }

    Ok(TokenPositionMapping {
        token_positions,
    })
}

