fn wait_send_final_state(module: &LightningClientModule, operation_id: OperationId) -> Result<FinalSendOperationState> {
    let mut stream = module.subscribe_send_operation_state(operation_id);
    let mut state = SendOperationState::Pending;

    while let Some(update) = stream.next().await {
        state = update?;
        if state.is_terminal() {
