    Ok(state.into())
}

fn validate_foreign_keys(
    table: &Table,
    existing: &HashMap<String, Vec<String>>,
) -> Result<(), String> {
    if let Some(foreign_keys) = &table.foreign_keys {
        for fk in foreign_keys {
            if let Some((referenced_table, referenced_column)) = &fk.referenced {
                if !existing.contains_key(referenced_table) {
                    return Err(format!("Referenced table {} does not exist", referenced_table));
                }
                let columns = existing.get(referenced_table).unwrap();
                if !columns.contains(referenced_column) {
                    return Err(format!(
                        "Referenced column {} does not exist in table {}",
                        referenced_column, referenced_table
                    ));
                }
            } else {
                return Err("Foreign key must specify referenced table and column".to_string());
            }
        }
    }
    Ok(())
}

fn join_slash_segments<I, S>(segments: I) -> String
where
    I: IntoIterator<Item = S>,
    S: AsRef<str>,
{
    let mut result = String::new();
    let mut first = true;

    for segment in segments {
        let segment = segment.as_ref();
        if !segment.is_empty() {
            if !first {
                result.push('/');
            } else {
                first = false;
            }
            result.push_str(segment);
        }
    }

    result
}

use std::str::FromStr;

fn validate_h256_hex(hex: &str) -> Result<String, String> {
    if hex.len() != 66 {
        return Err("Invalid length: must be exactly 66 characters".to_string());
    }

    if !hex.starts_with("0x") {
        return Err("Invalid format: must start with '0x'".to_string());
    }

    if hex.chars().filter(|c| c.is_digit(16) || *c == 'x').count() != 66 {
        return Err("Invalid characters: must be a valid hexadecimal string".to_string());
    }

    Ok(hex.to_string())
}

use solana_transaction::Transaction;
use solana_transaction_error::{TransportResult, TransportError};
use solana_client_traits::AsyncClient;
use solana_connection_cache::{ConnectionPool, ConnectionManager, NewConnectionConfig};

fn send_batch_in_chunks(&self, transactions: &[Transaction]) -> TransportResult<()> {
    let fanout_size = self.config.fanout_size;
    if fanout_size == 0 {
        return Ok(());
    }

    let mut chunk_index = 0;
    while chunk_index < transactions.len() {
        let end_index = std::cmp::min(chunk_index + fanout_size, transactions.len());
        let chunk = &transactions[chunk_index..end_index];

        // Send the chunk using the batch API
        self.send_batch(chunk)?;

        chunk_index += fanout_size;
    }

    Ok(())
}

fn send_batch(&self, transactions: &[Transaction]) -> TransportResult<()> {
    let connection_pool = self.connection_pool();
    let mut connection = connection_pool.borrow_mut();

    if connection.is_none() {
        let config = NewConnectionConfig::default();
        let manager = ConnectionManager::new(config);
        let connection = manager.connect()?;
        *connection_pool.borrow_mut() = Some(connection);
    }

    let connection = connection_pool.borrow().as_ref().unwrap();
    connection.send_batch(transactions)
}

