use syn::{Ident, Result as SynResult, Span, Type};
use crate::segment::RouteSegment;

fn parse_dynamic_segments<'a>(route: &'a str, fields: impl Iterator<Item = (&'a Ident, &'a Type)> + Clone) -> SynResult<Vec<RouteSegment>> {
    let mut segments = Vec::new();
    let mut chars = route.chars().peekable();
    let mut in_segment = false;
    let mut segment_start = 0;
    let mut current_segment = String::new();
    let mut field_iter = fields.clone().peekable();
    let mut field_index = 0;

    while let Some(c) = chars.next() {
        if c == ':' {
            if !in_segment {
                in_segment = true;
                segment_start = chars.position().unwrap_or(0);
                current_segment = String::new();
                current_segment.push(c);
            } else {
                // This is an error case, as we should not have consecutive colons
                return Err(syn::Error::new(Span::call_site(), "consecutive colons in route string"));
            }
        } else if c == '/' && in_segment {
            in_segment = false;
            let segment = &route[segment_start..chars.position().unwrap_or(0)];
            let ident = if let Some((field, _)) = field_iter.peek() {
                field
            } else {
                return Err(syn::Error::new(Span::call_site(), "unexpected segment in route string"));
            };
            segments.push(RouteSegment {
                name: ident.to_string(),
                ty: field_iter.next().unwrap().1.clone(),
                span: Span::new(segment_start as u32, chars.position().unwrap_or(0) as u32, Span::call_site().ctxt()),
            });
            current_segment.clear();
        } else if c == '/' && !in_segment {
            // Just a regular slash, ignore
        } else if in_segment {
            current_segment.push(c);
        }
    }

    if in_segment {
        return Err(syn::Error::new(Span::call_site(), "unclosed segment in route string"));
    }

    if field_iter.peek().is_some() {
        return Err(syn::Error::new(Span::call_site(), "extra fields in route string"));
    }

    Ok(segments)
}

