fn calculate_variable_row_widths(
    rows: &[&[u8]],
    opts: &[RowEncodingOptions],
) -> Vec<usize> {
    let mut widths = Vec::with_capacity(rows.len());
    for (row_idx, row) in rows.iter().enumerate() {
        let mut total_width = 0;
        for &opt in opts {
            match opt {
                RowEncodingOptions::Utf8 => {
                    total_width += row.len();
                }
                RowEncodingOptions::BinaryNoOrder => {
                    total_width += no_order::calculate_width(row);
                }
            }
        }
        widths.push(total_width);
    }
    widths
}

fn read_until_newline(&mut self, buffer: &mut String) -> std::io::Result<bool> {
    let mut temp_buffer = Vec::new();
    let mut found_newline = false;

    // Read available data from the serial stream
    let mut buf = [0u8; 1024];
    loop {
        let bytes_read = self.read(&mut buf)?;
        if bytes_read == 0 {
            break;
        }

        // Check for newline character
        for &byte in &buf[0..bytes_read] {
            if byte == b'\n' {
                found_newline = true;
                break;
            }
            temp_buffer.push(byte);
        }

        if found_newline {
            break;
        }
    }

    if found_newline {
        // Append the accumulated bytes to the buffer and clear the temp buffer
        buffer.push_str(str::from_utf8(&temp_buffer).unwrap());
        buffer.push('\n');
        temp_buffer.clear();
        Ok(true)
    } else {
        // Append the accumulated bytes to the buffer
        buffer.push_str(str::from_utf8(&temp_buffer).unwrap());
        temp_buffer.clear();
        Ok(false)
    }
}

use ratchet_deflate::{DeflateConfig, WindowBits, DeflateExtensionError};

fn parse_deflate_extension_header(header_value: &str) -> Result<DeflateConfig, DeflateExtensionError> {
    let mut params = std::collections::HashMap::new();
    let mut tokens = header_value.split(',').map(str::trim);

    while let Some(token) = tokens.next() {
        if token.is_empty() {
            continue;
        }

        let mut parts = token.split('=');
        let key = parts.next().ok_or(DeflateExtensionError::InvalidParameter)?;
        let value = parts.next().ok_or(DeflateExtensionError::InvalidParameter)?;

        if params.contains_key(key) {
            return Err(DeflateExtensionError::DuplicateParameter);
        }

        params.insert(key.to_string(), value.to_string());
    }

    let mut config = DeflateConfig::default();

    if let Some(val) = params.get("server_no_context_takeover") {
        if val.eq_ignore_ascii_case("0") {
            config.server_no_context_takeover = false;
        } else if val.eq_ignore_ascii_case("1") {
            config.server_no_context_takeover = true;
        } else {
            return Err(DeflateExtensionError::InvalidParameterValue);
        }
    }

    if let Some(val) = params.get("client_no_context_takeover") {
        if val.eq_ignore_ascii_case("0") {
            config.client_no_context_takeover = false;
        } else if val.eq_ignore_ascii_case("1") {
            config.client_no_context_takeover = true;
        } else {
            return Err(DeflateExtensionError::InvalidParameterValue);
        }
    }

    if let Some(val) = params.get("server_max_window_bits") {
        let bits: u8 = match val.parse() {
            Ok(b) => b,
            Err(_) => return Err(DeflateExtensionError::InvalidParameterValue),
        };

        if bits > 15 {
            return Err(DeflateExtensionError::InvalidParameterValue);
        }

        config.server_max_window_bits = bits;
    }

    if let Some(val) = params.get("client_max_window_bits") {
        let bits: u8 = match val.parse() {
            Ok(b) => b,
            Err(_) => return Err(DeflateExtensionError::InvalidParameterValue),
        };

        if bits > 15 {
            return Err(DeflateExtensionError::InvalidParameterValue);
        }

        config.client_max_window_bits = bits;
    }

    if params.contains_key("no_context_takeover") {
        return Err(DeflateExtensionError::UnknownParameter);
    }

    if params.contains_key("server_max_window_bits") && params.contains_key("client_max_window_bits") {
        return Err(DeflateExtensionError::UnknownParameter);
    }

    if params.contains_key("server_no_context_takeover") && params.contains_key("client_no_context_takeover") {
        return Err(DeflateExtensionError::UnknownParameter);
    }

    Ok(config)
}

fn random_with_degree<R: rand::Rng>(rng: &mut R, degree: usize) -> Self {
    let mut coeffs = Vec::with_capacity(degree + 1);
    for _ in 0..degree {
        coeffs.push(rng.gen());
    }
    // Ensure the leading coefficient is non-zero
    let leading = loop {
        let coeff = rng.gen();
        if coeff != Scalar::zero() {
            break coeff;
        }
    };
    coeffs.push(leading);
    PolyCoeff(coeffs)
}

use crate::nonblocking::tpu_client::send_wire_transaction_to_addr;
use futures_util::future::join_all;
use solana_transaction::Transaction;
use solana_transaction_error::{TransportResult, TransportError};
use solana_connection_cache::{ConnectionPool, ConnectionManager, NewConnectionConfig};

fn send_batch_with_retry(
    &self,
    transactions: &[Transaction],
    max_retries: usize,
) -> TransportResult<()> {
    let mut retry_count = 0;
    let mut connections = self.get_connections();
    let mut pool = ConnectionPool::new(ConnectionManager::new(
        NewConnectionConfig::default(),
    ));

    while retry_count < max_retries {
        let mut futures = Vec::new();
        let mut failed_transactions = Vec::new();

        for &tx in transactions {
            let connection = pool.get().map_err(|e| TransportError::new(e.to_string()))?;
            let future = send_wire_transaction_to_addr(tx, connection);
            futures.push(future);
        }

        let results = join_all(futures).map_err(|e| TransportError::new(e.to_string()))?;

        for (i, result) in results.into_iter().enumerate() {
            if let Err(e) = result {
                failed_transactions.push((transactions[i].clone(), e));
            }
        }

        if failed_transactions.is_empty() {
            return Ok(());
        }

        // If any transaction failed, retry with new connections
        connections = self.get_connections();
        retry_count += 1;
    }

    Err(TransportError::new("Failed to send batch after maximum retries".to_string()))
}

