}

impl<'c, C: Consumer + 'c> Iterator for GoodsIterator<'c, C> {
    type Item = C::Good;

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            match self.consumer.consume() {
                Ok(good) => return Some(good),
                Err(Failure::EmptyStock) => continue,
                Err(failure) => return Err(failure),
            }
        }
    }
}

