use levenshtein_automata::{DFA, SINK_STATE};

fn process_in_chunks(dfa: &DFA, chunks: &[&[u8]]) -> Option<u8> {
    let mut current_state = dfa.start_state();

    for &chunk in chunks {
        let mut chunk_state = current_state;
        let mut i = 0;

        while i < chunk.len() {
            let c = chunk[i];
            let next_state = dfa.next_state(chunk_state, c);

            if next_state == SINK_STATE {
                // If we reached the sink state, we can't recover, return None
                return None;
            }

            chunk_state = next_state;
            i += 1;
        }

        current_state = chunk_state;
    }

    // After processing all chunks, check if we're in an accepting state
    if dfa.is_accepting(current_state) {
        Some(current_state)
    } else {
        None
    }
}

fn split_worktree_update_custom(mut message: UpdateWorktree, max_chunk: usize) -> impl Iterator<Item = UpdateWorktree> {
    let mut result = Vec::new();
    let mut current_chunk = UpdateWorktree {
        project_id: message.project_id,
        worktree_id: message.worktree_id,
        root_name: message.root_name.clone(),
        abs_path: message.abs_path.clone(),
        scan_id: message.scan_id,
        is_last_update: false,
        updated_entries: Vec::new(),
        removed_entries: Vec::new(),
        updated_repositories: Vec::new(),
        removed_repositories: Vec::new(),
    };

    let mut updated_entries_count = 0;
    let mut removed_entries_count = 0;
    let mut updated_repositories_count = 0;
    let mut removed_repositories_count = 0;

    for entry in message.updated_entries {
        if updated_entries_count >= max_chunk {
            result.push(current_chunk);
            current_chunk = UpdateWorktree {
                project_id: message.project_id,
                worktree_id: message.worktree_id,
                root_name: message.root_name.clone(),
                abs_path: message.abs_path.clone(),
                scan_id: message.scan_id,
                is_last_update: false,
                updated_entries: Vec::new(),
                removed_entries: Vec::new(),
                updated_repositories: Vec::new(),
                removed_repositories: Vec::new(),
            };
            updated_entries_count = 0;
        }
        current_chunk.updated_entries.push(entry);
        updated_entries_count += 1;
    }

    for entry in message.removed_entries {
        if removed_entries_count >= max_chunk {
            result.push(current_chunk);
            current_chunk = UpdateWorktree {
                project_id: message.project_id,
                worktree_id: message.worktree_id,
                root_name: message.root_name.clone(),
                abs_path: message.abs_path.clone(),
                scan_id: message.scan_id,
                is_last_update: false,
                updated_entries: Vec::new(),
                removed_entries: Vec::new(),
                updated_repositories: Vec::new(),
                removed_repositories: Vec::new(),
            };
            removed_entries_count = 0;
        }
        current_chunk.removed_entries.push(entry);
        removed_entries_count += 1;
    }

    for entry in message.updated_repositories {
        if updated_repositories_count >= max_chunk {
            result.push(current_chunk);
            current_chunk = UpdateWorktree {
                project_id: message.project_id,
                worktree_id: message.worktree_id,
                root_name: message.root_name.clone(),
                abs_path: message.abs_path.clone(),
                scan_id: message.scan_id,
                is_last_update: false,
                updated_entries: Vec::new(),
                removed_entries: Vec::new(),
                updated_repositories: Vec::new(),
                removed_repositories: Vec::new(),
            };
            updated_repositories_count = 0;
        }
        current_chunk.updated_repositories.push(entry);
        updated_repositories_count += 1;
    }

    for entry in message.removed_repositories {
        if removed_repositories_count >= max_chunk {
            result.push(current_chunk);
            current_chunk = UpdateWorktree {
                project_id: message.project_id,
                worktree_id: message.worktree_id,
                root_name: message.root_name.clone(),
                abs_path: message.abs_path.clone(),
                scan_id: message.scan_id,
                is_last_update: false,
                updated_entries: Vec::new(),
                removed_entries: Vec::new(),
                updated_repositories: Vec::new(),
                removed_repositories: Vec::new(),
            };
            removed_repositories_count = 0;
        }
        current_chunk.removed_repositories.push(entry);
        removed_repositories_count += 1;
    }

    // Push the last chunk
    result.push(current_chunk);

    // Set is_last_update for the last chunk
    if !result.is_empty() {
        result.last_mut().unwrap().is_last_update = true;
    }

    result.into_iter()
}

fn add_debounced_input_listener(el: &web_sys::HtmlInputElement, delay: std::time::Duration, cb: impl Fn(String) + 'static) {
    let cb = cb;
    let mut last_value = el.value();

    window_event_listener_untyped(move |event| {
        if let Some(input_event) = event.as_event().and_then(|e| e.downcast::<web_sys::InputEvent>().ok()) {
            if let Ok(value) = input_event.target().and_then(|t| t.dyn_into::<HtmlInputElement>().ok()).map(|el| el.value()) {
                if value != last_value {
                    last_value = value;
                    debounce(delay, move || {
                        cb(value.clone());
                    });
                }
            }
        }
    }, "input", el);
}

use eip4844::Context;
use bls12_381::Scalar;
use serialization::{deserialize_blob_to_scalars, deserialize_compressed_g1, types::{BlobRef, Bytes48Ref}};
use itertools::izip;

fn compute_fiat_shamir_challenges(
    ctx: &Context,
    blobs: &[BlobRef],
    commitments: &[Bytes48Ref],
) -> Result<Vec<Scalar>, Error> {
    let mut challenges = Vec::with_capacity(blobs.len());
    let mut rng = ctx.get_rng();

    for (blob, commitment) in izip!(blobs, commitments) {
        let blob_scalars = deserialize_blob_to_scalars(blob)?;
        let commitment_g1 = deserialize_compressed_g1(commitment)?;
        let mut challenge = Scalar::zero();
        let mut hash = ctx.hasher().new_hasher();
        hash.write(&blob_scalars);
        hash.write(&commitment_g1);
        challenge = Scalar::from_hash(hash.finish());
        challenges.push(challenge);
    }

    Ok(challenges)
}

fn batch_update_tenant_metadata(
    client: &Client,
    tenant_id: Uuid,
    updates: serde_json::Map<String, serde_json::Value>,
) -> Result<Tenant, Error> {
    let existing_metadata = client.get_tenant_metadata(tenant_id)?;
    let merged_metadata = merge_metadata(existing_metadata, updates);
    client.update_tenant_metadata(tenant_id, merged_metadata)
}

fn merge_metadata(
    existing: serde_json::Map<String, serde_json::Value>,
    updates: serde_json::Map<String, serde_json::Value>,
) -> serde_json::Map<String, serde_json::Value> {
    let mut merged = existing;
    for (key, value) in updates {
        merged.insert(key, value);
    }
    merged
}

fn generate_json_schema(schema: &gluesql_core::prelude::Schema) -> serde_json::Value {
    let mut properties = serde_json::Map::new();
    let mut required = vec![];

    for column in &schema.columns {
        let bson_type = glue_type_to_bson_type(&column.data_type);
        let mut field = json!({
            "bsonType": bson_type,
            "description": column.comment.clone().unwrap_or_default()
        });

        if let Some(title) = &column.title {
            field["title"] = json!(title);
        }

        properties.insert(column.name.clone(), field);
        required.push(column.name.clone());
    }

    json!({
        "$jsonSchema": {
            "properties": properties,
            "required": required
        }
    })
}

fn get_duration(file_path: &str) -> Result<f64, Box<dyn std::error::Error>> {
    let file = File::open(file_path)?;
    let mut buffer = Vec::new();
    let mut reader = std::io::BufReader::new(file);
    reader.read_to_end(&mut buffer)?;

    let mut vorbis_info = MaybeUninit::uninit();
    let mut vorbis_comment = MaybeUninit::uninit();
    let mut pcm = MaybeUninit::uninit();
    let mut setup = MaybeUninit::uninit();

    let mut error = ptr::null_mut();
    let mut state = ptr::null_mut();

    unsafe {
        vorbis_info = MaybeUninit::new(vorbis_info.as_mut_ptr());
        vorbis_comment = MaybeUninit::new(vorbis_comment.as_mut_ptr());
        pcm = MaybeUninit::new(pcm.as_mut_ptr());
        setup = MaybeUninit::new(setup.as_mut_ptr());

        error = vorbis_info_setup_vorbis_file(
            buffer.as_ptr() as *const c_long,
            buffer.len() as c_long,
            vorbis_info.as_mut_ptr(),
            vorbis_comment.as_mut_ptr(),
            pcm.as_mut_ptr(),
            setup.as_mut_ptr(),
        );

        if error != 0 {
            return Err("Failed to setup Vorbis file".into());
        }

        state = vorbis_info_get_vorbis_file(setup.as_mut_ptr());
        if state.is_null() {
            return Err("Failed to get Vorbis file state".into());
        }

        let mut duration = 0.0;
        let mut length = 0;
        let mut total_samples = 0;

        let mut i = 0;
        while i < 1000 {
            let mut current = ptr::null_mut();
            let mut data = MaybeUninit::uninit();
            let mut data_len = MaybeUninit::uninit();

            current = vorbis_info_get_page(state);
            if current.is_null() {
                break;
            }

            let data_ptr = data.as_mut_ptr();
            let data_len_ptr = data_len.as_mut_ptr();
            let mut error = vorbis_info_page_data(current, data_ptr, data_len_ptr);
            if error != 0 {
                break;
            }

            let data_len = *data_len_ptr as usize;
            let data = data.as_ptr() as *const u8;
            let mut page = MaybeUninit::uninit();
            let mut error = vorbis_info_page_get_page_info(current, page.as_mut_ptr());
            if error != 0 {
                break;
            }

            let mut page_info = page.assume_init();
            let mut length = 0;
            let mut total_samples = 0;

            let mut error = vorbis_info_page_get_length(current, &mut length);
            if error != 0 {
                break;
            }

            let mut error = vorbis_info_page_get_total_samples(current, &mut total_samples);
            if error != 0 {
                break;
            }

            duration += (length as f64) / (total_samples as f64);
            i += 1;
        }

        vorbis_info_clear_vorbis_file(state);
        vorbis_info_clear_vorbis_file(setup.as_mut_ptr());
    }

    Ok(duration)
}

