use std::path::Path;
use std::io::{BufReader, BufWriter};
use warc::{WarcReader, WarcWriter, WarcRecord};

fn filter_records_by_content_length<P: AsRef<Path>>(input_path: P, output_path: P, min_length: usize) -> Result<(), std::io::Error> {
    let input = Path::new(&input_path);
    let output = Path::new(&output_path);

    let reader = BufReader::new(std::fs::File::open(input)?);
    let mut writer = BufWriter::new(std::fs::File::create(output)?);

    let mut warc_reader = WarcReader::new(reader);
    let mut warc_writer = WarcWriter::new(writer);

    for record in warc_reader.records() {
        let record = record?;
        if record.body().len() > min_length {
            warc_writer.write_record(record)?;
        }
    }

    Ok(())
}

