fn generate_opd_map(tm: &TurbulenceModel, n_xy: usize, filename: &str) {
    let size = n_xy * n_xy;
    let mut opd_data = Vec::with_capacity(size);

    for y in 0..n_xy {
        for x in 0..n_xy {
            let opd = Opd::new(tm.covariance(x as f64, y as f64));
            opd_data.push(opd);
        }
    }

    let file = File::create(filename).expect("Failed to create file");
    bincode::serialize_into(file, &opd_data).expect("Failed to serialize OPD map");
}

fn track_transaction_progress(
    client: &solana_client::rpc_client::RpcClient,
    signatures: &[solana_sdk::signature::Signature],
) -> solana_client::client_error::Result<()> {
    let total = signatures.len() as u64;
    let mut progress_bar = ProgressBar::new(total);
    progress_bar.set_style(indicatif::ProgressStyle::default_bar()
        .template("{spinner:.bold} {msg} {bar:40.cyan} {pos}/{total} ({percent}% )")
        .progress_chars("#>-"));
    progress_bar.set_message("Confirming transactions...");

    for (i, &signature) in signatures.iter().enumerate() {
        let confirmed = client.get_signature_status(signature)?;
        if let Some(status) = confirmed {
            if status.confirmation_status.is_some() {
                progress_bar.inc(1);
            }
        }
        sleep(Duration::from_millis(500));
    }

    progress_bar.finish_and_clear();
    Ok(())
}

