fn set_matlab_time_sampling(&mut self, sampling_frequency: f64) -> &mut Self {
    match &mut self.file_format {
        FileFormat::Matlab(MatFormat::SampleBased) => {
            log::warn!("Cannot set time-based sampling on a sample-based Matlab export.");
        }
        FileFormat::Matlab(MatFormat::TimeBased(_)) => {
            log::info!("Updating Matlab export to use time-based sampling with frequency: {}", sampling_frequency);
            *self.file_format = FileFormat::Matlab(MatFormat::TimeBased(sampling_frequency));
        }
        _ => {
            log::warn!("Matlab export is not enabled or not in a compatible format.");
        }
    }
    self
}

