fn aggregate_bandwidth(
    metrics: &Family<Labels, Counter>,
) -> std::collections::HashMap<String, (u64, u64)> {
    let mut result = std::collections::HashMap::new();
    for metric in metrics {
        if let Some(labels) = metric.labels() {
            if let Some(protocol) = labels.protocol {
                let direction = labels.direction;
                let value = metric.value();
                let entry = result.entry(protocol.clone())
                    .or_insert((0, 0));
                match direction {
                    Direction::Inbound => entry.0 = entry.0.saturating_add(value as u64),
                    Direction::Outbound => entry.1 = entry.1.saturating_add(value as u64),
                }
            }
        }
    }
    result
}

