fn add_duration_to_expiration(exp: &Expiration, dur: Duration) -> Result<Expiration, AuthError> {
    match exp {
        Expiration::Block(block) => {
            let new_block = block + dur.block;
            Ok(Expiration::Block(new_block))
        }
        Expiration::Timestamp(ts) => {
            let new_ts = *ts + dur.seconds as u64;
            Ok(Expiration::Timestamp(new_ts))
        }
    }
}

use sha1_smol::Sha1;
use std::fs::File;
use std::io::{BufReader, Read};
use std::path::Path;

pub fn verify_file_sha1(path: &Path, expected: &str) -> std::io::Result<bool> {
    let file = File::open(path)?;
    let mut reader = BufReader::new(file);
    let mut sha1 = Sha1::new();
    let mut buffer = [0u8; 8192];
    loop {
        let n = reader.read(&mut buffer)?;
        if n == 0 {
            break;
        }
        sha1.update(&buffer[..n]);
    }
    Ok(sha1.digest().to_string() == expected)
}

use tui_tree_widget::TreeItem;

pub fn item_depth<Identifier>(items: &[TreeItem<'_, Identifier>], path: &[Identifier]) -> Option<usize>
where
    Identifier: PartialEq + Eq + core::hash::Hash,
{
    fn recurse<Identifier>(items: &[TreeItem<'_, Identifier>], path: &[Identifier], depth: usize) -> Option<usize>
    where
        Identifier: PartialEq + Eq + core::hash::Hash,
    {
        if path.is_empty() {
            return None;
        }
        for item in items {
            if item.identifier == path[0] {
                if path.len() == 1 {
                    return Some(depth);
                }
                return recurse(&item.children, &path[1..], depth + 1);
            }
        }
        None
    }
    recurse(items, path, 0)
}

use bytes::BytesMut;
use ratchet_deflate::{DeflateConfig, DeflateExtensionError, DeflateDecoder};

pub fn decompress_payload(
    compressed: &[u8],
    config: &DeflateConfig,
) -> Result<BytesMut, DeflateExtensionError> {
    let mut decoder = DeflateDecoder::new(config);
    let mut decompressed = BytesMut::with_capacity(compressed.len());

    // Decompress the payload
    let decompressed_data = decoder.decompress(compressed)?;

    // If context takeover is requested, reset the decoder state
    if config.context_takeover {
        decoder.reset();
    }

    decompressed.extend_from_slice(&decompressed_data);
    Ok(decompressed)
}

