fn batch_discover(
    swarm: &mut libp2p_swarm::Swarm<libp2p_rendezvous::client::Behaviour>,
    namespaces: Vec<libp2p_rendezvous::Namespace>,
    cookie: Option<libp2p_rendezvous::Cookie>,
    limit: Option<u64>,
    rendezvous_node: libp2p_identity::PeerId,
) -> Vec<(libp2p_rendezvous::Namespace, Vec<libp2p_rendezvous::Registration>)> {
    let mut results = Vec::new();
    let mut events = Vec::new();

    for namespace in namespaces {
        let mut discovery = libp2p_rendezvous::client::Event::Discover {
            namespace,
            cookie,
            limit,
            rendezvous_node,
        };

        events.push(discovery);
    }

    swarm.behaviour_mut().events = events;

    while let Some(event) = swarm.next_event() {
        if let libp2p_rendezvous::client::Event::DiscoverResponse {
            namespace,
            registrations,
            ..
        } = event
        {
            results.push((namespace, registrations));
        }
    }

    results
}

