pub struct FuturesSetStream<O> {
    set: FuturesSet<O>,
}

impl<O> FuturesSetStream<O> {
    pub fn new(set: FuturesSet<O>) -> Self {
        FuturesSetStream { set }
    }
}

impl<O> Stream for FuturesSetStream<O> {
    type Item = Result<O, Timeout>;

    fn poll_next(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<Option<Self::Item>> {
        let this = self.get_mut();
        if let Poll::Ready(Some(result)) = this.set.poll_unpin(cx) {
            Poll::Ready(Some(result))
        } else {
            Poll::Pending
        }
    }
}

