use dotenvy::EnvMap;

fn expand_substituted_env(base: &EnvMap, subs: &[(String, String)]) -> EnvMap {
    let mut result = EnvMap::new();
    for (key, pattern) in subs {
        let expanded = expand_pattern(pattern, base);
        result.insert(key.clone(), expanded);
    }
    result
}

fn expand_pattern(pattern: &str, base: &EnvMap) -> String {
    let mut result = String::new();
    let mut i = 0;
    while i < pattern.len() {
        if pattern.starts_with("${", i) {
            let mut var_name = String::new();
            let mut j = i + 2;
            while j < pattern.len() && !pattern.chars().nth(j).unwrap().is_ascii_uppercase() {
                var_name.push(pattern.chars().nth(j).unwrap());
                j += 1;
            }
            if j < pattern.len() && pattern.chars().nth(j).unwrap() == '}' {
                if let Some(value) = base.get(&var_name) {
                    result.push_str(value);
                }
                i = j + 1;
                continue;
            }
        }
        result.push(pattern.chars().nth(i).unwrap());
        i += 1;
    }
    result
}

fn validate_block_assembler_config(args: &InitArgs) -> Result<(), String> {
    if args.code_hash.is_some() {
        if !is_h256(&args.code_hash.unwrap()) {
            return Err("Invalid code hash: must be a valid H256".to_string());
        }
    }

    if args.args.is_some() {
        if !is_hex(&args.args.unwrap()) {
            return Err("Invalid args: must be a valid hex string".to_string());
        }
    }

    if args.message.is_some() {
        if !is_hex(&args.message.unwrap()) {
            return Err("Invalid message: must be a valid hex string".to_string());
        }
    }

    Ok(())
}

