fn put_with_expiry(
    &self,
    request_response: CachePutRequest,
    resource: Option<Rc<dyn Resource>>,
    expiry_seconds: u64,
) -> Result<(), CacheError> {
    let hash_value = hash(&request_response);
    let expiry_timestamp = SystemTime::now()
        .checked_add(std::time::Duration::from_secs(expiry_seconds))
        .ok_or(CacheError::InvalidExpiryTime)?;

    let cache_dir = get_responses_dir()?;
    let cache_path = cache_dir.join(format!("{}.cache", hash_value));

    let mut file = tokio::fs::File::create(cache_path).map_err(|e| CacheError::CacheWriteError(e.to_string()))?;
    file.write_all(&request_response.data).map_err(|e| CacheError::CacheWriteError(e.to_string()))?;

    insert_cache_asset_with_expiry(hash_value, expiry_timestamp)?;

    if let Some(resource) = resource {
        // Handle resource if needed
    }

    Ok(())
}

fn read_until(&mut self, buf: &mut [u8], delimiter: u8) -> Result<usize, UsbError> {
    let mut bytes_read = 0;
    let mut i = 0;

    while bytes_read < buf.len() && i < self.buffer.len() {
        let byte = self.buffer[i];
        buf[bytes_read] = byte;
        bytes_read += 1;
        i += 1;

        if byte == delimiter {
            break;
        }
    }

    Ok(bytes_read)
}

fn estimate_transaction_cost(
    tx_sigs: u64,
    secp_sigs: u64,
    ed_sigs: u64,
    write_locks: u64,
    instructions: &[CompiledInstruction],
    compute_unit_limit: Option<u64>,
) -> UsageCostDetails {
    let signature_cost = tx_sigs * SIGNATURE_COST;
    let secp_verify_cost = secp_sigs * SECP256K1_VERIFY_COST;
    let ed_verify_cost = ed_sigs * ED25519_VERIFY_COST;
    let write_lock_cost = write_locks * WRITE_LOCK_UNITS;

    let mut data_bytes_cost = 0;
    let mut compute_unit_usage = 0;

    for instr in instructions {
        if let Some(data) = &instr.data {
            data_bytes_cost += data.len() as u64 * INSTRUCTION_DATA_BYTES_COST;
        }
        compute_unit_usage += instr.accounts.len() as u64;
    }

    UsageCostDetails {
        signature_cost,
        secp_verify_cost,
        ed_verify_cost,
        write_lock_cost,
        data_bytes_cost,
        compute_unit_limit,
        compute_unit_usage,
    }
}

use anyhow::Result;
use fedimint_core::PeerId;
use fedimint_testing::fixtures::Fixtures;
use fedimint_testing::federation::FederationTest;

fn create_degraded_federation(
    fixtures: &Fixtures,
    num_offline: u16,
    num_peers: u16,
) -> Result<FederationTest, anyhow::Error> {
    if num_offline >= num_peers {
        return Err(anyhow::anyhow!("Cannot have more offline peers than total peers"));
    }

    let mut peers: Vec<PeerId> = (0..num_peers)
        .map(|i| fixtures.peer_id(i))
        .collect();

    // Mark the first `num_offline` peers as offline
    for i in 0..num_offline {
        let peer_id = peers[i as usize];
        fixtures.set_peer_offline(peer_id)?;
    }

    // Create the federation test with the configured peers
    let federation = FederationTest::new(fixtures, peers.clone())?;

    // Verify the federation reports a degraded state
    let is_degraded = federation.is_degraded()?;
    if !is_degraded {
        return Err(anyhow::anyhow!("Federation did not report degraded state"));
    }

    // Verify the expected number of peers remain online
    let online_peers = federation.online_peers()?;
    if online_peers != num_peers - num_offline {
        return Err(anyhow::anyhow!(
            "Expected {} online peers, got {}",
            num_peers - num_offline,
            online_peers
        ));
    }

    // Verify client operations like fetching federation ID still succeed
    let federation_id = federation.get_federation_id()?;
    if federation_id.is_empty() {
        return Err(anyhow::anyhow!("Failed to fetch federation ID"));
    }

    Ok(federation)
}

fn check_rate_limit(session: &mut WritableSession, limit: u32, window_secs: u64) -> Result<bool, async_session::Error> {
    let key = "rate_limit";
    let now = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);

    let entry = session.get::<Vec<(u64, u64)>>(&key).unwrap_or_default();

    let filtered: Vec<_> = entry.iter()
        .filter(|&&(timestamp, _)| timestamp > now - window_secs)
        .map(|&(_, count)| count)
        .collect();

    let current_count = filtered.iter().sum::<u64>();

    if current_count >= limit {
        return Ok(false);
    }

    let mut updated = entry.iter()
        .map(|&(timestamp, count)| (timestamp, count))
        .collect::<Vec<_>>();

    let mut new_count = current_count + 1;
    let mut new_timestamp = now;

    // Keep only the latest timestamp for the same session
    let mut latest_timestamp = now;
    let mut latest_count = 0;

    for &(timestamp, count) in &updated {
        if timestamp == now {
            latest_count = count;
        } else if timestamp > latest_timestamp {
            latest_timestamp = timestamp;
            latest_count = count;
        }
    }

    // Update the count for the latest timestamp
    for entry in &mut updated {
        if entry.0 == latest_timestamp {
            entry.1 = latest_count + 1;
            break;
        }
    }

    session.set(&key, &updated)?;
    Ok(true)
}

fn bidirectional_windows<I>(iter: I, size: usize, rev: bool) -> Vec<Vec<I::Item>>
where
    I: DoubleEndedIterator + Clone,
    I::Item: Clone,
{
    let mut result = Vec::new();
    let mut window = Vec::new();
    let mut iter = iter.clone();

    if rev {
        iter = iter.rev();
    }

    for item in iter {
        window.push(item);
        if window.len() == size {
            result.push(window.clone());
            window.clear();
        }
    }

    result
}

