struct NetworkConnection {
    socket: String,
    timeout: Duration,
}

#[async_trait]
impl AsyncDrop for NetworkConnection {
    async fn async_drop(&mut self) -> Result<(), AsyncDropError> {
        let result = time::timeout(self.timeout, async {
            time::sleep(Duration::from_secs(2)).await;
            Ok(())
