fn extract_target_uris<P: AsRef<Path>>(path: P) -> Result<Vec<String>, io::Error> {
    let mut uris = Vec::new();
    let mut reader = WarcReader::open(path)?;

    for record in reader.records() {
        let record = record?;
        if record.header().record_type() == RecordType::Resource {
            if let Some(target_uri) = record.header().get("Target-URI") {
                uris.push(target_uri.to_string());
            }
        }
    }

    Ok(uris)
}

