fn touch_many<K, E>(&self, keys: &[K], expiration: E) -> Result<Vec<Status>, MemcacheError>
where
    K: AsRef<[u8]> + Send + Sync,
    E: Into<Option<Duration>> + Clone + Send,
{
    let expiration = expiration.into();
    let mut futures = Vec::new();

    for key in keys {
        let key_ref = key.as_ref();
        let expiration_clone = expiration.clone();
        let client = self.clone();

        futures.push(async move {
            let result = client.touch(key_ref, expiration_clone).await;
            match result {
                Ok(status) => Ok(status),
                Err(e) => Err(e),
            }
        });
    }

    let results = join_all(futures).await;
    let statuses: Vec<Status> = results.into_iter().collect::<Result<_, _>>()?;

    Ok(statuses)
}

use utmp_rs::UtmpEntry;
use std::collections::HashMap;
use time::OffsetDateTime;

fn calculate_session_durations(entries: &[UtmpEntry]) -> HashMap<String, i64> {
    let mut session_durations = HashMap::new();
    let mut session_map = HashMap::new();

    for entry in entries {
        match entry {
            UtmpEntry::Login(login) => {
                let session_id = login.session_id.clone();
                let timestamp = OffsetDateTime::from_unix_timestamp(login.tv_sec as i64)
                    .expect("Failed to parse timestamp");
                session_map.insert(session_id, timestamp);
            }
            UtmpEntry::Dead(dead) => {
                if let Some(session_id) = &dead.session_id {
                    if let Some(start_time) = session_map.get(session_id) {
                        let end_time = OffsetDateTime::from_unix_timestamp(dead.tv_sec as i64)
                            .expect("Failed to parse timestamp");
                        let duration = end_time - start_time;
                        session_durations.insert(session_id.clone(), duration.as_seconds() as i64);
                        session_map.remove(session_id);
                    }
                }
            }
            _ => {}
        }
    }

    session_durations
}

