    pub async fn batch_put_objects(
        &mut self,
        objects: Vec<(i64, Vec<FtColumn>, Vec<u8>)>,
    ) -> IndexerResult<usize> {
        self.start_transaction().await?;
        let mut success_count = 0;

        let mut queries = Vec::new();
        let mut values = Vec::new();

        for (type_id, columns, bytes) in objects {
            let table = self.tables.get(&type_id).ok_or_else(|| {
                IndexerError::DatabaseError(IndexerDatabaseError::TableMappingDoesNotExist(type_id))
            })?;

            let inserts: Vec<String> = columns.iter().map(|c| c.query_fragment()).collect();
            let updates: Vec<String> = self.schema[table]
                .iter()
                .zip(columns.iter())
                .map(|(col_name, value)| format!("{} = {}", col_name, value.query_fragment()))
                .collect();

            let query_text = self.upsert_query(table, &self.schema[table], inserts, updates);
            queries.push(query_text);
            values.push(bytes);
        }

        let conn = self.stashed.as_mut().ok_or_else(|| {
            IndexerError::NoTransactionError("batch_put_objects".to_string())
        })?;

        if let Err(e) = queries::batch_put_object(conn, queries, values).await {
            self.revert_transaction().await?;
            return Err(e);
        }

        self.commit_transaction().await?;
        Ok(success_count)
    }
}

fn upsert_query(
    table: &str,
    columns: &[&str],
    inserts: Vec<String>,
    updates: Vec<String>,
) -> String {
    let insert_columns = inserts.join(", ");
    let update_columns = updates.join(", ");
    format!(
        "INSERT INTO {} ({}) VALUES ({}) ON CONFLICT (id) DO UPDATE SET {}",
        table,
        columns.join(", "),
        insert_columns,
        update_columns
    )
}

use as_ffi_bindings::{BufferPtr, Read, Env};
use wasmer::Memory;
use anyhow::Result;

fn convert_buffer_to_custom(buf_ptr: BufferPtr, env: &Env) -> Result<Vec<u8>> {
    // Read the buffer data from the pointer
    let buffer_data = read_buffer(buf_ptr, env)?;

    // Compute the checksum of the buffer data
    let checksum = compute_checksum(&buffer_data);

    // Prepend the checksum to the buffer data
    let mut result = Vec::with_capacity(checksum.len() + buffer_data.len());
    result.extend_from_slice(&checksum);
    result.extend_from_slice(&buffer_data);

    Ok(result)
}

fn read_buffer(buf_ptr: BufferPtr, env: &Env) -> Result<Vec<u8>> {
    let memory = env.memory();
    let buffer_length = buf_ptr.read_u32(env)?;
    let buffer_data = memory
        .read_slice(buf_ptr.offset as usize, buffer_length as usize)
        .map_err(|e| anyhow::anyhow!("Failed to read buffer: {}", e))?;

    Ok(buffer_data)
}

fn compute_checksum(data: &[u8]) -> Vec<u8> {
    let mut checksum = 0u32;
    for &byte in data {
        checksum = (checksum + (byte as u32)) & 0xFFFFFFFF;
    }
    checksum.to_le_bytes().to_vec()
}

use crate::{WeightMatrix, Position};
use std::f32;

fn random_weight_matrix_f32(n: usize, invalid_ratio: f64) -> WeightMatrix<f32> {
    let mut matrix = WeightMatrix::new(n, n);
    let mut rng = rand::thread_rng();
    let invalid_threshold = invalid_ratio;

    for i in 0..n {
        for j in 0..n {
            let is_invalid = rng.gen::<f64>() < invalid_threshold;
            if is_invalid {
                matrix[(i, j)] = f32::INFINITY;
            } else {
                matrix[(i, j)] = rng.gen_range(0.0..100.0);
            }
        }
    }

    matrix
}

fn submit_blobs_with_retry<T, S>(client: &TxClient<T, S>, blobs: &[Blob], cfg: TxConfig) -> Result<TxInfo>
where
    T: GrpcService<BoxBody> + Clone,
    T::Error: Into<StdError>,
    T::ResponseBody: Body<Data = Bytes> + Send + 'static,
    <T::ResponseBody as Body>::Error: Into<StdError> + Send,
    S: DocSigner,
{
    let mut retries = 0;
    let max_retries = 3;
    let mut tx_info = None;

    while retries <= max_retries {
        match client.submit_blobs(blobs, &cfg) {
            Ok(info) => {
                tx_info = Some(info);
                break;
            }
            Err(Error::StdError(StdError::GrpcError(tonic::Status::invalid_argument(msg)))) if msg.contains("insufficient fee") => {
                tracing::warn!("Transaction rejected due to insufficient fee. Retrying...");
                retries += 1;
                if retries > max_retries {
                    return Err(Error::StdError(StdError::GrpcError(tonic::Status::failed_precondition("Max retries exceeded"))));
                }
                // Optionally adjust fee here or wait before retrying
                std::thread::sleep(std::time::Duration::from_secs(1));
            }
            Err(e) => {
                return Err(e);
            }
        }
    }

    tx_info.ok_or_else(|| Error::StdError(StdError::GrpcError(tonic::Status::internal("No transaction info returned"))))
}

fn display_name(&self) -> String {
    let mut result = String::new();
    let mut has_namespace = false;

    if let Some(namespace) = &self.namespace {
        result.push_str(namespace);
        has_namespace = true;
    }

    if !result.is_empty() {
        result.push(':');
    }

    result.push_str(&self.name);

    if has_namespace && self.version.is_some() {
        result.push(' ');
    }

    if let Some(version) = &self.version {
        result.push_str(version);
    } else {
        result.push_str(" unknown");
    }

    result
}

