use line_drawing::{BresenhamCircle, Point};

fn circle_outline(center: Point<i32>, radius: i32, thickness: i32) -> Vec<Point<i32>> {
    let mut result = Vec::new();
    let mut offset = 0;

    while offset < thickness {
        let current_radius = radius + offset;
        let circle_points = BresenhamCircle::new(center, current_radius);
        result.extend(circle_points);
        offset += 1;
    }

    result
}

fn send_persistent_text_message_with_properties(session: &mut Session, destination: &str, message_text: &str, properties: &[(&str, &str)], correlation_id: &str) -> Result<(), EMSException> {
    let destination_cstr = CString::new(destination).expect("Failed to create CString for destination");
    let message_text_cstr = CString::new(message_text).expect("Failed to create CString for message text");
    let correlation_id_cstr = CString::new(correlation_id).expect("Failed to create CString for correlation ID");

    let mut message = ptr::null_mut();
    unsafe {
        EMSCreateMessage(session, &mut message);
        EMSMessageSetString(message, EMS_TEXT, message_text_cstr.as_ptr() as *const i8);
        EMSMessageSetPersistent(message, EMS_PERSISTENT);
        EMSMessageSetCorrelationID(message, correlation_id_cstr.as_ptr() as *const i8);

        for &(prop_name, prop_value) in properties {
            let prop_name_cstr = CString::new(prop_name).expect("Failed to create CString for property name");
            let prop_value_cstr = CString::new(prop_value).expect("Failed to create CString for property value");
            EMSSetProperty(message, prop_name_cstr.as_ptr() as *const i8, prop_value_cstr.as_ptr() as *const i8);
        }

        EMSSend(session, destination_cstr.as_ptr() as *const i8, message);
        EMSClearMessage(message);
    }

    Ok(())
}

fn retry<T, E, F>(mut attempts: usize, mut op: F) -> Result<T, Failure>
where
    F: FnMut() -> Result<T, E>,
    E: Into<BoxError>,
{
    while attempts > 0 {
        match op() {
            Ok(value) => return Ok(value),
            Err(error) => {
                let mut failure = Failure::new();
                failure.set_error(error.into());
                track!(failure, "Attempt failed");
                attempts -= 1;
            }
        }
    }
    Err(failure)
}

fn skip_while_front<F>(&mut self, mut predicate: F)
    where
        F: FnMut(&I::Item) -> bool,
{
    while let Some(item) = self.peek() {
        if predicate(item) {
            self.next();
        } else {
            break;
        }
    }
}

