fn average_latency(latencies: &BTreeMap<PeerId, Option<Duration>>) -> Option<Duration> {
    let total: Duration = latencies
        .values()
        .filter_map(|&latency| latency)
        .sum();
    let count = latencies.values().filter_map(|&latency| latency).count() as u64;
    if count == 0 {
        return None;
    }
    Some(total / count)
}

fn set_version_from_string(&mut self, version: &str) -> &mut Self {
    let parts: Vec<&str> = version.split('.').collect();
    if parts.len() < 4 {
        panic!("Version string must be in the format MAJOR.MINOR.PATCH.RELEASE");
    }

    let major = parts[0].parse::<u32>().unwrap();
    let minor = parts[1].parse::<u32>().unwrap();
    let patch = parts[2].parse::<u32>().unwrap();
    let release = parts[3].parse::<u32>().unwrap();

    let file_version = (major << 48) | (minor << 32) | (patch << 16) | release as u64;
    let product_version = (major << 24) | (minor << 16) | (patch << 8) | release as u64;

    self.version_info.insert(VersionInfo::FILEVERSION, file_version);
    self.version_info.insert(VersionInfo::PRODUCTVERSION, product_version);

    self
}

use std::fs::File;
use datafusion_datasource_avro::avro_to_arrow::ReaderBuilder;
use datafusion_common::Result;
use arrow::array::Array;
use arrow::record_batch::RecordBatch;
use std::iter::Iterator;

fn avro_null_counts(path: &str) -> Result<Vec<(String, usize)>> {
    let file = File::open(path)?;
    let reader = ReaderBuilder::new().build(file)?;
    let mut null_counts = vec![];

    for batch in reader {
        let batch = batch?;
        for i in 0..batch.num_columns() {
            let array = batch.column(i);
            let name = batch.schema().field(i).name().to_string();
            let count = count_nulls(array);
            null_counts.push((name, count));
        }
    }

    Ok(null_counts)
}

fn count_nulls(array: &dyn Array) -> usize {
    let mut count = 0;
    for i in 0..array.len() {
        if array.is_null(i) {
            count += 1;
        }
    }
    count
}

