fn apply_conditional_style<W>(backend: &mut CrosstermBackend<W>, cell: &Cell, highlight: bool) -> std::io::Result<()>
where
    W: std::io::Write,
{
    if highlight {
        queue!(backend, SetColors(CrosstermColors::new(Color::Red, Color::Black)))?;
        queue!(backend, Print(cell.rendered))?; // Render the cell content
        queue!(backend, SetColors(CrosstermColors::new(Color::Reset, Color::Reset)))?;
    } else {
        queue!(backend, SetColors(CrosstermColors::new(Color::Green, Color::Black)))?;
        queue!(backend, Print(cell.rendered))?;
        queue!(backend, SetColors(CrosstermColors::new(Color::Reset, Color::Reset)))?;
    }
    Ok(())
}

fn convert_with_headers<R: std::io::Read>(
    reader: R,
    header_map: &HashMap<String, String>,
) -> Vec<CsvMap> {
    let mut csv_reader = CsvReader::new(reader);
    let mut result = Vec::new();
    let headers = csv_reader.headers().unwrap();

    for record in csv_reader.records() {
        let mut csv_map = CsvMap::new();
        for (source_header, target_key) in header_map {
            if let Some(value) = record.get(source_header.as_str()) {
                csv_map.insert(target_key.clone(), value.to_string());
            }
        }
        result.push(csv_map);
    }

    result
}

