fn linear_backoff(base: Duration, step: Duration, attempts: usize) -> impl Iterator<Item = Duration> {
    let mut current = base;
    std::iter::from_fn(move || {
        if attempts == 0 {
            None
        } else {
            attempts -= 1;
            let dur = current;
            current += step;
            Some(dur)
        }
    })
}

use ssi_caips::caip10::BlockchainAccountId;
use ssi_caips::caip2::ChainId;
use ssi_dids_core::{document::{Document, ValueOrReference}, DIDBuf, DIDURLBuf};
use crate::{PkhVerificationMethod, PkhVerificationMethodType, JsonLdContext, GenerateError};

fn build_tezos_did(account_address: &str, reference: &str) -> Result<(Document, JsonLdContext), GenerateError> {
    let did = format!("did:pkh:tezos:{}", account_address);
    let did_buf = DIDBuf::from(did.as_str()).map_err(|_| GenerateError::InvalidDID)?;
    let did_url = DIDURLBuf::from(did.as_str()).map_err(|_| GenerateError::InvalidDID)?;

    let mut verification_methods = Vec::new();

    // Add Ed25519 verification method
    let ed25519_method = PkhVerificationMethod {
        id: format!("{}#ed25519", did),
        type_: PkhVerificationMethodType::Ed25519,
        controller: did_buf,
        public_key: account_address.to_string(),
        reference: reference.to_string(),
    };
    verification_methods.push(ValueOrReference::Value(ed25519_method));

    // Add TezosMethod2021 verification method
    let tezos_method = PkhVerificationMethod {
        id: format!("{}#tezosmethod2021", did),
        type_: PkhVerificationMethodType::TezosMethod2021,
        controller: did_buf,
        public_key: account_address.to_string(),
        reference: reference.to_string(),
    };
    verification_methods.push(ValueOrReference::Value(tezos_method));

    let mut document = Document::new(did_url, Some(verification_methods));
    document
        .context
        .push(JsonLdContext::new(
            "https://www.w3.org/2019/05/ld-contexts/did/v1",
        ));
    document
        .context
        .push(JsonLdContext::new(
            "https://w3id.org/tezos/did/v1",
        ));

    Ok((document, JsonLdContext::new("https://w3id.org/tezos/did/v1")))
}

