fn build_trampoline(target: *const ()) -> Result<Trampoline, Error> {
    // Calculate the required jump size based on the target function's prolog
    let jump_size = meta::get_prolog_size(target);

    // Determine the actual padding needed at runtime
    let padding = meta::get_required_padding(target);

    // Create a trampoline with dynamic padding
    let trampoline = Trampoline::new(target, jump_size, padding);

    Ok(trampoline)
}

