use crate::model::{Conf, Geometry};

fn usable_display_geometry(conf: &Conf, geom: &Geometry, display_index: usize) -> Geometry {
    // Calculate the usable area by subtracting borders and gap
    let left = geom.x + conf.borders.left;
    let top = geom.y + conf.borders.top;
    let right = geom.x + geom.width - conf.borders.right;
    let bottom = geom.y + geom.height - conf.borders.bottom;

    // Apply gap if it's not the last display
    let gap = if display_index < conf.displays.len() - 1 {
        conf.gap
    } else {
        0
    };

    let usable_width = right - left - gap;
    let usable_height = bottom - top - gap;

    Geometry {
        x: left,
        y: top,
        width: usable_width,
        height: usable_height,
    }
}

use metaheuristics_nature::prelude::*;
use metaheuristics_nature::methods::rga::Rga;

fn new() -> Self {
    Rga::new(|individual: &mut Vec<f64>| {
        // Example: Adaptive mutation delta based on generation number
        let mut delta = 0.1;
        if generation < 50 {
            delta = 0.5; // Larger delta for early exploration
        } else if generation >= 50 && generation < 150 {
            delta = 0.3; // Moderate delta for balanced exploration and exploitation
        } else {
            delta = 0.1; // Smaller delta for fine-tuning in later generations
        }

        // Apply mutation
        for i in 0..individual.len() {
            let mut rand = rand::thread_rng();
            let mut value = individual[i];
            let mut noise = rand.normal_f64() * delta;
            value += noise;
            individual[i] = value;
        }
    })
}

