use crate::{Vfox, VfoxError};
use std::path::Path;
use std::fs;
use std::io::Write;
use std::process::Command;

fn install_sdks_batch(vfox: &mut Vfox, sdks_and_versions: Vec<(&str, &str)>) -> Result<(), VfoxError> {
    for (sdk_name, version) in sdks_and_versions {
        log_step(&format!("Starting installation of {} {}", sdk_name, version));

        // Check if the version is available
        if !check_version_available(vfox, sdk_name, version)? {
            return Err(VfoxError::VersionNotFound(format!("Version {} for SDK {} is not available", version, sdk_name)));
        }

        // Ensure plugins are installed
        if !ensure_plugins_installed(vfox, sdk_name)? {
            return Err(VfoxError::PluginInstallationFailed(format!("Failed to install plugins for SDK {}", sdk_name)));
        }

        // Download the SDK
        if !download_sdk(vfox, sdk_name, version)? {
            return Err(VfoxError::DownloadFailed(format!("Failed to download SDK {} version {}", sdk_name, version)));
        }

        // Install the SDK
        if !install_sdk(vfox, sdk_name, version)? {
            return Err(VfoxError::InstallationFailed(format!("Failed to install SDK {} version {}", sdk_name, version)));
        }

        log_step(&format!("Successfully installed {} {}", sdk_name, version));
    }

    Ok(())
}

fn check_version_available(vfox: &mut Vfox, sdk_name: &str, version: &str) -> Result<bool, VfoxError> {
    let available_versions = vfox.list_sdk_versions(sdk_name)?;
    Ok(available_versions.contains(&version.to_string()))
}

fn ensure_plugins_installed(vfox: &mut Vfox, sdk_name: &str) -> Result<bool, VfoxError> {
    let plugins = vfox.list_plugins()?;
    for plugin in plugins {
        if !vfox.install_plugin(plugin)? {
            return Ok(false);
        }
    }
    Ok(true)
}

fn download_sdk(vfox: &mut Vfox, sdk_name: &str, version: &str) -> Result<bool, VfoxError> {
    let download_path = vfox.get_download_path()?;
    let sdk_path = Path::new(&download_path).join(format!("{}-{}", sdk_name, version));

    if sdk_path.exists() {
        log_step(&format!("SDK {} version {} already downloaded", sdk_name, version));
        return Ok(true);
    }

    if !vfox.download_sdk(sdk_name, version, &download_path)? {
        return Err(VfoxError::DownloadFailed(format!("Failed to download SDK {} version {}", sdk_name, version)));
    }

    log_step(&format!("Downloaded SDK {} version {}", sdk_name, version));
    Ok(true)
}

fn install_sdk(vfox: &mut Vfox, sdk_name: &str, version: &str) -> Result<bool, VfoxError> {
    let install_path = vfox.get_install_path()?;
    let sdk_path = Path::new(&install_path).join(format!("{}-{}", sdk_name, version));

    if sdk_path.exists() {
        log_step(&format!("SDK {} version {} already installed", sdk_name, version));
        return Ok(true);
    }

    if !vfox.extract_sdk(&sdk_path)? {
        return Err(VfoxError::InstallationFailed(format!("Failed to install SDK {} version {}", sdk_name, version)));
    }

    log_step(&format!("Installed SDK {} version {}", sdk_name, version));
    Ok(true)
}

fn log_step(message: &str) {
    let log_file = Path::new("installation.log");
    let mut file = std::fs::File::create(log_file).unwrap();
    writeln!(file, "[{}] {}", chrono::Local::now().format("%Y-%m-%d %H:%M:%S"), message).unwrap();
}

