use oxc_cfg::{ControlFlowGraphBuilder, EdgeType, ErrorEdgeKind, CtxFlags};
use oxc_syntax::node::NodeId;

fn add_conditional_branch(
    builder: &mut ControlFlowGraphBuilder<'_>,
    condition_node: NodeId,
    true_block: BlockNodeId,
    false_block: BlockNodeId,
) {
    // Insert the condition instruction
    builder.insert_instruction(condition_node, EdgeType::Cond, true_block, false_block);

    // Add the true branch edge
    builder.add_edge(condition_node, true_block, EdgeType::Cond, CtxFlags::empty());

    // Add the false branch edge
    builder.add_edge(condition_node, false_block, EdgeType::Cond, CtxFlags::empty());
}

