pub fn generate_dependency_summary(dependencies: &[&str]) -> String {
    let mut categories: std::collections::HashMap<&str, Vec<&str>> = std::collections::HashMap::new();
    for dep in dependencies {
        let category = dep.split('-').next().unwrap_or("unknown");
        categories.entry(category).or_default().push(*dep);
    }
    let mut summary = String::new();
    for (cat, deps) in categories.iter() {
        summary.push_str(&format!("{}\n", cat));
        for d in deps {
            summary.push_str(&format!("  - {}\n", d));
        }
    }
    summary
}

