fn list_files_up_to_depth<'a>(
    store: &'a dyn ObjectStore,
    table_path: &'a ListingTableUrl,
    max_depth: usize,
    file_extension: &'a str,
) -> Result<BoxStream<'a, Result<PartitionedFile>>> {
    let mut stream = list_partitions(store, table_path, max_depth, file_extension);

    let stream = stream.map(move |partition| {
        let mut depth = 0;
        let mut files = Vec::new();

        let mut partition_stream = list_partitions(store, &partition.url, depth, file_extension);

        while let Some(file) = partition_stream.next().transpose()? {
            if file.url.ends_with(file_extension) {
                files.push(file);
            }
        }

        Ok(PartitionedFile {
            url: partition.url.clone(),
            partition: partition.partition.clone(),
            files,
        })
    });

    Ok(Box::pin(stream))
}

fn colorize_log(line: &str) -> String {
    let mut result = String::new();
    let mut chars = line.chars().peekable();

    while let Some(c) = chars.next() {
        if c == '(' {
            let level = chars.clone().take_while(|&ch| ch != ')').collect::<String>();
            if level == "ERROR" {
                let _ = write!(result, "{}", Style::new(Colour::Red).bold().paint("ERROR"));
            } else if level == "WARN" {
                let _ = write!(result, "{}", Style::new(Colour::Yellow).bold().paint("WARN"));
            } else if level == "INFO" {
                let _ = write!(result, "{}", Style::new(Colour::Green).bold().paint("INFO"));
            } else {
                let _ = write!(result, "({})", level);
            }
            // Skip the closing parenthesis
            chars.next();
        } else {
            let _ = write!(result, "{}", c);
        }
    }

    result
}

