use crate::signature::Signature;

fn fixed_size(sig: &Signature) -> Option<usize> {
    match sig {
        Signature::Empty => Some(0),
        Signature::Bool => Some(1),
        Signature::Byte => Some(1),
        Signature::Int16 => Some(2),
        Signature::UInt16 => Some(2),
        Signature::Int32 => Some(4),
        Signature::UInt32 => Some(4),
        Signature::Int64 => Some(8),
        Signature::UInt64 => Some(8),
        Signature::Int128 => Some(16),
        Signature::UInt128 => Some(16),
        Signature::Double => Some(8),
        Signature::String => None,
        Signature::ObjectPath => None,
        Signature::Signature => None,
        Signature::Array(inner) => {
            if let Some(size) = fixed_size(inner) {
                Some(size)
            } else {
                None
            }
        }
        Signature::DictEntry(key, value) => {
            if let Some(k_size) = fixed_size(key) {
                if let Some(v_size) = fixed_size(value) {
                    Some(k_size + v_size)
                } else {
                    None
                }
            } else {
                None
            }
        }
        _ => None,
    }
}

fn filter_valid_addresses(addresses: &[Multiaddr], transport: Transport) -> Vec<Multiaddr> {
    match transport {
        Transport::Tcp => addresses.iter().filter(|&&addr| is_tcp_addr(&addr)).cloned().collect(),
        Transport::Quic => addresses.iter().filter(|&&addr| is_quic_addr(&addr, false)).cloned().collect(),
        Transport::QuicV1 => addresses.iter().filter(|&&addr| is_quic_addr(&addr, true)).cloned().collect(),
    }
}

enum Transport {
    Tcp,
    Quic,
    QuicV1,
}

fn is_quic_addr(addr: &Multiaddr, v1: bool) -> bool {
    use libp2p_core::multiaddr::Protocol::*;
    let mut iter = addr.iter();
    let Some(first) = iter.next() else { return false; };
    let Some(second) = iter.next() else { return false; };
    let Some(third) = iter.next() else { return false; };
    let fourth = iter.next();
    let fifth = iter.next();
    matches!(first, Ip4(_) | Ip6(_) | Dns(_) | Dns4(_) | Dns6(_))
        && matches!(second, Udp(_))
        && if v1 { matches!(third, QuicV1) } else { matches!(third, Quic) }
        && matches!(fourth, Some(P2p(_)) | None)
        && fifth.is_none()
}

fn is_tcp_addr(addr: &Multiaddr) -> bool {
    use libp2p_core::multiaddr::Protocol::*;
    let mut iter = addr.iter();
    let Some(first) = iter.next() else { return false; };
    let Some(second) = iter.next() else { return false; };
    matches!(first, Ip4(_) | Ip6(_) | Dns(_) | Dns4(_) | Dns6(_)) && matches!(second, Tcp(_))
}

