fn serialize_model<W: Write>(model: &Model, writer: &mut W) -> std::io::Result<()> {
    // Write the number of features
    writer.write_all(&(model.num_features as u32).to_le_bytes())?;

    // Write the number of parameters
    writer.write_all(&(model.params.len() as u32).to_le_bytes())?;

    // Write each parameter value
    for &param in &model.params {
        writer.write_all(&param.to_le_bytes())?;
    }

    // Write the number of layers
    writer.write_all(&(model.layers.len() as u32).to_le_bytes())?;

    // Write each layer's configuration
    for layer in &model.layers {
        writer.write_all(&(layer.activation as u8).to_le_bytes())?;
        writer.write_all(&(layer.size as u32).to_le_bytes())?;
    }

    Ok(())
}

fn with_required_query<S, H, O>(self, path: S, handler: H) -> Self
where
    S: AsRef<str>,
    H: Handler<Request, Output = Result<O>> + Clone,
    O: IntoResponse,
{
    self.route(path, move |req: Request| {
        let query = req.query();
        if let Some(id) = query.get("id") {
            if !id.is_empty() {
                handler.handle(req)
            } else {
                Ok(StatusCode::BAD_REQUEST.into_response())
            }
        } else {
            Ok(StatusCode::BAD_REQUEST.into_response())
        }
    })
}

use std::process::{Command, Stdio};
use std::fs::File;
use std::io::{Read, Write};

fn main() {
    // Define the input file path
    let input_file = "input.txt";

    // Read input data from the file
    let mut input_data = String::new();
    match File::open(input_file) {
        Ok(mut file) => {
            if let Err(e) = file.read_to_string(&mut input_data) {
                eprintln!("Failed to read input file: {}", e);
                return;
            }
        },
        Err(e) => {
            eprintln!("Failed to open input file: {}", e);
            return;
        }
    }

    // Run the 'sort' command with the input data
    let mut cmd = Command::new("sort");
    cmd.stdin(Stdio::piped())
      .stdout(Stdio::piped())
      .stderr(Stdio::piped());

    let mut child = match cmd.spawn() {
        Ok(child) => child,
        Err(e) => {
            eprintln!("Failed to start sort command: {}", e);
            return;
        }
    };

    // Write input data to the command's stdin
    if let Err(e) = child.stdin.unwrap().write_all(input_data.as_bytes()) {
        eprintln!("Failed to write input to sort command: {}", e);
        return;
    }

    // Wait for the command to finish
    let status = child.wait().expect("Failed to wait on sort command");

    // Read standard output
    let mut stdout = String::new();
    if let Ok(_) = child.stdout.unwrap().read_to_string(&mut stdout) {
        println!("Sorted output:\n{}", stdout);
    } else {
        eprintln!("Failed to read standard output from sort command");
    }

    // Read standard error
    let mut stderr = String::new();
    if let Ok(_) = child.stderr.unwrap().read_to_string(&mut stderr) {
        eprintln!("Sort command error:\n{}", stderr);
    } else {
        eprintln!("Failed to read standard error from sort command");
    }

    // Check if the command exited successfully
    if !status.success() {
        eprintln!("Sort command failed with exit code: {}", status.code().unwrap());
    }
}

fn validate_date_argument(ctx: &mut Context<'_>, arg: &Positioned<ast::InputValueDefinition>) {
    if arg.typ.name() != "Date" {
        return;
    }

    if let Some(default_value) = &arg.default_value {
        if default_value.kind != ast::DefaultValueKind::Literal {
            ctx.report(miette::Report::new("Date argument default value must be a literal")
                .with_source_code(arg.span.source())
                .with_position(arg.span.start));
            return;
        }
    } else {
        ctx.report(miette::Report::new("Date argument must have a default value")
            .with_source_code(arg.span.source())
            .with_position(arg.span.start));
        return;
    }

    if let Some(default_value) = &arg.default_value {
        if let Some(value) = default_value.literal_value() {
            if value.kind != ast::ScalarValueKind::String {
                ctx.report(miette::Report::new("Date argument default value must be a string")
                    .with_source_code(arg.span.source())
                    .with_position(arg.span.start));
                return;
            }
        }
    }
}

fn generate_cache_control(file: &impl EmbedableFile) -> String {
    let mime_type = file.mime_type();
    let last_modified = file.last_modified();

    if mime_type.starts_with("image/") {
        "public, max-age=31536000".to_string()
    } else if mime_type.starts_with("text/") {
        let age = (chrono::Utc::now() - last_modified).num_seconds() as u64;
        if age < 3600 {
            "public, max-age=3600".to_string()
        } else {
            "public, max-age=600".to_string()
        }
    } else {
        "public, max-age=3600".to_string()
    }
}

fn monitor_volume_status(
    ec2_manager: &aws_manager::ec2::Manager,
    volume_id: &str,
    target_state: aws_sdk_ec2::types::VolumeState,
    timeout: std::time::Duration,
) -> Result<(), String> {
    let mut remaining_timeout = timeout;
    let mut last_state = None;

    while remaining_timeout > Duration::from_secs(0) {
        let filters = vec![Filter::builder()
            .name("volume-id")
            .values(volume_id)
            .build()];
        let volumes = ec2_manager.volumes().filters(filters).send();

        match volumes.await {
            Ok(volumes) => {
                if let Some(volume) = volumes.volumes().next() {
                    let current_state = volume.state().unwrap_or(&VolumeState::Unknown);
                    let current_state_str = current_state.as_str();

                    if current_state == &target_state {
                        log::info!("Volume {} reached target state: {}", volume_id, current_state_str);
                        return Ok(());
                    } else if last_state != Some(current_state_str.to_string()) {
                        log::info!("Volume {} is in state: {}", volume_id, current_state_str);
                        last_state = Some(current_state_str.to_string());
                    }
                } else {
                    log::warn!("No volume found with ID {}", volume_id);
                    return Err(format!("Volume not found: {}", volume_id));
                }
            }
            Err(e) => {
                log::error!("Error fetching volume status: {}", e);
                return Err(e.to_string());
            }
        }

        sleep(Duration::from_secs(5)).await;
        remaining_timeout -= Duration::from_secs(5);
    }

    log::warn!("Timeout reached. Volume {} did not reach the target state.", volume_id);
    Err(format!("Timeout reached. Volume {} did not reach the target state.", volume_id))
}

use risc0_binfmt::{Program, MemoryImage, KERNEL_START_ADDR, Digest};
use anyhow::{Result, Context};

fn build_and_validate_image(user_elf: &[u8], kernel_elf: &[u8], expected: &Digest) -> Result<MemoryImage> {
    // Parse user ELF
    let user_program = Program::parse_elf(user_elf)
        .with_context(|| "Failed to parse user ELF")?;

    // Parse kernel ELF
    let kernel_program = Program::parse_elf(kernel_elf)
        .with_context(|| "Failed to parse kernel ELF")?;

    // Build memory image
    let mut memory_image = MemoryImage::new();
    memory_image.add_program(&user_program)
        .with_context(|| "Failed to add user program to memory image")?;
    memory_image.add_program(&kernel_program)
        .with_context(|| "Failed to add kernel program to memory image")?;

    // Validate image ID matches expected digest
    let image_id = memory_image.id();
    if image_id != expected {
        return Err(anyhow::anyhow!("Image ID mismatch: expected {:x}, got {:x}", expected, image_id));
    }

    Ok(memory_image)
}

