            }
        }
    }
}

use std::io::{self, Read, Seek};
use riff_wave::WaveReader;

fn extract_samples_in_range<R: Read + Seek>(mut reader: R, start_sec: f64, end_sec: f64) -> io::Result<Vec<i16>> {
    let wave = WaveReader::new(&mut reader)?;
    let sample_rate = wave.sample_rate();
    let num_channels = wave.channels();

    let start_sample = (start_sec * sample_rate as f64) as u64;
    let end_sample = (end_sec * sample_rate as f64) as u64;

    let mut samples = Vec::new();
    let mut current_sample = 0;

    // Seek to the start of the audio data
    let data_start = wave.data_start();
    reader.seek(io::SeekFrom::Start(data_start))?; // Seek to the beginning of the data

    // Skip to the start sample
    let samples_per_frame = num_channels;
    let skip_samples = start_sample * samples_per_frame;
    let mut buffer = vec![0; skip_samples as usize * 2];
    reader.read_exact(&mut buffer)?; // Skip the initial samples

    // Read samples in the desired range
    while current_sample < end_sample {
        let mut buffer = vec![0; samples_per_frame * 2];
        reader.read_exact(&mut buffer)?;
        let buffer_samples: Vec<i16> = buffer.chunks(2)
            .map(|chunk| i16::from_le_bytes(chunk.try_into().unwrap()))
            .collect();
        samples.extend(buffer_samples);
        current_sample += samples_per_frame;
    }

    Ok(samples)
}

