fn restore_store(
    &self,
    context: Option<Context>,
    bucket: String,
    file_path: &str,
) -> anyhow::Result<()> {
    let store = self.get_store(&bucket)?;
    let content = fs::read(file_path).await?;
    let lines: Vec<String> = std::str::from_utf8(&content)
        .map_err(|e| anyhow!("Failed to read file content: {}", e))?
        .lines()
        .map(str::to_string)
        .collect();

    for line in lines {
        let obj: serde_json::Value = serde_json::from_str(&line).map_err(|e| anyhow!("Failed to parse JSON line: {}", e))?;
        let key = obj["key"].as_str().ok_or(anyhow!("Missing 'key' field in JSON"))?;
        let value = obj["value"].as_str().ok_or(anyhow!("Missing 'value' field in JSON"))?;

        let decoded = base64::decode(value).map_err(|e| anyhow!("Failed to decode base64 value: {}", e))?;
        store.upsert(key, &decoded).await?;
    }

    Ok(())
}

fn get_store(&self, bucket: &str) -> anyhow::Result<Store> {
    let jetstream = self.jetstream()?;
    let store = jetstream.kv().store(bucket).await?;
    Ok(store)
}

struct BatchInversionHelper<F: Field> {
    scratch_pad: Vec<F>,
}

impl<F: Field> BatchInversionHelper<F> {
    fn new() -> Self {
        BatchInversionHelper {
            scratch_pad: Vec::new(),
        }
    }

    fn invert(&mut self, elements: &[F]) -> Vec<F> {
        let mut result = vec![F::zero(); elements.len()];
        let mut scratch = self.scratch_pad.clone();
        let mut needed = elements.len();

        if scratch.len() < needed {
            scratch.resize(needed, F::zero());
        }

        unsafe {
            batch_inverse_scratch_pad(elements, &mut scratch, &mut result);
        }

        self.scratch_pad = scratch;
        result
    }
}

