use fj::{Sketch, Chain, Circle, PolyChain, SketchSegment};

fn scaled(&self, factor: f64) -> Self {
    let scaled_chain = |chain: &Chain| {
        match chain {
            Chain::Circle(circle) => Chain::Circle(Circle {
                center: circle.center.map(|(x, y)| (x * factor, y * factor)),
                radius: circle.radius * factor,
                ..*circle
            }),
            Chain::PolyChain(poly_chain) => {
                let scaled_segments = poly_chain
                    .segments
                    .iter()
                    .map(|segment| match segment {
                        SketchSegment::Line((x1, y1), (x2, y2)) => {
                            SketchSegment::Line(
                                (x1 * factor, y1 * factor),
                                (x2 * factor, y2 * factor),
                            )
                        }
                        SketchSegment::Arc((x, y), radius, start_angle, end_angle) => {
                            SketchSegment::Arc(
                                (x * factor, y * factor),
                                radius * factor,
                                start_angle,
                                end_angle,
                            )
                        }
                    })
                    .collect::<Vec<_>>();
                Chain::PolyChain(PolyChain {
                    segments: scaled_segments,
                    ..*poly_chain
                })
            }
        }
    };

    Sketch {
        chains: self.chains.iter().map(scaled_chain).collect(),
        ..*self
    }
}

fn nearest_neighbor_indices<T: kd_tree::KdPoint>(points: &[T]) -> Vec<usize> {
    if points.is_empty() {
        return Vec::new();
    }

    let tree = KdIndexTree::new(points);
    let mut result = Vec::with_capacity(points.len());

    for i in 0..points.len() {
        let nearest = tree.nearest_neighbor(points[i], 1);
        if let Some((_, index)) = nearest.first() {
            result.push(*index);
        } else {
            result.push(i); // fallback if no neighbor found
        }
    }

    result
}

fn validate_constraints(feature: &ClientFeature) -> Result<(), String> {
    if let Some(constraints) = &feature.constraints {
        for constraint in constraints {
            // Check that context name is non-empty
            if constraint.context_name.is_empty() {
                return Err("Context name must be non-empty".to_string());
            }

            // Check that operator is known
            match &constraint.operator {
                Operator::Unknown(name) => {
                    return Err(format!("Unknown operator: {}", name));
                }
                _ => {}
            }
        }
    }

    Ok(())
}

