fn extract_signature_details(instructions: &[(&Pubkey, SVMInstruction)]) -> PrecompileSignatureDetails {
    let mut secp256k1_count = 0;
    let mut ed25519_count = 0;
    let mut secp256r1_count = 0;

    for (_, instruction) in instructions {
        if let Some(signature) = instruction.signature() {
            match signature {
                "secp256k1" => secp256k1_count += 1,
                "ed25519" => ed25519_count += 1,
                "secp256r1" => secp256r1_count += 1,
                _ => {}
            }
        }
    }

    PrecompileSignatureDetails {
        secp256k1: secp256k1_count,
        ed25519: ed25519_count,
        secp256r1: secp256r1_count,
    }
}

fn batch_lookup_icons(
    names: &[&str],
    theme: &str,
    size: u16,
    scale: u16,
) -> std::collections::HashMap<String, std::path::PathBuf> {
    let mut cache = HashMap::new();
    let mut result = HashMap::new();

    for &name in names {
        let key = format!("{}-{}-{}", name, theme, size);
        if let Some(path) = cache.get(&key) {
            result.insert(name.to_string(), path.clone());
            continue;
        }

        let path = lookup(name, theme, size, scale);
        if let Some(path) = path {
            cache.insert(key, path.clone());
            result.insert(name.to_string(), path);
        }
    }

    result
}

use std::fs::File;
use std::io::{self, Read, Write};
use compress_manager::Encoder;
use flate2::bufread::GzEncoder;
use flate2::Compression;

fn compress_with_progress(src_path: &str, dst_path: &str, enc: Encoder, mut progress: impl FnMut(u64)) -> io::Result<()> {
    let src_file = File::open(src_path)?;
    let mut src = io::BufReader::new(src_file);

    let dst_file = File::create(dst_path)?;
    let mut dst = GzEncoder::new(dst_file, Compression::default());

    let mut buffer = [0; 1024 * 16]; // 64KB buffer
    let mut total_bytes_read = 0;

    loop {
        let bytes_read = src.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }
        total_bytes_read += bytes_read as u64;
        progress(total_bytes_read);

        dst.write_all(&buffer[..bytes_read])?;
    }

    dst.flush()?;
    Ok(())
}

