fn text_to_hid_report(text: &str) -> [u8; 8] {
    let mut state = KeyboardState::new();
    let mut report = [0u8; 8];

    for c in text.chars() {
        if c.is_ascii() {
            if let Some(key_id) = KeyMap::get_key_id(c) {
                state.press_key(key_id);
            }
        }
    }

    report.copy_from_slice(&state.get_report());
    report
