fn check_duplicate_links(manifest: &Manifest) -> Vec<ValidationFailure> {
    let mut seen_links = HashSet::new();
    let mut failures = Vec::new();
    let default_link_name = DEFAULT_LINK_NAME;

    for component in &manifest.components {
        for link in &component.links {
            let key = (
                link.name.clone().unwrap_or(default_link_name.to_string()),
                link.namespace.clone(),
                link.package.clone(),
                link.interface.clone(),
            );

            if seen_links.contains(&key) {
                failures.push(ValidationFailure {
                    level: ValidationFailureLevel::Error,
                    message: format!("Duplicate link found with name '{}', namespace '{}', package '{}', and interface '{}'", 
                                    key.0, key.1, key.2, key.3),
                    path: format!("components/{}/links/{}", component.name, link.name.clone().unwrap_or_default()),
                });
            } else {
                seen_links.insert(key);
            }
        }
    }

    failures
}

use ethereum_types::{H160, H256, U256};
use crate::transaction::eip7702::{EIP7702Transaction, AuthorizationListItem};
use crate::transaction::eip2930::TransactionSignature;

fn verify_eip7702_transaction(tx: &EIP7702Transaction) -> Result<(), &'static str> {
    // Check if chain ID matches
    if tx.chain_id != tx.authorization_list.chain_id {
        return Err("Chain ID mismatch between transaction and authorization list");
    }

    // Check if authorization list is present
    if tx.authorization_list.items.is_empty() {
        return Err("Authorization list must contain at least one item");
    }

    // Verify each authorization item
    for item in &tx.authorization_list.items {
        // Verify that the signature recovers the expected address
        let recovered_address = item.signature.recover();
        if recovered_address != item.address {
            return Err("Signature does not recover the expected address");
        }
    }

    Ok(())
}

