fn create_linear_gradient_with_transform(
    id: &str,
    colors: &[Color],
    transform: Transform,
) -> EcoString {
    let mut writer = XmlWriter::new();
    writer.start_element("linearGradient");
    writer.write_attribute("id", id);
    writer.write_attribute("gradientTransform", &transform_to_svg_matrix(transform));
    writer.start_element("stop");
    writer.write_attribute("offset", "0%");
    writer.write_attribute("stop-color", &color_to_svg(colors[0]));
    writer.end_element();
    writer.start_element("stop");
    writer.write_attribute("offset", "100%");
    writer.write_attribute("stop-color", &color_to_svg(colors[1]));
    writer.end_element();
    writer.end_element();
    writer.into_string()
}

fn transform_to_svg_matrix(transform: Transform) -> EcoString {
    let matrix = transform.to_matrix();
    let m = SvgMatrix {
        a: matrix.a,
        b: matrix.b,
        c: matrix.c,
        d: matrix.d,
        e: matrix.e,
        f: matrix.f,
    };
    EcoString::from(format!("matrix({},{},{},{},{},{})", m.a, m.b, m.c, m.d, m.e, m.f))
}

fn color_to_svg(color: &Color) -> EcoString {
    match color {
        Color::Rgb(r, g, b) => EcoString::from(format!("rgb({},{},{})", r, g, b)),
        Color::Rgba(r, g, b, a) => EcoString::from(format!("rgba({},{},{},{}]", r, g, b, a)),
        Color::Hsl(h, s, l) => EcoString::from(format!("hsl({},{},{})", h, s, l)),
        Color::Hsla(h, s, l, a) => EcoString::from(format!("hsla({},{},{},{}]", h, s, l, a)),
        Color::Keyword(k) => EcoString::from(k.to_string()),
    }
}

fn generate_partition_filter<'a, I>(columns: I, value_map: &'a HashMap<String, String>) -> Result<Expr, DataFusionError>
where
    I: IntoIterator<Item = &'a str>,
{
    let mut exprs = Vec::new();
    for &col_name in columns {
        if let Some(value) = value_map.get(col_name) {
            let col_expr = col(col_name);
            let lit_expr = lit(value);
            let eq_expr = binary_expr(col_expr, Operator::Eq, lit_expr);
            exprs.push(eq_expr);
        }
    }
    if exprs.is_empty() {
        Ok(lit(true))
    } else {
        Ok(exprs.into_iter().fold(exprs[0].clone(), |acc, expr| binary_expr(acc, Operator::And, expr)))
    }
}

fn setup_breakpad_with_logging<P: AsRef<std::path::Path>>(crash_dir: P, hub: std::sync::Arc<sentry_core::Hub>) -> Result<breakpad_handler::BreakpadHandler, crate::Error> {
    let crash_dir = crash_dir.as_ref().to_path_buf();
    let handler = BreakpadHandler::new(
        crash_dir,
        InstallOptions {
            minidump_path: Some(crash_dir),
            ..Default::default()
        },
    );

    let log_handler = move |minidump_path: &std::path::Path| {
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();
