    &mut self,
    program_addresses: &[Pubkey],
    rpc_client: &RpcClient,
) -> Result<&mut Self, String> {
    let mut cloned_programs = HashSet::new();
    let mut program_data = HashSet::new();

    for &program_address in program_addresses {
        let account = rpc_client.get_account(&program_address).map_err(|e| format!("Failed to get account for program: {}", e))?;

        if let Some(UpgradeableLoaderState::Upgradeable { programdata_address, .. }) = account.state() {
            // Clone the program
            if let Ok(program_data) = rpc_client.get_account(&program_address) {
                cloned_programs.insert(program_address);
                // Clone the associated programdata
                if let Ok(programdata) = rpc_client.get_account(&programdata_address) {
                    program_data.insert(programdata_address);
                }
            }
        }
    }

    // Assuming self has a method to add cloned programs and their data
    self.add_cloned_programs(cloned_programs);
    self.add_cloned_program_data(program_data);

    Ok(self)
}

