fn calculate_checksum(buf: &[u8]) -> u16 {
    let mut sum = 0u32;
    let mut i = 0;
    while i < buf.len() {
        let word = (buf[i] as u16) << 8 | buf[i + 1] as u16;
        sum += word as u32;
        i += 2;
    }
    while sum > 0xffff {
        sum = (sum >> 16) + (sum & 0xffff);
    }
    sum as u16
}

use std::io;
use std::path::Path;
use std::sync::Arc;
use tokio::fs::File;
use tokio::io::AsyncReadExt;
use object_store::{ObjectStore, PutPayload};
use vortex_buffer::ByteBufferMut;
use futures_util::future::try_join_all;

fn upload_file_in_chunks(
    object_store: Arc<dyn ObjectStore>,
    location: &Path,
    file_path: impl AsRef<Path>,
) -> io::Result<()> {
    let file = File::open(file_path.as_ref()).await?;
    let metadata = file.metadata().await?;
    let file_size = metadata.len();

    // Define chunk size
    const CHUNK_SIZE: u64 = 1024 * 1024 * 5; // 5 MB

    let mut offset = 0;
    let mut buffer = ByteBufferMut::new(CHUNK_SIZE as usize);

    while offset < file_size {
        let remaining = file_size - offset;
        let chunk_size = std::cmp::min(CHUNK_SIZE, remaining);

        // Read chunk
        let n = file.read_buf(&mut buffer).await?;
        if n < chunk_size as usize {
            buffer.truncate(n);
        }

        // Upload chunk
        let payload = PutPayload::from_bytes(buffer.as_ref());
        object_store.put(location.join(format!("part_{}", offset / CHUNK_SIZE)), payload).await?;

        offset += chunk_size;
        buffer.clear();
    }

    Ok(())
}

