fn generate_report<K1, K2, V>(map: &MultiMap<K1, K2, V>) -> String
where
    K1: Eq + Hash + Clone + std::fmt::Display + std::ops::Rem<Output = K1> + From<u8>,
    K2: Eq + Hash + Clone + std::fmt::Display,
    V: std::fmt::Display,
{
    let mut report = String::new();
    let mut first = true;

    for entry in map.iter() {
        let primary = entry.key();
        let secondary = entry.secondary_key();
        let value = entry.value();

        if primary % 2 == K1::from(0) {
            if let Some(prefix) = secondary.strip_prefix(&K2::from(0)) {
                if !first {
                    report.push('\n');
                }
                report.push_str(&format!("{}: {} -> {}", primary, secondary, value));
                first = false;
            }
        }
    }

    report
}

