use vcd::{Writer, TimescaleUnit, IdCode, Value};

fn generate_minimal_vcd(writer: &mut Writer<impl std::io::Write>, signal_names: &[&str]) -> std::io::Result<()> {
    // Write the VCD header
    writer.write_header()?;
    writer.write_id(IdCode::Vcd20)?;
    writer.write_timescale(TimescaleUnit::NanoSecond, 0)?;
    writer.write_date()?;
    writer.write_tool("minimal_vcd_generator")?;

    // Write the wire declarations
    for &name in signal_names {
        writer.write_var(Value::Wire, 0, 1, name, None)?;
    }

    // Write the initial state
    writer.write_time(0)?;
    for &name in signal_names {
        writer.write_value(name, Value::Logic0)?;
    }

    // Write the signal toggling over time
    let mut time = 10;
    let mut state = 0;
    for &name in signal_names {
        writer.write_time(time)?;
        writer.write_value(name, if state == 0 { Value::Logic1 } else { Value::Logic0 });
        state = 1 - state;
        time += 10;
    }

    Ok(())
}

