use tinyaudio::prelude::*;

fn create_stereo_ramp(channels: usize, samples_per_channel: usize) -> Vec<f32> {
    let mut buffer = Vec::with_capacity(channels * samples_per_channel);

    for sample in 0..samples_per_channel {
        for channel in 0..channels {
            let value = if channel % 2 == 0 {
                // Left channel ramps from -1.0 to 1.0
                (sample as f32 / (samples_per_channel as f32 - 1.0)) * 2.0 - 1.0
            } else {
                // Right channel ramps from 1.0 to -1.0
                -(sample as f32 / (samples_per_channel as f32 - 1.0)) * 2.0 + 1.0
            };
            buffer.push(value);
        }
    }

    buffer
}

