fn set_expiry(&self, cache_id: i64, request_url: &str, expiry_seconds: u64) -> Result<(), CacheError> {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_err(|e| CacheError::InvalidTimestamp(e.to_string()))?
        .as_secs();

    let expiry_time = now + expiry_seconds;

    let conn = self.conn.lock().unwrap();
    conn.execute(
        "UPDATE cache_entries SET timestamp = ?, request_url = ?, expiry_time = ? WHERE id = ?",
        (
            now,
            request_url,
            expiry_time,
            cache_id,
        ),
    )?;

    Ok(())
}

fn filter_stats_by_bytes(
    input_rx: async_channel::Receiver<Stats>,
    min_bytes_per_sec: u64,
) -> async_channel::Receiver<Stats> {
    let (sender, receiver) = async_channel::unbounded();
    let input_rx = input_rx;
    let min_bytes_per_sec = min_bytes_per_sec;

    spawn(async move {
        let mut last_time = std::time::Instant::now();
        let mut last_bytes = 0;

        while let Ok(stats) = input_rx.recv().await {
            let now = std::time::Instant::now();
            let elapsed = now.duration_since(last_time);
            let bytes = stats.bytes;

            if elapsed.as_secs() > 0 {
                let bytes_per_sec = (bytes as f64 / elapsed.as_secs_f64()) as u64;
                if bytes_per_sec >= min_bytes_per_sec {
                    sender.send(stats).await.unwrap();
                }
            }

            last_time = now;
            last_bytes = bytes;
        }
    });

    receiver
}

