fn check_daemon(pid_file: &PathBuf) -> Result<i32, io::Error> {
    // Read the PID from the file
    let contents = fs::read_to_string(pid_file)?;
    let pid_str = contents.trim();
    let pid: i32 = pid_str.parse().map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "Invalid PID in file"))?;

    // Check if the process is still running
    if let Err(e) = nix::sys::process::kill(Pid::from_raw(pid as u32), Signal::SIGUSR1) {
        if e.kind() == nix::Error::NoSuchProcess {
            return Err(io::Error::new(io::ErrorKind::NotFound, "Daemon process not running"));
        } else {
            return Err(io::Error::new(io::ErrorKind::Other, e.to_string()));
        }
    }

    Ok(pid)
}

