fn calculate_dominator_tree(cfg: &ControlFlowGraph) -> DiGraph<BlockNodeId, ()> {
    let mut dominators = DiGraph::new();
    let entry = cfg.entry();
    dominators.add_node(entry);

    // Initialize immediate dominators
    let mut idom = std::collections::HashMap::new();
    idom.insert(entry, None);

    // Compute immediate dominators using Lengauer-Tarjan algorithm
    let mut semi = std::collections::HashMap::new();
    let mut ancestor = std::collections::HashMap::new();
    let mut parent = std::collections::HashMap::new();
    let mut bucket = std::collections::HashMap::new();

    let nodes: Vec<BlockNodeId> = cfg.node_indices().collect();
    let mut nodes_iter = nodes.iter().peekable();

    if let Some(first) = nodes_iter.next() {
        if let Some(second) = nodes_iter.next() {
            let mut worklist = std::collections::VecDeque::new();
            worklist.push_back(*second);

            while let Some(node) = worklist.pop_front() {
                let mut semi_node = node;
                let mut ancestor_node = node;
                let mut bucket_list = std::collections::VecDeque::new();

                while let Some(&child) = parent.get(&semi_node) {
                    let mut s = child;
                    let mut p = idom.get(&s).copied().unwrap_or(*first);

                    while let Some(&a) = ancestor.get(&s) {
                        if a == p {
