                        semi_node = temp;
                    }

                    let mut tmp = semi_node;
                    while let Some(&a) = ancestor.get(&tmp) {
                        if a == semi_node {
                            break;
                        }
                        tmp = a;
                    }
                    semi_node = tmp;

                    if semi.get(&semi_node).copied().unwrap_or(*first) != semi_node {
                        semi.insert(semi_node, semi.get(&semi_node).copied().unwrap_or(*first));
                        worklist.push_back(semi_node);
                    }

                    if let Some(&parent_node) = parent.get(&semi_node) {
                        bucket.get_mut(&parent_node).unwrap().push(semi_node);
                    }

                    ancestor.insert(semi_node, ancestor.get(&s).copied().unwrap_or(*first));
                    parent.insert(semi_node, s);
                }

                let mut tmp = semi_node;
                while let Some(&a) = ancestor.get(&tmp) {
                    if a == semi_node {
