use std::io::Write;
use std::path::Path;
use miette::Result;
use crate::archive::{BinaryArchive, BinaryData, BinaryModifiedAt};
use crate::error::BuildError;
use zip::write::SimpleFileOptions;
use zip::CompressionMethod;

fn zip_binary_with_compression<BP, DD>(
    binary_path: BP,
    destination_directory: DD,
    data: &BinaryData,
    include: Option<Vec<String>>,
    compression: zip::CompressionMethod,
) -> Result<BinaryArchive>
where
    BP: AsRef<std::path::Path>,
    DD: AsRef<std::path::Path>,
{
    let binary_path = binary_path.as_ref();
    let destination_directory = destination_directory.as_ref();

    let mut zip = zip::ZipWriter::new(std::fs::File::create(destination_directory.join("output.zip"))?);

    let (binary_data, arch) = read_binary(
        &mut std::fs::File::open(binary_path)?,
        binary_path.display(),
    )?;

    let mut file_opts = zip_file_options_with_compression(
        &std::fs::metadata(binary_path)?,
        binary_path,
        compression,
    )?;

    zip.start_file("binary", file_opts)?;

    zip.write_all(&binary_data)?;

    if let Some(files) = include {
        include_files_in_zip(&mut zip, &files)?;
    }

    drop(zip);

    Ok(BinaryArchive {
        binary: BinaryData {
            data: binary_data,
            architecture: arch.to_string(),
            modified_at: BinaryModifiedAt::new(data.modified_at),
        },
        extra_files: data.extra_files.clone(),
    })
}

