fn sgr_parameters(actions: &[VTAction]) -> Vec<Vec<i64>> {
    let mut result = Vec::new();
    let mut current_params = Vec::new();

    for action in actions {
        match action {
            VTAction::CsiParam(param) => {
                current_params.push(*param as i64);
            }
            VTAction::CsiEscape => {
                if !current_params.is_empty() {
                    result.push(current_params);
                    current_params = Vec::new();
                }
            }
            _ => {}
        }
    }

    result
}

fn validate_transaction(data: &zino_core::Map) -> zino_core::validation::Validation {
    let mut validation = zino_core::validation::Validation::new();

    // Check if 'amount' field exists and is a positive number
    if !data.contains_key("amount") {
        validation.add_error("amount", "missing");
    } else if let Some(amount_str) = data.get("amount") {
        if let Some(amount) = amount_str.parse::<f64>().ok() {
            if amount <= 0.0 {
                validation.add_error("amount", "must be positive");
            }
        } else {
            validation.add_error("amount", "must be a number");
        }
    }

    // Check if 'currency' field exists and is in the allowed list
    let allowed_currencies = ["USD", "EUR", "GBP", "JPY", "CAD"];
    if !data.contains_key("currency") {
        validation.add_error("currency", "missing");
    } else if let Some(currency_str) = data.get("currency") {
        if let Some(currency) = currency_str.parse::<&str>().ok() {
            if !allowed_currencies.contains(&currency) {
                validation.add_error("currency", format!("must be one of: {:?}", allowed_currencies));
            }
        } else {
            validation.add_error("currency", "must be a string");
        }
    }

    // Check if 'type' is 'refund' and validate against original amount
    if data.contains_key("type") {
        if let Some(type_str) = data.get("type") {
            if let Some(type) = type_str.parse::<&str>().ok() {
                if type == "refund" {
                    if !data.contains_key("original_amount") {
                        validation.add_error("original_amount", "missing");
                    } else if let Some(original_amount_str) = data.get("original_amount") {
                        if let Some(original_amount) = original_amount_str.parse::<f64>().ok() {
                            if let Some(amount_str) = data.get("amount") {
                                if let Some(amount) = amount_str.parse::<f64>().ok() {
                                    if amount >= original_amount {
                                        validation.add_error("amount", "must be less than original amount");
                                    }
                                } else {
                                    validation.add_error("amount", "must be a number");
                                }
                            }
                        } else {
                            validation.add_error("original_amount", "must be a number");
                        }
                    }
                }
            } else {
                validation.add_error("type", "must be a string");
            }
        }
    }

    validation
}

