fn list_pending_proposals_with_status(
    deps: Deps,
    env: Env,
    start_after: Option<u64>,
    limit: u32,
) -> Result<Vec<ProposalWithStatus>, PreProposeError> {
    let approval_contract: Addr = PRE_PROPOSE_APPROVAL_CONTRACT.load(deps.storage)?;
    let approval_query = ApprovalQueryMsg::PendingProposals {
        start_after,
        limit,
    };
    let pending_proposals_response: PendingProposalsResponse = deps
        .querier
        .query_wasm_smart(approval_contract, approval_query)
        .map_err(|e| PreProposeError::QueryFailed {
            contract: approval_contract.to_string(),
            error: e.to_string(),
        })?;

    let mut proposals = Vec::new();
    for proposal in pending_proposals_response.proposals {
        let deposit_info: DepositInfoResponse = deps
            .querier
            .query_wasm_smart(
                approval_contract,
                ApprovalQueryMsg::DepositInfo {
                    proposal_id: proposal.id,
                },
            )
            .map_err(|e| PreProposeError::QueryFailed {
                contract: approval_contract.to_string(),
                error: e.to_string(),
            })?;

        let status: StatusResponse = deps
            .querier
            .query_wasm_smart(
                approval_contract,
                ApprovalQueryMsg::Status { proposal_id: proposal.id },
            )
            .map_err(|e| PreProposeError::QueryFailed {
                contract: approval_contract.to_string(),
                error: e.to_string(),
            })?;

        let deposit_amount = deposit_info
            .deposit
            .map(|d| d.amount)
            .unwrap_or(cosmwasm_std::Coin::new(0, "uusd"));
        let deposit_info_response = CheckedDepositInfo::new(deposit_amount, deposit_info.depositor)
            .map_err(|e| PreProposeError::InvalidDepositInfo {
                error: e.to_string(),
            })?;

        proposals.push(ProposalWithStatus {
            id: proposal.id,
            title: proposal.title,
            description: proposal.description,
            deposit_info: deposit_info_response,
            status: status.status,
        });
    }

    Ok(proposals)
}

