fn document_structs(input: proc_macro2::TokenStream) -> proc_macro2::TokenStream {
    let mut tokens = input.into_iter();
    let mut structs = Vec::new();
    let mut current_struct_name = None;
    let mut current_fields = Vec::new();
    let mut in_struct = false;

    while let Some(token) = tokens.next() {
        if let TokenTree::Ident(ident) = token {
            if ident.to_string() == "struct" {
                in_struct = true;
                current_struct_name = None;
                current_fields = Vec::new();
            } else if in_struct && current_struct_name.is_none() {
                current_struct_name = Some(ident.to_string());
            } else if in_struct && ident.to_string() == "impl" {
                in_struct = false;
                if let Some(name) = current_struct_name {
                    structs.push((name, current_fields));
                }
            } else if in_struct && ident.to_string() == "{" {
                // Field list starts
            } else if in_struct && ident.to_string() == "}" {
                in_struct = false;
                if let Some(name) = current_struct_name {
                    structs.push((name, current_fields));
                }
            } else if in_struct {
                current_fields.push(ident.to_string());
            }
        }
    }

    let mut result = TokenStream::new();
    let mut tokens = input.into_iter();

    while let Some(token) = tokens.next() {
        if let TokenTree::Ident(ident) = token {
            if ident.to_string() == "struct" {
                in_struct = true;
                current_struct_name = None;
                current_fields = Vec::new();
                result.extend(quote! { #token });
                continue;
            }
        }

        if in_struct && ident.to_string() == "impl" {
            in_struct = false;
            if let Some(name) = current_struct_name {
                let doc = current_fields.iter().map(|f| f.to_string()).collect::<Vec<_>>().join(", ");
                result.extend(quote! { #[doc = \"struct #name { #doc }\"] });
            }
        }

        result.extend(token);
    }

    result
}

use acir::native_types::{Expression, Witness};

fn extract_witness_indices(expr: &Expression) -> Vec<Witness> {
    match expr {
        Expression::Add(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::Sub(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::Mul(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::Neg(expr) => extract_witness_indices(expr),
        Expression::Const(_) => Vec::new(),
        Expression::Var(witness) => vec![*witness],
        Expression::BitwiseXor(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::BitwiseAnd(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::BitwiseOr(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::Shl(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::Shr(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::Eq(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::Neq(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::Lt(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::Gt(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::Leq(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::Geq(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::And(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::Or(lhs, rhs) => {
            let mut result = extract_witness_indices(lhs);
            result.extend(extract_witness_indices(rhs));
            result
        }
        Expression::Not(expr) => extract_witness_indices(expr),
        Expression::If(cond, then, else_expr) => {
            let mut result = extract_witness_indices(cond);
            result.extend(extract_witness_indices(then));
            result.extend(extract_witness_indices(else_expr));
            result
        }
        Expression::ArrayAccess(array, index) => {
            let mut result = extract_witness_indices(array);
            result.extend(extract_witness_indices(index));
            result
        }
        Expression::ArrayLength(array) => extract_witness_indices(array),
        Expression::FieldElement(_) => Vec::new(),
        Expression::UIntConstant(_) => Vec::new(),
        Expression::IntConstant(_) => Vec::new(),
        Expression::Tuple(exprs) => {
            let mut result = Vec::new();
            for expr in exprs {
                result.extend(extract_witness_indices(expr));
            }
            result
        }
        Expression::Let(name, value, body) => {
            let mut result = extract_witness_indices(value);
            result.extend(extract_witness_indices(body));
            result
        }
        Expression::Apply(func, args) => {
            let mut result = extract_witness_indices(func);
            for arg in args {
                result.extend(extract_witness_indices(arg));
            }
            result
        }
    }
}

