fn pretty_serialize_helper(document: &Document, result: &mut String, indent: usize) {
    match document {
        Document::Object(obj) => {
            if !obj.fields.is_empty() {
                result.push('{');
                result.push('\n');
                for (i, (key, value)) in obj.fields.iter().enumerate() {
                    for _ in 0..indent + 1 {
                        result.push(' ');
                    }
                    result.push_str(escape(key));
                    result.push(':');
                    result.push(' ');
                    pretty_serialize_helper(value, result, indent + 1);
                    if i != obj.fields.len() - 1 {
                        result.push(',');
                        result.push('\n');
                    } else {
                        result.push('\n');
                    }
                }
                for _ in 0..indent {
                    result.push(' ');
                }
                result.push('}');
            } else {
                result.push('{');
                result.push('}');
            }
        }
        Document::Array(arr) => {
            if !arr.items.is_empty() {
                result.push('[');
                result.push('\n');
                for (i, item) in arr.items.iter().enumerate() {
                    for _ in 0..indent + 1 {
                        result.push(' ');
                    }
                    pretty_serialize_helper(item, result, indent + 1);
                    if i != arr.items.len() - 1 {
                        result.push(',');
                        result.push('\n');
                    } else {
                        result.push('\n');
                    }
                }
                for _ in 0..indent {
                    result.push(' ');
                }
                result.push(']');
            } else {
                result.push('[');
                result.push(']');
            }
        }
        Document::String(s) => {
            result.push('\"');
            result.push_str(escape(s));
            result.push('\"');
        }
        Document::Number(n) => {
            match n {
                Number::Integer(i) => result.push_str(i.to_string().as_str()),
                Number::Decimal(d) => result.push_str(d.to_string().as_str()),
            }
        }
        Document::Bool(b) => {
            if *b {
                result.push('t');
                result.push('r');
                result.push('u');
                result.push('e');
            } else {
                result.push('f');
                result.push('a');
                result.push('l');
                result.push('s');
                result.push('e');
            }
        }
        Document::Null => result.push('n'),
        Document::Undefined => result.push('u'),
    }
}

use icu::plurals::{PluralRules, PluralCategory};
use icu::locale::Locale;

fn unread_message_text(count: usize, locale_str: &str) -> String {
    let locale = Locale::from_bytes(locale_str.as_bytes()).expect("Invalid locale");
    let rules = PluralRules::for_locale(locale, PluralCategory::Cardinal).expect("Failed to create plural rules");
    let category = rules.select(count);

    match category {
        PluralCategory::Zero => "You have zero unread messages".to_string(),
        PluralCategory::One => "You have one unread message".to_string(),
        PluralCategory::Two => "You have two unread messages".to_string(),
        PluralCategory::Few => "You have few unread messages".to_string(),
        PluralCategory::Many => "You have many unread messages".to_string(),
        PluralCategory::Other => format!("You have {} unread messages", count),
    }
}

