use bitcoincore_zmq::{subscribe_receiver, Message};
use bitcoin::Transaction;

fn collect_raw_txs(endpoints: &[&str], count: usize) -> bitcoincore_zmq::Result<Vec<Transaction>> {
    let mut receiver = subscribe_receiver(endpoints)?;
    let mut txs = Vec::with_capacity(count);

    for _ in 0..count {
        if let Ok(msg) = receiver.recv() {
            if let Ok(tx) = Message::deserialize(&msg.payload) {
                txs.push(tx);
            }
        } else {
            break;
        }
    }

    Ok(txs)
}

