fn persistent_dnd(ui: &mut egui::Ui, items: &mut Vec<Item>) {
    let mut dnd_items = items.iter_mut().map(|item| DragDropItem::new(item)).collect::<Vec<_>>();

    if let Some((new_items, _)) = dnd::list(ui, &mut dnd_items) {
        *items = new_items.into_iter().map(|item| item.item).collect();
    }

    // Save the current order to egui's memory
    egui::storage::Storage::get(ui.ctx().storage_mut(), "dnd_order")
        .unwrap_or(egui::Storage::default())
        .set("order", items.iter().map(|item| item.number).collect::<Vec<_>>());
}

impl egui::util::Storage for Vec<u32> {
    fn get(&self, key: &str) -> Option<Vec<u32>> {
        if key == "order" {
            Some(self.clone())
        } else {
            None
        }
    }

    fn set(&mut self, key: &str, value: Vec<u32>) {
        if key == "order" {
            *self = value;
        }
    }

    fn remove(&mut self, key: &str) {
        if key == "order" {
            self.clear();
        }
    }
}

fn proxy_from_env() -> Result<hyper_proxy2::ProxyConnector<hyper_util::client::legacy::connect::HttpConnector>, std::io::Error> {
    let proxy_url = env::var("PROXY_URL").expect("PROXY_URL environment variable not set");
    let proxy_user = env::var("PROXY_USER").ok();
    let proxy_pass = env::var("PROXY_PASS").ok();

    let uri: Uri = proxy_url.parse()?;
    let mut http_connector = HttpConnector::new();
    http_connector.set_connect_timeout(None);

    let mut proxy = Proxy::new();
    proxy.set_uri(uri);

    if let (Some(user), Some(pass)) = (proxy_user, proxy_pass) {
        let auth = Authorization::basic(user, pass);
        proxy.set_authorization(auth);
    }

    let connector = ProxyConnector::new(http_connector, Intercept::all(), proxy);
    Ok(connector)
}

