fn swap_bytes_in_mixed_buffer(buf: &mut [u8], start: usize, end: usize) {
    let mut i = start;
    while i < end {
        let size = match buf[i] {
            0x01 => 1,
            0x02 => 2,
            0x04 => 4,
            0x08 => 8,
            _ => panic!("Unknown integer size"),
        };
        match size {
            1 => {},
            2 => u16::swap_bytes(&mut buf[i..i + 2]),
            4 => u32::swap_bytes(&mut buf[i..i + 4]),
            8 => u64::swap_bytes(&mut buf[i..i + 8]),
            _ => panic!("Invalid size"),
        }
        i += size;
    }
}

use bevy_render::mesh::{Mesh, VertexAttributeValues, PrimitiveTopology};

fn create_simplified_mesh(original: &Mesh) -> Mesh {
    let mut simplified = Mesh::new(PrimitiveTopology::TriangleList);

    // Copy essential vertex attributes: position and normal
    for (attribute, values) in &original.attribute_iter() {
        match attribute.name() {
            "VERTEX_POSITION" => {
                simplified.attribute_mut(attribute.name(), VertexAttributeValues::new(values.values().to_vec()));
            }
            "VERTEX_NORMAL" => {
                simplified.attribute_mut(attribute.name(), VertexAttributeValues::new(values.values().to_vec()));
            }
            _ => {}
        }
    }

    simplified
}

fn flatten_nested_map<K1: Clone + Ord, K2: Clone + Ord, V>(nested_map: &BTreeMap<BTreeMap<K1, K2>, V>) -> impl Iterator<Item = (Vec<u8>, Vec<u8>, Vec<u8>)> {
    nested_map.iter()
        .flat_map(move |(inner_map, value)| {
            inner_map.iter()
                .map(move |(inner_key, inner_value)| {
                    let outer_key_bytes = to_bytes(inner_map);
                    let inner_key_bytes = to_bytes(inner_key);
                    let value_bytes = to_bytes(inner_value);
                    (outer_key_bytes, inner_key_bytes, value_bytes)
                })
        })
}

