use lambda_http::{Request, Response, Body, Error};
use tracing::{info, warn};

fn logged_handler<F, Fut>(handler: F, req: Request) -> Result<Response<Body>, Error>
where
    F: FnOnce(Request) -> Fut,
    Fut: std::future::Future<Output = Result<Response<Body>, Error>>,
{
    let start_time = std::time::Instant::now();
    info!("Received request: {:?}", req);

    let response = handler(req).await;

    let duration = start_time.elapsed();
    match response {
        Ok(res) => {
            info!("Handled request with status: {}", res.status());
            info!("Request duration: {:?}", duration);
            Ok(res)
        }
        Err(e) => {
            warn!("Request processing failed: {}", e);
            Err(e)
        }
    }
}

