fn create_tarball_from_current_dir_with_exclusions(temp_tarball_dir: &TempDir, exclusions: &[&str]) -> Result<PathBuf> {
    let current_dir = std::env::current_dir()?;
    let mut tarball_path = temp_tarball_dir.path().join("project.tar.gz");
    let file = std::fs::File::create(&tarball_path)?;
    let mut encoder = GzEncoder::new(file, Compression::best());
    let mut tar_builder = Builder::new(encoder);

    for entry in WalkDir::new(&current_dir).into_iter().filter_map(|e| e.ok()) {
        let path = entry.path();
        let relative_path = path.strip_prefix(&current_dir)?;
        let should_exclude = exclusions.iter().any(|&exclude| {
            relative_path.starts_with(exclude) || relative_path.ends_with(exclude)
        });
        if should_exclude {
            continue;
        }
        if relative_path.starts_with("out") {
            continue;
        }
        tar_builder.append_path_with_name(path, relative_path)?;
    }

    tar_builder.finish()?;
    Ok(tarball_path)
}

