fn format_latency_info(
    consensus_ord_latency: Option<Duration>,
    p2p_connection_status: &BTreeMap<PeerId, Option<Duration>>,
) -> Markup {
    let mut latency_alerts = vec![];

    // Handle consensus latency
    if let Some(latency) = consensus_ord_latency {
        let threshold = Duration::from_secs(10);
        let alert_class = if latency > threshold {
            "alert alert-danger"
        } else {
            "alert alert-warning"
        };
        latency_alerts.push(html! {
            div class=alert_class {
                span class="fas fa-exclamation-triangle" {}
                " Consensus order latency: " (latency.as_secs_f64()) "s"
            }
        });
    }

    // Handle peer connection status
    for (peer_id, latency) in p2p_connection_status {
        if let Some(latency) = latency {
            let threshold = Duration::from_secs(5);
            let alert_class = if latency > threshold {
                "alert alert-danger"
            } else {
                "alert alert-warning"
            };
            latency_alerts.push(html! {
                div class=alert_class {
                    span class="fas fa-exclamation-triangle" {}
                    " Peer " (peer_id) ": " (latency.as_secs_f64()) "s"
                }
            });
        }
    }

    html! {
        div class="alert-container" {
            @for alert in latency_alerts.iter() {
                (alert)
            }
        }
    }
}

fn insert_cache_asset(
    db: Arc<Mutex<Connection>>,
    put: CachePutRequest,
    response_body_key: Option<String>,
) -> Result<Option<String>, CacheError> {
    let db = db.lock().unwrap();
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos())
        .ok_or(CacheError::TimestampError)?;

    let mut stmt = db.prepare(
        "INSERT OR REPLACE INTO request_response_list (
            request_method, 
            request_url, 
            request_headers, 
            response_status, 
            response_headers, 
            response_body_key, 
            created_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(request_url) DO UPDATE SET
            request_method = excluded.request_method,
            request_headers = excluded.request_headers,
            response_status = excluded.response_status,
            response_headers = excluded.response_headers,
            response_body_key = excluded.response_body_key,
            created_at = excluded.created_at
        ",
    )?;

    let request_headers = serialize_headers(&put.request_headers);
    let response_headers = serialize_headers(&put.response_headers);

    stmt.execute((
        put.request_method,
        put.request_url,
        request_headers,
        put.response_status,
        response_headers,
        response_body_key,
        now,
    ))?;

    Ok(response_body_key)
}

