use rsa::RsaPublicKey;
use jsonwebtoken::{self, DecodingKey, Validation};
use snowflake_jwt::JwtError;
use serde_json::Value;

fn verify_jwt(token: &str, public_key_pem: &str) -> Result<bool, JwtError> {
    let public_key = RsaPublicKey::from_pem(public_key_pem)
        .map_err(|e| JwtError::InvalidPublicKey(format!("Failed to parse public key: {}", e)))?;

    let validation = Validation::new(jwt::Algorithm::RS256);
    validation.set_leeway(jwt::Leeway::default());
    validation.set_required_claims(vec!["iss", "sub", "aud", "exp"]);

    let mut header = jsonwebtoken::Header::new();
    header.alg = jwt::Algorithm::RS256;

    let decoding_key = DecodingKey::from_rsa_pem(public_key_pem)
        .map_err(|e| JwtError::InvalidPublicKey(format!("Failed to create decoding key: {}", e)))?;

    let result = jsonwebtoken::decode::<Value>(token, &decoding_key, &validation)
        .map(|_| true)
        .map_err(|e| JwtError::InvalidToken(format!("Token validation failed: {}", e)))?;

    Ok(result.claims.is_valid())
}

fn optimized_lookup_delayed_local_receipt(
    client: &actix::Addr<near_client::ViewClientActor>,
    runtime_config: &near_parameters::RuntimeConfig,
    block: &near_primitives::views::BlockView,
    receipt_id: near_primitives::hash::CryptoHash,
    shard_tracker: &near_epoch_manager::shard_tracker::ShardTracker,
) -> Result<near_primitives::views::ReceiptView, near_indexer::streamer::errors::FailedToFetchData> {
    // Check the in-memory cache first
    if let Some(receipt) = DELAYED_LOCAL_RECEIPTS_CACHE.read().get(&receipt_id) {
        return Ok(receipt.clone());
    }

    // Check the current block
    if let Some(receipt) = find_local_receipt_by_id_in_block(block, &receipt_id) {
        DELAYED_LOCAL_RECEIPTS_CACHE.write().insert(receipt_id, receipt.clone());
        return Ok(receipt);
    }

    // If not found, walk back up to 1000 blocks
    let max_blocks_to_search = 1000;
    let mut blocks_searched = 0;
    let mut current_block = block;
    let mut receipt = None;

    while blocks_searched < max_blocks_to_search {
        // Increment the metric for blocks inspected
        metrics::INVESTIGATED_BLOCKS.inc();

        // Check if the current block is the one we need
        if let Some(receipt_in_block) = find_local_receipt_by_id_in_block(current_block, &receipt_id) {
            receipt = Some(receipt_in_block);
            break;
        }

        // Fetch the previous block
        if let Ok(prev_block) = fetch_block(client, current_block.prev_block_hash(), runtime_config, shard_tracker) {
            current_block = &prev_block;
            blocks_searched += 1;
        } else {
            break;
        }
    }

    if let Some(receipt) = receipt {
        DELAYED_LOCAL_RECEIPTS_CACHE.write().insert(receipt_id, receipt.clone());
        Ok(receipt)
    } else {
        Err(FailedToFetchData)
    }
}

fn render_table(rows: &[Vec<&str>], column_widths: &[usize]) -> String {
    if rows.is_empty() || column_widths.is_empty() {
        return String::new();
    }

    let mut result = String::new();
    let num_columns = column_widths.len();

    // Determine the maximum width for each column based on content and specified widths
    let mut adjusted_widths = column_widths.to_vec();
    for col in 0..num_columns {
        let max_content_width = rows.iter()
            .filter_map(|row| row.get(col))
            .map(|s| s.len())
            .max()
            .unwrap_or(0);
        adjusted_widths[col] = std::cmp::max(adjusted_widths[col], max_content_width);
    }

    // Build the table row by row
    for (row_idx, row) in rows.iter().enumerate() {
        let mut row_str = String::new();
        for (col_idx, cell) in row.iter().enumerate() {
            let width = adjusted_widths[col_idx];
            let cell_str = if cell.len() > width {
                &cell[..width]
            } else {
                cell
            };
            row_str.push_str(cell_str);
            if col_idx < num_columns - 1 {
                row_str.push(' ');
            }
        }
        if row_idx == 0 {
            result.push_str(&format!("|{}|\n", row_str));
        } else {
            result.push_str(&format!("|{}|\n", row_str));
        }
    }

    result
}

