fn total_balance<AccountId, Balance, KeyType>(
    mapping: &Mapping<AccountId, Balance, KeyType>,
    start: u32,
    end: u32,
) -> Balance
where
    AccountId: scale::Encode + Clone,
    Balance: Default + core::ops::AddAssign + Copy,
    KeyType: StorageKey,
{
    let mut total = Balance::default();
