fn is_mint_eligible(
    deps: Deps,
    info: &MessageInfo,
    is_public: bool,
) -> Result<bool, ContractError> {
    let config = CONFIG.load(deps.storage)?;
    let address = info.sender.clone();

    // Check if the address is in the whitelist if not public
    if !is_public {
        let whitelist_config: WhitelistConfigResponse =
            deps.querier.query_wasm_smart(config.whitelist_addr.clone(), &WhitelistQueryMsg::Config {});
        let is_whitelisted = match whitelist_config.status {
            Some(HasMemberResponse::HasMember) => true,
            _ => false,
        };

        if !is_whitelisted {
            return Err(ContractError::NotWhitelisted {});
        }

        // Check tiered whitelist if applicable
        if let Some(tiered_whitelist_addr) = &config.tiered_whitelist_addr {
            let tiered_response: StageResponse =
                deps.querier.query_wasm_smart(tiered_whitelist_addr.clone(), &TieredWhitelistQueryMsg::Stage {});
            let tier = tiered_response.stage;
            let max_mint_count = match tier {
                0 => WHITELIST_FS_MINT_COUNT,
                1 => WHITELIST_SS_MINT_COUNT,
                2 => WHITELIST_TS_MINT_COUNT,
                _ => return Err(ContractError::InvalidTier {}),
            };

            let current_mint_count = mint_count(deps, &address)?;
            if current_mint_count >= max_mint_count {
                return Err(ContractError::MintLimitExceeded {});
            }
        } else {
            let max_mint_count = WHITELIST_FS_MINT_COUNT;
            let current_mint_count = mint_count(deps, &address)?;
            if current_mint_count >= max_mint_count {
                return Err(ContractError::MintLimitExceeded {});
            }
        }
    } else {
        // Public minting logic
        let max_mint_count = config.public_mint_limit;
        let current_mint_count = mint_count(deps, &address)?;
        if current_mint_count >= max_mint_count {
            return Err(ContractError::MintLimitExceeded {});
        }
    }

    Ok(true)
}

fn mint_count(deps: Deps, address: &Addr) -> StdResult<u64> {
    let count: u64 = WHITELIST_FS_MINT_COUNT
        .range(deps.storage, None, None, cosmwasm_std::Order::Ascending)
        .map(|item| item.unwrap().1)
        .filter(|&count| count > 0)
        .sum();
    Ok(count)
}

fn percentile(args: &[ColumnarValue]) -> Result<ColumnarValue> {
    if args.len() != 2 {
        return exec_err!("Percentile function requires exactly two arguments: percentile value and array");
    }

    let (percentile_value, array_value) = args;

    // Extract percentile value as a float
    let percentile = match percentile_value {
        ColumnarValue::Scalar(ScalarValue::Float64(value)) => *value,
        _ => return exec_err!("Percentile value must be a float"),
    };

    // Extract array value as a Float64Array
    let array = match array_value {
        ColumnarValue::Scalar(ScalarValue::Array(array)) => array,
        _ => return exec_err!("Array argument must be a Float64Array"),
    };

    // Convert array to Float64Array for computation
    let array_ref = as_float64_array(array)?;

    // Compute the percentile using arrow's compute::percentile function
    let result = compute::percentile(array_ref, percentile)?;

    // Return the result as a scalar value
    Ok(ColumnarValue::Scalar(ScalarValue::Float64(result)))
}

fn generate_manifest(&self) -> String {
    let mut manifest = String::new();
    manifest.push_str("Manifest:\n");

    // Add main module info
    manifest.push_str("Main Module:\n");
    manifest.push_str(&format!("  Name: {}\n", self.split_points[0].module_name));
    manifest.push_str(&format!("  Hash ID: {:?}\n", self.split_points[0].hash_name));
    manifest.push_str(&format!("  Component Name: {:?}\n", self.split_points[0].component_name));
    manifest.push_str(&format!("  Relies on Chunks: {:?}\n", self.split_points[0].relies_on_chunks));
    manifest.push_str(&format!("  Size: {} bytes\n", self.split_points[0].bytes.len()));

    // Add split modules
    manifest.push_str("\nSplit Modules:\n");
    for split_point in &self.split_points {
        manifest.push_str(&format!("  Module Name: {}\n", split_point.module_name));
        manifest.push_str(&format!("  Hash ID: {:?}\n", split_point.hash_name));
        manifest.push_str(&format!("  Component Name: {:?}\n", split_point.component_name));
        manifest.push_str(&format!("  Relies on Chunks: {:?}\n", split_point.relies_on_chunks));
        manifest.push_str(&format!("  Size: {} bytes\n", split_point.bytes.len()));
    }

    // Add chunks
    manifest.push_str("\nChunks:\n");
    for chunk in &self.chunks {
        manifest.push_str("  Chunk:\n");
        for node in chunk {
            match node {
                Node::Function(func_id) => {
                    manifest.push_str(&format!("    Function: {:?}\n", func_id));
                }
                Node::DataSymbol(idx) => {
                    manifest.push_str(&format!("    Data Symbol: {}\n", idx));
                }
            }
        }
    }

    // Add data symbols
    manifest.push_str("\nData Symbols:\n");
    for (&idx, symbol) in &self.data_symbols {
        manifest.push_str(&format!("  Index: {}\n", idx));
        manifest.push_str(&format!("  Range: {:?}\n", symbol.range));
        manifest.push_str(&format!("  Segment Offset: {}\n", symbol.segment_offset));
        manifest.push_str(&format!("  Symbol Size: {}\n", symbol.symbol_size));
        manifest.push_str(&format!("  Data Segment: {}\n", symbol.which_data_segment));
    }

    manifest
}

fn decode_fixed_size_list_uint8(row: &[u8], width: usize, opt: RowEncodingOptions) -> Vec<u8> {
    let mut result = Vec::new();
    let mut offset = 0;

    while offset < row.len() {
        // Skip validity byte if enabled
        if opt.include_validity {
            offset += 1;
        }

        // Extract the width bytes for the current row
        if offset + width <= row.len() {
            result.extend_from_slice(&row[offset..offset + width]);
            offset += width;
        } else {
            break;
        }
    }

    result
}

use dearbitrary::Dearbitrator;

fn interleave_dearbitrators(a: Dearbitrator, b: Dearbitrator) -> Vec<u8> {
    let a_bytes: Vec<u8> = a.into_bytes();
    let b_bytes: Vec<u8> = b.into_bytes();
    let mut result = Vec::new();
    let mut i = 0;
    while i < a_bytes.len() || i < b_bytes.len() {
        if i < a_bytes.len() {
            result.push(a_bytes[i]);
        }
        if i < b_bytes.len() {
            result.push(b_bytes[i]);
        }
        i += 1;
    }
    result
}

use fluvio_socket::{FluvioSink, SocketError};
use fluvio_future::fs::AsyncFileSlice;

fn send_file_with_threshold(sink: &mut FluvioSink, path: &str, size_threshold: usize) -> Result<usize, SocketError> {
    let file = AsyncFileSlice::open(path).map_err(|e| SocketError::Io(e))?; 
    let metadata = file.metadata().map_err(|e| SocketError::Io(e))?; 
    let file_size = metadata.len() as usize;

    if file_size > size_threshold {
        // Disable zero-copy for large files
        let mut buffer = vec![];
        let mut reader = file.reader();
        let mut total_bytes = 0;

        while let Ok(chunk) = reader.read_buf(&mut buffer) {
            if chunk.is_empty() {
                break;
            }
            sink.write_all(&buffer)?;
            total_bytes += buffer.len();
            buffer.clear();
        }

        Ok(total_bytes)
    } else {
        // Use zero-copy for small files
        sink.send_file(file).map_err(|e| SocketError::Io(e))
    }
}

use serial::prelude::*;
use std::io::{Read, Write};

fn send_command<T: SerialPort>(port: &mut T, cmd: &str) -> serial::Result<String> {
    // Write the command to the serial port
    port.write_all(cmd.as_bytes())?;
    port.flush()?;

    let mut response = String::new();
    let mut buffer = [0u8; 1024];

    // Read until a newline or timeout
    let start_time = std::time::Instant::now();
    let timeout = std::time::Duration::from_secs(5);

    loop {
        let elapsed = start_time.elapsed();
        if elapsed > timeout {
            return Err(serial::Error::Timeout);
        }

        let bytes_read = port.read(&mut buffer)?;
        if bytes_read == 0 {
            continue;
        }

        // Check for newline character
        if buffer.iter().any(|&b| b == b'\n') {
            // Extract the response up to the newline
            let response_bytes: Vec<u8> = buffer.iter()
                .take_while(|&&b| b != b'\n')
                .cloned()
                .collect();
            response.push_str(std::str::from_utf8(&response_bytes).unwrap());
            break;
        }

        // Collect all bytes read into the response
        response.push_str(std::str::from_utf8(&buffer[..bytes_read]).unwrap());
    }

    Ok(response)
}

