use crate::Root;
use crate::load_env_file;

fn validate_host_function_signature(
    function_name: &str,
    expected_args: &[(&str, &str)],
    expected_return: &str,
) -> Result<(), String> {
    let env = load_env_file()?;
    let function_def = env
        .host_functions
        .iter()
        .find(|def| def.name == function_name)
        .ok_or(format!("Function '{}' not found in env.json", function_name))?;

    if function_def.return_type != expected_return {
        return Err(format!(
            "Return type mismatch: expected '{}', found '{}'",
            expected_return, function_def.return_type
        ));
    }

    if expected_args.len() != function_def.arguments.len() {
        return Err(format!(
            "Argument count mismatch: expected {}, found {}",
            expected_args.len(),
            function_def.arguments.len()
        ));
    }

    for (i, (expected_arg_name, expected_arg_type)) in expected_args.iter().enumerate() {
        let arg = &function_def.arguments[i];
        if arg.name != *expected_arg_name {
            return Err(format!(
                "Argument name mismatch at index {}: expected '{}', found '{}'",
                i, expected_arg_name, arg.name
            ));
        }
        if arg.type_ != *expected_arg_type {
            return Err(format!(
                "Argument type mismatch at index {}: expected '{}', found '{}'",
                i, expected_arg_type, arg.type_
            ));
        }
    }

    Ok(())
}

