use gluesql_core::{error::Error, prelude::Value, data::{DataRow, Key}};
use mongodb::bson::{doc, Document};
use crate::{MongoStorage, error::MongoStorageError, row::{IntoRow, value::IntoBson}, utils::get_primary_key};
use futures::StreamExt;

fn fetch_rows_by_column(
    storage: &MongoStorage,
    table_name: &str,
    column_name: &str,
    value: Value,
) -> Result<Vec<(Key, DataRow)>, Error> {
    // Convert the Value to a BSON document for the filter
    let filter_doc = match value.into_bson() {
        Ok(doc) => doc,
        Err(_) => return Err(Error::InvalidValue),
    };

    // Create a MongoDB filter document
    let filter = doc! { column_name: filter_doc };

    // Fetch documents from the collection
    let collection = storage.get_collection(table_name).map_err(|e| Error::StorageError(Box::new(e)))?;
    let mut cursor = collection.find(Some(filter), None).map_err(|e| Error::StorageError(Box::new(e)))?;

    let mut rows = Vec::new();

    while let Some(result) = cursor.next().await {
        let document = result.map_err(|e| Error::StorageError(Box::new(e)))?;
        let primary_key = get_primary_key(&document).ok_or(Error::MissingPrimaryKey)?;
        let row = DataRow::from_document(document).map_err(|e| Error::RowConversionError(e.to_string()))?;
        rows.push((primary_key, row));
    }

    Ok(rows)
}

