use vortex_error::{VortexResult, vortex_bail};
use vortex_dtype::NativePType;
use vortex_array::arrays::PrimitiveArray;
use crate::compress::runend_decode_primitive;
use crate::array::RunEndArray;

fn runend_range<T: NativePType>(array: &RunEndArray, start: usize, end: usize) -> VortexResult<PrimitiveArray<T>> {
    // Ensure start and end are within bounds
    if start >= array.len() || end > array.len() {
        vortex_bail!("Start or end index out of bounds");
    }

    // Ensure start is not greater than end
    if start > end {
        vortex_bail!("Start index cannot be greater than end index");
    }

    // Extract the run-end encoded data and the lengths array
    let data = array.data();
    let lengths = array.lengths();

    // Calculate the number of elements to extract
    let num_elements = end - start;

    // Allocate a buffer for the result
    let mut result = Vec::with_capacity(num_elements);

    // Iterate over the run-end encoded data to extract the sub-range
    let mut current_index = 0;
    let mut current_value = 0;
    let mut value_index = 0;

    while current_index < lengths.len() && result.len() < num_elements {
        let run_length = lengths[current_index];
        let run_value = data[current_value];

        // Determine how many elements of this run can be included in the sub-range
        let available = run_length;
        let take = std::cmp::min(available, num_elements - result.len());

        // Add the elements to the result
        for _ in 0..take {
            result.push(run_value);
        }

        // Update the indices
        current_value += 1;
        current_index += 1;
    }

    // Create the result array
    Ok(PrimitiveArray::new(T::default(), result))
}

