use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use dav1d::{PictureAllocator, PictureAllocation, PictureParameters, Error, PICTURE_ALIGNMENT};

struct CustomAllocator {
    allocations: Mutex<HashMap<usize, usize>>,
    next_id: Mutex<usize>,
}

impl CustomAllocator {
    fn new() -> Arc<Self> {
        Arc::new(CustomAllocator {
            allocations: Mutex::new(HashMap::new()),
            next_id: Mutex::new(0),
        })
    }

    fn allocate(&self, params: &PictureParameters) -> Result<PictureAllocation, Error> {
        let id = {
            let mut next_id = self.next_id.lock().unwrap();
            let id = *next_id;
            *next_id += 1;
            id
        };

        let size = params.width as usize * params.height as usize * params.pixel_size as usize;
        let aligned_size = (size + PICTURE_ALIGNMENT - 1) & !(PICTURE_ALIGNMENT - 1);

        let mut allocations = self.allocations.lock().unwrap();
        allocations.insert(id, aligned_size);

        Ok(PictureAllocation {
            id,
            size: aligned_size,
            alignment: PICTURE_ALIGNMENT,
        })
    }

    fn free(&self, id: usize) -> Result<(), Error> {
        let mut allocations = self.allocations.lock().unwrap();
        allocations.remove(&id);
        Ok(())
    }

    fn active_count(&self) -> usize {
        let allocations = self.allocations.lock().unwrap();
        allocations.len()
    }
}

impl PictureAllocator for CustomAllocator {
    fn allocate_picture(&self, params: &PictureParameters) -> Result<PictureAllocation, Error> {
        self.allocate(params)
    }

    fn free_picture(&self, allocation: &PictureAllocation) -> Result<(), Error> {
        self.free(allocation.id)
    }

    fn active_picture_count(&self) -> usize {
        self.active_count()
    }
}

fn new() -> Arc<CustomAllocator> {
    CustomAllocator::new()
}

use async_stream::stream;
use async_stream::next;

fn interleave<S1, S2>(s1: S1, s2: S2) -> impl futures_core::stream::Stream<Item = u32>
where
    S1: futures_core::stream::Stream<Item = u32> + Unpin,
    S2: futures_core::stream::Stream<Item = u32> + Unpin,
{
    stream! {
        let (mut s1, mut s2) = (s1, s2);
        loop {
            match next!(&mut s1) {
                Some(val) => yield val,
                None => break,
            }
            match next!(&mut s2) {
                Some(val) => yield val,
                None => break,
            }
        }
    }
}

use aws_smithy_json::deserialize::{json_token_iter, expect_document, Error};
use aws_smithy_json::serialize::JsonValueWriter;
use aws_smithy_types::Document;
use std::collections::HashMap;

fn merge_objects(a: &str, b: &str) -> Result<String, Error> {
    let a_doc = expect_document(json_token_iter(a))?;
    let b_doc = expect_document(json_token_iter(b))?;

    let mut merged = HashMap::new();
    merge_json(&a_doc, &mut merged);
    merge_json(&b_doc, &mut merged);

    let mut writer = JsonValueWriter::new();
    writer.write_document(merged)?;
    Ok(writer.into_string())
}

fn merge_json(doc: &Document, map: &mut HashMap<String, Document>) {
    match doc {
        Document::Object(obj) => {
            for (key, value) in obj {
                merge_json(value, map);
                map.insert(key.clone(), doc.clone());
            }
        }
        Document::Array(arr) => {
            for item in arr {
                merge_json(item, map);
            }
        }
        _ => {}
    }
}

fn markdown_to_content_with_autolinks(text: &str, base_url: &url::Url) -> Content {
    let options = Options::empty()
        .extend([Options::ENABLE_AUTOLINKS, Options::ENABLE_FOOTNOTES, Options::ENABLE_STRIKETHROUGH]);
    let parser = Parser::new_ext(text, options);

    let mut content = Content::new();
    let mut current_element = ContentElement::new();
    let mut in_link = false;
    let mut link_text = CowStr::default();
    let mut link_url = CowStr::default();
    let mut link_title = CowStr::default();
    let mut link_type = LinkType::Email;

    for event in parser {
        match event {
            Event::Start(Tag::Link(link_type, link_text, link_url)) => {
                in_link = true;
                self.link_type = link_type;
                self.link_text = link_text;
                self.link_url = link_url;
            },
            Event::End(Tag::Link(link_type, link_text, link_url)) => {
                in_link = false;
                let resolved_url = if let Some(url) = link_url {
                    if let Ok(url) = url.parse() {
                        if let Some(base) = base_url {
                            if !url.scheme().is_empty() && !url.host().is_empty() {
                                url
                            } else {
                                base.join(url).unwrap_or(url)
                            }
                        } else {
                            url
                        }
                    } else {
                        link_url
                    }
                } else {
                    link_url
                };
                let autolink = ContentElement::Autolink {
                    url: resolved_url.to_string(),
                    text: link_text.to_string(),
                };
                current_element = ContentElement::new();
                current_element = autolink;
                content.push(current_element);
            },
            Event::Text(text) => {
                if in_link {
                    link_text = text;
                } else {
                    current_element = ContentElement::RawHtml(text.to_string());
                    content.push(current_element);
                }
            },
            _ => {
                if in_link {
                    // Handle other events while inside a link (e.g., emphasis, code, etc.)
                } else {
                    // Handle other events like headers, lists, etc.
                }
            },
        }
    }

    content
}

use ansi_term::{Colour, ANSIString};

fn rainbow_gradient(text: &str) -> Vec<ansi_term::ANSIString<'static>> {
    let mut result = Vec::new();
    let length = text.len();

    for i in 0..length {
        let hue = (i as f64 / length as f64) * 360.0;
        let colour = Colour::RGB((hue as u8) % 255, (hue * 1.5) as u8 % 255, (hue * 2.0) as u8 % 255);
        let styled_char = colour.paint(text.chars().nth(i).unwrap());
        result.push(styled_char);
    }

    result
}

