fn list_tables(conn: &mut IndexerConnection, namespace: &str, identifier: &str) -> sqlx::Result<Vec<String>> {
    let tables = query!(
        r#"
        SELECT table_name
        FROM information_schema.tables
        WHERE table_schema = $1
          AND table_name LIKE $2
        ORDER BY table_name
        "#,
        namespace,
        format!("{}%", identifier)
    )
    .fetch_all(conn)
    .map(|rows| rows.into_iter().map(|row| row.get("table_name")).collect())
