use uaparser::{UserAgentParser, UserAgent};

fn get_user_agent_version(user_agent: &str) -> String {
    let parser = UserAgentParser::new();
    let ua = parser.parse(user_agent);

    let mut version = String::new();
    if let Some(browser) = ua.browser() {
        if let Some(v) = browser.version() {
            version = v.to_string();
        }
    } else if let Some(os) = ua.os() {
        if let Some(v) = os.version() {
            version = v.to_string();
        }
    } else if let Some(device) = ua.device() {
        if let Some(v) = device.version() {
            version = v.to_string();
        }
    }

    if version.is_empty() {
        "Unknown".to_string()
    } else {
        version
    }
}

