fn lock_with_pw_and_qa(
    bundle: &UnlockedSeedBundle,
    passphrase: SharedLockedArray,
    qa: (String, String, String),
    answers: (
        sodoken::LockedArray,
        sodoken::LockedArray,
        sodoken::LockedArray,
    ),
) -> Result<Box<[u8]>, OneErr> {
    let mut seed_cipher_builder = bundle.lock_with_passphrase(passphrase)?;
    let (question, _, _) = qa;
    let (answer1, answer2, answer3) = answers;

    seed_cipher_builder = seed_cipher_builder.lock_with_qa(question, answer1)?;
    seed_cipher_builder = seed_cipher_builder.lock_with_qa(question, answer2)?;
    seed_cipher_builder = seed_cipher_builder.lock_with_qa(question, answer3)?;

    seed_cipher_builder.build()
}

