fn fetch_gateway_statuses(
    api: &dyn LightningFederationApi,
    conn: &dyn GatewayConnection,
    federation_id: &FederationId,
) -> Result<BTreeMap<SafeUrl, bool>> {
    let gateways = api.get_vetted_gateways(federation_id)?;
    let mut statuses = BTreeMap::new();

    for gateway in gateways {
        if let Ok(url) = SafeUrl::parse(&gateway.url) {
            match conn.test_connection(&url) {
                Ok(_) => {
                    statuses.insert(url, true);
                }
                Err(_) => {
                    statuses.insert(url, false);
                }
            }
        }
    }

    Ok(statuses)
}

fn parse_nested_route<'a>(route: &'a str, active_nests: &'a [NestId], all_nests: &'a [Nest]) -> syn::Result<(Vec<RouteSegment>, Option<QuerySegment>, Option<HashFragment>)> {
    let mut segments = Vec::new();
    let mut query = None;
    let mut hash = None;

    let parts: Vec<&str> = route.split('?').collect();
    let path_part = parts[0];
    let rest = parts.get(1).copied().unwrap_or("");

    let hash_parts: Vec<&str> = rest.split('#').collect();
    let path_part = path_part;
    let query_part = hash_parts.get(0).copied().unwrap_or("");
    let hash_part = hash_parts.get(1).copied().unwrap_or("");

    if !query_part.is_empty() {
        query = Some(QuerySegment::parse(query_part)?);
    }

    if !hash_part.is_empty() {
        hash = Some(HashFragment::parse(hash_part)?);
    }

    let mut current_nest_id = None;
    let mut current_nest = None;

    for part in path_part.split('/') {
        if part.is_empty() {
            continue;
        }

        if let Some(nest_id) = active_nests.iter().find(|&&id| id == current_nest_id) {
            if let Some(nest) = all_nests.iter().find(|n| n.id == nest_id) {
                if let Some(segment) = nest.parse_segment(part) {
                    segments.push(segment);
                }
            }
        } else {
            let segment = RouteSegment::parse(part)?;
            segments.push(segment);
        }
    }

    Ok((segments, query, hash))
}

