use tokio_schedule::{every, Job};
use std::future::Future;
use std::sync::Arc;
use tokio::time::sleep;
use std::time::Duration;

fn schedule_with_retry<F, Fut, E>(interval_secs: u32, max_retries: u32, retry_delay_secs: u64, task: F) -> impl Future<Output = ()>
where
    F: Fn() -> Fut + Send + Sync + 'static,
    Fut: Future<Output = Result<(), E>> + Send + 'static,
    E: std::fmt::Debug,
{
    let interval = Duration::from_secs(interval_secs as u64);
    let retry_delay = Duration::from_secs(retry_delay_secs);
    let max_retries = max_retries;

    let job = every(interval).for_each(move |_| {
        let task = Arc::new(task);
        let max_retries = max_retries;
        let retry_delay = retry_delay;

        Box::pin(async move {
            let mut attempts = 0;
            loop {
                attempts += 1;
                let result = (task)().await;
                match result {
                    Ok(_) => break,
                    Err(e) => {
                        if attempts < max_retries {
                            tracing::warn!("Task failed with error: {:?}", e);
                            sleep(retry_delay).await;
                        } else {
                            tracing::error!("Task failed after {} retries: {:?}", attempts, e);
                        }
                    }
                }
            }
        })
    });

    job
}

use serial_test::code_lock::{global_locks, check_new_key};

fn parallel_counts(keys: &[&str]) -> Vec<(String, u32)> {
    let mut result = Vec::new();
    for &key in keys {
        let key_str = key.to_string();
        if check_new_key(&key_str) {
            if let Some(count) = global_locks.get(&key_str) {
                result.push((key_str, *count));
            } else {
                result.push((key_str, 0));
            }
        } else {
            result.push((key_str, 0));
        }
    }
    result
}

