fn calculate_federation_health(api: &impl IGlobalFederationApi) -> u8 {
    let status: StatusResponse = api.status().await.unwrap();
    let online_peers = status.peers.iter().filter(|p| p.status == "online").count() as u32;
    let offline_peers = status.peers.iter().filter(|p| p.status == "offline").count() as u32;
    let flagged_peers = status.peers.iter().filter(|p| p.status == "flagged").count() as u32;
    let total_peers = online_peers + offline_peers + flagged_peers;

    if total_peers == 0 {
        return 0;
    }

    let online_ratio = (online_peers * 100) / total_peers;
    let flagged_ratio = (flagged_peers * 100) / total_peers;

    let health = online_ratio.saturating_sub(flagged_ratio.saturating_div(2));
    health.min(100).max(0)
}

fn send_sysex(endpoint: MIDIEndpointRef, data: &[u8]) -> Result<(), OSStatus> {
    let mut request = unsafe { mem::zeroed() };
    request.header.size = mem::size_of::<MIDISysexSendRequest>() as u32;
    request.header.destination = endpoint;
    request.header.data = data.as_ptr() as *mut Byte;
    request.header.length = data.len() as u32;

    unsafe {
        let status = MIDISendSysex(&mut request);
        if status == 0 {
            Ok(())
        } else {
            Err(status)
        }
    }
}

