use std::path::PathBuf;
use anyhow::Result;
use docker_generate::DockerFile;
use tempfile::NamedTempFile;
use crate::config::DockerOptions;

fn generate_dockerfile(docker_opts: &DockerOptions) -> Result<PathBuf> {
    let mut dockerfile = DockerFile::new();

    // Base image
    dockerfile.add_line("FROM risczero/risc0:latest");

    // Set environment variables
    if let Some(env_vars) = &docker_opts.env_vars {
        for (key, value) in env_vars {
            dockerfile.add_line(&format!("ENV {}={}", key, value));
        }
    }

    // Add any additional commands from DockerOptions
    if let Some(additional_commands) = &docker_opts.additional_commands {
        for cmd in additional_commands {
            dockerfile.add_line(cmd);
        }
    }

    // Create a temporary file to store the Dockerfile
    let mut temp_file = NamedTempFile::new()?;
    dockerfile.write_to(&mut temp_file)?;

    Ok(temp_file.path().to_path_buf())
}

fn compress_payload(payload: &[u8], config: &DeflateConfig) -> Result<BytesMut, DeflateExtensionError> {
    let mut encoder = DeflateEncoder::new(payload, config);
    let mut compressed = BytesMut::with_capacity(payload.len() * 2);

    let mut flush = FlushCompress::Finish;
    let mut buffer = [0u8; 1024];
    loop {
        let bytes_read = encoder.read(&mut buffer[..], &mut flush)?;
        if bytes_read == 0 {
            break;
        }
        compressed.extend_from_slice(&buffer[..bytes_read]);
    }

    Ok(compressed)
}

use codegen::{Struct, Trait, Impl};

fn generate_container_impl() -> (Struct, Trait, Impl) {
    let container_struct = Struct::new("Container")
        .field("value", "u32");

    let container_trait = Trait::new("ContainerTrait")
        .associated_type("Item", "u32");

    let container_impl = Impl::new("Container")
        .trait_ref("ContainerTrait")
        .method("get_item", "u32", |_, _| {
            r#"
                Self::Item
            "#
        });

    (container_struct, container_trait, container_impl)
}

use std::path::Path;
use std::io;
use self_replace;

fn move_and_self_delete(target_dir: &Path) -> Result<(), io::Error> {
    // Ensure the target directory exists
    if !target_dir.exists() {
        return Err(io::Error::new(io::ErrorKind::NotFound, format!("Target directory not found: {}", target_dir.display())));
    }

    // Create the target path by joining the directory with the current executable's file name
    let target_path = target_dir.join(Path::new(file!()).file_name().unwrap());

    // Move the executable to the target directory
    if std::fs::rename(Path::new(file!()), &target_path).is_err() {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "Failed to move executable"));
    }

    // Schedule the deletion of the moved executable
    self_replace::self_delete_at(&target_path)
}

