fn spawn_with_env_and_cwd(
    program: &str,
    env: &[(&str, &str)],
    cwd: &str,
) -> Result<Box<dyn portable_pty::Child + Send>> {
    let pty_system: Box<dyn PtySystem> = Box::new(NativePtySystem::new()?);
    let mut command = CommandBuilder::new(program);

    // Set the working directory
    command.cwd(cwd);

    // Set environment variables
    for (key, value) in env {
        command.env(key, value);
    }

    // Spawn the command in a PTY
    let (mut child, mut pty) = pty_system.spawn(command)?;

    // Set initial PTY size (e.g., 24 rows, 80 columns)
    pty.set_size(PtySize::new(24, 80))?;

    Ok(Box::new(child))
}

