#[derive(RustEmbed)]
#[folder = "i18n/"]
struct Localizations;

fn required_arguments(
    loader: &FluentLanguageLoader,
    message_id: &str,
) -> Vec<String> {
    let bundle = loader
        .bundle_for_language(loader.fallback_language().clone())
        .unwrap();

    if let Some(resource) = bundle.resource() {
        if let Some(message) = resource.get(message_id) {
            if let Some(pattern) = message.value() {
                collect_argument_names(pattern)
            } else {
                vec![]
            }
        } else {
            vec![]
        }
    } else {
        vec![]
    }
}

fn collect_argument_names(pattern: &Pattern) -> Vec<String> {
    let mut args = Vec::new();
    for element in &pattern.elements {
        if let PatternElement::Expression(Expression::InlineExpression(InlineExpression {
            expression: Expression::CallArguments(CallArguments { arguments, .. }),
            ..
        })) = element
        {
            for arg in arguments {
                if let Expression::Identifier(id) = &arg.value {
                    args.push(id.to_string());
                }
            }
        }
    }
    args
}

fn aggregate_bitcoin_status(
    monitors: &[&ServerBitcoinRpcMonitor],
) -> Result<BitcoinStatusReport, String> {
    if monitors.is_empty() {
        return Err("No monitors provided".to_string());
    }

    let mut network = None;
    let mut block_count = 0;
    let mut fee_rate = Feerate::zero();
    let mut sync_percentage = 0.0;

    for &monitor in monitors {
        let status = match monitor.status() {
            Ok(status) => status,
            Err(e) => {
                return Err(format!("Error getting status from monitor: {}", e));
            }
        };

        // Use the first monitor's network as the representative
        if network.is_none() {
            network = Some(status.network);
        } else if network.unwrap() != status.network {
            return Err("Monitors report different networks".to_string());
        }

        block_count = status.block_count;
        fee_rate = status.fee_rate;
        sync_percentage = status.sync_percentage;
    }

    Ok(BitcoinStatusReport {
        network: network.unwrap(),
        block_count,
        fee_rate,
        sync_percentage,
    })
}

