type PegInDescriptor = Descriptor<CompressedPublicKey>;

fn create_peg_in_descriptor(
    pubkeys: BTreeMap<PeerId, CompressedPublicKey>,
    threshold: usize,
) -> Result<PegInDescriptor, anyhow::Error> {
    if threshold > pubkeys.len() {
        return Err(anyhow!("Threshold cannot exceed the number of public keys"));
    }

    let mut sorted_pubkeys: Vec<CompressedPublicKey> = pubkeys.values().cloned().collect();
    sorted_pubkeys.sort();

    let mut multisig_script = Wsh::multi(sorted_pubkeys, threshold);
    let descriptor = Descriptor::new(Wsh::from_script(multisig_script));
    Ok(descriptor)
}

