fn entries_to_kmsg_with_seq(entries: &[Entry]) -> Vec<String> {
    let mut result = Vec::new();
    let mut last_seq = 0;

    for entry in entries {
        let seq = entry.sequence_num.unwrap_or(last_seq + 1);
        last_seq = seq;

        let mut s = String::new();
        let _ = write!(&mut s, "kmsg {} {} {} {} {} {} {} {} {} {}\n", 
            seq, 
            entry.timestamp.tv_sec, 
            entry.timestamp.tv_nsec, 
            entry.priority, 
            entry.level, 
            entry.source, 
            entry.message, 
            entry.pid, 
            entry.tid, 
            entry.flags);
        result.push(s);
    }

    result
}

use fax::{VecWriter, Bits, Color};

fn transitions_to_pbm_line(transitions: &[u16], width: u16) -> Vec<u8> {
    let mut result = Vec::new();
    let mut writer = VecWriter::new(&mut result);
    let mut current_color = Color::Black;
    let mut current_bit_count = 0;
    let mut bit_buffer = 0u8;

    for &pos in transitions {
        let run_length = pos as usize - current_bit_count;
        if run_length > 0 {
            // Write the current color
            for _ in 0..run_length {
                if current_color == Color::White {
                    bit_buffer |= 1 << (current_bit_count % 8);
                }
                current_bit_count += 1;
                if current_bit_count % 8 == 0 {
                    writer.write_bit(bit_buffer);
                    bit_buffer = 0;
                }
            }
        }
        current_color = Color::White;
    }

    // Write the remaining bits
    if current_bit_count % 8 != 0 {
        writer.write_bit(bit_buffer);
    }

    // Write the final byte
    if current_bit_count % 8 != 0 {
        writer.write_bit(0);
    }

    // Ensure the line is properly padded to 8 bits
    let padding = (8 - (current_bit_count % 8)) % 8;
    for _ in 0..padding {
        writer.write_bit(0);
    }

    result
}

