fn dashed_chain(
    chain: batbox_lapp::Chain<f32>,
    width: f32,
    color_a: Rgba<f32>,
    color_b: Rgba<f32>,
    round_resolution: usize,
) -> Chain {
    let mut result = Chain::new();
    let mut current_color = color_a;
    let mut vertex_index = 0;
    let mut previous_vertex = chain.vertices[0];
    let mut segments = vec![];
    let mut current_segment = vec![];

    // Process each segment of the chain
    while vertex_index < chain.vertices.len() {
        let current_vertex = chain.vertices[vertex_index];
        let next_vertex = if vertex_index + 1 < chain.vertices.len() {
            chain.vertices[vertex_index + 1]
        } else {
            current_vertex
        };

        // Determine the segment direction
        let direction = (next_vertex - previous_vertex).normalize();
        let segment_length = (next_vertex - previous_vertex).length();

        // Create a dashed segment with alternating colors
        let mut segment_vertices = vec![];
        let mut t = 0.0;
        let mut step = 1.0 / round_resolution as f32;

        while t < segment_length {
            let length = t + step;
            let point = previous_vertex + direction * length;
            segment_vertices.push(point);
            t += step;
        }

        // Assign color based on segment index
        if segments.len() % 2 == 0 {
            current_color = color_a;
        } else {
            current_color = color_b;
        }

        // Add the segment to the result with the current color
        for &vertex in &segment_vertices {
            result.vertices.push(ColoredVertex {
                vertex,
                color: current_color,
            });
        }

        segments.push(segment_vertices);
        previous_vertex = current_vertex;
        vertex_index += 1;
    }

    result
}

use anyhow::Context;
use mas_storage::{compat::CompatSessionFilter, oauth2::OAuth2SessionFilter, user::{BrowserSessionFilter, UserRepository}, RepositoryAccess};
use crate::State;

fn bulk_deactivate_user(user_id: i64, state: &State) -> Result<(), anyhow::Error> {
    let repo_access = state.repo_access();

    // Deactivate the user
    let user_repo = repo_access.user();
    user_repo
        .deactivate_user(user_id)
        .context("Failed to deactivate user")?;

    // Remove all browser sessions for the user
    let browser_sessions = user_repo
        .list_browser_sessions(user_id)
        .context("Failed to list browser sessions")?;

    for session_id in browser_sessions {
        user_repo
            .delete_browser_session(session_id)
            .context("Failed to delete browser session")?;
    }

    // Remove all OAuth2 sessions for the user
    let oauth2_sessions = user_repo
        .list_oauth2_sessions(user_id)
        .context("Failed to list OAuth2 sessions")?;

    for session_id in oauth2_sessions {
        user_repo
            .delete_oauth2_session(session_id)
            .context("Failed to delete OAuth2 session")?;
    }

    // Remove all compatibility sessions for the user
    let compat_sessions = user_repo
        .list_compat_sessions(user_id)
        .context("Failed to list compatibility sessions")?;

    for session_id in compat_sessions {
        user_repo
            .delete_compat_session(session_id)
            .context("Failed to delete compatibility session")?;
    }

    Ok(())
}

