    Ok(LambdaResponse::default())
}

use crate::parser::Stream;
use crate::elf32::Elf32Header;
use crate::ByteOrder;
use crate::ParseError;

fn elf32_total_section_size(
    data: &[u8],
    byte_order: binfarce::ByteOrder,
) -> Result<u64, binfarce::ParseError> {
    let mut stream = Stream::new(data);
    let elf_header = Elf32Header::parse(&mut stream, byte_order)?;

    let section_header_table_offset = elf_header.section_header_table_offset;
    let section_header_table_size = elf_header.section_header_table_size;

    let mut total_size = 0u64;

    let mut stream = Stream::new(&data[section_header_table_offset as usize..]);
    for _ in 0..elf_header.section_header_count {
        let section_header = unsafe { std::ptr::read_unaligned(&data[section_header_table_offset as usize..][stream.position()..stream.position() + 32]) };
        let size = section_header.size;
        total_size += size as u64;
        stream.advance(32);
    }

    Ok(total_size)
}

