fn validate_block_reward<CS: ChainStore + VersionbitsIndexer>(
    context: &VerifyContext<CS>,
    parent: &HeaderView,
) -> Result<(), Error> {
    let block_number = context.block_number();
    let consensus_parameters = context.get_consensus_parameters()?;
    let target = context.get_target(parent)?;
    let cellbase_output = context.cellbase_output()?;
    let capacity = cellbase_output.capacity();

    // Check that the cellbase output has the correct capacity
    if capacity != consensus_parameters.block_reward(block_number) {
        return Err(Error::CellbaseError(CellbaseError::InvalidCapacity));
    }

    // Check that the reward target is correctly finalized
    if target != consensus_parameters.reward_target(block_number) {
        return Err(Error::CellbaseError(CellbaseError::InvalidTarget));
    }

    Ok(())
}

use sha2::{Sha256, Digest};
use std::str::FromStr;
use toml_edit::Document;

fn dependency_graph_hash(cargo_toml: &str) -> Result<String, Box<dyn std::error::Error>> {
    let mut hasher = Sha256::new();
    let mut doc: Document = cargo_toml.parse()?;

    if let Some(package) = doc.get("package") {
        if let Some(name) = package.get("name") {
            if let Some(name_str) = name.as_str() {
                hasher.update(name_str);
            }
        }
    }

    if let Some(dependencies) = doc.get("dependencies") {
        if let Some(dependencies_table) = dependencies.as_table() {
            for (dep_name, dep_value) in dependencies_table {
                if let Some(dep_str) = dep_value.as_str() {
                    hasher.update(dep_name);
                    hasher.update(dep_str);
                }
            }
        }
    }

    let result = hasher.finalize();
    let hex_result = format!("{:x}", result);
    Ok(hex_result)
}

use crate::{IndexerResult, Database};
use fuel_indexer_schema::FtColumn;

fn put_many_objects(
    &mut self,
    objects: Vec<(i64, Vec<FtColumn>, Vec<u8>)>,
) -> IndexerResult<()> {
    let mut transaction = self.db.transaction()?;
    for (id, columns, data) in objects {
        let mut stmt = transaction
            .prepare("INSERT INTO objects (id, column1, column2, column3, column4, column5, column6, column7, column8, column9, column10, data) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)")?;
        stmt.bind(1, &id)?;
        stmt.bind(2, &columns[0])?;
        stmt.bind(3, &columns[1])?;
        stmt.bind(4, &columns[2])?;
        stmt.bind(5, &columns[3])?;
        stmt.bind(6, &columns[4])?;
        stmt.bind(7, &columns[5])?;
        stmt.bind(8, &columns[6])?;
        stmt.bind(9, &columns[7])?;
        stmt.bind(10, &columns[8])?;
        stmt.bind(11, &columns[9])?;
        stmt.bind(12, &data)?;
        stmt.next()?;
    }
    transaction.commit()?;
