thread_local! {
    static COUNTER: Context<AtomicUsize> = Context::new(AtomicUsize::new(0));
}

fn heavy_computation() -> usize {
    let guard = COUNTER.with(|counter| make_guard(counter));
    let value = *guard.get();

    // Spawn a blocking thread to perform the computation
    let handle = std::thread::spawn(move || {
        // Ensure the guard is valid in the new thread
        let guard = COUNTER.with(|counter| make_guard(counter));
        let mut value = *guard.get();

        // Simulate a CPU-bound computation
        for _ in 0..1_000_000_000 {
            value += 1;
        }

        value
    });

    // Wait for the computation to complete and return the result
    handle.join().unwrap()
}

