use deno_process::{Command, ProcessError, Stdio};
use tokio::io::AsyncReadExt;

fn run_and_collect_strings(
    cmd: &str,
    args: &[&str],
) -> Result<(String, String), ProcessError> {
    let mut child = Command::new(cmd)
        .args(args)
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;

    let stdout = child.stdout.take().unwrap();
    let stderr = child.stderr.take().unwrap();

    let mut stdout_str = String::new();
    let mut stderr_str = String::new();

    let _ = tokio::task::spawn(async move {
        let _ = stdout.read_to_string(&mut stdout_str).await;
        let _ = stderr.read_to_string(&mut stderr_str).await;
    })
    .await
    .unwrap();

    let status = child.wait().unwrap();

    if !status.success() {
        return Err(ProcessError::new("Command failed"));
    }

    Ok((stdout_str, stderr_str))
}

