        .arg("--id")
        .arg(elf_path)
        .output()
        .with_context(|| "Failed to run r0vm --id")?;

    if output.status.success() {
        let hex_str = String::from_utf8_lossy(&output.stdout);
        let digest = Digest::from_hex(hex_str.trim()).with_context(|| "Invalid hex digest")?;
        return Ok(digest);
    }

    // Fall back to Rust implementation
    let digest = risc0_binfmt::elf::get_elf_digest(elf_path)
        .with_context(|| "Failed to compute digest from ELF")?;

    Ok(digest)
}

