use ar::{Archive, Builder, Header};  
use std::io::{Read, Write, Result};  

fn filter_executable<R: Read, W: Write>(src: &mut Archive<R>, dst: &mut Builder<W>) -> Result<()> {  
    for entry in src.entries() {  
        let mut header = Header::new();  
        let mut data = Vec::new();  
        let entry_result = entry.read_to_end(&mut data)?;  
        if entry_result.is_err() {  
            continue;  
        }  
        header.set_data(&data);  
        if header.mode().unwrap_or(0).has_perm(0o111) {  
            dst.add_header(&header)?;  
        }  
    }  
    Ok(())  
}

