fn replace_height(expr: hir::Expr, value: i32) -> hir::Expr {
    match expr.kind {
        ExprKind::Binary(Binary { op: hir::BinaryOp::Eq, left, right }) => {
            if let ExprKind::Global(GlobalVars::HEIGHT) = left.kind {
                let right_expr = match right.kind {
                    ExprKind::Literal(Literal::Integer(i)) if i == value => right,
                    _ => hir::Expr {
                        kind: ExprKind::Literal(Literal::Integer(value)),
                        ..right
                    },
                };
                hir::Expr {
                    kind: ExprKind::Binary(Binary {
                        op: hir::BinaryOp::Eq,
                        left,
                        right: right_expr,
                    }),
                    ..expr
                }
            } else {
                expr
            }
        }
        _ => expr,
    }
}

