use zbus_lockstep::{LockstepError};
use zbus_lockstep::zbus_xml;
use std::io::BufReader;
use std::io::Read;
use std::collections::HashMap;

fn list_method_arguments(
    xml: impl std::io::Read,
    interface_name: &str,
    method_name: &str,
) -> Result<Vec<(String, String)>, Box<dyn std::error::Error>> {
    let reader = BufReader::new(xml);
    let xml_str = std::str::from_utf8(reader.bytes().collect::<Result<_, _>>()?)?;
    let doc = zbus_xml::parse_xml(xml_str)?;

    let mut interface = None;
    let mut method = None;

    for node in doc.iter() {
        match node {
            zbus_xml::XmlNode::Element { name, attributes, children } => {
                if name == "interface" {
                    if let Some(attr) = attributes.iter().find(|(k, _)| *k == "name") {
                        if attr.1 == interface_name {
                            interface = Some(node);
                        }
                    }
                } else if name == "method" {
                    if let Some(attr) = attributes.iter().find(|(k, _)| *k == "name") {
                        if attr.1 == method_name {
                            method = Some(node);
                        }
                    }
                }
            }
            _ => {}
        }
    }

    if interface.is_none() || method.is_none() {
        return Err("Interface or method not found".into());
    }

    let interface_node = interface.unwrap();
    let method_node = method.unwrap();

    let mut args: Vec<(String, String)> = Vec::new();

    for child in method_node.children.iter() {
        if let zbus_xml::XmlNode::Element { name, attributes, .. } = child {
            if name == "arg" {
                let mut name = String::new();
                let mut signature = String::new();

                for (key, value) in attributes.iter() {
                    match key {
                        "name" => name = value.to_string(),
                        "type" => signature = value.to_string(),
                        _ => {}
                    }
                }

                if !name.is_empty() && !signature.is_empty() {
                    args.push((name, signature));
                }
            }
        }
    }

    Ok(args)
}

