use barter_integration::channel::{UnboundedTx, mpsc_unbounded};
use std::fmt::Debug;
use std::clone::Clone;
use std::marker::Send;
use std::sync::{Arc, atomic::{AtomicBool, Ordering}};

pub struct ChannelTxDroppable<T> {
    tx: UnboundedTx<T>,
    disabled: Arc<AtomicBool>,
}

impl<T> ChannelTxDroppable<T> {
    pub fn new() -> Self {
        let (tx, _) = mpsc_unbounded();
        let disabled = Arc::new(AtomicBool::new(false));
        let disabled_clone = Arc::clone(&disabled);
        std::thread::spawn(move || {
            if let Err(_) = tx.send(()) {
                disabled_clone.store(true, Ordering::SeqCst);
                println!("Receiver dropped, sending disabled");
            }
        });
        ChannelTxDroppable { tx, disabled }
    }

    pub fn send(&self, item: T) -> Result<(), std::sync::mpsc::SendError<T>> {
        if self.disabled.load(Ordering::SeqCst) {
            return Err(std::sync::mpsc::SendError(item));
        }
        self.tx.send(item)
    }

    pub fn disable(&self) {
        self.disabled.store(true, Ordering::SeqCst);
    }
}
