use css_color_parser::Color;

fn blend(color1: Color, color2: Color, ratio: f32) -> Color {
    let ratio = ratio.clamp(0.0, 1.0);

    let r = (color1.red() as f32 * (1.0 - ratio) + color2.red() as f32 * ratio) as u8;
    let g = (color1.green() as f32 * (1.0 - ratio) + color2.green() as f32 * ratio) as u8;
    let b = (color1.blue() as f32 * (1.0 - ratio) + color2.blue() as f32 * ratio) as u8;
    let a = (color1.alpha() as f32 * (1.0 - ratio) + color2.alpha() as f32 * ratio) as u8;

    Color::rgba(r, g, b, a)
}

