fn validate_vary_header(
    vary_header: &ByteString,
    query_headers: &[(ByteString, ByteString)],
    cached_headers: &http::HeaderMap,
) -> bool {
    let vary_headers = get_headers_from_vary_header(vary_header);
    if vary_headers.is_empty() {
        return true;
    }

    for vary_header in vary_headers {
        let query_value = get_header(query_headers, &vary_header);
        let cached_value = cached_headers.get(&vary_header);
        if query_value != cached_value {
            return false;
        }
    }

    true
}

fn get_headers_from_vary_header(vary_header: &ByteString) -> Vec<ByteString> {
    vary_header
        .split_ascii_whitespace()
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string().into())
        .collect()
}

fn get_header(
    headers: &[(ByteString, ByteString)],
    name: &ByteString,
) -> ByteString {
    headers
        .iter()
        .find(|(key, _)| key == name)
        .map(|(_, value)| value.clone())
        .unwrap_or(ByteString::from(""))
}

