            if path.exists() {
                Some(path)
            } else {
                None
            }
        })
        .collect();

    // Sort files by creation time to get oldest first
    files.sort_by(|a, b| {
        let a_metadata = fs::metadata(a).expect("Failed to read metadata");
        let b_metadata = fs::metadata(b).expect("Failed to read metadata");
        a_metadata.created().cmp(&b_metadata.created())
    });

    // Calculate total size of all files
    for file in &files {
        let metadata = fs::metadata(file).expect("Failed to read metadata");
        total_size += metadata.len() as usize;
    }

    // If total size is already under the limit, do nothing
    if total_size <= max_total_bytes {
        return Ok(());
    }

    // Remove oldest files until total size is within the limit
    for file in files {
        let metadata = fs::metadata(&file).expect("Failed to read metadata");
        let file_size = metadata.len() as usize;

        if total_size - file_size <= max_total_bytes {
            fs::remove_file(&file).expect("Failed to remove file");
            total_size -= file_size;
        } else {
            break;
        }
    }

    Ok(())
}

