fn fetch_decryption_key_shares(
    global_context: DynGlobalClientContext,
    tpe_pks: BTreeMap<PeerId, PublicKeyShare>,
    outpoint: OutPoint,
    contract: IncomingContract,
) -> Result<BTreeMap<PeerId, DecryptionKeyShare>, String> {
    let mut key_shares = BTreeMap::new();
    let mut peer_errors = Vec::new();

    for (peer_id, pk_share) in tpe_pks {
        let request = ApiRequestErased::new(
            DECRYPTION_KEY_SHARE_ENDPOINT,
            serde_json::to_value(&DecryptionKeyShareRequest {
                outpoint: outpoint.to_string(),
                contract_id: contract.id,
                public_key_share: pk_share.to_string(),
            })
            .map_err(|e| anyhow!("Failed to serialize request: {}", e))?,
        );

        match global_context
            .request_from_peer(peer_id, request)
            .map_err(|e| anyhow!("Failed to request decryption key share: {}", e))?
        {
            Ok(response) => {
                let share: DecryptionKeyShare = serde_json::from_value(response)
                    .map_err(|e| anyhow!("Failed to deserialize decryption key share: {}", e))?;

                key_shares.insert(peer_id, share);
            }
            Err(PeerError::NoResponse) => {
                peer_errors.push(peer_id);
            }
            Err(PeerError::InvalidResponse) => {
                peer_errors.push(peer_id);
            }
            Err(e) => {
                return Err(format!("Error requesting from peer {}: {}", peer_id, e));
            }
        }
    }

    if !peer_errors.is_empty() {
        return Err(format!("No response from peers: {:?}", peer_errors));
    }

    Ok(key_shares)
}

