    public_key_share: String,
}

use www_authenticate::{WwwAuthenticate, DigestChallenge, Algorithm, Qop};

fn validate_digest_challenges(auth: &WwwAuthenticate) -> bool {
    if let WwwAuthenticate::Digest(DigestChallenge {
        algorithm,
        realm,
        nonce,
        qop,
        // other fields can be ignored if not required
    }) = auth
    {
        // Check if algorithm is valid
        if !matches!(algorithm, Algorithm::Md5 | Algorithm::Md5Sess) {
            return false;
        }

        // Check if realm is present
        if realm.is_none() {
            return false;
        }

        // Check if nonce is present
        if nonce.is_none() {
            return false;
        }

        // Check if qop is valid
        if let Some(qop) = qop {
            if !matches!(qop, Qop::Auth | Qop::AuthInt) {
                return false;
            }
        }

        true
    } else {
        false
    }
}

fn negotiate_with_retry<R, I>(
    inner: R,
    protocols: I,
    version: Version,
    max_attempts: usize,
) -> Result<(I::Item, Negotiated<R>), NegotiationError>
where
    R: AsyncRead + AsyncWrite + Unpin,
    I: IntoIterator,
    I::Item: AsRef<str> + Clone,
{
    let mut attempts = 0;
    let mut backoff = Duration::from_millis(100);

    loop {
        attempts += 1;
        if attempts > max_attempts {
            return Err(NegotiationError::TooManyAttempts);
        }

        match dialer_select_proto(inner, protocols, version).await {
            Ok((selected_proto, negotiated)) => {
                return Ok((selected_proto, negotiated));
            }
            Err(e) => {
                if attempts == max_attempts {
                    return Err(e);
                }
                sleep(backoff).await;
                backoff = backoff * 2;
            }
        }
    }
}

