use std::net::{IpAddr, SocketAddr};
use std::os::unix::io::RawFd;
use std::io::{self, Write};
use std::thread;
use std::time::Duration;
use nix::sys::socket::{bind, sock_type, AddressFamily};
use nix::sys::signal::Signal;
use nix::unistd::close;
use nix::fcntl::{flock, FlockArg};

fn check_port_availability_on_interfaces(
    port: u16,
    interfaces: &[IpAddr],
) -> Result<Vec<(IpAddr, bool)>, String> {
    let mut results = Vec::new();
    let mut fd = None;

    for &ip in interfaces {
        let socket_addr = SocketAddr::new(ip, port);
        let fd = match bind(
            socket_addr,
            sock_type::SOCK_STREAM,
            AddressFamily::AF_INET,
        ) {
            Ok(fd) => fd,
            Err(e) => {
                results.push((ip, false));
                continue;
            }
        };

        // Try to lock the socket to prevent other processes from binding
        if let Err(e) = flock(fd, FlockArg::LockExclusiveNonBlock) {
            results.push((ip, false));
            close(fd).unwrap();
            continue;
        }

        // Attempt to listen on the socket
        match nix::sys::socket::listen(fd, 10) {
            Ok(_) => {
                results.push((ip, true));
                close(fd).unwrap();
            }
            Err(e) => {
                results.push((ip, false));
                close(fd).unwrap();
            }
        }
    }

    Ok(results)
}

fn set_color_command(mut cmd: ConsoleCommand<SetColorCommand>, mut config: ResMut<ConsoleConfiguration>) {
    let SetColorCommand { fg, bg } = cmd.args;
    let mut fg_color = config.foreground;
    let mut bg_color = config.background;

    if let Some(fg_name) = fg {
        if let Some(color) = parse_color(&fg_name) {
            fg_color = color;
        }
    }

    if let Some(bg_name) = bg {
        if let Some(color) = parse_color(&bg_name) {
            bg_color = color;
        }
    }

    config.foreground = fg_color;
    config.background = bg_color;

    reply!("Console colors updated: foreground={:?}, background={:?}", fg_color, bg_color);
}

fn parse_color(name: &str) -> Option<Color32> {
    match name.to_lowercase().as_str() {
        "black" => Some(Color32::BLACK),
        "white" => Some(Color32::WHITE),
        "red" => Some(Color32::RED),
        "green" => Some(Color32::GREEN),
        "blue" => Some(Color32::BLUE),
        "cyan" => Some(Color32::CYAN),
        "magenta" => Some(Color32::MAGENTA),
        "yellow" => Some(Color32::YELLOW),
        "gray" => Some(Color32::GRAY),
        "lightgray" => Some(Color32::LIGHT_GRAY),
        _ => None,
    }
}

