fn analyze_contract_sizes_for_accounts(
    home: &PathBuf,
    genesis_validation: GenesisValidationMode,
    account_ids: Vec<AccountId>,
) -> anyhow::Result<()> {
    let config = load_config(home, genesis_validation)?;
    let storage = open_storage(home, &config, genesis_validation)?;
    let chain_store = ChainStore::open(home, &config, genesis_validation)?;
    let chain_store_access = ChainStoreAccess::new(chain_store);
    let epoch_manager = EpochManager::open(home, &config)?;
    let epoch_manager_adapter = EpochManagerAdapter::new(epoch_manager);
    let store_adapter = StoreAdapter::new(storage);
    let flat_storage_manager = FlatStorageManager::new(store_adapter);
    let shard_tries = ShardTries::new(flat_storage_manager, config.shard_layout.clone());
    let trie_config = TrieConfig::default();
    let trie_db_storage = TrieDBStorage::new(shard_tries, trie_config);
    let trie = Trie::new(trie_db_storage, StateSnapshotConfig::default());

    let mut contract_sizes = HashMap::new();

    for account_id in &account_ids {
        contract_sizes.insert(account_id.clone(), 0);
    }

    let command_args = CommandArgs {
        home: home.to_path_buf(),
        genesis_validation,
        ..Default::default()
    };

    let block_iterator = make_block_iterator_from_command_args(command_args)?;
    let mut block_height = 0;

    for block in block_iterator {
        let block_height = block.height;
        let shard_uid = block.shard_uid;

        let trie = trie.get_trie_for_shard(shard_uid);
        let mut contract_size = 0;

        for (key, value) in trie.iter() {
            let key = col::account_id_key(key);
            if let Some(account_id) = AccountId::from_bytes(key) {
                if account_ids.contains(&account_id) {
                    contract_size += value.len();
                }
            }
        }

        for account_id in &account_ids {
            let current_size = contract_sizes.get_mut(account_id).unwrap();
            *current_size += contract_size;
        }

        block_height += 1;
    }

    for (account_id, size) in &contract_sizes {
        println!("Account: {}, Contract Size: {}", account_id, size);
    }

    Ok(())
}

fn moving_average(points: &[(f32, f32)], window_size: usize) -> Vec<(f32, f32)> {
    if points.is_empty() || window_size == 0 {
        return Vec::new();
    }

    let mut result = Vec::new();
    let mut sum = 0.0;
    let mut count = 0;

    for (i, &(x, y)) in points.iter().enumerate() {
        sum += y;
        count += 1;

        if count == window_size {
            result.push((x, sum / window_size as f32));
            sum -= points[i - window_size].1;
        }
    }

    result
}

