fn pretty_hir(expr: &hir::Expr) -> String {
    match &expr.kind {
        ExprKind::Literal(literal) => match literal {
            Literal::Int(n) => format!("{}", n),
            Literal::Float(n) => format!("{}", n),
            Literal::Char(c) => format!("'{}'", c),
            Literal::Str(s) => format!("\"{}\"", s),
        },
        ExprKind::Binary(op, lhs, rhs) => {
            let lhs_str = pretty_hir(lhs);
            let rhs_str = pretty_hir(rhs);
            format!("{} {} {}", lhs_str, op, rhs_str)
        },
        ExprKind::Variable(name) => format!("var: {}", name),
        ExprKind::Call(func, args) => {
            let args_str: Vec<String> = args.iter().map(pretty_hir).collect();
            format!("{}({})", pretty_hir(func), args_str.join(", "))
        },
        ExprKind::If(cond, then, else_opt) => {
            let cond_str = pretty_hir(cond);
            let then_str = pretty_hir(then);
            let else_str = else_opt.as_ref().map_or("".to_string(), |e| pretty_hir(e));
            format!("if {} {{ {} }} else {{ {} }}", cond_str, then_str, else_str)
        },
        ExprKind::Loop(body, label) => {
            let body_str = pretty_hir(body);
            format!("loop {} {}", body_str, label.unwrap_or("".to_string()))
        },
        ExprKind::Match(expr, arms) => {
            let expr_str = pretty_hir(expr);
            let arms_str: Vec<String> = arms.iter().map(|(pat, expr)| {
                format!("case {} {{ {} }}", pat, pretty_hir(expr))
            }).collect();
            format!("match {} {{ {} }}", expr_str, arms_str.join("\n"))
        },
        ExprKind::Assign(lhs, rhs) => {
            let lhs_str = pretty_hir(lhs);
            let rhs_str = pretty_hir(rhs);
            format!("{} = {}", lhs_str, rhs_str)
        },
        ExprKind::Block(exprs, tail) => {
            let exprs_str: Vec<String> = exprs.iter().map(pretty_hir).collect();
            let tail_str = tail.as_ref().map_or("".to_string(), pretty_hir);
            format!("{{ {} }} {}", exprs_str.join("\n"), tail_str)
        },
        ExprKind::GlobalVar(var) => format!("global: {}", var),
        ExprKind::FnCall(name, args) => {
            let args_str: Vec<String> = args.iter().map(pretty_hir).collect();
            format!("{}({})", name, args_str.join(", "))
        },
        ExprKind::Return(expr) => {
            let expr_str = expr.as_ref().map_or("".to_string(), pretty_hir);
            format!("return {}", expr_str)
        },
        ExprKind::Break(label, expr) => {
            let expr_str = expr.as_ref().map_or("".to_string(), pretty_hir);
            format!("break {} {}", label.unwrap_or("".to_string()), expr_str)
        },
        ExprKind::Continue(label) => format!("continue {}", label.unwrap_or("".to_string())),
        ExprKind::While(cond, body) => {
            let cond_str = pretty_hir(cond);
            let body_str = pretty_hir(body);
            format!("while {} {{ {} }}", cond_str, body_str)
        },
        ExprKind::Struct(fields, name) => {
            let fields_str: Vec<String> = fields.iter().map(|(name, expr)| {
                format!("{}: {}", name, pretty_hir(expr))
            }).collect();
            format!("struct {} {{ {} }}", name.unwrap_or("".to_string()), fields_str.join(", "))
        },
        ExprKind::Array(exprs) => {
            let exprs_str: Vec<String> = exprs.iter().map(pretty_hir).collect();
            format!("array [{}]", exprs_str.join(", "))
        },
        ExprKind::Index(expr, index) => {
            let expr_str = pretty_hir(expr);
            let index_str = pretty_hir(index);
            format!("{}[{}]", expr_str, index_str)
        },
        ExprKind::Cast(expr, ty) => {
            let expr_str = pretty_hir(expr);
            format!("cast {} as {}", expr_str, ty)
        },
        ExprKind::Ref(expr, mutability) => {
            let expr_str = pretty_hir(expr);
            let mutability_str = if mutability { "mut" } else { "" };
            format!("ref {} {}", expr_str, mutability_str)
        },
