fn monitor_connection_stats(client: &QuicClientConnection, interval: Duration) {
    let mut last_stats = client.get_stats();
    thread::spawn(move || {
        loop {
            thread::sleep(interval);
            let current_stats = client.get_stats();
            let delta = current_stats
                .clone()
                .into_iter()
                .zip(last_stats.clone().into_iter())
                .map(|(current, last)| current - last)
                .collect::<Vec<_>>();
            info!("Connection stats delta: {:?}", delta);
            last_stats = current_stats;
        }
    });
}

