fn build_chain_from_json<P: AsRef<std::path::Path>>(path: P, lookback: Option<Lookback>) -> Result<SmartModuleChainBuilder> {
    let config = std::fs::read_to_string(path.as_ref())
        .context("Failed to read transformation config file")?;

    let config: TransformationConfig = serde_json::from_str(&config)
        .context("Failed to parse transformation config")?;

    let mut builder = SmartModuleChainBuilder::new();

    for module in &config.modules {
        let module_path = module.module_path.clone();
        let module_config = SmartModuleConfig::new(module_path, lookback.clone());

        let client = SmartModuleApiClient::new();
        let module_info = client
            .get_module_info(&module_path)
            .context("Failed to fetch module info")?;

        builder.add_module(module_config, module_info);
    }

    Ok(builder)
}

fn execute_federation_query<Ret, S>(
    api: &DynGlobalApi,
    strategy: S,
    method: String,
    params: ApiRequestErased,
) -> Result<Ret>
where
    Ret: serde::de::DeserializeOwned + Eq + std::fmt::Debug + Clone + MaybeSend,
    S: QueryStrategy<Ret, Ret> + MaybeSend,
{
    let mut retries = 3;
    let mut result: Option<Ret> = None;

    while retries > 0 {
        match api.federation_query_with_strategy(strategy.clone(), &method, params.clone()) {
            Ok(res) => {
                if let Ok(deserialized) = serde_json::from_str(&res) {
                    if deserialized == result.unwrap_or_default() {
                        result = Some(deserialized);
                        break;
                    }
                }
                retries = 0;
            }
            Err(e) => {
                tracing::warn!("Query failed: {}", e);
                std::thread::sleep(std::time::Duration::from_secs(1));
                retries -= 1;
            }
        }
    }

    result.ok_or(anyhow::anyhow!("Query failed after retries"))
}

