struct InputWithSuggestions {
    input: Input,
    suggestions: Vec<String>,
    current_suggestion_index: usize,
    input_value: String,
}

impl InputWithSuggestions {
    fn new(initial: String, suggestions: Vec<String>) -> Self {
        Self {
            input: Input::new(initial),
            suggestions,
            current_suggestion_index: 0,
            input_value: initial,
        }
    }

    fn handle_event(&mut self, event: &Event) -> Option<StateChanged> {
        match event {
            Event::Key(key) => {
                if key.code == crossterm::event::KeyCode::Tab {
                    self.current_suggestion_index = (self.current_suggestion_index + 1) % self.suggestions.len();
                    self.input_value = self.suggestions[self.current_suggestion_index].clone();
                    Some(StateChanged::Input(self.input_value.clone()))
                } else {
                    self.input.handle_event(event)
                }
            }
            _ => self.input.handle_event(event),
        }
    }

    fn render(&self) -> String {
        self.input.render()
    }

    fn get_value(&self) -> &str {
        self.input_value.as_str()
    }

    fn set_value(&mut self, value: String) {
        self.input_value = value;
        self.input.set_value(value);
    }
}

fn make_lazy_component(
    fn_ident: &syn::Ident,
    inputs: &syn::punctuated::Punctuated<syn::FnArg, syn::Token![,]>,
    block: &syn::Block,
) -> proc_macro2::TokenStream {
    let fn_ident = fn_ident.to_string();
    let inputs = inputs.iter().map(|arg| {
        if let FnArg::Typed(ty) = arg {
            ty.path.get_ident().map(|ident| ident.to_string()).unwrap_or_default()
        } else {
            "".to_string()
        }
    }).collect::<Vec<_>>();

    quote! {
        #[allow(clippy::type_complexity)]
        pub fn #fn_ident(#(#inputs: std::marker::PhantomData,)*) -> impl FnOnce() -> syn::parse::ParseStream {
            move || {
                let mut __body = #block;
                let __inputs = #(#inputs,)*
                syn::parse::parse_tokens(__body.into_token_stream())
            }
        }
    }
}

use crate::*;
use futures::future::join_all;

fn batch_process<F, R>(&self, func: F) -> Result<Vec<R>, GhostError>
    where
        F: Fn(&BoxEntity) -> Result<R, GhostError> + Send + Sync + 'static,
        R: Send + 'static,
{
    let entities: Vec<&BoxEntity> = self.entities.lock().unwrap().iter().collect();
    let mut futures = Vec::new();

    for entity in entities {
        let f = func;
        futures.push(tokio::spawn(f(entity)));
    }

    let results = join_all(futures).await;
    let mut output = Vec::new();

    for result in results {
        output.push(result??);
    }

    Ok(output)
}

