fn refresh_session_expiry<C>(store: &RedisStore<C>, session_id: &Id, extra: Duration) -> Result<(), RedisStoreError>
where
    C: KeysInterface + Send + Sync,
{
    let key = store.key(session_id);
    let current_expiry = store.get_expiry(session_id).unwrap_or(OffsetDateTime::now_utc());
    let new_expiry = current_expiry + extra;

    let options = SetOptions::new()
        .expiration(Expiration::FromNow(new_expiry - OffsetDateTime::now_utc()))
        .nx(false)
        .xx(false)
        .get(false)
        .keys(1);

    store.get_connection().set(key, &[], options).await?;
    Ok(())
}

fn outgoing_payment_summary(events: &[PersistedLogEntry]) -> (usize, f64, f64) {
    let mut success_count = 0;
    let mut total_fee = 0.0;
    let mut total_latency = 0.0;
    let mut payment_count = 0;

    for event in events {
        if let Some(event) = events::outgoing_payment(event) {
            if event.status == "success" {
                success_count += 1;
                total_fee += event.fee as f64;
                total_latency += event.latency as f64;
            }
            payment_count += 1;
        }
    }

    let avg_fee = if payment_count > 0 { total_fee / payment_count as f64 } else { 0.0 };
    let avg_latency = if payment_count > 0 { total_latency / payment_count as f64 } else { 0.0 };

    (success_count, avg_fee, avg_latency)
}

fn compute_blob_kzg_proofs(ctx: &Context, blobs: &[BlobRef], commitments: &[Bytes48Ref]) -> Result<Vec<KZGProof4844>, Error> {
    if blobs.len() != commitments.len() {
        return Err(Error::InvalidInput);
    }

    let mut proofs = Vec::with_capacity(blobs.len());
    for (blob, commitment) in blobs.iter().zip(commitments.iter()) {
        let proof = ctx.kzg_prove(blob, commitment)?;
        proofs.push(proof);
    }

    Ok(proofs)
}

fn check_duplicate_fields(ctx: &mut Context<'_>, type_name: &str, base_fields: &[Positioned<ast::FieldDefinition>]) {
    let mut field_names = HashSet::new();
    let mut duplicates = Vec::new();

    for field in base_fields {
        let field_name = &field.item.name.value;
        if !field_names.insert(field_name) {
            duplicates.push(field_name.to_string());
        }
    }

    if !duplicates.is_empty() {
        let mut all_fields = base_fields.to_vec();
        let extensions = ctx.extensions();
        for extension in extensions {
            if let Some(fields) = extension.fields() {
                for field in fields {
                    let field_name = &field.item.name.value;
                    if !field_names.insert(field_name) {
                        duplicates.push(field_name.to_string());
                    }
                }
            }
        }

        for duplicate in duplicates {
            ctx.report(Report::new().with_message(format!("Duplicate field name '{}' in type '{}'", duplicate, type_name)));
        }
    }
}

