fn calculate_total_gas_usage_for_shards(
    home: &PathBuf,
    genesis_validation: GenesisValidationMode,
    shard_ids: Vec<ShardId>,
) -> anyhow::Result<()> {
    let config = load_config(home, genesis_validation)?;
    let store = open_storage(home, &config)?; // Open the storage
    let chain_store = ChainStore::new(store, &config, genesis_validation)?;
    let chain_store_access = ChainStoreAccess::new(chain_store);
    let epoch_manager = EpochManager::new(&config, &chain_store_access)?;

    // Get the latest block height
    let latest_block_height = chain_store_access.get_finalized_block_height()?;
    let start_block_height = latest_block_height.saturating_sub(100);

    let mut total_gas_used = 0;

    // Iterate over the last 100 blocks
    for block_height in start_block_height..=latest_block_height {
        let block_hash = chain_store_access.get_block_hash(block_height)?;
        let block = chain_store_access.get_block(&block_hash)?;
        let block_execution_result = block.execution_result();

        if let Some(execution_result) = block_execution_result {
            // Iterate over all shards in the block
            for shard_id in &shard_ids {
                if let Some(gas_used) = execution_result.gas_used_per_shard.get(shard_id) {
                    total_gas_used += gas_used;
                }
            }
        }
    }

    println!("Total gas used for shards {:?} over last 100 blocks: {}", shard_ids, total_gas_used);
    Ok(())
}

fn start_labeled_loop(
    builder: &mut ControlFlowGraphBuilder<'_>,
    label: &'static str,
) -> (BlockNodeId, BlockNodeId) {
    let entry_block = builder.create_block();
    let body_block = builder.create_block();

    // Set up the entry block
    builder.set_entry_block(entry_block);
    builder.add_block(entry_block);

    // Set up the body block
    builder.add_block(body_block);

    // Register the label context for break and continue
    builder.register_label(label, entry_block, CtxFlags::BREAK | CtxFlags::CONTINUE);

    // Create an edge from entry to body
    builder.add_edge(entry_block, body_block, EdgeType::Normal);

    // Create an edge from body to entry to form a loop
    builder.add_edge(body_block, entry_block, EdgeType::Normal);

    (entry_block, body_block)
}

