fn batch_update<Q>(&mut self, updates: &[(Q, V)]) -> Result<(), &'static str>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
{
    let mut seen_keys = HashMap::new();
    for (key, value) in updates {
        let key_ref = key.borrow();
        if seen_keys.contains_key(key_ref) {
            return Err("Duplicate key found in updates");
        }
        seen_keys.insert(key_ref, ());
    }

    let mut multi_mut = HashMapMultiMut::new(self);
    for (key, value) in updates {
        let key_ref = key.borrow();
        if let Some(slot) = multi_mut.get_mut(key_ref) {
            unsafe {
                *slot.value_mut() = value;
            }
        } else {
            return Err("Key not found in map during batch update");
        }
    }

    Ok(())
}

use any_spawner::Executor;
use std::sync::{Arc, atomic::{AtomicBool, Ordering}};
use std::time::Duration;

struct CancellableTask {
    executor: Executor,
    cancellation_flag: Arc<AtomicBool>,
}

impl CancellableTask {
    fn new(executor: Executor, cancellation_flag: Arc<AtomicBool>) -> Self {
        CancellableTask {
            executor,
            cancellation_flag,
        }
    }
}

fn start<F>(interval: Duration, mut task: F) -> CancellableTask
    where
        F: FnMut() + Send + 'static,
{
    let cancellation_flag = Arc::new(AtomicBool::new(false));
    let cancellation_flag_clone = Arc::clone(&cancellation_flag);

    let executor = Executor::new();
    executor.spawn(move || {
        loop {
            if cancellation_flag.load(Ordering::Relaxed) {
                break;
            }
            task();
            executor.tick(interval);
        }
    });

    CancellableTask::new(executor, cancellation_flag)
}

fn cancel(task: &CancellableTask) {
    task.cancellation_flag.store(true, Ordering::Relaxed);
}

use async_acme::acme::{Directory, AcmeError};
use std::path::PathBuf;
use std::fs;
use serde_json;
use reqwest::Client;

fn get_cached_directory(cache_dir: &PathBuf, url: &str) -> Result<Directory, AcmeError> {
    // Ensure the cache directory exists
    fs::create_dir_all(cache_dir).map_err(|e| AcmeError::Other(e.to_string()))?;

    // Define the cache file path
    let cache_file = cache_dir.join("acme_directory.json");

    // Check if the cache file exists
    if PathBuf::from(&cache_file).exists() {
        // Read the cached JSON file
        let contents = fs::read_to_string(cache_file).map_err(|e| AcmeError::Other(e.to_string()))?;
        return serde_json::from_str(&contents).map_err(|e| AcmeError::Other(e.to_string()));
    }

    // If not cached, fetch the directory
    let client = Client::new();
    let response = client.get(url)
        .send()
        .map_err(|e| AcmeError::Other(e.to_string()))?;

    if !response.status().is_success() {
        return Err(AcmeError::Other(format!("Failed to fetch ACME directory: {}", response.status())));
    }

    let directory: Directory = response.json().map_err(|e| AcmeError::Other(e.to_string()))?;

    // Save the directory to cache
    let json = serde_json::to_string(&directory).map_err(|e| AcmeError::Other(e.to_string()))?;
    fs::write(cache_file, json).map_err(|e| AcmeError::Other(e.to_string()))?;

    Ok(directory)
}

use crate::collection::{CollectedTestCategory, CollectedTest, CollectedCategoryOrTest};
use crate::runner::{TestResult, Failure};
use std::time::{Duration, Instant};

fn run_tests_with_timeout<TData: Clone + Send + 'static>(
    category: &CollectedTestCategory<TData>,
    timeout: Duration,
    run_test: impl Fn(&CollectedTest<TData>) -> TestResult + Send + Sync + 'static,
) -> Vec<Failure<TData>> {
    let mut failures = Vec::new();
    let mut timeout_occurred = false;

    for test in &category.tests {
        let start = Instant::now();
        let result = run_test(test);
        let duration = start.elapsed();

        if duration > timeout {
            timeout_occurred = true;
            failures.push(Failure {
                category: test.category.clone(),
                test: test.name.clone(),
                message: format!("Test timed out after {}ms", duration.as_millis()),
                data: test.data.clone(),
            });
        } else {
            match result {
                TestResult::Passed => {}
                TestResult::Failed(message) => {
                    failures.push(Failure {
                        category: test.category.clone(),
                        test: test.name.clone(),
                        message,
                        data: test.data.clone(),
                    });
                }
                TestResult::Skipped => {}
            }
        }
    }

    if timeout_occurred {
        failures.push(Failure {
            category: category.name.clone(),
            test: String::from("Timeout"),
            message: format!("Some tests exceeded the timeout of {}ms", timeout.as_millis()),
            data: category.data.clone(),
        });
    }

    failures
}

fn select_gateway_for_invoice(api: &dyn LightningFederationApi, invoice: &Bolt11Invoice) -> Result<SafeUrl, anyhow::Error> {
