    }
}

use std::collections::HashMap;
use anyhow::anyhow;
use url::Url;
use rattler_networking::authentication_storage::AuthenticationStorage;
use rattler_networking::s3_middleware::S3;
use reqwest::Client;
use reqwest::header::{HeaderMap, HeaderValue};
use chrono::{Utc, Duration};

fn presign_s3_object(
    bucket: &str,
    key: &str,
    expiration_secs: u64,
    storage: &AuthenticationStorage,
) -> Result<Url, anyhow::Error> {
    let expiration = Utc::now() + Duration::seconds(expiration_secs);
    let expiration_str = expiration.to_rfc3339();

    let client = Client::builder()
        .redirect(reqwest::RedirectPolicy::none())
        .build()?;

    let auth = storage.get_aws_credentials()?;
    let access_key = auth.access_key;
    let secret_key = auth.secret_key;

    let mut headers = HeaderMap::new();
    headers.insert("Content-Type", HeaderValue::from_static("application/octet-stream"));

    let url = format!(
        "https://{}.s3.amazonaws.com/{}",
        bucket, key
    );

    let url = Url::parse(&url)?;

    let mut params = HashMap::new();
    params.insert("AWSAccessKeyId", access_key);
    params.insert("Expires", expiration_str);
    params.insert("SignatureMethod", "HmacSHA256");
    params.insert("SignatureVersion", "2");

    let canonical_request = format!(
        "GET\n{}\n{}\n{}\n",
        url.path(),
        headers
            .iter()
            .map(|(k, v)| format!("{}:{}", k.as_str(), v.to_str()?))
            .collect::<Vec<String>>()
            .join("\n"),
        params.iter()
            .map(|(k, v)| format!("{}={}", k, v))
            .collect::<Vec<String>>()
            .join("\n")
    );

    let signing_key = hmac_sha256(secret_key, "AWS4");
    let signing_key = hmac_sha256(signing_key, &format!("{}{}", bucket, "."));
    let signing_key = hmac_sha256(signing_key, &format!("{}{}", Utc::now().format("%Y%m%d"), "."));
    let signing_key = hmac_sha256(signing_key, "s3");

    let canonical_request_hash = sha256(canonical_request.as_bytes());
    let string_to_sign = format!("AWS4-HMAC-SHA256\n{}\n{}\n", expiration_str, canonical_request_hash);

    let signature = hmac_sha256(signing_key, string_to_sign.as_bytes());

    params.insert("Signature", format!("{}={}", "Signature", signature));

    let query = params.iter()
        .map(|(k, v)| format!("{}={}", k, v))
        .collect::<Vec<String>>()
        .join("&");

    let url = format!("{}?{}", url, query);

    Ok(Url::parse(&url)?)
}

fn hmac_sha256(key: &[u8], data: &[u8]) -> Vec<u8> {
    use hmac::{Hmac, Mac};
    use sha2::Sha256;

    let mut hmac = Hmac::<Sha256>::new_from_slice(key).expect("HMAC can take key of any size");
    hmac.update(data);
    let result = hmac.finalize();
    let result = result.into_bytes();
    result
}

fn sha256(data: &[u8]) -> Vec<u8> {
    use sha2::Sha256;
    let mut hasher = Sha256::new();
    hasher.update(data);
    let result = hasher.finalize();
    result.to_vec()
}

use serde_json::Serializer;
use sha2::{Digest, Sha256};
use base64::{encode_config, URL_SAFE_NO_PAD};

fn compute_thumbprint(key: &Key) -> Result<String, serde_json::Error> {
    let mut serializer = Serializer::new(Vec::new());
    key.serialize(&mut serializer)?;
    let json_bytes = serializer.into_inner();
    let mut hasher = Sha256::new();
    hasher.update(&json_bytes);
    let result = hasher.finalize();
    let thumbprint = encode_config(&result, URL_SAFE_NO_PAD);
    Ok(thumbprint)
}

