fn format_log(record: &LogRecord, cfg: &LoggingConfig) -> Option<String> {
    if !cfg.module_filters.contains(&record.module) {
        return None;
    }

    let mut result = String::new();
    let mut body = record.body.clone();

    for filter in &cfg.body_filters {
        if let Some((key, value)) = filter {
            if let Some(pos) = body.find(key) {
                if pos + key.len() < body.len() && body[pos + key.len()] == ':' {
                    let mut new_body = String::with_capacity(body.len() - key.len());
                    new_body.push_str(&body[..pos]);
                    new_body.push_str(value);
                    new_body.push_str(&body[pos + key.len() + 1..]);
                    body = new_body;
                }
            }
        }
    }

    writeln!(result, "{}", body).ok()?;
    Some(result)
}

use crate::error::ResultExt;
use gluesql_core::error::Error;
use mongodb::bson::{Document, doc};

fn find_collections_with_index_pattern(
    &self,
    index_key: &str,
    is_unique: bool,
) -> Result<Vec<String>, gluesql_core::error::Error> {
    let mut result = Vec::new();

    // Query the database for collections with the specified index pattern
    let collections = self.list_collections()?;
    for collection in collections {
        let collection_name = collection.name;
        let index_info = self.get_index_information(&collection_name)?;

        for index in index_info {
            if index.key == doc! { index_key: 1 } && index.unique == is_unique {
                result.push(collection_name.clone());
                break;
            }
        }
    }

    Ok(result)
}

fn list_collections(&self) -> Result<Vec<Document>, Error> {
    let collection_names = self.database.list_collection_names()?;
    let mut collections = Vec::new();

    for name in collection_names {
        let collection = self.database.collection::<Document>(name.as_str());
        let metadata = collection.metadata()?;
        collections.push(Document::from(metadata));
    }

    Ok(collections)
}

fn get_index_information(&self, collection_name: &str) -> Result<Vec<Document>, Error> {
    let collection = self.database.collection::<Document>(collection_name);
    let index_info = collection.index_information()?;
    Ok(index_info.values().cloned().collect())
}

fn generate_detailed_report(tests: &[TestResult]) -> String {
