fn validate_wallet_config(
    config: &WalletConfig,
    expected_network: Network,
) -> Result<(), String> {
    if config.network != expected_network {
        return Err(format!(
            "Wallet is configured for network: {:?}, but expected: {:?}",
            config.network, expected_network
        ));
    }

    if config.fee_consensus.min_fee < Amount::zero() {
        return Err("Minimum fee cannot be negative".to_string());
    }

    if config.fee_consensus.max_fee < config.fee_consensus.min_fee {
        return Err("Maximum fee cannot be less than minimum fee".to_string());
    }

    Ok(())
}

use jrsonnet_parser::{Expr, ObjBody, Member, FieldMember, IStr};

fn extract_obj_keys(expr: &Expr) -> Vec<IStr> {
    match expr {
        Expr::Obj(ObjBody::Fields(fields)) => {
            fields.iter()
                .filter_map(|member| match member {
                    Member::Field(FieldMember { name, .. }) => Some(name.clone()),
                    _ => None,
                })
                .collect()
        }
        Expr::Obj(ObjBody::Extends(extends)) => {
            // For extends, we need to collect keys from the extended object
            // This is a simplified version assuming the extended expression is an object
            if let Expr::Obj(ObjBody::Fields(fields)) = extends {
                fields.iter()
                    .filter_map(|member| match member {
                        Member::Field(FieldMember { name, .. }) => Some(name.clone()),
                        _ => None,
                    })
                    .collect()
            } else {
                Vec::new()
            }
        }
        _ => Vec::new(),
    }
}

fn list_keys_paginated(
    &self,
    context: Option<Context>,
    bucket: String,
    page_size: usize,
    page_number: usize,
) -> anyhow::Result<Result<Vec<String>>> {
    let store = self.get_store()?;
    let mut keys = Vec::new();
    let mut offset = page_number * page_size;

    // Fetch keys in batches to simulate pagination
    let mut stream = store.iter().try_stream()?;
    while let Some(key) = stream.next().await {
        if offset > 0 {
            offset -= 1;
            continue;
        }
        if let Some(value) = key.value() {
            keys.push(value.to_string());
            if keys.len() >= page_size {
                break;
            }
        }
    }

    Ok(Ok(keys))
}

fn get_store(&self) -> anyhow::Result<Store> {
    let kv = self.client().kv();
    let store = kv.open(&self.bucket)?;
    Ok(store)
}

use solana_zk_token_sdk::encryption::pedersen::Pedersen;
use solana_zk_token_sdk::instruction::BatchedRangeProofU64Data;
use std::convert::TryInto;

fn create_batched_range_proof_u64(
    amounts: &[u64],
) -> Result<BatchedRangeProofU64Data, Box<dyn std::error::Error>> {
    if amounts.is_empty() {
        return Err("Amounts cannot be empty".into());
    }

    let mut commitments = Vec::new();
    let mut openings = Vec::new();

    for &amount in amounts {
        let commitment = Pedersen::commit(amount).map_err(|e| e.to_string())?;
        let opening = Pedersen::open(amount).map_err(|e| e.to_string())?;
        commitments.push(commitment);
        openings.push(opening);
    }

    let batched_proof = BatchedRangeProofU64Data::new(commitments, openings);
    Ok(batched_proof)
}

fn list_filtered_packages(
    args: &Args,
    config: &VendorFilter,
    platform: Option<&str>,
) -> anyhow::Result<Vec<String>> {
    let all_packages = get_unfiltered_packages(args, config)?;
    let mut filtered_packages = HashMap::new();
    add_packages_for_platform(args, config, &all_packages, &mut filtered_packages, platform)?;

    let mut result = Vec::new();
    for (_, package) in &filtered_packages {
        if let Some(dep_kinds) = config.dep_kinds.as_ref() {
            if filter_dep_kinds(package, dep_kinds, platform) {
                result.push(package.name.clone());
            }
        } else {
            result.push(package.name.clone());
        }
    }
    Ok(result)
}

use rs_merkle::{MerkleTree, Hasher, algorithms::Sha256};
use crate::tests::hasher::SortingSha256Hasher;

pub fn generate_merkle_proof(member: &str, tree: &MerkleTree<SortingSha256Hasher>) -> Vec<String> {
    let leaf_hash = Sha256::hash(member.as_bytes());
    let leaves = tree.leaves();
    let mut index_opt = None;
    for (i, leaf) in leaves.iter().enumerate() {
        if leaf == &leaf_hash {
            index_opt = Some(i);
            break;
        }
    }
    let index = match index_opt {
        Some(i) => i,
        None => return vec![],
    };
    let proof = tree.proof(&[index]);
    proof.proof_hashes_hex()
}

use std::collections::BTreeMap;
use std::sync::Arc;
use std::thread;
use std::time::Duration;

use fedimint_api_client::api::DynGlobalApi;
use fedimint_core::module::ModuleInstanceId;
use fedim_core::peer_id::PeerId;
use fedimint_core::api::{ApiRequestErased, PeerResult};
use fedimint_core::util::backoff_util;
use fedimint_core::util::retry;
use serde_json::Value;
use anyhow;

fn fetch_module_statuses(
    api: &DynGlobalApi,
    module_id: ModuleInstanceId,
) -> anyhow::Result<BTreeMap<PeerId, Value>> {
    let peers = api.list_peers()?;
    let mut results = BTreeMap::new();
    let mut handles = vec![];

    for peer_id in peers {
        let api_clone = api.clone();
        let module_id_clone = module_id;
        let handle = thread::spawn(move || {
            let request = ApiRequestErased::new(
                "GET",
                format!("/modules/{}/status", module_id_clone),
            );
            let result = retry(
                || {
                    backoff_util::retry_with_backoff(3, || {
                        api_clone.send_request(peer_id, request.clone())
                    })
                },
                |e| e.is_timeout() || e.is_network() || e.is_connection() || e.is_unknown(),
            );
            match result {
                Ok(PeerResult::Success(value)) => Ok((peer_id, value)),
                Ok(PeerResult::Failure(err)) => {
                    tracing::warn!("Failed to get module status from peer {}: {}", peer_id, err);
                    Err(anyhow::anyhow!("Peer request failed"))
                }
                Err(e) => {
                    tracing::warn!("Error during retry for peer {}: {}", peer_id, e);
                    Err(e)
                }
            }
        });
        handles.push(handle);
    }

    for handle in handles {
        match handle.join() {
            Ok((peer_id, value)) => {
                results.insert(peer_id, value);
            }
            Err(e) => {
                tracing::warn!("Thread error: {}", e);
            }
        }
    }

    Ok(results)
}

use crate::Bmp;
use crate::BmpError;

fn from_ascii_art(ascii_art: &str) -> Result<Bmp, BmpError> {
    let lines: Vec<&str> = ascii_art.lines().collect();
    if lines.is_empty() {
        return Err(BmpError::EmptyInput);
    }

    let width = lines[0].len();
    let height = lines.len();

    if height == 0 || width == 0 {
        return Err(BmpError::EmptyInput);
    }

    let mut pixels = Vec::with_capacity(width * height);
    for line in lines {
        if line.len() != width {
            return Err(BmpError::InvalidDimensions);
        }
        for c in line.chars() {
            match c {
                '#' => pixels.push(0xFF_FF_FF), // White pixel
                '.' => pixels.push(0x00_00_00), // Black pixel
                _ => return Err(BmpError::InvalidCharacter),
            }
        }
    }

    let header = create_bmp_header(width as u32, height as u32, pixels.len() as u32);
    let data = create_bmp_data(pixels);

    Ok(Bmp { header, data })
}

fn create_bmp_header(width: u32, height: u32, size: u32) -> Vec<u8> {
    let mut header = vec![0; 54];
    header[0..4].copy_from_slice(b"BM");
    header[2] = 0x38; // 56 bytes for the header
    header[10] = (size as u8) & 0xFF;
    header[11] = ((size as u16) >> 8) as u8;
    header[12] = ((size as u32) >> 16) as u8;
    header[13] = ((size as u32) >> 24) as u8;
    header[18] = (width as u8) & 0xFF;
    header[19] = ((width as u16) >> 8) as u8;
    header[22] = (height as u8) & 0xFF;
    header[23] = ((height as u16) >> 8) as u8;
    header[28] = 0x28; // Start of image header
    header[34] = (width as u8) & 0xFF;
    header[35] = ((width as u16) >> 8) as u8;
    header[38] = (height as u8) & 0xFF;
    header[39] = ((height as u16) >> 8) as u8;
    header[40] = 0x01; // 1 bit per pixel
    header[44] = 0x00;
    header[46] = 0x00;
    header[48] = 0x00;
    header[50] = 0x00;
    header[52] = 0x00;
    header[54] = 0x00;
    header[56] = 0x00;
    header[57] = 0x00;
    header[58] = 0x00;
    header[59] = 0x00;
    header[60] = 0x00;
    header[61] = 0x00;
    header[62] = 0x00;
    header[63] = 0x00;
    header[64] = 0x00;
    header[65] = 0x00;
    header[66] = 0x00;
    header[67] = 0x00;
    header[68] = 0x00;
    header[69] = 0x00;
    header[70] = 0x00;
    header[71] = 0x00;
    header[72] = 0x00;
    header[73] = 0x00;
    header[74] = 0x00;
    header[75] = 0x00;
    header[76] = 0x00;
    header[77] = 0x00;
    header[78] = 0x00;
    header[79] = 0x00;
    header[80] = 0

fn fetch_updated_since<Id, Data, CODEC>(
    c3p0: &crate::mysql::SqlxMySqlC3p0Json<Id, Data, CODEC>,
    tx: &mut crate::mysql::Db,
    since: i64,
) -> Result<Vec<c3p0_common::Model<Id, Data>>, c3p0_common::C3p0Error>
where
    Id: c3p0_common::IdType,
    Data: c3p_common::DataType,
    CODEC: c3p_common::JsonCodec<Data>,
{
    let base_query = c3p0.base_query();
    let query = format!("{} WHERE update_epoch_millis > {}", base_query, since);
    let rows = query!($query).fetch_all(tx.conn())?;
    let models: Vec<Model<Id, Data>> = rows
        .into_iter()
        .map(|row| {
            let id = row.id;
            let data = CODEC.decode(row.data);
            Model::new(id, data)
        })
        .collect();
    Ok(models)
}

use grok::Grok;
use grok::Error;

#[derive(Debug, PartialEq, Eq)]
pub struct ApacheLog {
    pub remote_ip: String,
    pub user_ident: String,
    pub auth_user: String,
    pub timestamp: String,
    pub request_method: String,
    pub request_url: String,
    pub http_version: String,
    pub status_code: u16,
    pub bytes_sent: u64,
    pub referer: String,
    pub user_agent: String,
}

fn parse_apache_log(line: &str) -> Result<ApacheLog, grok::Error> {
    let pattern = "%{IP:remote_ip} %{USER:user_ident} %{USER:auth_user} \\[%{HTTPDATE:timestamp}\\] \"(%{WORD:request_method} %{URIPATH:request_url} %{NUMBER:http_version})\" %{NUMBER:status_code} %{NUMBER:bytes_sent} \"%{DATA:referer}\" \"%{DATA:user_agent}\"";
    let grok = Grok::new(pattern).unwrap();
    let mut match_data = grok.parse(line)?;

    Ok(ApacheLog {
        remote_ip: match_data.get("remote_ip").unwrap().to_string(),
        user_ident: match_data.get("user_ident").unwrap().to_string(),
        auth_user: match_data.get("auth_user").unwrap().to_string(),
        timestamp: match_data.get("timestamp").unwrap().to_string(),
        request_method: match_data.get("request_method").unwrap().to_string(),
        request_url: match_data.get("request_url").unwrap().to_string(),
        http_version: match_data.get("http_version").unwrap().to_string(),
        status_code: match_data.get("status_code").unwrap().parse::<u16>().unwrap(),
        bytes_sent: match_data.get("bytes_sent").unwrap().parse::<u64>().unwrap(),
        referer: match_data.get("referer").unwrap().to_string(),
        user_agent: match_data.get("user_agent").unwrap().to_string(),
    })
}

fn rpc(&self, method: &str, params: &serde_json::Value) -> anyhow::Result<serde_json::Value> {
    let versioned_method = if let Some(dot_index) = method.find('.') {
        let version = &method[dot_index + 1..];
        let base = &method[..dot_index];
        if version.parse::<u32>().is_ok() {
            format!("{}.{version}.{}", base, self.default_version)
        } else {
            format!("{}.{self.default_version}", method)
        }
    } else {
        format!("{}.{}", method, self.default_version)
    };

    self.inner.rpc(&versioned_method, params)
}

