fn repeat_command(mut cmd: ConsoleCommand<RepeatCommand>) {
    let RepeatCommand {
        text,
        count: count_opt,
        delay_ms: delay_opt,
    } = cmd.parse();
    let count = count_opt.unwrap_or(1);
    let delay = delay_opt.unwrap_or(0);

    for _ in 0..count {
        println!("{}", text);
        if delay > 0 {
            std::thread::sleep(std::time::Duration::from_millis(delay));
        }
    }
}

fn decompress_stream<R: std::io::Read>(mut src: R) -> std::io::Result<Vec<u8>> {
    let mut context: *mut LZ4FDecompressionContext = ptr::null_mut();
    let mut output_buffer = Vec::new();
    let mut output_size = 0;
    let mut input_buffer = Vec::new();
    let mut input_size = 0;

    // Initialize decompression context
    let result = unsafe { LZ4F_createDecompressionContext(&mut context, LZ4F_VERSION) };
    check_error(result)?;

    // Read the entire input into a buffer
    let mut buffer = Vec::new();
    let mut buffer_len = 0;
    loop {
        let mut chunk = Vec::with_capacity(1024 * 1024);
        let n = src.read(&mut chunk)?;
        if n == 0 {
            break;
        }
        buffer.extend(chunk);
        buffer_len += n;
    }

    // Decompress the entire buffer
    let mut output_capacity = buffer_len * 5; // Heuristic for output size
    output_buffer.resize(output_capacity, 0);
    let result = unsafe { LZ4F_decompress(context, buffer.as_ptr() as _, buffer_len as size_t, output_buffer.as_mut_ptr() as _, &mut output_capacity as *mut size_t) };
    check_error(result)?;

    // Truncate the output buffer to the actual decompressed size
    output_buffer.truncate(output_capacity as usize);

    // Free the decompression context
    unsafe { LZ4F_freeDecompressionContext(context) };

    Ok(output_buffer)
}

use crate::utils::Validator;
use crate::row::data_type::BsonType;
use crate::description::ColumnDescription;
use gluesql_core::data::Schema;
use gluesql_core::error::Error;
use bson::doc;
use serde_json;

fn generate_mongo_schema(schema: &Schema) -> Result<String, Error> {
    let mut validator = doc! {};
    let mut required = vec![];
    let mut indexes = vec![];

    for column in &schema.columns {
        let bson_type = match column.data_type() {
            "int" => BsonType::Integer,
            "long" => BsonType::Integer,
            "float" => BsonType::Double,
            "double" => BsonType::Double,
            "string" => BsonType::String,
            "boolean" => BsonType::Boolean,
            "timestamp" => BsonType::DateTime,
            "date" => BsonType::DateTime,
            "binary" => BsonType::Binary,
            "uuid" => BsonType::Uuid,
            "decimal" => BsonType::Decimal,
            "array" => BsonType::Array,
            "map" => BsonType::Document,
            "object" => BsonType::Document,
            _ => return Err(Error::UnsupportedDataType(format!("Unsupported data type: {}", column.data_type()))),
        };

        let field = doc! {
            column.name(): bson_type.to_bson()
        };

        validator[column.name()] = Some(field);

        if column.is_required() {
            required.push(column.name().to_string());
        }

        // Simple index creation for non-nullable fields
        if !column.is_nullable() && !required.contains(&column.name().to_string()) {
            indexes.push(doc! {
                column.name(): 1
            });
        }
    }

    let mut validator_doc = doc! {
        "$jsonSchema": validator
    };

    if !required.is_empty() {
        validator_doc["required"] = Some(doc! { required });
    }

    if !indexes.is_empty() {
        validator_doc["indexes"] = Some(doc! { "default": indexes });
    }

    Ok(serde_json::to_string(&validator_doc).unwrap())
}
